_SPELL_BUFF_MAP["gaseous-form-potion"] = {
    "key": "gaseous-form-potion",
    "name": "Gaseous Form",
    "icon": "💨",
    "duration_rounds": 600,  # up to 1 hour @ 6 s/round
    "duration_max": 600,
    "concentration": False,
    "effects": {
        "resistance_to": [
            "nonmagical-bludgeoning", "nonmagical-piercing",
            "nonmagical-slashing", "nonmagical-fire", "nonmagical-cold",
            "nonmagical-lightning", "nonmagical-thunder", "nonmagical-acid",
            "nonmagical-poison", "nonmagical-necrotic", "nonmagical-radiant",
            "nonmagical-psychic", "nonmagical-force",
        ],
        "fly_speed_ft": 10,  # hover
    },
    "desc": (
        "Gaseous form for up to 1 hour: resistance to nonmagical damage, "
        "advantage on STR/DEX/CON saves, 10-ft hover; can't attack, cast, "
        "or manipulate objects (GM-narrated). RAW DMG p.187."
    ),
}


# v2.49.51 — RAW (PHB p.290 condition definitions): these condition
# buff keys all imply the "incapacitated" state, which RAW (PHB p.203
# concentration rules) ends any concentration the affected creature
# is sustaining. Used by ``_install_buff`` to call
# ``_drop_caster_concentration`` on the TARGET when the buff lands.
# Charmed and Frightened are NOT in this set — those conditions
# constrain action choice but don't incapacitate.
_INCAPACITATING_BUFF_KEYS = frozenset({
    "paralyzed",      # Hold Person, Hold Monster
    "incapacitated",  # Hideous Laughter (and the generic state)
    "stunned",        # Stunning Strike, Power Word Stun
    "petrified",      # Flesh to Stone
    "unconscious",    # Sleep, knockout
    "asleep",         # alt key surface for Sleep
})


async def _install_buff_on_combatant_id(
    campaign_id: int, combatant_id: str, buff: dict,
) -> bool:
    """v2.32.0 Phase T.3c — NPC-friendly buff installer. Mutates the
    target combatant's ``buffs`` list in the hub state and broadcasts
    ``battle_update`` (NPCs don't have a Character row, so the
    ``buff_update`` broadcast that ``_install_buff`` uses for PCs
    isn't routable here). Refresh semantics: re-casting the same
    condition replaces the existing entry on the same combatant.
    """
    if not isinstance(buff, dict) or not buff.get("key"):
        return False
    state = hub.get_battle(campaign_id)
    if not state:
        return False
    target = None
    for c in state.get("combatants") or []:
        if c.get("id") == combatant_id:
            target = c
            break
    if target is None:
        return False
    # v2.99.128 — condition immunity gate (PC + NPC). RAW: targets
    # immune to a condition don't get the install on a failed save.
    # The combatant may be a PC (char_id) or an NPC (template_id);
    # we route to the right helper based on which is present.
    try:
        from app.database import SessionLocal as _CISessionLocal
        with _CISessionLocal() as _ci_db:
            buff_key_str = str(buff.get("key") or "")
            if target.get("char_id"):
                # PC target — read the character's sheet for
                # condition_immunities.
                _ci_char_row = _ci_db.query(Character).filter(
                    Character.id == int(target["char_id"]),
                ).first()
                if _ci_char_row and _target_condition_immune(
                    _ci_char_row.sheet or {}, buff_key_str,
                ):
                    return False
            else:
                # NPC target — read the template's sheet.
                if _target_condition_immune_npc(
                    target, buff_key_str, _ci_db,
                ):
                    return False
    except Exception:
        pass
    buffs = target.get("buffs")
    if not isinstance(buffs, list):
        buffs = []
        target["buffs"] = buffs
    key = str(buff["key"])
    new_list = [b for b in buffs if (b or {}).get("key") != key]
    new_list.append(dict(buff))
    target["buffs"] = new_list
    hub.set_battle(campaign_id, state)
    # v2.49.43 — server-initiated state change, so force_gm_sync (see
    # v2.49.40 for the broader audit). Without it the GM ignores the
    # broadcast and a freshly-installed NPC buff (e.g. Paralyzed on a
    # bandit from Hold Person) only shows up after the next push.
    await hub.broadcast(campaign_id, {
        "type": "battle_update",
        "data": state,
        "force_gm_sync": True,
    })
    return True


def _concentration_buff_for(
    campaign_id: int, character_id: int,
) -> dict | None:
    """Return the (single) concentration buff active on the combatant,
    or None. There can be at most one per combatant — ``_install_buff``
    enforces the invariant. Used by the concentration-save hook to
    decide whether a damage event needs to trigger a save.
    """
    for b in _get_buffs(campaign_id, character_id):
        if (b or {}).get("concentration"):
            return b
    return None


async def _maybe_concentration_save(
    campaign_id: int, char: Character, damage_amount: int,
    db: Session | None = None,
) -> dict | None:
    """If the character is concentrating on a buff and just took
    ``damage_amount`` damage, roll a CON save (DC = max(10, damage //
    2)) and act on the result. Returns ``None`` if no concentration
    buff is active or no damage was taken; otherwise returns
    ``{rolled, total, dc, passed, dropped_key}`` and broadcasts a
    ``concentration_save`` event. On fail, the concentration buff is
    removed via ``_remove_buff`` (which fires its own ``buff_update``).

    v2.19.1: auto-roll keeps the player UX consistent with the rest of
    the demo's "click → roll → result" loop. Players who prefer to
    hand-roll their concentration save can reinstall the buff after a
    miss; the GM can also rebroadcast via /use_rage / /cast_hunters_mark
    / /cast_hex.
    """
    if damage_amount <= 0:
        return None
    buff = _concentration_buff_for(campaign_id, char.id)
    if buff is None:
        return None

    # DC = max(10, damage // 2). Floor division per RAW.
    dc = max(10, damage_amount // 2)
    sheet = dict(char.sheet or {})
    abilities = dict(sheet.get("abilities") or {})
    con_score = int(abilities.get("CON") or 10)
    con_mod = (con_score - 10) // 2
    # CON save proficiency? RAW: Barbarian + Fighter + Sorcerer have
    # CON save proficiency; nothing else on the demo's PC roster. War
    # Caster (v2.83.0) and Resilient (CON) feats also grant it — War
    # Caster is now detected; Resilient is still filed.
    saves = dict(sheet.get("saving_throws") or {})
    pb = int(sheet.get("proficiency_bonus") or 0)
    war_caster_active = _pc_has_war_caster_feat(char)
    prof_bonus = pb if (saves.get("CON") or war_caster_active) else 0
    bonus = con_mod + prof_bonus

    # v2.49.48 — RAW: a creature loses concentration AUTOMATICALLY
    # if its hit points drop to 0 (PHB p.203), independent of the
    # CON save. Pre-fix the server still rolled the save and could
    # leave a dying / dead PC concentrating on Hex / Hunter's Mark
    # / Hold Person if they happened to pass — visible as the chip
    # staying on the unconscious PC's row, the marked target still
    # taking +1d6 necrotic, etc. The CON save still happens for
    # damage that doesn't drop to 0 (the standard branch). When at
    # 0 HP we still roll for telemetry but force passed=False so
    # the existing _remove_buff path runs.
    hp_current_after = int((sheet.get("hp") or {}).get("current") or 0)
    forced_drop_on_zero_hp = hp_current_after <= 0

    # v2.83.0 — War Caster grants advantage on concentration saves
    # from damage. Expression becomes 2d20kh1 (keep-highest) when WC
    # is active.
    d20_expr = "2d20kh1" if war_caster_active else "1d20"
    try:
        result = dice_mod.roll(f"{d20_expr}+{bonus}" if bonus >= 0 else f"{d20_expr}{bonus}")
        total = result.total
        raw = total - bonus  # the d20 face value
    except dice_mod.DiceParseError:
        raw = 10
        total = 10 + bonus

    passed = (total >= dc) and not forced_drop_on_zero_hp
    dropped_key = None
    paired_pre_drop: list[dict] = []
    if not passed:
        dropped_key = buff.get("key")
        if dropped_key:
            # v2.39.0: capture the paired buffs about to drop BEFORE
            # ``_remove_buff`` triggers the cleanup helper. We need
            # the list of (combatant_name, buff_name) tuples to
            # build the GM-only roll-log entry below — the helper
            # mutates state, so reading after the call would return
            # an empty list.
            state_snapshot = hub.get_battle(campaign_id)
            if state_snapshot:
                for c in state_snapshot.get("combatants") or []:
                    for b in c.get("buffs") or []:
                        b = b or {}
                        if (
                            b.get("source_char_id") == char.id
                            and bool(b.get("concentration"))
                            and b.get("key") != dropped_key
                        ):
                            paired_pre_drop.append({
                                "combatant_name": c.get("name") or "Unknown",
                                "buff_name": b.get("name") or b.get("key") or "Effect",
                            })
            await _remove_buff(campaign_id, char.id, dropped_key)
            # v2.19.2 Phase C.3: sync the sheet mirror so the Active
            # Effects panel updates when concentration breaks mid-fight.
            if db is not None:
                _mirror_buffs_to_sheet(
                    db, char.id, _get_buffs(campaign_id, char.id),
                )

    await hub.broadcast(campaign_id, {
        "type": "concentration_save",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "buff_key": buff.get("key"),
            "buff_name": buff.get("name"),
            "damage_amount": damage_amount,
            "dc": dc,
            "rolled": raw,
            "bonus": bonus,
            "total": total,
            "passed": passed,
            # v2.49.48 — distinguishes the RAW "drops to 0 HP" forced
            # drop from a regular failed save, so the client roll-log
            # can render "💀 Concentration broken (0 HP)" instead of
            # "❌ Concentration save failed". Always present; True
            # only when the drop was forced regardless of roll outcome.
            "forced_drop_on_zero_hp": forced_drop_on_zero_hp,
            "dropped_key": dropped_key,
            # v2.83.0 — surface War Caster's contribution so the
            # client can render "🛡 War Caster: advantage" on the
            # roll-log card. The d20 expression was 2d20kh1 when
            # set, the CON-save proficiency may have come from the
            # feat rather than the class. Both are useful audit
            # signals for the GM.
            "war_caster_advantage": war_caster_active,
        },
    })
    # v2.83.0 — broadcast a feature_used trail when War Caster's
    # advantage actually fired (the d20 expression was 2d20kh1). Same
    # pattern as v2.53.0 Aura of Protection and v2.52.0 Danger Sense.
    if war_caster_active:
        try:
            await hub.broadcast(campaign_id, {
                "type": "feature_used",
                "data": {
                    "character_id": char.id,
                    "character_name": char.name,
                    "user_color": char.color,
                    "feature_name": "🛡 War Caster (advantage)",
                    "feature_desc": (
                        f"Advantage on concentration save (2d20kh1) "
                        f"after taking {damage_amount} damage."
                    ),
                    "source": "war-caster-concentration",
                    "reaction_kind": "passive",
                    "dc": dc,
                    "rolled": raw,
                    "total": total,
                    "passed": passed,
                },
            })
        except Exception:
            pass

    # v2.39.0: GM-only narrative roll-log entry summarising the
    # concentration loss + the paired effects that dropped. Players
    # see their own buff vanish via the buff_update broadcast and
    # the concentration_save toast; the GM gets an extra log entry
    # naming exactly what was let go (Hold Person on Bandit Alpha,
    # etc.) so cleanup is auditable from one place.
    if not passed:
        buff_name = buff.get("name") or buff.get("key") or "concentration"
        if paired_pre_drop:
            paired_summary = " · ".join(
                f"{p['buff_name']} → {p['combatant_name']}"
                for p in paired_pre_drop
            )
            paired_note = f" — dropped: {paired_summary}"
        else:
            paired_note = ""
        # v2.49.50 — distinguish 💀 forced 0-HP drop from 💔 failed
        # CON save. The save was still ROLLED for telemetry parity
        # (existing tests assert on rolled/total/bonus) but a 0-HP
        # drop is conceptually different — the rule ended the spell,
        # not the save. The breakdown shows what the save would have
        # been so the GM can see whether the roll itself was a pass.
        if forced_drop_on_zero_hp:
            emoji = "💀"
            would_have_been = (
                f"1d20[{raw}]{'+' if bonus >= 0 else ''}{bonus} = {total} vs DC {dc}"
                if bonus != 0 else
                f"1d20[{raw}] = {total} vs DC {dc}"
            )
            gm_log_breakdown = (
                f"Concentration ends — incapacitated (0 HP) — "
                f"save would have been {would_have_been}"
            )
        else:
            emoji = "💔"
            gm_log_breakdown = (
                f"1d20[{raw}]{'+' if bonus >= 0 else ''}{bonus} = {total} vs DC {dc} — ✗ Failed"
                if bonus != 0 else
                f"1d20[{raw}] = {total} vs DC {dc} — ✗ Failed"
            )
        await hub.broadcast(campaign_id, {
            "type": "roll",
            "data": {
                "expression": "1d20",
                "total": total,
                "breakdown": gm_log_breakdown,
                "note": (
                    f"{emoji} {char.name} lost concentration on {buff_name}"
                    f"{paired_note}"
                ),
                "visibility": Visibility.GM_ONLY.value,
                "user_id": None,
                "user_name": "GM log",
                "char_name": char.name,
            },
        })

    return {
        "rolled": raw,
        "total": total,
        "dc": dc,
        "passed": passed,
        "dropped_key": dropped_key,
    }


async def _drop_paired_concentration_buffs(
    campaign_id: int, caster_char_id: int, except_key: "str | None" = None,
) -> list[dict]:
    """v2.38.0 Phase T.3e: when a caster's concentration drops (broke
    on damage, was replaced by a new concentration cast, or was ended
    manually), scan every combatant in init and remove buffs they
    granted under that concentration. T.3c/T.3d install Paralyzed /
    Charmed / Frightened conditions with ``source_char_id: <caster>``
    + ``concentration: True``; this helper drops them in lock-step
    with the caster's concentration buff.

    Returns the list of removed buff dicts (each shape preserved,
    plus ``_dropped_from_combatant_id`` field) so the caller can log.
    Broadcasts a single ``battle_update`` covering all removals.
    """
    state = hub.get_battle(campaign_id)
    if not state:
        return []
    removed: list[dict] = []
    dirty = False
    for c in state.get("combatants") or []:
        buffs = c.get("buffs") or []
        kept = []
        for b in buffs:
            b = b or {}
            # v2.99.1 — match on source_char_id AND
            # (concentration: True OR _dependent_on_caster_concentration).
            # Pre-v2.99.1 the check required ``concentration: True``,
            # which broke the cascade for v2.97.67-fixed target-side
            # condition buffs (Paralyzed / Frightened / Charmed etc.)
            # that now carry ``concentration: False`` so the damage-
            # triggered Con-save check on the target doesn't drop the
            # buff prematurely. v2.99.1 stamps the new
            # ``_dependent_on_caster_concentration: True`` marker on
            # the target buff at install time so the helper still
            # cascade-drops it when the caster's concentration ends.
            # v2.113.2 — never drop the buff that TRIGGERED this cascade.
            # When _install_buff swaps in a new concentration anchor it
            # calls this with except_key=<new anchor key>; without the
            # guard the cascade would remove the caster's own
            # just-installed anchor too (it carries source_char_id ==
            # caster + concentration), leaving the caster showing as not
            # concentrating right after a swap.
            if (
                b.get("source_char_id") == caster_char_id
                and (except_key is None or b.get("key") != except_key)
                and (
                    bool(b.get("concentration"))
                    or bool(b.get("_dependent_on_caster_concentration"))
                )
            ):
                rec = dict(b)
                rec["_dropped_from_combatant_id"] = c.get("id")
                removed.append(rec)
                continue
            kept.append(b)
        if len(kept) != len(buffs):
            c["buffs"] = kept
            dirty = True
    if dirty:
        hub.set_battle(campaign_id, state)
        # v2.49.43 — server-initiated paired-buff cleanup, force_gm_sync
        # (see v2.49.40 audit). Without it the GM's view of "concentration
        # ended → all paired buffs dropped" only updates on the next push.
        await hub.broadcast(campaign_id, {
            "type": "battle_update",
            "data": state,
            "force_gm_sync": True,
        })
    # v2.49.0 — also clear any persistent AoE markers this caster
    # placed (Spirit Guardians, Hypnotic Pattern, etc.). The marker
    # is keyed to the caster's concentration; once concentration
    # breaks, the marker should vanish from the map.
    await _clear_caster_concentration_aoes(campaign_id, caster_char_id)
    # v2.99.172 — Polymorph token-disguise revert. Closes a
    # v2.99.168 filed item. When the dropped buffs include a
    # `polymorph-active` marker, the corresponding target's
    # transform was tied to this caster's concentration. Revert
    # the target's sheet + token disguise via
    # `_revert_polymorph_internal`. Each target gets its own
    # revert call (rare to have multiple polymorph targets, but
    # safe for upcast Polymorph variants).
    for rec in removed:
        if (rec.get("key") or "").strip().lower() != "polymorph-active":
            continue
        tid = rec.get("_dropped_from_combatant_id") or ""
        if not tid:
            continue
        target_char_id = None
        for c in (state.get("combatants") or []):
            if c.get("id") == tid:
                target_char_id = c.get("char_id")
                break
        if target_char_id:
            await _revert_polymorph_internal(
                campaign_id, int(target_char_id),
            )

    # v2.113.0 — concentration-bound summons (Spiritual Weapon). When
    # the caster's concentration drops, dismiss any summon they stood
    # up under it (token + combatant + broadcasts), mirroring the AoE-
    # marker + polymorph cleanup above. Re-read the (post-buff-cleanup)
    # state and use an own session since this helper isn't passed one.
    _bound = [
        c for c in ((hub.get_battle(campaign_id) or {}).get("combatants") or [])
        if c.get("is_summon") and c.get("concentration_bound")
        and c.get("summoned_by") == caster_char_id
    ]
    if _bound:
        try:
            from app.database import SessionLocal as _SumSessionLocal
            with _SumSessionLocal() as _sum_db:
                for _bc in _bound:
                    try:
                        await _dismiss_companion(
                            _sum_db, campaign_id, _bc.get("id"),
                        )
                    except Exception:  # noqa: BLE001
                        pass
        except Exception:  # noqa: BLE001
            pass
    return removed


async def _revert_polymorph_internal(
    campaign_id: int, target_char_id: int,
) -> bool:
    """v2.99.172 — Internal Polymorph revert helper. Restores the
    target's sheet (active_form → prior_form), clears the polymorph
    metadata, and reverts the token disguise via
    `_revert_token_disguise`. Broadcasts `transform_update` +
    `token_update` per affected token.

    Called from `_drop_paired_concentration_buffs` when a caster's
    concentration drops and the cleanup removed a `polymorph-active`
    marker buff from a target combatant. Closes the v2.99.168 filed
    item "Polymorph concentration coupling".

    Defensive: opens its own DB session via SessionLocal (since the
    paired-cleanup helper isn't passed a Session). Failures are
    logged-not-raised so a downstream broadcast issue doesn't
    block the rest of the cascade.
    """
    try:
        from app.database import SessionLocal as _PSessionLocal
        with _PSessionLocal() as _p_db:
            target = _p_db.query(Character).filter(
                Character.id == int(target_char_id),
            ).first()
            if not target:
                return False
            sheet = dict(target.sheet or {})
            prior = sheet.get("prior_form")
            if not isinstance(prior, dict):
                # No prior form snapshot — nothing to restore. Still
                # clear active_form so the UI shows the character
                # back to "normal" form (best-effort recovery).
                sheet["active_form"] = None
                from sqlalchemy.orm.attributes import flag_modified
                target.sheet = sheet
                flag_modified(target, "sheet")
                _p_db.commit()
            else:
                for key in (
                    "hp", "ac", "speed", "abilities", "skills",
                    "saving_throws", "attacks", "race",
                    "initiative_bonus", "proficiency_bonus",
                    "damage_resistances", "damage_immunities",
                    "damage_vulnerabilities", "condition_immunities",
                ):
                    if key in prior and prior[key] is not None:
                        sheet[key] = prior[key]
                sheet["active_form"] = None
                sheet["prior_form"] = None
                from sqlalchemy.orm.attributes import flag_modified
                target.sheet = sheet
                flag_modified(target, "sheet")
                _p_db.commit()
            # Revert the token disguise (no-op for tokens already in
            # native form).
            _reverted = _revert_token_disguise(_p_db, int(target_char_id))
            if _reverted > 0:
                _p_db.commit()
                for _tok in _p_db.query(Token).filter(
                    Token.character_id == int(target_char_id),
                ).all():
                    await hub.broadcast(campaign_id, {
                        "type": "token_update",
                        "data": {
                            "id": _tok.id,
                            "label": _tok.label,
                            "size": _tok.size,
                            "disguise": _tok.disguise,
                        },
                    })
            # Broadcast the transform_update so live clients refresh.
            await hub.broadcast(campaign_id, {
                "type": "transform_update",
                "data": {
                    "character_id": int(target_char_id),
                    "active_form": None,
                    "hp": sheet.get("hp"),
                    "ac": sheet.get("ac"),
                    "speed": sheet.get("speed"),
                    "source": "polymorph-concentration-drop",
                },
            })
        return True
    except Exception:
        # Swallow — don't break the surrounding paired cleanup.
        return False


async def _drop_paired_concentration_buffs_npc(
    campaign_id: int, source_combatant_id: str,
) -> list[dict]:
    """v2.97.80 — NPC equivalent of ``_drop_paired_concentration_buffs``.
    Mirror logic: when an NPC caster's concentration drops, walk every
    combatant and remove buffs sourced from this NPC. Target-side
    buffs installed by an NPC caster carry ``source_combatant_id:
    <caster_combatant_id>`` (set by the v2.97.80 install path); this
    helper matches on that field.

    Returns the list of removed buff dicts; broadcasts one
    ``battle_update`` covering all removals. AoE-marker cleanup is
    PC-only for now (NPCs don't place persistent AoEs).
    """
    state = hub.get_battle(campaign_id)
    if not state:
        return []
    removed: list[dict] = []
    dirty = False
    for c in state.get("combatants") or []:
        buffs = c.get("buffs") or []
        kept = []
        for b in buffs:
            b = b or {}
            # v2.99.1 — match on source_combatant_id AND no PC
            # source_char_id (NPC-sourced gate) AND
            # (concentration: True OR _dependent_on_caster_concentration).
            # Same v2.97.67 / v2.99.1 reasoning as the PC helper.
            if (
                b.get("source_combatant_id") == source_combatant_id
                and not b.get("source_char_id")
                and (
                    bool(b.get("concentration"))
                    or bool(b.get("_dependent_on_caster_concentration"))
                )
            ):
                rec = dict(b)
                rec["_dropped_from_combatant_id"] = c.get("id")
                removed.append(rec)
                continue
            kept.append(b)
        if len(kept) != len(buffs):
            c["buffs"] = kept
            dirty = True
    if dirty:
        hub.set_battle(campaign_id, state)
        await hub.broadcast(campaign_id, {
            "type": "battle_update",
            "data": state,
            "force_gm_sync": True,
        })
    # v2.99.179 — NPC mirror of the v2.99.172 Polymorph revert
    # cascade. When the NPC's dropped buffs include a polymorph-
    # active marker, look up the target's char_id and revert via
    # `_revert_polymorph_internal`. Closes the v2.99.172 filed
    # item "NPC-cast Polymorph mirror".
    for rec in removed:
        if (rec.get("key") or "").strip().lower() != "polymorph-active":
            continue
        tid = rec.get("_dropped_from_combatant_id") or ""
        if not tid:
            continue
        target_char_id = None
        for c in (state.get("combatants") or []):
            if c.get("id") == tid:
                target_char_id = c.get("char_id")
                break
        if target_char_id:
            await _revert_polymorph_internal(
                campaign_id, int(target_char_id),
            )
    return removed


def _npc_concentration_buff_for(
    campaign_id: int, combatant_id: str,
) -> dict | None:
    """v2.97.80 — NPC equivalent of ``_concentration_buff_for``. Returns
    the (single) concentration buff active on an NPC combatant, or
    None. NPCs don't have a Character row so we key on combatant id
    instead of char_id.
    """
    state = hub.get_battle(campaign_id)
    if not state:
        return None
    for c in state.get("combatants") or []:
        if c.get("id") == combatant_id:
            for b in (c.get("buffs") or []):
                if (b or {}).get("concentration"):
                    return b
            return None
    return None


async def _maybe_npc_concentration_save(
    campaign_id: int, target_combatant: dict, damage_amount: int,
    db: "Session | None" = None,
) -> dict | None:
    """v2.97.80 — NPC equivalent of ``_maybe_concentration_save``. When
    an NPC combatant carrying a concentration anchor takes damage,
    roll a CON save (DC = max(10, dmg // 2)). On fail, drop the
    anchor + every target-side buff sourced from this NPC (via
    ``_drop_paired_concentration_buffs_npc``).

    Returns ``{rolled, total, dc, passed, dropped_key}`` or None when
    no concentration anchor is on this NPC. Broadcasts a
    ``concentration_save`` event identical in shape to the PC
    version, with ``combatant_id`` instead of ``character_id``.
    """
    if damage_amount <= 0:
        return None
    cb_id = target_combatant.get("id")
    if not cb_id:
        return None
    buff = _npc_concentration_buff_for(campaign_id, cb_id)
    if buff is None:
        return None

    # CON modifier from the NPC's template sheet. The template's
    # ``abilities.CON`` (score, not modifier) drives the roll. NPCs
    # don't currently get proficient CON saves wired through the
    # template; filed as a follow-up.
    npc_mod = 0
    tmpl_id = target_combatant.get("token_template_id")
    if tmpl_id and db is not None:
        try:
            tmpl = db.query(TokenTemplate).filter(
                TokenTemplate.id == int(tmpl_id),
            ).first()
            if tmpl is not None:
                npc_sheet = _monster_template_to_sheet(tmpl, campaign_id)
                npc_mod, _ = _resolve_stat_modifier(
                    npc_sheet, "dnd5e", "con_save",
                )
        except Exception:
            npc_mod = 0

    dc = max(10, damage_amount // 2)
    hp_after = int(target_combatant.get("hp_current") or 0)
    forced_drop_on_zero_hp = hp_after <= 0

    try:
        result = dice_mod.roll(
            f"1d20+{npc_mod}" if npc_mod >= 0 else f"1d20{npc_mod}"
        )
        total = int(result.total)
        raw = total - npc_mod
    except dice_mod.DiceParseError:
        raw = 10
        total = 10 + npc_mod

    passed = (total >= dc) and not forced_drop_on_zero_hp
    dropped_key = None
    if not passed:
        dropped_key = buff.get("key")
        if dropped_key:
            # Drop the anchor on the NPC.
            state = hub.get_battle(campaign_id)
            if state:
                for c in state.get("combatants") or []:
                    if c.get("id") != cb_id:
                        continue
                    c["buffs"] = [
                        b for b in (c.get("buffs") or [])
                        if (b or {}).get("key") != dropped_key
                    ]
                    hub.set_battle(campaign_id, state)
                    await hub.broadcast(campaign_id, {
                        "type": "buff_update",
                        "data": {
                            "combatant_id": cb_id,
                            "buffs": c["buffs"],
                            "removed_key": dropped_key,
                        },
                    })
                    break
            # Drop paired target-side buffs sourced from this NPC.
            await _drop_paired_concentration_buffs_npc(campaign_id, cb_id)

    await hub.broadcast(campaign_id, {
        "type": "concentration_save",
        "data": {
            "combatant_id": cb_id,
            "character_name": target_combatant.get("name") or "Creature",
            "buff_key": buff.get("key"),
            "buff_name": buff.get("name"),
            "damage_amount": damage_amount,
            "dc": dc,
            "rolled": raw,
            "bonus": npc_mod,
            "total": total,
            "passed": passed,
            "forced_drop_on_zero_hp": forced_drop_on_zero_hp,
            "dropped_key": dropped_key,
            "war_caster_advantage": False,
        },
    })
    return {
        "rolled": raw,
        "total": total,
        "dc": dc,
        "passed": passed,
        "dropped_key": dropped_key,
    }


async def _remove_buff(
    campaign_id: int, character_id: int, key: str,
) -> bool:
    """Remove a single buff by key. Returns True if removed, False if
    nothing matched. Broadcasts ``buff_update`` with the new (possibly
    empty) buff list when a removal happened; no-op silently otherwise.

    v2.38.0 Phase T.3e: if the removed buff was a concentration buff,
    also scans all combatants for paired condition buffs (Hold
    Person's Paralyzed, Fear's Frightened, …) sourced by this
    character and removes them too — RAW concentration cleanup.
    """
    state = hub.get_battle(campaign_id)
    if not state:
        return False
    target = None
    for c in state.get("combatants") or []:
        if c.get("char_id") == character_id:
            target = c
            break
    if target is None:
        return False
    buffs = target.get("buffs") or []
    # Capture the buff we're about to remove so we know whether it's
    # a concentration buff (drives the paired-cleanup decision).
    removed_buff = next(
        (b for b in buffs if (b or {}).get("key") == key), None,
    )
    new_list = [b for b in buffs if (b or {}).get("key") != key]
    if len(new_list) == len(buffs):
        return False
    target["buffs"] = new_list
    hub.set_battle(campaign_id, state)
    await hub.broadcast(campaign_id, {
        "type": "buff_update",
        "data": {
            "character_id": character_id,
            "buffs": new_list,
            "removed_key": key,
        },
    })
    if removed_buff and bool(removed_buff.get("concentration")):
        await _drop_paired_concentration_buffs(campaign_id, character_id)
    return True


# v2.49.61 — Sleep wake-on-damage hook. RAW (PHB Sleep): "each creature
# affected by this spell falls unconscious until the spell ends, THE
# SLEEPER TAKES DAMAGE, or someone uses an action to shake or slap the
# sleeper awake." The damage pipeline calls this helper after applying
# damage; if the target has an Unconscious buff with `source_spell ==
# "Sleep"`, the buff is removed and a public 🌅 roll-log entry fires.
# Scoped tightly to `source_spell == "Sleep"` so other Unconscious
# sources (a future Power Word Knockout, etc.) aren't accidentally
# cleared by stray damage. The dying-at-0-HP state lives on
# `Character.sheet.death_saves`, NOT in a buff, so it's untouched.
async def _fire_damage_triggered_saves(
    campaign_id: int,
    character_id: int | None,
    combatant_id: str | None,
    damage_applied: int,
    *,
    db: "Session | None" = None,
) -> None:
    """v2.97.65 — companion to ``_wake_sleeping_on_damage``. RAW Fear
    + Hideous Laughter: a damaged target rolls a fresh save against
    the original spell's DC; success ends the effect. Reuses the
    v2.97.60 install-time stamps (``repeated_save_ability``,
    ``repeated_save_dc``, ``source_caster_creature_type``) plus the
    v2.97.65 catalog marker ``save_on_damage`` to identify which
    buffs qualify. Composes the save expression with the v2.97.50
    PFE&G advantage helper + the v2.97.35 Bless/Bane suffix, rolls,
    broadcasts a public 🩸 roll log entry, and drops the buff on
    pass.

    No-op when ``damage_applied <= 0`` (resistance reduced to 0 → no
    damage → no save trigger, RAW). PC path runs through
    ``_remove_buff`` so the buff_update broadcast + paired cleanup
    fire; NPC path mutates the combatant directly and broadcasts
    ``buff_update`` keyed on combatant_id.

    The DB session is required for the PC path so we can mirror
    the buff list back to the sheet after drop. NPC path doesn't
    need it.
    """
    if damage_applied <= 0:
        return
    state = hub.get_battle(campaign_id)
    if not state:
        return
    target = None
    for c in state.get("combatants") or []:
        if character_id and c.get("char_id") == character_id:
            target = c
            break
        if combatant_id and c.get("id") == combatant_id and not character_id:
            target = c
            break
    if target is None:
        return
    # Collect qualifying buffs up front (we mutate state during the
    # loop via _remove_buff / in-place edits).
    qualifying = []
    for b in (target.get("buffs") or []):
        if not isinstance(b, dict):
            continue
        if not b.get("save_on_damage"):
            continue
        ab = str(b.get("repeated_save_ability") or "").upper()[:3]
        try:
            dc = int(b.get("repeated_save_dc") or 0)
        except (TypeError, ValueError):
            dc = 0
        if ab not in {"STR", "DEX", "CON", "INT", "WIS", "CHA"}:
            continue
        if dc <= 0:
            continue
        qualifying.append((b, ab, dc))
    if not qualifying:
        return
    # v2.97.70 — delegate to the shared
    # ``_resolve_repeated_save_for_buff`` helper. PC + NPC saver
    # construction stays here; the save resolution + broadcast +
    # drop loop is shared with /use_repeated_save and the v2.97.62 /
    # v2.97.69 PUT /battle end-of-turn auto-fire.
    saver = None
    if character_id:
        if db is None:
            return
        char = db.query(Character).filter(
            Character.id == int(character_id),
        ).first()
        if not char or not char.sheet:
            return
        saver = {
            "kind": "pc",
            "char_id": int(character_id),
            "char_name": char.name,
            "sheet": dict(char.sheet),
        }
    else:
        tmpl_id = target.get("token_template_id")
        if not tmpl_id or db is None:
            return
        tmpl = db.query(TokenTemplate).filter(
            TokenTemplate.id == int(tmpl_id),
        ).first()
        if not tmpl:
            return
        try:
            npc_sheet = _monster_template_to_sheet(tmpl, campaign_id)
        except Exception:
            return
        saver = {
            "kind": "npc",
            "char_name": target.get("name") or tmpl.name or "Creature",
            "sheet": npc_sheet,
            "combatant": target,
        }

    for buff, _ab, _dc in qualifying:
        await _resolve_repeated_save_for_buff(
            campaign_id, db, saver, buff,
            note_prefix="🩸 Damage-triggered save",
            feature_used_source="damage-triggered-save-passed",
        )


def _buff_is_wakeable_by_action(buff: dict) -> bool:
    """v2.99.0 — generic marker check for "is this buff cleared by
    taking damage or by someone shaking the sleeper awake?"
    Returns True when the buff carries a ``wakeable_by_action: True``
    field at the top level (v2.99.0+ install paths stamp this) OR
    when the legacy v2.49.x check matches (``key`` in
    ``{unconscious, asleep}`` AND ``source_spell == "Sleep"``). The
    legacy path covers any pre-v2.99.0 buff that lives in a
    persisted PC sheet at upgrade time.

    Use this in place of the hardcoded ``source_spell == "Sleep"``
    check at:
    - ``_wake_sleeping_on_damage`` (the v2.49.61 damage-clears-sleep hook)
    - ``/wake_sleeper`` (the v2.97.63 shake-action endpoint)
    - ``/shake_awake`` (the legacy GM action endpoint)
    """
    if not isinstance(buff, dict):
        return False
    if buff.get("wakeable_by_action"):
        return True
    if (
        buff.get("key") in ("unconscious", "asleep")
        and buff.get("source_spell") == "Sleep"
    ):
        return True
    return False


async def _wake_sleeping_on_damage(
    campaign_id: int,
    character_id: int | None,
    combatant_id: str | None,
    damage_applied: int,
    *,
    db: Session | None = None,
) -> None:
    """If damage > 0 lands on a target carrying a Sleep-sourced
    Unconscious buff, remove the buff + emit a wake log.

    No-op when ``damage_applied <= 0`` (resistance reduced to 0 → no
    damage taken → no wake, RAW). No-op when the target has no
    Unconscious buff or the buff was sourced by something other than
    Sleep. Either ``character_id`` (PC) or ``combatant_id`` (NPC) is
    required; PC takes precedence when both are set.
    """
    if damage_applied <= 0:
        return
    state = hub.get_battle(campaign_id)
    if not state:
        return
    target = None
    for c in state.get("combatants") or []:
        if character_id and c.get("char_id") == character_id:
            target = c
            break
        if combatant_id and c.get("id") == combatant_id and not character_id:
            target = c
            break
    if target is None:
        return
    buffs = list(target.get("buffs") or [])
    # v2.99.0 — use the generic wakeable-by-action marker instead of
    # hardcoding source_spell == "Sleep". Future buffs (Hypnotic Pattern,
    # Power Word Knockout, etc.) opt in by stamping
    # ``wakeable_by_action: True`` on their install dict.
    sleep_keys = [
        b.get("key") for b in buffs
        if _buff_is_wakeable_by_action(b or {})
    ]
    if not sleep_keys:
        return
    if character_id:
        # PC path: route through _remove_buff so the buff_update
        # broadcast + paired-cleanup hook (no-op for concentration=
        # False Sleep buffs) fire consistently.
        for key in sleep_keys:
            await _remove_buff(campaign_id, int(character_id), key)
        # Keep the sheet mirror in sync — cast_sleep's install path
        # mirrors via _mirror_buffs_to_sheet, so the removal should too.
        if db is not None:
            _mirror_buffs_to_sheet(
                db, int(character_id),
                _get_buffs(campaign_id, int(character_id)),
            )
    else:
        # NPC path: mutate the combatant's buff list + broadcast
        # battle_update with force_gm_sync (mirrors the v2.49.40 NPC
        # HP-damage pattern in _apply_damage_to_combatant).
        new_list = [
            b for b in buffs
            if not _buff_is_wakeable_by_action(b or {})
        ]
        target["buffs"] = new_list
        hub.set_battle(campaign_id, state)
        await hub.broadcast(campaign_id, {
            "type": "battle_update",
            "data": state,
            "force_gm_sync": True,
        })
    # Public wake log.
    target_name = target.get("name") or "Unknown"
    await hub.broadcast(campaign_id, {
        "type": "roll",
        "data": {
            "expression": "—",
            "total": 0,
            "breakdown": "Damage wakes the sleeper — Sleep ends (RAW PHB Sleep)",
            "note": f"🌅 {target_name} wakes — damaged",
            "user_name": "GM log",
            "char_name": target_name,
            "visibility": Visibility.PUBLIC.value,
        },
    })


def _get_buffs(campaign_id: int, character_id: int) -> list[dict]:
    """Read helper: return the current buff list for a character (or
    empty list if no battle / not in init). Read-only — never mutates.
    """
    state = hub.get_battle(campaign_id)
    if not state:
        return []
    for c in state.get("combatants") or []:
        if c.get("char_id") == character_id:
            return list(c.get("buffs") or [])
    return []


async def _roll_spell_damage_with_metamagic(
    campaign_id: int, character_id: int | None, expr: str,
) -> tuple[int, str, dict | None]:
    """v2.49.124 Sorcery Phase 1: roll a spell damage expression while
    honoring a pending Empowered Spell metamagic buff on the caster.

    Looks up ``metamagic-empowered-pending`` on the caster's combatant.
    If found, reads ``effects.rerolls_available`` (set by
    ``/use_metamagic_empowered_spell`` from the caster's CHA modifier)
    and rerolls up to that many lowest damage dice. The buff is removed
    after the roll — Empowered Spell is one-cast-per-pay (PHB p.102).

    Falls back to a plain ``dice_mod.roll`` when ``character_id`` is
    falsy or no Empowered buff is present.

    Returns ``(total, breakdown, empowered_log_or_None)`` matching the
    underlying ``_roll_with_empowered_reroll`` contract.
    """
    rerolls = 0
    pending: dict | None = None
    if character_id:
        buffs = _get_buffs(campaign_id, int(character_id))
        for b in buffs:
            if (b or {}).get("key") == "metamagic-empowered-pending":
                pending = b
                break
        if pending is not None:
            rerolls = int(((pending.get("effects") or {}).get("rerolls_available")) or 0)
    total, bd, log = _roll_with_empowered_reroll(expr, rerolls)
    if pending is not None:
        await _remove_buff(campaign_id, int(character_id), "metamagic-empowered-pending")
    return (total, bd, log)


def _lookup_combatant_name(campaign_id: int, combatant_id: str | None) -> str:
    """v2.23.0 Phase T.8: resolve a hub combatant id to its display
    name. Returns the empty string when ``combatant_id`` is falsy, no
    battle is active, or the combatant isn't in init. Used by the
    /attack broadcast so the chat card can render ``→ NAME`` without
    a second client lookup.
    """
    if not combatant_id:
        return ""
    state = hub.get_battle(campaign_id)
    if not state:
        return ""
    for c in state.get("combatants") or []:
        if c.get("id") == combatant_id:
            return c.get("name") or ""
    return ""


def _lookup_combatant(campaign_id: int, combatant_id: str | None) -> dict | None:
    """v2.24.0 Phase T.2: return the full combatant dict (or None)."""
    if not combatant_id:
        return None
    state = hub.get_battle(campaign_id)
    if not state:
        return None
    for c in state.get("combatants") or []:
        if c.get("id") == combatant_id:
            return c
    return None


def _target_hasnt_acted_yet(
    campaign_id: int, target_combatant_id: "str | None",
) -> bool:
    """v2.132.0 — RAW Assassinate advantage gate (Assassin Rogue Lv 3+,
    PHB p.97): "you have advantage on attack rolls against any creature
    that hasn't taken a turn in the combat yet." Reads the target
    combatant's `has_acted` flag, flipped True by the turn-advance hook
    in PUT /battle the first time the target's turn starts. Defaults
    False on missing combatant / inactive battle so the advantage source
    is silent rather than accidentally granted to absent-target attacks.
    """
    target = _lookup_combatant(campaign_id, target_combatant_id)
    if not target:
        return False
    return not bool(target.get("has_acted", False))


# v2.49.73 — distance-on-grid primitive. Extracted from token_move
# (line ~5040, formerly inline). Matches the JS _computeRulerDistanceFt
# math exactly so server-side range checks and client-side ruler
# readings agree to the foot. Chebyshev (RAW 5e "5-5-5" diagonals) on
# square grids; Euclidean on hex / no-grid. 5 ft per cell, rounded to
# 0.1 ft. Returns 0.0 when grid_size_px <= 0 (no-grid maps have no
# meaningful distance concept — same fallback as token_move had).
# Phase 2A of docs/plans/ruler-and-range.md. Phase 2B/C/D will call
# this from the range-enforcement check sites.
def _distance_ft_between_points(
    grid_size_px: int, grid_type: str,
    ax: float, ay: float, bx: float, by: float,
) -> float:
    if grid_size_px <= 0:
        return 0.0
    dx = bx - ax
    dy = by - ay
    if (grid_type or "square").lower() == "square":
        cells = max(abs(dx), abs(dy)) / grid_size_px
    else:
        cells = (dx * dx + dy * dy) ** 0.5 / grid_size_px
    return round(cells * 5, 1)


def _segment_to_point_min_ft(
    grid_size_px: int,
    ax: float, ay: float, bx: float, by: float,
    px: float, py: float,
) -> float:
    """v2.99.60 — minimum distance in feet from the line segment
    (a→b) to the point (p). Used by the path-aware OA detection
    in `_check_opportunity_attack_triggers`: if a watcher's reach
    circle intersects a mover's path (even though the start and
    end positions are BOTH outside the reach), the mover passed
    through the reach mid-move and provokes an OA on exit.

    Uses Euclidean distance (px → ft via grid_size_px) regardless
    of grid type. The Chebyshev/Euclidean distinction in
    `_distance_ft_between_points` matters for end-to-end distance
    rendering ("how many feet did you move"); the path-cross check
    is a pure geometric "did the threat circle touch your path?"
    question for which Euclidean is the natural metric. Square
    grids' Chebyshev approximation would over-detect, so Euclidean
    is the stricter (and more conservative) RAW reading.
    """
    if grid_size_px <= 0:
        return 0.0
    dx = bx - ax
    dy = by - ay
    seg_len_sq = dx * dx + dy * dy
    if seg_len_sq == 0.0:
        # Zero-length segment — distance is just point-to-point.
        return ((px - ax) ** 2 + (py - ay) ** 2) ** 0.5 / grid_size_px * 5
    # Project P onto the segment, clamping the parameter to [0, 1]
    # so we stay within the segment endpoints.
    t = ((px - ax) * dx + (py - ay) * dy) / seg_len_sq
    if t < 0.0:
        t = 0.0
    elif t > 1.0:
        t = 1.0
    qx = ax + t * dx
    qy = ay + t * dy
    px_dist = ((px - qx) ** 2 + (py - qy) ** 2) ** 0.5
    return round(px_dist / grid_size_px * 5, 1)


# v2.62.1 — F1 consumer #2: Sneak Attack ally-adjacency detection.
# RAW Sneak Attack (Rogue Lv 1): "advantage on the attack roll" OR
# "another enemy of the target is within 5 ft of it, not
# incapacitated, and you don't have disadvantage on the attack roll."
# Pre-v2.62.1 the eligibility was trust-based (client asserts).
# v2.62.1 uses the v2.61.0 _distance_ft_between_chars primitive to
# auto-detect the "another enemy within 5 ft of target" branch.
# Surfaced as an advisory ``sneak_attack_ally_adjacent`` field in
# the /attack response — non-enforcing (client UI may render a
# "Sneak Attack eligible" hint).
#
# v1 simplifications:
# - "Enemy of the target" — RAW requires the adjacent creature to
#   be hostile to the target. v1 counts ANY creature other than the
#   rogue + target. With the demo's typical "monsters vs PCs" layout
#   this is correct ~95% of the time; mixed loyalty edge cases
#   (charmed ally, party-vs-party PVP) are filed.
# - "Not incapacitated" — RAW excludes adjacent creatures who are
#   incapacitated. v1 doesn't check the incapacitated buff; filed.
# - "You don't have disadvantage" — RAW disqualifies the rogue when
#   they have disadvantage. v1 doesn't read the rogue's roll-state
#   today; filed.
def _sneak_attack_ally_adjacent(
    db: Session, campaign_id: int,
    rogue_char_id: int | None,
    target_combatant_id: str | None,
) -> bool:
    """v2.62.1 — returns True when at least one combatant (other than
    the rogue + the target) is within 5 ft of the target.

    Reads the active battle's combatant list, resolves the target's
    char_id, then walks every other combatant calling
    ``_distance_ft_between_chars(other, target)`` ≤ 5.0. Stops at
    the first hit.

    Returns False when no eligible adjacent creature is found, OR
    when the helper has insufficient data to compute (no battle, no
    target combatant, no positions). Same fall-back semantics as
    the v2.61.0 aura gates.
    """
    if not rogue_char_id or not target_combatant_id:
        return False
    state = hub.get_battle(campaign_id)
    if not state:
        return False
    combatants = state.get("combatants") or []
    target_combatant = None
    for c in combatants:
        if c.get("id") == target_combatant_id:
            target_combatant = c
            break
    if not target_combatant:
        return False
    target_char_id = target_combatant.get("char_id")
    if not target_char_id:
        # NPCs without a char_id aren't reachable via
        # _distance_ft_between_chars (which keys on Character rows).
        # Filed: NPC Token positions could be looked up by
        # source_token_id instead. For now Sneak Attack against
        # NPC targets gates on advantage only (trust-based).
        return False
    target_char_id = int(target_char_id)
    rogue_char_id_int = int(rogue_char_id)
    for c in combatants:
        other_char_id = c.get("char_id")
        if not other_char_id:
            continue
        other_id = int(other_char_id)
        if other_id == rogue_char_id_int or other_id == target_char_id:
            continue
        distance = _distance_ft_between_chars(
            db, campaign_id, other_id, target_char_id,
        )
        if distance is not None and distance <= 5.0:
            return True
    return False


# v2.61.0 — F1 token positional adjacency primitive. Looks up two
# characters' tokens on the campaign's active map and returns the
# in-game distance in feet between them. Returns None when the
# distance can't be computed (no active map, no grid_size_px, either
# character has no token on the map). Callers should treat None as
# "no position data — fall back to the v1 'any in init' simplification"
# rather than blocking the feature; positional gating is opt-in
# enrichment, not a hard requirement.
#
# Plan source: docs/plans/class-content-status.md "F1. Token positional
# adjacency / 5-ft-range checking". Unblocks the 10/30 ft radius
# gates filed against Aura of Protection (v2.53.0), Aura of Devotion
# (v2.55.0), Countercharm (v2.54.0), plus future Sneak Attack
# ally-adjacency (v2.16.0 filed) + Bardic Inspiration recipient
# range + Mass Cure target range + Opportunity Attack trigger.
def _distance_ft_between_chars(
    db: Session, campaign_id: int,
    char_a_id: int | None, char_b_id: int | None,
) -> "float | None":
    """v2.61.0 — distance in feet between two characters' tokens on
    the campaign's active map. Returns None when:
      - either char_id is falsy / not provided,
      - no active map on the campaign,
      - active map has no grid_size_px (no-grid maps are off-grid),
      - either character has no Token row on the active map.

    Returns 0.0 when both ids point to the same character (a self-aura
    target is always in range).

    Uses ``_distance_ft_between_points`` under the hood — square grids
    use Chebyshev distance (RAW 5e 5-5-5 diagonals), hex grids use
    Euclidean. 5 ft per cell, rounded to 0.1 ft.
    """
    if not char_a_id or not char_b_id:
        return None
    if int(char_a_id) == int(char_b_id):
        return 0.0
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not campaign.active_map_id:
        return None
    map_row = db.query(Map).filter(Map.id == campaign.active_map_id).first()
    if not map_row or not map_row.grid_size_px:
        return None
    token_a = (
        db.query(Token)
        .filter(Token.character_id == int(char_a_id), Token.map_id == map_row.id)
        .first()
    )
    if not token_a:
        return None
    token_b = (
        db.query(Token)
        .filter(Token.character_id == int(char_b_id), Token.map_id == map_row.id)
        .first()
    )
    if not token_b:
        return None
    grid_type = (
        map_row.grid_type.value if map_row.grid_type else "square"
    ).lower()
    return _distance_ft_between_points(
        int(map_row.grid_size_px),
        grid_type,
        float(token_a.x or 0), float(token_a.y or 0),
        float(token_b.x or 0), float(token_b.y or 0),
    )


def _combatant_token(db: Session, campaign_id: int, combatant: "dict | None"):
    """v2.99.432 — Phase 6.2: resolve a battle-state combatant to its
    ``Token`` row on the campaign's active map. Prefers the combatant's
    ``source_token_id`` (NPC); falls back to its ``char_id`` (PC). Returns
    None when there's no active map / no matching token (off-grid scene).
    """
    if not combatant:
        return None
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not campaign.active_map_id:
        return None
    stid = combatant.get("source_token_id")
    if stid:
        t = db.query(Token).filter(
            Token.id == int(stid), Token.map_id == campaign.active_map_id,
        ).first()
        if t:
            return t
    cid = combatant.get("char_id")
    if cid:
        t = db.query(Token).filter(
            Token.character_id == int(cid),
            Token.map_id == campaign.active_map_id,
        ).first()
        if t:
            return t
    return None


async def _force_move(
    db: Session,
    campaign_id: int,
    target_combatant: "dict | None",
    distance_ft: float,
    *,
    source_combatant: "dict | None" = None,
    pull: bool = False,
) -> dict:
    """v2.99.432 — Phase 6.2 of docs/plans/movement-and-summons.md:
    server-side forced movement. Move ``target_combatant``'s token
    ``distance_ft`` along the line from ``source_combatant`` to the target
    (pushed AWAY, or ``pull`` = toward); with no source, push along +x.
    Mutates ``Token.x/y`` directly and broadcasts ``token_move`` (with
    ``forced: True``). Does NOT consume the target's movement or hit the
    speed cap (forced move is involuntary), and skips the OA check (RAW
    forced movement doesn't provoke).

    Off-grid (no active map / no grid / no token) → ``{moved: False}`` so
    the caller can fall back to announce-only. Returns ``{moved,
    token_id, from_x, from_y, to_x, to_y, distance_ft}``.
    """
    result = {"moved": False, "token_id": None, "from_x": 0.0,
              "from_y": 0.0, "to_x": 0.0, "to_y": 0.0, "distance_ft": 0.0}
    try:
        dist = float(distance_ft or 0)
    except (TypeError, ValueError):
        dist = 0.0
    if dist <= 0 or not target_combatant:
        return result
    token = _combatant_token(db, campaign_id, target_combatant)
    if not token or not token.map or not token.map.grid_size_px:
        return result
    grid = int(token.map.grid_size_px)
    from_x, from_y = float(token.x or 0), float(token.y or 0)
    ux, uy = 1.0, 0.0  # default push direction (+x) when no source
    if source_combatant:
        src = _combatant_token(db, campaign_id, source_combatant)
        if src:
            sx, sy = float(src.x or 0), float(src.y or 0)
            dx, dy = from_x - sx, from_y - sy  # source → target
            mag = (dx * dx + dy * dy) ** 0.5
            if mag > 0.001:
                ux, uy = dx / mag, dy / mag
            if pull:
                ux, uy = -ux, -uy
    px = dist / 5.0 * grid
    to_x = from_x + ux * px
    to_y = from_y + uy * px
    grid_type = (
        token.map.grid_type.value if token.map.grid_type else "square"
    ).lower()
    actual_ft = _distance_ft_between_points(
        grid, grid_type, from_x, from_y, to_x, to_y,
    )
    token.x = to_x
    token.y = to_y
    db.commit()
    await hub.broadcast(campaign_id, {
        "type": "token_move",
        "data": {
            "id": token.id,
            "x": to_x, "y": to_y,
            "from_x": from_x, "from_y": from_y,
            "distance_ft": actual_ft,
            "character_id": token.character_id,
            "token_template_id": token.token_template_id,
            "forced": True,
        },
    })
    result.update(moved=True, token_id=token.id, from_x=from_x,
                  from_y=from_y, to_x=to_x, to_y=to_y, distance_ft=actual_ft)
    return result


# v2.99.437 — Phase 7.1 of docs/plans/movement-and-summons.md: a small
# registry of summonable companion stat blocks. Each entry carries
# enough to stand up a REAL combatant — its own token + init slot + HP +
# AC — that reuses the existing damage / HP pipeline for free. Keyed by a
# stable slug; the per-spell retrofits (Spiritual Weapon, Find Familiar,
# …) pick the entry that matches the summon.
_COMPANION_TEMPLATES: dict[str, dict] = {
    "wolf": {"name": "Wolf", "ac": 13, "hp": 11, "speed_walk": 40,
             "size": 1, "team": "hero", "color": "#7a8a99"},
    "spiritual-weapon": {"name": "Spiritual Weapon", "ac": 0, "hp": 1,
                         "speed_walk": 0, "size": 1, "team": "hero",
                         "color": "#d9c46a"},
    "flaming-sphere": {"name": "Flaming Sphere", "ac": 0, "hp": 1,
                       "speed_walk": 30, "size": 1, "team": "hero",
                       "color": "#e8772e"},
    "familiar": {"name": "Familiar", "ac": 11, "hp": 1, "speed_walk": 5,
                 "size": 1, "team": "hero", "color": "#b8a3d9"},
    "beast-companion": {"name": "Beast Companion", "ac": 13, "hp": 11,
                        "speed_walk": 40, "size": 1, "team": "hero",
                        "color": "#8a6d3b"},
    "steel-defender": {"name": "Steel Defender", "ac": 15, "hp": 2,
                       "speed_walk": 40, "size": 1, "team": "hero",
                       "color": "#6b7280"},
}


async def _summon_companion(
    db: Session,
    campaign_id: int,
    *,
    owner_char_id: int,
    companion_key: str,
    name: "str | None" = None,
    x: float = 0.0,
    y: float = 0.0,
    initiative: int = 0,
    hp: "int | None" = None,
    ac: "int | None" = None,
    concentration_bound: bool = False,
) -> "dict | None":
    """v2.99.437 — Phase 7.1: stand up a summoned companion as a REAL
    combatant. Creates an NPC ``Token`` on the active map (broadcast
    ``token_add``), synthesizes a combatant dict from the registry stat
    block (HP + AC ride on the dict — no ``TokenTemplate`` row), appends
    it to the battle state (init slot, broadcast ``battle_update`` with
    ``force_gm_sync``), and tags it ``is_summon`` + ``summoned_by`` for
    teardown. The companion reuses the existing damage / HP pipeline +
    `_force_move` for free.

    ``hp`` / ``ac`` override the registry stat block when supplied
    (v2.99.441 — Ranger's Companion scales HP with ranger level + adds
    the proficiency bonus to AC).

    Off-grid (no active map) → the combatant is still added but with no
    token (``token_id`` None — announce-style fallback). Returns
    ``{combatant, token_id, companion_key}`` or None for an unknown key.
    """
    entry = _COMPANION_TEMPLATES.get((companion_key or "").strip().lower())
    if not entry:
        return None
    disp_name = (name or entry["name"])[:120]

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    token_id = None
    if campaign and campaign.active_map_id:
        t = Token(
            map_id=campaign.active_map_id,
            character_id=None,
            token_template_id=None,
            label=disp_name,
            color=entry.get("color", "#888888"),
            image_url=entry.get("image_url"),
            x=float(x or 0), y=float(y or 0),
            size=int(entry.get("size", 1)),
        )
        db.add(t)
        db.commit()
        db.refresh(t)
        token_id = t.id
        await hub.broadcast(campaign_id, {
            "type": "token_add", "data": _token_dict(t),
        })

    hp_val = int(hp) if hp is not None else int(entry["hp"])
    ac_val = int(ac) if ac is not None else int(entry.get("ac", 10))
    combatant = {
        "id": (f"summon_{token_id}" if token_id
               else f"summon_{owner_char_id}_{disp_name}"),
        "char_id": None,
        "name": disp_name,
        "token_template_id": None,
        "source_token_id": token_id,
        "initiative": int(initiative or 0),
        "hp_current": hp_val,
        "hp_max": hp_val,
        "ac": ac_val,
        "speed_walk": int(entry.get("speed_walk", 30)),
        "team": entry.get("team", "hero"),
        "buffs": [],
        "economy": {"action": False, "bonus": False,
                    "reaction": False, "movement": 0},
        "is_summon": True,
        "summoned_by": int(owner_char_id),
        "companion_key": (companion_key or "").strip().lower(),
        # v2.113.0 — when True, the caster losing concentration dismisses
        # this summon (the _drop_paired_concentration_buffs cascade).
        "concentration_bound": bool(concentration_bound),
    }
    state = hub.get_battle(campaign_id) or {
        "combatants": [], "turn_index": 0, "round": 1, "active": False,
    }
    state.setdefault("combatants", []).append(combatant)
    hub.set_battle(campaign_id, state)
    await hub.broadcast(campaign_id, {
        "type": "battle_update", "data": state, "force_gm_sync": True,
    })
    return {"combatant": combatant, "token_id": token_id,
            "companion_key": combatant["companion_key"]}


async def _dismiss_companion(
    db: Session, campaign_id: int, combatant_id: str,
) -> dict:
    """v2.99.437 — Phase 7.1: teardown for a summoned companion. Removes
    the combatant from the battle state (broadcast ``battle_update``) and
    deletes its ``Token`` (broadcast ``token_delete``). Returns
    ``{removed, combatant_id, token_id}``; ``removed`` is False when no
    matching summon is in the battle.
    """
    result = {"removed": False, "combatant_id": combatant_id, "token_id": None}
    state = hub.get_battle(campaign_id)
    if not state:
        return result
    combatants = state.get("combatants") or []
    target = next(
        (c for c in combatants
         if c.get("id") == combatant_id and c.get("is_summon")), None,
    )
    if not target:
        return result
    token_id = target.get("source_token_id")
    state["combatants"] = [c for c in combatants if c.get("id") != combatant_id]
    hub.set_battle(campaign_id, state)
    if token_id:
        tok = db.query(Token).filter(Token.id == int(token_id)).first()
        if tok:
            db.delete(tok)
            db.commit()
        await hub.broadcast(campaign_id, {
            "type": "token_delete", "data": {"id": int(token_id)},
        })
    await hub.broadcast(campaign_id, {
        "type": "battle_update", "data": state, "force_gm_sync": True,
    })
    result.update(removed=True, token_id=token_id)
    return result


async def _teardown_summons_for_owner(
    db: Session, campaign_id: int, owner_char_id: int,
) -> list:
    """v2.99.439 — Phase 7.1: drop every summoned companion owned by
    ``owner_char_id`` (the long-rest teardown — RAW most summons end on a
    rest, and the plan's risks section flags un-torn-down companions as a
    board leak). Each is removed via `_dismiss_companion` (combatant +
    token + broadcasts). Returns the list of dismissed combatant ids.
    """
    state = hub.get_battle(campaign_id)
    if not state:
        return []
    ids = [
        c.get("id") for c in (state.get("combatants") or [])
        if c.get("is_summon") and c.get("summoned_by") == int(owner_char_id)
    ]
    dismissed = []
    for cid in ids:
        res = await _dismiss_companion(db, campaign_id, cid)
        if res["removed"]:
            dismissed.append(cid)
    return dismissed


# v2.66.0 — F1 follow-up: Opportunity Attack trigger detection.
# RAW (PHB p.195): "You can make an opportunity attack when a hostile
# creature that you can see moves out of your reach. To make the
# opportunity attack, you use your reaction to make one melee attack
# against the provoking creature."
#
# When a token moves, walk every OTHER combatant in the active battle
# and check whether the mover transitioned from within-reach to
# out-of-reach. Each provoked watcher returns one entry; the caller
# broadcasts an advisory feature_used so the player UI can prompt the
# watcher's controller to spend their reaction on an OA.
#
# v2.66.1 — reach-weapon support. Reach is no longer hardcoded 5 ft;
# `_combatant_melee_reach_ft(db, combatant)` returns the watcher's
# largest melee reach in feet. Honors an explicit `melee_reach_ft`
# field on the combatant (GM override), then for PCs falls back to
# scanning `sheet.attacks` for melee ranges (range strings parseable
# by `parse_range_ft` as a plain int, not a thrown N/M tuple). NPC
# action-desc parsing ("reach 10 ft.") filed for a follow-up — today
# the GM can set `melee_reach_ft` explicitly on NPC combatants in the
# `/battle` PUT to match monster reach.
#
# v1 simplifications still apply:
#   - "Hostile" not enforced — every other combatant is a potential
#     watcher. Mixed-loyalty (charmed PC, friendly NPC) is filed.
#   - "Can see" not enforced (no visibility/cover model yet).
#   - Pure advisory broadcast — does NOT consume the reaction or fire
#     the attack. Player UI decides whether to spend.
#   - Watchers whose reaction is already used in this round are
#     skipped (no spam broadcasts).
# v2.66.5 — Sentinel feat detection. Same shape as Polearm Master:
# explicit ``sentinel: True`` on the combatant dict (GM flag for
# NPCs) or PC ``sheet.feats`` entry with slug "sentinel".
def _combatant_has_sentinel(
    db: Session, combatant: dict,
) -> bool:
    explicit = combatant.get("sentinel")
    if explicit is not None:
        return bool(explicit)
    char_id = combatant.get("char_id")
    if char_id:
        try:
            char = db.query(Character).filter(
                Character.id == int(char_id),
            ).first()
        except Exception:
            char = None
        if char and char.sheet:
            for f in (char.sheet.get("feats") or []):
                if not isinstance(f, dict):
                    continue
                slug = (f.get("slug") or "").strip().lower()
                if slug == "sentinel":
                    return True
                name = (f.get("name") or "").strip().lower().replace(" ", "-")
                if name == "sentinel":
                    return True
    return False


# v2.66.5 — Sentinel "ally attacked near you" trigger. RAW (PHB
# Sentinel effect 3): "When a creature within 5 feet of you makes
# an attack against a target other than you (and that target doesn't
# have this feat), you can use your reaction to make a melee weapon
# attack against the attacking creature."
#
# Fires on every weapon attack. Walks combatants for any Sentinel
# watcher (not the attacker, not the target) within 5 ft of the
# attacker whose reaction is still available. Pure advisory — does
# NOT auto-fire the reaction.
#
# v1 simplifications:
#   - Always 5 ft (RAW). No per-watcher tweak.
#   - Target-has-Sentinel exception (the RAW "and that target doesn't
#     have this feat") IS honored — Sentinel watchers can't trigger
#     when the attack target ALSO has Sentinel.
#   - Hostility / visibility not gated (mirror of OA simplifications).
def _check_sentinel_attack_triggers(
    db: Session, campaign_id: int,
    attacker_combatant_id: str | None,
    attacker_char_id: int | None,
    target_combatant_id: str | None,
) -> list[dict]:
    """Return list of provoked Sentinel triggers. Each entry shape
    mirrors the OA trigger dict: ``{watcher_combatant_id,
    watcher_name, watcher_char_id, watcher_color, watcher_token_id,
    dist_ft}``. Empty list when no active battle, no active map, or
    no qualifying watcher.
    """
    if not attacker_combatant_id and not attacker_char_id:
        return []
    state = hub.get_battle(campaign_id)
    if not state:
        return []
    combatants = state.get("combatants") or []
    if not combatants:
        return []
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not campaign.active_map_id:
        return []
    map_row = db.query(Map).filter(Map.id == campaign.active_map_id).first()
    if not map_row or not map_row.grid_size_px:
        return []
    grid_type = (
        map_row.grid_type.value if map_row.grid_type else "square"
    ).lower()
    grid_size_px = int(map_row.grid_size_px)

    # Locate the attacker's combatant + token position.
    attacker_combatant = None
    for c in combatants:
        if attacker_combatant_id and c.get("id") == attacker_combatant_id:
            attacker_combatant = c
            break
        if (
            attacker_char_id and c.get("char_id") == int(attacker_char_id)
        ):
            attacker_combatant = c
            break
    if attacker_combatant is None:
        return []
    attacker_token = None
    src_id = attacker_combatant.get("source_token_id")
    if src_id:
        attacker_token = db.query(Token).filter(
            Token.id == int(src_id), Token.map_id == map_row.id,
        ).first()
    if attacker_token is None and attacker_combatant.get("char_id"):
        attacker_token = db.query(Token).filter(
            Token.character_id == int(attacker_combatant["char_id"]),
            Token.map_id == map_row.id,
        ).first()
    if attacker_token is None:
        return []
    ax = float(attacker_token.x or 0)
    ay = float(attacker_token.y or 0)

    # RAW exception: skip Sentinel triggers when the target ALSO has
    # the Sentinel feat. Sentinel doesn't fire watcher-to-watcher.
    if target_combatant_id:
        target_combatant = None
        for c in combatants:
            if c.get("id") == target_combatant_id:
                target_combatant = c
                break
        if target_combatant is not None:
            if _combatant_has_sentinel(db, target_combatant):
                return []

    SENTINEL_REACH_FT = 5.0
    triggers: list[dict] = []
    for c in combatants:
        if c.get("id") == (attacker_combatant_id or attacker_combatant.get("id")):
            continue
        if target_combatant_id and c.get("id") == target_combatant_id:
            continue
        economy = c.get("economy") or {}
        if bool(economy.get("reaction")):
            continue
        if not _combatant_has_sentinel(db, c):
            continue
        # Locate watcher's token.
        watcher_token = None
        wsrc = c.get("source_token_id")
        if wsrc:
            watcher_token = db.query(Token).filter(
                Token.id == int(wsrc), Token.map_id == map_row.id,
            ).first()
        if watcher_token is None and c.get("char_id"):
            watcher_token = db.query(Token).filter(
                Token.character_id == int(c["char_id"]),
                Token.map_id == map_row.id,
            ).first()
        if watcher_token is None:
            continue
        wx = float(watcher_token.x or 0)
        wy = float(watcher_token.y or 0)
        dist = _distance_ft_between_points(
            grid_size_px, grid_type, wx, wy, ax, ay,
        )
        if dist > SENTINEL_REACH_FT:
            continue
        triggers.append({
            "watcher_combatant_id": c.get("id"),
            "watcher_name": c.get("name") or "Combatant",
            "watcher_char_id": c.get("char_id"),
            "watcher_color": c.get("color"),
            "watcher_token_id": int(watcher_token.id),
            "dist_ft": dist,
        })
    return triggers


# v2.66.4 — Polearm Master feat detection. RAW (PHB feat):
# "While you are wielding a glaive, halberd, pike, quarterstaff, or
# spear, other creatures provoke an opportunity attack from you when
# they enter your reach." Returns True when the combatant has the
# feat set: either an explicit ``polearm_master: True`` on the
# combatant dict (GM flag for NPCs) or a PC sheet with a
# ``feats`` entry whose slug normalizes to "polearm-master".
# v2.99.27 — RAW polearm weapon names. Polearm Master applies to
# glaive / halberd / quarterstaff (PHB p.168) + spear (PHB errata /
# Tasha's). Pike is sometimes included by extended interpretation;
# included here for the v1 polearm gate. Matched case-insensitively
# against an equipped weapon's name or `_slug` field on the sheet.
_POLEARM_WEAPON_NAMES = {
    "glaive", "halberd", "quarterstaff", "spear", "pike",
}


def _pc_wields_polearm(sheet: "dict | None") -> bool:
    """v2.99.27 — return True when the sheet has an equipped weapon
    whose name or `_slug` matches one of `_POLEARM_WEAPON_NAMES`.
    Reads `sheet["inventory"]` for `equipped: True` weapon items.
    """
    if not sheet:
        return False
    for item in (sheet.get("inventory") or []):
        if not isinstance(item, dict):
            continue
        if not item.get("equipped"):
            continue
        name = (item.get("name") or "").strip().lower()
        slug = (item.get("_slug") or "").strip().lower()
        for polearm in _POLEARM_WEAPON_NAMES:
            if polearm in name or polearm in slug:
                return True
    return False


def _combatant_has_polearm_master(
    db: Session, combatant: dict,
) -> bool:
    """v2.66.4 — Polearm Master feat detection.

    v2.99.27 — sheet-driven path now also gates on the PC actually
    wielding a polearm (RAW PHB p.168: the feat's enter-reach OA
    requires "you are wielding a glaive, halberd, pike, quarterstaff,
    or spear"). The explicit combatant-level `polearm_master`
    override (used by test fixtures + GM overrides) still wins —
    it bypasses both feat and weapon checks. This preserves the
    v2.66.4 test fixtures while tightening the production gate to
    match RAW.
    """
    explicit = combatant.get("polearm_master")
    if explicit is not None:
        return bool(explicit)
    char_id = combatant.get("char_id")
    if not char_id:
        return False
    try:
        char = db.query(Character).filter(
            Character.id == int(char_id),
        ).first()
    except Exception:
        char = None
    if not char or not char.sheet:
        return False
    has_feat = False
    for f in (char.sheet.get("feats") or []):
        if not isinstance(f, dict):
            continue
        slug = (f.get("slug") or "").strip().lower()
        name = (f.get("name") or "").strip().lower().replace(" ", "-")
        if slug == "polearm-master" or name == "polearm-master":
            has_feat = True
            break
    if not has_feat:
        return False
    # v2.99.27 — RAW polearm-wielding gate on the sheet-driven path.
    return _pc_wields_polearm(char.sheet)


# v2.66.2 — Regex for NPC monster action desc strings. The SRD
# convention is "reach N ft." (e.g. "Melee Weapon Attack: +8 to hit,
# reach 10 ft., one target."). Pulls the first integer after "reach"
# so a Hill Giant's Greatclub action contributes 10 ft to the
# combatant's melee reach.
_NPC_REACH_RE = _re.compile(
    r"\breach\s+(\d+)\s*(?:ft|foot|feet)\.?", _re.IGNORECASE,
)


def _combatant_melee_reach_ft(
    db: Session, combatant: dict,
) -> float:
    """v2.66.1 / v2.66.2 — Reach in feet for a combatant's melee
    threat zone.

    Resolution order:
      1. ``combatant["melee_reach_ft"]`` — explicit override on the
         combatant dict (GM sets per-combatant via /battle PUT, e.g.
         for a glaive-wielding NPC or a Hill Giant).
      2. For PCs (combatant has ``char_id``): walk the character's
         ``sheet.attacks`` and find the maximum melee range. An attack
         counts as melee when its ``range`` string parses (via
         ``parse_range_ft``) to a plain integer (not a thrown tuple
         or None). Thrown / ranged weapons (e.g. "30/120 ft" → tuple)
         are excluded. Save-DC attacks (spell saves) are excluded.
      3. For NPCs (combatant has ``source_token_id``): look up the
         Token → TokenTemplate, project via ``_monster_template_to_sheet``,
         walk the resulting attacks, and regex ``reach N ft.`` from
         each action's desc/description field. Max across all matches.
      4. Default: 5.0 ft (RAW unarmed strike / standard weapon reach).

    Caps at 15 ft (largest practical 5e reach weapon / monster reach;
    defensive against ranged spell attacks miscategorized as melee).
    """
    # Largest 5e melee reach weapon is the lance at 10 ft; some
    # monsters reach 15 ft (Treant, Storm Giant, etc.). Defensive
    # cap so a Fire Bolt's "120 ft" range can't inflate the threat
    # zone to absurd distances even if it slips past other filters.
    MELEE_REACH_CAP_FT = 15.0

    explicit = combatant.get("melee_reach_ft")
    if explicit is not None:
        try:
            v = float(explicit)
            if v > 0:
                return v
        except (TypeError, ValueError):
            pass

    char_id = combatant.get("char_id")
    if char_id:
        try:
            char = db.query(Character).filter(
                Character.id == int(char_id),
            ).first()
        except Exception:
            char = None
        if char and char.sheet:
            from ..content.range_parser import parse_range_ft
            best = 0.0
            for atk in (char.sheet.get("attacks") or []):
                if not isinstance(atk, dict):
                    continue
                # Skip save-based attacks (spell saves like Sacred
                # Flame have a `save_dc > 0` field; they're never
                # melee weapons).
                try:
                    if int(atk.get("save_dc") or 0) > 0:
                        continue
                except (TypeError, ValueError):
                    pass
                range_str = (atk.get("range") or "").strip()
                if not range_str:
                    continue
                parsed = parse_range_ft(range_str)
                # Only single-band integer reach counts as melee
                # (thrown/ranged "N/M ft" parses to a tuple; "Self"
                # / "Touch" / "Unlimited" become 0/5/None). Cap at
                # MELEE_REACH_CAP_FT to defend against ranged
                # spell attacks miscategorized as melee.
                if isinstance(parsed, int) and 0 < parsed <= MELEE_REACH_CAP_FT:
                    if float(parsed) > best:
                        best = float(parsed)
            if best > 0:
                return best

    # NPC path — v2.66.2.
    src_token_id = combatant.get("source_token_id")
    if src_token_id:
        try:
            t = db.query(Token).filter(Token.id == int(src_token_id)).first()
        except Exception:
            t = None
        tmpl = None
        if t and t.token_template_id:
            try:
                tmpl = db.query(TokenTemplate).filter(
                    TokenTemplate.id == int(t.token_template_id),
                ).first()
            except Exception:
                tmpl = None
        if tmpl is not None:
            try:
                proj = _monster_template_to_sheet(tmpl, 0)
            except Exception:
                proj = None
            if isinstance(proj, dict):
                best = 0.0
                # SRD monsters fold action descs into "attacks"
                # (projection writes the desc into either "description"
                # or "desc"). The original actions list also lives at
                # sheet["actions"]. Scan both so we catch every reach
                # mention.
                desc_sources: list[str] = []
                for atk in (proj.get("attacks") or []):
                    if not isinstance(atk, dict):
                        continue
                    # Skip save-based attacks — those are spell-save
                    # actions (Frightful Presence, Breath weapons),
                    # not melee weapons. The reach numerically printed
                    # in the desc would be wrong to credit as melee.
                    try:
                        if int(atk.get("save_dc") or 0) > 0:
                            continue
                    except (TypeError, ValueError):
                        pass
                    for k in ("description", "desc"):
                        v = atk.get(k)
                        if isinstance(v, str) and v:
                            desc_sources.append(v)
                for action in (proj.get("actions") or []):
                    if not isinstance(action, dict):
                        continue
                    try:
                        if int(action.get("save_dc") or 0) > 0:
                            continue
                    except (TypeError, ValueError):
                        pass
                    v = action.get("desc")
                    if isinstance(v, str) and v:
                        desc_sources.append(v)
                for text in desc_sources:
                    for m in _NPC_REACH_RE.finditer(text):
                        try:
                            n = int(m.group(1))
                        except (TypeError, ValueError):
                            continue
                        if 0 < n <= MELEE_REACH_CAP_FT and float(n) > best:
                            best = float(n)
                if best > 0:
                    return best

    return 5.0


def _speed_walk_from_sheet(sheet: dict | None) -> int:
    """Read walking speed from a sheet dict. v2.99.65 — single
    source-of-truth helper for combatant speed_walk healing on
    encounter Load + demo seed + NPC auto-add. Mirrors the
    client-side ``_speedWalkFromSheet`` in tabletop.html so the
    server agrees with what the GM client computes when adding a
    combatant via the manual Add-to-Init flow.

    Accepts the canonical ``sheet["speed"]`` field in three shapes:
      - int (PC sheets after demo-seed normalization, monster
        sheets after ``_monster_dict_to_sheet``)
      - dict with a ``walk`` sub-key (open5e-shaped homebrew
        templates pre-projection)
      - string like "30 ft." (legacy / hand-edited sheets)

    Returns the parsed int speed in feet, or 30 as the standard
    medium-humanoid fallback when no valid value is found.
    """
    if not sheet or not isinstance(sheet, dict):
        return 30
    v = sheet.get("speed")
    if isinstance(v, (int, float)) and v > 0:
        return int(v)
    if isinstance(v, dict):
        w = v.get("walk")
        if isinstance(w, (int, float)) and w > 0:
            return int(w)
        if isinstance(w, str):
            import re as _re
            m = _re.search(r"\d+", w)
            if m:
                n = int(m.group())
                if n > 0:
                    return n
    if isinstance(v, str):
        import re as _re
        m = _re.search(r"\d+", v)
        if m:
            n = int(m.group())
            if n > 0:
                return n
    return 30


def _resolve_combatant_speed_walk(
    db: Session, campaign_id: int, combatant: dict,
) -> int:
    """v2.99.65 — project a combatant's walking speed by looking
    up its linked Character (PC) or TokenTemplate (NPC) sheet.
    Used by encounter Load (heals stale combatants) and the NPC
    auto-add path (line ~14934) to populate the missing field
    instead of letting the consumer fall back to a hard-coded 30.

    Precedence:
      1. ``char_id`` → ``Character.sheet["speed"]``
      2. ``token_template_id`` → ``_monster_template_to_sheet(tmpl)["speed"]``
         (projects monster_slug overlays + homebrew speeds via the
         same path the right-click NPC sheet uses)
      3. Default 30.
    """
    char_id = combatant.get("char_id")
    if char_id:
        try:
            char = db.query(Character).filter(
                Character.id == int(char_id),
            ).first()
        except Exception:
            char = None
        if char:
            return _speed_walk_from_sheet(char.sheet)
    tmpl_id = combatant.get("token_template_id")
    if tmpl_id:
        try:
            tmpl = db.query(TokenTemplate).filter(
                TokenTemplate.id == int(tmpl_id),
            ).first()
        except Exception:
            tmpl = None
        if tmpl:
            projected = _monster_template_to_sheet(tmpl, campaign_id)
            return _speed_walk_from_sheet(projected)
    return 30


# v2.99.98 — leaf-module re-exports so existing call sites that
# already imported these from tabletop_routes keep working without
# a refactor. The pure helpers live in app/content/effective_speed.py
# so the in-process unit tests can import without pulling in fastapi.
from app.content.effective_speed import (
    effective_speed_reduction_ft as _effective_speed_reduction_ft,
    effective_speed_walk as _effective_speed_walk,
)
from app.content.lair_actions import (
    lair_action_by_id as _lair_action_by_id,
    lair_actions_for_slug as _lair_actions_for_slug,
)
from app.content.regional_effects import (
    regional_effects_for_slug as _regional_effects_for_slug,
)


def _combatant_oa_blocked_against(combatant: dict, mover_char_id: int) -> bool:
    """v2.158.38 — Phase 2 read gate for the v2.148.0 Fancy Footwork
    mark (Swashbuckler Rogue Lv 3+, XGE p.47): "if you make a melee
    attack against a creature, that creature can't make opportunity
    attacks against you for the rest of your turn."

    Returns True when this watcher carries an active
    `fancy-footwork-blocked` buff whose
    `effects.fancy_footwork_blocked_against_char_id` equals the moving
    swashbuckler's char_id — in which case the OA trigger is suppressed.
    """
    if not mover_char_id:
        return False
    for b in (combatant.get("buffs") or []):
        if not isinstance(b, dict):
            continue
        if (str(b.get("key") or "").strip().lower() != "fancy-footwork-blocked"):
            continue
        eff = b.get("effects") or {}
        if not isinstance(eff, dict):
            continue
        try:
            if int(eff.get("fancy_footwork_blocked_against_char_id") or 0) == int(mover_char_id):
                return True
        except (TypeError, ValueError):
            continue
    return False


def _check_opportunity_attack_triggers(
    db: Session, campaign_id: int,
    mover_token_id: int,
    from_x: float, from_y: float,
    to_x: float, to_y: float,
) -> list[dict]:
    """Returns a list of provoked-OA dicts, one per watcher that:
      - is in the active battle's init tracker,
      - has a token on the active map (other than the mover),
      - was within 5 ft of from_pos AND beyond 5 ft of to_pos,
      - has their reaction available (economy.reaction is False).

    Each entry: {watcher_combatant_id, watcher_name, watcher_char_id,
    watcher_color, watcher_token_id}. Returns empty list when there's
    no active battle, no active map, or no qualifying watchers.
    """
    state = hub.get_battle(campaign_id)
    if not state:
        return []
    combatants = state.get("combatants") or []
    if not combatants:
        return []
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not campaign.active_map_id:
        return []
    map_row = db.query(Map).filter(Map.id == campaign.active_map_id).first()
    if not map_row or not map_row.grid_size_px:
        return []
    grid_type = (
        map_row.grid_type.value if map_row.grid_type else "square"
    ).lower()
    grid_size_px = int(map_row.grid_size_px)
    # v2.99.52 — plan-movement-oa-flow Phase 1 same-team filter.
    # Pull the mover's team once. RAW: OA fires from a "hostile
    # creature." When BOTH mover and watcher are non-neutral AND
    # share the same team, skip the trigger. Neutral on either
    # side leaves the existing behavior intact (back-compat for
    # campaigns that haven't tagged tokens yet).
    mover_token_row = db.query(Token).filter(
        Token.id == int(mover_token_id),
    ).first()
    mover_team = (
        (mover_token_row.team or "neutral").strip().lower()
        if mover_token_row else "neutral"
    )
    # v2.158.38 — Fancy Footwork (Swashbuckler Rogue Lv 3+). The mover's
    # char_id keys the `fancy-footwork-blocked` OA-suppression read below.
    mover_char_id = (
        int(mover_token_row.character_id)
        if mover_token_row and mover_token_row.character_id
        else None
    )
    triggers: list[dict] = []
    for c in combatants:
        # Reaction already spent? Skip — OA needs reaction.
        economy = c.get("economy") or {}
        if bool(economy.get("reaction")):
            continue
        # Find the watcher's token on the active map.
        watcher_token = None
        src_token_id = c.get("source_token_id")
        if src_token_id:
            watcher_token = db.query(Token).filter(
                Token.id == int(src_token_id),
                Token.map_id == map_row.id,
            ).first()
        if watcher_token is None and c.get("char_id"):
            watcher_token = db.query(Token).filter(
                Token.character_id == int(c["char_id"]),
                Token.map_id == map_row.id,
            ).first()
        # v2.99.62 — NPC watcher fallback. The demo's seed_encounter
        # (and most encounter saves) only carries ``token_template_id``
        # + ``name`` on NPC combatants — no ``source_token_id``. After
        # encounter Load the OLD Token rows are deleted and NEW ones
        # created with fresh ids; the combatants list still references
        # the old ids OR carries no link at all. The two lookups above
        # both fail for NPCs (no source_token_id, no char_id), so the
        # NPC watcher was silently skipped — no OA fired when a hero
        # walked past a bandit. The fallback matches by
        # token_template_id + label on the active map; for typical
        # encounters (unique NPC names) this resolves cleanly. For
        # duplicate-name NPCs (rare) the first match wins; a future
        # ship could add position-tiebreaking.
        if watcher_token is None and c.get("token_template_id") and c.get("name"):
            watcher_token = db.query(Token).filter(
                Token.token_template_id == int(c["token_template_id"]),
                Token.label == c["name"],
                Token.map_id == map_row.id,
            ).first()
        if watcher_token is None:
            continue
        if int(watcher_token.id) == int(mover_token_id):
            continue
        # v2.99.52 — same-team filter. Watcher's team comes from the
        # Token row (single source of truth); combatant dict's
        # ``team`` field (if present) is the cached version mirrored
        # by token_update broadcasts. Pull from the Token row to
        # avoid stale cache. Skip when both non-neutral AND equal.
        watcher_team = (watcher_token.team or "neutral").strip().lower()
        if (
            mover_team != "neutral"
            and watcher_team != "neutral"
            and mover_team == watcher_team
        ):
            continue
        # v2.158.38 — Fancy Footwork read site. If this watcher was
        # marked by the moving swashbuckler's earlier melee attack
        # (`fancy-footwork-blocked` buff naming the mover's char_id),
        # they can't make OAs against the swashbuckler this turn — skip.
        if _combatant_oa_blocked_against(c, mover_char_id):
            continue
        wx = float(watcher_token.x or 0)
        wy = float(watcher_token.y or 0)
        dist_from = _distance_ft_between_points(
            grid_size_px, grid_type, wx, wy, from_x, from_y,
        )
        dist_to = _distance_ft_between_points(
            grid_size_px, grid_type, wx, wy, to_x, to_y,
        )
        reach_ft = _combatant_melee_reach_ft(db, c)
        # Exit-reach transition (standard OA, every watcher).
        if dist_from <= reach_ft and dist_to > reach_ft:
            triggers.append({
                "watcher_combatant_id": c.get("id"),
                "watcher_name": c.get("name") or "Combatant",
                "watcher_char_id": c.get("char_id"),
                "watcher_color": c.get("color"),
                "watcher_token_id": int(watcher_token.id),
                "watcher_reach_ft": reach_ft,
                "dist_from_ft": dist_from,
                "dist_to_ft": dist_to,
                "trigger_type": "exit",
            })
            continue
        # v2.99.60 — path-aware OA. RAW (PHB p.195): "An opportunity
        # attack interrupts the provoking creature's movement,
        # occurring right before the creature leaves your reach."
        # Pre-v2.99.60 the helper only checked endpoints (was_in,
        # is_in) — a mover that started OUT of reach, walked
        # THROUGH the threat circle, and ended OUT was invisible to
        # the OA path even though RAW says it provokes on the exit
        # step. v2.99.60 closes the gap: if both endpoints are
        # outside reach AND the move segment passes within
        # reach_ft of the watcher, fire OA at the (computed) exit
        # point.
        if dist_from > reach_ft and dist_to > reach_ft:
            seg_min_ft = _segment_to_point_min_ft(
                grid_size_px, from_x, from_y, to_x, to_y, wx, wy,
            )
            if seg_min_ft <= reach_ft:
                triggers.append({
                    "watcher_combatant_id": c.get("id"),
                    "watcher_name": c.get("name") or "Combatant",
                    "watcher_char_id": c.get("char_id"),
                    "watcher_color": c.get("color"),
                    "watcher_token_id": int(watcher_token.id),
                    "watcher_reach_ft": reach_ft,
                    "dist_from_ft": dist_from,
                    "dist_to_ft": dist_to,
                    # Distinguish path-cross OAs in the trigger
                    # data so future telemetry / chat-card copy can
                    # explain why the OA fired despite both
                    # endpoints being outside reach.
                    "trigger_type": "exit",
                    "path_crossed_ft": seg_min_ft,
                })
                continue
        # v2.66.4 — Polearm Master enter-reach OA. Fires when a
        # creature ENTERS the watcher's reach (the inverse of the
        # exit transition). Only watchers with the Polearm Master
        # feat trigger this; standard combatants don't get OA on
        # entry. The watcher's reach is still per-combatant.
        if dist_from > reach_ft and dist_to <= reach_ft:
            if _combatant_has_polearm_master(db, c):
                triggers.append({
                    "watcher_combatant_id": c.get("id"),
                    "watcher_name": c.get("name") or "Combatant",
                    "watcher_char_id": c.get("char_id"),
                    "watcher_color": c.get("color"),
                    "watcher_token_id": int(watcher_token.id),
                    "watcher_reach_ft": reach_ft,
                    "dist_from_ft": dist_from,
                    "dist_to_ft": dist_to,
                    "trigger_type": "enter",
                })
    return triggers


# ── v2.67.0 — Reactions automation foundation (Phase 1) ──
#
# docs/plans/reactions-automation.md spec, server-side foundation:
#
#   - ``_active_reaction_prompts`` — in-memory dict of ``prompt_id``
#     → ``{...}`` entries with TTL. Replay-attack guard: only
#     prompts in this dict can be resolved by ``/use_reaction``;
#     each prompt is single-use.
#   - ``_eligible_reactions(db, campaign_id, watcher_char_id,
#     trigger_event, context)`` — returns a list of option dicts
#     for the prompt's catalog. Phase 1 ships only the
#     ``creature_exits_reach`` event with a single ``take-the-oa``
#     option; subsequent phases add more events + reactions.
#   - ``_emit_reaction_prompt(campaign_id, watcher_combatant,
#     trigger_event, summary, options, target_user_ids)`` async —
#     registers the prompt in ``_active_reaction_prompts`` and
#     broadcasts a ``reaction_prompt`` WS event.
#   - ``/use_reaction`` endpoint — single dispatch entry point.
#     Validates the prompt_id against the in-memory store, marks
#     the reaction slot, dispatches to the reaction's handler (Phase
#     1 only handles ``take-the-oa`` — just consumes the slot +
#     broadcasts ``reaction_prompt_resolved`` for the client to
#     dismiss the popup; the player still clicks Attack manually).
#
# Phase 1 deliberately does NOT include the client popup UI or the
# settings UI toggle — those land in Phase 1b. The DB column +
# server-side broadcast shape is the foundation everything else
# builds on.
import time as _time_mod
import uuid as _uuid_mod

# In-memory prompt registry. Format: ``{prompt_id: entry_dict}``
# where entry_dict has campaign_id / created_at / expires_at /
# watcher_char_id / trigger_event / options / resolved (bool). TTL
# enforced lazily on lookup; expired entries are dropped at the next
# read. Mirrors the v2.65.0 ``_attack_damage_log`` shape.
_active_reaction_prompts: dict[str, dict] = {}
_REACTION_PROMPT_TTL_S = 600  # 10 minutes


def _purge_active_reaction_prompts() -> None:
    """Drop expired prompts. Called inside every read/write path so
    the in-memory dict can't grow unboundedly. TTL is 10 minutes —
    well past any realistic player decision window but short enough
    to avoid memory leaks on long-running campaigns."""
    now = _time_mod.time()
    expired = [
        pid for pid, entry in _active_reaction_prompts.items()
        if float(entry.get("expires_at", 0)) <= now
    ]
    for pid in expired:
        _active_reaction_prompts.pop(pid, None)


# v2.69.0 Phase 3a — Shield spell eligibility helper.
#
# Returns ``(eligible, class_slug, slot_level)`` where:
#   - eligible: True when the PC has Shield in their spell list AND a
#     1st-level (or higher) slot available, AND their combatant's
#     reaction slot is unused. False otherwise.
#   - class_slug: the spellcasting class to debit (lowercase). Picks
#     the FIRST class found that has Shield + an available slot;
#     multi-class PCs are handled by iteration order.
#   - slot_level: the lowest slot level >= 1 that has remaining uses.
#
# Caller (the `_eligible_reactions[attack_targeted]` branch) uses
# (class_slug, slot_level) as params for the ``cast-shield`` option's
# dispatch in ``/use_reaction``.
def _pc_has_shield_available(char) -> "tuple[bool, str, int]":
    """Detect Shield (1st-level reaction spell) eligibility on a PC."""
    if not char or not char.sheet:
        return False, "", 0
    sheet = char.sheet or {}
    # Walk spells; need at least one entry with slug "shield" or name
    # "Shield" AND casting_time mentioning "reaction".
    has_shield = False
    for sp in (sheet.get("spells") or []):
        if not isinstance(sp, dict):
            continue
        slug = (sp.get("_slug") or "").strip().lower()
        name = (sp.get("name") or "").strip().lower()
        ct = (sp.get("casting_time") or "").lower()
        if (slug == "shield" or name == "shield") and "reaction" in ct:
            has_shield = True
            break
    if not has_shield:
        return False, "", 0
    # Find the lowest available 1st+ slot across the PC's classes.
    all_slots = sheet.get("spell_slots") or {}
    best_class = ""
    best_lv = 0
    for cslug, per_class in (all_slots or {}).items():
        if not isinstance(per_class, dict):
            continue
        for lv_key, slot in per_class.items():
            if not isinstance(slot, dict):
                continue
            try:
                lv = int(lv_key)
            except (TypeError, ValueError):
                continue
            if lv < 1:
                continue
            total = int(slot.get("total") or 0)
            used = int(slot.get("used") or 0)
            if total <= 0 or used >= total:
                continue
            # Prefer the lowest available level (don't burn higher
            # slots when a 1st will do).
            if best_lv == 0 or lv < best_lv:
                best_lv = lv
                best_class = str(cslug).strip().lower()
    if best_lv == 0:
        return False, "", 0
    return True, best_class, best_lv


# v2.74.0 Phase 4a — Defensive Duelist. RAW (PHB p.166): "When you
# are wielding a finesse weapon with which you are proficient and
# another creature hits you with a melee attack, you can use your
# reaction to add your proficiency bonus to your AC for that attack,
# potentially causing the attack to miss you." Returns (eligible,
# proficiency_bonus). The PC must:
#   - have the "defensive-duelist" feat in sheet.feats
#   - have at least one equipped weapon whose ``properties`` string
#     contains "finesse" (case-insensitive substring match — covers
#     "finesse, light", "finesse", "finesse, light, thrown", etc.)
# Reaction-slot availability is checked by the caller via the
# combatant's economy dict before _eligible_reactions runs.
def _pc_has_defensive_duelist_available(char) -> "tuple[bool, int]":
    """Detect Defensive Duelist feat eligibility on a PC."""
    if not char or not char.sheet:
        return False, 0
    sheet = char.sheet or {}
    has_feat = False
    for f in (sheet.get("feats") or []):
        if not isinstance(f, dict):
            continue
        slug = (f.get("slug") or "").strip().lower()
        name = (f.get("name") or "").strip().lower().replace(" ", "-")
        if slug == "defensive-duelist" or name == "defensive-duelist":
            has_feat = True
            break
    if not has_feat:
        return False, 0
    # Walk inventory for an equipped finesse weapon.
    has_finesse = False
    for it in (sheet.get("inventory") or []):
        if not isinstance(it, dict):
            continue
        if not it.get("equipped"):
            continue
        if (it.get("type") or "").strip().lower() != "weapon":
            continue
        props = (it.get("properties") or "").lower()
        if "finesse" in props:
            has_finesse = True
            break
    if not has_finesse:
        return False, 0
    pb = int(sheet.get("proficiency_bonus") or 2)
    return True, pb


# v2.80.0 — Detect "other attack_targeted reactions eligible for this
# PC" so the v2.49.243 Uncanny Dodge auto-fire path can SUPPRESS
# itself when the player has alternatives (Defensive Duelist, Shield,
# Lucky, item reactions). Without this, UD's auto-consume eats the
# reaction slot before the v2.69.0 attack_targeted prompt can offer
# the alternatives — closes the Pip-vs-DD interaction footgun filed
# in v2.74.0.
#
# Auto-fire still kicks in when the PC has UD as their ONLY
# attack_targeted reaction (the common case — vanilla Rogue 5+ with
# no feats). Existing tests in test_use_attack_uncanny_dodge.py
# continue to pass for Pip's default sheet (no DD/Shield/Lucky/item
# reactions on him).
def _pc_has_valor_bi_buff(
    db: Session, campaign_id: int, character_id: int,
) -> dict | None:
    """v2.158.68 — Walk the PC's live combatant buffs for a
    `bardic-inspiration-die` whose `source_char_id` is a Valor
    College Bard Lv 3+. Returns the buff dict (carrying
    `effects.bardic_inspiration_die` + `source_char_id`) so callers
    can read the die expression without re-walking; returns None
    when none is found (no active battle, target not in init, no BI
    buff, or the granting bard isn't Valor 3+). Drives the Combat
    Inspiration Phase 3 integration (option surfacing in
    `_eligible_reactions` + UD-auto-fire suppression in
    `_apply_damage_to_combatant` + dispatch eligibility in
    `/use_reaction`).
    """
    try:
        for b in (_get_buffs(campaign_id, int(character_id)) or []):
            if not isinstance(b, dict):
                continue
            if b.get("key") != "bardic-inspiration-die":
                continue
            src_id = b.get("source_char_id")
            if not src_id:
                continue
            src_char = db.query(Character).filter(
                Character.id == int(src_id),
            ).first()
            if not src_char or not src_char.sheet:
                continue
            if _pc_has_valor_bard(src_char.sheet, 3):
                return b
    except Exception:
        return None
    return None


def _pc_has_other_attack_targeted_reactions(
    char, *,
    db: "Session | None" = None,
    campaign_id: "int | None" = None,
) -> bool:
    """Returns True when the PC has at least one attack_targeted
    reaction eligible OTHER than Uncanny Dodge. Used to gate UD's
    auto-fire suppression so the player can pick from the prompt
    instead of having UD silently consume the reaction.

    v2.158.68 — accepts optional `db` + `campaign_id` so callers
    inside an active-battle context can also flag a Valor-Bard-
    sourced `bardic-inspiration-die` buff as an "other" reaction.
    Without those kwargs the BI check is skipped — backward-
    compatible with any caller that didn't plumb the battle state.
    """
    if not char or not char.sheet:
        return False
    if _pc_has_shield_available(char)[0]:
        return True
    if _pc_has_defensive_duelist_available(char)[0]:
        return True
    if _pc_has_lucky_available(char)[0]:
        return True
    if _pc_item_reactions_for_trigger(char, "attack_targeted"):
        return True
    # v2.158.68 — Combat Inspiration AC reaction. Only checked when
    # the caller plumbed db + campaign_id (both `_eligible_reactions`
    # and `_apply_damage_to_combatant` do, as of this commit).
    if db is not None and campaign_id is not None:
        if _pc_has_valor_bi_buff(db, int(campaign_id), int(char.id)):
            return True
    return False


# v2.78.0 Phase 5 — Item reactions. Generic catalog mechanism that
# lets equipped inventory items declare reaction options. Items in
# sheet.inventory[*] with `equipped: True` AND a `_reactions: [...]`
# array contribute one option per entry to `_eligible_reactions`.
# Each entry shape: {"key": str, "trigger": str, "label": str,
# "desc": str, "kind": str, "cost": str}.
#
# v1 ships with a single demo item (Cloak of Displacement on Lyra)
# whose entry binds to `trigger=attack_targeted`. The framework
# scales: any SRD/homebrew item with reaction text can add a
# `_reactions` array without further code changes — the catalog walk
# + dispatch is generic.
#
# Per-item state (charges, daily uses, etc.) is left to the item's
# `_reactions[*].cost` field for v1 (informational only). Charge
# tracking parallel to Lucky (v2.77.0) is filed for individual items
# that need it (Pearl of Power, Wand of Lightning Bolts, etc.).
def _pc_item_reactions_for_trigger(char, trigger: str) -> list[dict]:
    """Return the list of item-derived reaction option dicts a PC has
    for the given ``trigger`` event. Walks equipped inventory items
    only — unequipped reaction items don't fire.
    """
    if not char or not char.sheet:
        return []
    out: list[dict] = []
    for it in (char.sheet.get("inventory") or []):
        if not isinstance(it, dict):
            continue
        if not it.get("equipped"):
            continue
        for rx in (it.get("_reactions") or []):
            if not isinstance(rx, dict):
                continue
            if (rx.get("trigger") or "").strip().lower() != trigger.lower():
                continue
            key = (rx.get("key") or "").strip()
            if not key:
                continue
            out.append({
                "key": key,
                "label": rx.get("label") or f"Item reaction: {it.get('name') or 'Item'}",
                "kind": rx.get("kind") or "item",
                "resource_cost": rx.get("cost") or "Reaction",
                "params": {
                    "item_name": it.get("name") or "",
                    "item_slug": (it.get("_slug") or "").strip(),
                    "desc": (rx.get("desc") or "")[:200],
                },
                "available": True,
                "unavailable_reason": None,
            })
    return out


# v2.77.0 Phase 4b — Lucky feat. RAW (PHB p.167): "You have 3 luck
# points. Whenever you make an attack roll, an ability check, or a
# saving throw, you can spend one luck point to roll an additional
# d20... You can also spend one luck point when an attack roll is
# made against you. Roll a d20 and then choose whether the attack
# uses the attacker's roll or yours."
#
# v1 scope: ship the "attack roll made against you" trigger only.
# The own-roll surfaces (your attack/check/save) need new trigger
# events (attack_resolved + check_resolved) and a "roll modifier
# pending" state that v2.72.0 Silvery Barbs already partly models
# but hasn't generalized. Filed: extend to all four surfaces.
#
# Returns (eligible, charges_remaining). The watcher must:
#   - have the "lucky" feat in sheet.feats
#   - have at least 1 charge remaining in sheet.resources entry
#     keyed "lucky" (current > 0)
def _pc_has_lucky_available(char) -> "tuple[bool, int]":
    """Detect Lucky feat eligibility + remaining charges on a PC."""
    if not char or not char.sheet:
        return False, 0
    sheet = char.sheet or {}
    has_feat = False
    for f in (sheet.get("feats") or []):
        if not isinstance(f, dict):
            continue
        slug = (f.get("slug") or "").strip().lower()
        name = (f.get("name") or "").strip().lower()
        if slug == "lucky" or name == "lucky":
            has_feat = True
            break
    if not has_feat:
        return False, 0
    for r in (sheet.get("resources") or []):
        if not isinstance(r, dict):
            continue
        key = (r.get("key") or "").strip().lower()
        if key != "lucky":
            continue
        try:
            cur = int(r.get("current") or 0)
        except (TypeError, ValueError):
            cur = 0
        if cur > 0:
            return True, cur
        return False, 0
    return False, 0


# v2.105.0 — reroll framework. A registry of "spend a resource to
# reroll a d20" features, surfaced as button(s) on the roll-log card
# and resolved by the generic POST /use_reroll endpoint. Each entry:
#   key          — stable id (sent by the client + endpoint)
#   label / icon — button + chat-card text
#   resource_key — sheet.resources[].key to decrement on use
#   keep         — "better" (Lucky: keep the higher of old/new d20) or
#                  "new" (must use the new roll — Indomitable / Diamond
#                  Soul, folded in during Phase 3)
#   applies      — "any" (attack / check / save) or "save" (saves only)
#   detect       — (char) -> (eligible: bool, remaining: int)
#   desc         — short description for the feature_used audit card
# Phase 1 (v2.105.0) registers the Lucky feat; the save-only entries
# join in Phase 3 (they currently ship their own reroll endpoints).
def _reroll_detect_lucky(char):
    """(has_feature, remaining) for the Lucky feat. ``has_feature``
    ignores remaining uses so the client can GREY the button at 0 uses
    (vs hiding it entirely when the char has no such feat); the
    /use_reroll endpoint enforces ``remaining > 0``."""
    if not char or not char.sheet:
        return False, 0
    sheet = char.sheet or {}
    has_feat = any(
        isinstance(f, dict) and (
            (f.get("slug") or "").strip().lower() == "lucky"
            or (f.get("name") or "").strip().lower() == "lucky"
        )
        for f in (sheet.get("feats") or [])
    )
    if not has_feat:
        return False, 0
    remaining = 0
    for r in (sheet.get("resources") or []):
        if isinstance(r, dict) and (r.get("key") or "").strip().lower() == "lucky":
            try:
                remaining = int(r.get("current") or 0)
            except (TypeError, ValueError):
                remaining = 0
            break
    return True, remaining


def _reroll_resource_current(char, key) -> int:
    """Current uses of a sheet resource by key (0 if missing)."""
    for r in ((char.sheet or {}).get("resources") or []):
        if isinstance(r, dict) and (r.get("key") or "").strip().lower() == key:
            try:
                return int(r.get("current") or 0)
            except (TypeError, ValueError):
                return 0
    return 0


def _reroll_detect_indomitable(char):
    """(has_feature, remaining) for Fighter Indomitable (Lv 9+). RAW:
    reroll a failed save and use the new roll. Save-only."""
    if not char or not char.sheet:
        return False, 0
    if _fighter_level_from_sheet(char.sheet or {}) < 9:
        return False, 0
    return True, _reroll_resource_current(char, "indomitable")


def _reroll_detect_diamond_soul(char):
    """(has_feature, remaining) for Monk Diamond Soul (Lv 14+). RAW:
    spend 1 ki to reroll a failed save and use the new roll. Save-only."""
    if not char or not char.sheet:
        return False, 0
    if _monk_level_from_sheet(char.sheet or {}) < 14:
        return False, 0
    return True, _reroll_resource_current(char, "ki-points")


_REROLL_FEATURES = [
    {
        "key": "lucky",
        "label": "Lucky",
        "icon": "🍀",
        "resource_key": "lucky",
        "keep": "better",
        "applies": "any",
        "detect": _reroll_detect_lucky,
        "desc": "Roll a new d20 and keep the higher (Lucky feat, PHB p.167).",
    },
    {
        "key": "indomitable",
        "label": "Indomitable",
        "icon": "🛡️",
        "resource_key": "indomitable",
        "keep": "new",
        "applies": "save",
        "detect": _reroll_detect_indomitable,
        "desc": "Reroll a failed save and use the new roll (Fighter Lv 9+).",
    },
    {
        "key": "diamond-soul",
        "label": "Diamond Soul",
        "icon": "💎",
        "resource_key": "ki-points",
        "keep": "new",
        "applies": "save",
        "detect": _reroll_detect_diamond_soul,
        "desc": "Spend 1 ki to reroll a failed save (Monk Lv 14+).",
    },
]


def _reroll_feature(key):
    """Look up a reroll-feature descriptor by key, or None."""
    for f in _REROLL_FEATURES:
        if f["key"] == key:
            return f
    return None


def _max_dice_total(expr: str) -> tuple[int, str]:
    """v2.143.0 — Supreme Healing (Life Domain Cleric Lv 17+, PHB
    p.61): "when you would normally roll one or more dice to restore
    hit points with a spell, you instead use the highest number
    possible for each die." Returns ``(total, breakdown)`` for a dice
    expression with each ``NdM`` term replaced by its max value
    (``N × M``). Handles flat modifiers and mixed terms ("1d8+3" →
    (8+3, "1d8[max:8] +3 => 11"); "2d4+1d6" → (8+6, …)).

    Returns ``(0, "")`` on a missing / unparseable expression so the
    caller can fall back to a normal roll cleanly. Used by the
    /cast_spell heal pipeline when the caster passes
    `_pc_has_life_domain(sheet, 17)`.
    """
    expr = (expr or "").strip()
    if not expr:
        return 0, ""
    total = 0
    parts: list[str] = []
    for m in _re.finditer(r"([-+])?\s*(\d+d\d+|\d+)", expr):
        sign_str = m.group(1) or "+"
        sign = -1 if sign_str == "-" else 1
        term = m.group(2)
        md = _re.match(r"^(\d+)d(\d+)$", term)
        if md:
            n = int(md.group(1))
            d = int(md.group(2))
            v = n * d
            total += sign * v
            parts.append(f"{'-' if sign < 0 else '+'}{n}d{d}[max:{v}]")
        else:
            v = int(term)
            total += sign * v
            parts.append(f"{'-' if sign < 0 else '+'}{v}")
    if not parts:
        return 0, ""
    # Strip the leading + on the first term for a cleaner read.
    parts[0] = parts[0].lstrip("+")
    final = max(0, total)
    breakdown = " ".join(parts) + f"  =>  {final}"
    return final, breakdown


def _scale_dice_for_upcast(base_expr, per_slot_expr, extra_levels):
    """v2.110.0 — add ``extra_levels`` × ``per_slot_expr`` dice to
    ``base_expr``, merging same-die terms.

    '3d6' + 1×'1d6' → '4d6'; '1d8' + 1×'1d8' → '2d8'; '8d6' + 2×'1d6'
    → '10d6'. A different die size appends a new term ('1d10' + '1d6'
    → '1d10 + 1d6'). Returns ``base_expr`` unchanged when inputs are
    missing or unparseable (so a bad per-slot value can never corrupt
    the cast)."""
    base = (base_expr or "").strip()
    per = (per_slot_expr or "").strip()
    if not base or not per or (extra_levels or 0) <= 0:
        return base
    m_per = _re.match(r"^(\d+)d(\d+)$", per)
    if not m_per:
        return base
    add_n = int(m_per.group(1)) * int(extra_levels)
    per_die = int(m_per.group(2))
    m_base = _re.match(r"^(\d+)d(\d+)(.*)$", base)
    if m_base and int(m_base.group(2)) == per_die:
        return f"{int(m_base.group(1)) + add_n}d{per_die}{m_base.group(3)}"
    return f"{base} + {add_n}d{per_die}"




def _reroll_options_for_rolls(db, rolls):
    """v2.116.0 — map ``roll.id -> reroll_options`` for the rolling
    character across a list of DiceRolls, for the server-rendered roll
    history (tabletop + rolls popout). Batch-loads the characters once;
    only rolls with a kept d20 + an eligible feature appear."""
    char_ids = {r.character_id for r in rolls if r.character_id}
    chars = {}
    if char_ids:
        for c in db.query(Character).filter(Character.id.in_(char_ids)).all():
            chars[c.id] = c
    out: dict[int, list] = {}
    for r in rolls:
        c = chars.get(r.character_id) if r.character_id else None
        if c is None:
            continue
        opts = _compute_reroll_options(c, r.breakdown, None, r.note)
        if opts:
            out[r.id] = opts
    return out


def _roll_is_save(stat_key, note) -> bool:
    """Best-effort: is this roll a saving throw? Gates save-only reroll
    features (Indomitable / Diamond Soul). Conservative — only the
    save-only entries consult it, so a false negative just hides those
    buttons (Lucky, applies=any, is unaffected)."""
    sk = (stat_key or "").lower()
    if "save" in sk or "saving" in sk:
        return True
    n = (note or "").lower()
    return "saving throw" in n


def _compute_reroll_options(char, breakdown=None, stat_key=None, note=None):
    """Reroll features ``char`` could spend on a roll with this
    breakdown — used to decorate the /roll broadcast so the client can
    render reroll button(s). Empty when char is None, the roll has no
    kept d20 to reroll, or no feature is eligible."""
    if char is None:
        return []
    if (breakdown is not None
            and _extract_kept_d20_from_breakdown(breakdown) is None):
        return []
    is_save = _roll_is_save(stat_key, note)
    out = []
    for f in _REROLL_FEATURES:
        if f["applies"] == "save" and not is_save:
            continue
        try:
            eligible, remaining = f["detect"](char)
        except Exception:  # noqa: BLE001
            eligible, remaining = False, 0
        if not eligible:
            continue
        out.append({
            "key": f["key"], "label": f["label"], "icon": f["icon"],
            "keep": f["keep"], "remaining": int(remaining),
            "desc": f["desc"],
        })
    return out


# v2.76.0 Phase 4c — War Caster feat. RAW (PHB p.170) third
# benefit: "When a hostile creature's movement provokes an
# opportunity attack from you, you can use your reaction to cast a
# spell at the creature, rather than making an opportunity attack.
# The spell must have a casting time of 1 action and must target
# only that creature." The other two benefits (advantage on concen-
# tration saves when taking damage; somatic-while-holding-weapons)
# are filed.
#
# v1 simplification: surface the prompt when the watcher has the
# feat AND at least one prepared/known spell whose casting_time
# contains "1 action" (we don't enforce the "single creature" gate
# in v1 — caster picks the spell + GM adjudicates). Auto-cast
# resolution is filed alongside the v2.66.0 OA advisory pattern
# (player clicks Cast Spell instead of clicking Attack).
# v2.83.0 — War Caster passive feat detection (no spell-list gate).
# The reaction-trigger eligibility (`_pc_has_war_caster_available`,
# v2.76.0) gates on the PC having at least one 1-action spell ready,
# because the reaction's RAW effect is "cast a spell instead of the
# OA." The PASSIVE benefits (advantage + proficiency on concentration
# saves) trigger regardless of spell availability — they're feat-only.
# Hence this lighter detector.
def _pc_has_war_caster_feat(char) -> bool:
    """Detect just the War Caster feat — no spell-list check.

    Used by `_maybe_concentration_save` to apply the RAW passive
    benefits: advantage on Constitution saves to maintain concentration
    when you take damage, AND War Caster grants Constitution save
    proficiency for that specific roll even when the PC lacks it as a
    class feature.
    """
    if not char or not char.sheet:
        return False
    for f in (char.sheet.get("feats") or []):
        if not isinstance(f, dict):
            continue
        slug = (f.get("slug") or "").strip().lower()
        name = (f.get("name") or "").strip().lower().replace(" ", "-")
        if slug == "war-caster" or name == "war-caster":
            return True
    return False


def _pc_melee_attacks(char) -> list[tuple[int, dict]]:
    """v2.99.56 — plan-movement-oa-flow Phase 5 helper.

    Return ``[(attack_index, attack_dict), …]`` of the PC's melee
    attacks suitable for opportunity-attack picker options.

    Range detection: the sheet attack's ``range`` field is matched
    against a leading "<N> ft" prefix (no slash). Slashes ("20/60
    ft") mark thrown / ranged attacks even when they're nominally
    usable in melee — RAW treats them as ranged for the OA
    provoking-vs-being-provoked question. Anything with reach <= 15
    ft and no slash qualifies. Missing range → skipped (an attack
    without a declared range can't be safely classified as melee).
    """
    if not char or not char.sheet:
        return []
    out: list[tuple[int, dict]] = []
    for idx, a in enumerate(char.sheet.get("attacks") or []):
        if not isinstance(a, dict):
            continue
        rng = (a.get("range") or "").strip().lower()
        if not rng or "/" in rng:
            continue
        import re as _re
        m = _re.match(r"^(\d+(?:\.\d+)?)\s*ft", rng)
        if not m:
            continue
        try:
            reach = float(m.group(1))
        except (TypeError, ValueError):
            continue
        if reach <= 15.0:
            out.append((idx, a))
    return out


def _npc_melee_actions(
    db: Session, watcher_combatant: dict, campaign_id: int,
) -> list[tuple[int, dict]]:
    """v2.99.68 — NPC OA picker support. Parallel to
    ``_pc_melee_attacks`` but for NPC watchers — projects the
    monster template, walks ``sheet.actions``, and returns the
    melee-attack subset with their action index.

    Range detection: monster actions usually describe reach via
    desc text ("reach 5 ft.", "reach 10 ft."). The action's own
    ``range`` field may be empty. We extract the first reach
    distance from the desc when present, otherwise fall back to
    the action's range field, otherwise 5 ft (RAW default for
    standard humanoid melee). Anything > 15 ft is rejected as a
    ranged-or-special attack.

    Returns ``[(action_index, action_dict), ...]`` sized by the
    number of melee attack-roll actions on the template.
    """
    if not watcher_combatant:
        return []
    tmpl_id = watcher_combatant.get("token_template_id")
    if not tmpl_id:
        return []
    try:
        tmpl = db.query(TokenTemplate).filter(
            TokenTemplate.id == int(tmpl_id),
        ).first()
    except Exception:
        tmpl = None
    if not tmpl:
        return []
    sheet = _monster_template_to_sheet(tmpl, campaign_id)
    actions = sheet.get("actions") or []
    out: list[tuple[int, dict]] = []
    import re as _re
    for idx, a in enumerate(actions):
        if not isinstance(a, dict):
            continue
        # Must be an attack-roll action with damage. Skip pure save
        # actions (dragon breath) and pure narrative actions
        # (Multiattack). Skip reactions too — RAW: an OA itself
        # can't be a reaction-category action.
        atk_bonus = (a.get("attack_bonus") or "").strip()
        damage = (a.get("damage") or "").strip()
        if not atk_bonus or not damage:
            continue
        if (a.get("category") or "").strip().lower() == "reaction":
            continue
        # Reach: parse from desc first, then range field.
        reach = 5.0
        desc = (a.get("desc") or "")
        m = _re.search(r"reach\s+(\d+(?:\.\d+)?)\s*ft", desc, _re.IGNORECASE)
        if m:
            try:
                reach = float(m.group(1))
            except (TypeError, ValueError):
                reach = 5.0
        else:
            rng = (a.get("range") or "").strip().lower()
            if rng and "/" not in rng:
                m2 = _re.match(r"^(\d+(?:\.\d+)?)\s*ft", rng)
                if m2:
                    try:
                        reach = float(m2.group(1))
                    except (TypeError, ValueError):
                        reach = 5.0
        if reach <= 15.0:
            out.append((idx, a))
    return out


def _pc_has_war_caster_available(char) -> bool:
    """Detect War Caster feat + at-least-one-1-action-spell on a PC."""
    if not char or not char.sheet:
        return False
    sheet = char.sheet or {}
    has_feat = False
    for f in (sheet.get("feats") or []):
        if not isinstance(f, dict):
            continue
        slug = (f.get("slug") or "").strip().lower()
        name = (f.get("name") or "").strip().lower().replace(" ", "-")
        if slug == "war-caster" or name == "war-caster":
            has_feat = True
            break
    if not has_feat:
        return False
    for sp in (sheet.get("spells") or []):
        if not isinstance(sp, dict):
            continue
        ct = (sp.get("casting_time") or "").lower()
        if "1 action" in ct:
            return True
    return False


# v2.75.0 Phase 4d — Mage Slayer feat. RAW (PHB p.168): "When a
# creature within 5 feet of you casts a spell, you can use your
# reaction to make a melee weapon attack against that creature."
# Returns True when the PC has the feat AND at least one equipped
# melee weapon (any weapon without a "range" entry, OR with a range
# string mentioning "5 ft" for the melee component of a thrown
# weapon). v1 doesn't auto-resolve the attack — the chat-card
# surfaces the trigger + the player rolls the attack manually.
def _pc_has_mage_slayer_available(char) -> bool:
    """Detect Mage Slayer feat eligibility on a PC."""
    if not char or not char.sheet:
        return False
    sheet = char.sheet or {}
    has_feat = False
    for f in (sheet.get("feats") or []):
        if not isinstance(f, dict):
            continue
        slug = (f.get("slug") or "").strip().lower()
        name = (f.get("name") or "").strip().lower().replace(" ", "-")
        if slug == "mage-slayer" or name == "mage-slayer":
            has_feat = True
            break
    if not has_feat:
        return False
    # Walk inventory for an equipped melee weapon.
    for it in (sheet.get("inventory") or []):
        if not isinstance(it, dict):
            continue
        if not it.get("equipped"):
            continue
        if (it.get("type") or "").strip().lower() != "weapon":
            continue
        rng = (it.get("range") or "").strip().lower()
        # Pure melee weapons have no range or range == "5 ft".
        if not rng or "5 ft" in rng:
            return True
    return False


# v2.72.0 Phase 3d — Silvery Barbs. RAW (SAI / Strixhaven p.144):
# "1 reaction, which you take when a creature you can see within 60
# feet of yourself succeeds on an attack roll, an ability check, or
# a saving throw." 1st-level enchantment (Sorcerer / Wizard / Bard).
# Force the creature to reroll the d20 and use the lower; choose a
# different creature within 60 ft to gain advantage on its next
# attack/check/save within 1 minute.
#
# v1 stance: surface the option on save resolution (the most common
# table use). The dispatch consumes the slot + marks the reaction,
# but does NOT auto-roll the reroll — the GM/player re-rolls and
# applies the lower of the two as a manual adjudication. The
# secondary "ally gets advantage" buff is also filed for v3 pending-
# damage state machine (needs a buff with single-use trigger semantics
# the buff system doesn't yet model).
def _pc_has_silvery_barbs_available(char) -> "tuple[bool, str, int]":
    """Detect Silvery Barbs (1st-level reaction spell) eligibility on a PC."""
    if not char or not char.sheet:
        return False, "", 0
    sheet = char.sheet or {}
    has_sb = False
    for sp in (sheet.get("spells") or []):
        if not isinstance(sp, dict):
            continue
        slug = (sp.get("_slug") or "").strip().lower()
        name = (sp.get("name") or "").strip().lower()
        ct = (sp.get("casting_time") or "").lower()
        if (slug == "silvery-barbs" or name == "silvery barbs") and "reaction" in ct:
            has_sb = True
            break
    if not has_sb:
        return False, "", 0
    all_slots = sheet.get("spell_slots") or {}
    best_class = ""
    best_lv = 0
    for cslug, per_class in (all_slots or {}).items():
        if not isinstance(per_class, dict):
            continue
        for lv_key, slot in per_class.items():
            if not isinstance(slot, dict):
                continue
            try:
                lv = int(lv_key)
            except (TypeError, ValueError):
                continue
            if lv < 1:
                continue
            total = int(slot.get("total") or 0)
            used = int(slot.get("used") or 0)
            if total <= 0 or used >= total:
                continue
            if best_lv == 0 or lv < best_lv:
                best_lv = lv
                best_class = str(cslug).strip().lower()
    if best_lv == 0:
        return False, "", 0
    return True, best_class, best_lv


