def _safe_int(v, default=0) -> int:
    try:
        return int(v)
    except (TypeError, ValueError):
        return default


def _safe_str(v, max_len: int = 500) -> str:
    s = str(v or "").strip()
    return s[:max_len]


@router.post("/api/campaign/{campaign_id}/homebrew/import")
async def import_homebrew(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Bulk-import homebrew rows from a JSON pack (matching the
    ``/homebrew/export`` shape).

    Rows whose slug already exists in this campaign are silently skipped
    so re-importing a pack you've already pulled in is a no-op. Each
    content type is processed independently — a malformed entry in one
    list doesn't kill the rest of the import. Returns per-type counts of
    ``created`` / ``skipped`` / ``errors`` so the GM can see what landed.
    """
    _require_gm_for_campaign(campaign_id, user, db)
    body = await request.json()
    if not isinstance(body, dict):
        raise HTTPException(400, "Expected a JSON object — the export format root.")
    if body.get("format") and body["format"] != "simplevtt-homebrew":
        raise HTTPException(400, "Wrong format — expected ``simplevtt-homebrew``.")
    if body.get("version") and int(body.get("version", 0)) > HOMEBREW_EXPORT_VERSION:
        raise HTTPException(400, f"Pack version {body.get('version')} is newer than this server supports ({HOMEBREW_EXPORT_VERSION}). Upgrade first.")

    stats: dict[str, dict] = {
        k: {"created": 0, "skipped": 0, "errors": 0}
        for k in ("classes", "subclasses", "races", "monsters", "backgrounds", "feats")
    }

    def _existing_class(slug: str) -> bool:
        hit = local_content.resolve(slug, type="class_features", campaign_id=campaign_id)
        return bool(hit and hit[1] == "local-homebrew")

    def _existing_subclass(class_slug: str, sub_slug: str) -> bool:
        combined = f"{class_slug}__{sub_slug}"
        hit = local_content.resolve(combined, type="subclass_features", campaign_id=campaign_id)
        return bool(hit and hit[1] == "local-homebrew")

    def _existing_race(slug: str) -> bool:
        hit = local_content.resolve(slug, type="races", campaign_id=campaign_id)
        return bool(hit and hit[1] == "local-homebrew")

    def _existing_monster(slug: str) -> bool:
        hit = local_content.resolve(slug, type="monsters", campaign_id=campaign_id)
        return bool(hit and hit[1] == "local-homebrew")

    def _existing_background(slug: str) -> bool:
        hit = local_content.resolve(slug, type="backgrounds", campaign_id=campaign_id)
        return bool(hit and hit[1] == "local-homebrew")

    def _existing_feat(slug: str) -> bool:
        # v2.0.0: file-based homebrew tier. resolve() returns the highest-
        # priority hit including shipped SRD; we only want to mark "already
        # exists" if the campaign's own homebrew file claims the slug.
        hit = local_content.resolve(slug, type="feats", campaign_id=campaign_id)
        return bool(hit and hit[1] == "local-homebrew")

    # ── Classes ─────────────────────────────────────────────────────────
    for row in (body.get("classes") or [])[:200]:
        if not isinstance(row, dict):
            stats["classes"]["errors"] += 1
            continue
        try:
            name = _safe_str(row.get("name"), 120)
            slug = _slugify_for_subclass(name, max_len=60) or _safe_str(row.get("class_slug"), 60)
            if not name or not slug:
                stats["classes"]["errors"] += 1
                continue
            if _existing_class(slug):
                stats["classes"]["skipped"] += 1
                continue
            local_content.write_homebrew(
                {
                    "slug": slug,
                    "name": name,
                    "hit_die": _safe_int(row.get("hit_die"), 8),
                    "prof_armor": _safe_str(row.get("prof_armor"), 500),
                    "prof_weapons": _safe_str(row.get("prof_weapons"), 500),
                    "prof_tools": _safe_str(row.get("prof_tools"), 500),
                    "prof_saving_throws": _safe_str(row.get("prof_saving_throws"), 120),
                    "prof_skills": _safe_str(row.get("prof_skills"), 500),
                    "spellcasting_ability": _safe_str(row.get("spellcasting_ability"), 10).lower(),
                    "equipment": _safe_str(row.get("equipment"), 4000),
                    "features": row.get("features") if isinstance(row.get("features"), list) else [],
                    "spell_list": row.get("spell_list") if isinstance(row.get("spell_list"), list) else [],
                    "multiclass_prereq_abilities": row.get("multiclass_prereq_abilities") if isinstance(row.get("multiclass_prereq_abilities"), dict) else {},
                    "multiclass_prereq_mode": _safe_str(row.get("multiclass_prereq_mode") or "all", 8),
                    "multiclass_proficiencies": _safe_str(row.get("multiclass_proficiencies"), 500),
                    "resources": row.get("resources") if isinstance(row.get("resources"), list) else [],
                    "actions": [],
                    "system": "dnd5e",
                    "scope": f"campaign-{campaign_id}",
                    "source": "homebrew",
                    "owner": user.id,
                },
                type="class_features",
                scope=f"campaign-{campaign_id}",
            )
            stats["classes"]["created"] += 1
        except Exception:
            stats["classes"]["errors"] += 1

    # ── Subclasses ──────────────────────────────────────────────────────
    for row in (body.get("subclasses") or [])[:500]:
        if not isinstance(row, dict):
            stats["subclasses"]["errors"] += 1
            continue
        try:
            name = _safe_str(row.get("name"), 120)
            class_slug = _slugify_for_subclass(_safe_str(row.get("class_slug"), 60), max_len=60)
            sub_slug = _slugify_for_subclass(name, max_len=80) or _safe_str(row.get("sub_slug"), 80)
            if not name or not class_slug or not sub_slug:
                stats["subclasses"]["errors"] += 1
                continue
            if _existing_subclass(class_slug, sub_slug):
                stats["subclasses"]["skipped"] += 1
                continue
            local_content.write_homebrew(
                {
                    "slug": f"{class_slug}__{sub_slug}",
                    "name": name,
                    "class_slug": class_slug,
                    "subclass_flavor": _safe_str(row.get("flavor"), 4000),
                    "features": row.get("features") if isinstance(row.get("features"), list) else [],
                    "actions": [],
                    "system": "dnd5e",
                    "scope": f"campaign-{campaign_id}",
                    "source": "homebrew",
                    "owner": user.id,
                },
                type="subclass_features",
                scope=f"campaign-{campaign_id}",
            )
            stats["subclasses"]["created"] += 1
        except Exception:
            stats["subclasses"]["errors"] += 1

    # ── Races ───────────────────────────────────────────────────────────
    for row in (body.get("races") or [])[:200]:
        if not isinstance(row, dict):
            stats["races"]["errors"] += 1
            continue
        try:
            name = _safe_str(row.get("name"), 120)
            slug = _slugify_for_subclass(name, max_len=60) or _safe_str(row.get("race_slug"), 60)
            if not name or not slug:
                stats["races"]["errors"] += 1
                continue
            if _existing_race(slug):
                stats["races"]["skipped"] += 1
                continue
            local_content.write_homebrew(
                {
                    "slug": slug, "name": name,
                    "ability_bonuses": row.get("ability_bonuses") if isinstance(row.get("ability_bonuses"), list) else [],
                    "size": _safe_str(row.get("size"), 40),
                    "speed": _safe_int(row.get("speed"), 30),
                    "age": _safe_str(row.get("age"), 1000),
                    "alignment": _safe_str(row.get("alignment"), 1000),
                    "languages": _safe_str(row.get("languages"), 1000),
                    "traits": row.get("traits") if isinstance(row.get("traits"), list) else [],
                    "actions": [],
                    "system": "dnd5e",
                    "scope": f"campaign-{campaign_id}",
                    "source": "homebrew",
                    "owner": user.id,
                },
                type="races",
                scope=f"campaign-{campaign_id}",
            )
            stats["races"]["created"] += 1
        except Exception:
            stats["races"]["errors"] += 1

    # ── Monsters ────────────────────────────────────────────────────────
    for row in (body.get("monsters") or [])[:500]:
        if not isinstance(row, dict):
            stats["monsters"]["errors"] += 1
            continue
        try:
            name = _safe_str(row.get("name"), 120)
            slug = _slugify_for_subclass(name, max_len=80) or _safe_str(row.get("monster_slug"), 80)
            if not name or not slug:
                stats["monsters"]["errors"] += 1
                continue
            if _existing_monster(slug):
                stats["monsters"]["skipped"] += 1
                continue
            # Coalesce the 4 legacy split lists from the import payload into
            # the unified actions array with category labels.
            import re as _re
            _unified: list[dict] = []
            for _src_key, _cat in (
                ("actions", "action"),
                ("reactions", "reaction"),
                ("special_abilities", "special_ability"),
                ("legendary_actions", "legendary_action"),
            ):
                _list = row.get(_src_key)
                if not isinstance(_list, list):
                    continue
                for _entry in _list:
                    if not isinstance(_entry, dict):
                        continue
                    _nm = (_entry.get("name") or "").strip()
                    _slug_id = _re.sub(r"[^a-z0-9]+", "-", _nm.lower()).strip("-") or f"unnamed-{_cat}"
                    _unified.append({
                        "id": _entry.get("id") or _slug_id,
                        "name": _nm,
                        "desc": _entry.get("desc") or "",
                        "min_level": _entry.get("level") or 1,
                        "category": _cat,
                    })
            local_content.write_homebrew(
                {
                    "slug": slug, "name": name,
                    "size": _safe_str(row.get("size") or "Medium", 40),
                    "type": _safe_str(row.get("type") or "beast", 60).lower(),
                    "alignment": _safe_str(row.get("alignment"), 120),
                    "armor_class": _safe_int(row.get("armor_class"), 10),
                    "armor_desc": _safe_str(row.get("armor_desc"), 120),
                    "hit_points": _safe_int(row.get("hit_points"), 1),
                    "hit_dice": _safe_str(row.get("hit_dice"), 40),
                    "speed": row.get("speed") if isinstance(row.get("speed"), dict) else {"walk": 30},
                    "strength": _safe_int(row.get("strength"), 10),
                    "dexterity": _safe_int(row.get("dexterity"), 10),
                    "constitution": _safe_int(row.get("constitution"), 10),
                    "intelligence": _safe_int(row.get("intelligence"), 10),
                    "wisdom": _safe_int(row.get("wisdom"), 10),
                    "charisma": _safe_int(row.get("charisma"), 10),
                    "damage_vulnerabilities": _safe_str(row.get("damage_vulnerabilities"), 500),
                    "damage_resistances": _safe_str(row.get("damage_resistances"), 500),
                    "damage_immunities": _safe_str(row.get("damage_immunities"), 500),
                    "condition_immunities": _safe_str(row.get("condition_immunities"), 500),
                    "senses": _safe_str(row.get("senses"), 500),
                    "languages": _safe_str(row.get("languages"), 500),
                    "challenge_rating": _safe_str(row.get("challenge_rating") or "0", 20),
                    "actions": _unified,
                    "system": "dnd5e",
                    "scope": f"campaign-{campaign_id}",
                    "source": "homebrew",
                    "owner": user.id,
                },
                type="monsters",
                scope=f"campaign-{campaign_id}",
            )
            stats["monsters"]["created"] += 1
        except Exception:
            stats["monsters"]["errors"] += 1

    # ── Backgrounds ─────────────────────────────────────────────────────
    for row in (body.get("backgrounds") or [])[:200]:
        if not isinstance(row, dict):
            stats["backgrounds"]["errors"] += 1
            continue
        try:
            name = _safe_str(row.get("name"), 120)
            slug = _slugify_for_subclass(name, max_len=60) or _safe_str(row.get("background_slug"), 60)
            if not name or not slug:
                stats["backgrounds"]["errors"] += 1
                continue
            if _existing_background(slug):
                stats["backgrounds"]["skipped"] += 1
                continue
            local_content.write_homebrew(
                {
                    "slug": slug, "name": name,
                    "description": _safe_str(row.get("description"), 8000),
                    "skill_proficiencies": _safe_str(row.get("skill_proficiencies"), 500),
                    "tool_proficiencies": _safe_str(row.get("tool_proficiencies"), 500),
                    "languages": _safe_str(row.get("languages"), 500),
                    "equipment": _safe_str(row.get("equipment"), 4000),
                    "feature_name": _safe_str(row.get("feature_name"), 160),
                    "feature_desc": _safe_str(row.get("feature_desc"), 4000),
                    "actions": [],
                    "system": "dnd5e",
                    "scope": f"campaign-{campaign_id}",
                    "source": "homebrew",
                    "owner": user.id,
                },
                type="backgrounds",
                scope=f"campaign-{campaign_id}",
            )
            stats["backgrounds"]["created"] += 1
        except Exception:
            stats["backgrounds"]["errors"] += 1

    # ── Feats ───────────────────────────────────────────────────────────
    for row in (body.get("feats") or [])[:500]:
        if not isinstance(row, dict):
            stats["feats"]["errors"] += 1
            continue
        try:
            name = _safe_str(row.get("name"), 120)
            slug = _slugify_for_subclass(name, max_len=80) or _safe_str(row.get("feat_slug"), 80)
            if not name or not slug:
                stats["feats"]["errors"] += 1
                continue
            if _existing_feat(slug):
                stats["feats"]["skipped"] += 1
                continue
            # v2.0.0: write directly to the homebrew file volume.
            local_content.write_homebrew(
                {
                    "slug": slug, "name": name,
                    "prerequisite": _safe_str(row.get("prerequisite"), 500),
                    "desc": _safe_str(row.get("desc"), 8000),
                    "actions": [],
                    "system": "dnd5e",
                    "scope": f"campaign-{campaign_id}",
                    "source": "homebrew",
                    "owner": user.id,
                },
                type="feats",
                scope=f"campaign-{campaign_id}",
            )
            stats["feats"]["created"] += 1
        except Exception:
            stats["feats"]["errors"] += 1

    db.commit()
    totals = {
        "created": sum(s["created"] for s in stats.values()),
        "skipped": sum(s["skipped"] for s in stats.values()),
        "errors":  sum(s["errors"]  for s in stats.values()),
    }
    return {"ok": True, "stats": stats, "totals": totals}


@router.post("/campaign/{campaign_id}/members/{membership_id}/set_gm")
def set_member_gm(
    campaign_id: int,
    membership_id: int,
    is_gm: bool = Form(False),
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Promote/demote a campaign member to/from co-GM. Any GM (primary,
    co-GM, or admin) of this campaign may toggle the flag."""
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign:
        raise HTTPException(404, "Campaign not found")
    if not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only")
    membership = (
        db.query(CampaignMembership)
        .filter(
            CampaignMembership.id == membership_id,
            CampaignMembership.campaign_id == campaign_id,
        )
        .first()
    )
    if not membership:
        raise HTTPException(404, "Member not found")
    membership.is_gm = bool(is_gm)
    db.commit()
    return RedirectResponse(f"/campaign/{campaign_id}/settings", status_code=303)


@router.post("/campaign/{campaign_id}/session/start")
async def start_session(
    campaign_id: int,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """GM (or admin) opens the tabletop to players. Idempotent: re-Starting
    an already-active session is a no-op except it refreshes started_at.

    Audio auto-start: when ``campaign.auto_play_playlist_id`` is set, the
    configured playlist begins playing the moment the session starts.
    ``auto_play_mode == 'order'`` plays the first track; ``'shuffle'``
    picks a random track. Any audio already playing is replaced. The
    auto-play side-effect tolerates errors (missing playlist, no tracks)
    silently — a broken auto-play config shouldn't block session start.
    """
    from datetime import datetime as _dt
    import random as _random
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign:
        raise HTTPException(404, "Campaign not found")
    if not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only")
    campaign.session_active = True
    campaign.session_started_at = _dt.utcnow()
    db.commit()
    await hub.broadcast(campaign_id, {"type": "session_started", "data": {}})

    # Auto-start audio if configured.
    if campaign.auto_play_playlist_id:
        from .audio_routes import _start_track_for_campaign
        playlist = (
            db.query(Playlist)
            .filter(
                Playlist.id == campaign.auto_play_playlist_id,
                Playlist.campaign_id == campaign_id,
            )
            .first()
        )
        if playlist and playlist.tracks:
            tracks = list(playlist.tracks)   # ordered by position
            if (campaign.auto_play_mode or "order").lower() == "shuffle":
                track = _random.choice(tracks)
            else:
                track = tracks[0]
            try:
                await _start_track_for_campaign(
                    db, campaign, track,
                    source="auto_start",
                    prev_reason="session_end",
                    user_id=user.id,
                )
            except Exception as exc:
                log.warning("Auto-play failed for campaign %s: %s", campaign_id, exc)

    # Auto-load the configured default encounter, if any. Same
    # tolerate-failures pattern as audio above — a broken default
    # encounter config shouldn't block session start. ``start_audio``
    # is False here because we just kicked off audio above (if
    # configured) via the campaign's auto-play setting; letting the
    # encounter clobber that would be surprising.
    if campaign.default_encounter_id:
        default_enc = (
            db.query(Encounter)
            .filter(
                Encounter.id == campaign.default_encounter_id,
                Encounter.campaign_id == campaign_id,
            )
            .first()
        )
        if default_enc:
            try:
                await _perform_encounter_load(
                    db, campaign, default_enc,
                    start_audio=False,
                    user_id=user.id,
                )
            except HTTPException as exc:
                log.warning(
                    "Default encounter %s skipped on session start for campaign %s: %s",
                    default_enc.id, campaign_id, exc.detail,
                )
            except Exception as exc:
                log.warning(
                    "Default encounter %s failed on session start for campaign %s: %s",
                    default_enc.id, campaign_id, exc,
                )

    return RedirectResponse(f"/campaign/{campaign_id}", status_code=303)


@router.post("/campaign/{campaign_id}/session/end")
async def end_session(
    campaign_id: int,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """GM (or admin) closes the tabletop. Players in the tabletop will be
    bounced back to the lobby; new players hitting the URL get the
    waiting page until the GM Starts again.

    Audio auto-stop: any audio still playing is stopped for everyone via
    the same path as the manual ``/audio/stop`` button.
    """
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign:
        raise HTTPException(404, "Campaign not found")
    if not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only")
    campaign.session_active = False
    db.commit()
    await hub.broadcast(campaign_id, {"type": "session_ended", "data": {}})

    # Stop any audio that's still playing. Idempotent — safe when nothing
    # is currently playing. ``reason='session_end'`` labels the in-flight
    # AudioPlayEvent (if any) so the history shows why the play ended.
    if campaign.now_playing_track_id is not None:
        from .audio_routes import _stop_audio_for_campaign
        try:
            await _stop_audio_for_campaign(db, campaign, reason="session_end")
        except Exception as exc:
            log.warning("Auto-stop audio failed for campaign %s: %s", campaign_id, exc)

    return RedirectResponse("/", status_code=303)


@router.get("/campaign/{campaign_id}/rolls", response_class=HTMLResponse)
def rolls_popout(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(404, "Not found")
    rolls = (
        db.query(DiceRoll)
        .filter(DiceRoll.campaign_id == campaign.id)
        .order_by(DiceRoll.created_at.desc())
        .limit(500)
        .all()
    )
    visible = [r for r in rolls if _filter_roll_for_user(r, user, campaign, db)]
    user_color_map, user_portrait_map, user_char_name_map = _build_user_maps(db, campaign)
    return templates.TemplateResponse(
        "rolls_popout.html",
        {
            "request": request,
            "user": user,
            "campaign": campaign,
            "rolls": visible,
            "is_gm": _user_is_gm(user, campaign, db),
            "user_color_map": user_color_map,
            "user_portrait_map": user_portrait_map,
            "user_char_name_map": user_char_name_map,
            # v2.116.0 — reroll buttons in the popout too.
            "roll_reroll_options": _reroll_options_for_rolls(db, visible),
        },
    )


# ----------- API: tokens -----------

# v2.102.0 — movement-lock per-token grants. When the GM approves a
# player's movement request (Phase 3), a one-shot grant is recorded
# here keyed (campaign_id, user_id, token_id). The /token/move gate
# consumes it to let that player make a SINGLE move while the table
# stays locked for everyone else. Ephemeral (in-memory, cleared on
# restart) with a 10-minute TTL so a stale grant doesn't linger across
# a session. Mirrors the _heal_claims / _active_reaction_prompts shape.
_movement_grants: dict[tuple[int, int, int], float] = {}
_MOVEMENT_GRANT_TTL_S = 600  # 10 minutes


def _grant_movement(campaign_id: int, user_id: int, token_id: int) -> None:
    """Record a one-shot movement grant for (campaign, user, token)."""
    _movement_grants[(int(campaign_id), int(user_id), int(token_id))] = (
        _time.time() + _MOVEMENT_GRANT_TTL_S
    )


def _consume_movement_grant(
    campaign_id: int, user_id: int, token_id: int,
) -> bool:
    """Consume a one-shot movement grant. Returns True if a live grant
    existed (and removes it); False otherwise. An expired grant is
    dropped and treated as absent."""
    key = (int(campaign_id), int(user_id), int(token_id))
    expires = _movement_grants.pop(key, None)
    return expires is not None and expires >= _time.time()


# v2.104.0 — movement requests (Phase 3). When a player drags a token
# while movement is locked, they can ask the GM to unlock that one
# token. The request is recorded here (ephemeral, in-memory, 10-min
# TTL), broadcast to the GM(s) as ``movement_request``; the GM's
# approve issues a one-shot ``_grant_movement`` for (campaign, player,
# token) and broadcasts ``movement_request_resolved`` back to the
# requester so their client lets a single drag through. Mirrors the
# _active_reaction_prompts store shape.
_movement_requests: dict[str, dict] = {}
_MOVEMENT_REQUEST_TTL_S = 600  # 10 minutes


def _purge_movement_requests() -> None:
    """Drop expired / resolved movement requests so the store can't
    grow unboundedly. Called on every read/write path."""
    now = _time.time()
    for rid in [
        k for k, v in _movement_requests.items()
        if v.get("resolved") or float(v.get("expires_at", 0)) <= now
    ]:
        _movement_requests.pop(rid, None)


@router.post("/api/campaign/{campaign_id}/movement_lock")
async def set_movement_lock(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.102.0 — GM toggles the live movement-lock state.

    Body: ``{"locked": bool}``. GM-only. Persists
    ``campaign.movement_locked`` and broadcasts ``movement_lock_update``
    so every connected client updates its lock chrome (and the player
    canvas starts/stops rejecting drags). Returns the new state.
    """
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign:
        raise HTTPException(404, "Campaign not found")
    if not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only")
    body = await request.json()
    locked = bool(body.get("locked"))
    campaign.movement_locked = locked
    db.commit()
    await hub.broadcast(campaign_id, {
        "type": "movement_lock_update",
        "data": {"locked": locked},
    })
    return {"ok": True, "locked": locked}


@router.post("/api/campaign/{campaign_id}/movement_request")
async def create_movement_request(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.104.0 — a player asks the GM to unlock one token's movement.

    Body: ``{"token_id": int}``. Any campaign member may ask. Records
    an ephemeral request and broadcasts ``movement_request`` to the
    GM(s) only. Returns ``{ok, request_id}``. The GM resolves it via
    ``/movement_request/{rid}/respond``.
    """
    _purge_movement_requests()
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    body = await request.json()
    token_id = body.get("token_id")
    if token_id is None:
        raise HTTPException(400, "token_id required")
    token = db.query(Token).filter(Token.id == int(token_id)).first()
    if not token or token.map.campaign_id != campaign_id:
        raise HTTPException(404, "Token not found")
    request_id = uuid.uuid4().hex[:12]
    _movement_requests[request_id] = {
        "campaign_id": campaign_id,
        "requester_user_id": int(user.id),
        "token_id": int(token.id),
        "expires_at": _time.time() + _MOVEMENT_REQUEST_TTL_S,
        "resolved": False,
    }
    await hub.broadcast(
        campaign_id,
        {
            "type": "movement_request",
            "data": {
                "request_id": request_id,
                "requester_user_id": int(user.id),
                "requester_name": user.display_name,
                "token_id": int(token.id),
                "token_label": token.label or "Token",
                "character_id": token.character_id,
            },
        },
        recipient_filter=lambda ident: bool(ident.get("is_gm")),
    )
    return {"ok": True, "request_id": request_id}


@router.post("/api/campaign/{campaign_id}/movement_request/{request_id}/respond")
async def respond_movement_request(
    campaign_id: int,
    request_id: str,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.104.0 — GM approves or denies a movement request.

    Body: ``{"approved": bool}``. GM-only. On approve, issues a
    one-shot ``_grant_movement`` for (campaign, requester, token) so
    the requester's next drag of that token passes the lock gate, then
    broadcasts ``movement_request_resolved`` to the requester (and the
    GM tabs, so a second GM's popup dismisses).
    """
    _purge_movement_requests()
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign:
        raise HTTPException(404, "Campaign not found")
    if not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only")
    entry = _movement_requests.get(request_id)
    if not entry or entry.get("campaign_id") != campaign_id:
        raise HTTPException(404, "Movement request not found or expired")
    body = await request.json()
    approved = bool(body.get("approved"))
    entry["resolved"] = True
    requester_user_id = int(entry["requester_user_id"])
    token_id = int(entry["token_id"])
    token = db.query(Token).filter(Token.id == token_id).first()
    token_label = (token.label if token else None) or "Token"
    if approved:
        _grant_movement(campaign_id, requester_user_id, token_id)
    await hub.broadcast(
        campaign_id,
        {
            "type": "movement_request_resolved",
            "data": {
                "request_id": request_id,
                "approved": approved,
                "token_id": token_id,
                "token_label": token_label,
                "requester_user_id": requester_user_id,
            },
        },
        recipient_filter=lambda ident: (
            bool(ident.get("is_gm"))
            or ident.get("user_id") == requester_user_id
        ),
    )
    return {"ok": True, "approved": approved}


@router.post("/api/campaign/{campaign_id}/token/{token_id}/move")
async def move_token(
    campaign_id: int,
    token_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    body = await request.json()
    x = float(body.get("x", 0))
    y = float(body.get("y", 0))
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign:
        raise HTTPException(404, "Campaign not found")
    token = db.query(Token).filter(Token.id == token_id).first()
    if not token or token.map.campaign_id != campaign_id:
        raise HTTPException(404, "Token not found")
    if not _user_can_move_token(db, user, token, campaign):
        raise HTTPException(403, "You can't move that token")

    # v2.102.0 — movement lock. When the GM has locked movement
    # (``campaign.movement_locked``), non-GM token drags are rejected
    # with a 409 ``movement_locked`` so the player can't reposition
    # their piece until the GM unlocks OR approves a per-token request
    # (Phase 3). GM drags pass through — the GM is the arbiter and the
    # client shows them an advisory "move anyway?" confirm. A one-shot
    # GM grant (issued by approving a player's movement request) is
    # consumed here to let that player make a single move while the
    # table stays locked for everyone else.
    if bool(campaign.movement_locked) and not _user_is_gm(user, campaign, db):
        if not _consume_movement_grant(campaign_id, int(user.id), int(token.id)):
            return JSONResponse(status_code=409, content={
                "error": "movement_locked",
                "token_id": int(token.id),
            })

    # v2.99.79 — initiative-turn enforcement. When a battle is active
    # in the realtime hub AND the dragger is a non-GM, the token they're
    # moving must be the ACTIVE combatant's token. Off-turn drags are
    # rejected so players can't reposition pieces during another
    # combatant's turn. GM bypass (the rules authority). Battle
    # inactive → unchanged behavior.
    if not _user_is_gm(user, campaign, db):
        _state = hub.get_battle(campaign_id) or {}
        if bool(_state.get("active")):
            _combs = _state.get("combatants") or []
            _idx = _state.get("turn_index")
            if (_combs and isinstance(_idx, int)
                    and 0 <= _idx < len(_combs)):
                _active = _combs[_idx]
                _is_active_token = (
                    (_active.get("source_token_id") == int(token.id))
                    or (
                        token.character_id is not None
                        and _active.get("char_id") == int(token.character_id)
                    )
                )
                if not _is_active_token:
                    raise HTTPException(
                        403, "Not your turn — wait for the initiative tracker",
                    )

    # v2.6.2: Phase 5 movement tracker. Capture the prior position
    # before the mutation so the broadcast can carry both endpoints +
    # the computed distance in feet. The action-economy chip strip on
    # the init tracker adds ``distance_ft`` to the combatant's
    # ``economy.movement`` running total each time the matching token
    # moves. ``character_id`` is included so the client can join the
    # broadcast to the right combatant without a second lookup.
    from_x = float(token.x or 0)
    from_y = float(token.y or 0)
    grid_size_px = int(token.map.grid_size_px or 0)
    # v2.49.73 — distance math moved to ``_distance_ft_between_points``
    # so the ruler / range-check call sites use the same primitive.
    # Chebyshev (RAW 5-5-5 diagonals) on square; Euclidean on hex /
    # no-grid; 5 ft per cell. Grid type enum normalised by the ORM
    # (SQUARE / HEX_FLAT / HEX_POINTY / NONE all map here).
    grid_type = (token.map.grid_type.value if token.map.grid_type else "square").lower()
    distance_ft = _distance_ft_between_points(
        grid_size_px, grid_type, from_x, from_y, x, y,
    )

    # v2.158.51 — Relentless Avenger (Vengeance Paladin Lv 7+, PHB
    # p.88) Phase 2 read site. The v2.149.0 install lands a 1-round
    # `relentless-avenger-bonus-move` buff carrying
    # `free_movement_remaining_ft` (= half walking speed) +
    # `oa_immune_during_move`. RAW: "When you hit a creature with an
    # opportunity attack, you can move up to half your speed
    # immediately after the attack ... This movement doesn't provoke
    # opportunity attacks." This read (a) exempts up to
    # `free_movement_remaining_ft` of this drag from the over-speed
    # cap and (b) suppresses OA triggers for the move, then consumes
    # the buff (single-use — the install desc says "consumed on next
    # move"). Detected on the moving PC's combatant via `_get_buffs`.
    _ra_buff = None
    _ra_free_ft = 0.0
    if token.character_id and distance_ft > 0:
        for _rb in _get_buffs(campaign_id, int(token.character_id)):
            if (_rb or {}).get("key") != "relentless-avenger-bonus-move":
                continue
            _reff = _rb.get("effects") or {}
            if _reff.get("oa_immune_during_move"):
                _ra_buff = _rb
                try:
                    _ra_free_ft = float(_reff.get("free_movement_remaining_ft") or 0)
                except (TypeError, ValueError):
                    _ra_free_ft = 0.0
            break

    # v2.99.99 — server-side over-speed gate. Mirrors the OA 409
    # pattern: if this move would put the active combatant's
    # cumulative `economy.movement` past the EFFECTIVE cap
    # (base speed - Lance of Lethargy / Slow / web reductions
    # + Dash bonus), return 409 `over_speed_cap` UNLESS the client
    # passes `over_speed_confirmed: true`. Pre-v2.99.99 the
    # Dash/overrun gate was purely client-side advisory; this is
    # the defense-in-depth that catches malicious / scripted
    # clients bypassing the modal.
    #
    # Only fires when (a) a battle is active AND (b) the mover IS
    # the active combatant. Out-of-combat drags / off-turn drags
    # are not gated (off-turn already blocks at the v2.99.79 turn
    # check above for non-GMs). GM drags of NPC tokens during a PC's
    # turn aren't gated either — the GM is the arbiter and may
    # reposition pieces narratively.
    if distance_ft > 0 and not bool(body.get("over_speed_confirmed")):
        _state_for_cap = hub.get_battle(campaign_id) or {}
        if bool(_state_for_cap.get("active")):
            _combs_cap = _state_for_cap.get("combatants") or []
            _idx_cap = _state_for_cap.get("turn_index")
            if (_combs_cap and isinstance(_idx_cap, int)
                    and 0 <= _idx_cap < len(_combs_cap)):
                _active_cap = _combs_cap[_idx_cap]
                _is_active_for_cap = (
                    (_active_cap.get("source_token_id") == int(token.id))
                    or (
                        token.character_id is not None
                        and _active_cap.get("char_id") == int(token.character_id)
                    )
                )
                if _is_active_for_cap:
                    _econ_cap = _active_cap.get("economy") or {}
                    _used_ft = float(_econ_cap.get("movement") or 0)
                    _dash_bonus_ft = float(
                        _econ_cap.get("dash_bonus_ft") or 0
                    )
                    _eff_speed = _effective_speed_walk(_active_cap)
                    _eff_cap = _eff_speed + _dash_bonus_ft
                    # v2.158.51 — Relentless Avenger's bonus move is a
                    # separate movement that doesn't count against the
                    # turn's normal speed. Exempt up to the buff's
                    # remaining free budget from the projected total.
                    _ra_exempt = (
                        min(distance_ft, _ra_free_ft)
                        if _ra_buff is not None else 0.0
                    )
                    _projected_total = _used_ft + distance_ft - _ra_exempt
                    # Tolerance: 0.01 ft to absorb float drift in the
                    # Chebyshev / Euclidean distance derivation.
                    if _projected_total > _eff_cap + 0.01:
                        return JSONResponse(status_code=409, content={
                            "error": "over_speed_cap",
                            "distance_ft": distance_ft,
                            "used_ft": _used_ft,
                            "cap_ft": _eff_cap,
                            "base_speed_walk": int(
                                _active_cap.get("speed_walk") or 30
                            ),
                            "dash_bonus_ft": _dash_bonus_ft,
                            "speed_reduction_ft":
                                _effective_speed_reduction_ft(_active_cap),
                        })

    # v2.99.55 — plan-movement-oa-flow Phase 4 defense-in-depth gate.
    # Compute OA triggers BEFORE committing the move. If any fire
    # AND the client didn't pass ``oa_confirmed: true``, return 409
    # `oa_confirmation_required` so the malicious-client case can't
    # bypass the pre-move modal. The client (v2.99.55 Phase 4 wire)
    # calls /token/{id}/preview_move first, opens the modal, and
    # only POSTs /token/move with `oa_confirmed: true` once the GM
    # / player has clicked Continue. Token position stays put on the
    # 409 path so the client doesn't need to snap-back from a
    # half-committed move.
    oa_triggers: list[dict] = []
    if distance_ft > 0:
        try:
            oa_triggers = _check_opportunity_attack_triggers(
                db, campaign_id, int(token.id),
                from_x, from_y, x, y,
            )
        except Exception:
            oa_triggers = []
    # v2.158.51 — Relentless Avenger: the bonus move doesn't provoke
    # opportunity attacks. Drop any triggers this drag would have
    # raised so the 409 gate + advisory below both see an empty list.
    _ra_applied = False
    if _ra_buff is not None and distance_ft > 0:
        _ra_applied = True
        oa_triggers = []
    if oa_triggers and not bool(body.get("oa_confirmed")):
        return JSONResponse(status_code=409, content={
            "error": "oa_confirmation_required",
            "would_trigger_oa": True,
            "distance_ft": distance_ft,
            "triggers": [
                {
                    "watcher_combatant_id": t.get("watcher_combatant_id"),
                    "watcher_name": t.get("watcher_name"),
                    "watcher_char_id": t.get("watcher_char_id"),
                    "watcher_token_id": t.get("watcher_token_id"),
                    "watcher_reach_ft": t.get("watcher_reach_ft"),
                    "trigger_type": t.get("trigger_type") or "exit",
                    # v2.99.60 — path-cross OAs carry the minimum
                    # segment-to-watcher distance the helper detected
                    # so chat-card copy can explain why the OA fired
                    # despite both endpoints being outside reach.
                    # Absent on endpoint-based triggers.
                    "path_crossed_ft": t.get("path_crossed_ft"),
                }
                for t in oa_triggers
            ],
        })

    token.x = x
    token.y = y
    db.commit()
    await hub.broadcast(
        campaign_id,
        {"type": "token_move", "data": {
            "id": token.id,
            "x": x, "y": y,
            "from_x": from_x, "from_y": from_y,
            "distance_ft": distance_ft,
            "character_id": token.character_id,
            "token_template_id": token.token_template_id,
        }},
    )

    # v2.158.51 — Relentless Avenger: consume the single-use buff after
    # the move and announce the OA-free movement. Removing the buff
    # broadcasts a `buff_update`; a `feature_used` advisory documents
    # the OA suppression so the table sees why no OA fired.
    if _ra_applied:
        await _remove_buff(
            campaign_id, int(token.character_id),
            "relentless-avenger-bonus-move",
        )
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": token.character_id,
                "character_name": token.label or "Paladin",
                "feature_name": "🏃 Relentless Avenger",
                "feature_desc": (
                    f"Moved {round(distance_ft, 1)} ft without provoking "
                    f"opportunity attacks (Vengeance Paladin, half speed)."
                ),
                "source": "relentless-avenger",
            },
        })

    # v2.66.0 — F1 follow-up: Opportunity Attack trigger advisory.
    # When the mover leaves a watcher's 5 ft reach mid-move, broadcast
    # a feature_used advisory so the watcher's controller can decide
    # whether to spend their reaction on an OA. Pure advisory — does
    # NOT auto-fire the attack or consume the reaction.
    # v2.99.55 — oa_triggers was computed above for the 409 gate; reuse.
    mover_name = token.label or "Token"
    # v2.99.56 — plan-movement-oa-flow Phase 5 serial queue.
    # Pre-v2.99.56 every trigger emitted both a legacy feature_used
    # advisory AND a reaction_prompt in parallel — multiple
    # watchers' owners all got popups at once. v2.99.56 keeps the
    # per-trigger feature_used (audit trail stays complete) but
    # only emits a single reaction_prompt for the HEAD of the
    # trigger list. The tail rides along in the head's
    # ``context.next_triggers``; /use_reaction's resolve handler
    # pops the head off and emits the next prompt when the current
    # one resolves. This serializes the watcher prompts so the
    # mover sees them flow one-at-a-time instead of an
    # everyone-at-once swarm.
    for trig in oa_triggers:
        reach_ft = trig.get("watcher_reach_ft") or 5.0
        # Render the reach in whole feet when it's an integer value
        # (most common: 5, 10, 15) and strip trailing ".0" so the chat
        # card reads "5 ft" not "5.0 ft".
        reach_display = (
            int(reach_ft) if float(reach_ft).is_integer() else reach_ft
        )
        trigger_type = trig.get("trigger_type") or "exit"
        if trigger_type == "enter":
            # v2.66.4 — Polearm Master enter-reach OA. Different chat
            # card copy makes the source crystal clear.
            feature_name = (
                "⚔ Opportunity Attack triggered (Polearm Master)"
            )
            feature_desc = (
                f"{mover_name} entered {trig.get('watcher_name')}'s "
                f"{reach_display} ft polearm reach. Polearm Master lets "
                f"you use your reaction to make a melee attack on entry."
            )
        else:
            feature_name = "⚔ Opportunity Attack triggered"
            feature_desc = (
                f"{mover_name} moved out of {trig.get('watcher_name')}'s "
                f"{reach_display} ft reach. Use your reaction to make a "
                f"melee attack?"
            )
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": trig.get("watcher_char_id"),
                "character_name": trig.get("watcher_name"),
                "user_color": trig.get("watcher_color"),
                "feature_name": feature_name,
                "feature_desc": feature_desc,
                "source": "opportunity-attack-trigger",
                "trigger_type": trigger_type,
                "watcher_combatant_id": trig.get("watcher_combatant_id"),
                "watcher_token_id": trig.get("watcher_token_id"),
                "watcher_reach_ft": reach_ft,
                "mover_token_id": int(token.id),
                "mover_name": mover_name,
            },
        })

    # v2.99.57 — plan-movement-oa-flow Phase 6 per-owner sub-queue.
    # v2.99.56 emitted a SINGLE reaction_prompt for the head of the
    # entire trigger list, globally serializing every watcher.
    # v2.99.57 partitions triggers by their watcher's primary owner
    # (PC's owner_user_id; GM for NPCs) and emits ONE prompt per
    # owner in parallel. Each owner's tail rides in that prompt's
    # context.next_triggers; /use_reaction's resolve chain pops the
    # next head off the SAME owner's queue when resolved. Net
    # effect: two different players each get their popup
    # immediately; one player owning two watchers sees them one at
    # a time.
    if oa_triggers:
        # Partition triggers by owner_user_id, preserving original
        # iteration order across owners + within each owner.
        _gm_uid = int(campaign.gm_user_id) if campaign.gm_user_id else 0
        _owner_groups: dict[int, list[dict]] = {}
        _owner_order: list[int] = []
        for _trig in oa_triggers:
            _wcid = _trig.get("watcher_char_id")
            _owner_uid: int | None = None
            if _wcid:
                try:
                    _wchar = db.query(Character).filter(
                        Character.id == int(_wcid),
                    ).first()
                except Exception:
                    _wchar = None
                if _wchar and _wchar.owner_user_id:
                    _owner_uid = int(_wchar.owner_user_id)
            if _owner_uid is None:
                _owner_uid = _gm_uid
            if _owner_uid not in _owner_groups:
                _owner_groups[_owner_uid] = []
                _owner_order.append(_owner_uid)
            _owner_groups[_owner_uid].append(_trig)

        for _owner_uid in _owner_order:
            _group = _owner_groups[_owner_uid]
            if not _group:
                continue
            _head = _group[0]
            _head_trig_type = _head.get("trigger_type") or "exit"
            _head_reach_ft = _head.get("watcher_reach_ft") or 5.0
            _head_reach_disp = (
                int(_head_reach_ft) if float(_head_reach_ft).is_integer()
                else _head_reach_ft
            )
            if _head_trig_type == "enter":
                _head_summary = (
                    f"{mover_name} entered {_head.get('watcher_name')}'s "
                    f"{_head_reach_disp} ft polearm reach. Polearm "
                    f"Master lets you use your reaction to make a melee "
                    f"attack on entry."
                )
                _head_evt = "creature_enters_reach"
            else:
                _head_summary = (
                    f"{mover_name} moved out of "
                    f"{_head.get('watcher_name')}'s "
                    f"{_head_reach_disp} ft reach. Use your reaction to "
                    f"make a melee attack?"
                )
                _head_evt = "creature_exits_reach"
            _head_watcher_combatant = None
            for _c in (hub.get_battle(campaign_id) or {}).get(
                "combatants", []
            ) or []:
                if _c.get("id") == _head.get("watcher_combatant_id"):
                    _head_watcher_combatant = _c
                    break
            if _head_watcher_combatant is None:
                continue
            try:
                # Tail entries are scoped to THIS owner only. Each
                # owner's chain is independent — resolving an alice
                # prompt won't pop a bob prompt off.
                _tail = [
                    {
                        "watcher_combatant_id": t.get("watcher_combatant_id"),
                        "watcher_name": t.get("watcher_name"),
                        "watcher_char_id": t.get("watcher_char_id"),
                        "watcher_token_id": t.get("watcher_token_id"),
                        "watcher_reach_ft": t.get("watcher_reach_ft"),
                        "trigger_type": t.get("trigger_type") or "exit",
                    }
                    for t in _group[1:]
                ]
                # v2.99.68 — include mover_combatant_id so the
                # client can auto-chain the chosen OA attack via
                # /attack (PC watcher) or /npc_attack (NPC watcher)
                # against the provoker. v2.99.73 — extend the
                # lookup to also try token_template_id + label
                # for NPC movers whose combatants don't carry
                # source_token_id (the demo's seed_encounter shape
                # pre-v2.99.73). Without the fallback the chain
                # silently broke for every NPC-provoking-PC OA.
                _mover_comb_id = None
                _state2 = hub.get_battle(campaign_id) or {}
                _movers = (_state2.get("combatants") or [])
                for _mc in _movers:
                    if _mc.get("source_token_id") == int(token.id):
                        _mover_comb_id = _mc.get("id")
                        break
                if _mover_comb_id is None and token.character_id:
                    for _mc in _movers:
                        if _mc.get("char_id") == int(token.character_id):
                            _mover_comb_id = _mc.get("id")
                            break
                if _mover_comb_id is None and token.token_template_id and token.label:
                    for _mc in _movers:
                        if (
                            _mc.get("token_template_id") == int(token.token_template_id)
                            and _mc.get("name") == token.label
                        ):
                            _mover_comb_id = _mc.get("id")
                            break
                await _emit_reaction_prompt(
                    db, campaign, _head_watcher_combatant,
                    trigger_event=_head_evt,
                    summary=_head_summary,
                    context={
                        "mover_token_id": int(token.id),
                        "mover_combatant_id": _mover_comb_id,
                        "mover_name": mover_name,
                        "watcher_reach_ft": _head_reach_ft,
                        "trigger_type": _head_trig_type,
                        "next_triggers": _tail,
                    },
                )
            except Exception as _oa_emit_err:
                logging.exception(
                    "OA reaction_prompt emit failed for "
                    "owner_uid=%s watcher_combatant_id=%s trigger=%s: %s",
                    _owner_uid, _head.get("watcher_combatant_id"),
                    _head_trig_type, _oa_emit_err,
                )

    # v2.8.0: strict-mode movement audit. When the campaign has
    # strict_action_economy on AND this drag pushes the combatant past
    # their walking speed for the FIRST time this turn (transition from
    # pre <= speed_walk to post > speed_walk), broadcast a feature_used
    # audit entry to the roll log. We can't snap the token back — the
    # drag IS the GM's authoritative input — but the audit makes the
    # violation visible to everyone at the table.
    if campaign.strict_action_economy and distance_ft > 0:
        state = hub.get_battle(campaign_id) or {}
        combatant = None
        for c in state.get("combatants") or []:
            if c.get("source_token_id") == token.id:
                combatant = c
                break
            if token.character_id and c.get("char_id") == token.character_id:
                combatant = c
                break
        if combatant:
            economy = combatant.get("economy") or {}
            prev_movement = float(economy.get("movement") or 0)
            speed_walk = float(combatant.get("speed_walk") or 30)
            post_total = prev_movement + distance_ft
            if (prev_movement <= speed_walk + 0.001) and (post_total > speed_walk + 0.001):
                # First-transition fire only. Subsequent drags past the cap
                # don't re-fire (avoids spam on a multi-drag movement).
                # If the GM clicks the chip to reset movement to 0 mid-turn
                # and the player drags past again, the audit fires anew —
                # which matches the intent (a fresh overrun is a fresh
                # violation, even after a refund).
                name = combatant.get("name") or "Combatant"
                membership = (
                    db.query(CampaignMembership)
                    .filter(CampaignMembership.campaign_id == campaign_id,
                            CampaignMembership.user_id == user.id)
                    .first()
                )
                player_color = (
                    membership.color if membership and membership.color
                    else (campaign.gm_color if user.id == campaign.gm_user_id else None)
                )
                await hub.broadcast(campaign_id, {
                    "type": "feature_used",
                    "data": {
                        "character_id": combatant.get("char_id"),
                        "character_name": name,
                        "user_color": player_color,
                        "feature_name": "⚠ Movement overrun",
                        "feature_desc": f"{name} moved {round(post_total, 1)}/{int(speed_walk)} ft this turn (strict action economy).",
                        "source": "movement-overrun",
                        "remaining": 0,
                        "max": 0,
                        "over_budget": True,
                        "over_budget_slot": "",
                    },
                })

    return {
        "ok": True,
        "distance_ft": distance_ft,
        # v2.158.51 — Relentless Avenger applied to this move (OAs
        # suppressed + buff consumed). False on every other move.
        "relentless_avenger_applied": _ra_applied,
        # v2.66.0 — F1 OA: surface trigger advisories on the move
        # response too so harness tests + future client UI can assert
        # on them without watching the WS broadcast.
        "opportunity_attack_triggers": [
            {
                "watcher_combatant_id": t.get("watcher_combatant_id"),
                "watcher_name": t.get("watcher_name"),
                "watcher_char_id": t.get("watcher_char_id"),
                "watcher_token_id": t.get("watcher_token_id"),
                "watcher_reach_ft": t.get("watcher_reach_ft"),
                "trigger_type": t.get("trigger_type") or "exit",
                # v2.99.60 — see /token/move 409 comment for shape.
                "path_crossed_ft": t.get("path_crossed_ft"),
            }
            for t in oa_triggers
        ],
    }


@router.post("/api/campaign/{campaign_id}/force_move")
async def force_move(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.432 — Phase 6.2 of docs/plans/movement-and-summons.md:
    server-side forced movement. Pushes (or pulls) a target combatant's
    token ``distance_ft`` along the line from a source combatant (away by
    default; ``pull: true`` toward), via ``_force_move`` — the primitive
    the push/pull features (Pushing Attack, Thorn Whip, Thunderwave, …)
    call after their save resolves.

    Body: ``{target_combatant_id, distance_ft, source_combatant_id?,
    pull?}``. Requires an active map with a grid + a token for the target
    (off-grid → ``moved: false``). Bypasses the speed cap + OA check
    (forced move is involuntary).
    """
    body = await request.json()
    target_id = str(body.get("target_combatant_id") or "").strip()
    if not target_id:
        raise HTTPException(400, "target_combatant_id is required")
    try:
        distance_ft = float(body.get("distance_ft") or 0)
    except (TypeError, ValueError):
        distance_ft = 0.0
    if distance_ft <= 0:
        raise HTTPException(400, "distance_ft must be > 0")
    source_id = str(body.get("source_combatant_id") or "").strip() or None
    pull = bool(body.get("pull"))

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    target = _lookup_combatant(campaign_id, target_id)
    if target is None:
        raise HTTPException(404, "target_combatant not in battle")
    source = _lookup_combatant(campaign_id, source_id) if source_id else None

    result = await _force_move(
        db, campaign_id, target, distance_ft,
        source_combatant=source, pull=pull,
    )
    return {"ok": True, **result}


@router.post("/api/campaign/{campaign_id}/use_dash")
async def use_dash(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.79 — Dash audit broadcast.

    The client-side ``window._dashCombatant`` helper (Battle IIFE in
    ``tabletop.html``) marks the action chip + extends
    ``economy.dash_bonus_ft`` directly on the in-browser battle dict
    and pushBattles the change so other clients pick it up via the
    standard battle_update path. This endpoint adds the chat-log
    audit: a single ``feature_used`` broadcast naming who Dashed +
    how many feet the bonus grants. Pure announcement — no
    server-side state is mutated (the chip flip + dash_bonus_ft are
    already in hub state by the time this fires).

    Body: ``{combatant_id, character_id?, grant_ft}``.
    """
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    body = await request.json()
    combatant_id = (body.get("combatant_id") or "").strip() or None
    character_id_raw = body.get("character_id")
    try:
        character_id = int(character_id_raw) if character_id_raw else None
    except (TypeError, ValueError):
        character_id = None
    try:
        grant_ft = int(body.get("grant_ft") or 0)
    except (TypeError, ValueError):
        grant_ft = 0

    # Resolve the dasher's display name. PC: Character row name.
    # NPC: combatant.name from hub state. Fallback: "Combatant".
    dasher_name = "Combatant"
    if character_id:
        char = db.query(Character).filter(
            Character.id == character_id,
            Character.campaign_id == campaign_id,
        ).first()
        if char:
            dasher_name = char.name
    elif combatant_id:
        _state = hub.get_battle(campaign_id) or {}
        for _c in (_state.get("combatants") or []):
            if _c.get("id") == combatant_id:
                dasher_name = _c.get("name") or dasher_name
                break

    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": character_id,
            "character_name": dasher_name,
            "feature_name": "🏃 Dash",
            "feature_desc": (
                f"{dasher_name} took the Dash action. Movement cap "
                f"extends by +{grant_ft} ft this turn."
                if grant_ft > 0
                else f"{dasher_name} took the Dash action."
            ),
            "source": "dash-action",
            "grant_ft": grant_ft,
        },
    })

    # v2.100.3 — propagate Dash to the authoritative hub battle state
    # so the +grant_ft movement-cap bonus survives the GM's next
    # battle_update (which players adopt via a wholesale `battle =
    # msg.data` replace). Pre-v2.100.3 the client `_dashCombatant`
    # helper only mutated the dasher's LOCAL battle dict + called
    # `pushBattle()` — which is a no-op for non-GM clients
    # (`if (!IS_GM) return`). So a player's Dash bonus lived only in
    # their browser and got wiped the instant any battle_update
    # arrived (e.g. the GM's pushBattle after processing the very
    # move the player just made), silently reverting the Mov chip cap
    # to base speed and making the dash-extended movement read as
    # "over". Marking the action slot + dash_bonus_ft here (and
    # broadcasting `economy_update`, which BOTH the GM and players
    # apply surgically without a wholesale replace) makes the bonus
    # authoritative and durable. dash_bonus_ft is sent as an ABSOLUTE
    # value so the client set is idempotent under replay / reorder.
    new_dash_bonus = None
    state = hub.get_battle(campaign_id)
    if state:
        target = None
        for c in state.get("combatants") or []:
            if character_id is not None and c.get("char_id") == character_id:
                target = c
                break
            if combatant_id is not None and c.get("id") == combatant_id:
                target = c
                break
        if target is not None:
            economy = target.get("economy")
            if not isinstance(economy, dict):
                economy = {
                    "action": False, "bonus": False,
                    "reaction": False, "movement": 0, "dash_bonus_ft": 0,
                }
                target["economy"] = economy
            economy["action"] = True
            prior = economy.get("dash_bonus_ft") or 0
            prior_ft = float(prior) if isinstance(prior, (int, float)) else 0.0
            new_dash_bonus = prior_ft + float(max(0, grant_ft))
            economy["dash_bonus_ft"] = new_dash_bonus
            hub.set_battle(campaign_id, state)
            await hub.broadcast(campaign_id, {
                "type": "economy_update",
                "data": {
                    "character_id": target.get("char_id"),
                    "combatant_id": target.get("id"),
                    "slot": "action",
                    "used": True,
                    "dash_bonus_ft": new_dash_bonus,
                },
            })

    return {"ok": True, "grant_ft": grant_ft, "dash_bonus_ft": new_dash_bonus}


@router.post("/api/campaign/{campaign_id}/use_eldritch_sight")
async def use_eldritch_sight(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.138 — Eldritch Sight (Warlock Lv 2+ invocation).

    RAW (PHB p.110): "You can cast Detect Magic at will, without
    expending a spell slot."

    v1 ships the audit broadcast + invocation gate (mirror of
    /use_devils_sight + /use_mask_of_many_faces). Detect Magic's
    full mechanical effect (see auras of magical sources within
    30 ft for 10 min, concentration) isn't modeled by SimpleVTT
    today — there's no "magic aura" map layer. The endpoint
    broadcasts the cast so the chat log records when Magnus is
    scanning for magic.

    Body: ``{character_id}``.

    Validation:
      - Caller has `eldritch-invocation-eldritch-sight` on feats
      - 403 when not the GM and not the caster's owner
    """
    body = await request.json()
    char_id_raw = body.get("character_id")
    try:
        char_id = int(char_id_raw) if char_id_raw else 0
    except (TypeError, ValueError):
        char_id = 0
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Caster not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_eldritch_invocation(sheet, "eldritch-sight"):
        return JSONResponse(status_code=409, content={
            "error": "missing_invocation",
            "invocation": "eldritch-sight",
        })

    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "feature_name": "🔮 Detect Magic (Eldritch Sight)",
            "feature_desc": (
                f"{char.name} casts Detect Magic at will. Sees the "
                f"auras of magical effects within 30 ft for up to "
                f"10 minutes (concentration)."
            ),
            "source": "eldritch-sight",
            "range_ft": 30,
            "duration_rounds": 100,  # 10 minutes at 6s/round
        },
    })

    return {
        "ok": True,
        "character_id": char.id,
        "character_name": char.name,
        "range_ft": 30,
        "duration_rounds": 100,
    }


@router.post("/api/campaign/{campaign_id}/use_ascendant_step")
async def use_ascendant_step(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.141 — Ascendant Step (Warlock Lv 9+ invocation).

    RAW (PHB p.110): "Prerequisite: 9th level. You can cast Levitate
    on yourself at will, without expending a spell slot or material
    components."

    v1 ships the audit broadcast + invocation gate (mirror of
    /use_eldritch_sight + /use_devils_sight). The full mechanical
    effect (token-on-map vertical position, 20-ft altitude cap,
    concentration up to 10 min) isn't modeled — SimpleVTT's map
    layer is 2D, so vertical position is narrative. The endpoint
    broadcasts the cast so the chat log records when the warlock
    declares they're floating.

    Body: ``{character_id}``.

    Validation:
      - Caller has `eldritch-invocation-ascendant-step` on feats
      - 403 when not the GM and not the caster's owner
    """
    body = await request.json()
    char_id_raw = body.get("character_id")
    try:
        char_id = int(char_id_raw) if char_id_raw else 0
    except (TypeError, ValueError):
        char_id = 0
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Caster not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_eldritch_invocation(sheet, "ascendant-step"):
        return JSONResponse(status_code=409, content={
            "error": "missing_invocation",
            "invocation": "ascendant-step",
        })

    # v2.147.0 — install a levitate buff carrying a small fly speed
    # (was announce-only). RAW Levitate is vertical-only ("rise or fall
    # up to 20 ft per turn"), so `fly_speed_ft = 10` records the
    # mechanical "you can move vertically each round" without
    # over-claiming a horizontal fly speed; SimpleVTT's 2D map keeps
    # altitude narrative-only per the v2.99.141 ship note. Concentration
    # per RAW. Mirrors the v2.99.459 Stormborn shape; install requires
    # an active battle.
    fly_speed_ft = 10
    buff_installed = await _install_buff(campaign_id, char.id, {
        "key": "ascendant-step-levitate",
        "name": "Levitate (Ascendant Step)",
        "icon": "🪶",
        "duration_rounds": 100,
        "duration_max": 100,
        "concentration": True,
        "source_char_id": char.id,
        "effects": {"fly_speed_ft": fly_speed_ft},
        "desc": (
            f"Levitates up to 20 ft. Vertical-only per RAW. "
            f"Concentration up to 10 min. (Warlock Lv 9 Ascendant "
            f"Step invocation.)"
        ),
    })
    if buff_installed:
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "feature_name": "🪶 Levitate (Ascendant Step)",
            "feature_desc": (
                f"{char.name} casts Levitate on themselves at will. "
                f"Rises up to 20 ft for up to 10 minutes "
                f"(concentration)."
            ),
            "source": "ascendant-step",
            "altitude_ft": 20,
            "duration_rounds": 100,  # 10 minutes at 6s/round
            "fly_speed_ft": fly_speed_ft,
            "buff_installed": buff_installed,
        },
    })

    return {
        "ok": True,
        "character_id": char.id,
        "fly_speed_ft": fly_speed_ft,
        "buff_installed": buff_installed,
        "character_name": char.name,
        "altitude_ft": 20,
        "duration_rounds": 100,
    }


