def _str_disadvantage_buff_label(
    campaign_id: int, char_id: "int | None", marker: str,
) -> "tuple[str, str]":
    """v2.199.0 — inverse of `_str_advantage_buff_label`: find the
    active buff granting STR ``marker`` disadvantage (``str_check`` /
    ``str_save``) and return its (name, icon). Falls back to
    ("Diminution", "🤏"). Used by the disadvantage broadcast so the
    chat copy names the real source.
    """
    state = hub.get_battle(campaign_id)
    if state and char_id:
        for c in state.get("combatants") or []:
            if c.get("char_id") != char_id:
                continue
            for b in (c.get("buffs") or []):
                if not isinstance(b, dict):
                    continue
                effects = b.get("effects")
                if not isinstance(effects, dict):
                    continue
                dis = effects.get("disadvantage_on") or []
                if isinstance(dis, list) and marker in dis:
                    return (
                        str(b.get("name") or "Diminution"),
                        str(b.get("icon") or "🤏"),
                    )
            break
    return ("Diminution", "🤏")


_ABILITY_FULL_NAME = {
    "str": "Strength", "dex": "Dexterity", "con": "Constitution",
    "int": "Intelligence", "wis": "Wisdom", "cha": "Charisma",
}


async def _broadcast_ability_disadvantage(
    campaign_id: int, char: "Character | None", marker: str,
) -> None:
    """v2.347.0 — generic companion broadcast for
    `_pc_has_ability_disadvantage`. Names the source buff (Diminution,
    Staff of Withering, …) and the affected roll (e.g. "disadvantage on
    CON save") in the chat card. ``marker`` is ``"{ability}_check"`` /
    ``"{ability}_save"``.
    """
    if not char:
        return
    marker = (marker or "").strip().lower()
    ability = marker.split("_")[0] if "_" in marker else marker
    kind = "save" if marker.endswith("_save") else "check"
    full = _ABILITY_FULL_NAME.get(ability, ability.upper())
    label, icon = _str_disadvantage_buff_label(campaign_id, char.id, marker)
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": char.color,
            "feature_name": f"{icon} {label} — disadvantage on {full} {kind}",
            "feature_desc": (
                f"{char.name} has {label}: disadvantage on the {full} "
                f"{'saving throw' if kind == 'save' else 'ability / skill check'}."
            ),
            "source": f"disadvantage-{marker}",
        },
    })


async def _broadcast_str_check_disadvantage(
    campaign_id: int, char: "Character | None",
) -> None:
    """v2.199.0 — back-compat wrapper; delegates to the v2.347.0 generic
    `_broadcast_ability_disadvantage` with the ``str_check`` marker."""
    await _broadcast_ability_disadvantage(campaign_id, char, "str_check")


def _target_condition_immune(
    target_sheet: dict, buff_key: str,
) -> bool:
    """v2.99.128 — condition immunity engine. Returns True when the
    target's ``condition_immunities`` list (sheet OR template) or
    any active buff's ``effects.condition_immunity_to`` list
    contains the given buff key.

    Mirrors the damage immunity ("all" wildcard, per-type matches)
    pattern but for the condition layer instead. Sheet-level reads
    the canonical RAW condition_immunities list (Constructs are
    immune to charmed/frightened/paralyzed/petrified/poisoned, etc.).
    Buff-level reads dict-shaped buff effects.

    The check is case-insensitive: sheet/template entries phrased as
    ``"Paralyzed"`` or ``"PARALYZED"`` match a buff with
    ``key == "paralyzed"``.

    Returns False on missing sheet, missing buff_key, or no match.
    Callers (``_install_buff`` + ``_install_buff_on_combatant_id``)
    short-circuit the install when this returns True.
    """
    if not buff_key or not target_sheet:
        return False
    buff_key_l = str(buff_key).strip().lower()
    if not buff_key_l:
        return False
    sheet_cond = target_sheet.get("condition_immunities") or []
    if isinstance(sheet_cond, str):
        sheet_cond = [p.strip() for p in sheet_cond.split(",") if p.strip()]
    if isinstance(sheet_cond, list):
        normalized = {(str(r) or "").strip().lower() for r in sheet_cond}
        if "all" in normalized or buff_key_l in normalized:
            return True
    # v2.288.0 — equipped-item condition immunity (Periapt of Proof against
    # Poison → poisoned). Aggregated from equipped(+attuned) inventory items
    # via `_equipped_item_effects`; mirrors the item-resistance/immunity
    # bridges. Read after the sheet-level list, before buffs.
    try:
        _item_cond = _equipped_item_effects(target_sheet).get("condition_immunity_to") or []
    except Exception:
        _item_cond = []
    _item_cond_set = {(str(r) or "").strip().lower() for r in _item_cond}
    if "all" in _item_cond_set or buff_key_l in _item_cond_set:
        return True
    for b in target_sheet.get("_buffs_active") or []:
        if not isinstance(b, dict):
            continue
        effects = b.get("effects")
        if not isinstance(effects, dict):
            continue
        immune_list = effects.get("condition_immunity_to") or []
        if not isinstance(immune_list, list):
            continue
        immune_set = {
            (str(r) or "").strip().lower() for r in immune_list
        }
        if "all" in immune_set or buff_key_l in immune_set:
            return True
    return False


def _target_condition_immune_npc(
    combatant: dict, buff_key: str, db: Session,
) -> bool:
    """v2.99.128 — NPC mirror of ``_target_condition_immune``. Reads
    the TokenTemplate's ``sheet.condition_immunities`` list +
    combatant buff-level ``effects.condition_immunity_to``. Same
    case-insensitive matching + "all" wildcard semantics.
    """
    if not buff_key or not combatant:
        return False
    buff_key_l = str(buff_key).strip().lower()
    if not buff_key_l:
        return False
    tmpl_id = combatant.get("token_template_id")
    if tmpl_id:
        tmpl = db.query(TokenTemplate).filter(TokenTemplate.id == tmpl_id).first()
        if tmpl and (tmpl.sheet or {}):
            sheet_cond = (tmpl.sheet or {}).get("condition_immunities") or []
            if isinstance(sheet_cond, str):
                sheet_cond = [
                    p.strip() for p in sheet_cond.split(",") if p.strip()
                ]
            if isinstance(sheet_cond, list):
                normalized = {
                    (str(r) or "").strip().lower() for r in sheet_cond
                }
                if "all" in normalized or buff_key_l in normalized:
                    return True
    for b in (combatant.get("buffs") or []):
        if not isinstance(b, dict):
            continue
        effects = b.get("effects")
        if not isinstance(effects, dict):
            continue
        immune_list = effects.get("condition_immunity_to") or []
        if not isinstance(immune_list, list):
            continue
        immune_set = {
            (str(r) or "").strip().lower() for r in immune_list
        }
        if "all" in immune_set or buff_key_l in immune_set:
            return True
    return False


def _pc_has_heroism_frightened_immunity(
    campaign_id: int, char_id: int,
) -> bool:
    """v2.97.43 — closes one of the v2.97.37-filed Heroism mechanical
    halves. Returns True when the saver has a buff carrying
    ``effects.condition_immunity_frightened: True`` — the canonical
    marker for the Heroism buff in ``_SPELL_BUFF_MAP`` (and any
    future buff with the same opt-in). Sibling to
    ``_pc_has_rage_active_buff`` but keyed on the effects dict
    rather than a hardcoded buff key, so additional buffs with the
    same immunity (Calm Emotions, Bless Sanctuary, etc.) fold in
    by just adding the marker to their catalog entry.
    """
    for b in _get_buffs(campaign_id, int(char_id)) or []:
        if not isinstance(b, dict):
            continue
        effects = b.get("effects")
        if not isinstance(effects, dict):
            continue
        if effects.get("condition_immunity_frightened") is True:
            return True
    return False


def _saver_pfeag_save_advantage(
    campaign_id: int,
    saver_char_id: int | None,
    source_caster_creature_type: str,
    cond_key: str,
) -> bool:
    """v2.97.50 — closes the third and final v2.97.46-filed PFE&G
    hook. Returns True when:
    - the saver carries PFE&G AND
    - the source caster's creature type is in the buff's
      ``effects.pfeag_protected_types`` list AND
    - the cond_key being resolved is one of the PFE&G-protected
      install conditions (charmed / frightened — RAW also lists
      possessed; not currently modeled).

    The save-roll construction site flips the base_expression
    from ``1d20`` to ``2d20kh1`` (advantage). RAW (PHB p.270): "If
    the target is already charmed, frightened, or possessed by such
    a creature, the target has advantage on any new saving throw
    against the relevant effect." Our codebase doesn't have a
    distinct "ongoing-save" flow yet; the broader read here applies
    the advantage to the install-time save as well, which composes
    safely with the v2.97.49 gate (gate fires AFTER the save fails,
    so the advantage just makes the save more likely to succeed and
    skip the install entirely).
    """
    if not saver_char_id or not source_caster_creature_type:
        return False
    if cond_key not in ("charmed", "frightened"):
        return False
    return _pc_has_pfeag_against_type(
        campaign_id, int(saver_char_id), source_caster_creature_type,
    )


def _pc_has_pfeag_against_type(
    campaign_id: int,
    target_char_id: int,
    caster_creature_type: str,
) -> bool:
    """v2.97.49 — closes the second of three v2.97.46-filed PFE&G
    mechanical hooks. char_id variant of
    ``_target_pfeag_blocks_attacker_type`` (which takes combatant_id)
    for use in /respond's condition-install gate. Reads the target
    PC's buff list via ``_get_buffs`` and checks the source caster's
    creature type against the PFE&G ``pfeag_protected_types`` list.
    Used to short-circuit Charmed / Frightened installs when the
    spell's source is a protected creature type.
    """
    if not target_char_id or not caster_creature_type:
        return False
    for b in _get_buffs(campaign_id, int(target_char_id)) or []:
        if not isinstance(b, dict):
            continue
        # v2.158.10 — accept the Devotion Paladin Lv 15+ Purity of
        # Spirit permanent class-feature buff alongside the cast
        # spell. Both carry the same pfeag_* effects payload.
        if b.get("key") not in (
            "protection-from-evil-and-good", "purity-of-spirit",
        ):
            continue
        effects = b.get("effects")
        if not isinstance(effects, dict):
            continue
        protected = effects.get("pfeag_protected_types") or []
        if not isinstance(protected, list):
            continue
        if caster_creature_type in [str(t).lower() for t in protected]:
            return True
    return False


