@router.post("/api/campaign/{campaign_id}/use_improved_war_magic")
async def use_improved_war_magic(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.269 — Phase E.2 Phase 4b of the v2.99.193 phased
    completion plan. Improved War Magic (Eldritch Knight Lv 18+,
    PHB p.74): "Starting at 18th level, when you use your action
    to cast a spell, you can make one weapon attack as a bonus
    action."

    Body: ``{character_id, override?}``. Same shape as Phase 2
    War Magic but the gate is "Lv 1+ spell" instead of cantrip
    (GM-tracked); validates EK Lv 18+ + Phase 4 bonus chip.

    **CLOSES PHASE E.2.** With this commit + sibling Arcane
    Charge, all 4 phases of docs/plans/eldritch-knight.md are
    shipped.

    v2.158.12 — Phase 8 Lv-18 tier. Already chip-marked via
    `_mark_battle_economy` (so the table flagged this `tracked`
    pre-Phase-8); the Phase 8 enhancement installs a permanent
    `improved-war-magic-active` flag buff so the future War
    Magic spell-cast flow has an explicit parameter contract
    for the Lv-1+ upgrade:
      * `effects.improved_war_magic_active: True`
      * `effects.improved_war_magic_min_spell_level: 1`
    v2.158.40 — Phase 2 (shipped): `/use_war_magic` reads the buff
    via `_pc_improved_war_magic_min_level` and, when present, widens
    the bonus-action weapon-attack prerequisite from cantrips only to
    any Lv 1+ spell — surfacing `improved_war_magic` + `spell_min_level`
    on its response + `feature_used` broadcast (and relabeling the
    feature "Improved War Magic"). Before Phase 8 the Lv-1+-not-cantrip
    gate was implicit (the chip mark just claimed the bonus action was
    spent).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Fighter character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_eldritch_knight(sheet, 18):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "eldritch knight fighter lv 18+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _fighter_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "improved-war-magic",
            "label": "Improved War Magic",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "bonus")

    # v2.158.12 — install the parameter-flag buff so the future
    # War Magic / `/cast_spell` flow has an explicit Lv-1+
    # threshold to look up. Idempotent on re-press via key
    # dedupe.
    buff_installed = await _install_buff(campaign_id, char.id, {
        "key": "improved-war-magic-active",
        "name": "⚡ Improved War Magic",
        "icon": "⚡",
        "duration_rounds": 100000,
        "duration_max": 100000,
        "permanent": True,
        "concentration": False,
        "source_char_id": char.id,
        "effects": {
            "improved_war_magic_active": True,
            "improved_war_magic_min_spell_level": 1,
        },
        "desc": (
            f"{char.name} can cast a Lv 1+ spell with action and "
            f"make one weapon attack as a bonus action. (Eldritch "
            f"Knight Lv 18+ passive permanent. v2.158.40 Phase 2: "
            f"`/use_war_magic` reads these flags to widen the "
            f"prerequisite to any Lv 1+ spell.)"
        ),
    })
    if buff_installed:
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": "⚡ Improved War Magic — bonus weapon attack",
            "feature_desc": (
                f"{char.name} invokes Improved War Magic: after "
                f"casting a Lv 1+ spell with your action, make one "
                f"weapon attack as a bonus action. (Eldritch Knight "
                f"Lv 18+ class feature.)"
            ),
            "source": "improved-war-magic",
            "over_budget": was_used,
            "over_budget_slot": "bonus" if was_used else "",
            "buff_installed": buff_installed,
        },
    })

    return {
        "ok": True,
        "feature": "improved-war-magic",
        "over_budget": was_used,
        "buff_installed": buff_installed,
    }


@router.post("/api/campaign/{campaign_id}/use_eldritch_strike")
async def use_eldritch_strike(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.268 — Phase E.2 Phase 3 of the v2.99.193 phased
    completion plan. Eldritch Strike (Eldritch Knight Lv 10+,
    PHB p.74): "When you hit a creature with a weapon attack,
    that creature has disadvantage on the next saving throw it
    makes against a spell you cast before the end of your next
    turn."

    Body: ``{character_id, target_combatant_id, override?}``.

    Validates Eldritch Knight Lv 10+ + target in active battle.
    Installs `eldritch-strike-target` buff on the target with
    `effects.save_disadvantage_against_caster_id: <ek_id>`
    (10-round duration). v1 ships the buff install + announce;
    the consumer (save-roll site reading the flag + dropping
    the buff after one consume) is filed for follow-up.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    target_combatant_id = (str(body.get("target_combatant_id") or "")).strip()
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if not target_combatant_id:
        raise HTTPException(400, "target_combatant_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Fighter character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_eldritch_knight(sheet, 10):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "eldritch knight fighter lv 10+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _fighter_level_from_sheet(sheet),
        })

    state = hub.get_battle(campaign_id) or {}
    target_char_id = None
    target_name = ""
    for c in (state.get("combatants") or []):
        if c.get("id") == target_combatant_id:
            target_char_id = c.get("char_id")
            target_name = c.get("name") or ""
            break
    if target_char_id is None:
        # Allow NPC combatants (char_id is None) — install on the
        # combatant key directly. Re-locate.
        found = False
        for c in (state.get("combatants") or []):
            if c.get("id") == target_combatant_id:
                found = True
                break
        if not found:
            return JSONResponse(status_code=404, content={
                "error": "target_not_in_battle",
                "target_combatant_id": target_combatant_id,
            })

    es_buff = {
        "key": "eldritch-strike-target",
        "name": f"Eldritch Strike — disadvantage on save vs {char.name}'s spell",
        "icon": "🗡️",
        "duration_rounds": 10,
        "duration_max": 10,
        "concentration": False,
        "source": "eldritch-strike",
        "source_char_id": char.id,
        "effects": {
            "save_disadvantage_against_caster_id": char.id,
            "consume_on_first_save": True,
        },
        "desc": (
            f"Disadvantage on the next saving throw vs a spell "
            f"cast by {char.name} before end of {char.name}'s "
            f"next turn."
        ),
    }
    if target_char_id is not None:
        await _install_buff(campaign_id, int(target_char_id), es_buff)
        _mirror_buffs_to_sheet(
            db, int(target_char_id),
            _get_buffs(campaign_id, int(target_char_id)),
        )

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🗡️ Eldritch Strike — {target_name or 'target'} "
                f"disadvantage on next save"
            ),
            "feature_desc": (
                f"{char.name} marks {target_name or 'the target'} "
                f"with Eldritch Strike: disadvantage on the next "
                f"saving throw vs a spell {char.name} casts before "
                f"end of next turn. (Eldritch Knight Lv 10+ class "
                f"feature.)"
            ),
            "source": "eldritch-strike",
            "target_combatant_id": target_combatant_id,
            "target_char_id": target_char_id,
            "target_name": target_name,
        },
    })

    return {
        "ok": True,
        "feature": "eldritch-strike",
        "target_combatant_id": target_combatant_id,
        "target_char_id": target_char_id,
        "target_name": target_name,
        "buff_installed": target_char_id is not None,
    }


def _pc_improved_war_magic_min_level(sheet: "dict | None") -> int:
    """v2.158.40 — Phase 2 read gate for the v2.158.12 Improved War
    Magic buff (Eldritch Knight Fighter Lv 18+, PHB p.74): "when you
    use your action to cast a spell, you can make one weapon attack as
    a bonus action." This widens the Lv-7 War Magic prerequisite from
    cantrips only to any spell.

    Returns the minimum spell level that qualifies for the bonus-action
    weapon attack when the PC carries an active `improved-war-magic-
    active` buff (1 by RAW — any Lv 1+ spell); 0 when absent (the base
    Lv-7 War Magic limit of cantrips only). Reads the mirrored sheet
    buff (`_buffs_active`) — same source the other Phase-8 read sites
    use — so it works off `/use_war_magic`'s already-loaded `char.sheet`.
    """
    if not isinstance(sheet, dict):
        return 0
    for b in (sheet.get("_buffs_active") or []):
        if not isinstance(b, dict):
            continue
        if (str(b.get("key") or "").strip().lower()
                != "improved-war-magic-active"):
            continue
        eff = b.get("effects") or {}
        if not isinstance(eff, dict):
            continue
        if not eff.get("improved_war_magic_active"):
            continue
        try:
            return int(eff.get("improved_war_magic_min_spell_level") or 1)
        except (TypeError, ValueError):
            return 1
    return 0


@router.post("/api/campaign/{campaign_id}/use_war_magic")
async def use_war_magic(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.267 — Phase E.2 Phase 2 of the v2.99.193 phased
    completion plan. War Magic (Eldritch Knight Lv 7+, PHB p.74):
    "Beginning at 7th level, when you use your action to cast a
    cantrip, you can make one weapon attack as a bonus action."

    Body: ``{character_id, override?}``.

    Validates Eldritch Knight Lv 7+ + Phase 4 bonus chip. v1
    ships as announce-only — the cantrip cast prerequisite is
    GM-tracked; future commit can hook /cast_spell post-cast
    for cantrips to stamp a per-turn flag and have /attack
    consume it via `as_war_magic_bonus: true` body field.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Fighter character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_eldritch_knight(sheet, 7):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "eldritch knight fighter lv 7+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _fighter_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "war-magic",
            "label": "War Magic",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "bonus")

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color

    # v2.158.40 — Phase 2 read site for the v2.158.12 Improved War
    # Magic buff. A Lv 18+ EK carrying `improved-war-magic-active` may
    # trigger the bonus-action weapon attack after casting ANY Lv 1+
    # spell (not just a cantrip); surface the widened prerequisite on
    # the response + broadcast so the client describes it correctly.
    iwm_min_level = _pc_improved_war_magic_min_level(sheet)
    if iwm_min_level > 0:
        feature_desc = (
            f"{char.name} invokes Improved War Magic: after casting a "
            f"cantrip OR any Lv {iwm_min_level}+ spell with your action, "
            f"make one weapon attack as a bonus action. (Eldritch Knight "
            f"Lv 18+ class feature.) Roll the attack via the normal path."
        )
    else:
        feature_desc = (
            f"{char.name} invokes War Magic: after casting a "
            f"cantrip with your action, make one weapon attack "
            f"as a bonus action. (Eldritch Knight Lv 7+ class "
            f"feature.) Roll the attack via the normal path."
        )

    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                "⚡ Improved War Magic — bonus weapon attack"
                if iwm_min_level > 0
                else "⚡ War Magic — bonus weapon attack"
            ),
            "feature_desc": feature_desc,
            "source": "war-magic",
            "over_budget": was_used,
            "over_budget_slot": "bonus" if was_used else "",
            "improved_war_magic": iwm_min_level > 0,
            "spell_min_level": iwm_min_level,
        },
    })

    return {
        "ok": True,
        "feature": "war-magic",
        "over_budget": was_used,
        "improved_war_magic": iwm_min_level > 0,
        "spell_min_level": iwm_min_level,
    }


@router.post("/api/campaign/{campaign_id}/use_weapon_bond")
async def use_weapon_bond(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.232 — Phase E.2 Phase 1 of the v2.99.193 phased
    completion plan. Weapon Bond (Eldritch Knight Lv 3+, PHB
    p.74): "At 3rd level, you learn a ritual that creates a
    magical bond between yourself and one weapon... While the
    weapon is bonded to you, you can't be disarmed of that
    weapon unless you are incapacitated. If it is on the same
    plane of existence, you can summon that weapon as a bonus
    action on your turn, causing it to teleport instantly to
    your hand. You can have up to two bonded weapons, but can
    summon only one at a time with your bonus action."

    Body: ``{character_id, weapon_index, override?}``.

    Validates Eldritch Knight Lv 3+. Reads the weapon's slug or
    name from ``sheet.inventory[weapon_index]``, appends to
    ``sheet.bonded_weapons`` (list[str], max 2), persists,
    broadcasts. 409 ``cap_reached`` if already at 2 bonded
    weapons.

    v1 ships the bond persistence + announce. The "can't be
    disarmed" half is filed (no disarm action in SimpleVTT
    today); the bonus-action summon is filed (would need an
    "is the weapon equipped?" check on attack).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    weapon_index_raw = body.get("weapon_index")
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if weapon_index_raw is None:
        raise HTTPException(400, "weapon_index is required")
    try:
        weapon_index = int(weapon_index_raw)
    except (TypeError, ValueError):
        raise HTTPException(400, "weapon_index must be an integer")
    if weapon_index < 0:
        raise HTTPException(400, "weapon_index must be >= 0")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Fighter character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_eldritch_knight(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "eldritch knight fighter lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _fighter_level_from_sheet(sheet),
        })

    inventory = list(sheet.get("inventory") or [])
    if weapon_index >= len(inventory):
        raise HTTPException(
            400,
            f"weapon_index {weapon_index} out of range "
            f"(inventory has {len(inventory)} items)",
        )
    item = inventory[weapon_index] or {}
    if (item.get("type") or "").lower() != "weapon":
        raise HTTPException(
            400,
            f"inventory[{weapon_index}] is not a weapon",
        )
    weapon_name = (item.get("name") or "").strip() or f"item-{weapon_index}"
    weapon_slug = (item.get("_slug") or weapon_name.lower().replace(" ", "-"))

    bonded = list(sheet.get("bonded_weapons") or [])
    if weapon_slug in bonded:
        # Idempotent re-bond — return current list.
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "character_name": char.name,
                "feature_name": f"🔗 Weapon Bond — {weapon_name} (already bonded)",
                "feature_desc": (
                    f"{char.name}'s bond with {weapon_name} is "
                    f"already active. No change."
                ),
                "source": "weapon-bond",
                "weapon_slug": weapon_slug,
                "weapon_name": weapon_name,
                "bonded_weapons": bonded,
                "already_bonded": True,
            },
        })
        return {
            "ok": True,
            "feature": "weapon-bond",
            "weapon_slug": weapon_slug,
            "bonded_weapons": bonded,
            "already_bonded": True,
        }
    if len(bonded) >= 2:
        return JSONResponse(status_code=409, content={
            "error": "cap_reached",
            "label": "Weapon Bond",
            "max": 2,
            "current": len(bonded),
        })

    bonded.append(weapon_slug)
    sheet["bonded_weapons"] = bonded

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🔗 Weapon Bond — {weapon_name}"
            ),
            "feature_desc": (
                f"{char.name} completes the hour-long ritual to "
                f"bond {weapon_name}. The weapon can be summoned "
                f"as a bonus action while on the same plane and "
                f"can't be disarmed unless incapacitated. "
                f"(Eldritch Knight Lv 3+ class feature.)"
            ),
            "source": "weapon-bond",
            "weapon_slug": weapon_slug,
            "weapon_name": weapon_name,
            "bonded_weapons": bonded,
            "already_bonded": False,
        },
    })

    return {
        "ok": True,
        "feature": "weapon-bond",
        "weapon_slug": weapon_slug,
        "bonded_weapons": bonded,
        "already_bonded": False,
    }


_SUPERIORITY_DIE_SIZES = {"d8", "d10", "d12"}


@router.post("/api/campaign/{campaign_id}/use_commanders_strike")
async def use_commanders_strike(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.266 — Phase E.1 Phase 3 (maneuver 16 of 16 — FINAL)
    of the v2.99.193 phased completion plan. Commander's Strike
    (Battle Master Lv 3+, PHB p.74): "When you take the Attack
    action on your turn, you can forgo one of your attacks and
    use a bonus action to direct one of your companions to
    strike. When you do so, choose a friendly creature who can
    see or hear you and expend one superiority die. That creature
    can immediately use its reaction to make one weapon attack,
    adding the superiority die to the attack's damage roll."

    Body: ``{character_id, ally_name?, override?}``. Bonus-chip
    gated. **CLOSES PHASE E.1 PHASE 3 — all 16 maneuvers
    shipped.**
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    ally_name = (str(body.get("ally_name") or "")).strip()[:80]
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Fighter character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_battle_master(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "battle master fighter lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _fighter_level_from_sheet(sheet),
        })

    resources = list(sheet.get("resources") or [])
    sd_row = None
    sd_idx = -1
    for i, r in enumerate(resources):
        if (r.get("key") or "").lower() == "superiority-dice":
            sd_row = dict(r)
            sd_idx = i
            break
    if sd_row is None:
        raise HTTPException(404, "No Superiority Dice resource on this sheet")
    sd_cur = int(sd_row.get("current") or 0)
    sd_max = int(sd_row.get("max") or 0)
    if sd_cur < 1:
        return JSONResponse(status_code=409, content={
            "error": "out_of_uses",
            "label": "Superiority Dice",
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "commanders-strike",
            "label": "Commander's Strike",
            "strict": strict,
        })

    die_size = (sheet.get("superiority_die_size") or "d8").strip().lower()
    if die_size not in _SUPERIORITY_DIE_SIZES:
        die_size = "d8"

    new_sd = sd_cur - 1
    sd_row["current"] = new_sd
    resources[sd_idx] = sd_row
    sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    try:
        extra = dice_mod.roll(f"1{die_size}").total
    except Exception:
        extra = 1

    await _mark_battle_economy(campaign_id, char.id, "bonus")
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "superiority-dice",
            "current": new_sd,
            "max": sd_max,
        },
    })

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    ally_phrase = f" → {ally_name}" if ally_name else " → ally"
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"⚔ Commander's Strike — ally free attack "
                f"+{extra} damage{ally_phrase}"
            ),
            "feature_desc": (
                f"{char.name} forgoes one attack to direct "
                f"{ally_name or 'an ally'}: that creature uses "
                f"their reaction to make one weapon attack, "
                f"adding {extra} to the damage roll. (Battle "
                f"Master Lv 3+ maneuver; {new_sd}/{sd_max} dice "
                f"remaining.)"
            ),
            "source": "commanders-strike",
            "extra_damage": extra,
            "ally_name": ally_name,
            "die_size": die_size,
            "dice_remaining": new_sd,
            "over_budget": was_used,
            "over_budget_slot": "bonus" if was_used else "",
        },
    })

    return {
        "ok": True,
        "feature": "commanders-strike",
        "extra_damage": extra,
        "ally_name": ally_name,
        "die_size": die_size,
        "dice_remaining": new_sd,
        "over_budget": was_used,
    }


