@router.post("/api/campaign/{campaign_id}/use_avatar_of_battle")
async def use_avatar_of_battle(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.296 — Phase H.1 deeper (War Domain Cleric Lv 17+)
    of the v2.99.193 phased completion plan. Avatar of Battle
    (War Domain Cleric Lv 17+, PHB p.63): "At 17th level, you
    gain resistance to bludgeoning, piercing, and slashing
    damage from nonmagical attacks."

    Body: ``{character_id, override?}``. No chip cost —
    passive permanent.

    v2.158.0 — Phase 8 first commit: install a permanent
    `avatar-of-battle` buff carrying
    `effects.resistance_to = ["nonmagical-bludgeoning",
    "nonmagical-piercing", "nonmagical-slashing"]`. The F6
    `_resistance_matches_damage` matcher (v2.63.0) already
    handles the `nonmagical-X` SRD phrasing — it skips the
    resistance when the incoming attack is flagged
    `is_magical=True` (magical weapon, spell, Ki-Empowered
    Strikes, Pact of the Blade, etc.) and applies the half
    on mundane attacks. Idempotent — the `_install_buff`
    key-dedupe path overwrites any prior install so the
    player can re-press without stacking.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Cleric character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_war_domain(sheet, 17):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "war domain cleric lv 17+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _cleric_level_from_sheet(sheet),
        })

    cleric_lv = _cleric_level_from_sheet(sheet)

    # v2.158.0 — install the resistance buff. Permanent passive per
    # RAW: huge duration_rounds + `permanent: True` flag so the
    # turn-tick decrement never expires it. The buff's
    # `effects.resistance_to` triplet is read by the PC damage
    # pipeline's `_resistance_halve` (which delegates per-entry to
    # `_resistance_matches_damage` with the attack's `is_magical`
    # flag). No concentration — passive class feature.
    buff_installed = await _install_buff(campaign_id, char.id, {
        "key": "avatar-of-battle",
        "name": "⚔️ Avatar of Battle",
        "icon": "⚔️",
        "duration_rounds": 100000,
        "duration_max": 100000,
        "permanent": True,
        "concentration": False,
        "source_char_id": char.id,
        "effects": {
            "resistance_to": [
                "nonmagical-bludgeoning",
                "nonmagical-piercing",
                "nonmagical-slashing",
            ],
        },
        "desc": (
            f"{char.name} has resistance to bludgeoning, piercing, "
            f"and slashing damage from nonmagical attacks. "
            f"(War Domain Cleric Lv 17+ passive permanent.)"
        ),
    })
    if buff_installed:
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": "⚔️ Avatar of Battle — resist nonmagical BPS",
            "feature_desc": (
                f"{char.name} has resistance to bludgeoning, "
                f"piercing, and slashing damage from nonmagical "
                f"attacks. (War Domain Cleric Lv 17+ class feature; "
                f"passive permanent.)"
            ),
            "source": "avatar-of-battle",
            "resistance_types": ["bludgeoning", "piercing", "slashing"],
            "nonmagical_only": True,
            "cleric_level": cleric_lv,
            "buff_installed": buff_installed,
        },
    })

    return {
        "ok": True,
        "feature": "avatar-of-battle",
        "resistance_types": ["bludgeoning", "piercing", "slashing"],
        "nonmagical_only": True,
        "cleric_level": cleric_lv,
        "buff_installed": buff_installed,
    }


@router.post("/api/campaign/{campaign_id}/use_improved_reaper")
async def use_improved_reaper(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.297 — Phase H.1 deeper (Death Domain Cleric Lv 17+)
    of the v2.99.193 phased completion plan. Improved Reaper
    (Death Domain Cleric Lv 17+, DMG p.97): "Starting at 17th
    level, when you cast a necromancy spell of 1st through 5th
    level that targets only one creature, the spell can
    instead target two creatures within range and within 5
    feet of each other."

    Body: ``{character_id, override?}``. No chip cost —
    passive permanent (modifies necromancy spell casts).

    v2.158.9 — Phase 8 eighth feature commit (CLOSES the Lv-17
    cleric capstone batch 6/6). Phase 1 of the standard install-
    then-deferred-read split (same shape as v2.158.3 Improved
    Duplicity). Install a permanent `improved-reaper-active`
    buff carrying the parameters Phase 2's spell-routing change
    will read:
      * `effects.improved_reaper_active: True`
      * `effects.improved_reaper_min_spell_level: 1`
      * `effects.improved_reaper_max_spell_level: 5`
      * `effects.improved_reaper_school: "necromancy"`
      * `effects.improved_reaper_max_targets: 2`
      * `effects.improved_reaper_max_target_separation_ft: 5`
    Phase 2 (deferred): `/cast_spell` reads the buff and accepts
    a second `target_combatant_id` when the spell qualifies
    (school=necromancy, level 1-5, default single-target shape).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Cleric character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_death_domain(sheet, 17):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "death domain cleric lv 17+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _cleric_level_from_sheet(sheet),
        })

    cleric_lv = _cleric_level_from_sheet(sheet)

    # v2.158.9 — install the parameter-carrying buff. Permanent
    # passive (idempotent on re-press via key dedupe). Phase 2
    # (deferred): `/cast_spell` reads `effects.improved_reaper_*`
    # off the caster's `_buffs_active` and routes a second target
    # for qualifying single-target Lv-1-5 necromancy spells.
    buff_installed = await _install_buff(campaign_id, char.id, {
        "key": "improved-reaper-active",
        "name": "💀 Improved Reaper",
        "icon": "💀",
        "duration_rounds": 100000,
        "duration_max": 100000,
        "permanent": True,
        "concentration": False,
        "source_char_id": char.id,
        "effects": {
            "improved_reaper_active": True,
            "improved_reaper_min_spell_level": 1,
            "improved_reaper_max_spell_level": 5,
            "improved_reaper_school": "necromancy",
            "improved_reaper_max_targets": 2,
            "improved_reaper_max_target_separation_ft": 5,
        },
        "desc": (
            f"{char.name}'s 1st-5th level necromancy spells that "
            f"target one creature can now target two creatures within "
            f"range and within 5 ft of each other. (Death Domain "
            f"Cleric Lv 17+ passive permanent. Phase 2: `/cast_spell` "
            f"reads these flags off `_buffs_active`.)"
        ),
    })
    if buff_installed:
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                "💀 Improved Reaper — necromancy ×2 targets (Lv 1-5)"
            ),
            "feature_desc": (
                f"{char.name}'s 1st-5th level necromancy spells that "
                f"target one creature can now target two creatures "
                f"within range and within 5 ft of each other. "
                f"(Death Domain Cleric Lv 17+ class feature; "
                f"passive permanent.)"
            ),
            "source": "improved-reaper",
            "min_spell_level": 1,
            "max_spell_level": 5,
            "school": "necromancy",
            "max_targets": 2,
            "max_target_separation_ft": 5,
            "cleric_level": cleric_lv,
            "buff_installed": buff_installed,
        },
    })

    return {
        "ok": True,
        "feature": "improved-reaper",
        "min_spell_level": 1,
        "max_spell_level": 5,
        "school": "necromancy",
        "max_targets": 2,
        "max_target_separation_ft": 5,
        "cleric_level": cleric_lv,
        "buff_installed": buff_installed,
    }


@router.post("/api/campaign/{campaign_id}/use_invoke_duplicity")
async def use_invoke_duplicity(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.158.52 — Invoke Duplicity (Trickery Domain Cleric Lv 2+,
    PHB p.62) Channel Divinity. RAW: "As an action, you create a
    perfect illusion of yourself that lasts for 1 minute, or until
    you lose your concentration ... As a bonus action on your turn,
    you can move the illusion up to 30 feet ... but it must remain
    within 120 feet of you ... when both you and your illusion are
    within 5 feet of a creature that can see the illusion, you have
    advantage on attack rolls against that creature."

    Body: ``{character_id, override?}``. Costs 1 Channel Divinity use
    + an action; installs a 1-minute (10-round) concentration
    ``invoke-duplicity-active`` buff.

    This is the **Phase 2 read site** for the v2.158.3
    ``improved-duplicity`` buff (Trickery Cleric Lv 17+). RAW the
    Lv-17 upgrade raises the duplicate count from 1 to 4 (the 30-ft
    bonus move + 120-ft range are unchanged at both tiers). The
    endpoint walks the caster's combatant buffs for
    ``improved-duplicity`` and, when present, reads
    ``effects.invoke_duplicity_max_duplicates`` (4) instead of the
    Lv-2 baseline of 1 — flipping that buff from announce-only to
    consumed.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Cleric character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_trickery_domain(sheet, 2):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "trickery domain cleric lv 2+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _cleric_level_from_sheet(sheet),
        })

    resources = list(sheet.get("resources") or [])
    cd_row = None
    cd_idx = -1
    for i, r in enumerate(resources):
        if (r.get("key") or "").lower() == "channel-divinity":
            cd_row = dict(r)
            cd_idx = i
            break
    if cd_row is None:
        raise HTTPException(404, "No Channel Divinity resource on this sheet")
    cd_cur = int(cd_row.get("current") or 0)
    cd_max = int(cd_row.get("max") or 0)
    if cd_cur < 1:
        return JSONResponse(status_code=409, content={
            "error": "out_of_uses",
            "label": "Channel Divinity",
            "resource_key": "channel-divinity",
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "invoke-duplicity",
            "label": "Invoke Duplicity",
            "strict": strict,
        })

    # v2.158.52 — Phase 2 read of the v2.158.3 improved-duplicity buff.
    # Baseline Lv-2 Invoke Duplicity makes 1 duplicate; the Lv-17+
    # upgrade buff bumps it to 4 (move + range are identical at both
    # tiers, so they're read as constants here).
    max_duplicates = 1
    bonus_move_ft = 30
    max_range_ft = 120
    improved = False
    for b in _get_buffs(campaign_id, char.id):
        if (b or {}).get("key") != "improved-duplicity":
            continue
        eff = b.get("effects") or {}
        try:
            max_duplicates = int(eff.get("invoke_duplicity_max_duplicates") or 1)
        except (TypeError, ValueError):
            max_duplicates = 1
        try:
            bonus_move_ft = int(
                eff.get("invoke_duplicity_bonus_move_per_duplicate_ft") or 30
            )
        except (TypeError, ValueError):
            bonus_move_ft = 30
        try:
            max_range_ft = int(eff.get("invoke_duplicity_max_range_ft") or 120)
        except (TypeError, ValueError):
            max_range_ft = 120
        improved = True
        break

    cd_row["current"] = cd_cur - 1
    resources[cd_idx] = cd_row
    sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    cleric_lv = _cleric_level_from_sheet(sheet)
    buff_installed = await _install_buff(campaign_id, char.id, {
        "key": "invoke-duplicity-active",
        "name": "🎭 Invoke Duplicity",
        "icon": "🎭",
        "duration_rounds": 10,
        "duration_max": 10,
        "concentration": True,
        "source_char_id": char.id,
        "effects": {
            "duplicates": max_duplicates,
            "duplicate_move_ft": bonus_move_ft,
            "duplicate_max_range_ft": max_range_ft,
            "advantage_when_flanking_with_duplicate": True,
        },
        "desc": (
            f"{char.name} projects {max_duplicates} illusory "
            f"{'duplicate' if max_duplicates == 1 else 'duplicates'}. "
            f"Bonus action: move {'it' if max_duplicates == 1 else 'them'} "
            f"up to {bonus_move_ft} ft (max {max_range_ft} ft away). "
            f"Advantage on attacks vs. a creature when both you and a "
            f"duplicate are within 5 ft of it. Concentration, 1 minute."
        ),
    })
    if buff_installed:
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    await _mark_battle_economy(campaign_id, char.id, "action")
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "channel-divinity",
            "current": cd_cur - 1,
            "max": cd_max,
        },
    })

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🎭 Invoke Duplicity — {max_duplicates} "
                f"{'duplicate' if max_duplicates == 1 else 'duplicates'}"
            ),
            "feature_desc": (
                f"{char.name} creates {max_duplicates} perfect "
                f"{'illusion' if max_duplicates == 1 else 'illusions'} of "
                f"{'himself' if max_duplicates == 1 else 'themselves'} "
                f"within 30 ft. Concentration, 1 minute. "
                f"(Trickery Domain Cleric Lv 2+ Channel Divinity"
                f"{'; Improved Duplicity upgrade' if improved else ''}.)"
            ),
            "source": "invoke-duplicity",
            "duplicates": max_duplicates,
            "bonus_move_per_duplicate_ft": bonus_move_ft,
            "max_range_ft": max_range_ft,
            "improved": improved,
            "cleric_level": cleric_lv,
            "buff_installed": buff_installed,
        },
    })

    return {
        "ok": True,
        "feature": "invoke-duplicity",
        "duplicates": max_duplicates,
        "bonus_move_per_duplicate_ft": bonus_move_ft,
        "max_range_ft": max_range_ft,
        "improved": improved,
        "cleric_level": cleric_lv,
        "channel_divinity_remaining": cd_cur - 1,
        "buff_installed": buff_installed,
    }


@router.post("/api/campaign/{campaign_id}/use_improved_duplicity")
async def use_improved_duplicity(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.298 — Phase H.1 deeper (Trickery Domain Cleric
    Lv 17+) of the v2.99.193 phased completion plan. Improved
    Duplicity (Trickery Domain Cleric Lv 17+, PHB p.62): "At
    17th level, you can create up to four duplicates of
    yourself, instead of one, when you use Invoke Duplicity.
    As a bonus action on your turn, you can move any number
    of them up to 30 feet, to a maximum range of 120 feet."

    Body: ``{character_id, override?}``. No chip cost —
    passive upgrade to Invoke Duplicity CD.

    v2.158.3 — Phase 8 third commit (Phase 1 of the standard
    install-then-deferred-read split, same shape as v2.148.0
    Fancy Footwork + v2.149.0 Relentless Avenger). Invoke
    Duplicity itself isn't yet a server-side endpoint
    (announce-only / GM-tracked at Trickery Cleric Lv 2), so
    Improved Duplicity has no concrete state to mutate yet —
    but the Lv-17 upgrade IS a real change to the parameters
    Invoke Duplicity will eventually read. Phase 1 captures
    those parameters in a permanent `improved-duplicity` buff:
      * `effects.invoke_duplicity_max_duplicates: 4` (was 1)
      * `effects.invoke_duplicity_bonus_move_per_duplicate_ft: 30`
      * `effects.invoke_duplicity_max_range_ft: 120`
    Phase 2 (deferred): when Invoke Duplicity gets its own
    `/use_invoke_duplicity` endpoint, it walks the caster's
    `_buffs_active`, finds an `improved-duplicity` buff (if
    present), and uses the upgraded params instead of the
    baseline 1-duplicate / 0-bonus-move shape.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Cleric character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_trickery_domain(sheet, 17):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "trickery domain cleric lv 17+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _cleric_level_from_sheet(sheet),
        })

    cleric_lv = _cleric_level_from_sheet(sheet)

    # v2.158.3 — install the parameter-carrying buff. Permanent
    # passive (idempotent on re-press via `_install_buff`'s key
    # dedupe). Phase 2 (deferred): Invoke Duplicity reads
    # `effects.invoke_duplicity_*` off the caster's
    # `_buffs_active` and substitutes the upgraded params.
    buff_installed = await _install_buff(campaign_id, char.id, {
        "key": "improved-duplicity",
        "name": "🎭 Improved Duplicity",
        "icon": "🎭",
        "duration_rounds": 100000,
        "duration_max": 100000,
        "permanent": True,
        "concentration": False,
        "source_char_id": char.id,
        "effects": {
            "invoke_duplicity_max_duplicates": 4,
            "invoke_duplicity_bonus_move_per_duplicate_ft": 30,
            "invoke_duplicity_max_range_ft": 120,
        },
        "desc": (
            f"{char.name}'s Invoke Duplicity now creates up to 4 "
            f"duplicates (was 1) + bonus-action 30 ft each. "
            f"(Trickery Domain Cleric Lv 17+ passive upgrade. "
            f"Phase 2: Invoke Duplicity endpoint will read these "
            f"flags off `_buffs_active`.)"
        ),
    })
    if buff_installed:
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                "🎭 Improved Duplicity — 4 duplicates, 30 ft bonus move"
            ),
            "feature_desc": (
                f"{char.name}'s Invoke Duplicity now creates up to "
                f"4 duplicates (was 1). As a bonus action, move any "
                f"number of duplicates up to 30 ft each (max 120 ft "
                f"range from {char.name}). (Trickery Domain Cleric "
                f"Lv 17+ class feature; passive upgrade.)"
            ),
            "source": "improved-duplicity",
            "max_duplicates": 4,
            "bonus_move_per_duplicate_ft": 30,
            "max_range_ft": 120,
            "cleric_level": cleric_lv,
            "buff_installed": buff_installed,
        },
    })

    return {
        "ok": True,
        "feature": "improved-duplicity",
        "max_duplicates": 4,
        "bonus_move_per_duplicate_ft": 30,
        "max_range_ft": 120,
        "cleric_level": cleric_lv,
        "buff_installed": buff_installed,
    }


@router.post("/api/campaign/{campaign_id}/use_saint_of_forge_and_fire")
async def use_saint_of_forge_and_fire(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.299 — Phase H.1 deeper (Forge Domain Cleric Lv 17+)
    of the v2.99.193 phased completion plan. Saint of Forge
    and Fire (Forge Domain Cleric Lv 17+, XGE p.18): "At 17th
    level, your blessed affinity with fire and metal becomes
    more powerful. You gain immunity to fire damage, and while
    you're wearing heavy armor, you have resistance to
    bludgeoning, piercing, and slashing damage from nonmagical
    attacks."

    Body: ``{character_id, override?}``. No chip cost —
    passive permanent.

    v2.158.2 — Phase 8 follow-up to v2.158.0 Avatar of Battle:
    install a permanent `saint-of-forge-and-fire` buff carrying:
      * `effects.immunity_to=["fire"]` — read by `_immunity_zero`
        (PC side); a fire-damage hit on the cleric drops to 0
        regardless of source (magical or mundane per RAW).
      * `effects.resistance_to=["nonmagical-bludgeoning",
        "nonmagical-piercing","nonmagical-slashing"]` — read by
        the v2.158.1-upgraded F6-aware `_resistance_halve`. Halves
        nonmagical BPS hits, passes magical BPS at full damage.

    v1 simplification — RAW gates the BPS resistance on "while
    wearing heavy armor", but PC sheets don't currently track
    equipped-armor category (the demo sets `ac` directly). At Lv 17
    a Forge Cleric is canonically wearing heavy armor (their Lv 1
    proficiency + the capstone explicitly assumes it). Filed for a
    future PC-armor-detection helper that gates the BPS half of the
    buff — for now both halves install unconditionally.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Cleric character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_forge_domain(sheet, 17):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "forge domain cleric lv 17+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _cleric_level_from_sheet(sheet),
        })

    cleric_lv = _cleric_level_from_sheet(sheet)

    # v2.158.2 — install fire-immunity + nonmagical-BPS resistance
    # in a single permanent buff. Mirrors the v2.158.0 Avatar of
    # Battle shape. Idempotent on re-press via the `_install_buff`
    # key dedupe.
    buff_installed = await _install_buff(campaign_id, char.id, {
        "key": "saint-of-forge-and-fire",
        "name": "🔥 Saint of Forge and Fire",
        "icon": "🔥",
        "duration_rounds": 100000,
        "duration_max": 100000,
        "permanent": True,
        "concentration": False,
        "source_char_id": char.id,
        "effects": {
            "immunity_to": ["fire"],
            "resistance_to": [
                "nonmagical-bludgeoning",
                "nonmagical-piercing",
                "nonmagical-slashing",
            ],
        },
        "desc": (
            f"{char.name} is immune to fire damage. While wearing "
            f"heavy armor, also resistant to nonmagical bludgeoning, "
            f"piercing, and slashing. (Forge Domain Cleric Lv 17+ "
            f"passive permanent. v1 simplification: BPS halving "
            f"installs unconditionally pending PC armor detection.)"
        ),
    })
    if buff_installed:
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                "🔥 Saint of Forge and Fire — fire immune + heavy-armor BPS resist"
            ),
            "feature_desc": (
                f"{char.name} is immune to fire damage. While "
                f"wearing heavy armor, also has resistance to "
                f"bludgeoning, piercing, and slashing damage from "
                f"nonmagical attacks. (Forge Domain Cleric Lv 17+ "
                f"class feature; passive permanent.)"
            ),
            "source": "saint-of-forge-and-fire",
            "fire_immunity": True,
            "heavy_armor_bps_resistance": True,
            "resistance_types": ["bludgeoning", "piercing", "slashing"],
            "resistance_nonmagical_only": True,
            "cleric_level": cleric_lv,
            "buff_installed": buff_installed,
        },
    })

    return {
        "ok": True,
        "feature": "saint-of-forge-and-fire",
        "fire_immunity": True,
        "heavy_armor_bps_resistance": True,
        "resistance_types": ["bludgeoning", "piercing", "slashing"],
        "resistance_nonmagical_only": True,
        "cleric_level": cleric_lv,
        "buff_installed": buff_installed,
    }


@router.post("/api/campaign/{campaign_id}/use_keeper_of_souls")
async def use_keeper_of_souls(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.300 — Phase H.1 deeper (Grave Domain Cleric Lv 17+)
    of the v2.99.193 phased completion plan. Keeper of Souls
    (Grave Domain Cleric Lv 17+, XGE p.19): "Starting at 17th
    level, when an enemy you can see dies within 60 feet of
    you, you or one creature of your choice within 60 ft
    regains HP equal to the enemy's number of Hit Dice. Can't
    be used while incapacitated. Once used, can't again until
    the start of your next turn."

    Body: ``{character_id, enemy_hit_dice, override?}``. No
    chip cost — passive end-of-enemy-turn trigger. Body
    accepts `enemy_hit_dice` to inform the manual announce
    (defaults to 1 if missing).

    v2.158.4 — Phase 8 fourth commit (Phase 1 of install-then-
    deferred-read split, same shape as v2.158.3 Improved
    Duplicity + v2.148.0 Fancy Footwork). Install a permanent
    `keeper-of-souls-watcher` buff carrying the radius +
    watcher-active flag:
      * `effects.keeper_of_souls_watcher: True`
      * `effects.keeper_of_souls_radius_ft: 60`
    Phase 2 (deferred): on-death hook in `_apply_damage_to_combatant`'s
    NPC branch detects the 0-HP transition, walks PC combatants for
    the buff, range-gates at 60 ft, and auto-heals the watcher for
    the dying NPC's Hit Dice count. The manual announce path stays
    as the explicit override the player can press for non-detected
    cases (offscreen kills, NPC-vs-NPC kills the watcher saw, etc.).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    enemy_hd = max(1, int(body.get("enemy_hit_dice") or 1))

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Cleric character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_grave_domain(sheet, 17):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "grave domain cleric lv 17+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _cleric_level_from_sheet(sheet),
        })

    heal_amount = enemy_hd
    cleric_lv = _cleric_level_from_sheet(sheet)

    # v2.158.4 — install the watcher flag buff. Permanent passive
    # (idempotent on re-press via `_install_buff`'s key dedupe).
    # Phase 2 (deferred): NPC 0-HP transition in
    # `_apply_damage_to_combatant` walks PC combatants for this
    # buff key + range-gates + auto-heals the watcher.
    buff_installed = await _install_buff(campaign_id, char.id, {
        "key": "keeper-of-souls-watcher",
        "name": "⚱️ Keeper of Souls (watcher)",
        "icon": "⚱️",
        "duration_rounds": 100000,
        "duration_max": 100000,
        "permanent": True,
        "concentration": False,
        "source_char_id": char.id,
        "effects": {
            "keeper_of_souls_watcher": True,
            "keeper_of_souls_radius_ft": 60,
        },
        "desc": (
            f"{char.name} is attuned to nearby death. When an enemy "
            f"within 60 ft dies, {char.name} or an ally regains HP "
            f"= enemy's Hit Dice. (Grave Domain Cleric Lv 17+ "
            f"passive. Phase 2: on-death hook in damage pipeline.)"
        ),
    })
    if buff_installed:
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"⚱️ Keeper of Souls — heal {heal_amount} HP from dying enemy"
            ),
            "feature_desc": (
                f"{char.name} seizes a trace of vitality from a "
                f"parting soul. An ally within 60 ft (or {char.name}) "
                f"regains {heal_amount} HP (= enemy's hit dice). "
                f"(Grave Domain Cleric Lv 17+ class feature; "
                f"once per turn.)"
            ),
            "source": "keeper-of-souls",
            "heal_amount": heal_amount,
            "enemy_hit_dice": enemy_hd,
            "max_range_ft": 60,
            "cleric_level": cleric_lv,
            "buff_installed": buff_installed,
        },
    })

    return {
        "ok": True,
        "feature": "keeper-of-souls",
        "heal_amount": heal_amount,
        "enemy_hit_dice": enemy_hd,
        "max_range_ft": 60,
        "cleric_level": cleric_lv,
        "buff_installed": buff_installed,
    }


@router.post("/api/campaign/{campaign_id}/use_visions_of_the_past")
async def use_visions_of_the_past(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.301 — Phase H.1 deeper (Knowledge Domain Cleric
    Lv 17+) of the v2.99.193 phased completion plan. Visions
    of the Past (Knowledge Domain Cleric Lv 17+, PHB p.60):
    Spend at least 1 min in meditation, then receive
    dream-like glimpses of recent events. Concentration:
    minutes equal to WIS score (min 1). Once per short rest.

    Modes:
    - Object Reading: hold an object → 24h history + who used.
    - Area Reading: 50-ft cube → 24h history.

    Body: ``{character_id, mode?, override?}``. Mode: "object"
    or "area" (default "object"). Auto-bootstraps a
    `visions-of-the-past` resource (max=1, reset=short).
    v1 announce-only.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    mode = (body.get("mode") or "object").strip().lower()
    if mode not in ("object", "area"):
        mode = "object"

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Cleric character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_knowledge_domain(sheet, 17):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "knowledge domain cleric lv 17+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _cleric_level_from_sheet(sheet),
        })

    resources = list(sheet.get("resources") or [])
    vp_row = None
    vp_idx = -1
    for i, r in enumerate(resources):
        if not isinstance(r, dict):
            continue
        if (r.get("key") or "").strip().lower() == "visions-of-the-past":
            vp_row = dict(r); vp_idx = i; break
    if vp_row is None:
        vp_row = {
            "key": "visions-of-the-past",
            "label": "Visions of the Past",
            "current": 1, "max": 1, "reset": "short",
        }
        vp_idx = len(resources)
        resources.append(vp_row)
    vp_cur = int(vp_row.get("current") or 0)
    vp_max = int(vp_row.get("max") or 1)
    if vp_cur < 1:
        return JSONResponse(status_code=409, content={
            "error": "no_uses_left",
            "label": "Visions of the Past",
            "current": vp_cur, "max": vp_max,
        })

    vp_row["current"] = vp_cur - 1
    resources[vp_idx] = vp_row
    sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    wis = int((sheet.get("abilities") or {}).get("WIS") or 10)
    max_duration_minutes = max(1, wis)
    cleric_lv = _cleric_level_from_sheet(sheet)

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    if mode == "object":
        mode_text = "an object's 24-hour history (and who used it)"
    else:
        mode_text = "a 50-ft cube's 24-hour history"
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "visions-of-the-past",
            "current": vp_cur - 1, "max": vp_max,
        },
    })
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"📜 Visions of the Past — {mode} reading "
                f"(concentrate {max_duration_minutes} min)"
            ),
            "feature_desc": (
                f"{char.name} meditates 1+ min and receives "
                f"shadowy glimpses of {mode_text}. Concentration "
                f"up to {max_duration_minutes} min (= WIS score). "
                f"(Knowledge Domain Cleric Lv 17+ class feature; "
                f"once per short or long rest.)"
            ),
            "source": "visions-of-the-past",
            "mode": mode,
            "max_duration_minutes": max_duration_minutes,
            "uses_remaining": vp_cur - 1,
            "cleric_level": cleric_lv,
        },
    })

    return {
        "ok": True,
        "feature": "visions-of-the-past",
        "mode": mode,
        "max_duration_minutes": max_duration_minutes,
        "uses_remaining": vp_cur - 1,
        "max_uses": vp_max,
        "cleric_level": cleric_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_master_of_nature")
async def use_master_of_nature(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.302 — Phase H.1 deeper (Nature Domain Cleric
    Lv 17+) of the v2.99.193 phased completion plan. Master
    of Nature (Nature Domain Cleric Lv 17+, PHB p.62): "At
    17th level, you gain the ability to command animals and
    plant creatures. While creatures are charmed by your
    Charm Animals and Plants feature, you can take a bonus
    action on your turn to verbally command what each of
    those creatures will do on its next turn."

    Body: ``{character_id, override?}``. Costs a bonus chip
    (RAW: bonus action to issue commands while charm holds).
    v1 announce-only — actual charmed-creature command
    interpretation is GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Cleric character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_nature_domain(sheet, 17):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "nature domain cleric lv 17+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _cleric_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "master-of-nature",
            "label": "Master of Nature",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "bonus")

    cleric_lv = _cleric_level_from_sheet(sheet)

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                "🌿 Master of Nature — command charmed beasts & plants"
            ),
            "feature_desc": (
                f"{char.name} verbally commands the beasts and "
                f"plants charmed by their Charm Animals and Plants "
                f"CD what to do on their next turn. (Nature Domain "
                f"Cleric Lv 17+ class feature; bonus action while "
                f"the charm holds.)"
            ),
            "source": "master-of-nature",
            "cleric_level": cleric_lv,
        },
    })

    return {
        "ok": True,
        "feature": "master-of-nature",
        "cleric_level": cleric_lv,
    }


