@router.post("/api/campaign/{campaign_id}/use_orders_wrath")
async def use_orders_wrath(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.305 — Phase H.1 deeper (Order Domain Cleric Lv 17+)
    of the v2.99.193 phased completion plan. CLOSES the H.1 Lv 17
    batch (13/13 PHB+TCE+SCAG domains). Order's Wrath (Order
    Domain Cleric Lv 17+, TCE p.40): "When you deal your Divine
    Strike damage to a creature, you can curse it until the
    start of your next turn. The next time one of your allies
    hits the cursed creature with an attack, the cursed creature
    takes 2d8 psychic damage, and the curse ends. You can curse
    a creature only once per turn."

    Body: ``{character_id, target_combatant_id?, override?}``.
    No chip — passive trigger on Divine Strike.

    v2.158.5 — Phase 8 fifth commit (Phase 1 of install-then-
    deferred-read split). When `target_combatant_id` is supplied,
    install an `orders-wrath-curse` buff on the target combatant
    carrying the curse payload:
      * `effects.orders_wrath_psychic_damage_expression: "2d8"`
      * `effects.orders_wrath_caster_char_id: <cleric.id>`
      * `effects.orders_wrath_active: True`
    Duration 2 rounds (RAW: "until the start of your next turn"
    — the first turn-tick decrement happens on the next round
    boundary, so 2 covers the until-end-of-cleric's-next-turn
    span). Phase 2 (deferred): `/attack` flow detects an ally
    (anyone except the curse's `caster_char_id`) hitting the
    cursed target → deals 2d8 psychic via `_apply_damage_to_combatant`
    + drops the curse buff. If no `target_combatant_id` supplied
    the endpoint falls back to the historical announce-only
    behavior (manual GM application).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    target_combatant_id = body.get("target_combatant_id") or None

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Cleric character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_order_domain(sheet, 17):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "order domain cleric lv 17+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _cleric_level_from_sheet(sheet),
        })

    cleric_lv = _cleric_level_from_sheet(sheet)

    # v2.158.5 — install the curse buff on the target combatant
    # (PC or NPC). Uses `_install_buff_on_combatant_id` so it
    # routes by combatant id rather than character id — Order's
    # Wrath is most often cast at NPCs who don't have a Character
    # row. When no target supplied, fall back to historical
    # announce-only behavior (no buff install, manual GM track).
    curse_installed = False
    if target_combatant_id:
        curse_installed = await _install_buff_on_combatant_id(
            campaign_id, str(target_combatant_id), {
                "key": "orders-wrath-curse",
                "name": "⚖️ Order's Wrath (curse)",
                "icon": "⚖️",
                "duration_rounds": 2,
                "duration_max": 2,
                "concentration": False,
                "source_char_id": char.id,
                "effects": {
                    "orders_wrath_psychic_damage_expression": "2d8",
                    "orders_wrath_caster_char_id": int(char.id),
                    "orders_wrath_active": True,
                },
                "desc": (
                    f"Cursed by {char.name}'s Order's Wrath. The next "
                    f"ally to hit takes 2d8 psychic damage; curse ends "
                    f"on hit or at the start of {char.name}'s next "
                    f"turn. (Order Domain Cleric Lv 17+.)"
                ),
            },
        )

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    target_text = (
        f"combatant {target_combatant_id}"
        if target_combatant_id else "the Divine Strike target"
    )
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                "⚖️ Order's Wrath — 2d8 psychic curse on Divine Strike target"
            ),
            "feature_desc": (
                f"{char.name} curses {target_text} until the start "
                f"of their next turn. The next time an ally hits the "
                f"cursed creature, the curse triggers 2d8 psychic "
                f"damage and ends. (Order Domain Cleric Lv 17+ class "
                f"feature; once per turn.)"
            ),
            "source": "orders-wrath",
            "target_combatant_id": target_combatant_id,
            "psychic_damage_expression": "2d8",
            "expires_on": "next_turn_start",
            "cleric_level": cleric_lv,
            "curse_installed": curse_installed,
        },
    })

    return {
        "ok": True,
        "feature": "orders-wrath",
        "target_combatant_id": target_combatant_id,
        "psychic_damage_expression": "2d8",
        "expires_on": "next_turn_start",
        "cleric_level": cleric_lv,
        "curse_installed": curse_installed,
    }


@router.post("/api/campaign/{campaign_id}/use_assassinate")
async def use_assassinate(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.306 — Phase E.3 Rogue subclass opener (Assassin
    Rogue Lv 3+) of the v2.99.193 phased completion plan.
    Pivots after discovering Thief Fast Hands was already
    wired in v2.99.224. Assassinate (Assassin Rogue Lv 3+,
    PHB p.97): "Starting at 3rd level, you are at your
    deadliest when you get the drop on your enemies. You
    have advantage on attack rolls against any creature that
    hasn't taken a turn in the combat yet. In addition, any
    hit you score against a creature that is surprised is a
    critical hit."

    Body: ``{character_id, override?}``. No chip cost — this
    is a passive declaration that the next attack against a
    not-yet-acted (or surprised) target gets the bonus.
    v1 announce-only — the actual advantage / auto-crit
    mechanics are applied by the GM at attack time.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Rogue character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_assassin_subclass(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "assassin rogue lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _rogue_level_from_sheet(sheet),
        })

    rogue_lv = _rogue_level_from_sheet(sheet)

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                "🗡️ Assassinate — advantage vs not-acted, auto-crit on surprised"
            ),
            "feature_desc": (
                f"{char.name} has advantage on attack rolls against "
                f"creatures that haven't taken a turn yet in this "
                f"combat. Any hit against a surprised creature is a "
                f"critical hit. (Assassin Rogue Lv 3+ class feature.)"
            ),
            "source": "assassinate",
            "advantage_vs_pre_turn": True,
            "auto_crit_vs_surprised": True,
            "rogue_level": rogue_lv,
        },
    })

    return {
        "ok": True,
        "feature": "assassinate",
        "advantage_vs_pre_turn": True,
        "auto_crit_vs_surprised": True,
        "rogue_level": rogue_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_fancy_footwork")
async def use_fancy_footwork(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.307 — Phase E.3 Rogue subclass batch (Swashbuckler
    Rogue Lv 3+) of the v2.99.193 phased completion plan. Fancy
    Footwork (Swashbuckler Rogue Lv 3+, XGE p.47): "Beginning
    at 3rd level, you can nimbly dodge out of the way of
    dangerous foes. During your turn, if you make a melee
    attack against a creature, that creature can't make
    opportunity attacks against you for the rest of your turn."

    Body: ``{character_id, target_combatant_id?, override?}``.
    No chip — passive on a melee attack. v1 announce-only —
    the OA-suppression vs the target is GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    target_combatant_id = body.get("target_combatant_id") or None

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Rogue character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_swashbuckler_subclass(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "swashbuckler rogue lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _rogue_level_from_sheet(sheet),
        })

    rogue_lv = _rogue_level_from_sheet(sheet)

    # v2.148.0 — Phase 1 mechanical wiring: when the caller passes
    # `target_combatant_id`, install a 1-round `fancy-footwork-blocked`
    # buff on the target carrying `effects.fancy_footwork_blocked_against_char_id
    # = swashbuckler.id`.
    # v2.158.38 — Phase 2 (shipped): `_check_opportunity_attack_triggers`
    # reads this buff via `_combatant_oa_blocked_against` and suppresses
    # the marked watcher's OA against the swashbuckler for the turn.
    buff_installed = False
    if target_combatant_id:
        buff_installed = await _install_buff_on_combatant_id(
            campaign_id, str(target_combatant_id), {
                "key": "fancy-footwork-blocked",
                "name": "🎭 Fancy Footwork (no OA vs Swashbuckler)",
                "icon": "🎭",
                "duration_rounds": 1,
                "duration_max": 1,
                "concentration": False,
                "effects": {
                    "fancy_footwork_blocked_against_char_id": int(char.id),
                },
                "desc": (
                    f"Can't make opportunity attacks against "
                    f"{char.name} until the end of {char.name}'s "
                    f"turn. (Swashbuckler Rogue Lv 3+.)"
                ),
                "source": "fancy-footwork",
                "source_char_id": int(char.id),
            },
        )

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    target_text = (
        f"combatant {target_combatant_id}"
        if target_combatant_id else "the melee attack target"
    )
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                "🎭 Fancy Footwork — no OAs from melee target this turn"
            ),
            "feature_desc": (
                f"{char.name} dodges nimbly past {target_text} — "
                f"that creature can't make opportunity attacks "
                f"against {char.name} for the rest of this turn. "
                f"(Swashbuckler Rogue Lv 3+ class feature.)"
            ),
            "source": "fancy-footwork",
            "target_combatant_id": target_combatant_id,
            "oa_suppressed_until": "end_of_turn",
            "rogue_level": rogue_lv,
            "buff_installed": buff_installed,
        },
    })

    return {
        "ok": True,
        "feature": "fancy-footwork",
        "target_combatant_id": target_combatant_id,
        "oa_suppressed_until": "end_of_turn",
        "rogue_level": rogue_lv,
        "buff_installed": buff_installed,
    }


