@router.post("/api/campaign/{campaign_id}/use_natural_recovery")
async def use_natural_recovery(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.314 — Phase E.4 Druid subclass batch (Land Druid
    Lv 2+) of the v2.99.193 phased completion plan. Natural
    Recovery (Land Druid Lv 2+, PHB p.68): "During a short
    rest, you choose expended spell slots to recover. The
    spell slots can have a combined level that is equal to
    or less than half your druid level (rounded up), and none
    of the slots can be 6th level or higher. You can't use
    this feature again until you finish a long rest."

    Body: ``{character_id, override?}``. No chip — happens
    during short rest. Auto-bootstraps a `natural-recovery`
    resource (max=1, reset=long). Computes recoverable pool =
    ceil(druid_lv / 2). v1 announce-only — actual spell-slot
    refund is GM-tracked (or follow-up sheet patch).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Druid character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_land_druid(sheet, 2):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "land druid lv 2+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _druid_level_from_sheet(sheet),
        })

    resources = list(sheet.get("resources") or [])
    nr_row = None
    nr_idx = -1
    for i, r in enumerate(resources):
        if not isinstance(r, dict):
            continue
        if (r.get("key") or "").strip().lower() == "natural-recovery":
            nr_row = dict(r); nr_idx = i; break
    if nr_row is None:
        nr_row = {
            "key": "natural-recovery",
            "label": "Natural Recovery",
            "current": 1, "max": 1, "reset": "long",
        }
        nr_idx = len(resources)
        resources.append(nr_row)
    nr_cur = int(nr_row.get("current") or 0)
    nr_max = int(nr_row.get("max") or 1)
    if nr_cur < 1:
        return JSONResponse(status_code=409, content={
            "error": "no_uses_left",
            "label": "Natural Recovery",
            "current": nr_cur, "max": nr_max,
        })

    nr_row["current"] = nr_cur - 1
    resources[nr_idx] = nr_row
    sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    druid_lv = _druid_level_from_sheet(sheet)
    recoverable_level_pool = (druid_lv + 1) // 2  # ceil(druid_lv / 2)
    max_slot_level = 5

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "natural-recovery",
            "current": nr_cur - 1, "max": nr_max,
        },
    })
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🌿 Natural Recovery — recover spell-slot levels "
                f"(pool {recoverable_level_pool}, max Lv 5)"
            ),
            "feature_desc": (
                f"{char.name} meditates during a short rest and "
                f"recovers spell slots totaling up to "
                f"{recoverable_level_pool} levels (none Lv 6+). "
                f"(Land Druid Lv 2+ class feature; once per long "
                f"rest.)"
            ),
            "source": "natural-recovery",
            "recoverable_level_pool": recoverable_level_pool,
            "max_slot_level": max_slot_level,
            "uses_remaining": nr_cur - 1,
            "druid_level": druid_lv,
        },
    })

    return {
        "ok": True,
        "feature": "natural-recovery",
        "recoverable_level_pool": recoverable_level_pool,
        "max_slot_level": max_slot_level,
        "uses_remaining": nr_cur - 1,
        "max_uses": nr_max,
        "druid_level": druid_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_spirit_totem")
async def use_spirit_totem(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.315 — Phase E.4 Druid subclass batch (Shepherd
    Druid Lv 2+, XGE) of the v2.99.193 phased completion plan.
    Spirit Totem (Shepherd Druid Lv 2+, XGE p.24): bonus
    action to summon a Bear/Hawk/Unicorn spirit at a point
    within 60 ft. Spirit creates a 30-ft radius aura, persists
    1 min, once per short or long rest.

    Body: ``{character_id, spirit?, target_combatant_ids?, override?}``.
    Spirit: "bear" (default — 5+druid_lv temp HP), "hawk" (reaction
    → ally advantage on attack roll), or "unicorn" (heal-spell
    rider HP equal to druid level). Costs a bonus chip.
    Auto-bootstraps `spirit-totem` resource (max=1, reset=short).

    v2.99.421 — Phase 4.2 of docs/plans/temp-hp-and-bonuses.md: for the
    **bear** spirit, when ``target_combatant_ids`` (the allies in the
    30-ft aura) is supplied, each gains `5 + druid level` temp HP via
    `_grant_temp_hp` (RAW non-stacking) on summon.

    v2.99.427 — Phase 5.3 of docs/plans/auras.md: the bear spirit now
    also installs a `spirit-totem-bear` aura buff so the v2.99.425 tick
    re-grants the temp HP to allies in the 30-ft aura at the start of each
    of the druid's turns (the ongoing re-grant the P4.2 summon-only path
    deferred). Hawk / unicorn effects stay announce-only.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    spirit = (body.get("spirit") or "bear").strip().lower()
    if spirit not in ("bear", "hawk", "unicorn"):
        spirit = "bear"
    target_ids = body.get("target_combatant_ids") or []
    if not isinstance(target_ids, list):
        raise HTTPException(400, "target_combatant_ids must be a list")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Druid character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_shepherd_druid(sheet, 2):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "shepherd druid lv 2+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _druid_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "spirit-totem",
            "label": "Spirit Totem",
            "strict": strict,
        })

    resources = list(sheet.get("resources") or [])
    st_row = None
    st_idx = -1
    for i, r in enumerate(resources):
        if not isinstance(r, dict):
            continue
        if (r.get("key") or "").strip().lower() == "spirit-totem":
            st_row = dict(r); st_idx = i; break
    if st_row is None:
        st_row = {
            "key": "spirit-totem",
            "label": "Spirit Totem",
            "current": 1, "max": 1, "reset": "short",
        }
        st_idx = len(resources)
        resources.append(st_row)
    st_cur = int(st_row.get("current") or 0)
    st_max = int(st_row.get("max") or 1)
    if st_cur < 1:
        return JSONResponse(status_code=409, content={
            "error": "no_uses_left",
            "label": "Spirit Totem",
            "current": st_cur, "max": st_max,
        })

    st_row["current"] = st_cur - 1
    resources[st_idx] = st_row
    sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    await _mark_battle_economy(campaign_id, char.id, "bonus")

    druid_lv = _druid_level_from_sheet(sheet)
    bear_temp_hp = 5 + druid_lv
    unicorn_heal_bonus = druid_lv

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    if spirit == "bear":
        effect_text = (
            f"You and allies in the 30-ft aura gain "
            f"{bear_temp_hp} temporary HP."
        )
    elif spirit == "hawk":
        effect_text = (
            "Reaction: when ally in aura attacks, give them "
            "advantage on the attack roll."
        )
    else:  # unicorn
        effect_text = (
            f"When you cast a healing spell using a slot, "
            f"allies in aura also heal {unicorn_heal_bonus} HP."
        )

    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "spirit-totem",
            "current": st_cur - 1, "max": st_max,
        },
    })
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🐻 Spirit Totem — {spirit.title()} (30 ft aura, 1 min)"
            ),
            "feature_desc": (
                f"{char.name} summons the {spirit.title()} Spirit at "
                f"a point within 60 ft. {effect_text} (Shepherd Druid "
                f"Lv 2+ class feature; once per short or long rest.)"
            ),
            "source": "spirit-totem",
            "spirit": spirit,
            "aura_radius_ft": 30,
            "duration_minutes": 1,
            "bear_temp_hp": bear_temp_hp,
            "unicorn_heal_bonus": unicorn_heal_bonus,
            "uses_remaining": st_cur - 1,
            "druid_level": druid_lv,
        },
    })

    # v2.99.421 — Phase 4.2: the Bear spirit grants temp HP to the
    # supplied aura allies on summon (RAW non-stacking). Hawk/unicorn
    # don't grant temp HP; the ongoing aura re-grant is Phase 5.
    targets_applied = 0
    if spirit == "bear" and bear_temp_hp > 0:
        for tcid in target_ids:
            cb = _lookup_combatant(campaign_id, str(tcid).strip())
            if cb is None:
                continue
            gr = await _grant_temp_hp(
                db, campaign_id, cb, bear_temp_hp, source="spirit-totem",
            )
            if gr["temp_after"] > 0:
                targets_applied += 1

    # v2.99.427 — Phase 5.3 of docs/plans/auras.md: the Bear spirit now
    # also installs a `spirit-totem-bear` AURA buff on the druid so the
    # v2.99.425 tick re-grants the temp HP to allies in the 30-ft aura at
    # the start of each of the druid's turns (closes the P4.2 ongoing-
    # re-grant defer). The summon grant above covers turn 0; the aura
    # maintains it (non-stacking). 10-round duration ≈ the 1-minute totem.
    # (v1 covers allies; the druid's own ongoing temp HP is via the summon
    # target list — RAW "you and your allies".)
    aura_installed = False
    if spirit == "bear" and bear_temp_hp > 0:
        aura_installed = await _install_buff(campaign_id, char.id, {
            "key": "spirit-totem-bear",
            "name": "Spirit Totem (Bear)",
            "icon": "🐻",
            "duration_rounds": 10,
            "duration_max": 10,
            "concentration": False,
            "source_char_id": char.id,
            "effects": {
                "aura": {
                    "radius_ft": 30,
                    "affects": "allies",
                    "temp_hp": bear_temp_hp,
                    "source": "spirit-totem-bear",
                    "label": "Spirit Totem (Bear)",
                },
            },
            "desc": (
                f"Allies within the 30-ft aura gain {bear_temp_hp} temp "
                f"HP at the start of your turn. (Shepherd Druid Lv 2+.)"
            ),
        })
        if aura_installed:
            _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    return {
        "ok": True,
        "feature": "spirit-totem",
        "spirit": spirit,
        "aura_radius_ft": 30,
        "duration_minutes": 1,
        "bear_temp_hp": bear_temp_hp,
        "unicorn_heal_bonus": unicorn_heal_bonus,
        "uses_remaining": st_cur - 1,
        "max_uses": st_max,
        "druid_level": druid_lv,
        "targets_applied": targets_applied,
        "aura_installed": aura_installed,
    }


@router.post("/api/campaign/{campaign_id}/use_star_map")
async def use_star_map(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.316 — Phase E.4 Druid subclass batch (Stars
    Druid Lv 2+, TCE) of the v2.99.193 phased completion plan.
    Star Map (Stars Druid Lv 2+, TCE p.37): Star chart as
    spellcasting focus. Guidance + Guiding Bolt always prepared
    (don't count against prep limit). Guiding Bolt is a 1st-
    level druid spell for you, and you can cast it without a
    slot WIS_mod times per long rest (min 1).

    Body: ``{character_id, override?}``. No chip — passive
    declaration.

    v2.158.13 — Phase 8 diversifies into Druid (first Druid
    subclass feature flipped from announce-only to tracked).
    Two-part Phase 1:
      1. Install a permanent `star-map-active` buff carrying
         the parameter flags:
           * `effects.star_map_active: True`
           * `effects.star_map_free_guiding_bolt_uses_max`
             (= WIS mod, min 1)
           * `effects.star_map_always_prepared`
             (= ["Guidance", "Guiding Bolt"])
      2. Delivers on the original docstring's "auto-bootstrap
         a `guiding-bolt-charges` resource" promise — adds the
         resource entry to `sheet.resources` if missing
         (key="guiding-bolt-charges", max=WIS_mod min 1,
         reset="long"). The existing rest-character flow
         refills it on long rest; the existing resource-decrement
         flow lets the player tick a free Guiding Bolt cast.

    Phase 2 (deferred): `/cast_spell` reads the buff and lets
    "Guiding Bolt" be cast without a slot when the resource has
    charges. Spell-preparation read sites exempt
    "Guidance" + "Guiding Bolt" from the prep cap when the buff
    is present.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Druid character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_stars_druid(sheet, 2):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "stars druid lv 2+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _druid_level_from_sheet(sheet),
        })

    abilities = sheet.get("abilities") or {}
    try:
        wis_mod = (int(abilities.get("WIS") or 10) - 10) // 2
    except (TypeError, ValueError):
        wis_mod = 0
    free_guiding_bolt_uses = max(1, wis_mod)
    druid_lv = _druid_level_from_sheet(sheet)

    # v2.158.13 — auto-bootstrap the `guiding-bolt-charges`
    # resource if missing. Re-press doesn't reset the current
    # charge count (idempotent in that sense — the player won't
    # accidentally refund themselves a free cast by re-pressing).
    # Refilled on long rest by the existing `rest_character`
    # generic loop (resets `current` to `max` for any entry
    # with `reset == "long"`).
    resources = list(sheet.get("resources") or [])
    gb_idx = next(
        (i for i, r in enumerate(resources)
         if (r.get("key") or "").lower() == "guiding-bolt-charges"),
        -1,
    )
    resource_bootstrapped = False
    if gb_idx < 0:
        resources.append({
            "key": "guiding-bolt-charges",
            "label": "Guiding Bolt (free casts)",
            "current": free_guiding_bolt_uses,
            "max": free_guiding_bolt_uses,
            "reset": "long",
        })
        sheet["resources"] = resources
        from sqlalchemy.orm.attributes import flag_modified
        char.sheet = sheet
        flag_modified(char, "sheet")
        db.commit()
        resource_bootstrapped = True

    # v2.158.13 — install the permanent parameter-flag buff.
    # Idempotent on re-press via key dedupe.
    buff_installed = await _install_buff(campaign_id, char.id, {
        "key": "star-map-active",
        "name": "🌌 Star Map",
        "icon": "🌌",
        "duration_rounds": 100000,
        "duration_max": 100000,
        "permanent": True,
        "concentration": False,
        "source_char_id": char.id,
        "effects": {
            "star_map_active": True,
            "star_map_free_guiding_bolt_uses_max": free_guiding_bolt_uses,
            "star_map_always_prepared": ["Guidance", "Guiding Bolt"],
        },
        "desc": (
            f"{char.name}'s star chart is a spellcasting focus. "
            f"Guidance + Guiding Bolt always prepared; Guiding Bolt "
            f"castable {free_guiding_bolt_uses}/long rest without "
            f"a slot. (Stars Druid Lv 2+ passive. Phase 2: "
            f"`/cast_spell` reads these flags.)"
        ),
    })
    if buff_installed:
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🌌 Star Map — Guidance + Guiding Bolt ({free_guiding_bolt_uses}/rest free)"
            ),
            "feature_desc": (
                f"{char.name}'s star chart is a spellcasting focus. "
                f"Guidance + Guiding Bolt are always prepared (don't "
                f"count against prep limit). Guiding Bolt is a Lv 1 "
                f"druid spell, castable {free_guiding_bolt_uses} "
                f"times without a slot per long rest (= WIS mod, "
                f"min 1). (Stars Druid Lv 2+ TCE class feature.)"
            ),
            "source": "star-map",
            "free_guiding_bolt_uses": free_guiding_bolt_uses,
            "always_prepared": ["Guidance", "Guiding Bolt"],
            "druid_level": druid_lv,
            "buff_installed": buff_installed,
            "resource_bootstrapped": resource_bootstrapped,
        },
    })

    return {
        "ok": True,
        "feature": "star-map",
        "free_guiding_bolt_uses": free_guiding_bolt_uses,
        "always_prepared": ["Guidance", "Guiding Bolt"],
        "druid_level": druid_lv,
        "buff_installed": buff_installed,
        "resource_bootstrapped": resource_bootstrapped,
    }


@router.post("/api/campaign/{campaign_id}/use_halo_of_spores")
async def use_halo_of_spores(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.317 — Phase E.4 Druid subclass batch (Spores
    Druid Lv 2+, TCE) of the v2.99.193 phased completion plan.
    Halo of Spores (Spores Druid Lv 2+, TCE p.36): "When a
    creature you can see moves into a space within 10 feet of
    you, or a creature within 10 feet of you starts its turn
    there, you can use your reaction to deal Xd? necrotic
    damage to that creature unless it succeeds on a CON save
    against your spell save DC."

    Damage die by druid level:
    - Lv 2-5: 1d4
    - Lv 6-9: 1d6
    - Lv 10-13: 1d8
    - Lv 14+: 1d10

    Body: ``{character_id, target_combatant_id?, override?}``.
    Costs a reaction chip. v1 announce-only — actual CON
    save + damage application is GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    target_combatant_id = body.get("target_combatant_id") or None

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Druid character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_spores_druid(sheet, 2):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "spores druid lv 2+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _druid_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "reaction")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "reaction",
            "char_name": char.name,
            "source": "halo-of-spores",
            "label": "Halo of Spores",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "reaction")

    druid_lv = _druid_level_from_sheet(sheet)
    if druid_lv >= 14:
        damage_die = "1d10"
    elif druid_lv >= 10:
        damage_die = "1d8"
    elif druid_lv >= 6:
        damage_die = "1d6"
    else:
        damage_die = "1d4"

    prof = int(sheet.get("proficiency_bonus") or 2)
    wis = int((sheet.get("abilities") or {}).get("WIS") or 10)
    wis_mod = (wis - 10) // 2
    save_dc = 8 + prof + wis_mod

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"☠️ Halo of Spores — {damage_die} necrotic (CON save DC {save_dc})"
            ),
            "feature_desc": (
                f"{char.name} releases necrotic spores at the target. "
                f"CON save DC {save_dc}; on fail, take {damage_die} "
                f"necrotic damage. (Spores Druid Lv 2+ TCE class "
                f"feature; reaction when target moves into or starts "
                f"turn within 10 ft.)"
            ),
            "source": "halo-of-spores",
            "target_combatant_id": target_combatant_id,
            "damage_expression": damage_die,
            "damage_type": "necrotic",
            "save_ability": "CON",
            "save_dc": save_dc,
            "aura_radius_ft": 10,
            "druid_level": druid_lv,
        },
    })

    return {
        "ok": True,
        "feature": "halo-of-spores",
        "target_combatant_id": target_combatant_id,
        "damage_expression": damage_die,
        "damage_type": "necrotic",
        "save_ability": "CON",
        "save_dc": save_dc,
        "aura_radius_ft": 10,
        "druid_level": druid_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_summon_wildfire_spirit")
async def use_summon_wildfire_spirit(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.318 — Phase E.4 Druid subclass batch (Wildfire
    Druid Lv 2+, TCE) of the v2.99.193 phased completion plan.
    Summon Wildfire Spirit (Wildfire Druid Lv 2+, TCE p.38):
    "As an action, you can expend a use of your Wild Shape
    to summon a Wildfire Spirit for 1 hour. Once you summon
    the spirit, you can't do so again until you finish a long
    rest, unless you expend a spell slot of 2nd level or
    higher to summon it."

    Body: ``{character_id, slot_level?, override?}``. Costs
    an action chip. `slot_level` (≥2) for the spell-slot
    variant; otherwise consumes a Wild Shape use. v1
    announce-only — Wild Shape / slot consumption + summon
    persistence are GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    slot_level_raw = body.get("slot_level")
    slot_level = None
    if slot_level_raw is not None:
        try:
            slot_level = max(2, int(slot_level_raw))
        except (TypeError, ValueError):
            slot_level = None

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Druid character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_wildfire_druid(sheet, 2):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "wildfire druid lv 2+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _druid_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "summon-wildfire-spirit",
            "label": "Summon Wildfire Spirit",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "action")

    druid_lv = _druid_level_from_sheet(sheet)
    resource_used = "spell-slot" if slot_level else "wild-shape"

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    if slot_level:
        method_text = (
            f"by expending a Lv {slot_level} spell slot"
        )
    else:
        method_text = "by spending a Wild Shape use"
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🔥 Summon Wildfire Spirit ({resource_used}) — 1 hour"
            ),
            "feature_desc": (
                f"{char.name} summons a Wildfire Spirit "
                f"{method_text}. The spirit fights at their side "
                f"for 1 hour. (Wildfire Druid Lv 2+ TCE class "
                f"feature.)"
            ),
            "source": "summon-wildfire-spirit",
            "resource_used": resource_used,
            "slot_level": slot_level,
            "duration_minutes": 60,
            "druid_level": druid_lv,
        },
    })

    return {
        "ok": True,
        "feature": "summon-wildfire-spirit",
        "resource_used": resource_used,
        "slot_level": slot_level,
        "duration_minutes": 60,
        "druid_level": druid_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_balm_of_the_summer_court")
async def use_balm_of_the_summer_court(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.319 — Phase E.4 Druid subclass batch (Dreams
    Druid Lv 2+, XGE) of the v2.99.193 phased completion plan.
    Balm of the Summer Court (Dreams Druid Lv 2+, XGE p.23):
    "Pool of d6 fey energy = druid level. As a bonus action,
    spend up to half-druid-level dice; ally within 120 ft
    regains HP = total rolled, +1 temp HP per die spent.
    Refills on long rest."

    Body: ``{character_id, dice_spent?, override?}``. Default
    dice_spent = 1. Costs a bonus chip. Auto-bootstraps a
    `balm-of-summer-court-dice` resource (max=druid_lv,
    reset=long). v1 announce-only — actual heal dice are
    rolled server-side and broadcast; ally HP/temp HP
    application is GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    dice_spent_raw = body.get("dice_spent") or 1
    try:
        dice_spent = max(1, int(dice_spent_raw))
    except (TypeError, ValueError):
        dice_spent = 1

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Druid character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_dreams_druid(sheet, 2):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "dreams druid lv 2+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _druid_level_from_sheet(sheet),
        })

    druid_lv = _druid_level_from_sheet(sheet)
    half_lv = max(1, druid_lv // 2)
    dice_spent = min(dice_spent, half_lv)

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "balm-of-the-summer-court",
            "label": "Balm of the Summer Court",
            "strict": strict,
        })

    resources = list(sheet.get("resources") or [])
    bsc_row = None
    bsc_idx = -1
    for i, r in enumerate(resources):
        if not isinstance(r, dict):
            continue
        if (r.get("key") or "").strip().lower() == "balm-of-summer-court-dice":
            bsc_row = dict(r); bsc_idx = i; break
    if bsc_row is None:
        bsc_row = {
            "key": "balm-of-summer-court-dice",
            "label": "Balm of the Summer Court dice",
            "current": druid_lv, "max": druid_lv, "reset": "long",
        }
        bsc_idx = len(resources)
        resources.append(bsc_row)
    bsc_cur = int(bsc_row.get("current") or 0)
    bsc_max = int(bsc_row.get("max") or druid_lv)
    if bsc_cur < dice_spent:
        return JSONResponse(status_code=409, content={
            "error": "no_uses_left",
            "label": "Balm of the Summer Court dice",
            "current": bsc_cur, "max": bsc_max,
            "requested": dice_spent,
        })

    try:
        result = dice_mod.roll(f"{dice_spent}d6")
        heal_total = max(dice_spent, int(result.total))
        breakdown = result.breakdown
    except dice_mod.DiceParseError:
        heal_total = dice_spent
        breakdown = ""
    temp_hp = dice_spent

    bsc_row["current"] = bsc_cur - dice_spent
    resources[bsc_idx] = bsc_row
    sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    await _mark_battle_economy(campaign_id, char.id, "bonus")

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "balm-of-summer-court-dice",
            "current": bsc_cur - dice_spent, "max": bsc_max,
        },
    })
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"☀️ Balm of the Summer Court — heal {heal_total} HP + "
                f"{temp_hp} temp HP (spent {dice_spent}d6)"
            ),
            "feature_desc": (
                f"{char.name} spends {dice_spent}d6 of fey energy to "
                f"restore {heal_total} HP and grant {temp_hp} temp HP "
                f"to an ally within 120 ft. (Dreams Druid Lv 2+ XGE "
                f"class feature; pool refills on long rest.)"
            ),
            "source": "balm-of-the-summer-court",
            "dice_spent": dice_spent,
            "dice_breakdown": breakdown,
            "heal_amount": heal_total,
            "temp_hp": temp_hp,
            "max_range_ft": 120,
            "dice_remaining": bsc_cur - dice_spent,
            "druid_level": druid_lv,
        },
    })

    return {
        "ok": True,
        "feature": "balm-of-the-summer-court",
        "dice_spent": dice_spent,
        "heal_amount": heal_total,
        "temp_hp": temp_hp,
        "max_range_ft": 120,
        "dice_remaining": bsc_cur - dice_spent,
        "max_dice": bsc_max,
        "druid_level": druid_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_combat_wild_shape")
async def use_combat_wild_shape(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.348 — Phase E.4 Druid subclass batch ship (Moon
    Druid Lv 2+, PHB) of the v2.99.193 phased completion plan —
    CLOSES the Druid batch (Moon was the last untouched circle).
    Combat Wild Shape (Moon Druid Lv 2+, PHB p.69): "You can use
    Wild Shape as a bonus action, rather than as an action.
    Additionally, while you are transformed by Wild Shape, you can
    use a bonus action to expend one spell slot to regain 1d8 hit
    points per level of the spell slot expended."

    Body: ``{character_id, slot_level?, override?}``. Costs a bonus
    chip. Two modes:
      - no ``slot_level`` → announce the bonus-action Wild Shape
        (use the existing /transform flow to actually shapeshift).
      - ``slot_level >= 1`` → roll ``<slot_level>d8`` server-side
        and announce the in-beast-form heal.
    v1 announce-only — the transform itself + spell-slot spend +
    HP application stay GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    slot_level_raw = body.get("slot_level")
    slot_level = 0
    if slot_level_raw is not None:
        try:
            slot_level = int(slot_level_raw)
        except (TypeError, ValueError):
            slot_level = 0
    if slot_level < 0 or slot_level > 9:
        raise HTTPException(400, "slot_level must be between 1 and 9")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Druid character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_moon_druid(sheet, 2):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "moon druid lv 2+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _druid_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "combat-wild-shape",
            "label": "Combat Wild Shape",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "bonus")

    druid_lv = _druid_level_from_sheet(sheet)
    mode = "heal" if slot_level >= 1 else "transform"
    heal_amount = 0
    dice_breakdown = ""
    if mode == "heal":
        try:
            result = dice_mod.roll(f"{slot_level}d8")
            heal_amount = max(slot_level, int(result.total))
            dice_breakdown = result.breakdown
        except dice_mod.DiceParseError:
            heal_amount = slot_level

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    if mode == "heal":
        feature_name = (
            f"🐺 Combat Wild Shape — heal {heal_amount} HP "
            f"(Lv {slot_level} slot, {slot_level}d8)"
        )
        feature_desc = (
            f"{char.name} expends a level {slot_level} spell slot "
            f"as a bonus action while transformed, regaining "
            f"{heal_amount} HP (1d8 per slot level). (Moon Druid "
            f"Lv 2+ PHB class feature.)"
        )
    else:
        feature_name = "🐺 Combat Wild Shape — Wild Shape as a bonus action"
        feature_desc = (
            f"{char.name} shapeshifts via Wild Shape as a bonus "
            f"action (rather than an action). While transformed, "
            f"can spend a bonus action + a spell slot to heal 1d8 "
            f"HP per slot level. (Moon Druid Lv 2+ PHB class "
            f"feature.)"
        )
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": feature_name,
            "feature_desc": feature_desc,
            "source": "combat-wild-shape",
            "mode": mode,
            "slot_level": slot_level,
            "heal_amount": heal_amount,
            "dice_breakdown": dice_breakdown,
            "druid_level": druid_lv,
        },
    })

    return {
        "ok": True,
        "feature": "combat-wild-shape",
        "mode": mode,
        "slot_level": slot_level,
        "heal_amount": heal_amount,
        "druid_level": druid_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_dark_ones_blessing")
async def use_dark_ones_blessing(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.349 — Phase G Warlock patron subclass batch OPEN
    (The Fiend Lv 1+, PHB) of the v2.99.193 phased completion
    plan. Dark One's Blessing (The Fiend Lv 1+, PHB p.109):
    "Starting at 1st level, when you reduce a hostile creature to
    0 hit points, you gain temporary hit points equal to your
    Charisma modifier + your warlock level (minimum of 1)."

    Body: ``{character_id}``. Costs no action (a reactive trigger
    on a kill). Computes the temp-HP amount server-side.

    v2.99.417 — Phase 4.2 of docs/plans/temp-hp-and-bonuses.md: the temp
    HP (CHA mod + warlock level, min 1) is now **applied to the warlock**
    via `_grant_temp_hp` (RAW non-stacking) instead of announce-only. The
    GM still decides when the kill trigger fires (the endpoint is the
    trigger). Response gains `temp_hp_applied`.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Warlock character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_fiend_warlock(sheet, 1):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "the fiend warlock lv 1+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _warlock_level_from_sheet(sheet),
        })

    try:
        cha_score = int((sheet.get("abilities") or {}).get("CHA", 10))
    except (TypeError, ValueError):
        cha_score = 10
    cha_mod = (cha_score - 10) // 2
    warlock_lv = _warlock_level_from_sheet(sheet)
    temp_hp = max(1, cha_mod + warlock_lv)

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"😈 Dark One's Blessing — +{temp_hp} temp HP"
            ),
            "feature_desc": (
                f"{char.name} drops a foe and is wreathed in "
                f"fiendish vigor: gains {temp_hp} temporary HP "
                f"(CHA mod {cha_mod:+d} + warlock level "
                f"{warlock_lv}, min 1). (The Fiend Warlock Lv 1+ "
                f"PHB class feature.)"
            ),
            "source": "dark-ones-blessing",
            "temp_hp": temp_hp,
            "cha_mod": cha_mod,
            "warlock_level": warlock_lv,
        },
    })

    # v2.99.417 — Phase 4.2: apply the temp HP to the warlock (self).
    gr = await _grant_temp_hp(
        db, campaign_id, {"char_id": char.id}, temp_hp,
        source="dark-ones-blessing",
    )

    return {
        "ok": True,
        "feature": "dark-ones-blessing",
        "temp_hp": temp_hp,
        "cha_mod": cha_mod,
        "warlock_level": warlock_lv,
        "temp_hp_applied": gr["temp_after"] > 0,
    }


@router.post("/api/campaign/{campaign_id}/use_fey_presence")
async def use_fey_presence(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.350 — Phase G Warlock patron subclass batch ship #2
    (The Archfey Lv 1+, PHB) of the v2.99.193 phased completion
    plan. Fey Presence (The Archfey Lv 1+, PHB p.109): "As an
    action, you can cause each creature in a 10-foot cube
    originating from you to make a Wisdom saving throw against
    your warlock spell save DC. The creatures that fail their
    saving throws are all charmed or frightened by you (your
    choice) until the end of your next turn. Once you use this
    feature, you can't use it again until you finish a short or
    long rest."

    Body: ``{character_id, effect?, target_combatant_ids?, override?}``.
    ``effect`` is "charmed" (default) or "frightened". Costs an action
    chip. Computes the warlock spell save DC server-side.

    v2.99.410 — Phase 3.4 of docs/plans/feature-saves.md: when
    ``target_combatant_ids`` (the creatures the caster picks out of the
    10-ft cube) is supplied, each target auto-resolves its WIS save via
    `_resolve_feature_save` (NPC inline / PC prompt) and, on a fail, gets
    Charmed or Frightened (per ``effect``) until the end of the caster's
    next turn (≈ 2 rounds; no repeated save). Without a target list it
    stays announce-only (the GM picks the cube + rolls).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    effect = (body.get("effect") or "charmed").strip().lower()
    if effect not in ("charmed", "frightened"):
        raise HTTPException(400, "effect must be 'charmed' or 'frightened'")
    target_ids = body.get("target_combatant_ids") or []
    if not isinstance(target_ids, list):
        raise HTTPException(400, "target_combatant_ids must be a list")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Warlock character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_archfey_warlock(sheet, 1):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "the archfey warlock lv 1+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _warlock_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "fey-presence",
            "label": "Fey Presence",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "action")

    try:
        cha_score = int((sheet.get("abilities") or {}).get("CHA", 10))
    except (TypeError, ValueError):
        cha_score = 10
    cha_mod = (cha_score - 10) // 2
    pb = int(sheet.get("proficiency_bonus") or 0)
    if pb <= 0:
        pb = 2 + (max(1, _warlock_level_from_sheet(sheet)) - 1) // 4
    save_dc = 8 + pb + cha_mod
    warlock_lv = _warlock_level_from_sheet(sheet)

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🧚 Fey Presence — 10-ft cube, WIS save DC "
                f"{save_dc} or {effect}"
            ),
            "feature_desc": (
                f"{char.name} projects the beguiling presence of "
                f"the fey: each creature in a 10-ft cube makes a "
                f"WIS save (DC {save_dc}) or is {effect} until the "
                f"end of {char.name}'s next turn. Refreshes on a "
                f"short or long rest. (The Archfey Warlock Lv 1+ "
                f"PHB class feature.)"
            ),
            "source": "fey-presence",
            "save_dc": save_dc,
            "effect": effect,
            "cube_ft": 10,
            "warlock_level": warlock_lv,
        },
    })

    # v2.99.410 — Phase 3.4: resolve each picked target's WIS save. On a
    # fail → Charmed or Frightened (per `effect`) until end of the
    # caster's next turn (≈ 2 rounds; not a repeated save).
    _cond_name = "Charmed" if effect == "charmed" else "Frightened"
    condition_buff = {
        "key": effect,
        "name": f"{_cond_name} (Fey Presence)",
        "icon": "🧚",
        "duration_rounds": 2,
        "duration_max": 2,
        "concentration": False,
        "source_spell": "Fey Presence",
        "effects": (
            ["regards the caster as friendly",
             "advantage on the caster's social interactions"]
            if effect == "charmed" else
            ["disadvantage on ability checks / attacks while the caster "
             "is in sight",
             "can't willingly move closer to the caster"]
        ),
    }
    feature_saves: list[dict] = []
    for tcid in target_ids:
        cb = _lookup_combatant(campaign_id, str(tcid).strip())
        if cb is None:
            continue
        sr = await _resolve_feature_save(
            db, campaign_id,
            caster_char_id=char.id, caster_char_name=char.name,
            target_combatant=cb,
            save_ability="WIS", dc=save_dc,
            note_label=f"Fey Presence save (DC {save_dc})",
            condition_buff=condition_buff,
            repeated_save=False,
            source="fey-presence",
            campaign=campaign,
            prompt_user=user,
            feature_name="Fey Presence",
        )
        feature_saves.append(sr)

    return {
        "ok": True,
        "feature": "fey-presence",
        "save_dc": save_dc,
        "effect": effect,
        "cube_ft": 10,
        "warlock_level": warlock_lv,
        "feature_saves": feature_saves,
    }


@router.post("/api/campaign/{campaign_id}/use_hexblades_curse")
async def use_hexblades_curse(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.351 — Phase G Warlock patron subclass batch ship #3
    (The Hexblade Lv 1+, XGE) of the v2.99.193 phased completion
    plan. Hexblade's Curse (The Hexblade Lv 1+, XGE p.55): "As a
    bonus action, choose one creature you can see within 30 feet
    of you. The target is cursed for 1 minute. ... you gain a
    bonus to damage rolls against the cursed target equal to your
    proficiency bonus; any attack roll you make against the cursed
    target is a critical hit on a roll of 19 or 20; if the cursed
    target dies, you regain hit points equal to your warlock level
    + your Charisma modifier (minimum of 1)." Once per short or
    long rest.

    Body: ``{character_id, target_combatant_id?, override?}``. Costs a
    bonus chip. The 1-per-short-or-long-rest budget is server-tracked
    (v2.99.388).

    v2.99.399 — Phase 2.3 of docs/plans/on-hit-riders.md: when a
    ``target_combatant_id`` is supplied, the feature **installs a
    `hexblades-curse` rider buff** keyed to that target —
    `weapon_hit_bonus_flat: <PB>` (every hit vs the cursed target deals
    +PB) and `weapon_hit_crit_range: 19` (crits on a 19–20 vs it) — so
    both auto-apply through the `/attack` pipeline. The on-death heal +
    the 1-minute / ends-on-death duration stay GM-tracked. Without a
    target it stays announce-only (back-compat).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    target_combatant_id = body.get("target_combatant_id") or None

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Warlock character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_hexblade_warlock(sheet, 1):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "the hexblade warlock lv 1+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _warlock_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "hexblades-curse",
            "label": "Hexblade's Curse",
            "strict": strict,
        })

    # v2.99.388 — Phase 1: server-tracked 1-per-short-or-long-rest budget
    # via the feature-use registry. Refilled by /rest on either rest
    # type. (The +PB damage / crit-19 / on-death heal riders stay
    # GM-tracked pending the Phase 2 on-hit rider primitive.)
    spent = _consume_feature_use(sheet, "hexblades_curse_uses")
    if spent is None:
        return JSONResponse(status_code=409, content={
            "error": "out_of_uses",
            "label": "Hexblade's Curse",
            "char_name": char.name,
            "source": "hexblades-curse",
            "uses_remaining": 0,
            "uses_max": _feature_use_max(sheet, "hexblades_curse_uses") or 1,
        })
    uses_remaining, uses_max = spent
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    await _mark_battle_economy(campaign_id, char.id, "bonus")

    try:
        cha_score = int((sheet.get("abilities") or {}).get("CHA", 10))
    except (TypeError, ValueError):
        cha_score = 10
    cha_mod = (cha_score - 10) // 2
    warlock_lv = _warlock_level_from_sheet(sheet)
    pb = int(sheet.get("proficiency_bonus") or 0)
    if pb <= 0:
        pb = 2 + (max(1, warlock_lv) - 1) // 4
    death_heal = max(1, warlock_lv + cha_mod)

    # v2.99.399 — Phase 2.3: install the on-hit rider buff keyed to the
    # cursed target. Every weapon hit vs it gains +PB damage
    # (weapon_hit_bonus_flat, NOT once-per-turn) and crits on a 19-20
    # (weapon_hit_crit_range). Re-cursing replaces the prior buff
    # (same-key refresh). 1-minute duration ≈ 10 rounds; the
    # ends-on-death and on-death-heal stay GM-tracked.
    buff_installed = False
    if target_combatant_id:
        curse_buff = {
            "key": "hexblades-curse",
            "name": "Hexblade's Curse",
            "icon": "🗡️",
            "duration_rounds": 10,
            "duration_max": 10,
            "concentration": False,
            "source_char_id": char.id,
            "effects": {
                "weapon_hit_bonus_flat": pb,
                "weapon_hit_bonus_target_combatant_id": target_combatant_id,
                "weapon_hit_crit_range": 19,
            },
            "desc": (
                f"Every weapon hit vs the cursed target deals +{pb} "
                f"damage and crits on a 19-20; on its death regain "
                f"{death_heal} HP. (The Hexblade Lv 1+; 1 minute.)"
            ),
        }
        buff_installed = await _install_buff(campaign_id, char.id, curse_buff)
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🗡️ Hexblade's Curse — +{pb} dmg, crit 19-20, "
                f"heal {death_heal} on kill"
            ),
            "feature_desc": (
                f"{char.name} curses a target within 30 ft for 1 "
                f"minute: +{pb} damage (proficiency bonus) and "
                f"crits on a 19-20 against it; on the target's "
                f"death, regain {death_heal} HP (warlock level "
                f"{warlock_lv} + CHA mod {cha_mod:+d}, min 1). "
                f"Refreshes on a short or long rest. (The Hexblade "
                f"Warlock Lv 1+ XGE class feature.)"
            ),
            "source": "hexblades-curse",
            "range_ft": 30,
            "damage_bonus": pb,
            "crit_range": 19,
            "death_heal": death_heal,
            "uses_remaining": uses_remaining,
            "uses_max": uses_max,
            "buff_installed": buff_installed,
            "target_combatant_id": target_combatant_id,
            "warlock_level": warlock_lv,
        },
    })

    return {
        "ok": True,
        "feature": "hexblades-curse",
        "range_ft": 30,
        "damage_bonus": pb,
        "crit_range": 19,
        "death_heal": death_heal,
        "uses_remaining": uses_remaining,
        "uses_max": uses_max,
        "buff_installed": buff_installed,
        "target_combatant_id": target_combatant_id,
        "warlock_level": warlock_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_awakened_mind")
async def use_awakened_mind(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.352 — Phase G Warlock patron subclass batch ship #4
    (The Great Old One Lv 1+, PHB) of the v2.99.193 phased
    completion plan. Awakened Mind (The Great Old One Lv 1+, PHB
    p.110): "Starting at 1st level, your alien knowledge gives you
    the ability to touch the minds of other creatures. You can
    telepathically speak to any creature you can see within 30
    feet of you. You don't need to share a language with the
    creature for it to understand your telepathic utterances, but
    the creature must be able to understand at least one
    language."

    Body: ``{character_id}``. At-will — costs no action / bonus /
    reaction. v1 announce-only — the target choice + one-way
    telepathy are GM-narrated.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Warlock character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_great_old_one_warlock(sheet, 1):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "the great old one warlock lv 1+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _warlock_level_from_sheet(sheet),
        })

    warlock_lv = _warlock_level_from_sheet(sheet)

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"👁️ Awakened Mind — telepathy to a creature within 30 ft"
            ),
            "feature_desc": (
                f"{char.name} touches an alien mind: speaks "
                f"telepathically (one-way) to any creature seen "
                f"within 30 ft. No shared language needed — the "
                f"creature only needs to understand at least one "
                f"language. At-will. (The Great Old One Warlock "
                f"Lv 1+ PHB class feature.)"
            ),
            "source": "awakened-mind",
            "range_ft": 30,
            "warlock_level": warlock_lv,
        },
    })

    return {
        "ok": True,
        "feature": "awakened-mind",
        "range_ft": 30,
        "warlock_level": warlock_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_healing_light")
async def use_healing_light(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.353 — Phase G Warlock patron subclass batch ship #5
    (The Celestial Lv 1+, XGE) of the v2.99.193 phased completion
    plan. Healing Light (The Celestial Lv 1+, XGE p.54): "You have
    a pool of d6s that you spend to fuel this healing. The number
    of dice in the pool equals 1 + your warlock level. As a bonus
    action, you can heal one creature you can see within 60 feet
    of you, spending dice from the pool. The maximum number of
    dice you can spend at once equals your Charisma modifier (a
    minimum of one die). You regain all expended dice when you
    finish a long rest."

    Body: ``{character_id, dice_spent?, override?}``. Default
    dice_spent = 1, capped at the per-use max (CHA mod, min 1) and
    the remaining pool. Costs a bonus chip. Auto-bootstraps a
    `healing-light-dice` resource (max = 1 + warlock_lv,
    reset=long). The heal dice are rolled server-side and
    broadcast; target HP application is GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    dice_spent_raw = body.get("dice_spent") or 1
    try:
        dice_spent = max(1, int(dice_spent_raw))
    except (TypeError, ValueError):
        dice_spent = 1

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Warlock character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_celestial_warlock(sheet, 1):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "the celestial warlock lv 1+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _warlock_level_from_sheet(sheet),
        })

    warlock_lv = _warlock_level_from_sheet(sheet)
    try:
        cha_score = int((sheet.get("abilities") or {}).get("CHA", 10))
    except (TypeError, ValueError):
        cha_score = 10
    cha_mod = (cha_score - 10) // 2
    per_use_max = max(1, cha_mod)
    pool_max = 1 + warlock_lv
    dice_spent = min(dice_spent, per_use_max)

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "healing-light",
            "label": "Healing Light",
            "strict": strict,
        })

    resources = list(sheet.get("resources") or [])
    hl_row = None
    hl_idx = -1
    for i, r in enumerate(resources):
        if not isinstance(r, dict):
            continue
        if (r.get("key") or "").strip().lower() == "healing-light-dice":
            hl_row = dict(r); hl_idx = i; break
    if hl_row is None:
        hl_row = {
            "key": "healing-light-dice",
            "label": "Healing Light dice",
            "current": pool_max, "max": pool_max, "reset": "long",
        }
        hl_idx = len(resources)
        resources.append(hl_row)
    hl_cur = int(hl_row.get("current") or 0)
    hl_max = int(hl_row.get("max") or pool_max)
    if hl_cur < dice_spent:
        return JSONResponse(status_code=409, content={
            "error": "no_uses_left",
            "label": "Healing Light dice",
            "current": hl_cur, "max": hl_max,
            "requested": dice_spent,
        })

    try:
        result = dice_mod.roll(f"{dice_spent}d6")
        heal_total = max(dice_spent, int(result.total))
        breakdown = result.breakdown
    except dice_mod.DiceParseError:
        heal_total = dice_spent
        breakdown = ""

    hl_row["current"] = hl_cur - dice_spent
    resources[hl_idx] = hl_row
    sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    await _mark_battle_economy(campaign_id, char.id, "bonus")

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "healing-light-dice",
            "current": hl_cur - dice_spent, "max": hl_max,
        },
    })
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🌟 Healing Light — heal {heal_total} HP "
                f"(spent {dice_spent}d6)"
            ),
            "feature_desc": (
                f"{char.name} channels celestial energy to restore "
                f"{heal_total} HP to a creature within 60 ft "
                f"(spent {dice_spent}d6 of the pool). (The "
                f"Celestial Warlock Lv 1+ XGE class feature; pool "
                f"= 1 + warlock level, refills on long rest.)"
            ),
            "source": "healing-light",
            "dice_spent": dice_spent,
            "dice_breakdown": breakdown,
            "heal_amount": heal_total,
            "max_range_ft": 60,
            "dice_remaining": hl_cur - dice_spent,
            "max_dice": hl_max,
            "per_use_max": per_use_max,
            "warlock_level": warlock_lv,
        },
    })

    return {
        "ok": True,
        "feature": "healing-light",
        "dice_spent": dice_spent,
        "heal_amount": heal_total,
        "max_range_ft": 60,
        "dice_remaining": hl_cur - dice_spent,
        "max_dice": hl_max,
        "per_use_max": per_use_max,
        "warlock_level": warlock_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_tentacle_of_the_deeps")
async def use_tentacle_of_the_deeps(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.354 — Phase G Warlock patron subclass batch ship #6
    (The Fathomless Lv 1+, TCE) of the v2.99.193 phased completion
    plan. Tentacle of the Deeps (The Fathomless Lv 1+, TCE p.70):
    "As a bonus action, you can create a 10-foot-long tentacle at
    a point you can see within 60 feet of you. ... you can make a
    melee spell attack against one creature within 10 feet of it.
    On a hit, the target takes 1d8 cold damage, and for 1 minute,
    its speed is reduced by 10 feet." Cold damage rises to 2d8 at
    Lv 10. Summonable a number of times equal to proficiency
    bonus per long rest.

    Body: ``{character_id, override?}``. Costs a bonus chip. Rolls
    the cold damage server-side + reports the melee-spell-attack
    bonus. v1 announce-only — the attack roll resolution, target
    choice, speed reduction, and uses-per-rest limit stay
    GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Warlock character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_fathomless_warlock(sheet, 1):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "the fathomless warlock lv 1+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _warlock_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "tentacle-of-the-deeps",
            "label": "Tentacle of the Deeps",
            "strict": strict,
        })

    # v2.99.391 — Phase 1: server-tracked PB-per-long-rest budget via the
    # feature-use registry. Refilled by /rest. (The attack roll +
    # cold-damage rider + speed reduction stay GM-tracked pending the
    # Phase 2 on-hit rider / Phase 7 summon-token primitives.)
    spent = _consume_feature_use(sheet, "tentacle_uses")
    if spent is None:
        return JSONResponse(status_code=409, content={
            "error": "out_of_uses",
            "label": "Tentacle of the Deeps",
            "char_name": char.name,
            "source": "tentacle-of-the-deeps",
            "uses_remaining": 0,
            "uses_max": _feature_use_max(sheet, "tentacle_uses") or 0,
        })
    uses_remaining, uses_max = spent
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    await _mark_battle_economy(campaign_id, char.id, "bonus")

    warlock_lv = _warlock_level_from_sheet(sheet)
    try:
        cha_score = int((sheet.get("abilities") or {}).get("CHA", 10))
    except (TypeError, ValueError):
        cha_score = 10
    cha_mod = (cha_score - 10) // 2
    pb = int(sheet.get("proficiency_bonus") or 0)
    if pb <= 0:
        pb = 2 + (max(1, warlock_lv) - 1) // 4
    attack_bonus = pb + cha_mod
    dice_count = 2 if warlock_lv >= 10 else 1
    try:
        result = dice_mod.roll(f"{dice_count}d8")
        cold_damage = int(result.total)
        breakdown = result.breakdown
    except dice_mod.DiceParseError:
        cold_damage = dice_count
        breakdown = ""

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🐙 Tentacle of the Deeps — melee spell atk "
                f"{attack_bonus:+d}, {cold_damage} cold on hit"
            ),
            "feature_desc": (
                f"{char.name} summons a 10-ft spectral tentacle "
                f"within 60 ft and lashes out: melee spell attack "
                f"{attack_bonus:+d} vs a creature within 10 ft. On "
                f"a hit, {cold_damage} cold damage ({dice_count}d8) "
                f"and the target's speed drops by 10 ft for 1 min. "
                f"(The Fathomless Warlock Lv 1+ TCE class feature; "
                f"summon PB times per long rest.)"
            ),
            "source": "tentacle-of-the-deeps",
            "summon_range_ft": 60,
            "reach_ft": 10,
            "attack_bonus": attack_bonus,
            "cold_damage": cold_damage,
            "damage_dice": f"{dice_count}d8",
            "dice_breakdown": breakdown,
            "speed_reduction_ft": 10,
            "uses_remaining": uses_remaining,
            "uses_max": uses_max,
            "warlock_level": warlock_lv,
        },
    })

    return {
        "ok": True,
        "feature": "tentacle-of-the-deeps",
        "summon_range_ft": 60,
        "reach_ft": 10,
        "attack_bonus": attack_bonus,
        "cold_damage": cold_damage,
        "damage_dice": f"{dice_count}d8",
        "speed_reduction_ft": 10,
        "uses_remaining": uses_remaining,
        "uses_max": uses_max,
        "warlock_level": warlock_lv,
    }


_GENIE_KIND_DAMAGE = {
    "dao": "bludgeoning",
    "djinni": "thunder",
    "efreeti": "fire",
    "marid": "cold",
}


@router.post("/api/campaign/{campaign_id}/use_genies_wrath")
async def use_genies_wrath(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.355 — Phase G Warlock patron subclass batch ship #7
    (The Genie Lv 1+, TCE) of the v2.99.193 phased completion plan
    — CLOSES the Warlock patron batch (Genie was the last
    untouched patron). Genie's Wrath (The Genie Lv 1+, TCE p.71):
    "Once during each of your turns when you hit with an attack
    roll, you can deal extra damage to the target equal to your
    proficiency bonus. The type of this damage is determined by
    your patron's kind: bludgeoning (dao), thunder (djinni), fire
    (efreeti), or cold (marid)."

    Body: ``{character_id, genie_kind?}``. ``genie_kind`` is one of
    dao / djinni / efreeti / marid (defaults to the sheet's
    ``genie_kind``, else "djinni"). No action cost (a once-per-turn
    rider on a hit). Computes the +PB bonus damage + its type
    server-side. v1 announce-only — the once-per-turn limit + the
    actual on-hit damage application stay GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Warlock character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_genie_warlock(sheet, 1):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "the genie warlock lv 1+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _warlock_level_from_sheet(sheet),
        })

    genie_kind = (
        body.get("genie_kind")
        or sheet.get("genie_kind")
        or "djinni"
    )
    genie_kind = str(genie_kind).strip().lower()
    if genie_kind not in _GENIE_KIND_DAMAGE:
        raise HTTPException(
            400, "genie_kind must be dao, djinni, efreeti, or marid")
    damage_type = _GENIE_KIND_DAMAGE[genie_kind]

    warlock_lv = _warlock_level_from_sheet(sheet)
    pb = int(sheet.get("proficiency_bonus") or 0)
    if pb <= 0:
        pb = 2 + (max(1, warlock_lv) - 1) // 4
    bonus_damage = pb

    # v2.99.450 — Phase 2 on-hit-rider retrofit (docs/plans/on-hit-riders.md):
    # install a non-target, once-per-turn rider so the first hit each turn
    # auto-adds +PB damage of the genie's element through the /attack
    # pipeline (was announce-only). Flat-only (no dice) — Genie's Wrath is
    # +proficiency bonus. 10-round duration ≈ a combat; RAW it's always-on.
    rider_installed = await _install_buff(campaign_id, char.id, {
        "key": "genies-wrath",
        "name": "Genie's Wrath",
        "icon": "🧞",
        "duration_rounds": 10,
        "duration_max": 10,
        "concentration": False,
        "source_char_id": char.id,
        "effects": {
            "weapon_hit_bonus_flat": bonus_damage,
            "weapon_hit_bonus_damage_type": damage_type,
            "weapon_hit_once_per_turn": True,
            "weapon_hit_flag": "genies_wrath",
        },
        "desc": (
            f"The first weapon hit each turn deals +{bonus_damage} "
            f"{damage_type} damage ({genie_kind} genie). (The Genie "
            f"Warlock Lv 1+.)"
        ),
    })
    if rider_installed:
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🧞 Genie's Wrath — +{bonus_damage} {damage_type} "
                f"({genie_kind})"
            ),
            "feature_desc": (
                f"{char.name} channels the vessel's element: once "
                f"this turn on a hit, deal +{bonus_damage} "
                f"{damage_type} damage (proficiency bonus; "
                f"{genie_kind} genie kind). (The Genie Warlock "
                f"Lv 1+ TCE class feature.)"
            ),
            "source": "genies-wrath",
            "genie_kind": genie_kind,
            "damage_type": damage_type,
            "bonus_damage": bonus_damage,
            "warlock_level": warlock_lv,
            "rider_installed": rider_installed,
        },
    })

    return {
        "ok": True,
        "feature": "genies-wrath",
        "genie_kind": genie_kind,
        "damage_type": damage_type,
        "bonus_damage": bonus_damage,
        "warlock_level": warlock_lv,
        "rider_installed": rider_installed,
    }


_SHADOW_ARTS_SPELLS = {
    "darkness", "darkvision", "pass without trace", "silence",
}


@router.post("/api/campaign/{campaign_id}/use_shadow_arts")
async def use_shadow_arts(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.356 — Phase G Monk Ways subclass batch OPEN (Way of
    Shadow Lv 3+, PHB) of the v2.99.193 phased completion plan.
    Shadow Arts (Way of Shadow Lv 3+, PHB p.80): "As an action,
    you can spend 2 ki points to cast Darkness, Darkvision, Pass
    without Trace, or Silence, without providing material
    components. Additionally, you gain the Minor Illusion cantrip
    if you don't already know it."

    Body: ``{character_id, spell?, override?}``. ``spell`` is one
    of darkness / darkvision / pass without trace / silence
    (default "darkness"). Costs an action chip + 2 ki. v1
    announce-only — the actual spell effect is GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    spell = (body.get("spell") or "darkness").strip().lower().replace("-", " ")
    if spell not in _SHADOW_ARTS_SPELLS:
        raise HTTPException(
            400,
            "spell must be darkness, darkvision, pass without trace, "
            "or silence",
        )

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Monk character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_way_of_shadow(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "way of shadow monk lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _monk_level_from_sheet(sheet),
        })

    # Ki resource lookup (key "ki"); Shadow Arts costs 2 ki.
    resources = list(sheet.get("resources") or [])
    ki_row = None
    ki_idx = -1
    for i, r in enumerate(resources):
        if not isinstance(r, dict):
            continue
        if (r.get("key") or "").strip().lower() == "ki":
            ki_row = dict(r); ki_idx = i; break
    if ki_row is None:
        raise HTTPException(404, "No Ki resource on this sheet")
    ki_cur = int(ki_row.get("current") or 0)
    if ki_cur < 2:
        return JSONResponse(status_code=409, content={
            "error": "no_ki",
            "available": ki_cur,
            "required": 2,
            "label": "Shadow Arts",
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "shadow-arts",
            "label": "Shadow Arts",
            "strict": strict,
        })

    ki_remaining = ki_cur - 2
    ki_row["current"] = ki_remaining
    resources[ki_idx] = ki_row
    sheet["resources"] = resources
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    await _mark_battle_economy(campaign_id, char.id, "action")

    monk_lv = _monk_level_from_sheet(sheet)

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "ki",
            "current": ki_remaining,
        },
    })
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🌑 Shadow Arts — cast {spell.title()} (2 ki)"
            ),
            "feature_desc": (
                f"{char.name} bends shadow to ki, casting "
                f"{spell.title()} without material components "
                f"(spent 2 ki, {ki_remaining} left). (Way of "
                f"Shadow Monk Lv 3+ PHB class feature; also grants "
                f"Minor Illusion.)"
            ),
            "source": "shadow-arts",
            "spell": spell,
            "ki_spent": 2,
            "ki_remaining": ki_remaining,
            "monk_level": monk_lv,
        },
    })

    return {
        "ok": True,
        "feature": "shadow-arts",
        "spell": spell,
        "ki_spent": 2,
        "ki_remaining": ki_remaining,
        "monk_level": monk_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_kensei_shot")
async def use_kensei_shot(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.357 — Phase G Monk Ways subclass batch ship #2 (Way
    of the Kensei Lv 3+, XGE) of the v2.99.193 phased completion
    plan. Kensei's Shot (Way of the Kensei Lv 3+, XGE p.34): "You
    can use a bonus action on your turn to make your ranged
    attacks more deadly. When you do so, any ranged attack you
    make with a kensei weapon this turn deals an extra 1d4 damage
    of the weapon's type. This benefit lasts until the end of the
    current turn."

    Body: ``{character_id, override?}``. Costs a bonus chip, no
    ki. Rolls the 1d4 bonus damage server-side.

    v2.99.403 — Phase 2 of docs/plans/on-hit-riders.md: installs a
    `kensei-shot` on-hit rider buff (non-target, NOT once-per-turn — it
    benefits every qualifying hit this turn) so a weapon hit auto-adds
    +1d4 of the weapon's type through the /attack pipeline:
    `weapon_hit_bonus_dice: "1d4"`, no damage-type key (defaults to the
    weapon's type), no target key, 1-round duration (drops at turn
    advance, matching "until the end of this turn"). Simplification: the
    substrate has no ranged/kensei-weapon filter, so the rider applies to
    any weapon hit this turn, not strictly ranged kensei swings — the
    RAW weapon restriction stays GM-tracked. `buff_installed` added.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Monk character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_way_of_kensei(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "way of the kensei monk lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _monk_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "kensei-shot",
            "label": "Kensei's Shot",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "bonus")

    monk_lv = _monk_level_from_sheet(sheet)
    try:
        result = dice_mod.roll("1d4")
        bonus_damage = int(result.total)
        breakdown = result.breakdown
    except dice_mod.DiceParseError:
        bonus_damage = 1
        breakdown = ""

    # v2.99.403 — install the this-turn, non-target rider so a weapon
    # hit this turn auto-adds +1d4 of the weapon's type. NOT once-per-turn
    # (RAW: every qualifying ranged hit this turn benefits); the 1d4 is
    # re-rolled per hit at /attack time. No damage-type key → the uplift
    # inherits the weapon's type. 1-round duration drops at turn advance.
    buff_installed = await _install_buff(campaign_id, char.id, {
        "key": "kensei-shot",
        "name": "Kensei's Shot",
        "icon": "🏹",
        "duration_rounds": 1,
        "duration_max": 1,
        "concentration": False,
        "source_char_id": char.id,
        "effects": {
            "weapon_hit_bonus_dice": "1d4",
        },
        "desc": (
            "Ranged kensei weapon hits this turn deal +1d4 of the "
            "weapon's type. (Way of the Kensei Monk Lv 3+.)"
        ),
    })
    if buff_installed:
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🏹 Kensei's Shot — +{bonus_damage} dmg this turn"
            ),
            "feature_desc": (
                f"{char.name} steadies the bow: ranged kensei "
                f"weapon attacks deal +{bonus_damage} (1d4) damage "
                f"of the weapon's type until the end of this turn. "
                f"(Way of the Kensei Monk Lv 3+ XGE class feature.)"
            ),
            "source": "kensei-shot",
            "bonus_damage": bonus_damage,
            "damage_dice": "1d4",
            "dice_breakdown": breakdown,
            "monk_level": monk_lv,
            "buff_installed": buff_installed,
        },
    })

    return {
        "ok": True,
        "feature": "kensei-shot",
        "bonus_damage": bonus_damage,
        "damage_dice": "1d4",
        "monk_level": monk_lv,
        "buff_installed": buff_installed,
    }


@router.post("/api/campaign/{campaign_id}/use_hands_of_healing")
async def use_hands_of_healing(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.358 — Phase G Monk Ways subclass batch ship #3 (Way
    of Mercy Lv 3+, TCE) of the v2.99.193 phased completion plan.
    Hands of Healing (Way of Mercy Lv 3+, TCE p.51): "As an
    action, you can spend 1 ki point to touch a creature and
    restore a number of hit points equal to a roll of your Martial
    Arts die + your Wisdom modifier."

    Body: ``{character_id, override?}``. Costs an action chip +
    1 ki. Rolls the heal (Martial Arts die + WIS mod) server-side.
    v1 announce-only — the target choice + HP application stay
    GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Monk character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_way_of_mercy(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "way of mercy monk lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _monk_level_from_sheet(sheet),
        })

    resources = list(sheet.get("resources") or [])
    ki_row = None
    ki_idx = -1
    for i, r in enumerate(resources):
        if not isinstance(r, dict):
            continue
        if (r.get("key") or "").strip().lower() == "ki":
            ki_row = dict(r); ki_idx = i; break
    if ki_row is None:
        raise HTTPException(404, "No Ki resource on this sheet")
    ki_cur = int(ki_row.get("current") or 0)
    if ki_cur < 1:
        return JSONResponse(status_code=409, content={
            "error": "no_ki",
            "available": ki_cur,
            "required": 1,
            "label": "Hands of Healing",
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "hands-of-healing",
            "label": "Hands of Healing",
            "strict": strict,
        })

    ki_remaining = ki_cur - 1
    ki_row["current"] = ki_remaining
    resources[ki_idx] = ki_row
    sheet["resources"] = resources
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    await _mark_battle_economy(campaign_id, char.id, "action")

    monk_lv = _monk_level_from_sheet(sheet)
    ma_die = _martial_arts_die(monk_lv)
    try:
        wis_score = int((sheet.get("abilities") or {}).get("WIS", 10))
    except (TypeError, ValueError):
        wis_score = 10
    wis_mod = (wis_score - 10) // 2
    try:
        result = dice_mod.roll(f"1d{ma_die}")
        die_roll = int(result.total)
        breakdown = result.breakdown
    except dice_mod.DiceParseError:
        die_roll = 1
        breakdown = ""
    heal_amount = max(1, die_roll + wis_mod)

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "ki",
            "current": ki_remaining,
        },
    })
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🩹 Hands of Healing — heal {heal_amount} HP (1 ki)"
            ),
            "feature_desc": (
                f"{char.name} channels mercy: touches a creature "
                f"and restores {heal_amount} HP (1d{ma_die} Martial "
                f"Arts die {die_roll} + WIS mod {wis_mod:+d}). Spent "
                f"1 ki, {ki_remaining} left. (Way of Mercy Monk "
                f"Lv 3+ TCE class feature.)"
            ),
            "source": "hands-of-healing",
            "heal_amount": heal_amount,
            "martial_arts_die": f"1d{ma_die}",
            "die_roll": die_roll,
            "wis_mod": wis_mod,
            "dice_breakdown": breakdown,
            "ki_spent": 1,
            "ki_remaining": ki_remaining,
            "monk_level": monk_lv,
        },
    })

    return {
        "ok": True,
        "feature": "hands-of-healing",
        "heal_amount": heal_amount,
        "martial_arts_die": f"1d{ma_die}",
        "die_roll": die_roll,
        "wis_mod": wis_mod,
        "ki_spent": 1,
        "ki_remaining": ki_remaining,
        "monk_level": monk_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_radiant_sun_bolt")
async def use_radiant_sun_bolt(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.359 — Phase G Monk Ways subclass batch ship #5 (Way
    of the Sun Soul Lv 3+, XGE) of the v2.99.193 phased completion
    plan. Radiant Sun Bolt (Way of the Sun Soul Lv 3+, XGE p.35):
    "You can hurl searing bolts of magical radiance. ... Make a
    ranged spell attack against a target within 30 feet ... using
    your Dexterity modifier for the attack roll. On a hit, the
    target takes radiant damage equal to your Martial Arts die +
    your Dexterity modifier."

    Body: ``{character_id, override?}``. Costs an action chip (the
    bolt is part of the Attack action). Computes the ranged-spell-
    attack bonus (PB + DEX mod) and rolls the radiant damage
    (Martial Arts die + DEX mod) server-side. v1 announce-only —
    the attack roll resolution + target choice stay GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Monk character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_way_of_sun_soul(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "way of the sun soul monk lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _monk_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "radiant-sun-bolt",
            "label": "Radiant Sun Bolt",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "action")

    monk_lv = _monk_level_from_sheet(sheet)
    ma_die = _martial_arts_die(monk_lv)
    try:
        dex_score = int((sheet.get("abilities") or {}).get("DEX", 10))
    except (TypeError, ValueError):
        dex_score = 10
    dex_mod = (dex_score - 10) // 2
    pb = int(sheet.get("proficiency_bonus") or 0)
    if pb <= 0:
        pb = 2 + (max(1, monk_lv) - 1) // 4
    attack_bonus = pb + dex_mod
    try:
        result = dice_mod.roll(f"1d{ma_die}")
        die_roll = int(result.total)
        breakdown = result.breakdown
    except dice_mod.DiceParseError:
        die_roll = 1
        breakdown = ""
    radiant_damage = max(1, die_roll + dex_mod)

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"☀️ Radiant Sun Bolt — ranged atk {attack_bonus:+d}, "
                f"{radiant_damage} radiant on hit"
            ),
            "feature_desc": (
                f"{char.name} hurls a searing bolt of radiance: "
                f"ranged spell attack {attack_bonus:+d} vs a target "
                f"within 30 ft. On a hit, {radiant_damage} radiant "
                f"(1d{ma_die} Martial Arts die {die_roll} + DEX mod "
                f"{dex_mod:+d}). (Way of the Sun Soul Monk Lv 3+ "
                f"XGE class feature; spend 1 ki for two more bolts "
                f"as a bonus action.)"
            ),
            "source": "radiant-sun-bolt",
            "range_ft": 30,
            "attack_bonus": attack_bonus,
            "radiant_damage": radiant_damage,
            "martial_arts_die": f"1d{ma_die}",
            "die_roll": die_roll,
            "dex_mod": dex_mod,
            "dice_breakdown": breakdown,
            "monk_level": monk_lv,
        },
    })

    return {
        "ok": True,
        "feature": "radiant-sun-bolt",
        "range_ft": 30,
        "attack_bonus": attack_bonus,
        "radiant_damage": radiant_damage,
        "martial_arts_die": f"1d{ma_die}",
        "die_roll": die_roll,
        "dex_mod": dex_mod,
        "monk_level": monk_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_drunken_technique")
async def use_drunken_technique(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.360 — Phase G Monk Ways subclass batch ship #6 (Way
    of the Drunken Master Lv 3+, XGE) of the v2.99.193 phased
    completion plan. Drunken Technique (Way of the Drunken Master
    Lv 3+, XGE p.33): "Whenever you use Flurry of Blows, you gain
    the benefit of the Disengage action, and your walking speed
    increases by 10 feet until the end of the current turn."

    Body: ``{character_id}``. No additional action cost — this is
    an automatic rider on Flurry of Blows (which already spends the
    bonus action + 1 ki).

    v2.158.18 — Phase 8 Monk diversification (first Monk subclass
    feature flipped from announce-only to tracked this session —
    pushes the diversification arc to 9/12 classes). Install a
    1-turn `drunken-technique-active` buff carrying:
      * `effects.disengage: True` (reuses the engine flag from
        Step of the Wind / `effects.disengage` — movement
        doesn't provoke OAs this turn)
      * `effects.drunken_technique_speed_bonus_ft: 10`
      * `effects.drunken_technique_rider_of: "flurry-of-blows"`
    `duration_rounds: 1` (expires at next turn-start tick per
    RAW "until the end of the current turn"). Different from
    the permanent-passive Phase 8 commits — this is a per-Flurry
    rider that the existing OA-prompting flow already consumes
    via `effects.disengage`.

    v2.158.37 — Phase 2 finisher: the +10 ft speed half of the
    rider is now live. The buff also carries the engine-generic
    `effects.speed_bonus_ft: 10`, which `effective_speed_walk`
    already folds into a combatant's `/token/move` speed cap (and
    the Mov chip). Previously the rider stored the bonus only under
    the descriptive `drunken_technique_speed_bonus_ft` key, which
    nothing read — so the speed half was inert.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Monk character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_way_of_drunken_master(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "way of the drunken master monk lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _monk_level_from_sheet(sheet),
        })

    monk_lv = _monk_level_from_sheet(sheet)

    # v2.158.18 — install the 1-turn rider buff. The
    # `effects.disengage` flag is the same one Step of the Wind
    # installs; the OA-prompting flow already consumes it.
    # v2.158.37 — Phase 2 read site for the +10 ft speed rider: the
    # buff now ALSO carries the generic `effects.speed_bonus_ft: 10`
    # key, which `effective_speed_walk` (via `effective_speed_bonus_ft`)
    # already sums into a combatant's move cap — same engine path
    # Longstrider / Glory Paladin / Step of the Wind use. The
    # descriptive `drunken_technique_speed_bonus_ft` key is kept for the
    # state-contract surface; `speed_bonus_ft` is the one the engine reads.
    buff_installed = await _install_buff(campaign_id, char.id, {
        "key": "drunken-technique-active",
        "name": "🍶 Drunken Technique",
        "icon": "🍶",
        "duration_rounds": 1,
        "duration_max": 1,
        "concentration": False,
        "source_char_id": char.id,
        "effects": {
            "disengage": True,
            "speed_bonus_ft": 10,
            "drunken_technique_speed_bonus_ft": 10,
            "drunken_technique_rider_of": "flurry-of-blows",
        },
        "desc": (
            f"{char.name}'s Flurry of Blows triggers the drunken "
            f"weave: movement doesn't provoke OAs this turn + "
            f"+10 ft walking speed. (Way of the Drunken Master "
            f"Monk Lv 3+ XGE; expires at end of turn.)"
        ),
    })
    if buff_installed:
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🍶 Drunken Technique — Disengage + 10 ft speed"
            ),
            "feature_desc": (
                f"{char.name} weaves and staggers through the "
                f"Flurry of Blows: gains the benefit of the "
                f"Disengage action and +10 ft walking speed until "
                f"the end of this turn. (Way of the Drunken Master "
                f"Monk Lv 3+ XGE class feature; rider on Flurry of "
                f"Blows.)"
            ),
            "source": "drunken-technique",
            "disengage": True,
            "speed_bonus_ft": 10,
            "monk_level": monk_lv,
            "buff_installed": buff_installed,
        },
    })

    return {
        "ok": True,
        "feature": "drunken-technique",
        "disengage": True,
        "speed_bonus_ft": 10,
        "monk_level": monk_lv,
        "buff_installed": buff_installed,
    }


@router.post("/api/campaign/{campaign_id}/use_arms_of_the_astral_self")
async def use_arms_of_the_astral_self(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.361 — Phase G Monk Ways subclass batch ship #7 (Way
    of the Astral Self Lv 3+, TCE) of the v2.99.193 phased
    completion plan. Arms of the Astral Self (Way of the Astral
    Self Lv 3+, TCE p.50): "As a bonus action, you can spend 1 ki
    point to summon the arms of your astral self ... For 10
    minutes ... you can use your Wisdom modifier in place of your
    Strength ... your unarmed strikes [via the arms] reach 5 feet
    farther ... deal force damage equal to your Martial Arts die +
    your Wisdom modifier."

    Body: ``{character_id, override?}``. Costs a bonus chip +
    1 ki. Reports the +5 ft reach + the per-hit damage formula
    (Martial Arts die + WIS mod). v1 announce-only — the actual
    attacks + WIS-for-STR substitution stay GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Monk character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_way_of_astral_self(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "way of the astral self monk lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _monk_level_from_sheet(sheet),
        })

    resources = list(sheet.get("resources") or [])
    ki_row = None
    ki_idx = -1
    for i, r in enumerate(resources):
        if not isinstance(r, dict):
            continue
        if (r.get("key") or "").strip().lower() == "ki":
            ki_row = dict(r); ki_idx = i; break
    if ki_row is None:
        raise HTTPException(404, "No Ki resource on this sheet")
    ki_cur = int(ki_row.get("current") or 0)
    if ki_cur < 1:
        return JSONResponse(status_code=409, content={
            "error": "no_ki",
            "available": ki_cur,
            "required": 1,
            "label": "Arms of the Astral Self",
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "arms-of-the-astral-self",
            "label": "Arms of the Astral Self",
            "strict": strict,
        })

    ki_remaining = ki_cur - 1
    ki_row["current"] = ki_remaining
    resources[ki_idx] = ki_row
    sheet["resources"] = resources
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    await _mark_battle_economy(campaign_id, char.id, "bonus")

    monk_lv = _monk_level_from_sheet(sheet)
    ma_die = _martial_arts_die(monk_lv)
    try:
        wis_score = int((sheet.get("abilities") or {}).get("WIS", 10))
    except (TypeError, ValueError):
        wis_score = 10
    wis_mod = (wis_score - 10) // 2

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "ki",
            "current": ki_remaining,
        },
    })
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"👐 Arms of the Astral Self — +5 ft reach, "
                f"1d{ma_die}{wis_mod:+d} force"
            ),
            "feature_desc": (
                f"{char.name} summons spectral arms for 10 min "
                f"(spent 1 ki, {ki_remaining} left): unarmed "
                f"strikes reach 5 ft farther and deal force damage "
                f"= 1d{ma_die} + WIS mod {wis_mod:+d}; can use WIS "
                f"in place of STR for checks/saves. (Way of the "
                f"Astral Self Monk Lv 3+ TCE class feature.)"
            ),
            "source": "arms-of-the-astral-self",
            "reach_bonus_ft": 5,
            "melee_damage_die": f"1d{ma_die}",
            "wis_mod": wis_mod,
            "duration_minutes": 10,
            "ki_spent": 1,
            "ki_remaining": ki_remaining,
            "monk_level": monk_lv,
        },
    })

    return {
        "ok": True,
        "feature": "arms-of-the-astral-self",
        "reach_bonus_ft": 5,
        "melee_damage_die": f"1d{ma_die}",
        "wis_mod": wis_mod,
        "duration_minutes": 10,
        "ki_spent": 1,
        "ki_remaining": ki_remaining,
        "monk_level": monk_lv,
    }


