@router.post("/api/campaign/{campaign_id}/use_touch_of_death")
async def use_touch_of_death(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.363 — Phase G Monk Ways subclass batch ship #9 (Way
    of the Long Death Lv 3+, SCAG) of the v2.99.193 phased
    completion plan — CLOSES the Monk Ways batch (Long Death was
    the last untouched way). Touch of Death (Way of the Long Death
    Lv 3+, SCAG p.130): "When you reduce a creature within 5 feet
    of you to 0 hit points, you gain temporary hit points equal to
    your Wisdom modifier + your monk level (minimum of 1
    temporary hit point)."

    Body: ``{character_id}``. No action cost (a reactive trigger
    on a kill). Computes the temp-HP amount server-side.

    v2.99.418 — Phase 4.2 of docs/plans/temp-hp-and-bonuses.md: the temp
    HP (WIS mod + monk level, min 1) is now **applied to the monk** via
    `_grant_temp_hp` (RAW non-stacking) instead of announce-only. The GM
    still decides when the on-kill trigger fires (the endpoint is the
    trigger). Response gains `temp_hp_applied`.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Monk character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_way_of_long_death(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "way of the long death monk lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _monk_level_from_sheet(sheet),
        })

    monk_lv = _monk_level_from_sheet(sheet)
    try:
        wis_score = int((sheet.get("abilities") or {}).get("WIS", 10))
    except (TypeError, ValueError):
        wis_score = 10
    wis_mod = (wis_score - 10) // 2
    temp_hp = max(1, wis_mod + monk_lv)

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"💀 Touch of Death — +{temp_hp} temp HP"
            ),
            "feature_desc": (
                f"{char.name} drains vitality from a dying foe: "
                f"gains {temp_hp} temporary HP (WIS mod "
                f"{wis_mod:+d} + monk level {monk_lv}, min 1) on "
                f"reducing a creature within 5 ft to 0 HP. (Way of "
                f"the Long Death Monk Lv 3+ SCAG class feature.)"
            ),
            "source": "touch-of-death",
            "temp_hp": temp_hp,
            "wis_mod": wis_mod,
            "monk_level": monk_lv,
        },
    })

    # v2.99.418 — Phase 4.2: apply the temp HP to the monk (self).
    gr = await _grant_temp_hp(
        db, campaign_id, {"char_id": char.id}, temp_hp,
        source="touch-of-death",
    )

    return {
        "ok": True,
        "feature": "touch-of-death",
        "temp_hp": temp_hp,
        "wis_mod": wis_mod,
        "monk_level": monk_lv,
        "temp_hp_applied": gr["temp_after"] > 0,
    }


_TOTEM_SPIRIT_BENEFITS = {
    "bear": (
        "While raging, you have resistance to all damage except "
        "psychic — you can wade into any battle and shrug off "
        "blows."
    ),
    "eagle": (
        "While raging and not wearing heavy armor, opportunity "
        "attacks against you have disadvantage and you can take "
        "the Dash action as a bonus action."
    ),
    "wolf": (
        "While raging, your allies have advantage on melee attack "
        "rolls against any creature within 5 ft of you that is "
        "hostile to you."
    ),
}


@router.post("/api/campaign/{campaign_id}/use_totem_spirit")
async def use_totem_spirit(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.364 — Phase G Barbarian Paths subclass batch OPEN
    (Path of the Totem Warrior Lv 3+, PHB) of the v2.99.193 phased
    completion plan. Totem Spirit (Path of the Totem Warrior Lv
    3+, PHB p.50): at 3rd level you choose a totem animal — Bear,
    Eagle, or Wolf — and gain its rage benefit. Bear: resistance
    to all damage except psychic while raging. Eagle: attackers
    have disadvantage on opportunity attacks + Dash as a bonus
    action while raging (no heavy armor). Wolf: allies have
    advantage on melee attacks vs enemies within 5 ft of you while
    raging.

    Body: ``{character_id, totem?}``. ``totem`` is bear (default),
    eagle, or wolf. No action cost — declares the chosen totem's
    passive rage benefit. v1 announce-only — the resistance /
    OA-disadvantage / ally-advantage effects are GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    totem = (body.get("totem") or "bear").strip().lower()
    if totem not in _TOTEM_SPIRIT_BENEFITS:
        raise HTTPException(400, "totem must be bear, eagle, or wolf")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Barbarian character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_totem_warrior(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "totem warrior barbarian lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _barbarian_level_from_sheet(sheet),
        })

    barb_lv = _barbarian_level_from_sheet(sheet)
    benefit = _TOTEM_SPIRIT_BENEFITS[totem]
    totem_icon = {"bear": "🐻", "eagle": "🦅", "wolf": "🐺"}[totem]

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"{totem_icon} Totem Spirit — {totem.title()}"
            ),
            "feature_desc": (
                f"{char.name} calls on the spirit of the "
                f"{totem.title()}: {benefit} (Path of the Totem "
                f"Warrior Barbarian Lv 3+ PHB class feature.)"
            ),
            "source": "totem-spirit",
            "totem": totem,
            "benefit": benefit,
            "barbarian_level": barb_lv,
        },
    })

    return {
        "ok": True,
        "feature": "totem-spirit",
        "totem": totem,
        "benefit": benefit,
        "barbarian_level": barb_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_divine_fury")
async def use_divine_fury(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.365 — Phase G Barbarian Paths subclass batch ship #2
    (Path of the Zealot Lv 3+, XGE) of the v2.99.193 phased
    completion plan. Divine Fury (Path of the Zealot Lv 3+, XGE
    p.11): "While you're raging, the first creature you hit on each
    of your turns with a weapon attack takes extra damage equal to
    1d6 + half your barbarian level. The extra damage is necrotic
    or radiant; you choose the type when you gain this feature."

    Body: ``{character_id, damage_type?}``. ``damage_type`` is
    radiant (default) or necrotic. No action cost (a rider on the
    first weapon hit each turn while raging). Rolls the bonus
    damage server-side (1d6 + barbarian level // 2).

    v2.99.402 — Phase 2 of docs/plans/on-hit-riders.md: installs a
    `divine-fury` on-hit rider buff (non-target, once-per-turn) so the
    first weapon hit each turn auto-adds +1d6 + half-level of the chosen
    type through the /attack pipeline — `weapon_hit_bonus_dice: "1d6"` +
    `weapon_hit_bonus_flat: <half level>` + `weapon_hit_once_per_turn`,
    no target key (applies to any hit). 1-minute (10-round) duration
    approximates "while raging"; the RAW rage gate stays GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    damage_type = (body.get("damage_type") or "radiant").strip().lower()
    if damage_type not in ("radiant", "necrotic"):
        raise HTTPException(400, "damage_type must be radiant or necrotic")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Barbarian character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_zealot_path(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "zealot barbarian lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _barbarian_level_from_sheet(sheet),
        })

    barb_lv = _barbarian_level_from_sheet(sheet)
    half_lv = barb_lv // 2
    try:
        result = dice_mod.roll("1d6")
        die_roll = int(result.total)
        breakdown = result.breakdown
    except dice_mod.DiceParseError:
        die_roll = 1
        breakdown = ""
    bonus_damage = die_roll + half_lv

    # v2.99.402 — install the non-target, once-per-turn on-hit rider so
    # the first weapon hit each turn auto-adds +1d6 + half-level of the
    # chosen type via _compute_attack_auto_uplifts. No target key (Divine
    # Fury applies to any creature you hit, not a marked one); the 1d6 is
    # re-rolled at /attack time. 10-round duration ≈ the 1-minute rage.
    buff_installed = await _install_buff(campaign_id, char.id, {
        "key": "divine-fury",
        "name": "Divine Fury",
        "icon": "⚡",
        "duration_rounds": 10,
        "duration_max": 10,
        "concentration": False,
        "source_char_id": char.id,
        "effects": {
            "weapon_hit_bonus_dice": "1d6",
            "weapon_hit_bonus_flat": half_lv,
            "weapon_hit_bonus_damage_type": damage_type,
            "weapon_hit_once_per_turn": True,
            "weapon_hit_flag": "divine_fury",
        },
        "desc": (
            f"The first weapon hit each turn (while raging) deals "
            f"+1d6+{half_lv} {damage_type} damage. (Path of the "
            f"Zealot Barbarian Lv 3+.)"
        ),
    })
    if buff_installed:
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"⚡ Divine Fury — +{bonus_damage} {damage_type} "
                f"(1d6 {die_roll} + {half_lv})"
            ),
            "feature_desc": (
                f"{char.name} channels divine fury: the first "
                f"creature hit this turn with a weapon attack while "
                f"raging takes +{bonus_damage} {damage_type} damage "
                f"(1d6 {die_roll} + half barbarian level {half_lv}). "
                f"(Path of the Zealot Barbarian Lv 3+ XGE class "
                f"feature.)"
            ),
            "source": "divine-fury",
            "damage_type": damage_type,
            "bonus_damage": bonus_damage,
            "die_roll": die_roll,
            "half_level": half_lv,
            "dice_breakdown": breakdown,
            "barbarian_level": barb_lv,
            "buff_installed": buff_installed,
        },
    })

    return {
        "ok": True,
        "feature": "divine-fury",
        "damage_type": damage_type,
        "bonus_damage": bonus_damage,
        "die_roll": die_roll,
        "half_level": half_lv,
        "barbarian_level": barb_lv,
        "buff_installed": buff_installed,
    }


