@router.post("/api/campaign/{campaign_id}/use_storm_aura")
async def use_storm_aura(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.367 — Phase G Barbarian Paths subclass batch ship #4
    (Path of the Storm Herald Lv 3+, XGE) of the v2.99.193 phased
    completion plan. Storm Aura (Path of the Storm Herald Lv 3+,
    XGE p.10): a 10-ft aura while raging. Choose Desert (each other
    creature in the aura takes fire damage), Sea (one creature in
    the aura makes a DEX save or takes lightning), or Tundra (one
    creature in the aura gains temp HP). Magnitudes scale at Lv
    10/15/20.

    Body: ``{character_id, environment?}``. ``environment`` is
    desert (default), sea, or tundra. No action cost (the aura
    activates with your rage). The Sea lightning is rolled
    server-side.

    v2.99.426 — Phase 5.2 of docs/plans/auras.md: the **desert**
    environment ("each other creature in your aura takes fire damage")
    now installs a `storm-aura` aura buff (`effects.aura` with a fire
    `damage` payload, `affects: "others"`, 10-ft radius), so the v2.99.425
    aura tick auto-applies the fire damage to every other creature in
    range at the start of each of the barbarian's turns. Sea (one
    creature, Dex save) and Tundra (one chosen creature gains temp HP)
    are single-target *choices*, not auto-tick-all, so they stay
    announce-only (GM/player picks the target). Response gains
    `aura_installed`.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    environment = (body.get("environment") or "desert").strip().lower()
    if environment not in ("desert", "sea", "tundra"):
        raise HTTPException(400, "environment must be desert, sea, or tundra")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Barbarian character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_storm_herald(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "storm herald barbarian lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _barbarian_level_from_sheet(sheet),
        })

    barb_lv = _barbarian_level_from_sheet(sheet)
    tiers = sum(1 for t in (10, 15, 20) if barb_lv >= t)

    effect = {"aura_radius_ft": 10, "environment": environment}
    if environment == "desert":
        fire_damage = 2 + tiers
        effect["fire_damage"] = fire_damage
        effect_summary = (
            f"each other creature in the 10-ft aura takes "
            f"{fire_damage} fire damage"
        )
    elif environment == "sea":
        sea_dice = 1 + tiers
        try:
            result = dice_mod.roll(f"{sea_dice}d6")
            lightning_damage = int(result.total)
            breakdown = result.breakdown
        except dice_mod.DiceParseError:
            lightning_damage = sea_dice
            breakdown = ""
        effect["lightning_damage"] = lightning_damage
        effect["lightning_dice"] = f"{sea_dice}d6"
        effect["dice_breakdown"] = breakdown
        effect["save"] = "dex"
        effect_summary = (
            f"one creature in the aura makes a DEX save or takes "
            f"{lightning_damage} lightning ({sea_dice}d6)"
        )
    else:  # tundra
        temp_hp = 2 + tiers
        effect["temp_hp"] = temp_hp
        effect_summary = (
            f"one creature in the aura gains {temp_hp} temporary HP"
        )

    env_icon = {"desert": "🏜️", "sea": "🌊", "tundra": "❄️"}[environment]

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"{env_icon} Storm Aura — {environment.title()}"
            ),
            "feature_desc": (
                f"{char.name} emanates a {environment} storm aura "
                f"while raging: {effect_summary}. (Path of the "
                f"Storm Herald Barbarian Lv 3+ XGE class feature.)"
            ),
            "source": "storm-aura",
            **effect,
            "barbarian_level": barb_lv,
        },
    })

    # v2.99.426 — Phase 5.2: the desert environment installs an aura buff
    # so the v2.99.425 tick applies the fire damage to every other
    # creature in range at the start of each of the barbarian's turns.
    # RAW "each OTHER creature" → affects "others" (allies included). The
    # 10-round duration approximates the 1-minute rage. Sea/tundra are
    # single-target choices → stay announce-only.
    aura_installed = False
    if environment == "desert":
        aura_installed = await _install_buff(campaign_id, char.id, {
            "key": "storm-aura",
            "name": "Storm Aura (Desert)",
            "icon": env_icon,
            "duration_rounds": 10,
            "duration_max": 10,
            "concentration": False,
            "source_char_id": char.id,
            "effects": {
                "aura": {
                    "radius_ft": 10,
                    "affects": "others",
                    "damage": {"expr": str(fire_damage), "type": "fire"},
                    "source": "storm-aura-desert",
                    "label": "Storm Aura (Desert)",
                },
            },
            "desc": (
                f"While raging, each other creature within 10 ft takes "
                f"{fire_damage} fire damage at the start of your turn. "
                f"(Storm Herald Barbarian Lv 3+.)"
            ),
        })
        if aura_installed:
            _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    return {
        "ok": True,
        "feature": "storm-aura",
        **effect,
        "barbarian_level": barb_lv,
        "aura_installed": aura_installed,
    }


