@router.post("/api/campaign/{campaign_id}/use_form_of_the_beast")
async def use_form_of_the_beast(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.368 — Phase G Barbarian Paths subclass batch ship #5
    (Path of the Beast Lv 3+, TCE) of the v2.99.193 phased
    completion plan — CLOSES the Barbarian Paths batch (Beast was
    the last untouched path). Form of the Beast (Path of the Beast
    Lv 3+, TCE p.9): when you enter your rage, manifest a natural
    weapon as part of the bonus action — Bite (1d8 piercing,
    self-heal), Claws (1d6 slashing, extra attack), or Tail (1d8
    piercing, 10-ft reach, reaction AC). Lasts until your rage
    ends.

    Body: ``{character_id, form?}``. ``form`` is bite, claws
    (default), or tail. No separate action cost (manifested as
    part of entering rage). v1 announce-only — the natural-weapon
    attacks + special riders are GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    form = (body.get("form") or "claws").strip().lower()
    if form not in _FORM_OF_THE_BEAST:
        raise HTTPException(400, "form must be bite, claws, or tail")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Barbarian character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_path_of_beast(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "path of the beast barbarian lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _barbarian_level_from_sheet(sheet),
        })

    barb_lv = _barbarian_level_from_sheet(sheet)
    form_data = _FORM_OF_THE_BEAST[form]
    form_icon = {"bite": "🦷", "claws": "🐾", "tail": "🦎"}[form]

    # v2.158.20 — install the form-parameter buff. 10 rounds =
    # 1 minute rage duration. Idempotent on re-press via key
    # dedupe (overwrites any prior form selection).
    buff_installed = await _install_buff(campaign_id, char.id, {
        "key": "form-of-the-beast-active",
        "name": f"{form_icon} Form of the Beast ({form.title()})",
        "icon": form_icon,
        "duration_rounds": 10,
        "duration_max": 10,
        "concentration": False,
        "source_char_id": char.id,
        "effects": {
            "form_of_the_beast_active": True,
            "form_of_the_beast_form": form,
            "form_of_the_beast_damage_die": form_data["damage_die"],
            "form_of_the_beast_damage_type": form_data["damage_type"],
            "form_of_the_beast_reach_ft": form_data["reach_ft"],
            "form_of_the_beast_special": form_data["special"],
        },
        "desc": (
            f"{char.name} manifests a {form} natural weapon "
            f"({form_data['damage_die']} {form_data['damage_type']}, "
            f"reach {form_data['reach_ft']} ft) while raging. "
            f"{form_data['special']} (Path of the Beast Barbarian "
            f"Lv 3+ TCE; expires when rage ends.)"
        ),
    })
    if buff_installed:
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"{form_icon} Form of the Beast — {form.title()} "
                f"({form_data['damage_die']} {form_data['damage_type']})"
            ),
            "feature_desc": (
                f"{char.name} manifests a {form} as a natural "
                f"weapon while raging: {form_data['damage_die']} "
                f"{form_data['damage_type']}, reach "
                f"{form_data['reach_ft']} ft. {form_data['special']} "
                f"(Path of the Beast Barbarian Lv 3+ TCE class "
                f"feature.)"
            ),
            "source": "form-of-the-beast",
            "form": form,
            **form_data,
            "barbarian_level": barb_lv,
            "buff_installed": buff_installed,
        },
    })

    return {
        "ok": True,
        "feature": "form-of-the-beast",
        "form": form,
        **form_data,
        "barbarian_level": barb_lv,
        "buff_installed": buff_installed,
    }


def _pc_active_natural_weapons(
    sheet: dict, campaign_id: int, character_id: int,
) -> list[dict]:
    """v2.158.25 — Phase 2 read site for the v2.158.20 Form of the
    Beast buff (and any future natural-weapon-grant buffs).

    Walks the PC's active buffs for entries that carry natural-weapon
    parameters and returns a list of attack-dict-shaped entries
    (mirroring ``sheet["attacks"]``) so callers can render them as
    additional attack options while the buff is active. Each entry
    carries:

      * ``name`` — e.g. "Bite (Form of the Beast)"
      * ``attack_bonus`` — string like "+7" (STR mod + proficiency)
      * ``damage`` — e.g. "1d8+4" (die from buff + STR mod)
      * ``damage_type`` — buff's damage type
      * ``range`` — e.g. "5 ft" (reach from buff)
      * ``desc`` — the buff's special-rider text
      * ``source_buff_key`` — back-pointer to the granting buff
      * ``form`` — the form key (bite / claws / tail) for callers
        that need to surface variant labels

    Today this covers ``form-of-the-beast-active`` (Path of the Beast
    Barbarian Lv 3+ TCE); the helper is shaped to accommodate future
    natural-weapon buffs (Form of Dread, Polymorph beast shapes,
    Bestial Soul) by reading effects.*_active flags and *_form /
    *_damage_die / *_damage_type / *_reach_ft keys with the same
    contract.
    """
    out: list[dict] = []
    abilities = sheet.get("abilities") or {}
    try:
        str_score = int(abilities.get("STR") or 10)
    except (TypeError, ValueError):
        str_score = 10
    str_mod = (str_score - 10) // 2
    try:
        prof = int(sheet.get("proficiency_bonus") or 2)
    except (TypeError, ValueError):
        prof = 2
    for buff in _get_buffs(campaign_id, int(character_id)):
        if not isinstance(buff, dict):
            continue
        effects = buff.get("effects") or {}
        if effects.get("form_of_the_beast_active"):
            form = str(effects.get("form_of_the_beast_form") or "claws")
            die = str(effects.get("form_of_the_beast_damage_die") or "1d6")
            dmg_type = str(
                effects.get("form_of_the_beast_damage_type") or "slashing"
            )
            try:
                reach_ft = int(effects.get("form_of_the_beast_reach_ft") or 5)
            except (TypeError, ValueError):
                reach_ft = 5
            special = str(effects.get("form_of_the_beast_special") or "")
            atk_bonus = str_mod + prof
            dmg_bonus = str_mod
            damage_expr = f"{die}{dmg_bonus:+d}" if dmg_bonus else die
            entry = {
                "name": f"{form.title()} (Form of the Beast)",
                "attack_bonus": f"{atk_bonus:+d}",
                "damage": damage_expr,
                "damage_type": dmg_type,
                "range": f"{reach_ft} ft",
                "desc": special,
                "source_buff_key": "form-of-the-beast-active",
                "form": form,
            }
            out.append(entry)
    return out


@router.get("/api/campaign/{campaign_id}/active_natural_weapons")
def active_natural_weapons(
    campaign_id: int,
    character_id: int,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.158.25 — Phase 2 read site for natural-weapon-grant buffs
    (today: Form of the Beast Lv 3+ Barbarian; future: similar shape-
    change buffs). Returns the merged list of natural weapons the PC
    currently has access to via active buffs, in ``sheet["attacks"]``-
    shaped dicts so callers can render them as additional attack
    options without re-deriving the buff effect flags client-side.

    Query: ``?character_id=N``.

    Response:
    ```
    {
      "ok": True,
      "character_id": N,
      "natural_weapons": [
        {"name": "Bite (Form of the Beast)",
         "attack_bonus": "+7",
         "damage": "1d8+4",
         "damage_type": "piercing",
         "range": "5 ft",
         "desc": "...",
         "source_buff_key": "form-of-the-beast-active",
         "form": "bite"},
         ...
      ]
    }
    ```

    Empty list when no qualifying buff is active. See
    ``_pc_active_natural_weapons`` for the resolution logic.
    """
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == int(character_id),
        Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")
    sheet = dict(char.sheet or {})
    weapons = _pc_active_natural_weapons(
        sheet, campaign_id, int(character_id),
    )
    return {
        "ok": True,
        "character_id": int(character_id),
        "natural_weapons": weapons,
    }


@router.post(
    "/api/campaign/{campaign_id}/use_form_of_the_beast_claws_attack"
)
async def use_form_of_the_beast_claws_attack(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.158.29 — Phase 2 rider for the v2.158.20 Form of the Beast
    CLAWS form (Path of the Beast Barbarian Lv 3+ TCE p.9). RAW:
    "Immediately after you use the Attack action on your turn to attack
    with your claws, you can make one additional attack with your claws
    as a bonus action."

    Body: ``{character_id, target_combatant_id?, target_name?, override?}``.

    Gates:
      * an active Form of the Beast buff whose form is ``claws`` (the
        v2.158.25 read site `_pc_active_natural_weapons` surfaces it);
        otherwise 409 ``no_claws_form``;
      * once-per-turn via the attacker's economy flag
        ``fb_claws_extra_used`` (409 ``already_used``);
      * Phase 4 over-budget gate on the BONUS slot (RAW: the extra
        claw attack is a bonus action), with the standard
        ``override`` / strict-mode handling.

    When a ``target_combatant_id`` is supplied the extra claw attack is
    resolved server-side (d20 vs AC, damage on a hit) reusing the same
    helpers as Horde Breaker. Consumes the bonus slot, marks the
    once-per-turn flag, and broadcasts ``feature_used``
    (source ``form-of-the-beast-claws``).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    target_name = (str(body.get("target_name") or "")).strip()[:80]
    target_combatant_id = body.get("target_combatant_id") or None
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    natural_weapons = _pc_active_natural_weapons(sheet, campaign_id, char.id)
    claws = next(
        (w for w in natural_weapons if str(w.get("form")) == "claws"),
        None,
    )
    if claws is None:
        return JSONResponse(status_code=409, content={
            "error": "no_claws_form",
            "feature": "form-of-the-beast-claws",
        })

    # Once-per-turn gate via the attacker combatant's economy flag.
    _state = hub.get_battle(campaign_id)
    _atk_cb = next(
        (c for c in (_state.get("combatants") or [])
         if c.get("char_id") == char.id), None,
    ) if _state else None
    if _atk_cb and bool((_atk_cb.get("economy") or {}).get(
            "fb_claws_extra_used")):
        return JSONResponse(status_code=409, content={
            "error": "already_used",
            "feature": "form-of-the-beast-claws",
        })

    # Phase 4 over-budget gate (bonus slot — RAW: bonus action).
    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "form-of-the-beast-claws",
            "label": "Form of the Beast — Claw attack",
            "strict": strict,
        })

    attacked = False
    hit = False
    crit = False
    attack_total = 0
    target_ac = 0
    damage_rolled = 0
    damage_applied = 0
    damage_type = str(claws.get("damage_type") or "slashing")
    if target_combatant_id:
        target_combatant = _lookup_combatant(campaign_id, target_combatant_id)
        if not target_combatant:
            raise HTTPException(404, "Target not in battle")
        try:
            atk_bonus = int(
                str(claws.get("attack_bonus") or "0").replace("+", "").strip()
                or 0)
        except (TypeError, ValueError):
            atk_bonus = 0
        dmg_expr = str(claws.get("damage") or "1d6")
        target_ac = _read_target_ac(db, campaign_id, target_combatant)
        attacked = True
        atk_roll_expr = f"1d20{atk_bonus:+d}"
        try:
            _ar = dice_mod.roll(atk_roll_expr)
            attack_total, _abd = int(_ar.total), _ar.breakdown
        except dice_mod.DiceParseError:
            attack_total, _abd = 0, ""
        _nat_m = _re.search(r"\[(\d+)\]", _abd)
        nat = int(_nat_m.group(1)) if _nat_m else (attack_total - atk_bonus)
        if nat == 20:
            hit, crit = True, True
        elif nat == 1:
            hit, crit = False, False
        else:
            hit, crit = (attack_total >= target_ac), False
        if hit:
            roll_expr = _double_dice_for_crit(dmg_expr) if crit else dmg_expr
            try:
                damage_rolled = max(0, int(dice_mod.roll(roll_expr).total))
            except dice_mod.DiceParseError:
                damage_rolled = 0
            if damage_rolled > 0:
                _res = await _apply_damage_to_combatant(
                    db, campaign_id, target_combatant, damage_rolled,
                    damage_type, is_crit=crit, is_attack=True,
                    attacker_char_id=char.id,
                )
                damage_applied = int(_res.get("applied") or 0)

    await _mark_battle_economy(campaign_id, char.id, "bonus")
    await _mark_attack_flag(campaign_id, char.id, "fb_claws_extra")

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    target_phrase = f" vs {target_name}" if target_name else ""
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🐾 Form of the Beast — Claw attack{target_phrase}"
            ),
            "feature_desc": (
                f"{char.name} made one additional claw attack{target_phrase} "
                f"as a bonus action (Path of the Beast Barbarian Lv 3+ TCE; "
                f"once per turn)."
            ),
            "source": "form-of-the-beast-claws",
            "target_name": target_name,
            "attacked": attacked,
            "hit": hit,
            "damage_applied": damage_applied,
            "over_budget": was_used,
            "over_budget_slot": "bonus" if was_used else "",
        },
    })

    return {"ok": True, "feature": "form-of-the-beast-claws",
            "target_name": target_name,
            "attacked": attacked,
            "hit": hit,
            "crit": crit,
            "attack_total": attack_total,
            "target_ac": target_ac,
            "damage_rolled": damage_rolled,
            "damage_applied": damage_applied,
            "damage_type": damage_type}


@router.post("/api/campaign/{campaign_id}/use_mage_hand_legerdemain")
async def use_mage_hand_legerdemain(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.369 — Phase G Rogue archetype sweep (Arcane Trickster
    Lv 3+, PHB) of the v2.99.193 phased completion plan — rounds
    out the Rogue archetypes (Arcane Trickster was the last
    untouched one). Mage Hand Legerdemain (Arcane Trickster Lv 3+,
    PHB p.97): "When you cast Mage Hand, you can make the spectral
    hand invisible, and you can perform the following additional
    tasks with it: stow or retrieve an object in a container worn
    or carried by another creature; use thieves' tools to pick
    locks and disarm traps at range. You can perform one of these
    tasks without being noticed if you beat a creature's passive
    Perception with a Sleight of Hand check."

    Body: ``{character_id}``. No action cost beyond the Mage Hand
    cast itself (controlled as a bonus action).

    v2.158.17 — Phase 8 Rogue diversification (first Rogue
    subclass feature flipped from announce-only to tracked this
    session — pushes the diversification arc to 8/12 classes).
    Install a permanent `mage-hand-legerdemain-active` buff
    carrying the parameter flags:
      * `effects.mage_hand_legerdemain_range_ft: 30`
      * `effects.mage_hand_legerdemain_invisible: True`
      * `effects.mage_hand_legerdemain_bonus_action_control: True`
      * `effects.mage_hand_legerdemain_unnoticed_check`:
        `"sleight_of_hand_vs_passive_perception"`
    Phase 2 (deferred): when the Mage Hand cantrip is cast +
    targets a humanoid carry, the spell-cast flow reads the buff
    and surfaces the Legerdemain task picker (stow/retrieve,
    pick locks/disarm traps, unnoticed-on-Sleight-vs-passive-
    Perception). The buff captures the parameters so the read
    site has a stable contract.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Rogue character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_arcane_trickster(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "arcane trickster rogue lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _rogue_level_from_sheet(sheet),
        })

    rogue_lv = _rogue_level_from_sheet(sheet)
    tasks = [
        "stow or retrieve an object in another creature's container",
        "pick locks and disarm traps at range (thieves' tools)",
        "control the hand as a bonus action",
    ]

    # v2.158.17 — install the parameter-flag buff. Permanent
    # passive (idempotent on re-press via key dedupe). Phase 2
    # (deferred): Mage Hand cast flow reads
    # `effects.mage_hand_legerdemain_*` off the caster's
    # `_buffs_active` and surfaces the Legerdemain task picker.
    buff_installed = await _install_buff(campaign_id, char.id, {
        "key": "mage-hand-legerdemain-active",
        "name": "🖐️ Mage Hand Legerdemain",
        "icon": "🖐️",
        "duration_rounds": 100000,
        "duration_max": 100000,
        "permanent": True,
        "concentration": False,
        "source_char_id": char.id,
        "effects": {
            "mage_hand_legerdemain_range_ft": 30,
            "mage_hand_legerdemain_invisible": True,
            "mage_hand_legerdemain_bonus_action_control": True,
            "mage_hand_legerdemain_unnoticed_check": (
                "sleight_of_hand_vs_passive_perception"
            ),
        },
        "desc": (
            f"{char.name} can cast Mage Hand invisible at 30 ft + "
            f"work Legerdemain tasks (stow/retrieve, pick "
            f"locks/disarm traps at range) controlled as a bonus "
            f"action. Unnoticed on Sleight-of-Hand vs passive "
            f"Perception. (Arcane Trickster Rogue Lv 3+ passive "
            f"permanent. Phase 2: Mage Hand cast flow reads "
            f"these flags.)"
        ),
    })
    if buff_installed:
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🖐️ Mage Hand Legerdemain — invisible hand (30 ft)"
            ),
            "feature_desc": (
                f"{char.name} conjures an invisible spectral Mage "
                f"Hand within 30 ft and works mischief: stow or "
                f"retrieve objects from others, pick locks or "
                f"disarm traps at range, all controlled as a bonus "
                f"action — and unnoticed on a winning Sleight of "
                f"Hand check vs passive Perception. (Arcane "
                f"Trickster Rogue Lv 3+ PHB class feature.)"
            ),
            "source": "mage-hand-legerdemain",
            "range_ft": 30,
            "invisible": True,
            "tasks": tasks,
            "rogue_level": rogue_lv,
            "buff_installed": buff_installed,
        },
    })

    return {
        "ok": True,
        "feature": "mage-hand-legerdemain",
        "range_ft": 30,
        "invisible": True,
        "tasks": tasks,
        "rogue_level": rogue_lv,
        "buff_installed": buff_installed,
    }


@router.post("/api/campaign/{campaign_id}/use_fighting_spirit")
async def use_fighting_spirit(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.370 — Phase G Fighter martial archetype sweep
    (Samurai Lv 3+, XGE) of the v2.99.193 phased completion plan.
    Fighting Spirit (Samurai Lv 3+, XGE p.31): "As a bonus action
    on your turn, you can give yourself advantage on weapon attack
    rolls until the end of the current turn. When you do so, you
    also gain 5 temporary hit points. The number of temporary hit
    points increases ... to 10 at 10th level and 15 at 15th
    level. You can use this feature three times. You regain all
    expended uses when you finish a long rest."

    Body: ``{character_id, override?}``. Costs a bonus chip.
    Computes the temp-HP amount by Fighter level (5/10/15)
    server-side. The 3-per-long-rest budget is server-tracked (v2.99.387).

    v2.99.419 — Phase 4.2 of docs/plans/temp-hp-and-bonuses.md: the temp
    HP (5/10/15 by level) is now **applied to the samurai** via
    `_grant_temp_hp` (RAW non-stacking) instead of announce-only. The
    until-end-of-turn attack advantage stays GM-tracked. Response gains
    `temp_hp_applied`.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Fighter character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_samurai(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "samurai fighter lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _fighter_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "fighting-spirit",
            "label": "Fighting Spirit",
            "strict": strict,
        })

    # v2.99.387 — Phase 1: server-tracked 3-per-long-rest budget via the
    # feature-use registry. Refilled by /rest. (Temp-HP application is
    # still GM-tracked pending the Phase 4 temp-HP primitive.)
    spent = _consume_feature_use(sheet, "fighting_spirit_uses")
    if spent is None:
        return JSONResponse(status_code=409, content={
            "error": "out_of_uses",
            "label": "Fighting Spirit",
            "char_name": char.name,
            "source": "fighting-spirit",
            "uses_remaining": 0,
            "uses_max": _feature_use_max(sheet, "fighting_spirit_uses") or 3,
        })
    uses_remaining, uses_max = spent
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    await _mark_battle_economy(campaign_id, char.id, "bonus")

    fighter_lv = _fighter_level_from_sheet(sheet)
    temp_hp = 15 if fighter_lv >= 15 else 10 if fighter_lv >= 10 else 5

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"⚔️ Fighting Spirit — advantage + {temp_hp} temp HP"
            ),
            "feature_desc": (
                f"{char.name} steels their resolve: advantage on "
                f"weapon attack rolls until the end of this turn "
                f"and gains {temp_hp} temporary HP. Usable 3 times "
                f"per long rest. (Samurai Fighter Lv 3+ XGE class "
                f"feature.)"
            ),
            "source": "fighting-spirit",
            "advantage_on_weapon_attacks": True,
            "temp_hp": temp_hp,
            "uses_remaining": uses_remaining,
            "uses_max": uses_max,
            "fighter_level": fighter_lv,
        },
    })

    # v2.99.419 — Phase 4.2: apply the temp HP to the samurai (self).
    gr = await _grant_temp_hp(
        db, campaign_id, {"char_id": char.id}, temp_hp,
        source="fighting-spirit",
    )

    return {
        "ok": True,
        "feature": "fighting-spirit",
        "advantage_on_weapon_attacks": True,
        "temp_hp": temp_hp,
        "uses_remaining": uses_remaining,
        "uses_max": uses_max,
        "fighter_level": fighter_lv,
        "temp_hp_applied": gr["temp_after"] > 0,
    }


@router.post("/api/campaign/{campaign_id}/use_protective_field")
async def use_protective_field(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.371 — Phase G Fighter martial archetype sweep (Psi
    Warrior Lv 3+, TCE) of the v2.99.193 phased completion plan.
    Protective Field (Psi Warrior Psionic Power, Lv 3+, TCE p.40):
    "When you or another creature you can see within 30 feet of
    you takes damage, you can use your reaction to expend one
    Psionic Energy die, roll it, and reduce the damage by the
    number rolled plus your Intelligence modifier (minimum
    reduction of 1)."

    Body: ``{character_id, override?}``. Costs a reaction. Rolls
    the Psionic Energy die (size scales with Fighter level) + INT
    mod server-side. v1 announce-only — the damage reduction
    application + the Psionic Energy dice pool are GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    target_combatant_id = body.get("target_combatant_id") or None

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Fighter character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_psi_warrior(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "psi warrior fighter lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _fighter_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "reaction")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "reaction",
            "char_name": char.name,
            "source": "protective-field",
            "label": "Protective Field",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "reaction")

    fighter_lv = _fighter_level_from_sheet(sheet)
    die_size = _psionic_energy_die(fighter_lv)
    try:
        int_score = int((sheet.get("abilities") or {}).get("INT", 10))
    except (TypeError, ValueError):
        int_score = 10
    int_mod = (int_score - 10) // 2
    try:
        result = dice_mod.roll(f"1d{die_size}")
        die_roll = int(result.total)
        breakdown = result.breakdown
    except dice_mod.DiceParseError:
        die_roll = 1
        breakdown = ""
    reduction = max(1, die_roll + int_mod)

    # v2.99.456 — Phase 7: apply the damage reduction by restoring
    # `reduction` HP to the protected creature (it just took the damage;
    # reducing it = healing that much back, capped at max). Was
    # announce-only. The "took damage within 30 ft" trigger stays
    # GM/UI-tracked — the caller names who's being shielded.
    protected = False
    applied = 0
    if target_combatant_id:
        target_combatant = _lookup_combatant(campaign_id, target_combatant_id)
        if not target_combatant:
            raise HTTPException(404, "Target not in battle")
        protected = True
        hr = await _apply_heal_to_combatant(
            db, campaign_id, target_combatant, reduction)
        applied = int(hr.get("applied") or 0)

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🛡️ Protective Field — reduce damage by {reduction} "
                f"(1d{die_size} {die_roll} {int_mod:+d})"
            ),
            "feature_desc": (
                f"{char.name} weaves a telekinetic shield: as a "
                f"reaction, reduce damage to a creature within 30 "
                f"ft by {reduction} (1d{die_size} Psionic Energy "
                f"die {die_roll} + INT mod {int_mod:+d}, min 1). "
                f"(Psi Warrior Fighter Lv 3+ TCE class feature.)"
            ),
            "source": "protective-field",
            "reduction": reduction,
            "psionic_die": f"1d{die_size}",
            "die_roll": die_roll,
            "int_mod": int_mod,
            "fighter_level": fighter_lv,
            "protected": protected,
            "applied": applied,
        },
    })

    return {
        "ok": True,
        "feature": "protective-field",
        "reduction": reduction,
        "psionic_die": f"1d{die_size}",
        "die_roll": die_roll,
        "int_mod": int_mod,
        "fighter_level": fighter_lv,
        "protected": protected,
        "applied": applied,
    }


