@router.post("/api/campaign/{campaign_id}/use_arcane_shot")
async def use_arcane_shot(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.374 — Phase G Fighter martial archetype sweep (Arcane
    Archer Lv 3+, XGE) of the v2.99.193 phased completion plan.
    Arcane Shot (Arcane Archer Lv 3+, XGE p.28): once per turn
    when you fire an arrow as part of the Attack action, apply one
    Arcane Shot option to it. Two uses, regained on a short or
    long rest. Save DC = 8 + proficiency bonus + DEX modifier.

    Body: ``{character_id, arrow?}``. ``arrow`` is one of
    banishing / beguiling / bursting (default) / enfeebling /
    grasping / piercing / seeking / shadow. No separate action
    cost (a rider on the attack). Rolls the option's bonus damage
    + computes the save DC server-side. v1 announce-only — the
    attack/save resolution + 2-uses-per-rest limit are GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    arrow = (body.get("arrow") or "bursting").strip().lower()
    if arrow not in _ARCANE_SHOT_OPTIONS:
        raise HTTPException(
            400,
            "arrow must be one of: " + ", ".join(sorted(_ARCANE_SHOT_OPTIONS)),
        )

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Fighter character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_arcane_archer(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "arcane archer fighter lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _fighter_level_from_sheet(sheet),
        })

    # v2.99.390 — Phase 1: server-tracked 2-per-short-or-long-rest budget
    # via the feature-use registry. Refilled by /rest on either rest
    # type. (The bonus damage / save resolution stay GM-tracked pending
    # the Phase 2/3 primitives.)
    spent = _consume_feature_use(sheet, "arcane_shot_uses")
    if spent is None:
        return JSONResponse(status_code=409, content={
            "error": "out_of_uses",
            "label": "Arcane Shot",
            "char_name": char.name,
            "source": "arcane-shot",
            "uses_remaining": 0,
            "uses_max": _feature_use_max(sheet, "arcane_shot_uses") or 2,
        })
    uses_remaining, uses_max = spent
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    fighter_lv = _fighter_level_from_sheet(sheet)
    pb = int(sheet.get("proficiency_bonus") or 0)
    if pb <= 0:
        pb = 2 + (max(1, fighter_lv) - 1) // 4
    try:
        dex_score = int((sheet.get("abilities") or {}).get("DEX", 10))
    except (TypeError, ValueError):
        dex_score = 10
    dex_mod = (dex_score - 10) // 2
    save_dc = 8 + pb + dex_mod

    option = _ARCANE_SHOT_OPTIONS[arrow]
    bonus_damage = 0
    breakdown = ""
    if option["dice"]:
        try:
            result = dice_mod.roll(option["dice"])
            bonus_damage = int(result.total)
            breakdown = result.breakdown
        except dice_mod.DiceParseError:
            bonus_damage = 0

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    dmg_clause = (
        f"+{bonus_damage} {option['damage_type']} ({option['dice']}) "
        if option["dice"] else ""
    )
    save_clause = (
        f"{option['save'].upper()} save DC {save_dc}: "
        if option["save"] else ""
    )
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🏹 Arcane Shot — {arrow.title()} Arrow "
                f"{('+' + str(bonus_damage) + ' ' + option['damage_type']) if option['dice'] else ''}"
            ),
            "feature_desc": (
                f"{char.name} looses a {arrow} arrow: {dmg_clause}"
                f"{save_clause}{option['effect']}. (Arcane Archer "
                f"Fighter Lv 3+ XGE class feature; 2 uses per short "
                f"or long rest.)"
            ),
            "source": "arcane-shot",
            "arrow": arrow,
            "bonus_damage": bonus_damage,
            "damage_dice": option["dice"],
            "damage_type": option["damage_type"],
            "save": option["save"],
            "save_dc": save_dc,
            "effect": option["effect"],
            "uses_remaining": uses_remaining,
            "uses_max": uses_max,
            "fighter_level": fighter_lv,
        },
    })

    return {
        "ok": True,
        "feature": "arcane-shot",
        "arrow": arrow,
        "bonus_damage": bonus_damage,
        "damage_dice": option["dice"],
        "damage_type": option["damage_type"],
        "save": option["save"],
        "save_dc": save_dc,
        "effect": option["effect"],
        "uses_remaining": uses_remaining,
        "uses_max": uses_max,
        "fighter_level": fighter_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_unwavering_mark")
async def use_unwavering_mark(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.375 — Phase G Fighter martial archetype sweep
    (Cavalier Lv 3+, XGE) of the v2.99.193 phased completion plan.
    Unwavering Mark (Cavalier Lv 3+, XGE p.30): "When you hit a
    creature with a melee weapon attack, you can mark the creature
    until the end of your next turn. ... While it is within 5 feet
    of you, a creature marked by you has disadvantage on any
    attack roll that doesn't target you. ... if a creature marked
    by you deals damage to anyone other than you, you can make a
    special melee weapon attack against the marked creature as a
    bonus action on your next turn ... with advantage, and if it
    hits, the attack deals extra damage equal to half your fighter
    level." Usable STR-modifier times per long rest for the
    special attack.

    Body: ``{character_id}``. No separate action cost (the mark is
    a rider on a melee hit). Computes the punishing-attack bonus
    damage (half fighter level) server-side. v1 announce-only —
    the mark tracking, disadvantage, and punishing attack are
    GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Fighter character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_cavalier(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "cavalier fighter lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _fighter_level_from_sheet(sheet),
        })

    fighter_lv = _fighter_level_from_sheet(sheet)
    punish_bonus = fighter_lv // 2

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🎯 Unwavering Mark — foe marked, +{punish_bonus} "
                f"punish dmg"
            ),
            "feature_desc": (
                f"{char.name} marks the struck foe until the end "
                f"of {char.name}'s next turn: while within 5 ft it "
                f"has disadvantage on attacks not aimed at "
                f"{char.name}, and if it harms an ally, {char.name} "
                f"can make a bonus-action melee attack against it "
                f"with advantage, dealing +{punish_bonus} damage on "
                f"a hit. (Cavalier Fighter Lv 3+ XGE class feature.)"
            ),
            "source": "unwavering-mark",
            "target_attack_disadvantage": True,
            "punish_bonus_damage": punish_bonus,
            "fighter_level": fighter_lv,
        },
    })

    return {
        "ok": True,
        "feature": "unwavering-mark",
        "target_attack_disadvantage": True,
        "punish_bonus_damage": punish_bonus,
        "fighter_level": fighter_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_unwavering_punish")
async def use_unwavering_punish(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.141.0 — Phase 2 of Unwavering Mark (Cavalier Fighter Lv 3+,
    XGE p.13): "if a creature marked by you deals damage to anyone
    other than you, you can make a special melee weapon attack
    against the marked creature as a bonus action on your next turn.
    You have advantage on the attack roll. If it hits, the attack's
    weapon deals extra damage to the target equal to half your
    fighter level."

    Body: ``{character_id, target_combatant_id, attack_index,
    override?}``. Bonus-action gated unless `override`. Subclass
    gated to Cavalier Fighter Lv 3+. v1 simplification: doesn't
    enforce the "marked creature damaged an ally" trigger gate —
    GM/player adjudicates. The attack rolls 2d20kh1 + weapon
    attack_bonus, vs the target's AC. On a hit, rolls weapon damage
    + a flat `fighter_lv // 2` bonus (RAW; the bonus damage type
    matches the weapon's). Broadcasts `weapon_attack` so chat-card
    chrome renders the swing.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    attack_index = int(body.get("attack_index", -1))
    target_combatant_id = (body.get("target_combatant_id") or "").strip() or None
    override = bool(body.get("override"))
    if char_id <= 0 or attack_index < 0 or not target_combatant_id:
        raise HTTPException(
            400, "character_id, attack_index, target_combatant_id required",
        )

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Fighter character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_cavalier(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "cavalier fighter lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _fighter_level_from_sheet(sheet),
        })

    attacks = list(sheet.get("attacks") or [])
    if attack_index >= len(attacks):
        raise HTTPException(404, f"attack_index {attack_index} out of range")
    attack = dict(attacks[attack_index])

    # Bonus action chip gate.
    if not override and _is_slot_used(campaign_id, char.id, "bonus"):
        return JSONResponse(status_code=409, content={
            "error": "bonus_action_already_used",
            "char_name": char.name,
        })

    # Resolve the swing: 2d20kh1 + attack_bonus (advantage forced).
    fighter_lv = _fighter_level_from_sheet(sheet)
    punish_bonus = fighter_lv // 2
    bonus_str = str(attack.get("attack_bonus") or "").strip()
    if bonus_str and not bonus_str.startswith(("+", "-")):
        bonus_str = "+" + bonus_str
    atk_expr = f"2d20kh1{bonus_str}"
    try:
        atk_r = dice_mod.roll(atk_expr)
        attack_total = atk_r.total
        attack_breakdown = atk_r.breakdown
    except dice_mod.DiceParseError:
        attack_total = None
        attack_breakdown = ""

    # Look up target AC.
    target_combatant = _lookup_combatant(campaign_id, target_combatant_id)
    target_ac = (
        _read_target_ac(db, campaign_id, target_combatant)
        if target_combatant else None
    )
    is_crit = False
    if attack_breakdown:
        import re as _re_crit
        _m = _re_crit.search(r"\d*d20[^d=+ ]*=(\d+)", attack_breakdown)
        if _m and int(_m.group(1)) >= 20:
            is_crit = True
    hit = (
        is_crit
        or (attack_total is not None
            and target_ac is not None
            and attack_total >= int(target_ac))
    )

    damage_total = None
    damage_breakdown = ""
    damage_type = str(attack.get("damage_type") or "").strip().lower()
    if hit:
        dmg_expr = str(attack.get("damage") or "").strip()
        if is_crit:
            dmg_expr = _double_dice_for_crit(dmg_expr)
        if dmg_expr:
            try:
                d_r = dice_mod.roll(dmg_expr)
                damage_total = int(d_r.total) + int(punish_bonus)
                damage_breakdown = (
                    f"{d_r.breakdown}  +  Unwavering Punish +{punish_bonus}"
                )
            except dice_mod.DiceParseError:
                damage_total = punish_bonus
                damage_breakdown = f"Unwavering Punish +{punish_bonus}"

    # Mark bonus action used.
    if not override:
        await _mark_battle_economy(campaign_id, char.id, "bonus")

    target_name = (target_combatant or {}).get("name") if target_combatant else ""
    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    payload = {
        "character_id": char.id,
        "character_name": char.name,
        "caster_char_name": char.name,
        "user_color": caster_color,
        "feature_name": (
            f"🎯 Unwavering Punish — +{punish_bonus} bonus dmg vs marked"
        ),
        "feature_desc": (
            f"{char.name} swings back at "
            f"{target_name or 'the marked creature'} with advantage "
            f"+ {punish_bonus} extra damage. "
            f"(Cavalier Fighter Lv 3+ bonus-action punish.)"
        ),
        "source": "unwavering-punish",
        "attack_name": attack.get("name") or "Punish",
        "attack_total": attack_total,
        "attack_breakdown": attack_breakdown,
        "damage_total": damage_total,
        "damage_breakdown": damage_breakdown,
        "damage_type": damage_type,
        "target_combatant_id": target_combatant_id,
        "target_name": target_name,
        "target_ac": target_ac,
        "hit": hit,
        "is_crit": is_crit,
        "punish_bonus_damage": punish_bonus,
        "fighter_level": fighter_lv,
        "roll_state_applied": "advantage_unwavering_punish",
    }
    await hub.broadcast(campaign_id, {"type": "feature_used", "data": payload})

    return {
        "ok": True,
        "feature": "unwavering-punish",
        "attack_total": attack_total,
        "attack_breakdown": attack_breakdown,
        "damage_total": damage_total,
        "damage_breakdown": damage_breakdown,
        "hit": hit,
        "is_crit": is_crit,
        "punish_bonus_damage": punish_bonus,
        "fighter_level": fighter_lv,
        "roll_state_applied": "advantage_unwavering_punish",
    }


@router.post("/api/campaign/{campaign_id}/use_rallying_cry")
async def use_rallying_cry(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.376 — Phase G Fighter martial archetype sweep
    (Banneret / Purple Dragon Knight Lv 3+, SCAG) of the v2.99.193
    phased completion plan — CLOSES the Fighter sweep (Banneret was
    the last untouched archetype). Rallying Cry (Banneret Lv 3+,
    SCAG p.128): "When you use your Second Wind feature, you can
    choose up to three creatures within 60 feet of you that are
    allied with you. Each one regains hit points equal to your
    fighter level, provided that the creature can see or hear
    you."

    Body: ``{character_id}``. No separate action cost (a rider on
    Second Wind, which is itself a bonus action). Computes the
    per-ally heal (fighter level) server-side. v1 announce-only —
    the ally targeting + HP application are GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    target_ids = body.get("target_combatant_ids") or []
    if not isinstance(target_ids, list):
        target_ids = []

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Fighter character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_banneret(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "banneret fighter lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _fighter_level_from_sheet(sheet),
        })

    fighter_lv = _fighter_level_from_sheet(sheet)
    heal_per_ally = fighter_lv

    # v2.99.454 — heal the supplied allies (up to 3) by fighter level
    # via _apply_heal_to_combatant (was announce-only). The "within 60 ft /
    # can see or hear / allied" gate stays GM-tracked — the caller picks
    # the targets. Unknown ids yield a per-result error entry.
    healed = []
    for tid in target_ids[:3]:
        tgt = _lookup_combatant(campaign_id, tid)
        if not tgt:
            healed.append({"combatant_id": tid, "applied": 0,
                           "error": "not_in_battle"})
            continue
        hr = await _apply_heal_to_combatant(
            db, campaign_id, tgt, heal_per_ally)
        healed.append({
            "combatant_id": tid, "name": tgt.get("name") or "",
            "applied": int(hr.get("applied") or 0),
            "revived": bool(hr.get("revived")),
        })

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"📯 Rallying Cry — heal up to 3 allies {heal_per_ally} HP"
            ),
            "feature_desc": (
                f"{char.name} sounds a rallying cry with their "
                f"Second Wind: up to three allies within 60 ft who "
                f"can see or hear {char.name} each regain "
                f"{heal_per_ally} HP (fighter level). (Banneret / "
                f"Purple Dragon Knight Fighter Lv 3+ SCAG class "
                f"feature.)"
            ),
            "source": "rallying-cry",
            "heal_per_ally": heal_per_ally,
            "max_allies": 3,
            "range_ft": 60,
            "fighter_level": fighter_lv,
            "allies_healed": len([h for h in healed if h.get("applied", 0) > 0]),
        },
    })

    return {
        "ok": True,
        "feature": "rallying-cry",
        "heal_per_ally": heal_per_ally,
        "max_allies": 3,
        "range_ft": 60,
        "fighter_level": fighter_lv,
        "healed": healed,
    }


@router.post("/api/campaign/{campaign_id}/use_dread_ambusher")
async def use_dread_ambusher(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.377 — Phase G Ranger conclave subclass batch OPEN
    (Gloom Stalker Lv 3+, XGE) of the v2.99.193 phased completion
    plan. Dread Ambusher (Gloom Stalker Lv 3+, XGE p.42): "You can
    give yourself a bonus to your initiative rolls equal to your
    Wisdom modifier. At the start of your first turn of each
    combat, your walking speed increases by 10 feet, which lasts
    until the end of that turn. If you take the Attack action on
    that turn, you can make one additional weapon attack as part
    of that action. If that attack hits, the target takes an extra
    1d8 damage of the weapon's damage type."

    Body: ``{character_id}``. No separate action cost (the extra
    attack is part of your first-turn Attack action). Computes the
    WIS initiative bonus + rolls the 1d8 ambush damage
    server-side. v1 announce-only — the initiative bonus, speed
    boost, and extra attack are GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    target_combatant_id = body.get("target_combatant_id") or None
    attack_index = int(body.get("attack_index") or 0)

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Ranger character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_gloom_stalker(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "gloom stalker ranger lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _ranger_level_from_sheet(sheet),
        })

    ranger_lv = _ranger_level_from_sheet(sheet)
    try:
        wis_score = int((sheet.get("abilities") or {}).get("WIS", 10))
    except (TypeError, ValueError):
        wis_score = 10
    wis_mod = (wis_score - 10) // 2
    initiative_bonus = wis_mod
    try:
        result = dice_mod.roll("1d8")
        ambush_damage = int(result.total)
        breakdown = result.breakdown
    except dice_mod.DiceParseError:
        ambush_damage = 1
        breakdown = ""

    # v2.99.452 — Phase 2 extra-attack retrofit (mirrors Horde Breaker
    # v2.99.451): when a `target_combatant_id` is supplied, resolve the
    # Dread Ambusher bonus weapon attack server-side + the +1d8 on a hit,
    # once per turn. RAW "first turn of combat only" stays GM-tracked.
    attacked = False
    hit = False
    crit = False
    attack_total = 0
    target_ac = 0
    damage_rolled = 0
    damage_applied = 0
    ambush_bonus = 0
    damage_type = ""
    if target_combatant_id:
        target_combatant = _lookup_combatant(campaign_id, target_combatant_id)
        if not target_combatant:
            raise HTTPException(404, "Target not in battle")
        _state = hub.get_battle(campaign_id)
        _atk_cb = next(
            (c for c in (_state.get("combatants") or [])
             if c.get("char_id") == char.id), None,
        ) if _state else None
        if _atk_cb and bool((_atk_cb.get("economy") or {}).get(
                "dread_ambusher_used")):
            return JSONResponse(status_code=409, content={
                "error": "already_used", "feature": "dread-ambusher",
            })
        attacks = list(sheet.get("attacks") or [])
        if not (0 <= attack_index < len(attacks)):
            raise HTTPException(400, "attack_index out of range")
        weapon = attacks[attack_index] or {}
        try:
            atk_bonus = int(
                str(weapon.get("attack_bonus") or "0").replace("+", "").strip()
                or 0)
        except (TypeError, ValueError):
            atk_bonus = 0
        dmg_expr = str(weapon.get("damage") or "1d4")
        damage_type = str(weapon.get("damage_type") or "")
        target_ac = _read_target_ac(db, campaign_id, target_combatant)
        attacked = True
        atk_roll_expr = f"1d20{atk_bonus:+d}"
        try:
            _ar = dice_mod.roll(atk_roll_expr)
            attack_total, _abd = int(_ar.total), _ar.breakdown
        except dice_mod.DiceParseError:
            attack_total, _abd = 0, ""
        _nat_m = _re.search(r"\[(\d+)\]", _abd)
        nat = int(_nat_m.group(1)) if _nat_m else (attack_total - atk_bonus)
        if nat == 20:
            hit, crit = True, True
        elif nat == 1:
            hit, crit = False, False
        else:
            hit, crit = (attack_total >= target_ac), False
        if hit:
            # Weapon damage + the Dread Ambusher +1d8 (both the weapon's
            # type); dice double on a crit.
            w_expr = _double_dice_for_crit(dmg_expr) if crit else dmg_expr
            a_expr = "2d8" if crit else "1d8"
            try:
                w_dmg = max(0, int(dice_mod.roll(w_expr).total))
            except dice_mod.DiceParseError:
                w_dmg = 0
            try:
                ambush_bonus = max(0, int(dice_mod.roll(a_expr).total))
            except dice_mod.DiceParseError:
                ambush_bonus = 0
            damage_rolled = w_dmg + ambush_bonus
            if damage_rolled > 0:
                _res = await _apply_damage_to_combatant(
                    db, campaign_id, target_combatant, damage_rolled,
                    damage_type, is_crit=crit, is_attack=True,
                    attacker_char_id=char.id,
                )
                damage_applied = int(_res.get("applied") or 0)
        await _mark_attack_flag(campaign_id, char.id, "dread_ambusher")

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🌫️ Dread Ambusher — extra attack +{ambush_damage}, "
                f"init {initiative_bonus:+d}, +10 ft speed"
            ),
            "feature_desc": (
                f"{char.name} strikes from the gloom: +"
                f"{initiative_bonus} to initiative (WIS), +10 ft "
                f"speed on the first turn, and one extra weapon "
                f"attack on a first-turn Attack action that deals "
                f"+{ambush_damage} (1d8) on a hit. (Gloom Stalker "
                f"Ranger Lv 3+ XGE class feature.)"
            ),
            "source": "dread-ambusher",
            "initiative_bonus": initiative_bonus,
            "speed_bonus_ft": 10,
            "ambush_damage": ambush_damage,
            "ambush_damage_die": "1d8",
            "ranger_level": ranger_lv,
            "attacked": attacked,
            "hit": hit,
            "damage_applied": damage_applied,
        },
    })

    return {
        "ok": True,
        "feature": "dread-ambusher",
        "initiative_bonus": initiative_bonus,
        "speed_bonus_ft": 10,
        "ambush_damage": ambush_damage,
        "ambush_damage_die": "1d8",
        "ranger_level": ranger_lv,
        "attacked": attacked,
        "hit": hit,
        "crit": crit,
        "attack_total": attack_total,
        "target_ac": target_ac,
        "damage_rolled": damage_rolled,
        "damage_applied": damage_applied,
        "ambush_bonus": ambush_bonus,
        "damage_type": damage_type,
    }


_COMPANION_COMMANDS = {"attack", "dash", "disengage", "dodge", "help"}


@router.post("/api/campaign/{campaign_id}/use_rangers_companion")
async def use_rangers_companion(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.378 — Phase G Ranger conclave subclass batch ship #2
    (Beast Master Lv 3+, PHB) of the v2.99.193 phased completion
    plan. Ranger's Companion (Beast Master Lv 3+, PHB p.93): you
    gain a beast companion (CR ≤ 1/4, ≤ Medium). Add your
    proficiency bonus to its AC, attack rolls, damage rolls, and
    proficient saves/skills; its HP maximum equals four times your
    ranger level (or its normal max, whichever is higher). It acts
    on your initiative; you can use your action to command it to
    take the Attack, Dash, Disengage, Dodge, or Help action.

    Body: ``{character_id, command?}``. ``command`` is attack
    (default), dash, disengage, dodge, or help. Costs an action
    chip (commanding the companion). Computes the companion HP
    floor (4 × ranger level) + the PB bonus server-side. v1
    announce-only — the companion token + its action resolution
    are GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    command = (body.get("command") or "attack").strip().lower()
    if command not in _COMPANION_COMMANDS:
        raise HTTPException(
            400,
            "command must be attack, dash, disengage, dodge, or help",
        )

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Ranger character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_beast_master(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "beast master ranger lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _ranger_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "rangers-companion",
            "label": "Ranger's Companion",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "action")

    ranger_lv = _ranger_level_from_sheet(sheet)
    pb = int(sheet.get("proficiency_bonus") or 0)
    if pb <= 0:
        pb = 2 + (max(1, ranger_lv) - 1) // 4
    companion_hp_floor = 4 * ranger_lv

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🐾 Ranger's Companion — command {command.title()}"
            ),
            "feature_desc": (
                f"{char.name} commands their beast companion to "
                f"take the {command.title()} action. The companion "
                f"adds +{pb} (proficiency) to its AC, attacks, "
                f"damage, and proficient saves/skills, with an HP "
                f"floor of {companion_hp_floor} (4 × ranger level). "
                f"(Beast Master Ranger Lv 3+ PHB class feature.)"
            ),
            "source": "rangers-companion",
            "command": command,
            "companion_hp_floor": companion_hp_floor,
            "proficiency_bonus": pb,
            "ranger_level": ranger_lv,
        },
    })

    return {
        "ok": True,
        "feature": "rangers-companion",
        "command": command,
        "companion_hp_floor": companion_hp_floor,
        "proficiency_bonus": pb,
        "ranger_level": ranger_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_slayers_prey")
async def use_slayers_prey(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.379 — Phase G Ranger conclave subclass batch ship #3
    (Monster Slayer Lv 3+, XGE) of the v2.99.193 phased completion
    plan. Slayer's Prey (Monster Slayer Lv 3+, XGE p.43): "As a
    bonus action, you designate one creature you can see within 60
    feet of you as the target of this feature. The first time each
    turn that you hit that target with a weapon attack, it takes
    an extra 1d6 damage from you. This benefit lasts until you
    finish a short or long rest. It ends early if you designate a
    different creature."

    Body: ``{character_id, target_combatant_id?, override?}``. Costs a
    bonus chip.

    v2.99.396 — Phase 2.2 of docs/plans/on-hit-riders.md: when a
    ``target_combatant_id`` is supplied, the feature now **installs a
    `slayers-prey` rider buff** keyed to that target
    (`weapon_hit_bonus_dice: 1d6`, `weapon_hit_once_per_turn`), so the
    first weapon hit each turn against the prey auto-applies +1d6 through
    the `/attack` pipeline. Without a target it stays announce-only
    (back-compat). The until-rest duration + re-mark-cancels are
    GM-tracked (the buff drops on rest / re-install).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    target_combatant_id = body.get("target_combatant_id") or None

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Ranger character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_monster_slayer(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "monster slayer ranger lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _ranger_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "slayers-prey",
            "label": "Slayer's Prey",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "bonus")

    ranger_lv = _ranger_level_from_sheet(sheet)
    try:
        result = dice_mod.roll("1d6")
        bonus_damage = int(result.total)
        breakdown = result.breakdown
    except dice_mod.DiceParseError:
        bonus_damage = 1
        breakdown = ""

    # v2.99.396 — Phase 2.2: install the on-hit rider buff keyed to the
    # designated prey so the first weapon hit each turn auto-applies +1d6
    # of the weapon's damage type via _compute_attack_auto_uplifts.
    # Re-installing replaces the prior mark (RAW "ends if you designate a
    # different creature") via _install_buff's same-key refresh.
    buff_installed = False
    if target_combatant_id:
        prey_buff = {
            "key": "slayers-prey",
            "name": "Slayer's Prey",
            "icon": "🎯",
            "duration_rounds": 600,
            "duration_max": 600,
            "concentration": False,
            "source_char_id": char.id,
            "effects": {
                "weapon_hit_bonus_dice": "1d6",
                "weapon_hit_bonus_target_combatant_id": target_combatant_id,
                "weapon_hit_once_per_turn": True,
                "weapon_hit_flag": "slayers_prey",
            },
            "desc": (
                "First weapon hit each turn against the marked prey "
                "deals an extra 1d6 of the weapon's damage type. Lasts "
                "until a short or long rest or until a new prey is marked."
            ),
        }
        buff_installed = await _install_buff(campaign_id, char.id, prey_buff)
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🎯 Slayer's Prey — marked, +{bonus_damage} on first "
                f"hit/turn"
            ),
            "feature_desc": (
                f"{char.name} marks a creature within 60 ft as "
                f"their prey: the first weapon hit each turn deals "
                f"+{bonus_damage} (1d6) damage to it until "
                f"{char.name} finishes a short or long rest or "
                f"marks a new target. (Monster Slayer Ranger Lv 3+ "
                f"XGE class feature.)"
            ),
            "source": "slayers-prey",
            "range_ft": 60,
            "bonus_damage": bonus_damage,
            "bonus_damage_die": "1d6",
            "buff_installed": buff_installed,
            "target_combatant_id": target_combatant_id,
            "ranger_level": ranger_lv,
        },
    })

    return {
        "ok": True,
        "feature": "slayers-prey",
        "range_ft": 60,
        "bonus_damage": bonus_damage,
        "bonus_damage_die": "1d6",
        "buff_installed": buff_installed,
        "target_combatant_id": target_combatant_id,
        "ranger_level": ranger_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_gathered_swarm")
async def use_gathered_swarm(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.380 — Phase G Ranger conclave subclass batch ship #4
    (Swarmkeeper Lv 3+, TCE) of the v2.99.193 phased completion
    plan. Gathered Swarm (Swarmkeeper Lv 3+, TCE p.59): once on
    each of your turns when you hit a creature with an attack, you
    can call on your swarm of nature spirits for one effect — the
    target takes an extra 1d6 force damage; OR the target is moved
    up to 15 ft horizontally; OR you are moved up to 5 ft
    horizontally (without provoking opportunity attacks).

    Body: ``{character_id, mode?}``. ``mode`` is damage (default),
    move_target, or move_self. No separate action cost (a rider on
    a hit). For ``damage`` the 1d6 force is rolled server-side. v1
    announce-only — the on-hit application + forced movement are
    GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    mode = (body.get("mode") or "damage").strip().lower()
    if mode not in ("damage", "move_target", "move_self"):
        raise HTTPException(
            400, "mode must be damage, move_target, or move_self")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Ranger character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_swarmkeeper(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "swarmkeeper ranger lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _ranger_level_from_sheet(sheet),
        })

    ranger_lv = _ranger_level_from_sheet(sheet)
    result_fields = {"mode": mode, "buff_installed": False}
    if mode == "damage":
        try:
            roll = dice_mod.roll("1d6")
            bonus_damage = int(roll.total)
        except dice_mod.DiceParseError:
            bonus_damage = 1
        result_fields["bonus_damage"] = bonus_damage
        result_fields["bonus_damage_die"] = "1d6"
        result_fields["damage_type"] = "force"
        effect_summary = f"the target takes +{bonus_damage} force (1d6)"
        # v2.99.398 — Phase 2.2: the damage mode installs a 1-round (this
        # turn) non-target once-per-turn rider so the next weapon hit
        # auto-applies +1d6 force via _compute_attack_auto_uplifts. RAW
        # is a per-turn choice, so the buff lasts only the current turn
        # (the player re-declares the mode each turn). The move modes are
        # forced movement (Phase 6) and don't install a rider.
        gs_buff = {
            "key": "gathered-swarm",
            "name": "Gathered Swarm",
            "icon": "🦟",
            "duration_rounds": 1,
            "duration_max": 1,
            "concentration": False,
            "source_char_id": char.id,
            "effects": {
                "weapon_hit_bonus_dice": "1d6",
                "weapon_hit_bonus_damage_type": "force",
                "weapon_hit_once_per_turn": True,
                "weapon_hit_flag": "gathered_swarm",
            },
            "desc": (
                "Next weapon hit this turn deals an extra 1d6 force "
                "damage. (Swarmkeeper Lv 3+; once per turn.)"
            ),
        }
        result_fields["buff_installed"] = await _install_buff(
            campaign_id, char.id, gs_buff)
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))
    elif mode == "move_target":
        result_fields["move_distance_ft"] = 15
        result_fields["move_subject"] = "target"
        effect_summary = "the target is moved up to 15 ft horizontally"
    else:  # move_self
        result_fields["move_distance_ft"] = 5
        result_fields["move_subject"] = "self"
        effect_summary = (
            "you are moved up to 5 ft horizontally without "
            "provoking opportunity attacks"
        )

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🦟 Gathered Swarm — {mode.replace('_', ' ')}"
            ),
            "feature_desc": (
                f"{char.name}'s swarm of nature spirits assists "
                f"the strike: {effect_summary}. (Swarmkeeper Ranger "
                f"Lv 3+ TCE class feature; once per turn on a hit.)"
            ),
            "source": "gathered-swarm",
            **result_fields,
            "ranger_level": ranger_lv,
        },
    })

    return {
        "ok": True,
        "feature": "gathered-swarm",
        **result_fields,
        "ranger_level": ranger_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_dreadful_strike")
async def use_dreadful_strike(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.381 — Phase G Ranger conclave subclass batch ship #5
    (Fey Wanderer Lv 3+, TCE) of the v2.99.193 phased completion
    plan. Dreadful Strike (Fey Wanderer Lv 3+, TCE p.60): "When
    you hit a creature with a weapon attack, you can deal an extra
    1d4 psychic damage to that creature, which can take this extra
    damage only once per turn." The die grows to 1d6 at Lv 11.

    Body: ``{character_id}``. No separate action cost (a rider on a
    weapon hit). Rolls the psychic damage server-side (1d4, or 1d6
    at Lv 11+). v1 announce-only — the on-hit application + once-
    per-turn limit are GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Ranger character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_fey_wanderer(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "fey wanderer ranger lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _ranger_level_from_sheet(sheet),
        })

    ranger_lv = _ranger_level_from_sheet(sheet)
    die_size = 6 if ranger_lv >= 11 else 4
    try:
        result = dice_mod.roll(f"1d{die_size}")
        psychic_damage = int(result.total)
        breakdown = result.breakdown
    except dice_mod.DiceParseError:
        psychic_damage = 1
        breakdown = ""

    # v2.99.397 — Phase 2.2: install the on-hit rider buff. Dreadful
    # Strike is NOT target-keyed (it applies to any creature you hit,
    # once per turn), so the buff omits the target field — block 2 of
    # _compute_attack_auto_uplifts treats a target-less rider as
    # applying to any hit. The +1d{die} psychic auto-applies on the
    # first weapon hit each turn. No action cost (an at-will rider).
    ds_buff = {
        "key": "dreadful-strike",
        "name": "Dreadful Strike",
        "icon": "🃏",
        "duration_rounds": 600,
        "duration_max": 600,
        "concentration": False,
        "source_char_id": char.id,
        "effects": {
            "weapon_hit_bonus_dice": f"1d{die_size}",
            "weapon_hit_bonus_damage_type": "psychic",
            "weapon_hit_once_per_turn": True,
            "weapon_hit_flag": "dreadful_strike",
        },
        "desc": (
            f"First weapon hit each turn deals an extra 1d{die_size} "
            f"psychic damage. (Fey Wanderer Lv 3+; at-will.)"
        ),
    }
    buff_installed = await _install_buff(campaign_id, char.id, ds_buff)
    _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🃏 Dreadful Strike — +{psychic_damage} psychic "
                f"(1d{die_size})"
            ),
            "feature_desc": (
                f"{char.name} scars a foe's mind with feywild "
                f"dread: +{psychic_damage} psychic (1d{die_size}) "
                f"on the weapon hit, once per turn. (Fey Wanderer "
                f"Ranger Lv 3+ TCE class feature.)"
            ),
            "source": "dreadful-strike",
            "psychic_damage": psychic_damage,
            "damage_die": f"1d{die_size}",
            "buff_installed": buff_installed,
            "ranger_level": ranger_lv,
        },
    })

    return {
        "ok": True,
        "feature": "dreadful-strike",
        "psychic_damage": psychic_damage,
        "damage_die": f"1d{die_size}",
        "buff_installed": buff_installed,
        "ranger_level": ranger_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_planar_warrior")
async def use_planar_warrior(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.382 — Phase G Ranger conclave subclass batch ship #6
    (Horizon Walker Lv 3+, XGE) of the v2.99.193 phased completion
    plan — CLOSES the Ranger conclave batch (Horizon Walker was
    the last untouched conclave). Planar Warrior (Horizon Walker
    Lv 3+, XGE p.42): "As a bonus action, choose one creature you
    can see within 30 feet of you. The next time you hit that
    creature on this turn with a weapon attack, all damage dealt
    by the attack becomes force damage, and the creature takes an
    extra 1d8 force damage from the attack." The extra damage
    rises to 2d8 at Lv 11.

    Body: ``{character_id, target_combatant_id?, override?}``. Costs a
    bonus chip. Rolls the extra force damage server-side (1d8, or 2d8
    at Lv 11+).

    v2.99.400 — Phase 2.4 of docs/plans/on-hit-riders.md: when a
    ``target_combatant_id`` is supplied, the feature **installs a
    `planar-warrior` rider buff** keyed to that target —
    `weapon_hit_bonus_dice: "{1|2}d8"` + `weapon_hit_bonus_damage_type:
    "force"` (the extra force damage) and `weapon_hit_convert_type:
    "force"` (re-types the whole hit's damage to force), gated
    `weapon_hit_once_per_turn` (next hit this turn only). The buff is
    1-round so it drops at turn advance (RAW "on this turn"). Without a
    target it stays announce-only (back-compat).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    target_combatant_id = body.get("target_combatant_id") or None

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Ranger character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_horizon_walker(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "horizon walker ranger lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _ranger_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "planar-warrior",
            "label": "Planar Warrior",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "bonus")

    ranger_lv = _ranger_level_from_sheet(sheet)
    dice_count = 2 if ranger_lv >= 11 else 1
    try:
        result = dice_mod.roll(f"{dice_count}d8")
        force_damage = int(result.total)
        breakdown = result.breakdown
    except dice_mod.DiceParseError:
        force_damage = dice_count
        breakdown = ""

    # v2.99.400 — Phase 2.4: install the on-hit rider buff keyed to the
    # marked target. The next weapon hit this turn vs it auto-adds the
    # extra {1|2}d8 force (weapon_hit_bonus_dice, re-rolled at /attack
    # time) AND re-types the whole hit's damage to force
    # (weapon_hit_convert_type). Once-per-turn + 1-round duration so it
    # fires exactly once and drops at turn advance (RAW "on this turn").
    # Without a target it stays announce-only (back-compat).
    buff_installed = False
    if target_combatant_id:
        pw_buff = {
            "key": "planar-warrior",
            "name": "Planar Warrior",
            "icon": "🌀",
            "duration_rounds": 1,
            "duration_max": 1,
            "concentration": False,
            "source_char_id": char.id,
            "effects": {
                "weapon_hit_bonus_dice": f"{dice_count}d8",
                "weapon_hit_bonus_damage_type": "force",
                "weapon_hit_bonus_target_combatant_id": target_combatant_id,
                "weapon_hit_convert_type": "force",
                "weapon_hit_once_per_turn": True,
                "weapon_hit_flag": "planar_warrior",
            },
            "desc": (
                f"The next weapon hit this turn vs the marked target "
                f"deals all its damage as force, plus an extra "
                f"{dice_count}d8 force. (Horizon Walker Ranger Lv 3+.)"
            ),
        }
        buff_installed = await _install_buff(campaign_id, char.id, pw_buff)
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🌀 Planar Warrior — all-force + {force_damage} "
                f"({dice_count}d8)"
            ),
            "feature_desc": (
                f"{char.name} marks a creature within 30 ft with "
                f"multiversal energy: the next weapon hit this turn "
                f"deals all its damage as force, plus an extra "
                f"{force_damage} force ({dice_count}d8). (Horizon "
                f"Walker Ranger Lv 3+ XGE class feature.)"
            ),
            "source": "planar-warrior",
            "range_ft": 30,
            "force_damage": force_damage,
            "force_damage_dice": f"{dice_count}d8",
            "converts_to_force": True,
            "ranger_level": ranger_lv,
            "buff_installed": buff_installed,
            "target_combatant_id": target_combatant_id,
        },
    })

    return {
        "ok": True,
        "feature": "planar-warrior",
        "range_ft": 30,
        "force_damage": force_damage,
        "force_damage_dice": f"{dice_count}d8",
        "converts_to_force": True,
        "ranger_level": ranger_lv,
        "buff_installed": buff_installed,
        "target_combatant_id": target_combatant_id,
    }


@router.post("/api/campaign/{campaign_id}/use_watchers_will")
async def use_watchers_will(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.383 — Phase G Paladin oath sweep (Oath of the Watchers
    Lv 3+, TCE) of the v2.99.193 phased completion plan. Watcher's
    Will (Oath of the Watchers Channel Divinity, Lv 3+, TCE p.56):
    "As an action, you can choose a number of creatures you can see
    within 30 feet of you, up to a number equal to your Charisma
    modifier (minimum of one creature). For 1 minute, you and the
    chosen creatures have advantage on Intelligence, Wisdom, and
    Charisma saving throws."

    Body: ``{character_id, override?}``. Costs an action chip
    (Channel Divinity). Computes the number of creatures (CHA mod,
    min 1) server-side. v1 announce-only — the targeting + save
    advantage + Channel Divinity uses are GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Paladin character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_watchers_oath(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "oath of the watchers paladin lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _paladin_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "watchers-will",
            "label": "Watcher's Will",
            "strict": strict,
        })

    # v2.99.392 — Phase 1: spend a Channel Divinity use from the shared
    # pool (Watcher's Will is a Channel Divinity option). Refilled by
    # the generic /rest resource loop. (The save-advantage application
    # stays GM-tracked pending the Phase 4 roll-bonus engine.)
    cd = _consume_channel_divinity(sheet)
    if cd == "no_resource":
        raise HTTPException(404, "No Channel Divinity resource on this sheet")
    if cd == "out_of_uses":
        return JSONResponse(status_code=409, content={
            "error": "out_of_uses",
            "label": "Channel Divinity",
            "char_name": char.name,
            "source": "watchers-will",
        })
    cd_remaining, cd_max = cd
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    await _mark_battle_economy(campaign_id, char.id, "action")
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "channel-divinity",
            "current": cd_remaining,
            "max": cd_max,
        },
    })

    paladin_lv = _paladin_level_from_sheet(sheet)
    try:
        cha_score = int((sheet.get("abilities") or {}).get("CHA", 10))
    except (TypeError, ValueError):
        cha_score = 10
    cha_mod = (cha_score - 10) // 2
    num_creatures = max(1, cha_mod)

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"👁️ Watcher's Will — {num_creatures} allies: adv on "
                f"INT/WIS/CHA saves"
            ),
            "feature_desc": (
                f"{char.name} channels divine vigilance: {char.name} "
                f"and up to {num_creatures} creature"
                f"{'s' if num_creatures != 1 else ''} within 30 ft "
                f"(Charisma modifier) gain advantage on Intelligence, "
                f"Wisdom, and Charisma saving throws for 1 minute. "
                f"(Oath of the Watchers Paladin Lv 3+ TCE Channel "
                f"Divinity.)"
            ),
            "source": "watchers-will",
            "num_creatures": num_creatures,
            "range_ft": 30,
            "advantage_saves": ["int", "wis", "cha"],
            "duration_minutes": 1,
            "cd_remaining": cd_remaining,
            "cd_max": cd_max,
            "paladin_level": paladin_lv,
        },
    })

    return {
        "ok": True,
        "feature": "watchers-will",
        "num_creatures": num_creatures,
        "range_ft": 30,
        "advantage_saves": ["int", "wis", "cha"],
        "duration_minutes": 1,
        "cd_remaining": cd_remaining,
        "cd_max": cd_max,
        "paladin_level": paladin_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_champion_challenge")
async def use_champion_challenge(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.384 — Phase G Paladin oath sweep (Oath of the Crown
    Lv 3+, SCAG) of the v2.99.193 phased completion plan. Champion
    Challenge (Oath of the Crown Channel Divinity, Lv 3+, SCAG
    p.131): "As a bonus action, you issue a challenge that compels
    other creatures to do battle with you. Each creature of your
    choice that you can see within 30 feet of you must make a
    Wisdom saving throw. On a failed save, a creature can't
    willingly move more than 30 feet away from you."

    Body: ``{character_id, target_combatant_ids?, override?}``. Costs a
    bonus chip (Channel Divinity). Computes the Paladin spell save DC
    (8 + PB + CHA mod) server-side.

    v2.99.412 — Phase 3.4 of docs/plans/feature-saves.md: when
    ``target_combatant_ids`` (the creatures within 30 ft the paladin
    challenges) is supplied, each target auto-resolves its WIS save via
    `_resolve_feature_save` (NPC inline / PC prompt) and, on a fail, gets
    a `challenged` condition (can't willingly move >30 ft from the
    paladin; 1 minute). The movement restriction itself stays GM-enforced
    (no positional tether engine yet) — the buff is the marker. Without a
    target list it stays announce-only.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    target_ids = body.get("target_combatant_ids") or []
    if not isinstance(target_ids, list):
        raise HTTPException(400, "target_combatant_ids must be a list")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Paladin character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_crown_oath(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "oath of the crown paladin lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _paladin_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "champion-challenge",
            "label": "Champion Challenge",
            "strict": strict,
        })

    # v2.99.393 — Phase 1: spend a Channel Divinity use from the shared
    # pool. Refilled by the generic /rest resource loop. (The saves +
    # movement restriction stay GM-tracked pending the Phase 3 save
    # resolver.)
    cd = _consume_channel_divinity(sheet)
    if cd == "no_resource":
        raise HTTPException(404, "No Channel Divinity resource on this sheet")
    if cd == "out_of_uses":
        return JSONResponse(status_code=409, content={
            "error": "out_of_uses",
            "label": "Channel Divinity",
            "char_name": char.name,
            "source": "champion-challenge",
        })
    cd_remaining, cd_max = cd
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    await _mark_battle_economy(campaign_id, char.id, "bonus")
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "channel-divinity",
            "current": cd_remaining,
            "max": cd_max,
        },
    })

    paladin_lv = _paladin_level_from_sheet(sheet)
    pb = int(sheet.get("proficiency_bonus") or 0)
    if pb <= 0:
        pb = 2 + (max(1, paladin_lv) - 1) // 4
    try:
        cha_score = int((sheet.get("abilities") or {}).get("CHA", 10))
    except (TypeError, ValueError):
        cha_score = 10
    cha_mod = (cha_score - 10) // 2
    save_dc = 8 + pb + cha_mod

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"👑 Champion Challenge — WIS save DC {save_dc} or "
                f"can't flee"
            ),
            "feature_desc": (
                f"{char.name} issues a challenge to battle: each "
                f"chosen creature within 30 ft makes a WIS save (DC "
                f"{save_dc}); on a failure it can't willingly move "
                f"more than 30 ft away from {char.name}. (Oath of "
                f"the Crown Paladin Lv 3+ SCAG Channel Divinity.)"
            ),
            "source": "champion-challenge",
            "save_dc": save_dc,
            "save": "wis",
            "range_ft": 30,
            "tether_ft": 30,
            "cd_remaining": cd_remaining,
            "cd_max": cd_max,
            "paladin_level": paladin_lv,
        },
    })

    # v2.99.412 — Phase 3.4: resolve each challenged target's WIS save.
    # On a fail → a `challenged` marker buff (1 minute; the >30-ft tether
    # is GM-enforced). No repeated save (RAW: ends on incapacitation /
    # distance, not an end-of-turn re-save).
    challenged_buff = {
        "key": "challenged",
        "name": "Challenged (Champion Challenge)",
        "icon": "👑",
        "duration_rounds": 10,
        "duration_max": 10,
        "concentration": False,
        "source_spell": "Champion Challenge",
        "effects": [
            "can't willingly move more than 30 ft from the paladin",
        ],
    }
    feature_saves: list[dict] = []
    for tcid in target_ids:
        cb = _lookup_combatant(campaign_id, str(tcid).strip())
        if cb is None:
            continue
        sr = await _resolve_feature_save(
            db, campaign_id,
            caster_char_id=char.id, caster_char_name=char.name,
            target_combatant=cb,
            save_ability="WIS", dc=save_dc,
            note_label=f"Champion Challenge save (DC {save_dc})",
            condition_buff=challenged_buff,
            repeated_save=False,
            source="champion-challenge",
            campaign=campaign,
            prompt_user=user,
            feature_name="Champion Challenge",
        )
        feature_saves.append(sr)

    return {
        "ok": True,
        "feature": "champion-challenge",
        "save_dc": save_dc,
        "save": "wis",
        "range_ft": 30,
        "tether_ft": 30,
        "cd_remaining": cd_remaining,
        "cd_max": cd_max,
        "paladin_level": paladin_lv,
        "feature_saves": feature_saves,
    }


@router.post("/api/campaign/{campaign_id}/use_control_undead")
async def use_control_undead(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.385 — Phase G Paladin oath sweep (Oathbreaker Lv 3+,
    DMG) of the v2.99.193 phased completion plan — rounds out the
    Paladin oaths (Oathbreaker was the last untouched oath).
    Control Undead (Oathbreaker Channel Divinity, Lv 3+, DMG
    p.97): "As an action, you target one undead creature you can
    see within 30 feet of you. The target must make a Charisma
    saving throw. On a failed save, the target must obey your
    commands for the next 24 hours ... An undead whose challenge
    rating is equal to or greater than your level is immune to
    this effect."

    Body: ``{character_id, target_combatant_id?, override?}``. Costs an
    action chip (Channel Divinity). Computes the Paladin spell save DC
    (8 + PB + CHA mod) + the max controllable CR (your level − 1)
    server-side.

    v2.99.414 — Phase 3.5 of docs/plans/feature-saves.md (completes
    Phase 3): when a ``target_combatant_id`` is supplied, the CHA save
    auto-resolves via `_resolve_feature_save` (NPC inline / PC prompt)
    and, on a fail, installs a `controlled-undead` marker (24-hour
    control). The "must be undead" + "CR ≥ your level is immune" gates
    stay GM-tracked (no creature-type/CR engine check here). Without a
    target it stays announce-only.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    target_combatant_id = body.get("target_combatant_id") or None

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Paladin character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_oathbreaker(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "oathbreaker paladin lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _paladin_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "control-undead",
            "label": "Control Undead",
            "strict": strict,
        })

    # v2.99.393 — Phase 1: spend a Channel Divinity use from the shared
    # pool. Refilled by the generic /rest resource loop. (The CHA save +
    # 24h control stay GM-tracked pending the Phase 3 save resolver.)
    cd = _consume_channel_divinity(sheet)
    if cd == "no_resource":
        raise HTTPException(404, "No Channel Divinity resource on this sheet")
    if cd == "out_of_uses":
        return JSONResponse(status_code=409, content={
            "error": "out_of_uses",
            "label": "Channel Divinity",
            "char_name": char.name,
            "source": "control-undead",
        })
    cd_remaining, cd_max = cd
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    await _mark_battle_economy(campaign_id, char.id, "action")
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "channel-divinity",
            "current": cd_remaining,
            "max": cd_max,
        },
    })

    paladin_lv = _paladin_level_from_sheet(sheet)
    pb = int(sheet.get("proficiency_bonus") or 0)
    if pb <= 0:
        pb = 2 + (max(1, paladin_lv) - 1) // 4
    try:
        cha_score = int((sheet.get("abilities") or {}).get("CHA", 10))
    except (TypeError, ValueError):
        cha_score = 10
    cha_mod = (cha_score - 10) // 2
    save_dc = 8 + pb + cha_mod
    max_cr = max(0, paladin_lv - 1)

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"💀 Control Undead — CHA save DC {save_dc} (CR ≤ "
                f"{max_cr})"
            ),
            "feature_desc": (
                f"{char.name} bends an undead within 30 ft to their "
                f"will: it makes a CHA save (DC {save_dc}); on a "
                f"failure it obeys {char.name}'s commands for 24 "
                f"hours. Undead with CR ≥ {paladin_lv} (your level) "
                f"are immune. (Oathbreaker Paladin Lv 3+ DMG "
                f"Channel Divinity.)"
            ),
            "source": "control-undead",
            "save_dc": save_dc,
            "save": "cha",
            "range_ft": 30,
            "max_cr": max_cr,
            "duration_hours": 24,
            "cd_remaining": cd_remaining,
            "cd_max": cd_max,
            "paladin_level": paladin_lv,
        },
    })

    # v2.99.414 — Phase 3.5: resolve the target's CHA save. On a fail →
    # a `controlled-undead` marker (24h control; GM drives the obedience).
    # No repeated save (RAW: lasts 24h, no end-of-turn re-save). The
    # "must be undead" + CR-immunity gates stay GM-tracked.
    save_resolved = False
    save_passed = None
    condition_installed = False
    save_prompted = False
    save_prompt_id = 0
    if target_combatant_id:
        target_combatant = _lookup_combatant(campaign_id, target_combatant_id)
        if target_combatant:
            sr = await _resolve_feature_save(
                db, campaign_id,
                caster_char_id=char.id, caster_char_name=char.name,
                target_combatant=target_combatant,
                save_ability="CHA", dc=save_dc,
                note_label=f"Control Undead save (DC {save_dc})",
                condition_buff={
                    "key": "controlled-undead",
                    "name": "Controlled (Control Undead)",
                    "icon": "💀",
                    "duration_rounds": 600,
                    "duration_max": 600,
                    "concentration": False,
                    "source_spell": "Control Undead",
                    "effects": [
                        "obeys the Oathbreaker's commands (24 hours)",
                    ],
                },
                repeated_save=False,
                source="control-undead",
                campaign=campaign,
                prompt_user=user,
                feature_name="Control Undead",
            )
            save_resolved = sr["resolved"]
            save_passed = sr["passed"]
            condition_installed = sr["condition_installed"]
            save_prompted = sr["prompted"]
            save_prompt_id = sr["prompt_id"]

    return {
        "ok": True,
        "feature": "control-undead",
        "save_dc": save_dc,
        "save": "cha",
        "range_ft": 30,
        "max_cr": max_cr,
        "duration_hours": 24,
        "cd_remaining": cd_remaining,
        "cd_max": cd_max,
        "paladin_level": paladin_lv,
        "save_resolved": save_resolved,
        "save_passed": save_passed,
        "condition_installed": condition_installed,
        "save_prompted": save_prompted,
        "save_prompt_id": save_prompt_id,
    }


@router.post("/api/campaign/{campaign_id}/use_combat_inspiration")
async def use_combat_inspiration(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.320 — Phase F.1 Bard subclass batch opener (Valor
    College Bard Lv 3+) of the v2.99.193 phased completion
    plan. Combat Inspiration (Valor College Bard Lv 3+, PHB
    p.55): "A creature that has a Bardic Inspiration die from
    you can roll that die and add it to a weapon damage roll
    OR (as a reaction when attacked) to its AC against that
    attack."

    Body: ``{character_id, mode?, override?}``. Mode:
    "damage" (default) or "ac". No chip cost — this endpoint
    declares the BI die holder's intent to use Combat
    Inspiration. v1 announce-only; actual roll + application
    is GM-tracked via the existing BI flow.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    mode = (body.get("mode") or "damage").strip().lower()
    if mode not in ("damage", "ac"):
        mode = "damage"
    # v2.144.0 — mechanical wiring (Phase 1, damage half): when the
    # caller passes a `target_combatant_id` AND `mode="damage"`, roll
    # the BI die server-side and apply it as bonus damage to the
    # target. Falls back to announce-only when either is absent.
    target_combatant_id = (body.get("target_combatant_id") or "").strip() or None
    damage_type = (body.get("damage_type") or "").strip().lower() or "slashing"

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Bard character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_valor_bard(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "valor bard lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _bard_level_from_sheet(sheet),
        })

    bard_lv = _bard_level_from_sheet(sheet)
    # Die size — same table as Bardic Inspiration.
    if bard_lv >= 15:
        die_size = 12
    elif bard_lv >= 10:
        die_size = 10
    elif bard_lv >= 5:
        die_size = 8
    else:
        die_size = 6

    # v2.144.0 — roll the BI die + apply bonus damage when wired.
    bonus_rolled = None
    bonus_applied = None
    bonus_breakdown = ""
    if mode == "damage" and target_combatant_id:
        try:
            _br = dice_mod.roll(f"1d{die_size}")
            bonus_rolled = max(0, int(_br.total))
            bonus_breakdown = _br.breakdown
        except dice_mod.DiceParseError:
            bonus_rolled = None
        if bonus_rolled and bonus_rolled > 0:
            _target = _lookup_combatant(campaign_id, target_combatant_id)
            if _target is not None:
                _dr = await _apply_damage_to_combatant(
                    db, campaign_id, _target, bonus_rolled, damage_type,
                    is_attack=True, attacker_char_id=char.id,
                )
                bonus_applied = int(_dr.get("applied") or 0)

    # v2.145.0 — Phase 2 AC half: when mode=ac AND the body provides
    # both `attack_total` and `target_ac`, roll the BI die + compute
    # the boosted AC + return whether it converts the hit to a miss.
    # Pure calculation — no state mutation. RAW PHB p.55 lets the
    # holder roll the BI die "after seeing the roll but before
    # knowing whether it hits or misses," so this endpoint serves as
    # the calculator the GM/player uses to reconcile the outcome.
    ac_attack_total = None
    ac_original_ac = None
    ac_new_ac = None
    ac_would_miss = None
    if mode == "ac":
        _at_in = body.get("attack_total")
        _ac_in = body.get("target_ac")
        try:
            ac_attack_total = int(_at_in) if _at_in is not None else None
        except (TypeError, ValueError):
            ac_attack_total = None
        try:
            ac_original_ac = int(_ac_in) if _ac_in is not None else None
        except (TypeError, ValueError):
            ac_original_ac = None
        if ac_attack_total is not None and ac_original_ac is not None:
            try:
                _br = dice_mod.roll(f"1d{die_size}")
                bonus_rolled = max(0, int(_br.total))
                bonus_breakdown = _br.breakdown
            except dice_mod.DiceParseError:
                bonus_rolled = None
            if bonus_rolled is not None:
                ac_new_ac = ac_original_ac + bonus_rolled
                ac_would_miss = ac_attack_total < ac_new_ac

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    if mode == "damage":
        mode_text = "add it to a weapon damage roll"
    else:
        mode_text = "add it to AC vs the triggering attack (reaction)"
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🎺 Combat Inspiration — BI die holder can {mode_text} (1d{die_size})"
            ),
            "feature_desc": (
                f"A creature with a Bardic Inspiration die from "
                f"{char.name} can roll the 1d{die_size} and "
                f"{mode_text}. (Valor College Bard Lv 3+ class "
                f"feature; same BI die.)"
            ),
            "source": "combat-inspiration",
            "mode": mode,
            "die_expression": f"1d{die_size}",
            "die_size": die_size,
            "bard_level": bard_lv,
            "bonus_rolled": bonus_rolled,
            "bonus_applied": bonus_applied,
            "bonus_breakdown": bonus_breakdown,
            "target_combatant_id": target_combatant_id,
            "damage_type": damage_type if bonus_rolled is not None else "",
            "ac_attack_total": ac_attack_total,
            "ac_original_ac": ac_original_ac,
            "ac_new_ac": ac_new_ac,
            "ac_would_miss": ac_would_miss,
        },
    })

    return {
        "ok": True,
        "feature": "combat-inspiration",
        "mode": mode,
        "die_expression": f"1d{die_size}",
        "die_size": die_size,
        "bard_level": bard_lv,
        "bonus_rolled": bonus_rolled,
        "bonus_applied": bonus_applied,
        "bonus_breakdown": bonus_breakdown,
        "target_combatant_id": target_combatant_id,
        "ac_attack_total": ac_attack_total,
        "ac_original_ac": ac_original_ac,
        "ac_new_ac": ac_new_ac,
        "ac_would_miss": ac_would_miss,
    }


@router.post("/api/campaign/{campaign_id}/use_mantle_of_inspiration")
async def use_mantle_of_inspiration(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.321 — Phase F.1 Bard subclass batch (Glamour
    College Bard Lv 3+, XGE) of the v2.99.193 phased completion
    plan. Mantle of Inspiration (Glamour College Bard Lv 3+,
    XGE p.16): "Bonus action: expend a Bardic Inspiration use;
    choose up to CHA-mod (min 1) allies within 60 ft. Each
    gains 5 + bard_level temp HP. Each may use their reaction
    immediately to move up to their speed without provoking
    OAs."

    Body: ``{character_id, override?}``. Costs a bonus chip
    AND expends a BI use. v1 announce-only — actual ally
    temp HP + reaction-move application is GM-tracked. BI
    decrement is performed via the existing resource flow.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Bard character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_glamour_bard(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "glamour bard lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _bard_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "mantle-of-inspiration",
            "label": "Mantle of Inspiration",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "bonus")

    bard_lv = _bard_level_from_sheet(sheet)
    abilities = sheet.get("abilities") or {}
    try:
        cha_mod = (int(abilities.get("CHA") or 10) - 10) // 2
    except (TypeError, ValueError):
        cha_mod = 0
    max_targets = max(1, cha_mod)
    temp_hp = 5 + bard_lv

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"✨ Mantle of Inspiration — {max_targets} allies × {temp_hp} temp HP + free move"
            ),
            "feature_desc": (
                f"{char.name} weaves a song of fey magic. Up to "
                f"{max_targets} allies (within 60 ft, can see "
                f"{char.name}) each gain {temp_hp} temp HP and can "
                f"use their reaction immediately to move up to their "
                f"speed without provoking OAs. (Glamour Bard Lv 3+ "
                f"XGE class feature; consumes 1 BI use.)"
            ),
            "source": "mantle-of-inspiration",
            "max_targets": max_targets,
            "temp_hp_per_target": temp_hp,
            "max_range_ft": 60,
            "free_move_no_oa": True,
            "consumed_bardic_inspiration": True,
            "bard_level": bard_lv,
        },
    })

    return {
        "ok": True,
        "feature": "mantle-of-inspiration",
        "max_targets": max_targets,
        "temp_hp_per_target": temp_hp,
        "max_range_ft": 60,
        "free_move_no_oa": True,
        "consumed_bardic_inspiration": True,
        "bard_level": bard_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_whispers_psychic_blades")
async def use_whispers_psychic_blades(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.322 — Phase F.1 Bard subclass batch (Whispers
    College Bard Lv 3+, XGE) of the v2.99.193 phased completion
    plan. Psychic Blades (Whispers College Bard Lv 3+, XGE
    p.17): "When you hit a creature with a weapon attack, you
    can expend one use of your Bardic Inspiration to deal
    extra psychic damage to that target."

    Endpoint slug is `/use_whispers_psychic_blades` to avoid
    collision with Soulknife Rogue's `/use_psychic_blades`
    (v2.99.311) — both features share the RAW name "Psychic
    Blades" but are different class features.

    Damage by bard level:
    - Lv 3-4: 2d6
    - Lv 5-9: 3d6
    - Lv 10-14: 5d6
    - Lv 15+: 8d6

    Body: ``{character_id, target_combatant_id?, override?}``.
    No chip — this is a damage rider on a successful weapon
    attack. BI decrement via the existing flow. v1
    announce-only.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    target_combatant_id = body.get("target_combatant_id") or None

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Bard character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_whispers_bard(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "whispers bard lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _bard_level_from_sheet(sheet),
        })

    bard_lv = _bard_level_from_sheet(sheet)
    if bard_lv >= 15:
        dice_count = 8
    elif bard_lv >= 10:
        dice_count = 5
    elif bard_lv >= 5:
        dice_count = 3
    else:
        dice_count = 2
    damage_expression = f"{dice_count}d6"

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    target_text = (
        f"combatant {target_combatant_id}"
        if target_combatant_id else "the target"
    )
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🗣️ Psychic Blades — +{damage_expression} psychic to {target_text}"
            ),
            "feature_desc": (
                f"{char.name} channels a BI use into their weapon hit. "
                f"{target_text} takes additional {damage_expression} "
                f"psychic damage. (Whispers College Bard Lv 3+ XGE "
                f"class feature; consumes 1 BI use.)"
            ),
            "source": "whispers-psychic-blades",
            "target_combatant_id": target_combatant_id,
            "damage_expression": damage_expression,
            "damage_type": "psychic",
            "consumed_bardic_inspiration": True,
            "bard_level": bard_lv,
        },
    })

    return {
        "ok": True,
        "feature": "whispers-psychic-blades",
        "target_combatant_id": target_combatant_id,
        "damage_expression": damage_expression,
        "damage_type": "psychic",
        "consumed_bardic_inspiration": True,
        "bard_level": bard_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_blade_flourish")
async def use_blade_flourish(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.323 — Phase F.1 Bard subclass batch (Swords
    College Bard Lv 3+, XGE) of the v2.99.193 phased completion
    plan. Blade Flourish (Swords College Bard Lv 3+, XGE p.16):
    "On your Attack action, walking speed +10 ft until end of
    turn. If a weapon attack hits, expend 1 BI use to apply
    one Flourish: Defensive (+BI to damage + AC until next
    turn), Slashing (+BI bonus dmg to nearby creature), or
    Mobile (+BI bonus dmg + push 5 ft + free reaction-move
    adjacent to target). Once per turn."

    Body: ``{character_id, flourish?, target_combatant_id?,
    override?}``. flourish: "defensive" (default), "slashing",
    or "mobile". No chip — BI decrement via existing flow.
    v1 announce-only — actual BI roll + applied bonus is
    GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    flourish = (body.get("flourish") or "defensive").strip().lower()
    if flourish not in ("defensive", "slashing", "mobile"):
        flourish = "defensive"
    target_combatant_id = (body.get("target_combatant_id") or "").strip() or None
    # v2.146.0 — Phase 1 mechanical wiring (shared damage half): when
    # `target_combatant_id` + `damage_type` are provided, roll the BI
    # die server-side + apply the rolled value as bonus damage to the
    # named target. RAW (XGE p.16) ties the BI bonus to all three
    # flourishes; Slashing's "another creature within 5 ft of the
    # target" is the caller's responsibility — they pass the secondary
    # creature's combatant id. Defensive's AC bonus + Mobile's push are
    # deferred to Phase 2.
    damage_type = (body.get("damage_type") or "").strip().lower() or "slashing"

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Bard character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_swords_bard(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "swords bard lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _bard_level_from_sheet(sheet),
        })

    bard_lv = _bard_level_from_sheet(sheet)
    walking_speed_bonus_ft = 10
    # BI die size — same table as Bardic Inspiration / Combat Inspiration.
    if bard_lv >= 15:
        die_size = 12
    elif bard_lv >= 10:
        die_size = 10
    elif bard_lv >= 5:
        die_size = 8
    else:
        die_size = 6

    # v2.146.0 — roll the BI die + apply bonus damage when wired.
    bonus_rolled = None
    bonus_applied = None
    bonus_breakdown = ""
    if target_combatant_id:
        try:
            _br = dice_mod.roll(f"1d{die_size}")
            bonus_rolled = max(0, int(_br.total))
            bonus_breakdown = _br.breakdown
        except dice_mod.DiceParseError:
            bonus_rolled = None
        if bonus_rolled and bonus_rolled > 0:
            _target = _lookup_combatant(campaign_id, target_combatant_id)
            if _target is not None:
                _dr = await _apply_damage_to_combatant(
                    db, campaign_id, _target, bonus_rolled, damage_type,
                    is_attack=True, attacker_char_id=char.id,
                )
                bonus_applied = int(_dr.get("applied") or 0)

    # v2.158.66 — Phase 2 Defensive Flourish AC self-buff. When the
    # flourish is "defensive" AND a BI die was rolled (meaning the
    # caller passed a target_combatant_id, i.e. the post-hit BI-
    # consumption fired), install a 1-round AC bonus on the bard via
    # the v2.97.39 `effects.ac_bonus` read site in `_read_target_ac`.
    # RAW XGE p.16: "+BI to damage and AC until the start of your
    # next turn." `duration_rounds=1` decrements at the bard's next
    # turn-start so the buff is live exactly for the post-hit window.
    defensive_ac_bonus = 0
    defensive_buff_installed = False
    if flourish == "defensive" and bonus_rolled and bonus_rolled > 0:
        defensive_ac_bonus = int(bonus_rolled)
        _bf_buff = {
            "key": "blade-flourish-defensive-active",
            "name": "Defensive Flourish",
            "icon": "🛡️",
            "duration_rounds": 1,
            "duration_max": 1,
            "concentration": False,
            "effects": {"ac_bonus": defensive_ac_bonus},
            "desc": (
                f"+{defensive_ac_bonus} AC until start of next turn "
                f"(Defensive Flourish, Swords Bard Lv {bard_lv})."
            ),
        }
        defensive_buff_installed = await _install_buff(
            campaign_id, char.id, _bf_buff,
        )

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    flourish_text = {
        "defensive": (
            "Defensive Flourish: +BI to damage and AC until "
            "the start of your next turn."
        ),
        "slashing": (
            "Slashing Flourish: +BI bonus damage to another "
            "creature within 5 ft of the target."
        ),
        "mobile": (
            "Mobile Flourish: +BI bonus damage + push target "
            "5 ft + free reaction-move adjacent to target."
        ),
    }[flourish]
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"⚔️ Blade Flourish — {flourish.title()} + "
                f"+{walking_speed_bonus_ft} ft speed"
            ),
            "feature_desc": (
                f"{char.name} performs a {flourish.title()} Flourish. "
                f"{flourish_text} Walking speed +{walking_speed_bonus_ft} "
                f"ft until end of turn. (Swords College Bard Lv 3+ "
                f"XGE class feature; consumes 1 BI use, once per turn.)"
            ),
            "source": "blade-flourish",
            "flourish": flourish,
            "target_combatant_id": target_combatant_id,
            "walking_speed_bonus_ft": walking_speed_bonus_ft,
            "consumed_bardic_inspiration": True,
            "bard_level": bard_lv,
            "die_expression": f"1d{die_size}",
            "die_size": die_size,
            "bonus_rolled": bonus_rolled,
            "bonus_applied": bonus_applied,
            "bonus_breakdown": bonus_breakdown,
            "damage_type": damage_type if bonus_rolled is not None else "",
            # v2.158.66 — Phase 2 Defensive Flourish AC self-buff fields.
            # Zero/False on non-defensive flourishes or when no BI die
            # rolled (no target_combatant_id provided).
            "defensive_ac_bonus": defensive_ac_bonus,
            "defensive_buff_installed": defensive_buff_installed,
        },
    })

    return {
        "ok": True,
        "feature": "blade-flourish",
        "flourish": flourish,
        "target_combatant_id": target_combatant_id,
        "walking_speed_bonus_ft": walking_speed_bonus_ft,
        "consumed_bardic_inspiration": True,
        "bard_level": bard_lv,
        "die_expression": f"1d{die_size}",
        "die_size": die_size,
        "bonus_rolled": bonus_rolled,
        "bonus_applied": bonus_applied,
        "bonus_breakdown": bonus_breakdown,
        # v2.158.66 — Phase 2 Defensive Flourish AC self-buff response.
        "defensive_ac_bonus": defensive_ac_bonus,
        "defensive_buff_installed": defensive_buff_installed,
    }


@router.post("/api/campaign/{campaign_id}/use_silver_tongue")
async def use_silver_tongue(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.324 — Phase F.1 Bard subclass batch (Eloquence
    College Bard Lv 3+, TCE) of the v2.99.193 phased completion
    plan. Silver Tongue (Eloquence College Bard Lv 3+, TCE
    p.28): "When you make a Charisma (Persuasion) or Charisma
    (Deception) check, you can treat a d20 roll of 9 or lower
    as a 10."

    Body: ``{character_id, override?}``. No chip — passive
    permanent feature.

    v2.158.16 — Phase 8 Bard diversification (first Bard
    subclass feature flipped from announce-only to tracked this
    session — pushes the diversification arc to 7/12 classes).
    Install a permanent `silver-tongue-active` buff carrying the
    parameter flags:
      * `effects.silver_tongue_min_d20: 10`
      * `effects.silver_tongue_skills: ["persuasion", "deception"]`
      * `effects.silver_tongue_ability: "CHA"`
    Phase 2 (shipped v2.158.36): the `/roll` endpoint reads the
    buff via `_pc_silver_tongue_floor_applies` and applies the
    min-10 floor to the kept d20 on Cha Persuasion / Deception
    checks (reusing the Reliable Talent floor mechanic).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Bard character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_eloquence_bard(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "eloquence bard lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _bard_level_from_sheet(sheet),
        })

    bard_lv = _bard_level_from_sheet(sheet)

    # v2.158.16 — install the parameter-flag buff. Permanent
    # passive (idempotent on re-press via key dedupe). Phase 2
    # (shipped v2.158.36): the `/roll` endpoint reads
    # `effects.silver_tongue_*` off the caster's `_buffs_active`
    # and applies the min-10 floor on CHA Persuasion/Deception.
    buff_installed = await _install_buff(campaign_id, char.id, {
        "key": "silver-tongue-active",
        "name": "💬 Silver Tongue",
        "icon": "💬",
        "duration_rounds": 100000,
        "duration_max": 100000,
        "permanent": True,
        "concentration": False,
        "source_char_id": char.id,
        "effects": {
            "silver_tongue_min_d20": 10,
            "silver_tongue_skills": ["persuasion", "deception"],
            "silver_tongue_ability": "CHA",
        },
        "desc": (
            f"{char.name}'s Cha (Persuasion) and Cha (Deception) "
            f"checks treat a d20 roll of 9 or lower as a 10. "
            f"(Eloquence College Bard Lv 3+ passive permanent. "
            f"Phase 2: ability-check resolver reads these flags.)"
        ),
    })
    if buff_installed:
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                "💬 Silver Tongue — Persuasion/Deception d20 ≥ 10"
            ),
            "feature_desc": (
                f"{char.name}'s Cha (Persuasion) and Cha (Deception) "
                f"checks treat a d20 roll of 9 or lower as a 10. "
                f"(Eloquence College Bard Lv 3+ TCE class feature; "
                f"passive permanent.)"
            ),
            "source": "silver-tongue",
            "minimum_d20_value": 10,
            "applies_to": ["persuasion", "deception"],
            "ability": "CHA",
            "bard_level": bard_lv,
            "buff_installed": buff_installed,
        },
    })

    return {
        "ok": True,
        "feature": "silver-tongue",
        "minimum_d20_value": 10,
        "applies_to": ["persuasion", "deception"],
        "ability": "CHA",
        "bard_level": bard_lv,
        "buff_installed": buff_installed,
    }


_SPIRIT_TALES = {
    1: ("Tale of the Clever Animal",
        "Target gains advantage on next ability check or save."),
    2: ("Tale of the Renowned Duelist",
        "Make a melee attack vs target — +your spell save DC."),
    3: ("Tale of the Beloved Friends",
        "Target + creature within 5 ft each gain 2d6 + bard_lv temp HP."),
    4: ("Tale of the Brute",
        "Target makes STR save; fail → 2d10 force damage + prone."),
    5: ("Tale of the Tragic Romance",
        "Target makes WIS save; fail → charmed by Bard for 1 min."),
    6: ("Tale of the Traveler",
        "Target gains 2d6 + bard_lv temp HP + +10 ft walking speed for 10 min."),
}


@router.post("/api/campaign/{campaign_id}/use_tales_from_beyond")
async def use_tales_from_beyond(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.325 — Phase F.1 Bard subclass batch (Spirits
    College Bard Lv 3+, TCE) of the v2.99.193 phased completion
    plan. Tales from Beyond (Spirits College Bard Lv 3+, TCE
    p.30): "Bonus action to roll on the Spirit Tales table.
    Action to choose a creature within 30 ft as the target."

    Body: ``{character_id, override?, force_tale?}``.
    `force_tale` (1-6) is a TEST_MODE escape hatch to
    deterministically pick a tale; otherwise rolls 1d6. Costs
    a bonus chip. v1 announce-only — actual tale effect
    application is GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    force_tale = body.get("force_tale")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Bard character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_spirits_bard(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "spirits bard lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _bard_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "tales-from-beyond",
            "label": "Tales from Beyond",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "bonus")

    _test_mode = (
        os.environ.get("TEST_MODE", "").strip().lower()
        in ("1", "true", "yes", "on")
    )
    tale_roll = None
    if force_tale is not None and _test_mode:
        try:
            tale_roll = max(1, min(6, int(force_tale)))
        except (TypeError, ValueError):
            tale_roll = None
    if tale_roll is None:
        try:
            tale_roll = max(1, min(6, int(dice_mod.roll("1d6").total)))
        except dice_mod.DiceParseError:
            tale_roll = 1
    tale_name, tale_desc = _SPIRIT_TALES.get(tale_roll, _SPIRIT_TALES[1])
    bard_lv = _bard_level_from_sheet(sheet)

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"👻 Tales from Beyond — {tale_name} (rolled {tale_roll})"
            ),
            "feature_desc": (
                f"{char.name} channels a spirit's tale: {tale_name}. "
                f"{tale_desc} (Spirits College Bard Lv 3+ TCE class "
                f"feature; bonus action to roll, action to apply.)"
            ),
            "source": "tales-from-beyond",
            "tale_roll": tale_roll,
            "tale_name": tale_name,
            "tale_description": tale_desc,
            "bard_level": bard_lv,
        },
    })

    return {
        "ok": True,
        "feature": "tales-from-beyond",
        "tale_roll": tale_roll,
        "tale_name": tale_name,
        "tale_description": tale_desc,
        "bard_level": bard_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_mote_of_potential")
async def use_mote_of_potential(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.326 — Phase F.1 Bard subclass batch (Creation
    College Bard Lv 3+, TCE) of the v2.99.193 phased completion
    plan. CLOSES the F.1 Bard batch (8/8). Mote of Potential
    (Creation College Bard Lv 3+, TCE p.31): "When a creature
    uses a BI die from you, you have the mote attach + trigger
    an effect depending on what the die was used for:
    - Ability check: re-roll BI die and add result to check.
    - Attack roll: BI die in force damage to creature within
      5 ft of target.
    - Saving throw: target gains temp HP = BI roll + CHA mod."

    Body: ``{character_id, mode?, target_combatant_id?,
    override?}``. mode "check" (default), "attack", or "save".
    No chip — passive rider on existing BI use. v1
    announce-only — actual Mote roll + effect application
    GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    mode = (body.get("mode") or "check").strip().lower()
    if mode not in ("check", "attack", "save"):
        mode = "check"
    target_combatant_id = body.get("target_combatant_id") or None

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Bard character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_creation_bard(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "creation bard lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _bard_level_from_sheet(sheet),
        })

    bard_lv = _bard_level_from_sheet(sheet)
    abilities = sheet.get("abilities") or {}
    try:
        cha_mod = (int(abilities.get("CHA") or 10) - 10) // 2
    except (TypeError, ValueError):
        cha_mod = 0
    # Die size — same table as Bardic Inspiration.
    if bard_lv >= 15:
        die_size = 12
    elif bard_lv >= 10:
        die_size = 10
    elif bard_lv >= 5:
        die_size = 8
    else:
        die_size = 6

    mode_effect = {
        "check": (
            f"Mote bursts in sparks — roll an additional 1d{die_size} "
            f"and add to the ability check."
        ),
        "attack": (
            f"Mote releases as projectile — 1d{die_size} force damage "
            f"to a creature within 5 ft of the target."
        ),
        "save": (
            f"Mote becomes a comforting drumbeat — target gains "
            f"1d{die_size} + {cha_mod} temp HP."
        ),
    }[mode]

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🌟 Mote of Potential — {mode} mode ({mode_effect.split('—')[0].strip()})"
            ),
            "feature_desc": (
                f"{char.name}'s BI use triggers a Mote of Potential "
                f"on the recipient. {mode_effect} (Creation College "
                f"Bard Lv 3+ TCE class feature; passive rider on BI.)"
            ),
            "source": "mote-of-potential",
            "mode": mode,
            "target_combatant_id": target_combatant_id,
            "die_expression": f"1d{die_size}",
            "die_size": die_size,
            "cha_mod": cha_mod,
            "bard_level": bard_lv,
        },
    })

    return {
        "ok": True,
        "feature": "mote-of-potential",
        "mode": mode,
        "target_combatant_id": target_combatant_id,
        "die_expression": f"1d{die_size}",
        "die_size": die_size,
        "cha_mod": cha_mod,
        "bard_level": bard_lv,
    }


@router.post("/api/campaign/{campaign_id}/use_arcane_ward")
async def use_arcane_ward(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.327 — Phase G.1 Wizard subclass batch opener
    (Abjuration School Wizard Lv 2+) of the v2.99.193 phased
    completion plan. Arcane Ward (Abjuration Wizard Lv 2+,
    PHB p.115): "When you cast an abjuration spell of 1st
    level or higher, you can simultaneously create a magical
    ward on yourself that lasts until you finish a long rest.
    Ward HP = 2 × wizard_level + INT mod. Whenever you take
    damage, the ward absorbs first. The ward regains 2 × spell
    level HP when you cast an abjuration spell of 1st level or
    higher. Once created, you can't create it again until
    you finish a long rest."

    Body: ``{character_id, override?}``. No chip — the ward
    creation rides on an abjuration cast. Auto-bootstraps an
    `arcane-ward-hp` resource (max=2*wiz_lv + INT mod,
    current=max, reset=long). v1 announce-only — actual
    damage-absorption hook is GM-tracked (the ward HP pool is
    tracked as a resource).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Wizard character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_abjuration_wizard(sheet, 2):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "abjuration wizard lv 2+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _wizard_level_from_sheet(sheet),
        })

    wizard_lv = _wizard_level_from_sheet(sheet)
    abilities = sheet.get("abilities") or {}
    try:
        int_mod = (int(abilities.get("INT") or 10) - 10) // 2
    except (TypeError, ValueError):
        int_mod = 0
    ward_max_hp = 2 * wizard_lv + int_mod

    resources = list(sheet.get("resources") or [])
    aw_row = None
    aw_idx = -1
    for i, r in enumerate(resources):
        if not isinstance(r, dict):
            continue
        if (r.get("key") or "").strip().lower() == "arcane-ward-hp":
            aw_row = dict(r); aw_idx = i; break
    if aw_row is None:
        aw_row = {
            "key": "arcane-ward-hp",
            "label": "Arcane Ward HP",
            "current": ward_max_hp, "max": ward_max_hp, "reset": "long",
        }
        aw_idx = len(resources)
        resources.append(aw_row)
    else:
        # Refresh max in case wizard_lv / INT changed.
        aw_row["max"] = ward_max_hp
        # Setting current = max represents fresh ward casting.
        aw_row["current"] = ward_max_hp

    sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "arcane-ward-hp",
            "current": ward_max_hp, "max": ward_max_hp,
        },
    })
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🛡️ Arcane Ward — {ward_max_hp} HP barrier "
                f"(2 × wizard_lv + INT mod)"
            ),
            "feature_desc": (
                f"{char.name} weaves abjuration magic into a "
                f"{ward_max_hp} HP magical ward that absorbs "
                f"damage. Refills 2 × spell-level HP per "
                f"abjuration cast of 1st+ level. Lasts until "
                f"long rest. (Abjuration Wizard Lv 2+ class "
                f"feature.)"
            ),
            "source": "arcane-ward",
            "ward_hp_max": ward_max_hp,
            "wizard_level": wizard_lv,
            "int_mod": int_mod,
        },
    })

    return {
        "ok": True,
        "feature": "arcane-ward",
        "ward_hp_max": ward_max_hp,
        "wizard_level": wizard_lv,
        "int_mod": int_mod,
    }


_THIRD_EYE_SENSES = {
    "darkvision": (
        "Darkvision out to 60 ft."
    ),
    "ethereal-sight": (
        "Ethereal Sight 60 ft — see into Ethereal Plane."
    ),
    "greater-comprehension": (
        "Greater Comprehension — read any written language."
    ),
    "see-invisibility": (
        "See Invisibility 10 ft — see invisible creatures."
    ),
}


@router.post("/api/campaign/{campaign_id}/use_third_eye")
async def use_third_eye(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.328 — Phase G.1 Wizard subclass batch (Divination
    School Wizard Lv 10+) of the v2.99.193 phased completion
    plan. The Third Eye (Divination Wizard Lv 10+, PHB p.116):
    "Action to gain one of four magical senses until you
    dismiss it or finish a short or long rest: Darkvision (60
    ft), Ethereal Sight (60 ft), Greater Comprehension (read
    any written language), See Invisibility (10 ft)."

    Pivoted to Third Eye after discovering Portent (the Lv 2
    feature) is already wired in v2.99.219 with a different
    body shape (uses roll_id to consume a banked die).

    Body: ``{character_id, sense?, override?}``. sense one of
    "darkvision" (default), "ethereal-sight",
    "greater-comprehension", or "see-invisibility". Costs an
    action chip. v1 announce-only — sense application is
    GM-tracked.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    sense = (body.get("sense") or "darkvision").strip().lower()
    if sense not in _THIRD_EYE_SENSES:
        sense = "darkvision"

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Wizard character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_divination_wizard_lv(sheet, 10):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "divination wizard lv 10+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _wizard_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "third-eye",
            "label": "The Third Eye",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "action")

    wizard_lv = _wizard_level_from_sheet(sheet)
    sense_desc = _THIRD_EYE_SENSES[sense]

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"👁️ The Third Eye — {sense.replace('-', ' ').title()}"
            ),
            "feature_desc": (
                f"{char.name} opens their third eye and gains "
                f"{sense_desc} Lasts until dismissed or until "
                f"{char.name} finishes a short or long rest. "
                f"(Divination Wizard Lv 10+ class feature.)"
            ),
            "source": "third-eye",
            "sense": sense,
            "sense_description": sense_desc,
            "wizard_level": wizard_lv,
        },
    })

    return {
        "ok": True,
        "feature": "third-eye",
        "sense": sense,
        "sense_description": sense_desc,
        "wizard_level": wizard_lv,
    }


