@router.post("/api/campaign/{campaign_id}/use_hypnotic_gaze")
async def use_hypnotic_gaze(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.330 — Phase G.1 Wizard subclass batch (Enchantment
    School Wizard Lv 2+) of the v2.99.193 phased completion
    plan. Hypnotic Gaze (Enchantment Wizard Lv 2+, PHB p.117):
    "Action: choose one creature within 5 ft. WIS save DC 8 +
    prof + INT mod; on fail, target charmed + incapacitated +
    speed 0 until end of next turn. Subsequent turns: action
    to extend. Ends on damage, you move >5 ft away, or target
    loses sight/hearing. Once a target succeeds, no re-use
    until long rest."

    Body: ``{character_id, target_combatant_id?, override?}``.
    Costs an action chip.

    v2.99.413 — Phase 3.5 of docs/plans/feature-saves.md: when a
    ``target_combatant_id`` is supplied, the WIS save auto-resolves via
    `_resolve_feature_save` (NPC inline / PC prompt) and, on a fail,
    installs a `charmed` condition (Hypnotic Gaze) until the end of the
    caster's next turn. The incapacitated + speed-0 riders are carried as
    descriptive effects (GM-enforced) and there's no repeated save (the
    gaze is sustained by re-using the action, not shrugged off). Without
    a target it stays announce-only.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    override = bool(body.get("override"))
    target_combatant_id = body.get("target_combatant_id") or None

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Wizard character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_enchantment_wizard(sheet, 2):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "enchantment wizard lv 2+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _wizard_level_from_sheet(sheet),
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "hypnotic-gaze",
            "label": "Hypnotic Gaze",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "action")

    wizard_lv = _wizard_level_from_sheet(sheet)
    prof = int(sheet.get("proficiency_bonus") or 2)
    abilities = sheet.get("abilities") or {}
    try:
        int_mod = (int(abilities.get("INT") or 10) - 10) // 2
    except (TypeError, ValueError):
        int_mod = 0
    save_dc = 8 + prof + int_mod

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    target_text = (
        f"combatant {target_combatant_id}"
        if target_combatant_id else "the target within 5 ft"
    )
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"😵 Hypnotic Gaze — WIS save DC {save_dc} or charmed+0-speed"
            ),
            "feature_desc": (
                f"{char.name} locks gaze on {target_text}. WIS save "
                f"DC {save_dc}; on fail, charmed + incapacitated + "
                f"speed 0 until end of {char.name}'s next turn. Use "
                f"action on subsequent turns to extend. Ends if "
                f"{char.name} moves >5 ft away, target loses "
                f"sight/hearing, or target takes damage. (Enchantment "
                f"Wizard Lv 2+ class feature; once per target per "
                f"long rest.)"
            ),
            "source": "hypnotic-gaze",
            "target_combatant_id": target_combatant_id,
            "save_ability": "WIS",
            "save_dc": save_dc,
            "range_ft": 5,
            "wizard_level": wizard_lv,
        },
    })

    # v2.99.413 — Phase 3.5: resolve the single target's WIS save. On a
    # fail → Charmed (Hypnotic Gaze) until end of the caster's next turn
    # (≈ 2 rounds; the incapacitated + speed-0 riders ride as descriptive
    # effects, GM-enforced). No repeated save (sustained, not shrugged).
    save_resolved = False
    save_passed = None
    condition_installed = False
    save_prompted = False
    save_prompt_id = 0
    if target_combatant_id:
        target_combatant = _lookup_combatant(campaign_id, target_combatant_id)
        if target_combatant:
            sr = await _resolve_feature_save(
                db, campaign_id,
                caster_char_id=char.id, caster_char_name=char.name,
                target_combatant=target_combatant,
                save_ability="WIS", dc=save_dc,
                note_label=f"Hypnotic Gaze save (DC {save_dc})",
                condition_buff={
                    "key": "charmed",
                    "name": "Charmed (Hypnotic Gaze)",
                    "icon": "😵",
                    "duration_rounds": 2,
                    "duration_max": 2,
                    "concentration": False,
                    "source_spell": "Hypnotic Gaze",
                    "effects": [
                        "charmed by the gazer",
                        "incapacitated",
                        "speed 0",
                    ],
                },
                repeated_save=False,
                source="hypnotic-gaze",
                campaign=campaign,
                prompt_user=user,
                feature_name="Hypnotic Gaze",
            )
            save_resolved = sr["resolved"]
            save_passed = sr["passed"]
            condition_installed = sr["condition_installed"]
            save_prompted = sr["prompted"]
            save_prompt_id = sr["prompt_id"]

    return {
        "ok": True,
        "feature": "hypnotic-gaze",
        "target_combatant_id": target_combatant_id,
        "save_ability": "WIS",
        "save_dc": save_dc,
        "range_ft": 5,
        "wizard_level": wizard_lv,
        "save_resolved": save_resolved,
        "save_passed": save_passed,
        "condition_installed": condition_installed,
        "save_prompted": save_prompted,
        "save_prompt_id": save_prompt_id,
    }


