@router.post("/api/campaign/{campaign_id}/use_rebuke_the_violent")
async def use_rebuke_the_violent(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.249 — Phase H.2 fifth + FINAL non-Devotion Paladin
    oath of the v2.99.193 phased completion plan. Rebuke the
    Violent (Redemption Paladin Lv 3+, XGE p.39): "When an
    attacker within 30 feet of you damages a creature other
    than you with an attack, you can use your reaction to force
    the attacker to make a Wisdom saving throw. On a failed
    save, the attacker takes psychic damage equal to the damage
    they just dealt to the target. On a successful save, they
    take half as much damage."

    Body: ``{character_id, attacker_combatant_id, damage_dealt,
    override?}``.

    Validates Redemption Paladin Lv 3+ + `sheet.resources` has
    a `channel-divinity` entry with `current >= 1` + attacker
    in active battle + Phase 4 reaction chip. Decrements CD
    counter, marks chip, computes spell save DC, broadcasts
    the save + damage announce. v1 ships announce-only — the
    GM rolls the attacker's Wis save + applies the psychic
    damage.

    With this commit, Phase H.2 (5 non-Devotion Paladin oaths)
    is substantially complete.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    attacker_combatant_id = (str(body.get("attacker_combatant_id") or "")).strip()
    damage_dealt_raw = body.get("damage_dealt")
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if not attacker_combatant_id:
        raise HTTPException(400, "attacker_combatant_id is required")
    if damage_dealt_raw is None:
        raise HTTPException(400, "damage_dealt is required")
    try:
        damage_dealt = int(damage_dealt_raw)
    except (TypeError, ValueError):
        raise HTTPException(400, "damage_dealt must be an integer")
    if damage_dealt < 1:
        raise HTTPException(400, "damage_dealt must be >= 1")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Paladin character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if not _pc_has_redemption_oath(sheet, 3):
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass_or_level",
            "expected": "redemption paladin lv 3+",
            "got_class": (sheet.get("class") or "").lower(),
            "got_subclass": (sheet.get("subclass") or "").lower(),
            "got_level": _paladin_level_from_sheet(sheet),
        })

    resources = list(sheet.get("resources") or [])
    cd_row = None
    cd_idx = -1
    for i, r in enumerate(resources):
        if (r.get("key") or "").lower() == "channel-divinity":
            cd_row = dict(r)
            cd_idx = i
            break
    if cd_row is None:
        raise HTTPException(
            404,
            "No Channel Divinity resource on this sheet",
        )
    cd_cur = int(cd_row.get("current") or 0)
    cd_max = int(cd_row.get("max") or 0)
    if cd_cur < 1:
        return JSONResponse(status_code=409, content={
            "error": "out_of_uses",
            "label": "Channel Divinity",
        })

    state = hub.get_battle(campaign_id) or {}
    attacker_name = ""
    found = False
    for c in (state.get("combatants") or []):
        if c.get("id") == attacker_combatant_id:
            attacker_name = c.get("name") or ""
            found = True
            break
    if not found:
        return JSONResponse(status_code=404, content={
            "error": "attacker_not_in_battle",
            "attacker_combatant_id": attacker_combatant_id,
        })

    was_used = _is_slot_used(campaign_id, char.id, "reaction")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "reaction",
            "char_name": char.name,
            "source": "rebuke-the-violent",
            "label": "Rebuke the Violent",
            "strict": strict,
        })

    cd_row["current"] = cd_cur - 1
    resources[cd_idx] = cd_row
    sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    prof = int(sheet.get("proficiency_bonus") or 2)
    cha = int((sheet.get("abilities") or {}).get("CHA") or 10)
    cha_mod = (cha - 10) // 2
    save_dc = 8 + prof + cha_mod

    await _mark_battle_economy(campaign_id, char.id, "reaction")
    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": "channel-divinity",
            "current": cd_cur - 1,
            "max": cd_max,
        },
    })

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    half = damage_dealt // 2
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"☮️ Rebuke the Violent — {attacker_name or 'attacker'} "
                f"Wis DC {save_dc} or {damage_dealt} psychic"
            ),
            "feature_desc": (
                f"{char.name} rebukes "
                f"{attacker_name or 'the attacker'}: Wis save "
                f"DC {save_dc} or take {damage_dealt} psychic "
                f"damage ({half} on a success). (Redemption "
                f"Paladin Lv 3+ Channel Divinity.)"
            ),
            "source": "rebuke-the-violent",
            "attacker_combatant_id": attacker_combatant_id,
            "attacker_name": attacker_name,
            "damage_dealt": damage_dealt,
            "psychic_damage_on_fail": damage_dealt,
            "psychic_damage_on_success": half,
            "save_dc": save_dc,
            "uses_remaining": cd_cur - 1,
            "over_budget": was_used,
            "over_budget_slot": "reaction" if was_used else "",
        },
    })

    return {
        "ok": True,
        "feature": "rebuke-the-violent",
        "attacker_combatant_id": attacker_combatant_id,
        "attacker_name": attacker_name,
        "damage_dealt": damage_dealt,
        "psychic_damage_on_fail": damage_dealt,
        "psychic_damage_on_success": half,
        "save_dc": save_dc,
        "uses_remaining": cd_cur - 1,
        "over_budget": was_used,
    }


@router.post("/api/campaign/{campaign_id}/use_invocation")
async def use_invocation(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.250 — Phase H.3 of the v2.99.193 phased completion
    plan: batched 5-invocation breadth ship for the road to
    3.0.0.

    Body: ``{character_id, invocation_slug, override?}`` where
    invocation_slug ∈ keys of `_H3_INVOCATION_REGISTRY`.

    The registry holds 5 RAW PHB+XGE Eldritch Invocations:
    Devil's Sight, Mask of Many Faces, Hex Warrior, Lifedrinker,
    Lance of Lethargy. Each entry carries `name`, `desc`,
    `min_warlock_level`, and optional prereqs (`prereq_pact`,
    `prereq_subclass`, `prereq_spell`).

    Validates Warlock class + invocation_slug in registry +
    warlock level >= min_warlock_level + (if prereq_subclass)
    subclass slug match + (if prereq_pact) pact_boon match.
    Broadcasts feature_used announcing the invocation. v1 ships
    announce-only — each invocation's mechanical wiring (Devil's
    Sight darkness piercing on Perception, Mask of Many Faces
    at-will Disguise Self cast, etc.) is filed as per-invocation
    follow-up commits.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    invocation_slug = (str(body.get("invocation_slug") or "")).strip().lower()
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if not invocation_slug:
        raise HTTPException(400, "invocation_slug is required")
    entry = _H3_INVOCATION_REGISTRY.get(invocation_slug)
    if entry is None:
        raise HTTPException(
            400,
            f"invocation_slug must be one of "
            f"{sorted(_H3_INVOCATION_REGISTRY.keys())}",
        )

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Warlock character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    cls = (sheet.get("class") or "").lower()
    if cls != "warlock":
        has_warlock = any(
            (e.get("class") or "").strip().lower() == "warlock"
            for e in (sheet.get("classes") or [])
        )
        if not has_warlock:
            return JSONResponse(status_code=409, content={
                "error": "wrong_class",
                "expected": "warlock",
                "got": cls,
            })

    warlock_lv = _warlock_level_from_sheet(sheet)
    min_lv = int(entry.get("min_warlock_level") or 1)
    if warlock_lv < min_lv:
        return JSONResponse(status_code=409, content={
            "error": "level_too_low",
            "required": min_lv,
            "got": warlock_lv,
        })

    prereq_subclass = entry.get("prereq_subclass")
    if prereq_subclass:
        subclass = (sheet.get("subclass") or "").strip().lower()
        if prereq_subclass not in subclass:
            return JSONResponse(status_code=409, content={
                "error": "subclass_prereq_unmet",
                "required": prereq_subclass,
                "got": subclass,
            })

    prereq_pact = entry.get("prereq_pact")
    if prereq_pact:
        pact_boon = (sheet.get("pact_boon") or "").strip().lower()
        if prereq_pact not in pact_boon:
            return JSONResponse(status_code=409, content={
                "error": "pact_prereq_unmet",
                "required": prereq_pact,
                "got": pact_boon,
            })

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    name = entry["name"]
    icon = entry.get("icon") or "✨"
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": f"{icon} {name}",
            "feature_desc": (
                f"{char.name} invokes {name}: {entry['desc']} "
                f"(Eldritch Invocation; Warlock Lv {min_lv}+.)"
            ),
            "source": "eldritch-invocation",
            "invocation_slug": invocation_slug,
            "invocation_name": name,
        },
    })

    return {
        "ok": True,
        "feature": "eldritch-invocation",
        "invocation_slug": invocation_slug,
        "invocation_name": name,
        "min_warlock_level": min_lv,
    }


@router.post("/api/campaign/{campaign_id}/select_hunters_prey")
async def select_hunters_prey(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.223 — Phase E.3 of the v2.99.193 phased completion
    plan. Hunter's Prey (Hunter Ranger Lv 3, PHB p.93): pick ONE
    of Colossus Slayer / Giant Killer / Horde Breaker.

    Body: ``{character_id, option}``. option ∈ {colossus-slayer,
    giant-killer, horde-breaker}.

    Validates Hunter Ranger Lv 3+. Persists
    `sheet.hunters_prey = <option>`. Colossus Slayer is already
    wired via `_compute_attack_auto_uplifts` (v2.60.0); Giant
    Killer + Horde Breaker get their own announce endpoints
    (`/use_giant_killer` + `/use_horde_breaker`).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    option = (str(body.get("option") or "")).strip().lower()
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if option not in _HUNTERS_PREY_OPTIONS:
        raise HTTPException(
            400,
            f"option must be one of {sorted(_HUNTERS_PREY_OPTIONS)}",
        )

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Ranger character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    cls = (sheet.get("class") or "").lower()
    if cls != "ranger":
        return JSONResponse(status_code=409, content={
            "error": "wrong_class", "expected": "ranger",
            "got": cls or "",
        })
    if "hunter" not in (sheet.get("subclass") or "").strip().lower():
        return JSONResponse(status_code=409, content={
            "error": "wrong_subclass",
            "expected": "hunter",
            "got": (sheet.get("subclass") or "").strip().lower(),
        })
    if _ranger_level_from_sheet(sheet) < 3:
        return JSONResponse(status_code=409, content={
            "error": "level_too_low", "required": 3,
            "got": _ranger_level_from_sheet(sheet),
        })

    sheet["hunters_prey"] = option
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    pretty = option.replace("-", " ").title()
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": f"🏹 Hunter's Prey — {pretty}",
            "feature_desc": (
                f"{char.name} chose {pretty} as Hunter's Prey."
            ),
            "source": "hunters-prey-pick",
            "option": option,
        },
    })

    return {"ok": True, "option": option}


@router.post("/api/campaign/{campaign_id}/use_giant_killer")
async def use_giant_killer(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.223 — Giant Killer reaction announce. RAW PHB p.93:
    "When a Large or larger creature within 5 feet of you hits
    or misses you with an attack, you can use your reaction to
    attack that creature immediately after its attack."

    Body: ``{character_id, override?}``.

    Validates Hunter Ranger Lv 3+ with `hunters_prey ==
    "giant-killer"` + Phase 4 reaction slot gate. Marks the
    reaction chip + broadcasts feature_used. The actual attack
    is rolled normally via /attack.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Ranger character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    pick = _pc_hunters_prey_pick(sheet)
    if pick != "giant-killer":
        return JSONResponse(status_code=409, content={
            "error": "wrong_hunters_prey",
            "expected": "giant-killer",
            "got": pick,
        })

    was_used = _is_slot_used(campaign_id, char.id, "reaction")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "reaction",
            "char_name": char.name,
            "source": "giant-killer",
            "label": "Giant Killer",
            "strict": strict,
        })

    await _mark_battle_economy(campaign_id, char.id, "reaction")
    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": "🐘 Giant Killer — reaction attack",
            "feature_desc": (
                f"{char.name} used Giant Killer — reaction attack "
                f"on a Large+ creature within 5 ft. Roll the "
                f"attack normally."
            ),
            "source": "giant-killer",
            "over_budget": was_used,
            "over_budget_slot": "reaction" if was_used else "",
        },
    })

    return {"ok": True, "feature": "giant-killer",
            "over_budget": was_used}


@router.post("/api/campaign/{campaign_id}/use_horde_breaker")
async def use_horde_breaker(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.223 — Horde Breaker free-action announce. RAW PHB
    p.93: "Once on each of your turns when you make a weapon
    attack, you can make another attack with the same weapon
    against a different creature that is within 5 feet of the
    original target and within range of your weapon."

    Body: ``{character_id, target_name?, override?}``.

    Validates Hunter Ranger Lv 3+ with `hunters_prey ==
    "horde-breaker"`. No action-economy chip (RAW: the extra
    attack is part of the Attack action, not a separate
    action). Broadcasts feature_used naming the second target.
    Per-turn tracking is filed (one extra attack per turn RAW).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    target_name = (str(body.get("target_name") or "")).strip()[:80]
    target_combatant_id = body.get("target_combatant_id") or None
    attack_index = int(body.get("attack_index") or 0)
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Ranger character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    pick = _pc_hunters_prey_pick(sheet)
    if pick != "horde-breaker":
        return JSONResponse(status_code=409, content={
            "error": "wrong_hunters_prey",
            "expected": "horde-breaker",
            "got": pick,
        })

    # v2.99.451 — Phase 2 extra-attack retrofit: when a `target_combatant_id`
    # is supplied, resolve the Horde Breaker bonus weapon attack
    # server-side (roll vs AC, apply damage on a hit) with a once-per-turn
    # gate. RAW "the second creature is within 5 ft of the original target"
    # stays GM-tracked (the caller picks the secondary target). No
    # action-economy chip (RAW: part of the Attack action).
    attacked = False
    already_used = False
    hit = False
    crit = False
    attack_total = 0
    target_ac = 0
    damage_rolled = 0
    damage_applied = 0
    damage_type = ""
    if target_combatant_id:
        target_combatant = _lookup_combatant(campaign_id, target_combatant_id)
        if not target_combatant:
            raise HTTPException(404, "Target not in battle")
        # Once-per-turn gate via the attacker combatant's economy flag.
        _state = hub.get_battle(campaign_id)
        _atk_cb = next(
            (c for c in (_state.get("combatants") or [])
             if c.get("char_id") == char.id), None,
        ) if _state else None
        if _atk_cb and bool((_atk_cb.get("economy") or {}).get(
                "horde_breaker_used")):
            return JSONResponse(status_code=409, content={
                "error": "already_used",
                "feature": "horde-breaker",
            })
        attacks = list(sheet.get("attacks") or [])
        if not (0 <= attack_index < len(attacks)):
            raise HTTPException(400, "attack_index out of range")
        weapon = attacks[attack_index] or {}
        try:
            atk_bonus = int(
                str(weapon.get("attack_bonus") or "0").replace("+", "").strip()
                or 0)
        except (TypeError, ValueError):
            atk_bonus = 0
        dmg_expr = str(weapon.get("damage") or "1d4")
        damage_type = str(weapon.get("damage_type") or "")
        target_ac = _read_target_ac(db, campaign_id, target_combatant)
        attacked = True
        atk_roll_expr = f"1d20{atk_bonus:+d}"
        try:
            _ar = dice_mod.roll(atk_roll_expr)
            attack_total, _abd = int(_ar.total), _ar.breakdown
        except dice_mod.DiceParseError:
            attack_total, _abd = 0, ""
        _nat_m = _re.search(r"\[(\d+)\]", _abd)
        nat = int(_nat_m.group(1)) if _nat_m else (attack_total - atk_bonus)
        if nat == 20:
            hit, crit = True, True
        elif nat == 1:
            hit, crit = False, False
        else:
            hit, crit = (attack_total >= target_ac), False
        if hit:
            roll_expr = _double_dice_for_crit(dmg_expr) if crit else dmg_expr
            try:
                damage_rolled = max(0, int(dice_mod.roll(roll_expr).total))
            except dice_mod.DiceParseError:
                damage_rolled = 0
            if damage_rolled > 0:
                _res = await _apply_damage_to_combatant(
                    db, campaign_id, target_combatant, damage_rolled,
                    damage_type, is_crit=crit, is_attack=True,
                    attacker_char_id=char.id,
                )
                damage_applied = int(_res.get("applied") or 0)
        await _mark_attack_flag(campaign_id, char.id, "horde_breaker")

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    target_phrase = f" vs {target_name}" if target_name else ""
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🐺 Horde Breaker — extra attack{target_phrase}"
            ),
            "feature_desc": (
                f"{char.name} used Horde Breaker — second weapon "
                f"attack{target_phrase} (within 5 ft of original "
                f"target). Roll the attack normally. Once per turn."
            ),
            "source": "horde-breaker",
            "target_name": target_name,
            "attacked": attacked,
            "hit": hit,
            "damage_applied": damage_applied,
        },
    })

    return {"ok": True, "feature": "horde-breaker",
            "target_name": target_name,
            "attacked": attacked,
            "hit": hit,
            "crit": crit,
            "attack_total": attack_total,
            "target_ac": target_ac,
            "damage_rolled": damage_rolled,
            "damage_applied": damage_applied,
            "damage_type": damage_type}


@router.post("/api/campaign/{campaign_id}/use_primeval_awareness")
async def use_primeval_awareness(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.221 — Phase F.3 final of the v2.99.193 phased
    completion plan. Primeval Awareness (Ranger Lv 3+, PHB
    p.92): spend a Ranger spell slot to sense the 7 creature
    types within 1 mile (6 miles in favored terrain) for 1
    minute per slot level.

    Body: ``{character_id, slot_level, override?}``.

    Validates Ranger Lv 3+ + Ranger slot at `slot_level` >= 1
    available + Phase 4 action slot gate. Atomically decrements
    the slot + marks the action slot + broadcasts feature_used
    naming the 7 creature types + duration. v1 ships as
    announce-only — the GM resolves whether any of the 7
    creature types are within 1 mile (the result is GM
    knowledge; the chat card is the surface).

    No mechanical buff is installed; the duration just rides on
    the chat card description.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    slot_level_raw = body.get("slot_level")
    try:
        slot_level = int(slot_level_raw) if slot_level_raw is not None else 1
    except (TypeError, ValueError):
        slot_level = 1
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if slot_level < 1:
        slot_level = 1

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Ranger character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    cls = (sheet.get("class") or "").lower()
    if cls != "ranger":
        has_ranger = any(
            (entry.get("class") or "").strip().lower() == "ranger"
            for entry in (sheet.get("classes") or [])
        )
        if not has_ranger:
            return JSONResponse(status_code=409, content={
                "error": "wrong_class", "expected": "ranger",
                "got": cls or "",
            })
    ranger_lv = _ranger_level_from_sheet(sheet)
    if ranger_lv < 3:
        return JSONResponse(status_code=409, content={
            "error": "level_too_low", "required": 3, "got": ranger_lv,
        })

    # Ranger slot lookup.
    all_slots = dict(sheet.get("spell_slots") or {})
    per_class = dict(all_slots.get("ranger") or {})
    slot_key = str(slot_level)
    slot = dict(per_class.get(slot_key) or {"total": 0, "used": 0})
    total = int(slot.get("total") or 0)
    used = int(slot.get("used") or 0)
    if total <= 0 or used >= total:
        return JSONResponse(status_code=409, content={
            "error": "no_slot",
            "level": slot_level,
            "class_slug": "ranger",
            "spell_name": "Primeval Awareness",
        })

    # Phase 4 over-budget gate (action slot).
    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "primeval-awareness",
            "label": "Primeval Awareness",
            "strict": strict,
        })

    # Decrement slot.
    slot["used"] = used + 1
    per_class[slot_key] = slot
    all_slots["ranger"] = per_class
    sheet["spell_slots"] = all_slots
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    await _mark_battle_economy(campaign_id, char.id, "action")

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    duration_min = slot_level
    creature_types = [
        "aberrations", "celestials", "dragons", "elementals",
        "fey", "fiends", "undead",
    ]
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": (
                f"🌳 Primeval Awareness ({duration_min} min)"
            ),
            "feature_desc": (
                f"{char.name} senses {', '.join(creature_types)} "
                f"within 1 mile (6 miles in favored terrain) for "
                f"{duration_min} minute(s). GM resolves whether "
                f"any are present."
            ),
            "source": "primeval-awareness",
            "slot_level": slot_level,
            "duration_min": duration_min,
            "creature_types": creature_types,
            "over_budget": was_used,
            "over_budget_slot": "action" if was_used else "",
        },
    })
    await hub.broadcast(campaign_id, {
        "type": "spell_slot_update",
        "data": {
            "character_id": char.id,
            "class_slug": "ranger",
            "level": slot_level,
            "used": used + 1,
            "total": total,
        },
    })

    # v2.99.464 — log the slot spend so the chat-card ↶ Undo refunds it.
    cast_id = _log_spell_slot_spend(
        campaign_id, char.id, "ranger", slot_level, used,
        "Primeval Awareness")
    return {
        "ok": True,
        "cast_id": cast_id,
        "slot_level": slot_level,
        "duration_min": duration_min,
        "creature_types": creature_types,
        "over_budget": was_used,
    }


@router.post("/api/campaign/{campaign_id}/use_hide_in_plain_sight")
async def use_hide_in_plain_sight(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.214 — Phase F.3 start of the v2.99.193 phased
    completion plan. Hide in Plain Sight (Ranger Lv 10+, PHB
    p.92). RAW: "You can spend 1 minute creating camouflage for
    yourself... You gain a +10 bonus to Dexterity (Stealth)
    checks as long as you remain there without moving or taking
    actions. Once you move or take an action or a reaction, you
    must camouflage yourself again to gain this benefit."

    Body: ``{character_id, override?}``.

    Validates Ranger class + level >= 10. Installs a
    `hide-in-plain-sight-active` buff with `effects.stealth_bonus:
    10`. The /roll Stealth hook consumes the buff on the next
    Stealth check (removes the buff + adds +10 to total).

    v1 ignores the "must remain there without moving" gate (would
    require movement tracking + auto-remove). The buff is
    consumed on the next Stealth roll, which is RAW-equivalent
    for the per-check case but doesn't auto-clean when the PC
    moves or takes an action without a Stealth check first.
    Filed.

    No resource cost (RAW: just 1 minute of setup). The action
    slot IS marked per RAW "spend 1 minute creating camouflage"
    being a 1-minute downtime action; the Phase 4 gate applies.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Ranger character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    cls = (sheet.get("class") or "").lower()
    if cls != "ranger":
        has_ranger = any(
            (entry.get("class") or "").strip().lower() == "ranger"
            for entry in (sheet.get("classes") or [])
        )
        if not has_ranger:
            return JSONResponse(status_code=409, content={
                "error": "wrong_class", "expected": "ranger",
                "got": cls or "",
            })
    ranger_lv = _ranger_level_from_sheet(sheet)
    if ranger_lv < 10:
        return JSONResponse(status_code=409, content={
            "error": "level_too_low", "required": 10, "got": ranger_lv,
        })

    # Phase 4 over-budget gate (action slot).
    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "hide-in-plain-sight",
            "label": "Hide in Plain Sight",
            "strict": strict,
        })

    # Install the buff. duration_rounds=10 (1 minute) gives the
    # buff a reasonable lifetime; in practice it's consumed on the
    # next Stealth roll regardless.
    hips_buff = {
        "key": "hide-in-plain-sight-active",
        "name": "Hide in Plain Sight — Camouflaged",
        "icon": "🌿",
        "duration_rounds": 10,
        "duration_max": 10,
        "concentration": False,
        "source": "hide-in-plain-sight",
        "source_char_id": char.id,
        "effects": {
            "stealth_bonus": 10,
            "consume_on_stealth_roll": True,
        },
        "desc": (
            "Camouflaged: +10 on the next Stealth check. RAW: lost "
            "when you move or take an action; v1 consumes on the "
            "next Stealth roll."
        ),
    }
    await _install_buff(campaign_id, char.id, hips_buff)
    _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))
    await _mark_battle_economy(campaign_id, char.id, "action")

    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": "🌿 Hide in Plain Sight — Camouflaged",
            "feature_desc": (
                f"{char.name} created camouflage with naturally "
                f"occurring materials. +10 on the next Stealth "
                f"check (Ranger Lv 10+ class feature)."
            ),
            "source": "hide-in-plain-sight",
            "stealth_bonus": 10,
            "over_budget": was_used,
            "over_budget_slot": "action" if was_used else "",
        },
    })

    return {
        "ok": True,
        "stealth_bonus": 10,
        "buff_installed": True,
        "over_budget": was_used,
    }


@router.post("/api/campaign/{campaign_id}/cast_hunters_mark")
async def cast_hunters_mark(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Cast Hunter's Mark on a target — install the concentration buff
    + decrement a Ranger spell slot + mark the bonus chip.

    Body: ``{character_id, target_character_id?, target_name?, slot_level?, override?}``.

    RAW: Bonus action. Concentration, up to 1 hour. Mark a creature:
    +1d6 weapon damage on hits against it, advantage on Wisdom
    (Perception / Survival) checks to find it. Re-mark a new creature
    as a bonus action when the previous target drops to 0 HP.
    Upcastable: L3 = up to 8 hours; L4+ = up to 24 hours.

    Validates Ranger class (409), Hunter's Mark on the spell list (409),
    Phase 4 over-budget on bonus slot, L1+ Ranger slot available (409
    no_slot). Atomically decrements the Ranger slot + installs the
    Hunter's Mark concentration buff (drops any existing concentration
    buff on the caster — RAW one-at-a-time rule) + marks the bonus chip.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    target_character_id = body.get("target_character_id")
    target_character_id = int(target_character_id) if target_character_id else None
    target_name = (body.get("target_name") or "").strip() or None
    slot_level_raw = body.get("slot_level")
    slot_level = int(slot_level_raw) if slot_level_raw is not None else 1
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if not target_character_id and not target_name:
        raise HTTPException(400, "target_character_id or target_name is required")
    if slot_level < 1:
        slot_level = 1

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Caster not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    primary_class = (sheet.get("class") or "").strip().lower()
    if primary_class != "ranger":
        # Multi-class lookup
        has_ranger = any(
            (entry.get("class") or "").strip().lower() == "ranger"
            for entry in (sheet.get("classes") or [])
        )
        if not has_ranger:
            raise HTTPException(409, "Hunter's Mark requires Ranger level 1+")

    # Verify Hunter's Mark is on the known spell list (defensive — the
    # client UI shouldn't surface it otherwise).
    spells = list(sheet.get("spells") or [])
    has_hm = any(
        (s.get("_slug") == "hunters-mark") or
        (str(s.get("name", "")).lower() == "hunter's mark")
        for s in spells
    )
    if not has_hm:
        raise HTTPException(409, "Hunter's Mark is not on this character's spell list")

    # v2.49.148: range audit — Hunter's Mark is RAW 90 ft (PHB p.251).
    # Fires before slot consumption + buff install.
    _override_range_hm = bool(body.get("override_range"))
    _user_is_gm_for_range_hm = _user_is_gm(user, campaign, db)
    _strict_for_range_hm = bool(campaign.strict_action_economy)
    _range_err_hm = _check_cast_range(
        db, campaign, char,
        "90 feet", "Hunter's Mark",
        None, target_character_id, target_name,
        override_range=_override_range_hm,
        user_is_gm=_user_is_gm_for_range_hm,
        strict=_strict_for_range_hm,
    )
    if _range_err_hm:
        return JSONResponse(status_code=409, content=_range_err_hm)

    # Decrement a Ranger slot.
    all_slots = dict(sheet.get("spell_slots") or {})
    per_class = dict(all_slots.get("ranger") or {})
    slot_key = str(slot_level)
    slot = dict(per_class.get(slot_key) or {"total": 0, "used": 0})
    total = int(slot.get("total") or 0)
    used = int(slot.get("used") or 0)
    if total <= 0 or used >= total:
        return JSONResponse(status_code=409, content={
            "error": "no_slot",
            "level": slot_level,
            "class_slug": "ranger",
            "spell_name": "Hunter's Mark",
        })

    # Phase 4 over-budget gate (bonus slot).
    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "hunters-mark",
            "label": "Hunter's Mark",
            "strict": strict,
        })

    # Commit slot decrement.
    slot["used"] = used + 1
    per_class[slot_key] = slot
    all_slots["ranger"] = per_class
    sheet["spell_slots"] = all_slots
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # v2.97.32 — undo plumbing for /cast_hunters_mark. The dedicated
    # endpoint sits outside /cast_spell's generic v2.92.0 spell_slot_spend
    # path, so we mint a cast_id here and log the slot consume + the
    # buff install under it ourselves. Mirrors the canonical v2.97.20
    # pattern: snapshot caster buffs → install → log buff_install.
    hm_cast_id = uuid.uuid4().hex[:12]
    _log_damage_entry(hm_cast_id, {
        "kind": "spell_slot_spend",
        "campaign_id": campaign_id,
        "character_id": char.id,
        "class_slug": "ranger",
        "slot_level": int(slot_level),
        "used_before": used,
        "spell_name": "Hunter's Mark",
    })

    # Resolve the target.
    target_combatant_id, resolved_name = await _resolve_target_combatant(
        campaign_id,
        target_character_id=target_character_id,
        target_name=target_name,
    )
    display_target = resolved_name or "the target"

    # v2.99.187 — Twinned Spell auto-route. Consume the pending buff
    # EARLY so the second target can be folded into the install-time
    # buff. Closes the v2.99.183 filed item — the rider buff's
    # `effects.weapon_hit_bonus_target_combatant_id` now carries a
    # list when twinned, so the v2.99.187 list-aware consumer matches
    # either target on weapon-hit resolution.
    _twin_target_2_hm = await _consume_twinned_for_second_target(
        campaign_id, int(char.id),
    )

    # Duration scales with slot level: L1-L2 = 1 hour (600 rounds), L3-L4
    # = 8 hours (4800 rounds), L5+ = 24 hours (14400 rounds). For demo
    # purposes we cap displayed duration at 100 rounds so the chip text
    # stays compact; the buff persists until removed or concentration
    # breaks regardless.
    if slot_level >= 5:
        duration_rounds = 100  # display cap
        duration_label = "24h"
    elif slot_level >= 3:
        duration_rounds = 100
        duration_label = "8h"
    else:
        duration_rounds = 100  # display cap; RAW 1 hour = 600 rounds
        duration_label = "1h"

    # v2.99.187 — when Twinned folded in a second target, the rider
    # effect carries a list of both combatant IDs so the consumer
    # at line ~21498 matches either. The top-level
    # `target_combatant_id` stays singular for backward compat with
    # other consumers (broadcast cards, undo replay); a new
    # `target_combatant_ids` list surfaces both for clients that
    # want to highlight both marks.
    _rider_targets = (
        [target_combatant_id, _twin_target_2_hm]
        if _twin_target_2_hm
        else target_combatant_id
    )
    _all_target_ids = (
        [target_combatant_id, _twin_target_2_hm]
        if _twin_target_2_hm
        else [target_combatant_id] if target_combatant_id else []
    )
    _desc_target_phrase = (
        f"{display_target} + a second target"
        if _twin_target_2_hm else display_target
    )
    # Install the concentration buff. Replaces any existing
    # concentration buff on the caster (RAW).
    buff = {
        "key": "hunters-mark",
        "name": "Hunter's Mark",
        "icon": "🎯",
        "source_caster_id": None,  # filled by client from broadcast
        "target_combatant_id": target_combatant_id,
        "target_combatant_ids": _all_target_ids,
        "target_character_id": target_character_id,
        "target_name": resolved_name or target_name,
        "duration_rounds": duration_rounds,
        "duration_max": duration_rounds,
        "duration_label": duration_label,
        "concentration": True,
        "effects": {
            "weapon_hit_bonus_dice": "1d6",
            "weapon_hit_bonus_target_combatant_id": _rider_targets,
            "advantage_on": ["perception_to_find_target", "survival_to_find_target"],
        },
        "desc": (
            f"Concentration ({duration_label}). +1d6 weapon damage on hits "
            f"against {_desc_target_phrase}. Advantage on Perception / Survival "
            f"checks to find it."
        ),
    }
    # v2.97.32 — snapshot the caster's buffs BEFORE install so the
    # buff_install undo entry can restore exactly. Install is best-
    # effort: outside combat _install_buff returns False and we skip
    # the log entry on that path.
    _hm_buffs_before = _snapshot_target_buffs(
        db, campaign_id, {"char_id": char.id},
    )
    _hm_buff_installed = await _install_buff(campaign_id, char.id, buff)
    _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))
    if _hm_buff_installed:
        _log_damage_entry(hm_cast_id, {
            "kind": "buff_install",
            "campaign_id": campaign_id,
            "target_char_id": char.id,
            "buffs_before": _hm_buffs_before,
            "buff_installed_key": "hunters-mark",
        })

    # Mark the bonus slot.
    await _mark_battle_economy(campaign_id, char.id, "bonus")

    # Broadcasts.
    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color

    # v2.99.188 — name both targets in the chat card when Twinned
    # folded in a second target. v2.99.187 installed the per-target
    # rider but the broadcast still surfaced only the primary,
    # which hid the second mark from the chat log.
    _second_target_name = (
        _lookup_combatant_name(campaign_id, _twin_target_2_hm)
        if _twin_target_2_hm else ""
    )
    _display_targets = (
        f"{display_target} + {_second_target_name or 'a second target'}"
        if _twin_target_2_hm else display_target
    )
    _target_names_list = [display_target] + (
        [_second_target_name or "a second target"]
        if _twin_target_2_hm else []
    )
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": f"🎯 Hunter's Mark → {_display_targets}",
            "feature_desc": (
                f"Bonus action. Concentration ({duration_label}). +1d6 weapon "
                f"damage on hits against {_display_targets}. L{slot_level} slot."
            ),
            "source": "hunters-mark",
            "cast_id": hm_cast_id,
            "target_character_id": target_character_id,
            "target_name": resolved_name or target_name,
            "target_names": _target_names_list,
            "twinned_target_combatant_id_2": _twin_target_2_hm or None,
            "twinned_target_name": _second_target_name or None,
            "over_budget": was_used,
            "over_budget_slot": "bonus" if was_used else "",
        },
    })

    await hub.broadcast(campaign_id, {
        "type": "spell_slot_update",
        "data": {
            "character_id": char.id,
            "class_slug": "ranger",
            "level": slot_level,
            "total": total,
            "used": used + 1,
        },
    })

    return {
        "ok": True,
        "cast_id": hm_cast_id,
        "slot_level": slot_level,
        "slot_used": used + 1,
        "slot_total": total,
        "target_combatant_id": target_combatant_id,
        "target_character_id": target_character_id,
        "target_name": resolved_name or target_name,
        "duration_rounds": duration_rounds,
        "duration_label": duration_label,
        # v2.99.183 — Twinned auto-route response field.
        "twinned_target_combatant_id_2": _twin_target_2_hm or None,
    }


# ----------- API: Hex (Warlock L1) — Phase C.2 -----------

@router.post("/api/campaign/{campaign_id}/cast_hex")
async def cast_hex(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Cast Hex on a target — install the concentration buff + decrement
    a Warlock spell slot + mark the bonus chip.

    Body: ``{character_id, target_character_id?, target_name?,
    slot_level?, ability?, override?}``.

    RAW: Bonus action. Concentration, up to 1 hour. Hex a creature:
    +1d6 necrotic damage on weapon / spell hits against it,
    disadvantage on ability checks made with the chosen ability.
    Re-hex a new creature as a bonus action when the previous target
    drops to 0 HP. Upcasts: L3 = up to 8 hours; L5+ = up to 24 hours.

    ``ability`` (one of STR/DEX/CON/INT/WIS/CHA, defaults to STR) is
    the ability the marked target has disadvantage on.

    Validates Warlock class (409), Hex on the spell list (409), Phase 4
    over-budget on bonus slot, Warlock slot available at slot_level
    (default = highest castable = L3 for Lv 5 Warlock). Concentration
    swap rule via ``_install_buff``.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    target_character_id = body.get("target_character_id")
    target_character_id = int(target_character_id) if target_character_id else None
    target_name = (body.get("target_name") or "").strip() or None
    slot_level_raw = body.get("slot_level")
    slot_level = int(slot_level_raw) if slot_level_raw is not None else 1
    ability = (body.get("ability") or "STR").upper()
    override = bool(body.get("override"))
    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if not target_character_id and not target_name:
        raise HTTPException(400, "target_character_id or target_name is required")
    if ability not in ("STR", "DEX", "CON", "INT", "WIS", "CHA"):
        ability = "STR"
    if slot_level < 1:
        slot_level = 1

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Caster not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    primary_class = (sheet.get("class") or "").strip().lower()
    if primary_class != "warlock":
        has_warlock = any(
            (entry.get("class") or "").strip().lower() == "warlock"
            for entry in (sheet.get("classes") or [])
        )
        if not has_warlock:
            raise HTTPException(409, "Hex requires Warlock level 1+")

    # Verify Hex is on the spell list.
    spells = list(sheet.get("spells") or [])
    has_hex = any(
        (s.get("_slug") == "hex") or
        (str(s.get("name", "")).lower() == "hex")
        for s in spells
    )
    if not has_hex:
        raise HTTPException(409, "Hex is not on this character's spell list")

    # v2.49.76 — Phase 2D range-enforcement gate. Hex's RAW range is
    # 90 feet. Fires before slot consumption (same contract as
    # cast_spell's range check).
    _override_range = bool(body.get("override_range"))
    _user_is_gm_for_range = _user_is_gm(user, campaign, db)
    _strict_for_range = bool(campaign.strict_action_economy)
    _range_err = _check_cast_range(
        db, campaign, char,
        "90 feet", "Hex",
        None, target_character_id, target_name,
        override_range=_override_range,
        user_is_gm=_user_is_gm_for_range,
        strict=_strict_for_range,
    )
    if _range_err:
        return JSONResponse(status_code=409, content=_range_err)

    # Find a usable Warlock slot. For Warlock Lv 5 the table only has
    # L3 slots; if the caller asked for L1 we upgrade to whatever's
    # actually available (Pact Magic).
    all_slots = dict(sheet.get("spell_slots") or {})
    per_class = dict(all_slots.get("warlock") or {})
    # Pick the lowest available slot at or above slot_level.
    chosen_level = None
    for k in sorted(per_class.keys(), key=lambda x: int(x)):
        try:
            lv = int(k)
        except ValueError:
            continue
        if lv < slot_level:
            continue
        s = per_class.get(k) or {}
        if int(s.get("used") or 0) < int(s.get("total") or 0):
            chosen_level = lv
            break
    if chosen_level is None:
        return JSONResponse(status_code=409, content={
            "error": "no_slot",
            "level": slot_level,
            "class_slug": "warlock",
            "spell_name": "Hex",
        })
    slot = dict(per_class.get(str(chosen_level)) or {"total": 0, "used": 0})
    total = int(slot.get("total") or 0)
    used = int(slot.get("used") or 0)
    slot_level = chosen_level  # update for downstream

    # Phase 4 over-budget gate (bonus slot).
    was_used = _is_slot_used(campaign_id, char.id, "bonus")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "bonus",
            "char_name": char.name,
            "source": "hex",
            "label": "Hex",
            "strict": strict,
        })

    # Commit slot decrement.
    slot["used"] = used + 1
    per_class[str(slot_level)] = slot
    all_slots["warlock"] = per_class
    sheet["spell_slots"] = all_slots
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # v2.97.32 — undo plumbing for /cast_hex. Mirrors the
    # /cast_hunters_mark wiring shipped in the same commit. Mint a
    # cast_id, log the slot consume + the (best-effort) buff install
    # under it. v2.65.0 buff_install undo branch + v2.92.0 spell_slot
    # refund branch handle the teardown.
    hex_cast_id = uuid.uuid4().hex[:12]
    _log_damage_entry(hex_cast_id, {
        "kind": "spell_slot_spend",
        "campaign_id": campaign_id,
        "character_id": char.id,
        "class_slug": "warlock",
        "slot_level": int(slot_level),
        "used_before": used,
        "spell_name": "Hex",
    })

    # Resolve target.
    target_combatant_id, resolved_name = await _resolve_target_combatant(
        campaign_id,
        target_character_id=target_character_id,
        target_name=target_name,
    )
    display_target = resolved_name or "the target"

    # v2.99.189 — Twinned Spell auto-route. Consume the pending buff
    # EARLY so the second target can be folded into the install-time
    # buff. Mirrors the v2.99.187 Hunter's Mark pattern. The shared
    # weapon-hit rider consumer already accepts list-or-string (the
    # v2.99.187 edit), so this just needs the install + broadcast
    # changes.
    _twin_target_2_hex = await _consume_twinned_for_second_target(
        campaign_id, int(char.id),
    )

    # Duration scales with slot level.
    if slot_level >= 5:
        duration_rounds = 100
        duration_label = "24h"
    elif slot_level >= 3:
        duration_rounds = 100
        duration_label = "8h"
    else:
        duration_rounds = 100
        duration_label = "1h"

    # v2.99.189 — list-shape rider + descriptor when Twinned fired.
    _rider_targets_hex = (
        [target_combatant_id, _twin_target_2_hex]
        if _twin_target_2_hex
        else target_combatant_id
    )
    _all_target_ids_hex = (
        [target_combatant_id, _twin_target_2_hex]
        if _twin_target_2_hex
        else [target_combatant_id] if target_combatant_id else []
    )
    _second_target_name_hex = (
        _lookup_combatant_name(campaign_id, _twin_target_2_hex)
        if _twin_target_2_hex else ""
    )
    _display_targets_hex = (
        f"{display_target} + {_second_target_name_hex or 'a second target'}"
        if _twin_target_2_hex else display_target
    )
    buff = {
        "key": "hex",
        "name": "Hex",
        "icon": "🕷️",
        "source_caster_id": None,
        "target_combatant_id": target_combatant_id,
        "target_combatant_ids": _all_target_ids_hex,
        "target_character_id": target_character_id,
        "target_name": resolved_name or target_name,
        "duration_rounds": duration_rounds,
        "duration_max": duration_rounds,
        "duration_label": duration_label,
        "concentration": True,
        "effects": {
            "weapon_hit_bonus_dice": "1d6",
            "weapon_hit_bonus_damage_type": "necrotic",
            "weapon_hit_bonus_target_combatant_id": _rider_targets_hex,
            "disadvantage_on_ability_check": ability,
        },
        "desc": (
            f"Concentration ({duration_label}). +1d6 necrotic on weapon/spell "
            f"hits against {_display_targets_hex}. Disadvantage on {ability} checks."
        ),
    }
    # v2.97.32 — snapshot before install, log buff_install if it took.
    _hex_buffs_before = _snapshot_target_buffs(
        db, campaign_id, {"char_id": char.id},
    )
    _hex_buff_installed = await _install_buff(campaign_id, char.id, buff)
    _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))
    if _hex_buff_installed:
        _log_damage_entry(hex_cast_id, {
            "kind": "buff_install",
            "campaign_id": campaign_id,
            "target_char_id": char.id,
            "buffs_before": _hex_buffs_before,
            "buff_installed_key": "hex",
        })

    # Mark the bonus slot.
    await _mark_battle_economy(campaign_id, char.id, "bonus")

    # Broadcasts.
    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color

    # v2.99.189 — name both targets in the chat card when Twinned
    # folded in a second target. Mirrors the v2.99.188 Hunter's
    # Mark broadcast extension.
    _target_names_list_hex = [display_target] + (
        [_second_target_name_hex or "a second target"]
        if _twin_target_2_hex else []
    )
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": f"🕷️ Hex ({ability}) → {_display_targets_hex}",
            "feature_desc": (
                f"Bonus action. Concentration ({duration_label}). +1d6 necrotic "
                f"on hits against {_display_targets_hex}. Disadvantage on {ability} "
                f"checks. L{slot_level} slot."
            ),
            "source": "hex",
            "cast_id": hex_cast_id,
            "target_character_id": target_character_id,
            "target_name": resolved_name or target_name,
            "target_names": _target_names_list_hex,
            "twinned_target_combatant_id_2": _twin_target_2_hex or None,
            "twinned_target_name": _second_target_name_hex or None,
            "ability": ability,
            "over_budget": was_used,
            "over_budget_slot": "bonus" if was_used else "",
        },
    })

    await hub.broadcast(campaign_id, {
        "type": "spell_slot_update",
        "data": {
            "character_id": char.id,
            "class_slug": "warlock",
            "level": slot_level,
            "total": total,
            "used": used + 1,
        },
    })

    return {
        "ok": True,
        "cast_id": hex_cast_id,
        "slot_level": slot_level,
        "slot_used": used + 1,
        "slot_total": total,
        "target_combatant_id": target_combatant_id,
        "target_character_id": target_character_id,
        "target_name": resolved_name or target_name,
        "ability": ability,
        "duration_rounds": duration_rounds,
        "duration_label": duration_label,
        # v2.99.183 — Twinned auto-route response field.
        "twinned_target_combatant_id_2": _twin_target_2_hex or None,
    }


# ----------- API: cast Sleep (HP-pool targeting) -----------

# v2.49.64 — RAW Sleep exclusion ("Undead and creatures immune to
# being charmed aren't affected by this spell"). Inspects the
# target combatant's stat block + condition immunities. NPCs route
# through their monster template (slug → SRD JSON via local_content);
# PCs route through their character sheet. Returns ``(is_immune,
# reason)`` where reason is one of ``"undead"`` / ``"charm_immune"``
# / ``"fey-ancestry"`` / ``""``. Undead trumps the others in
# reporting (most undead are also charm-immune; "undead" is the
# more specific cause).
#
# v2.99.15 — (D) Phase 3 first-ship: extends the immunity gate with
# Fey Ancestry (Elf / Half-Elf). RAW Fey Ancestry second sentence
# (PHB p.23): "magic can't put you to sleep." This is a true
# install-time IMMUNITY (not a save advantage like the v2.99.11
# charm-save half of Fey Ancestry), so the Sleep target walker
# silently filters Fey-Ancestry'd creatures into the unaffected
# list — same as undead / charm-immune monsters. Surfaces in the
# `unaffected[].reason` field with `"fey-ancestry"` so the cast
# card can display "Thalindra was immune (Fey Ancestry)".
def _is_sleep_immune(
    combatant: dict, db: Session, campaign_id: int,
) -> tuple[bool, str]:
    def _check_sheet(sheet: dict) -> tuple[bool, str]:
        race = (sheet.get("race") or "").lower()
        if "undead" in race:
            return True, "undead"
        cond_imm = sheet.get("condition_immunities") or []
        if isinstance(cond_imm, str):
            cond_imm = [p.strip() for p in cond_imm.split(",")]
        cond_imm_l = [str(c).lower() for c in cond_imm]
        if any("charm" in c for c in cond_imm_l):
            return True, "charm_immune"
        # v2.99.15 — Fey Ancestry sleep immunity (Elf / Half-Elf).
        # Uses the same slug normalizer as the v2.99.11 save
        # advantage table so subrace variants (Wood / High / Dark
        # Elf) fold to the same gate.
        if _race_slug_from_sheet(sheet) in ("elf", "half-elf"):
            return True, "fey-ancestry"
        return False, ""

    # NPC: resolve via monster template's SRD-overlaid sheet.
    tmpl_id = combatant.get("token_template_id")
    if tmpl_id:
        tmpl = db.query(TokenTemplate).filter(
            TokenTemplate.id == int(tmpl_id),
        ).first()
        if tmpl:
            sheet = _monster_template_to_sheet(tmpl, campaign_id)
            immune, reason = _check_sheet(sheet)
            if immune:
                return True, reason
    # PC: check the character sheet directly.
    char_id = combatant.get("char_id")
    if char_id:
        char = db.query(Character).filter(
            Character.id == int(char_id),
        ).first()
        if char:
            immune, reason = _check_sheet(char.sheet or {})
            if immune:
                return True, reason
    return False, ""


@router.post("/api/campaign/{campaign_id}/cast_sleep")
async def cast_sleep(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Cast Sleep — roll a 5d8-per-slot HP pool and put creatures to
    sleep in ascending order of current HP until the pool is exhausted.

    Body: ``{character_id, class_slug, slot_level, target_combatant_ids,
    override?}``.

    RAW (PHB Sleep, 1st-level Enchantment): 1 action, 90 ft range,
    duration 1 minute, NO save, NO concentration. Roll 5d8 (+2d8 per
    slot level above 1st) — that's the HP pool. Affected: creatures
    within 20 ft of a chosen point, sorted ascending by current HP,
    ignoring unconscious creatures. Walk the list; each affected
    creature falls Unconscious until the spell ends, the sleeper
    takes damage, or another creature uses an action to shake them
    awake. Subtract each affected creature's HP from the pool before
    moving to the next. Undead + creatures immune to charm are
    immune.

    Implementation notes:
      - SimpleVTT doesn't enforce spatial range / radius today, so
        the caller passes the candidate set as ``target_combatant_ids``
        (the future ruler/range work can sweep this from the canvas).
      - "Immune to charm" / "undead" lookups aren't fully modelled —
        v1 skips those exclusions and lets the GM uncheck inappropriate
        targets via the picker. Filed for follow-up.
      - "Asleep until damaged" is handled by the existing damage
        pipeline: damage on an Unconscious combatant doesn't auto-
        wake them in SimpleVTT today (filed). GMs can /end_buff
        ``unconscious`` to wake a sleeper manually.
      - The Unconscious key is in ``_INCAPACITATING_BUFF_KEYS`` so
        the v2.49.51 hook fires and a PC sleeper loses their own
        concentration. Same as Hold Person etc.

    Validation: caster has the named class + Sleep on spell list +
    available slot at the requested level + Phase 4 action gate (over-
    rideable). Pool roll uses the campaign's dice path so seeded test
    runs are deterministic.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    class_slug = (body.get("class_slug") or "").strip().lower()
    slot_level_raw = body.get("slot_level")
    slot_level = int(slot_level_raw) if slot_level_raw is not None else 1
    target_combatant_ids = body.get("target_combatant_ids") or []
    override = bool(body.get("override"))

    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if class_slug not in ("wizard", "bard", "sorcerer", "warlock"):
        raise HTTPException(400, "class_slug must be one of wizard, bard, sorcerer, warlock")
    if slot_level < 1:
        raise HTTPException(400, "slot_level must be >= 1")
    if not isinstance(target_combatant_ids, list) or not target_combatant_ids:
        raise HTTPException(400, "target_combatant_ids must be a non-empty list")

    # v2.49.76 — Phase 2D range-enforcement: /cast_sleep is intentionally
    # SKIPPED from the range check. RAW Sleep's range is 90 ft to the
    # cast point + a 20 ft radius extending from that point; individual
    # targets in the radius can be up to 110 ft from the caster. Today
    # the endpoint receives pre-resolved targets without a cast-point
    # coordinate, so a strict server-side check would either under-enforce
    # (compare to the closest target only) or over-enforce (reject a
    # valid 110-ft target). Same convention as /cast_spell with AoE
    # multi-target lists (see Phase 2C "When NOT to enforce"). A future
    # commit could add a `cast_point: {x, y}` body field + an AoE-aware
    # range check; filed.

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Caster not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})

    # Validate class membership: primary class OR a multiclass entry.
    primary_class = (sheet.get("class") or "").strip().lower()
    if primary_class != class_slug:
        has_class = any(
            (entry.get("class") or "").strip().lower() == class_slug
            for entry in (sheet.get("classes") or [])
        )
        if not has_class:
            return JSONResponse(status_code=409, content={
                "error": "wrong_class",
                "expected": class_slug,
                "got": primary_class or "",
            })

    # Verify Sleep is on the spell list.
    spells = list(sheet.get("spells") or [])
    has_sleep = any(
        (s.get("_slug") == "sleep") or
        (str(s.get("name", "")).lower() == "sleep")
        for s in spells
    )
    if not has_sleep:
        return JSONResponse(status_code=409, content={
            "error": "spell_not_known",
            "spell": "sleep",
        })

    # Find an available slot at the requested level.
    all_slots = dict(sheet.get("spell_slots") or {})
    per_class = dict(all_slots.get(class_slug) or {})
    slot = dict(per_class.get(str(slot_level)) or {"total": 0, "used": 0})
    total = int(slot.get("total") or 0)
    used = int(slot.get("used") or 0)
    if total <= 0 or used >= total:
        return JSONResponse(status_code=409, content={
            "error": "no_slot",
            "level": slot_level,
            "class_slug": class_slug,
            "spell_name": "Sleep",
        })

    # Phase 4 over-budget gate (action slot).
    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "sleep",
            "label": "Sleep",
            "strict": strict,
        })

    # Commit slot decrement.
    slot["used"] = used + 1
    per_class[str(slot_level)] = slot
    all_slots[class_slug] = per_class
    sheet["spell_slots"] = all_slots
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # v2.99.184 — Twinned Spell auto-route. RAW: Sleep targets an
    # HP-pool sphere, not a single creature — Twinned doesn't
    # apply RAW. Wired for consistency with the helper-pattern;
    # GM is responsible for declining Twinned on AoE spells.
    _twin_target_2_sleep = await _consume_twinned_for_second_target(
        campaign_id, int(char.id),
    )
    if _twin_target_2_sleep and _twin_target_2_sleep not in target_combatant_ids:
        target_combatant_ids = list(target_combatant_ids) + [_twin_target_2_sleep]

    # Roll the HP pool: 5d8 + 2d8 per slot level above 1st. v2.128.0 —
    # shared helper (was inlined as `5 + max(0, slot_level - 1) * 2`).
    from ..content.spell_upcast_parse import upcast_pool_dice
    pool_dice = upcast_pool_dice(
        slot_level, base_level=1, base_dice=5, per_slot_dice=2)
    pool_expr = f"{pool_dice}d8"
    try:
        pool_roll = dice_mod.roll(pool_expr)
        pool_total = int(pool_roll.total)
        pool_breakdown = pool_roll.breakdown
    except dice_mod.DiceParseError:
        pool_total = 0
        pool_breakdown = pool_expr

    # Resolve targets + capture current HP. Skip already-unconscious
    # combatants (RAW: ignored when ordering). Surface RAW-immune
    # creatures (undead / charm-immune) in the `unaffected` list with
    # a `reason` so the cast card can show "X was immune".
    resolved_targets: list[dict] = []
    immune_unaffected: list[dict] = []
    for tid in target_combatant_ids:
        if not isinstance(tid, str) or not tid:
            continue
        c = _lookup_combatant(campaign_id, tid)
        if not c:
            continue
        hp_cur = int(c.get("hp_current") or 0)
        # RAW: 0 HP creatures are already unconscious / dead — skip.
        if hp_cur <= 0:
            continue
        already_unc = any(
            (b or {}).get("key") in ("unconscious", "asleep")
            for b in (c.get("buffs") or [])
        )
        if already_unc:
            continue
        # v2.49.64: RAW Sleep — "Undead and creatures immune to being
        # charmed aren't affected by this spell." Surfaced in
        # ``unaffected`` with a reason so the cast card can display
        # the exclusion to the caster rather than silently filtering.
        immune, immune_reason = _is_sleep_immune(c, db, campaign_id)
        if immune:
            immune_unaffected.append({
                "combatant_id": tid,
                "name": c.get("name") or "",
                "hp": hp_cur,
                "reason": immune_reason,
            })
            continue
        resolved_targets.append({
            "combatant_id": tid,
            "name": c.get("name") or "",
            "hp_current": hp_cur,
            "char_id": c.get("char_id"),
            "token_template_id": c.get("token_template_id"),
        })

    # Sort by ascending current HP; walk down the list.
    resolved_targets.sort(key=lambda t: t["hp_current"])

    affected: list[dict] = []
    unaffected: list[dict] = list(immune_unaffected)
    pool_remaining = pool_total
    sleep_duration_rounds = 10  # 1 min = 10 rounds at 6 s/round
    for t in resolved_targets:
        if t["hp_current"] <= pool_remaining:
            pool_remaining -= t["hp_current"]
            buff = {
                "key": "unconscious",
                "name": "Unconscious (Sleep)",
                "icon": "💤",
                "source_char_id": char.id,
                "source_char_name": char.name,
                "source_spell": "Sleep",
                "duration_rounds": sleep_duration_rounds,
                "duration_max": sleep_duration_rounds,
                "concentration": False,
                # v2.99.0 — generic marker for "wake on damage" + the
                # /wake_sleeper + /shake_awake action endpoints. Future
                # content that imposes a wakeable unconscious / asleep
                # state can opt in by stamping this field.
                "wakeable_by_action": True,
                "effects": [
                    "incapacitated — no actions or reactions",
                    "drops what it's holding + falls prone",
                    "auto-fail STR / DEX saves",
                    "attacks vs target have advantage; hits within 5 ft auto-crit",
                    "wakes on damage or when shaken (action) — GM /end_buff to wake",
                ],
            }
            installed = False
            if t["char_id"]:
                installed = await _install_buff(
                    campaign_id, int(t["char_id"]), buff,
                )
                if installed:
                    _mirror_buffs_to_sheet(
                        db, int(t["char_id"]),
                        _get_buffs(campaign_id, int(t["char_id"])),
                    )
            else:
                installed = await _install_buff_on_combatant_id(
                    campaign_id, t["combatant_id"], buff,
                )
            affected.append({
                "combatant_id": t["combatant_id"],
                "name": t["name"],
                "hp": t["hp_current"],
                "installed": installed,
            })
        else:
            unaffected.append({
                "combatant_id": t["combatant_id"],
                "name": t["name"],
                "hp": t["hp_current"],
                "reason": "hp_above_pool_remaining",
                "pool_remaining": pool_remaining,
            })

    # Mark the action slot.
    await _mark_battle_economy(campaign_id, char.id, "action")

    # Public roll log + spell-slot broadcast.
    affected_summary = ", ".join(
        f"{a['name']} ({a['hp']} HP)" for a in affected
    ) or "no one"
    note = f"💤 Sleep (L{slot_level}, pool {pool_total}) → {affected_summary}"
    await hub.broadcast(campaign_id, {
        "type": "roll",
        "data": {
            "expression": pool_expr,
            "total": pool_total,
            "breakdown": (
                f"{pool_breakdown} = {pool_total} HP pool. "
                f"Affected (asc HP): {affected_summary}. "
                f"Pool remaining after sleeps: {pool_remaining}."
            ),
            "note": note,
            "user_name": char.name,
            "char_name": char.name,
            "visibility": Visibility.PUBLIC.value,
        },
    })

    await hub.broadcast(campaign_id, {
        "type": "spell_slot_update",
        "data": {
            "character_id": char.id,
            "class_slug": class_slug,
            "level": slot_level,
            "total": total,
            "used": used + 1,
        },
    })

    # v2.99.463 — log the slot spend so the chat-card ↶ Undo refunds it.
    cast_id = _log_spell_slot_spend(
        campaign_id, char.id, class_slug, slot_level, used, "spell")
    return {
        "ok": True,
        "cast_id": cast_id,
        "slot_level": slot_level,
        "slot_used": used + 1,
        "slot_total": total,
        "class_slug": class_slug,
        "pool_expr": pool_expr,
        "pool_total": pool_total,
        "pool_breakdown": pool_breakdown,
        "pool_remaining": pool_remaining,
        "affected": affected,
        "unaffected": unaffected,
        "duration_rounds": sleep_duration_rounds,
        # v2.99.184 — Twinned auto-route response field.
        "twinned_target_combatant_id_2": _twin_target_2_sleep or None,
    }


# ----------- v2.99.140 — Invocation-driven spell-cast router -----------
#
# Closes the v2.99.137 filed item. Some Eldritch Invocations grant
# the warlock the ability to cast a spell (e.g. Mire the Mind →
# Slow, Sculptor of Flesh → Polymorph, Bewitching Whispers →
# Compulsion). Pre-v2.99.140 each /cast_<spell> endpoint that
# accepted an invocation route had to inline the slug check, the
# resource lookup, and the spell-list bypass logic — see
# v2.99.137's /cast_slow for the original inline implementation.
#
# This registry + the three helpers below extract that pattern. To
# wire a new invocation:
#
#   1. Add an entry to ``_INVOCATION_SPELL_CAST_REGISTRY`` keyed by
#      the invocation slug (without the ``eldritch-invocation-``
#      prefix — same convention as ``_pc_has_eldritch_invocation``).
#   2. Call ``_validate_invocation_cast(sheet, via_invocation)`` at
#      the top of the target /cast_<spell> endpoint. A non-None
#      return is a JSONResponse to surface directly to the caller.
#   3. When ``bypass_spell_list_check`` is True, skip the standard
#      "spell on caster's spell list" check (the invocation grants
#      the cast, so the spell isn't on the class list).
#   4. After the slot decrement, call
#      ``_consume_invocation_resource(sheet, via_invocation)`` to
#      decrement the 1/long-rest gating resource in place.
#
# The /cast_slow endpoint is the first consumer; future
# invocations will land their own /cast_<spell> wiring and reuse
# these helpers without duplicating the validation chain.

_INVOCATION_SPELL_CAST_REGISTRY: dict[str, dict] = {
    "mire-the-mind": {
        "spell_slug": "slow",
        "spell_name": "Slow",
        "class_slug": "warlock",
        "resource_key": "mire-the-mind-uses",
        "bypass_spell_list_check": True,
    },
    # v2.99.142 — Sculptor of Flesh: cast Polymorph once per long
    # rest using a Warlock spell slot. RAW prereq Lv 7 Warlock.
    # Routed via /cast_polymorph with via_invocation="sculptor-of-flesh".
    "sculptor-of-flesh": {
        "spell_slug": "polymorph",
        "spell_name": "Polymorph",
        "class_slug": "warlock",
        "resource_key": "sculptor-of-flesh-uses",
        "bypass_spell_list_check": True,
    },
    # v2.99.148 — Bewitching Whispers: cast Compulsion once per
    # long rest using a Warlock spell slot. RAW prereq Lv 7
    # Warlock. Routed via /cast_compulsion with
    # via_invocation="bewitching-whispers". Third consumer of
    # the registry — proves the abstraction generalizes.
    "bewitching-whispers": {
        "spell_slug": "compulsion",
        "spell_name": "Compulsion",
        "class_slug": "warlock",
        "resource_key": "bewitching-whispers-uses",
        "bypass_spell_list_check": True,
    },
    # v2.99.149 — Sign of Ill Omen: cast Bestow Curse once per
    # long rest using a Warlock spell slot. RAW prereq Lv 5
    # Warlock. Routed via /cast_bestow_curse with
    # via_invocation="sign-of-ill-omen". Fourth consumer of the
    # registry.
    "sign-of-ill-omen": {
        "spell_slug": "bestow-curse",
        "spell_name": "Bestow Curse",
        "class_slug": "warlock",
        "resource_key": "sign-of-ill-omen-uses",
        "bypass_spell_list_check": True,
    },
    # v2.99.150 — Thief of Five Fates: cast Bane once per long
    # rest using a Warlock spell slot. No RAW level prereq.
    # Routed via /cast_bane with via_invocation="thief-of-five-fates".
    # Fifth consumer of the registry.
    "thief-of-five-fates": {
        "spell_slug": "bane",
        "spell_name": "Bane",
        "class_slug": "warlock",
        "resource_key": "thief-of-five-fates-uses",
        "bypass_spell_list_check": True,
    },
    # Future entries (filed): "visions-of-distant-realms" → arcane
    # eye, "dreadful-word" → confusion, "minions-of-chaos" →
    # conjure elemental. Each needs its own /cast_<spell> wiring
    # + demo-seed resource entry; the router metadata stays here.
}


def _get_invocation_cast_meta(invocation_slug: str) -> dict | None:
    """v2.99.140 — return the spell-cast metadata for an invocation,
    or None if the slug isn't a registered spell-cast invocation."""
    if not invocation_slug:
        return None
    return _INVOCATION_SPELL_CAST_REGISTRY.get(
        invocation_slug.strip().lower()
    )


def _validate_invocation_cast(
    sheet: dict, invocation_slug: str,
) -> JSONResponse | None:
    """v2.99.140 — verify the caster has the invocation on their
    feats list AND a use is available on the gating resource.

    Returns ``None`` on success or a ready-to-return JSONResponse
    with the appropriate 409 error on failure. Callers should
    short-circuit their endpoint when this returns non-None.

    Used by /cast_<spell> endpoints that accept a ``via_invocation``
    body field. Returns ``None`` (i.e. "pass-through, run normal
    validation") when the invocation slug isn't registered — that
    way an unrecognized via_invocation falls through to the standard
    spell-list check.
    """
    meta = _get_invocation_cast_meta(invocation_slug)
    if not meta:
        return None
    if not _pc_has_eldritch_invocation(sheet, invocation_slug):
        return JSONResponse(status_code=409, content={
            "error": "missing_invocation",
            "invocation": invocation_slug,
        })
    resource_key = meta.get("resource_key")
    if resource_key:
        resources = list(sheet.get("resources") or [])
        idx = next(
            (i for i, r in enumerate(resources)
             if (r.get("key") or "").lower() == resource_key.lower()),
            -1,
        )
        if idx < 0:
            return JSONResponse(status_code=409, content={
                "error": "missing_resource",
                "resource_key": resource_key,
            })
        cur = int(resources[idx].get("current") or 0)
        if cur < 1:
            return JSONResponse(status_code=409, content={
                "error": "not_enough_uses",
                "resource_key": resource_key,
                "have": cur,
            })
    return None


def _consume_invocation_resource(sheet: dict, invocation_slug: str) -> dict:
    """v2.99.140 — decrement the gating resource for an invocation
    cast in the given sheet dict (in place). No-op if the slug
    isn't registered or has no gating resource. Returns the same
    sheet dict for chaining; caller persists via flag_modified +
    commit.
    """
    meta = _get_invocation_cast_meta(invocation_slug)
    if not meta:
        return sheet
    resource_key = meta.get("resource_key")
    if not resource_key:
        return sheet
    resources = list(sheet.get("resources") or [])
    idx = next(
        (i for i, r in enumerate(resources)
         if (r.get("key") or "").lower() == resource_key.lower()),
        -1,
    )
    if idx >= 0:
        row = dict(resources[idx])
        row["current"] = max(0, int(row.get("current") or 0) - 1)
        resources[idx] = row
        sheet["resources"] = resources
    return sheet


# ----------- API: cast Slow (3rd-level Transmutation, concentration) -----------

@router.post("/api/campaign/{campaign_id}/cast_slow")
async def cast_slow(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.101 — Cast Slow on up to six target combatants.

    Body: ``{character_id, class_slug, slot_level, target_combatant_ids,
    override?}``.

    RAW (PHB Slow, 3rd-level Transmutation): 1 action, 120 ft, 40-ft
    cube, concentration up to 1 minute, Wisdom save. v1 ships the
    speed-halving effect only (the mechanical hook into v2.99.98
    `_effective_speed_walk`); the other Slow effects (-2 AC, no
    reactions, action OR bonus action, single attack, spell delay
    roll) are filed for follow-up and surfaced as `raw_effects`
    bullets on the buff tooltip so the GM can narrate them today.

    The save logic is also a v1 simplification: the caller passes
    a pre-resolved list of target_combatant_ids (the "failed save"
    set). Auto-rolled saves can wire into this endpoint via the
    existing /respond pipeline in a follow-up.

    Validation: caster has class + Slow on spell list + an available
    Lv 3+ slot + Phase 4 action-economy gate (overrideable). RAW
    caps at 6 targets — the endpoint enforces.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    class_slug = (body.get("class_slug") or "").strip().lower()
    slot_level_raw = body.get("slot_level")
    slot_level = int(slot_level_raw) if slot_level_raw is not None else 3
    target_combatant_ids = body.get("target_combatant_ids") or []
    override = bool(body.get("override"))
    # v2.99.137 — Mire the Mind (Warlock invocation, PHB p.111).
    # When ``via_invocation == "mire-the-mind"`` is set, the cast
    # routes through the Mire the Mind 1/long-rest resource gate
    # and skips the standard "Slow on spell list" check (Slow
    # isn't a Warlock spell — the invocation is what grants it).
    via_invocation = (body.get("via_invocation") or "").strip().lower()

    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if class_slug not in ("wizard", "sorcerer", "warlock"):
        raise HTTPException(
            400, "class_slug must be wizard, sorcerer, or warlock",
        )
    if class_slug == "warlock":
        # v2.99.140 — Warlock can only cast Slow via a registered
        # invocation that maps to it (Mire the Mind today; future
        # invocations register additional routes). Verified against
        # ``_INVOCATION_SPELL_CAST_REGISTRY`` instead of a hardcoded
        # slug check.
        _meta_for_class = _get_invocation_cast_meta(via_invocation)
        if not _meta_for_class or _meta_for_class.get("spell_slug") != "slow":
            return JSONResponse(status_code=409, content={
                "error": "missing_invocation",
                "invocation": "mire-the-mind",
            })
    if slot_level < 3:
        raise HTTPException(400, "slot_level must be >= 3 (Slow is L3)")
    if not isinstance(target_combatant_ids, list) or not target_combatant_ids:
        raise HTTPException(400, "target_combatant_ids must be a non-empty list")
    if len(target_combatant_ids) > 6:
        return JSONResponse(status_code=409, content={
            "error": "too_many_targets",
            "max": 6,
            "got": len(target_combatant_ids),
        })

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Caster not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})

    primary_class = (sheet.get("class") or "").strip().lower()
    if primary_class != class_slug:
        has_class = any(
            (entry.get("class") or "").strip().lower() == class_slug
            for entry in (sheet.get("classes") or [])
        )
        if not has_class:
            return JSONResponse(status_code=409, content={
                "error": "wrong_class",
                "expected": class_slug,
                "got": primary_class or "",
            })

    # v2.99.140 — invocation-cast router. When ``via_invocation`` is
    # set AND the slug is registered in
    # ``_INVOCATION_SPELL_CAST_REGISTRY`` (e.g. "mire-the-mind"),
    # ``_validate_invocation_cast`` checks the feats list + the
    # gating resource (1/long-rest). If the invocation has
    # ``bypass_spell_list_check: True``, the standard "Slow on the
    # caster's spell list" check is skipped (the invocation is the
    # cast source). Pre-v2.99.140 this was inline; the helpers
    # extract the pattern for future invocations (Sculptor of Flesh
    # → Polymorph etc.) without each /cast_<spell> re-implementing
    # the validation chain.
    invocation_meta = _get_invocation_cast_meta(via_invocation)
    if invocation_meta:
        bad = _validate_invocation_cast(sheet, via_invocation)
        if bad is not None:
            return bad
    if not invocation_meta or not invocation_meta.get("bypass_spell_list_check"):
        spells = list(sheet.get("spells") or [])
        has_slow = any(
            (s.get("_slug") == "slow") or
            (str(s.get("name", "")).lower() == "slow")
            for s in spells
        )
        if not has_slow:
            return JSONResponse(status_code=409, content={
                "error": "spell_not_known",
                "spell": "slow",
            })

    all_slots = dict(sheet.get("spell_slots") or {})
    per_class = dict(all_slots.get(class_slug) or {})
    slot = dict(per_class.get(str(slot_level)) or {"total": 0, "used": 0})
    total = int(slot.get("total") or 0)
    used = int(slot.get("used") or 0)
    if total <= 0 or used >= total:
        return JSONResponse(status_code=409, content={
            "error": "no_slot",
            "level": slot_level,
            "class_slug": class_slug,
            "spell_name": "Slow",
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "slow",
            "label": "Slow",
            "strict": strict,
        })

    # Commit slot decrement.
    slot["used"] = used + 1
    per_class[str(slot_level)] = slot
    all_slots[class_slug] = per_class
    sheet["spell_slots"] = all_slots
    # v2.99.140 — also decrement the invocation's gating resource if
    # the cast was routed through one (e.g. Mire the Mind's
    # "mire-the-mind-uses" 1/long-rest). No-op for non-invocation
    # casts (Wizard / Sorcerer route).
    _consume_invocation_resource(sheet, via_invocation)
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # v2.99.109 — install caster-side concentration anchor BEFORE
    # the target buffs. Any prior concentration on the caster
    # (Hex / Hunter's Mark / etc.) is dropped via the
    # `_install_buff` v2.19.1 RAW concentration-swap; the cascade
    # then clears that prior spell's target buffs cleanly before
    # the new Slow targets get installed.
    await _install_caster_concentration_anchor(
        campaign_id, char, "slow", "Slow",
        duration_rounds=10, icon="🐢",
    )

    # v2.99.181 — Twinned Spell auto-route. When the caster has the
    # metamagic-twinned-pending buff with a second target, consume
    # the pending (one-shot per RAW) and append the second target
    # to the install list. Note: RAW Twinned applies only to
    # single-target spells; Slow targets up to 6 creatures + grouped
    # AoE, so this is technically not a RAW-valid combo. The helper
    # is wired anyway for GM convenience (the GM can decline by not
    # declaring Twinned). Mirror of v2.99.174 /cast_polymorph.
    _twin_target_2_slow = await _consume_twinned_for_second_target(
        campaign_id, int(char.id),
    )
    if _twin_target_2_slow and _twin_target_2_slow not in target_combatant_ids:
        target_combatant_ids = list(target_combatant_ids) + [_twin_target_2_slow]

    # Install slow buff on each target.
    affected: list[dict] = []
    unaffected: list[dict] = []
    for tid in target_combatant_ids:
        if not isinstance(tid, str) or not tid:
            continue
        c = _lookup_combatant(campaign_id, tid)
        if not c:
            unaffected.append({"combatant_id": tid, "reason": "not_found"})
            continue
        # v2.99.102 — explicitly handle speed_walk=0 (e.g. already
        # webbed). `or 30` would trip the falsy-int trap and lift a
        # 0 back to 30; default-only-on-None preserves the zero case.
        _raw_speed = c.get("speed_walk")
        try:
            base_speed = int(_raw_speed) if _raw_speed is not None else 30
        except (TypeError, ValueError):
            base_speed = 30
        buff = _make_slow_buff(
            target_speed_walk=base_speed,
            source_char_id=char.id,
            source_char_name=char.name,
            spell_save_dc=_compute_spell_save_dc_from_sheet(sheet),
        )
        installed = await _install_buff_on_combatant_id(
            campaign_id, tid, buff,
        )
        affected.append({
            "combatant_id": tid,
            "name": c.get("name") or "",
            "base_speed_walk": base_speed,
            "speed_reduction_ft": buff["effects"]["speed_reduction_ft"],
            "installed": installed,
        })

    await _mark_battle_economy(campaign_id, char.id, "action")

    affected_summary = ", ".join(
        f"{a['name']} (-{a['speed_reduction_ft']} ft)" for a in affected
    ) or "no one"
    note = f"🐢 Slow (L{slot_level}) → {affected_summary}"
    await hub.broadcast(campaign_id, {
        "type": "roll",
        "data": {
            "expression": "",
            "total": 0,
            "breakdown": (
                f"Slow installed on {len(affected)} target(s). "
                f"Concentration up to 1 min. Speed halved + other "
                f"RAW effects (narrate). Targets: {affected_summary}."
            ),
            "note": note,
            "user_name": char.name,
            "char_name": char.name,
            "visibility": Visibility.PUBLIC.value,
        },
    })

    await hub.broadcast(campaign_id, {
        "type": "spell_slot_update",
        "data": {
            "character_id": char.id,
            "class_slug": class_slug,
            "level": slot_level,
            "total": total,
            "used": used + 1,
        },
    })

    # v2.99.463 — log the slot spend so the chat-card ↶ Undo refunds it.
    cast_id = _log_spell_slot_spend(
        campaign_id, char.id, class_slug, slot_level, used, "spell")
    return {
        "ok": True,
        "cast_id": cast_id,
        "slot_level": slot_level,
        "slot_used": used + 1,
        "slot_total": total,
        "class_slug": class_slug,
        "affected": affected,
        "unaffected": unaffected,
        "duration_rounds": 10,
        "concentration": True,
        # v2.99.181 — Twinned auto-route response field.
        "twinned_target_combatant_id_2": _twin_target_2_slow or None,
    }


# ----------- API: cast Polymorph (4th-level Transmutation, concentration) -----------

@router.post("/api/campaign/{campaign_id}/cast_polymorph")
async def cast_polymorph(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.142 — Cast Polymorph: prepare the spell cast (slot +
    concentration anchor + audit). The actual transformation runs
    via the existing `/transform` endpoint with `source="polymorph"`
    on the target combatant — this endpoint is the "spell-side" half
    that handles the slot decrement + invocation gate + concentration
    anchor + chat-log audit.

    Body: ``{character_id, class_slug, slot_level, via_invocation?,
    override?}``.

    RAW (PHB p.266): L4 Transmutation, 1 action, 60 ft, concentration
    up to 1 hour. Target a creature (target must be willing or fail a
    WIS save) and transform it into a beast with CR ≤ target's level.
    The CR cap + target validation happen on `/transform`; this
    endpoint just consumes the slot + resource and broadcasts the
    audit.

    Classes that get Polymorph: Bard, Druid, Sorcerer, Wizard.
    Warlock-only via the v2.99.142 Sculptor of Flesh invocation
    (PHB p.111: "Prerequisite: 7th level. You can cast Polymorph
    once using a warlock spell slot. You can't do so again until
    you finish a long rest.").

    Second consumer of the v2.99.140 invocation-cast registry. The
    Sculptor of Flesh entry maps "sculptor-of-flesh" → polymorph;
    on Warlock callers, `via_invocation` must resolve to a registry
    entry whose `spell_slug == "polymorph"` (same pattern as the
    /cast_slow + Mire the Mind route).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    class_slug = (body.get("class_slug") or "").strip().lower()
    slot_level_raw = body.get("slot_level")
    slot_level = int(slot_level_raw) if slot_level_raw is not None else 4
    override = bool(body.get("override"))
    via_invocation = (body.get("via_invocation") or "").strip().lower()
    # v2.99.175 — Polymorph WIS save for unwilling targets. RAW
    # PHB p.266: "An unwilling creature must make a Wisdom saving
    # throw to resist the effect. If it succeeds, it isn't
    # affected by this spell." When unwilling=True + a PC target
    # is supplied, the endpoint rolls the target's WIS save vs
    # the caster's spell save DC. On success, the cast still
    # consumes the slot (RAW: the spell was cast even if it
    # didn't take effect) but skips the concentration anchor
    # install — the caster isn't concentrating on a polymorph
    # that didn't land.
    unwilling = bool(body.get("unwilling") or False)
    target_combatant_id = (body.get("target_combatant_id") or "").strip()

    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if class_slug not in ("bard", "druid", "sorcerer", "wizard", "warlock"):
        raise HTTPException(
            400,
            "class_slug must be bard, druid, sorcerer, wizard, or warlock",
        )
    if class_slug == "warlock":
        # v2.99.142 — Warlock can only cast Polymorph via a
        # registered invocation that maps to it (Sculptor of Flesh).
        _meta_for_class = _get_invocation_cast_meta(via_invocation)
        if not _meta_for_class or _meta_for_class.get("spell_slug") != "polymorph":
            return JSONResponse(status_code=409, content={
                "error": "missing_invocation",
                "invocation": "sculptor-of-flesh",
            })
    if slot_level < 4:
        raise HTTPException(400, "slot_level must be >= 4 (Polymorph is L4)")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Caster not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})

    primary_class = (sheet.get("class") or "").strip().lower()
    if primary_class != class_slug:
        has_class = any(
            (entry.get("class") or "").strip().lower() == class_slug
            for entry in (sheet.get("classes") or [])
        )
        if not has_class:
            return JSONResponse(status_code=409, content={
                "error": "wrong_class",
                "expected": class_slug,
                "got": primary_class or "",
            })

    # v2.99.140 — invocation-cast router (second consumer after
    # /cast_slow). When ``via_invocation`` resolves to a registry
    # entry, ``_validate_invocation_cast`` checks the feats list +
    # the gating resource. ``bypass_spell_list_check: True`` skips
    # the standard "Polymorph on spell list" check (the invocation
    # is the cast source).
    invocation_meta = _get_invocation_cast_meta(via_invocation)
    if invocation_meta:
        bad = _validate_invocation_cast(sheet, via_invocation)
        if bad is not None:
            return bad
    if not invocation_meta or not invocation_meta.get("bypass_spell_list_check"):
        spells = list(sheet.get("spells") or [])
        has_poly = any(
            (s.get("_slug") == "polymorph") or
            (str(s.get("name", "")).lower() == "polymorph")
            for s in spells
        )
        if not has_poly:
            return JSONResponse(status_code=409, content={
                "error": "spell_not_known",
                "spell": "polymorph",
            })

    all_slots = dict(sheet.get("spell_slots") or {})
    per_class = dict(all_slots.get(class_slug) or {})
    slot = dict(per_class.get(str(slot_level)) or {"total": 0, "used": 0})
    total = int(slot.get("total") or 0)
    used = int(slot.get("used") or 0)
    if total <= 0 or used >= total:
        return JSONResponse(status_code=409, content={
            "error": "no_slot",
            "level": slot_level,
            "class_slug": class_slug,
            "spell_name": "Polymorph",
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "polymorph",
            "label": "Polymorph",
            "strict": strict,
        })

    # Commit slot decrement.
    slot["used"] = used + 1
    per_class[str(slot_level)] = slot
    all_slots[class_slug] = per_class
    sheet["spell_slots"] = all_slots
    # v2.99.140 — also decrement the invocation's gating resource if
    # the cast was routed through one (Sculptor of Flesh's
    # "sculptor-of-flesh-uses" 1/long-rest).
    _consume_invocation_resource(sheet, via_invocation)
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # v2.99.175 — Polymorph WIS save for unwilling targets. Rolled
    # server-side when `unwilling=True` + target_combatant_id
    # resolves to a PC. Save mod = WIS ability mod + proficiency
    # bonus (if proficient in WIS saves). DC = caster's spell save
    # DC. On success: skip the concentration anchor install + return
    # `saved: True`. The slot is still consumed per RAW (the spell
    # was cast — it just didn't take effect).
    _save_rolled = False
    _save_passed = False
    _save_total = 0
    _save_dc = _compute_spell_save_dc_from_sheet(sheet)
    _target_name = ""
    if unwilling and target_combatant_id:
        _target_combatant = _lookup_combatant(campaign_id, target_combatant_id)
        _save_mod = None
        if _target_combatant:
            if _target_combatant.get("char_id"):
                # PC target — read from Character.sheet.
                _target_char = db.query(Character).filter(
                    Character.id == int(_target_combatant["char_id"]),
                ).first()
                if _target_char and _target_char.sheet:
                    _t_sheet = dict(_target_char.sheet or {})
                    _target_name = _target_char.name or _target_combatant.get("name") or ""
                    _wis = int((_t_sheet.get("abilities") or {}).get("WIS", 10))
                    _wis_mod = (_wis - 10) // 2
                    _t_prof = int(_t_sheet.get("proficiency_bonus") or 2)
                    # v2.99.206 — Slippery Mind (Rogue Lv 15+) grants
                    # WIS save proficiency. RAW: "By 15th level, you
                    # gain proficiency in Wisdom saving throws."
                    # OR'd with the sheet-stored saving_throws.WIS
                    # so existing prof-WIS classes (Wizard, Cleric,
                    # Druid, Sorcerer, Warlock, Monk) keep firing
                    # via the explicit path; Slippery Mind adds the
                    # class-feature gate.
                    # v2.99.208 — Diamond Soul (Monk Lv 14+) grants
                    # proficiency in ALL saves. OR'd alongside
                    # Slippery Mind so a multi-classed Monk/Rogue
                    # gets both gates.
                    _wis_proficient = bool(
                        (_t_sheet.get("saving_throws") or {}).get("WIS")
                    ) or _pc_has_slippery_mind(_t_sheet) or _pc_has_diamond_soul(_t_sheet)
                    _save_mod = _wis_mod + (_t_prof if _wis_proficient else 0)
            elif _target_combatant.get("token_template_id"):
                # v2.99.180 — NPC target. Read save mod from the
                # template via `_monster_template_to_sheet` +
                # `_resolve_stat_modifier`. Closes the v2.99.175
                # filed item "NPC target WIS save".
                _tmpl_id = _target_combatant.get("token_template_id")
                try:
                    _tmpl = db.query(TokenTemplate).filter(
                        TokenTemplate.id == int(_tmpl_id),
                    ).first()
                    if _tmpl is not None:
                        _npc_sheet = _monster_template_to_sheet(
                            _tmpl, campaign_id,
                        )
                        _save_mod_raw, _ = _resolve_stat_modifier(
                            _npc_sheet, "dnd5e", "wis_save",
                        )
                        _save_mod = int(_save_mod_raw)
                        _target_name = (
                            _target_combatant.get("name") or _tmpl.name or ""
                        )
                except Exception:
                    _save_mod = None
        if _save_mod is not None:
            import random as _random_polymorph
            _d20 = _random_polymorph.randint(1, 20)
            _save_total = _d20 + _save_mod
            _save_rolled = True
            _save_passed = _save_total >= _save_dc
            await hub.broadcast(campaign_id, {
                "type": "roll",
                "data": {
                    "expression": f"1d20+{_save_mod}",
                    "total": _save_total,
                    "breakdown": (
                        f"WIS save: 1d20[{_d20}]+{_save_mod} = "
                        f"{_save_total} vs DC {_save_dc} → "
                        f"{'PASS' if _save_passed else 'FAIL'}"
                    ),
                    "note": (
                        f"🧠 {_target_name}'s WIS save vs "
                        f"{char.name}'s Polymorph"
                    ),
                    "user_name": char.name,
                    "char_name": _target_name,
                    "visibility": Visibility.PUBLIC.value,
                },
            })

    # Caster concentration anchor (1 hour = 600 rounds). Skip if
    # the unwilling target passed their WIS save — RAW the spell
    # doesn't take effect, so there's nothing to concentrate on.
    if not (_save_rolled and _save_passed):
        await _install_caster_concentration_anchor(
            campaign_id, char, "polymorph", "Polymorph",
            duration_rounds=600, icon="🐺",
        )
    # v2.99.174 — Twinned Spell auto-route. When the caster has a
    # `metamagic-twinned-pending` buff carrying a second target,
    # surface the second target in the audit + the response. The
    # helper consumes the pending one-shot (RAW: Twinned applies
    # to THIS cast). v1 surfaces the second target ID; the
    # downstream /transform call on the second target is still
    # GM-resolved (no auto-transform), but the audit broadcast
    # gives the GM a single source of truth instead of needing
    # to remember the pre-cast Twinned declaration.
    _twin_target_2 = await _consume_twinned_for_second_target(
        campaign_id, int(char.id),
    )
    await _mark_battle_economy(campaign_id, char.id, "action")

    invocation_tag = (
        f" via {invocation_meta['spell_name']}-invocation "
        f"({via_invocation})"
        if invocation_meta else ""
    )
    note = (
        f"🐺 {char.name} casts Polymorph (L{slot_level}){invocation_tag} — "
        f"target via /transform"
    )
    await hub.broadcast(campaign_id, {
        "type": "roll",
        "data": {
            "expression": "",
            "total": 0,
            "breakdown": note,
            "note": note,
            "user_name": char.name,
            "char_name": char.name,
            "visibility": Visibility.PUBLIC.value,
        },
    })

    await hub.broadcast(campaign_id, {
        "type": "spell_slot_update",
        "data": {
            "character_id": char.id,
            "class_slug": class_slug,
            "level": slot_level,
            "total": total,
            "used": used + 1,
        },
    })

    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "feature_name": "🐺 Polymorph",
            "feature_desc": (
                f"{char.name} casts Polymorph. Pick a target via "
                f"`/transform` with source=\"polymorph\"."
                + (
                    f" Twinned — second target combatant_id: "
                    f"{_twin_target_2}"
                    if _twin_target_2 else ""
                )
            ),
            "source": (
                f"sculptor-of-flesh" if via_invocation == "sculptor-of-flesh"
                else "polymorph"
            ),
            "via_invocation": via_invocation or None,
            "duration_rounds": 600,
            # v2.99.174 — surface the second target on the audit when
            # Twinned consumed.
            "twinned_target_combatant_id_2": _twin_target_2 or None,
        },
    })

    # v2.99.463 — log the slot spend so the chat-card ↶ Undo refunds it.
    cast_id = _log_spell_slot_spend(
        campaign_id, char.id, class_slug, slot_level, used, "spell")
    return {
        "ok": True,
        "cast_id": cast_id,
        "slot_level": slot_level,
        "slot_used": used + 1,
        "slot_total": total,
        "class_slug": class_slug,
        "via_invocation": via_invocation or None,
        "duration_rounds": 600,
        "concentration": not (_save_rolled and _save_passed),
        "ready_to_transform": not (_save_rolled and _save_passed),
        # v2.99.174 — Twinned auto-route response field.
        "twinned_target_combatant_id_2": _twin_target_2 or None,
        # v2.99.175 — WIS save fields for unwilling targets.
        "save_rolled": _save_rolled,
        "save_passed": _save_passed,
        "save_total": _save_total,
        "save_dc": _save_dc,
        "save_target_name": _target_name or None,
    }


# ----------- API: cast Compulsion (4th-level Enchantment, concentration) -----------

@router.post("/api/campaign/{campaign_id}/cast_compulsion")
async def cast_compulsion(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.148 — Cast Compulsion: prepare the spell cast (slot +
    concentration anchor + audit). RAW (PHB p.224): L4 Enchantment,
    1 action, 30 ft (caster radius), concentration up to 1 minute.
    Each creature in range (caster's choice) makes a WIS save; on
    fail, the caster designates a direction on each of the
    target's turns and the target must use all of its movement
    in that direction.

    v1 ships the spell-side audit (slot + resource + concentration
    anchor + chat-log audit). The WIS save resolution per target
    + the per-turn movement compulsion are filed — they need a
    `compelled_direction` buff that the speed engine's movement
    enforcement consults.

    Body: ``{character_id, class_slug, slot_level, via_invocation?,
    override?}``.

    Classes that get Compulsion: Bard, Wizard. Warlock-only via
    the v2.99.148 Bewitching Whispers invocation (PHB p.110:
    "Prerequisite: 7th level. You can cast Compulsion once using
    a warlock spell slot. You can't do so again until you finish
    a long rest.").

    Third consumer of the v2.99.140 invocation-cast registry —
    after v2.99.137 Mire the Mind and v2.99.142 Sculptor of Flesh.
    Reuses the same helpers (`_get_invocation_cast_meta`,
    `_validate_invocation_cast`, `_consume_invocation_resource`)
    without adding new validation code.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    class_slug = (body.get("class_slug") or "").strip().lower()
    slot_level_raw = body.get("slot_level")
    slot_level = int(slot_level_raw) if slot_level_raw is not None else 4
    override = bool(body.get("override"))
    via_invocation = (body.get("via_invocation") or "").strip().lower()

    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if class_slug not in ("bard", "wizard", "warlock"):
        raise HTTPException(
            400, "class_slug must be bard, wizard, or warlock",
        )
    if class_slug == "warlock":
        # v2.99.148 — Warlock can only cast Compulsion via a
        # registered invocation that maps to it (Bewitching
        # Whispers).
        _meta_for_class = _get_invocation_cast_meta(via_invocation)
        if not _meta_for_class or _meta_for_class.get("spell_slug") != "compulsion":
            return JSONResponse(status_code=409, content={
                "error": "missing_invocation",
                "invocation": "bewitching-whispers",
            })
    if slot_level < 4:
        raise HTTPException(400, "slot_level must be >= 4 (Compulsion is L4)")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Caster not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})

    primary_class = (sheet.get("class") or "").strip().lower()
    if primary_class != class_slug:
        has_class = any(
            (entry.get("class") or "").strip().lower() == class_slug
            for entry in (sheet.get("classes") or [])
        )
        if not has_class:
            return JSONResponse(status_code=409, content={
                "error": "wrong_class",
                "expected": class_slug,
                "got": primary_class or "",
            })

    # v2.99.140 — invocation-cast router (third consumer after
    # /cast_slow + /cast_polymorph). Same helper chain.
    invocation_meta = _get_invocation_cast_meta(via_invocation)
    if invocation_meta:
        bad = _validate_invocation_cast(sheet, via_invocation)
        if bad is not None:
            return bad
    if not invocation_meta or not invocation_meta.get("bypass_spell_list_check"):
        spells = list(sheet.get("spells") or [])
        has_comp = any(
            (s.get("_slug") == "compulsion") or
            (str(s.get("name", "")).lower() == "compulsion")
            for s in spells
        )
        if not has_comp:
            return JSONResponse(status_code=409, content={
                "error": "spell_not_known",
                "spell": "compulsion",
            })

    all_slots = dict(sheet.get("spell_slots") or {})
    per_class = dict(all_slots.get(class_slug) or {})
    slot = dict(per_class.get(str(slot_level)) or {"total": 0, "used": 0})
    total = int(slot.get("total") or 0)
    used = int(slot.get("used") or 0)
    if total <= 0 or used >= total:
        return JSONResponse(status_code=409, content={
            "error": "no_slot",
            "level": slot_level,
            "class_slug": class_slug,
            "spell_name": "Compulsion",
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "compulsion",
            "label": "Compulsion",
            "strict": strict,
        })

    # Commit slot decrement.
    slot["used"] = used + 1
    per_class[str(slot_level)] = slot
    all_slots[class_slug] = per_class
    sheet["spell_slots"] = all_slots
    _consume_invocation_resource(sheet, via_invocation)
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # Caster concentration anchor (1 minute = 10 rounds).
    await _install_caster_concentration_anchor(
        campaign_id, char, "compulsion", "Compulsion",
        duration_rounds=10, icon="🎭",
    )
    # v2.99.181 — Twinned Spell auto-route. Surfaces the second
    # target on the response + feature_used broadcast. Same pattern
    # as v2.99.174 /cast_polymorph + v2.99.181 /cast_slow.
    _twin_target_2_comp = await _consume_twinned_for_second_target(
        campaign_id, int(char.id),
    )
    await _mark_battle_economy(campaign_id, char.id, "action")

    invocation_tag = (
        f" via {invocation_meta['spell_name']}-invocation "
        f"({via_invocation})"
        if invocation_meta else ""
    )
    note = (
        f"🎭 {char.name} casts Compulsion (L{slot_level}){invocation_tag} — "
        f"target WIS saves filed (v1 stops at the cast)"
    )
    await hub.broadcast(campaign_id, {
        "type": "roll",
        "data": {
            "expression": "",
            "total": 0,
            "breakdown": note,
            "note": note,
            "user_name": char.name,
            "char_name": char.name,
            "visibility": Visibility.PUBLIC.value,
        },
    })

    await hub.broadcast(campaign_id, {
        "type": "spell_slot_update",
        "data": {
            "character_id": char.id,
            "class_slug": class_slug,
            "level": slot_level,
            "total": total,
            "used": used + 1,
        },
    })

    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "feature_name": "🎭 Compulsion",
            "feature_desc": (
                f"{char.name} casts Compulsion. Each creature in "
                f"30 ft makes a WIS save (per-target saves filed)."
            ),
            "source": (
                "bewitching-whispers" if via_invocation == "bewitching-whispers"
                else "compulsion"
            ),
            "via_invocation": via_invocation or None,
            "duration_rounds": 10,
            "range_ft": 30,
        },
    })

    # v2.99.463 — log the slot spend so the chat-card ↶ Undo refunds it.
    cast_id = _log_spell_slot_spend(
        campaign_id, char.id, class_slug, slot_level, used, "spell")
    return {
        "ok": True,
        "cast_id": cast_id,
        "slot_level": slot_level,
        "slot_used": used + 1,
        "slot_total": total,
        "class_slug": class_slug,
        "via_invocation": via_invocation or None,
        "duration_rounds": 10,
        "range_ft": 30,
        "concentration": True,
        # v2.99.181 — Twinned auto-route response field.
        "twinned_target_combatant_id_2": _twin_target_2_comp or None,
    }


# ----------- API: cast Bestow Curse (3rd-level Necromancy, concentration) -----------

@router.post("/api/campaign/{campaign_id}/cast_bestow_curse")
async def cast_bestow_curse(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.149 — Cast Bestow Curse: prepare the spell cast (slot
    + concentration anchor + audit). RAW (PHB p.218): L3
    Necromancy, 1 action, touch, concentration up to 1 minute.
    Target a creature; on a failed WIS save the caster picks one
    of four curse effects (disadvantage on ability checks tied to
    one ability, disadvantage on attack rolls against the caster,
    WIS save at start of each turn or wasted turn, +1d8 necrotic
    damage from caster's attacks/spells).

    Classes that get Bestow Curse: Bard, Cleric, Wizard. Warlock-
    only via the v2.99.149 Sign of Ill Omen invocation (PHB
    p.111: "Prerequisite: 5th level. You can cast Bestow Curse
    once using a warlock spell slot. You can't do so again until
    you finish a long rest.").

    Fourth consumer of the v2.99.140 invocation-cast registry,
    mirror of /cast_compulsion + /cast_polymorph. v1 ships the
    spell-side audit (slot + resource + concentration anchor);
    per-target WIS save resolution + the four curse-effect buffs
    are filed.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    class_slug = (body.get("class_slug") or "").strip().lower()
    slot_level_raw = body.get("slot_level")
    slot_level = int(slot_level_raw) if slot_level_raw is not None else 3
    override = bool(body.get("override"))
    via_invocation = (body.get("via_invocation") or "").strip().lower()

    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if class_slug not in ("bard", "cleric", "wizard", "warlock"):
        raise HTTPException(
            400, "class_slug must be bard, cleric, wizard, or warlock",
        )
    if class_slug == "warlock":
        # v2.99.149 — Warlock can only cast Bestow Curse via a
        # registered invocation that maps to it (Sign of Ill Omen).
        _meta_for_class = _get_invocation_cast_meta(via_invocation)
        if not _meta_for_class or _meta_for_class.get("spell_slug") != "bestow-curse":
            return JSONResponse(status_code=409, content={
                "error": "missing_invocation",
                "invocation": "sign-of-ill-omen",
            })
    if slot_level < 3:
        raise HTTPException(400, "slot_level must be >= 3 (Bestow Curse is L3)")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Caster not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})

    primary_class = (sheet.get("class") or "").strip().lower()
    if primary_class != class_slug:
        has_class = any(
            (entry.get("class") or "").strip().lower() == class_slug
            for entry in (sheet.get("classes") or [])
        )
        if not has_class:
            return JSONResponse(status_code=409, content={
                "error": "wrong_class",
                "expected": class_slug,
                "got": primary_class or "",
            })

    # v2.99.140 — invocation-cast router (fourth consumer).
    invocation_meta = _get_invocation_cast_meta(via_invocation)
    if invocation_meta:
        bad = _validate_invocation_cast(sheet, via_invocation)
        if bad is not None:
            return bad
    if not invocation_meta or not invocation_meta.get("bypass_spell_list_check"):
        spells = list(sheet.get("spells") or [])
        has_bc = any(
            (s.get("_slug") == "bestow-curse") or
            (str(s.get("name", "")).lower() == "bestow curse")
            for s in spells
        )
        if not has_bc:
            return JSONResponse(status_code=409, content={
                "error": "spell_not_known",
                "spell": "bestow-curse",
            })

    all_slots = dict(sheet.get("spell_slots") or {})
    per_class = dict(all_slots.get(class_slug) or {})
    slot = dict(per_class.get(str(slot_level)) or {"total": 0, "used": 0})
    total = int(slot.get("total") or 0)
    used = int(slot.get("used") or 0)
    if total <= 0 or used >= total:
        return JSONResponse(status_code=409, content={
            "error": "no_slot",
            "level": slot_level,
            "class_slug": class_slug,
            "spell_name": "Bestow Curse",
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "bestow-curse",
            "label": "Bestow Curse",
            "strict": strict,
        })

    # Commit slot decrement.
    slot["used"] = used + 1
    per_class[str(slot_level)] = slot
    all_slots[class_slug] = per_class
    sheet["spell_slots"] = all_slots
    _consume_invocation_resource(sheet, via_invocation)
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # Caster concentration anchor (1 minute = 10 rounds at base L3;
    # upcast at L4-L8 → 10 min concentration; L9 → 1 day. v1 stamps
    # the base 10 rounds, callers can adjust the anchor's duration
    # downstream if upcast handling is wired).
    await _install_caster_concentration_anchor(
        campaign_id, char, "bestow-curse", "Bestow Curse",
        duration_rounds=10, icon="🕷️",
    )
    # v2.99.183 — Twinned Spell auto-route. Surfaces the second
    # target on the response. Per-target buff install on the
    # second target is filed alongside the v1 WIS save resolution.
    _twin_target_2_bc = await _consume_twinned_for_second_target(
        campaign_id, int(char.id),
    )
    await _mark_battle_economy(campaign_id, char.id, "action")

    invocation_tag = (
        f" via {invocation_meta['spell_name']}-invocation "
        f"({via_invocation})"
        if invocation_meta else ""
    )
    note = (
        f"🕷️ {char.name} casts Bestow Curse (L{slot_level}){invocation_tag} — "
        f"touch range, WIS save filed (v1 stops at the cast)"
    )
    await hub.broadcast(campaign_id, {
        "type": "roll",
        "data": {
            "expression": "",
            "total": 0,
            "breakdown": note,
            "note": note,
            "user_name": char.name,
            "char_name": char.name,
            "visibility": Visibility.PUBLIC.value,
        },
    })

    await hub.broadcast(campaign_id, {
        "type": "spell_slot_update",
        "data": {
            "character_id": char.id,
            "class_slug": class_slug,
            "level": slot_level,
            "total": total,
            "used": used + 1,
        },
    })

    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "feature_name": "🕷️ Bestow Curse",
            "feature_desc": (
                f"{char.name} casts Bestow Curse. Target makes a "
                f"WIS save (per-target save + curse-effect picker "
                f"filed)."
            ),
            "source": (
                "sign-of-ill-omen" if via_invocation == "sign-of-ill-omen"
                else "bestow-curse"
            ),
            "via_invocation": via_invocation or None,
            "duration_rounds": 10,
            "range_ft": 5,
        },
    })

    # v2.99.463 — log the slot spend so the chat-card ↶ Undo refunds it.
    cast_id = _log_spell_slot_spend(
        campaign_id, char.id, class_slug, slot_level, used, "spell")
    return {
        "ok": True,
        "cast_id": cast_id,
        "slot_level": slot_level,
        "slot_used": used + 1,
        "slot_total": total,
        "class_slug": class_slug,
        "via_invocation": via_invocation or None,
        "duration_rounds": 10,
        "range_ft": 5,
        "concentration": True,
        # v2.99.183 — Twinned auto-route response field.
        "twinned_target_combatant_id_2": _twin_target_2_bc or None,
    }


# ----------- API: cast Bane (1st-level Enchantment, concentration) -----------

@router.post("/api/campaign/{campaign_id}/cast_bane")
async def cast_bane(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.150 — Cast Bane: prepare the spell cast (slot +
    concentration anchor + audit). RAW (PHB p.216): L1
    Enchantment, 1 action, 30 ft, concentration up to 1 minute.
    Up to 3 creatures make CHA save; on fail they subtract 1d4
    from attack rolls + saving throws for the duration.

    Classes that get Bane: Bard, Cleric. Warlock-only via the
    v2.99.150 Thief of Five Fates invocation (PHB p.111: "You
    can cast Bane once using a warlock spell slot. You can't do
    so again until you finish a long rest.").

    Fifth consumer of the v2.99.140 invocation-cast registry,
    mirror of /cast_bestow_curse + /cast_compulsion + /cast_polymorph.
    v1 ships the spell-side audit (slot + resource + concentration
    anchor); per-target CHA save resolution + the 1d4 penalty buff
    are filed.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    class_slug = (body.get("class_slug") or "").strip().lower()
    slot_level_raw = body.get("slot_level")
    # v2.99.150 — explicit None check so a literal 0 surfaces the
    # below "slot_level < 1" → 400 gate (falsy-int trap fix
    # mirroring v2.99.102 / .103 / .140 patches elsewhere).
    slot_level = int(slot_level_raw) if slot_level_raw is not None else 1
    override = bool(body.get("override"))
    via_invocation = (body.get("via_invocation") or "").strip().lower()

    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if class_slug not in ("bard", "cleric", "warlock"):
        raise HTTPException(
            400, "class_slug must be bard, cleric, or warlock",
        )
    if class_slug == "warlock":
        # v2.99.150 — Warlock can only cast Bane via a registered
        # invocation that maps to it (Thief of Five Fates).
        _meta_for_class = _get_invocation_cast_meta(via_invocation)
        if not _meta_for_class or _meta_for_class.get("spell_slug") != "bane":
            return JSONResponse(status_code=409, content={
                "error": "missing_invocation",
                "invocation": "thief-of-five-fates",
            })
    if slot_level < 1:
        raise HTTPException(400, "slot_level must be >= 1 (Bane is L1)")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Caster not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})

    primary_class = (sheet.get("class") or "").strip().lower()
    if primary_class != class_slug:
        has_class = any(
            (entry.get("class") or "").strip().lower() == class_slug
            for entry in (sheet.get("classes") or [])
        )
        if not has_class:
            return JSONResponse(status_code=409, content={
                "error": "wrong_class",
                "expected": class_slug,
                "got": primary_class or "",
            })

    # v2.99.140 — invocation-cast router (fifth consumer).
    invocation_meta = _get_invocation_cast_meta(via_invocation)
    if invocation_meta:
        bad = _validate_invocation_cast(sheet, via_invocation)
        if bad is not None:
            return bad
    if not invocation_meta or not invocation_meta.get("bypass_spell_list_check"):
        spells = list(sheet.get("spells") or [])
        has_bane = any(
            (s.get("_slug") == "bane") or
            (str(s.get("name", "")).lower() == "bane")
            for s in spells
        )
        if not has_bane:
            return JSONResponse(status_code=409, content={
                "error": "spell_not_known",
                "spell": "bane",
            })

    # NOTE: Warlock Lv 5 Pact Magic slots are all L3 — but Thief
    # of Five Fates lets the cast burn any Warlock slot for L1
    # Bane. The registry's resource gate handles the 1/long-rest
    # cap; the slot decrement still uses whatever level was
    # requested. For testing convenience the endpoint accepts the
    # caster's actual slot level (Magnus's L3 Pact slot) when the
    # requested level matches.
    all_slots = dict(sheet.get("spell_slots") or {})
    per_class = dict(all_slots.get(class_slug) or {})
    slot = dict(per_class.get(str(slot_level)) or {"total": 0, "used": 0})
    total = int(slot.get("total") or 0)
    used = int(slot.get("used") or 0)
    if total <= 0 or used >= total:
        return JSONResponse(status_code=409, content={
            "error": "no_slot",
            "level": slot_level,
            "class_slug": class_slug,
            "spell_name": "Bane",
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "bane",
            "label": "Bane",
            "strict": strict,
        })

    # Commit slot decrement.
    slot["used"] = used + 1
    per_class[str(slot_level)] = slot
    all_slots[class_slug] = per_class
    sheet["spell_slots"] = all_slots
    _consume_invocation_resource(sheet, via_invocation)
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # Caster concentration anchor (1 minute = 10 rounds).
    await _install_caster_concentration_anchor(
        campaign_id, char, "bane", "Bane",
        duration_rounds=10, icon="🎯",
    )
    # v2.99.183 — Twinned Spell auto-route. Bane is multi-target
    # (up to 3) RAW; per-target install with the v1 -1d4 penalty
    # buff is filed. v1 surfaces the second target on the
    # response.
    _twin_target_2_bn = await _consume_twinned_for_second_target(
        campaign_id, int(char.id),
    )
    await _mark_battle_economy(campaign_id, char.id, "action")

    invocation_tag = (
        f" via {invocation_meta['spell_name']}-invocation "
        f"({via_invocation})"
        if invocation_meta else ""
    )
    note = (
        f"🎯 {char.name} casts Bane (L{slot_level}){invocation_tag} — "
        f"3 target CHA saves filed (v1 stops at the cast)"
    )
    await hub.broadcast(campaign_id, {
        "type": "roll",
        "data": {
            "expression": "",
            "total": 0,
            "breakdown": note,
            "note": note,
            "user_name": char.name,
            "char_name": char.name,
            "visibility": Visibility.PUBLIC.value,
        },
    })

    await hub.broadcast(campaign_id, {
        "type": "spell_slot_update",
        "data": {
            "character_id": char.id,
            "class_slug": class_slug,
            "level": slot_level,
            "total": total,
            "used": used + 1,
        },
    })

    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "feature_name": "🎯 Bane",
            "feature_desc": (
                f"{char.name} casts Bane. Up to 3 creatures in 30 ft "
                f"make a CHA save (per-target save + -1d4 penalty "
                f"buff filed)."
            ),
            "source": (
                "thief-of-five-fates" if via_invocation == "thief-of-five-fates"
                else "bane"
            ),
            "via_invocation": via_invocation or None,
            "duration_rounds": 10,
            "range_ft": 30,
            "max_targets": 3,
        },
    })

    # v2.99.463 — log the slot spend so the chat-card ↶ Undo refunds it.
    cast_id = _log_spell_slot_spend(
        campaign_id, char.id, class_slug, slot_level, used, "spell")
    return {
        "ok": True,
        "cast_id": cast_id,
        "slot_level": slot_level,
        "slot_used": used + 1,
        "slot_total": total,
        "class_slug": class_slug,
        "via_invocation": via_invocation or None,
        "duration_rounds": 10,
        "range_ft": 30,
        "max_targets": 3,
        "concentration": True,
        # v2.99.183 — Twinned auto-route response field.
        "twinned_target_combatant_id_2": _twin_target_2_bn or None,
    }


# ----------- API: Grapple action (PHB p.195) -----------

@router.post("/api/campaign/{campaign_id}/use_grapple")
async def use_grapple(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.112 — Use the Grapple action on a target combatant.

    Body: ``{character_id, target_combatant_id, override?}``.

    RAW (PHB p.195): replace one attack with a STR (Athletics)
    check contested by the target's STR (Athletics) or DEX
    (Acrobatics) check (target chooses). Success → target Grappled.

    v1 ships the mechanical install + audit broadcast. The
    contested check itself is a v1 simplification — the GM
    pre-decides the outcome via the standard /roll workflow and
    invokes this endpoint when the grapple lands. A future commit
    can add auto-rolled contested checks via /respond-style save
    threading. The grapple action consumes the attacker's action
    slot (overrideable).

    Validation:
      - character_id + target_combatant_id required
      - target_combatant must exist in active battle
      - action slot enforcement (overrideable per the standard
        Phase 4 gate)
    """
    body = await request.json()
    char_id_raw = body.get("character_id")
    try:
        char_id = int(char_id_raw) if char_id_raw else 0
    except (TypeError, ValueError):
        char_id = 0
    target_combatant_id = (body.get("target_combatant_id") or "").strip()
    override = bool(body.get("override"))
    # v2.99.113 — optional pre-rolled contested check totals. When
    # BOTH are supplied, the server compares them and only installs
    # the grappled buff on grappler-win. Either missing → legacy
    # v2.99.112 "always install" behavior (assumes GM resolved the
    # check externally and is just marking the grapple).
    attacker_check_total_raw = body.get("attacker_check_total")
    target_check_total_raw = body.get("target_check_total")

    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if not target_combatant_id:
        raise HTTPException(400, "target_combatant_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Grappler not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    target = _lookup_combatant(campaign_id, target_combatant_id)
    if not target:
        return JSONResponse(status_code=404, content={
            "error": "target_not_found",
            "target_combatant_id": target_combatant_id,
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "grapple",
            "label": "Grapple",
            "strict": strict,
        })

    # v2.99.113 — auto-resolved contested check when both totals are
    # supplied. RAW PHB Grapple: STR (Athletics) check contested by
    # the target's STR (Athletics) or DEX (Acrobatics). Grappler
    # must STRICTLY beat the target (RAW: "you fail on a tie").
    attacker_total: int | None = None
    target_total: int | None = None
    if (
        attacker_check_total_raw is not None
        and target_check_total_raw is not None
    ):
        try:
            attacker_total = int(attacker_check_total_raw)
            target_total = int(target_check_total_raw)
        except (TypeError, ValueError):
            return JSONResponse(status_code=400, content={
                "error": "bad_check_totals",
                "attacker_check_total": str(attacker_check_total_raw),
                "target_check_total": str(target_check_total_raw),
            })

    if attacker_total is not None and target_total is not None:
        if attacker_total > target_total:
            outcome = "grappler_won"
        elif attacker_total < target_total:
            outcome = "target_won"
        else:
            outcome = "tie"  # RAW: target wins on ties → no grapple
    else:
        outcome = "auto"  # legacy v2.99.112 path: install unconditionally

    target_name = target.get("name") or "Target"
    # Action is spent on the attempt regardless of outcome.
    await _mark_battle_economy(campaign_id, char.id, "action")

    # On a failed grapple (target_won OR tie), short-circuit before
    # the buff install + grapple-success broadcasts. Still emit a
    # short audit so the chat log shows "tried and failed".
    if outcome in ("target_won", "tie"):
        outcome_copy = (
            "target broke free"
            if outcome == "target_won"
            else "tied — target wins by RAW"
        )
        note = (
            f"🤼 {char.name}'s grapple on {target_name} failed "
            f"({outcome_copy}: {attacker_total} vs {target_total})"
        )
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "character_name": char.name,
                "feature_name": "🤼 Grapple (failed)",
                "feature_desc": note,
                "source": "grapple-action",
                "target_combatant_id": target_combatant_id,
                "target_name": target_name,
                "outcome": outcome,
                "attacker_check_total": attacker_total,
                "target_check_total": target_total,
            },
        })
        await hub.broadcast(campaign_id, {
            "type": "roll",
            "data": {
                "expression": "",
                "total": 0,
                "breakdown": note,
                "note": note,
                "user_name": char.name,
                "char_name": char.name,
                "visibility": Visibility.PUBLIC.value,
            },
        })
        return {
            "ok": True,
            "outcome": outcome,
            "grappler_character_id": char.id,
            "grappler_name": char.name,
            "target_combatant_id": target_combatant_id,
            "target_name": target_name,
            "installed": False,
            "attacker_check_total": attacker_total,
            "target_check_total": target_total,
        }

    # Pull the target's speed_walk for the buff math. Same falsy-
    # zero guard as the spell endpoints.
    _raw_speed = target.get("speed_walk")
    try:
        base_speed = int(_raw_speed) if _raw_speed is not None else 30
    except (TypeError, ValueError):
        base_speed = 30

    buff = _make_grapple_action_buff(
        target_speed_walk=base_speed,
        source_char_id=char.id,
        source_char_name=char.name,
        grappler_athletics_dc=_compute_grappler_athletics_dc_from_sheet(
            char.sheet or {},
        ),
    )
    installed = await _install_buff_on_combatant_id(
        campaign_id, target_combatant_id, buff,
    )

    note = f"🤼 {char.name} grapples {target_name} (speed → 0)"
    if outcome == "grappler_won":
        note = (
            f"🤼 {char.name} grapples {target_name} "
            f"({attacker_total} vs {target_total} → grappler wins)"
        )
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "feature_name": "🤼 Grapple",
            "feature_desc": (
                f"{char.name} grapples {target_name}. "
                f"Target is Grappled: speed 0, can't benefit from "
                f"speed bonuses. Escape requires an action + STR "
                f"(Athletics) or DEX (Acrobatics) vs grappler's "
                f"STR (Athletics)."
            ),
            "source": "grapple-action",
            "target_combatant_id": target_combatant_id,
            "target_name": target_name,
            "speed_reduction_ft": buff["effects"]["speed_reduction_ft"],
            "outcome": outcome,
            "attacker_check_total": attacker_total,
            "target_check_total": target_total,
        },
    })
    await hub.broadcast(campaign_id, {
        "type": "roll",
        "data": {
            "expression": "",
            "total": 0,
            "breakdown": note,
            "note": note,
            "user_name": char.name,
            "char_name": char.name,
            "visibility": Visibility.PUBLIC.value,
        },
    })

    return {
        "ok": True,
        "outcome": outcome,
        "grappler_character_id": char.id,
        "grappler_name": char.name,
        "target_combatant_id": target_combatant_id,
        "target_name": target_name,
        "base_speed_walk": base_speed,
        "speed_reduction_ft": buff["effects"]["speed_reduction_ft"],
        "installed": installed,
        "duration_rounds": 10,
        "attacker_check_total": attacker_total,
        "target_check_total": target_total,
    }


# ----------- API: Escape Grapple action (PHB p.195) -----------

@router.post("/api/campaign/{campaign_id}/escape_grapple")
async def escape_grapple(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.114 — Use an action to escape a grapple.

    Body: ``{character_id, escapee_check_total?, grappler_check_total?,
    override?}``.

    RAW (PHB p.195): "A grappled creature can use its action to
    escape. To do so, it must succeed on a Strength (Athletics) or
    Dexterity (Acrobatics) check contested by the grappler's
    Strength (Athletics) check." The escapee chooses which ability
    to use; this endpoint doesn't gate on the choice — the GM does
    the rolls externally and passes both totals when the contested
    check should be auto-resolved.

    Body is the mirror of /use_grapple (v2.99.113):
      - When BOTH check totals are supplied, the server compares
        them. Escapee must strictly beat the grappler to break
        free (RAW: ties go to the contesting party = grappler).
      - When either is missing, the endpoint falls through to
        "legacy auto" mode: assumes the GM decided escape succeeds
        and removes the grappled buff unconditionally.

    Action economy fires regardless of outcome (RAW: the action
    was spent on the attempt). Validates the caller actually has
    the grappled buff (409 not_grappled if absent).
    """
    body = await request.json()
    char_id_raw = body.get("character_id")
    try:
        char_id = int(char_id_raw) if char_id_raw else 0
    except (TypeError, ValueError):
        char_id = 0
    override = bool(body.get("override"))
    escapee_total_raw = body.get("escapee_check_total")
    grappler_total_raw = body.get("grappler_check_total")

    if char_id <= 0:
        raise HTTPException(400, "character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Escapee not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    # Verify the caller has the grappled buff. Read from hub state
    # so we can also surface the grappler's identity in the audit.
    state = hub.get_battle(campaign_id)
    escapee_cb = None
    if state:
        for c in state.get("combatants") or []:
            if c.get("char_id") == char.id:
                escapee_cb = c
                break
    grappled_buff = None
    if escapee_cb:
        for b in (escapee_cb.get("buffs") or []):
            if (b or {}).get("key") == "grappled":
                grappled_buff = b
                break
    if not grappled_buff:
        return JSONResponse(status_code=409, content={
            "error": "not_grappled",
            "character_id": char.id,
        })

    # Parse + validate contested-check totals.
    escapee_total: int | None = None
    grappler_total: int | None = None
    if escapee_total_raw is not None and grappler_total_raw is not None:
        try:
            escapee_total = int(escapee_total_raw)
            grappler_total = int(grappler_total_raw)
        except (TypeError, ValueError):
            return JSONResponse(status_code=400, content={
                "error": "bad_check_totals",
                "escapee_check_total": str(escapee_total_raw),
                "grappler_check_total": str(grappler_total_raw),
            })

    if escapee_total is not None and grappler_total is not None:
        if escapee_total > grappler_total:
            outcome = "escaped"
        elif escapee_total < grappler_total:
            outcome = "still_grappled"
        else:
            outcome = "tie"  # RAW: contesting party (grappler) wins
    else:
        outcome = "auto"  # legacy path: always escape

    grappler_name = grappled_buff.get("source_char_name") or "Grappler"
    grappler_char_id = grappled_buff.get("source_char_id")

    # Action is spent on the attempt regardless of outcome.
    await _mark_battle_economy(campaign_id, char.id, "action")

    # On a failed escape, short-circuit + broadcast a "still
    # grappled" audit.
    if outcome in ("still_grappled", "tie"):
        outcome_copy = (
            "couldn't break free"
            if outcome == "still_grappled"
            else "tied — grappler holds by RAW"
        )
        note = (
            f"🤼 {char.name} fails to escape {grappler_name}'s grapple "
            f"({outcome_copy}: {escapee_total} vs {grappler_total})"
        )
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "character_name": char.name,
                "feature_name": "🤼 Escape Grapple (failed)",
                "feature_desc": note,
                "source": "escape-grapple-action",
                "outcome": outcome,
                "grappler_name": grappler_name,
                "grappler_char_id": grappler_char_id,
                "escapee_check_total": escapee_total,
                "grappler_check_total": grappler_total,
            },
        })
        await hub.broadcast(campaign_id, {
            "type": "roll",
            "data": {
                "expression": "",
                "total": 0,
                "breakdown": note,
                "note": note,
                "user_name": char.name,
                "char_name": char.name,
                "visibility": Visibility.PUBLIC.value,
            },
        })
        return {
            "ok": True,
            "outcome": outcome,
            "character_id": char.id,
            "character_name": char.name,
            "removed": False,
            "grappler_char_id": grappler_char_id,
            "grappler_name": grappler_name,
            "escapee_check_total": escapee_total,
            "grappler_check_total": grappler_total,
        }

    # Escape succeeded — remove the grappled buff.
    removed = await _remove_buff(campaign_id, char.id, "grappled")

    if outcome == "auto":
        note = f"🤼 {char.name} escapes {grappler_name}'s grapple"
    else:
        note = (
            f"🤼 {char.name} escapes {grappler_name}'s grapple "
            f"({escapee_total} vs {grappler_total} → escapee wins)"
        )
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "feature_name": "🤼 Escape Grapple",
            "feature_desc": (
                f"{char.name} breaks free of {grappler_name}'s grapple. "
                f"The Grappled condition ends."
            ),
            "source": "escape-grapple-action",
            "outcome": outcome,
            "grappler_name": grappler_name,
            "grappler_char_id": grappler_char_id,
            "escapee_check_total": escapee_total,
            "grappler_check_total": grappler_total,
        },
    })
    await hub.broadcast(campaign_id, {
        "type": "roll",
        "data": {
            "expression": "",
            "total": 0,
            "breakdown": note,
            "note": note,
            "user_name": char.name,
            "char_name": char.name,
            "visibility": Visibility.PUBLIC.value,
        },
    })

    return {
        "ok": True,
        "outcome": outcome,
        "character_id": char.id,
        "character_name": char.name,
        "removed": removed,
        "grappler_char_id": grappler_char_id,
        "grappler_name": grappler_name,
        "escapee_check_total": escapee_total,
        "grappler_check_total": grappler_total,
    }


# ----------- API: cast Hold Person (2nd-level Enchantment, concentration) -----------

@router.post("/api/campaign/{campaign_id}/cast_hold_person")
async def cast_hold_person(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.107 — Cast Hold Person on target combatants.

    Body: ``{character_id, class_slug, slot_level, target_combatant_ids,
    override?}``.

    RAW (PHB Hold Person, 2nd-level Enchantment): 1 action, 60 ft,
    concentration up to 1 minute, WIS save. Single-target at L2;
    each upcast level adds one more humanoid target. v1 ships the
    speed→0 (Paralyzed) effect via the v2.99.107 Paralyzed factory;
    other Paralyzed effects (incapacitated, can't speak, auto-fail
    STR/DEX saves, attacks have advantage, melee within 5 ft auto-
    crits) surface as `raw_effects` for GM narration.

    Save logic is a v1 simplification: caller passes the failed-
    save target list. The end-of-turn WIS save (RAW) isn't auto-
    fired today; mirror of the v2.97.62 end-of-turn save hook is
    filed.

    Classes that get Hold Person: Cleric, Bard, Sorcerer, Warlock,
    Wizard (one of the widest cross-class spells in 5e).

    Validation: caster has class + Hold Person on spell list +
    Lv 2+ slot + Phase 4 action gate. Mirrors /cast_slow + /cast_web.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    class_slug = (body.get("class_slug") or "").strip().lower()
    slot_level_raw = body.get("slot_level")
    slot_level = int(slot_level_raw) if slot_level_raw is not None else 2
    target_combatant_ids = body.get("target_combatant_ids") or []
    override = bool(body.get("override"))

    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if class_slug not in ("cleric", "bard", "sorcerer", "warlock", "wizard"):
        raise HTTPException(
            400,
            "class_slug must be cleric, bard, sorcerer, warlock, or wizard",
        )
    if slot_level < 2:
        raise HTTPException(
            400, "slot_level must be >= 2 (Hold Person is L2)",
        )
    if not isinstance(target_combatant_ids, list) or not target_combatant_ids:
        raise HTTPException(400, "target_combatant_ids must be a non-empty list")
    # RAW: 1 humanoid at L2, +1 per upcast level. L2 → 1, L3 → 2,
    # L4 → 3, etc. v2.127.0 — shared helper (was inlined as
    # `max(1, slot_level - 1)`).
    from ..content.spell_upcast_parse import upcast_target_count
    max_targets = upcast_target_count(slot_level, base_level=2)
    if len(target_combatant_ids) > max_targets:
        return JSONResponse(status_code=409, content={
            "error": "too_many_targets",
            "max": max_targets,
            "got": len(target_combatant_ids),
            "slot_level": slot_level,
        })

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Caster not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})

    primary_class = (sheet.get("class") or "").strip().lower()
    if primary_class != class_slug:
        has_class = any(
            (entry.get("class") or "").strip().lower() == class_slug
            for entry in (sheet.get("classes") or [])
        )
        if not has_class:
            return JSONResponse(status_code=409, content={
                "error": "wrong_class",
                "expected": class_slug,
                "got": primary_class or "",
            })

    spells = list(sheet.get("spells") or [])
    has_hp = any(
        (s.get("_slug") == "hold-person") or
        (str(s.get("name", "")).lower() == "hold person")
        for s in spells
    )
    if not has_hp:
        return JSONResponse(status_code=409, content={
            "error": "spell_not_known",
            "spell": "hold-person",
        })

    all_slots = dict(sheet.get("spell_slots") or {})
    per_class = dict(all_slots.get(class_slug) or {})
    slot = dict(per_class.get(str(slot_level)) or {"total": 0, "used": 0})
    total = int(slot.get("total") or 0)
    used = int(slot.get("used") or 0)
    if total <= 0 or used >= total:
        return JSONResponse(status_code=409, content={
            "error": "no_slot",
            "level": slot_level,
            "class_slug": class_slug,
            "spell_name": "Hold Person",
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "hold-person",
            "label": "Hold Person",
            "strict": strict,
        })

    slot["used"] = used + 1
    per_class[str(slot_level)] = slot
    all_slots[class_slug] = per_class
    sheet["spell_slots"] = all_slots
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # v2.99.109 — caster-side concentration anchor for paired cleanup.
    await _install_caster_concentration_anchor(
        campaign_id, char, "hold-person", "Hold Person",
        duration_rounds=10, icon="🥶",
    )

    # v2.99.181 — Twinned Spell auto-route. When the helper returns
    # a second target, append it to the install list so the
    # paralyzed buff lands on both targets. Single-target spells
    # like Hold Person are the canonical Twinned use case per RAW.
    _twin_target_2_hp = await _consume_twinned_for_second_target(
        campaign_id, int(char.id),
    )
    if _twin_target_2_hp and _twin_target_2_hp not in target_combatant_ids:
        target_combatant_ids = list(target_combatant_ids) + [_twin_target_2_hp]

    affected: list[dict] = []
    unaffected: list[dict] = []
    for tid in target_combatant_ids:
        if not isinstance(tid, str) or not tid:
            continue
        c = _lookup_combatant(campaign_id, tid)
        if not c:
            unaffected.append({"combatant_id": tid, "reason": "not_found"})
            continue
        _raw_speed = c.get("speed_walk")
        try:
            base_speed = int(_raw_speed) if _raw_speed is not None else 30
        except (TypeError, ValueError):
            base_speed = 30
        buff = _make_hold_person_paralyzed_buff(
            target_speed_walk=base_speed,
            source_char_id=char.id,
            source_char_name=char.name,
            spell_save_dc=_compute_spell_save_dc_from_sheet(sheet),
        )
        installed = await _install_buff_on_combatant_id(
            campaign_id, tid, buff,
        )
        affected.append({
            "combatant_id": tid,
            "name": c.get("name") or "",
            "base_speed_walk": base_speed,
            "speed_reduction_ft": buff["effects"]["speed_reduction_ft"],
            "installed": installed,
        })

    await _mark_battle_economy(campaign_id, char.id, "action")

    affected_summary = ", ".join(
        f"{a['name']} (Paralyzed)" for a in affected
    ) or "no one"
    note = f"🥶 Hold Person (L{slot_level}) → {affected_summary}"
    await hub.broadcast(campaign_id, {
        "type": "roll",
        "data": {
            "expression": "",
            "total": 0,
            "breakdown": (
                f"Hold Person installed on {len(affected)} target(s). "
                f"Concentration up to 1 min. Paralyzed: speed 0, "
                f"incapacitated, auto-fail STR/DEX saves, attacks have "
                f"advantage, melee within 5 ft auto-crits. WIS save at "
                f"end of each turn to break free."
            ),
            "note": note,
            "user_name": char.name,
            "char_name": char.name,
            "visibility": Visibility.PUBLIC.value,
        },
    })

    await hub.broadcast(campaign_id, {
        "type": "spell_slot_update",
        "data": {
            "character_id": char.id,
            "class_slug": class_slug,
            "level": slot_level,
            "total": total,
            "used": used + 1,
        },
    })

    # v2.99.462 — log the slot spend so the chat-card ↶ Undo refunds it.
    cast_id = _log_spell_slot_spend(
        campaign_id, char.id, class_slug, slot_level, used, "Hold Person")
    return {
        "ok": True,
        "cast_id": cast_id,
        "slot_level": slot_level,
        "slot_used": used + 1,
        "slot_total": total,
        "class_slug": class_slug,
        "affected": affected,
        "unaffected": unaffected,
        "duration_rounds": 10,  # 1 min
        "concentration": True,
        "max_targets": max_targets,
        # v2.99.181 — Twinned auto-route response field.
        "twinned_target_combatant_id_2": _twin_target_2_hp or None,
    }


# ----------- API: cast Flesh to Stone (6th-level Transmutation, concentration) -----------

@router.post("/api/campaign/{campaign_id}/cast_flesh_to_stone")
async def cast_flesh_to_stone(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.130 — Cast Flesh to Stone on a single target.

    Body: ``{character_id, class_slug, slot_level, target_combatant_id,
    stage?: "restrained" | "petrified", override?}``.

    RAW (PHB p.243): L6 Transmutation, 1 action, 60 ft, concentration
    up to 1 minute. CON save. On fail, target is Restrained as flesh
    hardens; CON save at end of each turn — 3 successes end the
    spell, 3 failures turn the target to stone (Petrified condition
    for the duration). v1 simplification: the endpoint takes a
    ``stage`` flag and installs ONE buff (Restrained OR Petrified)
    based on the caller's decision. The full staged 3-strikes flow
    requires a save-counter hook in the v2.97.62 framework — filed.
    GMs resolve the staged transitions manually today: cast with
    ``stage="restrained"``, then once 3 fails accumulate via
    `/use_repeated_save`, /end_buff the restrained and re-cast with
    ``stage="petrified"`` (no slot cost: pass ``override: true``).

    Classes: Wizard, Sorcerer (the v6.E version also exists for the
    Cleric Forge Domain at higher levels — out of scope today).
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    class_slug = (body.get("class_slug") or "").strip().lower()
    slot_level_raw = body.get("slot_level")
    slot_level = int(slot_level_raw) if slot_level_raw is not None else 6
    target_combatant_id = (body.get("target_combatant_id") or "").strip()
    stage = (body.get("stage") or "restrained").strip().lower()
    override = bool(body.get("override"))

    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if class_slug not in ("wizard", "sorcerer"):
        raise HTTPException(400, "class_slug must be wizard or sorcerer")
    if slot_level < 6:
        raise HTTPException(
            400, "slot_level must be >= 6 (Flesh to Stone is L6)",
        )
    if not target_combatant_id:
        raise HTTPException(400, "target_combatant_id is required")
    if stage not in ("restrained", "petrified"):
        raise HTTPException(
            400, 'stage must be "restrained" or "petrified"',
        )

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Caster not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})

    primary_class = (sheet.get("class") or "").strip().lower()
    if primary_class != class_slug:
        has_class = any(
            (entry.get("class") or "").strip().lower() == class_slug
            for entry in (sheet.get("classes") or [])
        )
        if not has_class:
            return JSONResponse(status_code=409, content={
                "error": "wrong_class",
                "expected": class_slug,
                "got": primary_class or "",
            })

    spells = list(sheet.get("spells") or [])
    has_fts = any(
        (s.get("_slug") == "flesh-to-stone") or
        (str(s.get("name", "")).lower() == "flesh to stone")
        for s in spells
    )
    if not has_fts:
        return JSONResponse(status_code=409, content={
            "error": "spell_not_known",
            "spell": "flesh-to-stone",
        })

    all_slots = dict(sheet.get("spell_slots") or {})
    per_class = dict(all_slots.get(class_slug) or {})
    slot = dict(per_class.get(str(slot_level)) or {"total": 0, "used": 0})
    total = int(slot.get("total") or 0)
    used = int(slot.get("used") or 0)
    if total <= 0 or used >= total:
        return JSONResponse(status_code=409, content={
            "error": "no_slot",
            "level": slot_level,
            "class_slug": class_slug,
            "spell_name": "Flesh to Stone",
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "flesh-to-stone",
            "label": "Flesh to Stone",
            "strict": strict,
        })

    # Resolve target.
    target = _lookup_combatant(campaign_id, target_combatant_id)
    if not target:
        return JSONResponse(status_code=404, content={
            "error": "target_not_found",
            "target_combatant_id": target_combatant_id,
        })

    # Commit slot decrement.
    slot["used"] = used + 1
    per_class[str(slot_level)] = slot
    all_slots[class_slug] = per_class
    sheet["spell_slots"] = all_slots
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # Caster-side concentration anchor.
    await _install_caster_concentration_anchor(
        campaign_id, char, "flesh-to-stone", "Flesh to Stone",
        duration_rounds=10, icon="🗿",
    )

    # v2.99.184 — Twinned Spell auto-route. Surfaces the second
    # target on the response. Per-target install on the second
    # target is filed (Flesh to Stone has staged Restrained →
    # Petrified progression; routing v1's stage flag to both
    # targets is non-trivial).
    _twin_target_2_fts = await _consume_twinned_for_second_target(
        campaign_id, int(char.id),
    )

    # Target speed + DC.
    _raw_speed = target.get("speed_walk")
    try:
        base_speed = int(_raw_speed) if _raw_speed is not None else 30
    except (TypeError, ValueError):
        base_speed = 30
    dc = _compute_spell_save_dc_from_sheet(sheet)

    if stage == "restrained":
        buff = _make_restrained_buff(
            target_speed_walk=base_speed,
            source_char_id=char.id,
            source_char_name=char.name,
            source="flesh-to-stone-spell",
            display_name="Restrained (Flesh to Stone)",
            icon="🪨",
            duration_rounds=10,
            concentration=True,
            source_specific_raw_effects=[
                "Stage 1 of Flesh to Stone — flesh hardening",
                "CON save at end of each turn; 3 successes end, "
                "3 fails → Petrified",
            ],
            repeated_save_ability="CON",
            repeated_save_dc=dc,
        )
        # v2.99.135 — strike-counter stamps for the staged RAW flow.
        # The v2.97.62 framework rolls the CON save at end of each
        # target turn; future engine wiring (filed) will read these
        # counters + auto-transition on 3 of either. v1 stamps the
        # fields so the GM UI can render the progress and a future
        # commit can implement the transition without changing the
        # data shape.
        buff["strike_counter"] = True
        buff["success_count"] = 0
        buff["failure_count"] = 0
        buff["strike_threshold"] = 3
    else:  # stage == "petrified"
        buff = _make_flesh_to_stone_petrified_buff(
            target_speed_walk=base_speed,
            source_char_id=char.id,
            source_char_name=char.name,
            spell_save_dc=dc,
        )

    installed = await _install_buff_on_combatant_id(
        campaign_id, target_combatant_id, buff,
    )

    await _mark_battle_economy(campaign_id, char.id, "action")

    target_name = target.get("name") or "Target"
    note = (
        f"🪨 {char.name} casts Flesh to Stone on {target_name} "
        f"(stage={stage}, DC {dc})"
    )
    await hub.broadcast(campaign_id, {
        "type": "roll",
        "data": {
            "expression": "",
            "total": 0,
            "breakdown": note,
            "note": note,
            "user_name": char.name,
            "char_name": char.name,
            "visibility": Visibility.PUBLIC.value,
        },
    })

    await hub.broadcast(campaign_id, {
        "type": "spell_slot_update",
        "data": {
            "character_id": char.id,
            "class_slug": class_slug,
            "level": slot_level,
            "total": total,
            "used": used + 1,
        },
    })

    # v2.99.463 — log the slot spend so the chat-card ↶ Undo refunds it.
    cast_id = _log_spell_slot_spend(
        campaign_id, char.id, class_slug, slot_level, used, "spell")
    return {
        "ok": True,
        "cast_id": cast_id,
        "slot_level": slot_level,
        "slot_used": used + 1,
        "slot_total": total,
        "class_slug": class_slug,
        "target_combatant_id": target_combatant_id,
        "target_name": target_name,
        "stage": stage,
        "save_dc": dc,
        "installed": installed,
        "duration_rounds": 10,
        "concentration": True,
        # v2.99.184 — Twinned auto-route response field.
        "twinned_target_combatant_id_2": _twin_target_2_fts or None,
    }


# ----------- API: Flesh to Stone — permanent petrification on sustained concentration -----------

@router.post("/api/campaign/{campaign_id}/use_flesh_to_stone_make_permanent")
async def use_flesh_to_stone_make_permanent(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.139 — Flip a Flesh to Stone Petrified buff from
    concentration-bonded to PERMANENT.

    Closes the v2.99.136 filed item. RAW (PHB p.243): "If you maintain
    your concentration on this spell for the entire possible duration,
    the creature is turned to stone until the effect is ended by a
    Greater Restoration spell or other magic." Today the Petrified buff
    has a 10-round duration_max bonded to the caster's concentration
    anchor — when the anchor drops, paired cleanup removes the
    Petrified buff. This endpoint is the GM-callable "10 rounds done,
    lock it in" trigger: drops the concentration link on the buff,
    stamps `permanent: True`, extends the duration to effectively
    forever, and cleanly drops the caster's concentration anchor
    WITHOUT triggering paired cleanup against the now-permanent buff
    (the anchor is removed surgically, not via the cascade).

    Body: ``{character_id, target_combatant_id}``.

    Validation:
      - character_id required (the caster)
      - target_combatant_id required
      - Target must have a Petrified buff sourced from
        ``"flesh-to-stone-spell"`` (409 no_flesh_to_stone_petrified)
      - Buff's source_char_id must match the caller (409 not_your_spell)

    After this fires, only Greater Restoration / Stone to Flesh / GM
    `/end_buff` removes the Petrified condition.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    target_combatant_id = (body.get("target_combatant_id") or "").strip()

    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if not target_combatant_id:
        raise HTTPException(400, "target_combatant_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Caster not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    state = hub.get_battle(campaign_id)
    if not state:
        return JSONResponse(status_code=409, content={
            "error": "no_active_battle",
        })

    target = None
    for c in state.get("combatants") or []:
        if c.get("id") == target_combatant_id:
            target = c
            break
    if target is None:
        return JSONResponse(status_code=404, content={
            "error": "target_not_found",
            "target_combatant_id": target_combatant_id,
        })

    # Find the Flesh to Stone Petrified buff.
    fts_buff = None
    for b in target.get("buffs") or []:
        if not isinstance(b, dict):
            continue
        if b.get("key") == "petrified" and b.get("source") == "flesh-to-stone-spell":
            fts_buff = b
            break
    if fts_buff is None:
        return JSONResponse(status_code=409, content={
            "error": "no_flesh_to_stone_petrified",
            "target_combatant_id": target_combatant_id,
        })

    # Caster must match the buff's source.
    buff_source_id = fts_buff.get("source_char_id")
    if buff_source_id is not None and int(buff_source_id) != int(char.id):
        return JSONResponse(status_code=409, content={
            "error": "not_your_spell",
            "expected_caster_id": buff_source_id,
        })

    # Mutate the buff in place to permanent.
    fts_buff["concentration"] = False
    fts_buff["_dependent_on_caster_concentration"] = False
    fts_buff["permanent"] = True
    fts_buff["duration_rounds"] = 100000
    fts_buff["duration_max"] = 100000
    raw = list(fts_buff.get("raw_effects") or [])
    raw.append(
        "PERMANENT — caster sustained concentration for full 1 minute "
        "(RAW). Cures: Greater Restoration or Stone to Flesh."
    )
    fts_buff["raw_effects"] = raw

    # Surgically drop the caster's concentration-flesh-to-stone anchor
    # WITHOUT going through paired cleanup (which would re-evaluate
    # concentration buffs; the FtS Petrified is now concentration:False
    # so it would survive, but we avoid the cascade to be safe).
    anchor_key = "concentration-flesh-to-stone"
    for c in state.get("combatants") or []:
        if c.get("char_id") != int(char.id):
            continue
        before = c.get("buffs") or []
        c["buffs"] = [
            b for b in before
            if not (isinstance(b, dict) and b.get("key") == anchor_key)
        ]
        break

    hub.set_battle(campaign_id, state)

    await hub.broadcast(campaign_id, {
        "type": "battle_update",
        "data": state,
        "force_gm_sync": True,
    })

    target_name = target.get("name") or "Target"
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": int(char.id),
            "character_name": char.name,
            "feature_name": "🗿 Flesh to Stone — Permanent",
            "feature_desc": (
                f"{char.name} sustained concentration for the full minute. "
                f"{target_name} is turned to stone permanently — only "
                f"Greater Restoration or Stone to Flesh will restore them."
            ),
            "source": "flesh-to-stone-permanent",
            "target_combatant_id": target_combatant_id,
            "target_name": target_name,
        },
    })

    return {
        "ok": True,
        "character_id": int(char.id),
        "character_name": char.name,
        "target_combatant_id": target_combatant_id,
        "target_name": target_name,
        "permanent": True,
        "concentration": False,
    }


# ----------- API: cast Hold Monster (5th-level Enchantment, concentration) -----------

@router.post("/api/campaign/{campaign_id}/cast_hold_monster")
async def cast_hold_monster(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.108 — Cast Hold Monster on target combatants.

    Body: ``{character_id, class_slug, slot_level, target_combatant_ids,
    override?}``.

    RAW (PHB Hold Monster, 5th-level Enchantment): 1 action, 90 ft,
    concentration up to 1 minute, WIS save. Any creature except
    Undead. Single-target at L5; each upcast level adds one more
    target. Mirror of `/cast_hold_person` (v2.99.107) — same
    Paralyzed factory + same upcast cap arithmetic + same
    validation chain, just different class list (no Cleric — Hold
    Monster isn't on the Cleric list) and L5 minimum slot.

    Classes that get Hold Monster: Bard, Sorcerer, Warlock, Wizard.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    class_slug = (body.get("class_slug") or "").strip().lower()
    slot_level_raw = body.get("slot_level")
    slot_level = int(slot_level_raw) if slot_level_raw is not None else 5
    target_combatant_ids = body.get("target_combatant_ids") or []
    override = bool(body.get("override"))

    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if class_slug not in ("bard", "sorcerer", "warlock", "wizard"):
        raise HTTPException(
            400,
            "class_slug must be bard, sorcerer, warlock, or wizard",
        )
    if slot_level < 5:
        raise HTTPException(
            400, "slot_level must be >= 5 (Hold Monster is L5)",
        )
    if not isinstance(target_combatant_ids, list) or not target_combatant_ids:
        raise HTTPException(400, "target_combatant_ids must be a non-empty list")
    # RAW: 1 creature at L5, +1 per upcast level. L5 → 1, L6 → 2,
    # L7 → 3, L8 → 4, L9 → 5. v2.127.0 — shared helper (was inlined as
    # `max(1, slot_level - 4)`).
    from ..content.spell_upcast_parse import upcast_target_count
    max_targets = upcast_target_count(slot_level, base_level=5)
    if len(target_combatant_ids) > max_targets:
        return JSONResponse(status_code=409, content={
            "error": "too_many_targets",
            "max": max_targets,
            "got": len(target_combatant_ids),
            "slot_level": slot_level,
        })

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Caster not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})

    primary_class = (sheet.get("class") or "").strip().lower()
    if primary_class != class_slug:
        has_class = any(
            (entry.get("class") or "").strip().lower() == class_slug
            for entry in (sheet.get("classes") or [])
        )
        if not has_class:
            return JSONResponse(status_code=409, content={
                "error": "wrong_class",
                "expected": class_slug,
                "got": primary_class or "",
            })

    spells = list(sheet.get("spells") or [])
    has_hm = any(
        (s.get("_slug") == "hold-monster") or
        (str(s.get("name", "")).lower() == "hold monster")
        for s in spells
    )
    if not has_hm:
        return JSONResponse(status_code=409, content={
            "error": "spell_not_known",
            "spell": "hold-monster",
        })

    all_slots = dict(sheet.get("spell_slots") or {})
    per_class = dict(all_slots.get(class_slug) or {})
    slot = dict(per_class.get(str(slot_level)) or {"total": 0, "used": 0})
    total = int(slot.get("total") or 0)
    used = int(slot.get("used") or 0)
    if total <= 0 or used >= total:
        return JSONResponse(status_code=409, content={
            "error": "no_slot",
            "level": slot_level,
            "class_slug": class_slug,
            "spell_name": "Hold Monster",
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "hold-monster",
            "label": "Hold Monster",
            "strict": strict,
        })

    slot["used"] = used + 1
    per_class[str(slot_level)] = slot
    all_slots[class_slug] = per_class
    sheet["spell_slots"] = all_slots
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # v2.99.184 — Twinned Spell auto-route. Hold Monster takes
    # target_combatant_ids (plural); append the second target to
    # the install list so the paralyzed buff lands on both.
    _twin_target_2_hm2 = await _consume_twinned_for_second_target(
        campaign_id, int(char.id),
    )
    if _twin_target_2_hm2 and _twin_target_2_hm2 not in target_combatant_ids:
        target_combatant_ids = list(target_combatant_ids) + [_twin_target_2_hm2]

    # v2.99.109 — caster-side concentration anchor for paired cleanup.
    await _install_caster_concentration_anchor(
        campaign_id, char, "hold-monster", "Hold Monster",
        duration_rounds=10, icon="🥶",
    )

    affected: list[dict] = []
    unaffected: list[dict] = []
    for tid in target_combatant_ids:
        if not isinstance(tid, str) or not tid:
            continue
        c = _lookup_combatant(campaign_id, tid)
        if not c:
            unaffected.append({"combatant_id": tid, "reason": "not_found"})
            continue
        _raw_speed = c.get("speed_walk")
        try:
            base_speed = int(_raw_speed) if _raw_speed is not None else 30
        except (TypeError, ValueError):
            base_speed = 30
        buff = _make_hold_monster_paralyzed_buff(
            target_speed_walk=base_speed,
            source_char_id=char.id,
            source_char_name=char.name,
            spell_save_dc=_compute_spell_save_dc_from_sheet(sheet),
        )
        installed = await _install_buff_on_combatant_id(
            campaign_id, tid, buff,
        )
        affected.append({
            "combatant_id": tid,
            "name": c.get("name") or "",
            "base_speed_walk": base_speed,
            "speed_reduction_ft": buff["effects"]["speed_reduction_ft"],
            "installed": installed,
        })

    await _mark_battle_economy(campaign_id, char.id, "action")

    affected_summary = ", ".join(
        f"{a['name']} (Paralyzed)" for a in affected
    ) or "no one"
    note = f"🥶 Hold Monster (L{slot_level}) → {affected_summary}"
    await hub.broadcast(campaign_id, {
        "type": "roll",
        "data": {
            "expression": "",
            "total": 0,
            "breakdown": (
                f"Hold Monster installed on {len(affected)} target(s). "
                f"Concentration up to 1 min. Paralyzed: speed 0, "
                f"incapacitated, auto-fail STR/DEX saves, attacks have "
                f"advantage, melee within 5 ft auto-crits. WIS save at "
                f"end of each turn to break free. Any creature except Undead."
            ),
            "note": note,
            "user_name": char.name,
            "char_name": char.name,
            "visibility": Visibility.PUBLIC.value,
        },
    })

    await hub.broadcast(campaign_id, {
        "type": "spell_slot_update",
        "data": {
            "character_id": char.id,
            "class_slug": class_slug,
            "level": slot_level,
            "total": total,
            "used": used + 1,
        },
    })

    # v2.99.463 — log the slot spend so the chat-card ↶ Undo refunds it.
    cast_id = _log_spell_slot_spend(
        campaign_id, char.id, class_slug, slot_level, used, "spell")
    return {
        "ok": True,
        "cast_id": cast_id,
        "slot_level": slot_level,
        "slot_used": used + 1,
        "slot_total": total,
        "class_slug": class_slug,
        "affected": affected,
        "unaffected": unaffected,
        "duration_rounds": 10,
        "concentration": True,
        "max_targets": max_targets,
        # v2.99.184 — Twinned auto-route response field.
        "twinned_target_combatant_id_2": _twin_target_2_hm2 or None,
    }


# ----------- API: cast Web (2nd-level Conjuration, concentration) -----------

@router.post("/api/campaign/{campaign_id}/cast_web")
async def cast_web(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.99.105 — Cast Web on target combatants in the AoE.

    Body: ``{character_id, class_slug, slot_level, target_combatant_ids,
    override?}``.

    RAW (PHB Web, 2nd-level Conjuration): 1 action, 60 ft range, 20-ft
    cube AoE, concentration up to 1 hour, DEX save. v1 ships the
    speed→0 effect (full base reduction so the v2.99.98 engine
    clamps effective speed to 0). Other Restrained effects
    (attack/save disadvantages, advantage to attackers) are surfaced
    as `raw_effects` tooltips for GM narration; mechanical
    enforcement is filed pending a standalone `restrained` condition
    buff.

    Save logic is a v1 simplification: caller passes the failed-save
    set as `target_combatant_ids`. Auto-rolled saves + the 20-ft
    cube AoE sweep can wire into this endpoint via /respond + a
    future cast-point coordinate; filed.

    Validation: caster has class + Web on spell list + Lv 2+ slot +
    Phase 4 action gate (overrideable). Mirrors /cast_slow.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    class_slug = (body.get("class_slug") or "").strip().lower()
    slot_level_raw = body.get("slot_level")
    slot_level = int(slot_level_raw) if slot_level_raw is not None else 2
    target_combatant_ids = body.get("target_combatant_ids") or []
    override = bool(body.get("override"))

    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if class_slug not in ("wizard", "sorcerer"):
        raise HTTPException(400, "class_slug must be wizard or sorcerer")
    if slot_level < 2:
        raise HTTPException(400, "slot_level must be >= 2 (Web is L2)")
    if not isinstance(target_combatant_ids, list) or not target_combatant_ids:
        raise HTTPException(400, "target_combatant_ids must be a non-empty list")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Caster not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})

    primary_class = (sheet.get("class") or "").strip().lower()
    if primary_class != class_slug:
        has_class = any(
            (entry.get("class") or "").strip().lower() == class_slug
            for entry in (sheet.get("classes") or [])
        )
        if not has_class:
            return JSONResponse(status_code=409, content={
                "error": "wrong_class",
                "expected": class_slug,
                "got": primary_class or "",
            })

    spells = list(sheet.get("spells") or [])
    has_web = any(
        (s.get("_slug") == "web") or
        (str(s.get("name", "")).lower() == "web")
        for s in spells
    )
    if not has_web:
        return JSONResponse(status_code=409, content={
            "error": "spell_not_known",
            "spell": "web",
        })

    all_slots = dict(sheet.get("spell_slots") or {})
    per_class = dict(all_slots.get(class_slug) or {})
    slot = dict(per_class.get(str(slot_level)) or {"total": 0, "used": 0})
    total = int(slot.get("total") or 0)
    used = int(slot.get("used") or 0)
    if total <= 0 or used >= total:
        return JSONResponse(status_code=409, content={
            "error": "no_slot",
            "level": slot_level,
            "class_slug": class_slug,
            "spell_name": "Web",
        })

    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "web",
            "label": "Web",
            "strict": strict,
        })

    # Commit slot decrement.
    slot["used"] = used + 1
    per_class[str(slot_level)] = slot
    all_slots[class_slug] = per_class
    sheet["spell_slots"] = all_slots
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # v2.99.109 — caster-side concentration anchor. Web's duration
    # is up to 1 hour (600 rounds at 6 s / round); the anchor
    # carries that so /end_buff timing matches.
    await _install_caster_concentration_anchor(
        campaign_id, char, "web", "Web",
        duration_rounds=600, icon="🕸",
    )

    affected: list[dict] = []
    unaffected: list[dict] = []
    for tid in target_combatant_ids:
        if not isinstance(tid, str) or not tid:
            continue
        c = _lookup_combatant(campaign_id, tid)
        if not c:
            unaffected.append({"combatant_id": tid, "reason": "not_found"})
            continue
        _raw_speed = c.get("speed_walk")
        try:
            base_speed = int(_raw_speed) if _raw_speed is not None else 30
        except (TypeError, ValueError):
            base_speed = 30
        buff = _make_web_buff(
            target_speed_walk=base_speed,
            source_char_id=char.id,
            source_char_name=char.name,
            spell_save_dc=_compute_spell_save_dc_from_sheet(sheet),
        )
        installed = await _install_buff_on_combatant_id(
            campaign_id, tid, buff,
        )
        affected.append({
            "combatant_id": tid,
            "name": c.get("name") or "",
            "base_speed_walk": base_speed,
            "speed_reduction_ft": buff["effects"]["speed_reduction_ft"],
            "installed": installed,
        })

    await _mark_battle_economy(campaign_id, char.id, "action")

    affected_summary = ", ".join(
        f"{a['name']} (speed → 0)" for a in affected
    ) or "no one"
    note = f"🕸 Web (L{slot_level}) → {affected_summary}"
    await hub.broadcast(campaign_id, {
        "type": "roll",
        "data": {
            "expression": "",
            "total": 0,
            "breakdown": (
                f"Web installed on {len(affected)} target(s). "
                f"Concentration up to 1 hour. Restrained (speed 0, "
                f"attack/save disadvantages — GM narrate). "
                f"STR (Athletics) check to break free."
            ),
            "note": note,
            "user_name": char.name,
            "char_name": char.name,
            "visibility": Visibility.PUBLIC.value,
        },
    })

    await hub.broadcast(campaign_id, {
        "type": "spell_slot_update",
        "data": {
            "character_id": char.id,
            "class_slug": class_slug,
            "level": slot_level,
            "total": total,
            "used": used + 1,
        },
    })

    # v2.99.463 — log the slot spend so the chat-card ↶ Undo refunds it.
    cast_id = _log_spell_slot_spend(
        campaign_id, char.id, class_slug, slot_level, used, "spell")
    return {
        "ok": True,
        "cast_id": cast_id,
        "slot_level": slot_level,
        "slot_used": used + 1,
        "slot_total": total,
        "class_slug": class_slug,
        "affected": affected,
        "unaffected": unaffected,
        "duration_rounds": 600,  # 1 hour
        "concentration": True,
    }


# ----------- API: shake a sleeping creature awake (RAW Sleep wake action) -----------

@router.post("/api/campaign/{campaign_id}/shake_awake")
async def shake_awake(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Use an action to shake a Sleep'd creature awake.

    Body: ``{character_id, target_combatant_id?, target_character_id?,
    target_name?, override?}``.

    RAW (PHB Sleep): "each creature affected by this spell falls
    unconscious until the spell ends, the sleeper takes damage, OR
    SOMEONE USES AN ACTION TO SHAKE OR SLAP THE SLEEPER AWAKE." This
    endpoint covers the third branch. No class restriction — RAW
    "someone" means any creature can do it. Costs 1 action.

    Validates:
      - target has a Sleep-sourced Unconscious buff (key=`unconscious`
        AND source_spell=`Sleep`). Other Unconscious sources (a
        dying-at-0-HP creature, a future Knockout feature, etc.) are
        not in scope — shaking a dying character doesn't wake them
        RAW. 409 ``not_asleep`` otherwise.
      - Phase 4 action gate. 409 ``over_budget`` when the shaker's
        action chip is already burnt + they're not the GM + ``override``
        is False (or strict_action_economy is on).

    On success:
      - Removes the Unconscious buff (PC: ``_remove_buff`` + sheet
        mirror; NPC: hub-state mutation + ``battle_update``).
      - Marks the shaker's action slot.
      - Emits a public 🤚 roll-log entry so the table sees the wake.
      - Returns ``{ok, target_name, action_used: True}``.

    No range check today — SimpleVTT doesn't enforce spatial range
    yet (see docs/plans/ruler-and-range.md). The future range-
    enforcement Phase 2 will add a 5-ft melee check here.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    target_combatant_id = (body.get("target_combatant_id") or "").strip()
    target_character_id_in = body.get("target_character_id")
    if target_character_id_in is not None:
        target_character_id_in = int(target_character_id_in)
    target_name_in = (body.get("target_name") or "").strip()
    override = bool(body.get("override"))

    if char_id <= 0:
        raise HTTPException(400, "character_id is required")
    if not target_combatant_id and not target_character_id_in:
        raise HTTPException(400, "target_combatant_id or target_character_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Shaker character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    # Resolve target.
    target_combatant = (
        _lookup_combatant(campaign_id, target_combatant_id)
        if target_combatant_id else None
    )
    if not target_combatant and target_character_id_in:
        # PC fallback — synthesize a combatant dict so the buff check
        # can run via the hub state (PC buffs live there, not on the
        # character sheet during combat).
        state = hub.get_battle(campaign_id) or {}
        for c in state.get("combatants") or []:
            if c.get("char_id") == target_character_id_in:
                target_combatant = c
                break
        if not target_combatant:
            target_combatant = {
                "char_id": target_character_id_in,
                "id": target_combatant_id or "",
                "name": target_name_in or "",
                "buffs": [],
            }
    if not target_combatant:
        raise HTTPException(404, "Target combatant not found")

    # v2.99.0 — generic wakeable-by-action gate (was hardcoded
    # ``source_spell == "Sleep"`` pre-v2.99.0).
    target_buffs = list(target_combatant.get("buffs") or [])
    sleep_buff_keys = [
        b.get("key") for b in target_buffs
        if _buff_is_wakeable_by_action(b or {})
    ]
    if not sleep_buff_keys:
        return JSONResponse(status_code=409, content={
            "error": "not_asleep",
            "target_name": target_combatant.get("name") or "",
            "reason": "target has no wakeable-by-action buff",
        })

    # Phase 4 over-budget gate (action slot).
    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    effective_override = override and not strict
    if was_used and not user_is_gm and not effective_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "shake_awake",
            "label": "Shake Awake",
            "strict": strict,
        })

    # Remove the Sleep-Unconscious buff(s).
    target_char_id = target_combatant.get("char_id")
    removed_count = 0
    if target_char_id:
        # PC path.
        for key in sleep_buff_keys:
            if await _remove_buff(campaign_id, int(target_char_id), key):
                removed_count += 1
        if removed_count:
            _mirror_buffs_to_sheet(
                db, int(target_char_id),
                _get_buffs(campaign_id, int(target_char_id)),
            )
    else:
        # NPC path — mutate hub combatant buff list directly.
        state = hub.get_battle(campaign_id)
        if state:
            for c in state.get("combatants") or []:
                if c.get("id") != target_combatant.get("id"):
                    continue
                new_list = [
                    b for b in (c.get("buffs") or [])
                    if not _buff_is_wakeable_by_action(b or {})
                ]
                if len(new_list) != len(c.get("buffs") or []):
                    removed_count = len(c.get("buffs") or []) - len(new_list)
                    c["buffs"] = new_list
                    hub.set_battle(campaign_id, state)
                    await hub.broadcast(campaign_id, {
                        "type": "battle_update",
                        "data": state,
                        "force_gm_sync": True,
                    })
                break

    # Mark the action slot.
    await _mark_battle_economy(campaign_id, char.id, "action")

    # Public wake log.
    target_name = target_combatant.get("name") or "Unknown"
    await hub.broadcast(campaign_id, {
        "type": "roll",
        "data": {
            "expression": "—",
            "total": 0,
            "breakdown": (
                f"Action: shake {target_name} awake — Sleep ends "
                f"(RAW PHB Sleep)"
            ),
            "note": f"🤚 {char.name} shakes {target_name} awake",
            "user_name": char.name,
            "char_name": char.name,
            "visibility": Visibility.PUBLIC.value,
        },
    })

    return {
        "ok": True,
        "target_name": target_name,
        "action_used": True,
        "buffs_removed": removed_count,
    }


# ----------- API: get a character's current action-economy state -----------
#
# Phase 4a (v2.7.2) Layer A dimming: the full character sheet polls
# this endpoint every few seconds to learn which slots are already
# spent, so action / spell / feature buttons whose slot is used can be
# rendered with 50% opacity + cursor:not-allowed + a title="" hint
# before the player even clicks. The 409 over_budget gate on
# /use_attack, /cast_spell, /use_feature, /use_item still fires on a
# click — Layer A is purely the pre-emptive visual cue. Polling rather
# than WS to keep the sheet page free of WS infrastructure for now;
# 4-second cadence × 3-5 sheets open = trivial load.

@router.get("/api/campaign/{campaign_id}/character/{character_id}/economy")
def get_character_economy(
    campaign_id: int,
    character_id: int,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Return the current action-economy state for one character.

    Shape: ``{battle_active, action, bonus, reaction, movement, speed_walk,
    potions_as_bonus_action}``. When no battle is active or the
    character isn't in init, the chip booleans are False / 0 and
    ``battle_active`` is False — the sheet treats that as "nothing is
    spent; don't dim anything." The ``potions_as_bonus_action`` flag is
    echoed so the sheet can decide whether to dim 🧪 Use on heal
    potions independently of the chip state (used only when Bns is
    already spent).
    """
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == character_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    state = hub.get_battle(campaign_id)
    base = {
        "battle_active": False,
        "action": False, "bonus": False, "reaction": False,
        "movement": 0.0,
        "speed_walk": 30,
        "potions_as_bonus_action": bool(campaign.potions_as_bonus_action),
    }
    if not state:
        return base
    active = bool(state.get("active"))
    base["battle_active"] = active
    if not active:
        return base
    for c in state.get("combatants") or []:
        if c.get("char_id") == character_id:
            economy = c.get("economy") or {}
            base["action"] = bool(economy.get("action"))
            base["bonus"] = bool(economy.get("bonus"))
            base["reaction"] = bool(economy.get("reaction"))
            base["movement"] = float(economy.get("movement") or 0)
            sw = c.get("speed_walk")
            if isinstance(sw, (int, float)) and sw > 0:
                base["speed_walk"] = int(sw)
            return base
    return base


# ----------- Death save state machine (v2.1.0) -----------
#
# 5e death saving throws: when a character drops to 0 HP they enter the
# "dying" state and roll a d20 each turn. 10+ = success, <10 = failure;
# 3 successes → stable, 3 failures → dead. Natural 20 regains 1 HP +
# wakes them up; natural 1 counts as two failures. Damage while at 0 HP
# auto-ticks a failure (two on a crit); damage that exceeds max HP at 0
# is instant death (massive damage rule).
#
# Every endpoint that mutates ``Character.sheet["hp"]["current"]`` MUST
# route through ``_apply_hp_change`` so the state machine stays in
# lockstep with HP. Direct ``sheet["hp"]["current"] = …`` assignments
# bypass the machine and leave the character in an inconsistent state.

# Valid death save status values. Kept as a constant so the override and
# stabilize endpoints can validate against the same set.
_DEATH_SAVE_STATUSES = ("alive", "dying", "stable", "dead")


def _apply_hp_change(
    char: Character,
    new_current: int,
    *,
    is_damage: bool = False,
    is_crit: bool = False,
    damage_amount: int = 0,
) -> dict:
    """Set ``Character.sheet["hp"]["current"]`` to ``new_current`` and run
    the death save state machine. The single source of truth for HP
    transitions in v2.1.0+.

    Args:
        char: The Character row to mutate (modified in-place).
        new_current: Target HP value after the change. Clamped at 0.
        is_damage: True if the change is a damage source. Enables the
            damage-at-0 auto-failure tick and the massive-damage rule.
            Callers that just *set* HP (manual sheet save, GM edit, /heal)
            should leave this False.
        is_crit: True for critical-hit damage. Ticks two failures instead
            of one when applied to a dying character.
        damage_amount: Raw damage value applied this event (before temp
            HP absorption). Used to evaluate the massive-damage threshold.

    Returns:
        A dict with the post-mutation state for the caller to echo back
        and broadcast:
            - hp: {current, max, temp}
            - death_saves: {status, successes, failures}
            - status_changed: bool
            - became_dying / became_dead: bool flags for the caller
              to surface in the log / toast
    """
    sheet = dict(char.sheet or {})
    hp = dict(sheet.get("hp") or {})
    ds = dict(sheet.get("death_saves") or {})

    max_hp = int(hp.get("max") or 0)
    old_current = int(hp.get("current") or 0)
    old_status = ds.get("status") or "alive"
    successes = int(ds.get("successes") or 0)
    failures = int(ds.get("failures") or 0)

    new_status = old_status
    became_dying = False
    became_dead = False
    relentless_endurance_fired = False
    relentless_endurance_damage = 0
    # v2.99.202 — Phase F.1 cont'd: Relentless Rage trigger flags.
    relentless_rage_fired = False
    relentless_rage_passed = False
    relentless_rage_dc = 0
    relentless_rage_save_total = 0

    new_current = max(0, int(new_current))

    if new_current > 0:
        # HP positive — healing or set. Wake from any non-alive state.
        # v2.1.1: this includes "dead" — healing auto-revives. The earlier
        # design ("dead stays dead, GM override required") proved confusing
        # in practice: the user healing a character is usually the GM, and
        # forcing them through a second action to clear the dead flag was
        # unhelpful. If a table wants strict revivify-spell semantics they
        # can keep the character at 0 HP and use the override to mark them
        # alive at 1 HP rather than healing them through it.
        if old_status in ("dying", "stable", "dead"):
            new_status = "alive"
            successes = 0
            failures = 0
    else:
        # new_current == 0
        if old_status == "alive":
            # Crossing into 0 HP. Massive-damage rule: if remaining
            # damage past 0 ≥ max_hp, instant death.
            if is_damage and max_hp > 0:
                remaining = max(0, damage_amount - old_current)
                if remaining >= max_hp:
                    new_status = "dead"
                    became_dead = True
                    successes = 0
                    failures = 0
                # v2.99.17 — Half-Orc Relentless Endurance auto-fire.
                # RAW: "reduced to 0 HP but not killed outright" → drop
                # to 1 HP instead. The massive-damage check above
                # gates "not killed outright" (if remaining ≥ max_hp,
                # instant death takes priority). Available 1/long
                # rest via the `relentless-endurance` resource.
                elif _pc_has_relentless_endurance_available(sheet):
                    new_current = 1
                    _decrement_relentless_endurance(sheet)
                    relentless_endurance_fired = True
                    relentless_endurance_damage = damage_amount
                    # Stay alive; don't tick death-save state.
                    new_status = "alive"
                # v2.99.202 — Phase F.1 cont'd: Relentless Rage
                # (Barbarian Lv 11+). RAW PHB p.49: when raging
                # and reduced to 0 HP but not killed outright,
                # CON save vs DC 10 (escalates +5 per use, resets
                # on short/long rest). On success: clamp HP to 1.
                # Composes after Relentless Endurance — a Half-Orc
                # Barbarian Lv 11+ would use RE first (no-roll), and
                # RR only as a fallback if RE is spent. Sheet
                # mutated in-place by `_maybe_relentless_rage_save`
                # (DC bumps +5 each fire).
                elif _pc_has_relentless_rage_available(sheet):
                    passed, dc_used, total, _con_mod = (
                        _maybe_relentless_rage_save(sheet)
                    )
                    relentless_rage_fired = True
                    relentless_rage_passed = passed
                    relentless_rage_dc = dc_used
                    relentless_rage_save_total = total
                    if passed:
                        new_current = 1
                        new_status = "alive"
                    else:
                        new_status = "dying"
                        became_dying = True
                        successes = 0
                        failures = 0
                else:
                    new_status = "dying"
                    became_dying = True
                    successes = 0
                    failures = 0
            else:
                # Non-damage set to 0 (manual edit). Treat as dying with
                # zero counters; no auto-failure.
                new_status = "dying"
                became_dying = True
                successes = 0
                failures = 0
        elif old_status == "dying":
            if is_damage:
                # Per RAW: any damage at 0 HP = 1 failure (2 on crit);
                # damage_amount ≥ max_hp = instant death.
                if max_hp > 0 and damage_amount >= max_hp:
                    new_status = "dead"
                    became_dead = True
                    successes = 0
                    failures = 0
                else:
                    failures += 2 if is_crit else 1
                    if failures >= 3:
                        new_status = "dead"
                        became_dead = True
                        successes = 0
                        failures = 0
        elif old_status == "stable":
            if is_damage:
                # Damage to a stable character drops them back to dying
                # with an immediate failure tick.
                if max_hp > 0 and damage_amount >= max_hp:
                    new_status = "dead"
                    became_dead = True
                    successes = 0
                    failures = 0
                else:
                    new_status = "dying"
                    became_dying = True
                    failures = 2 if is_crit else 1
                    successes = 0
        # ``dead`` stays dead until GM override.

    hp["current"] = new_current
    hp.setdefault("max", 0)
    hp.setdefault("temp", 0)
    ds["status"] = new_status
    ds["successes"] = successes
    ds["failures"] = failures

    sheet["hp"] = hp
    sheet["death_saves"] = ds
    char.sheet = sheet

    return {
        "hp": hp,
        "death_saves": ds,
        "status_changed": new_status != old_status,
        "became_dying": became_dying,
        "became_dead": became_dead,
        # v2.99.17 — Relentless Endurance trigger flags. Callers
        # broadcast the feature_used event when fired.
        "relentless_endurance_fired": relentless_endurance_fired,
        "relentless_endurance_damage": relentless_endurance_damage,
        # v2.99.202 — Relentless Rage trigger flags.
        "relentless_rage_fired": relentless_rage_fired,
        "relentless_rage_passed": relentless_rage_passed,
        "relentless_rage_dc": relentless_rage_dc,
        "relentless_rage_save_total": relentless_rage_save_total,
    }


def _set_death_save_state(
    char: Character,
    *,
    status: str | None = None,
    successes: int | None = None,
    failures: int | None = None,
) -> dict:
    """Manually patch parts of the death save state without touching HP.
    Used by the GM override + stabilize endpoints. Returns the updated
    ``death_saves`` dict for the caller to broadcast."""
    sheet = dict(char.sheet or {})
    ds = dict(sheet.get("death_saves") or {"status": "alive", "successes": 0, "failures": 0})
    if status is not None:
        ds["status"] = status
    if successes is not None:
        ds["successes"] = max(0, int(successes))
    if failures is not None:
        ds["failures"] = max(0, int(failures))
    sheet["death_saves"] = ds
    char.sheet = sheet
    return ds


async def _drop_caster_concentration(
    campaign_id: int, character_id: int, *,
    reason: str = "incapacitated",
) -> int:
    """Drop every concentration-tagged buff the character is holding.
    Reuses ``_remove_buff`` which handles the buff_update broadcast +
    ``_drop_paired_concentration_buffs`` cascade for target-side
    condition cleanup.

    v2.49.49 — used by the death-save endpoints to enforce the RAW
    "incapacitated → lose concentration" rule on paths that DON'T go
    through ``_maybe_concentration_save`` (which the v2.49.48 fix
    covered). Specifically: rolling 3 death-save failures → dead,
    or GM override to a non-alive status. The damage-event path
    already drops concentration via the v2.49.48 fix, so this
    helper is purely defensive for the rare non-damage transition
    into incapacitation.

    v2.49.50 — also emits a 💀 GM-only roll-log entry for each buff
    dropped, mirroring the v2.39.0 💔 failed-save log shape. The
    ``reason`` param flows into the log breakdown so the GM can tell
    "incapacitated (3 failed death saves)" from "incapacitated (GM
    override)" at a glance.

    v2.49.51 — filters concentration buffs by ``source_char_id``. A
    buff with ``concentration: True`` on a combatant might be (a)
    the combatant's own concentration anchor (e.g. Hex on the caster
    — source is self or absent) or (b) a paired condition sustained
    by ANOTHER caster's concentration (e.g. Paralyzed on a Hold
    Person victim — source is the enemy caster). Only (a) should
    drop when THIS character is incapacitated; (b) is the source
    caster's concern and drops when THEY lose concentration via
    ``_drop_paired_concentration_buffs``. Without this filter the
    new v2.49.51 incapacitation hook would drop the just-installed
    Paralyzed buff right back off.

    Returns the number of buffs removed.
    """
    state = hub.get_battle(campaign_id)
    if not state:
        return 0
    target = None
    for c in state.get("combatants") or []:
        if c.get("char_id") == character_id:
            target = c
            break
    if target is None:
        return 0
    caster_name = target.get("name") or "Unknown"
    # Snapshot (key, name, paired-pre-drop list) for every concentration
    # buff BEFORE calling _remove_buff — the helper mutates state in
    # place, and the paired-buff cascade fires during removal so the
    # paired list would be empty if we read it after.
    drops: list[tuple[str, str, list[dict]]] = []
    for b in target.get("buffs") or []:
        b = b or {}
        if not b.get("concentration"):
            continue
        # v2.49.51: skip paired condition buffs sustained by another
        # caster. The combatant isn't concentrating on those; their
        # source caster is.
        src = b.get("source_char_id")
        if src is not None and src != character_id:
            continue
        key = b.get("key")
        if not key:
            continue
        buff_name = b.get("name") or key
        paired_pre_drop: list[dict] = []
        for c in state.get("combatants") or []:
            for pb in c.get("buffs") or []:
                pb = pb or {}
                if (
                    pb.get("source_char_id") == character_id
                    and bool(pb.get("concentration"))
                    and pb.get("key") != key
                ):
                    paired_pre_drop.append({
                        "combatant_name": c.get("name") or "Unknown",
                        "buff_name": pb.get("name") or pb.get("key") or "Effect",
                    })
        drops.append((key, buff_name, paired_pre_drop))

    removed_count = 0
    for key, buff_name, paired in drops:
        if not await _remove_buff(campaign_id, character_id, key):
            continue
        removed_count += 1
        if paired:
            paired_summary = " · ".join(
                f"{p['buff_name']} → {p['combatant_name']}"
                for p in paired
            )
            paired_note = f" — dropped: {paired_summary}"
        else:
            paired_note = ""
        await hub.broadcast(campaign_id, {
            "type": "roll",
            "data": {
                "expression": "—",
                "total": 0,
                "breakdown": f"Concentration ends — {reason}",
                "note": (
                    f"💀 {caster_name} lost concentration on {buff_name}"
                    f"{paired_note}"
                ),
                "visibility": Visibility.GM_ONLY.value,
                "user_id": None,
                "user_name": "GM log",
                "char_name": caster_name,
            },
        })
    return removed_count


# ----------- Roll-state (advantage/disadvantage) — v2.2.0 -----------
#
# Per-character "roll state" toggled via the tri-state pill on the
# mini-sheet / full sheet. When set, the server upgrades single-d20
# expressions sent through /roll and /attack to 2d20kh1 (advantage) or
# 2d20kl1 (disadvantage) before rolling. Manual buttons that produce
# 2d20kh1 / 2d20kl1 directly bypass the auto-upgrade (the regex only
# matches single-d20). See docs/plans/advantage-disadvantage.md.

# Matches exactly a single 1d20 with optional +N/-N modifiers and
# whitespace. Rejects 1d20a / 1d20d (manual shorthand), 2d20kh1/kl1
# (manual long form), and any multi-dice expression (damage, ability
# gen, etc.). Group 1 captures the trailing modifier string.
_SINGLE_D20_RE = _re.compile(
    r'^\s*1d20((?:\s*[+-]\s*\d+)*)\s*$',
    _re.IGNORECASE,
)

# Manual adv/dis detection in the *submitted* expression (before any
# server upgrade). Matches both the long form (2d20kh1 / 2d20kl1) and
# the shorthand (1d20a / 1d20d) that dice.py expands.
_MANUAL_ADV_RE = _re.compile(r'(?i)\b(?:2d20kh1|1d20a)\b')
_MANUAL_DIS_RE = _re.compile(r'(?i)\b(?:2d20kl1|1d20d)\b')


def _apply_roll_state(
    expression: str,
    roll_state: dict | None,
) -> tuple[str, str]:
    """Upgrade a single-d20 expression to 2d20kh1 (advantage) or 2d20kl1
    (disadvantage) per the character's stored ``roll_state.value``.

    Returns ``(new_expression, applied)`` where ``applied`` is:

    - ``"auto_advantage"`` / ``"auto_disadvantage"`` — server upgraded
    - ``"manual_advantage"`` / ``"manual_disadvantage"`` — caller submitted
      a manual 2d20kh1 / 1d20a / 2d20kl1 / 1d20d expression
    - ``""`` — no upgrade and no manual flag

    Manual takes precedence over auto: if the submitted expression is
    already adv/dis, ``new_expression`` is the original and ``applied``
    reflects the manual form.
    """
    expr = expression or ""

    # 1) Detect manual adv/dis on the original expression first. If
    # the caller explicitly picked adv/dis, that wins — we don't double
    # up, and we tag the log with "manual ...".
    if _MANUAL_ADV_RE.search(expr):
        return expr, "manual_advantage"
    if _MANUAL_DIS_RE.search(expr):
        return expr, "manual_disadvantage"

    # 2) Auto upgrade only when the character has a roll_state set AND
    # the expression is a single-d20 form.
    value = None
    if isinstance(roll_state, dict):
        value = roll_state.get("value")
    if value not in ("advantage", "disadvantage"):
        return expr, ""

    m = _SINGLE_D20_RE.match(expr)
    if not m:
        return expr, ""
    modifiers = m.group(1) or ""
    if value == "advantage":
        return "2d20kh1" + modifiers, "auto_advantage"
    return "2d20kl1" + modifiers, "auto_disadvantage"


def _roll_state_note_suffix(applied: str) -> str:
    """Human-readable tag for ``applied`` from _apply_roll_state, suitable
    for appending to the roll's ``note`` field. Empty string for no-op."""
    return {
        "auto_advantage":     " (auto advantage)",
        "auto_disadvantage":  " (auto disadvantage)",
        "manual_advantage":   " (manual advantage)",
        "manual_disadvantage":" (manual disadvantage)",
    }.get(applied, "")


# ----------- API: apply healing from roll-log card -----------

@router.post("/api/campaign/{campaign_id}/apply_healing")
async def apply_healing(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Roll healing dice for a spell cast and apply the result to the calling
    user's character.  For AOE spells each user may only claim once; the
    charge counter is enforced server-side via ``_heal_claims``."""
    body = await request.json()
    cast_id = str(body.get("cast_id") or "")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    claim = _heal_claims.get(cast_id)
    if not claim or claim["campaign_id"] != campaign_id:
        # v2.26.2 fix: when v2.26.0 Phase T.4 auto-applied the heal to
        # the targeted ally, the claim was popped server-side but a
        # cached chat card might still render the legacy "🩹 Apply
        # Healing" button. Detect this by checking the damage-log for
        # a matching is_heal entry, and return a friendly 200 instead
        # of the alarming "expired" 404.
        _purge_attack_damage_log()
        # v2.65.0: log shape changed to list[dict]. Detect "already
        # auto-applied" by walking entries for an is_heal record
        # matching this campaign.
        log_entries = _attack_damage_log.get(cast_id) or []
        heal_entry = next(
            (e for e in log_entries
             if isinstance(e, dict)
             and e.get("is_heal")
             and e.get("campaign_id") == campaign_id),
            None,
        )
        if heal_entry:
            return {
                "ok": True,
                "already_auto_applied": True,
                "applied": int(heal_entry.get("applied") or 0),
                "message": "Heal was already auto-applied to the targeted ally — use ↶ Undo to revert.",
            }
        raise HTTPException(404, "Unknown spell cast — it may have expired")

    claimed: set = claim["claimed"]
    max_targets: int = claim["max_targets"]

    if user.id in claimed:
        raise HTTPException(409, "You have already claimed healing from this spell")
    if max_targets > 1 and len(claimed) >= max_targets:
        raise HTTPException(409, "All healing charges have been used")

    # v2.27.1: route the heal to the cast's intended target if the
    # claim carries one (stored at registration time from cast_spell's
    # target descriptors). This is the right behavior for almost every
    # caller: the GM clicking "Apply Healing" on a Tavik → Krieger
    # cast expects Krieger to be healed, not the GM's first owned PC.
    # Fall back to "first character owned by calling user" only when
    # the claim has no stored target (truly self-claim flow, like
    # Mass Healing Word AoE with no specific target).
    char = None
    stored_target_char_id = claim.get("target_character_id")
    if stored_target_char_id:
        char = db.query(Character).filter(
            Character.id == int(stored_target_char_id),
            Character.campaign_id == campaign_id,
        ).first()
    if not char:
        stored_target_combatant_id = claim.get("target_combatant_id")
        if stored_target_combatant_id:
            target_combatant = _lookup_combatant(campaign_id, stored_target_combatant_id)
            if target_combatant and target_combatant.get("char_id"):
                char = db.query(Character).filter(
                    Character.id == int(target_combatant["char_id"]),
                    Character.campaign_id == campaign_id,
                ).first()
    if not char:
        # Fallback: calling user's first owned PC in the campaign.
        char = (
            db.query(Character)
            .filter(Character.campaign_id == campaign_id, Character.owner_user_id == user.id)
            .first()
        )
    if not char:
        raise HTTPException(404, "No target character resolved for this heal claim")

    # Roll the healing dice server-side
    try:
        r = dice_mod.roll(claim["dice"])
        rolled = r.total
        breakdown = r.breakdown
    except Exception:
        rolled = 0
        breakdown = ""

    # v2.59.2 — bring the heal-claim flow into parity with the
    # target-bound auto-heal path (v2.58.0 + v2.59.1). Two
    # corrections: (a) add the caster's spellcasting modifier per
    # RAW (Cure Wounds heals `dice + spellcasting modifier`);
    # (b) add Disciple of Life uplift if the caster is a Life
    # Domain Cleric Lv 1+. Pre-v2.59.2 the claim flow rolled bare
    # dice — under-healing on every cast that went through the
    # legacy "🩹 Apply Healing" button path.
    caster_char = None
    caster_sheet = {}
    if claim.get("caster_char_id"):
        caster_char = db.query(Character).filter(
            Character.id == int(claim["caster_char_id"]),
            Character.campaign_id == campaign_id,
        ).first()
        if caster_char:
            caster_sheet = caster_char.sheet or {}
    _spc_mod = _caster_spellcasting_mod(caster_sheet)
    _claim_slot_level = int(claim.get("slot_level") or 0)
    _target_is_caster = bool(caster_char and caster_char.id == char.id)
    _life_target_uplift, _life_self_uplift = _life_domain_heal_uplift(
        caster_sheet, _claim_slot_level, _target_is_caster,
    )
    if rolled > 0 and _spc_mod > 0:
        rolled += _spc_mod
        breakdown = (
            f"{breakdown} + {_spc_mod} (spellcasting mod)"
            if breakdown else f"+{_spc_mod}"
        )
    if rolled > 0 and _life_target_uplift > 0:
        rolled += _life_target_uplift

    # Apply HP through the death-save state machine (heals wake the
    # character from dying/stable per v2.1.0 design).
    hp_before = char.sheet.get("hp") or {}
    hp_cur = int(hp_before.get("current") or 0)
    hp_max = int(hp_before.get("max") or 0)
    new_cur = min(hp_max, hp_cur + rolled) if hp_max > 0 else (hp_cur + rolled)
    result = _apply_hp_change(char, new_cur)
    db.commit()

    # v2.97.17 — stamp the heal entry against the cast_id so the
    # spell-cast card's ↶ Undo button reverses the HP gain. The
    # auto-applied path (v2.26.0 + v2.59.0) already stamps via
    # _apply_heal_to_combatant; this commit closes the heal-claim
    # path (player clicks 🩹 Apply Healing on a Cure Wounds card).
    # Blessed Healer self-heal logged above (cast_id=None) is NOT
    # included — undo won't refund the caster's self-heal yet;
    # filed for a follow-up commit.
    _claim_applied = int(result["hp"]["current"]) - int(hp_cur)
    if _claim_applied > 0:
        _log_damage_entry(cast_id, {
            "kind": "heal",
            "campaign_id": campaign_id,
            "target_char_id": char.id,
            "applied": _claim_applied,
            "is_heal": True,
        })

    # v2.59.2 — Disciple of Life + Blessed Healer broadcasts +
    # Blessed Healer self-heal. Mirror of the cast_spell single-
    # target Blessed Healer branch (~L 8260) but anchored on the
    # claim's caster_char + claimed target_char.
    if _life_target_uplift > 0 and caster_char:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": caster_char.id,
                "character_name": caster_char.name,
                "user_color": caster_char.color,
                "feature_name": (
                    f"💗 Disciple of Life → +{_life_target_uplift} "
                    f"HP on {char.name}"
                ),
                "feature_desc": (
                    f"Life Domain Lv 1+ — outgoing heals add "
                    f"2 + spell level ({_life_target_uplift}) HP."
                ),
                "source": "disciple-of-life",
            },
        })
    if _life_self_uplift > 0 and caster_char:
        _bh_caster_combatant = _lookup_combatant(
            campaign_id, f"tok_{caster_char.id}",
        )
        if not _bh_caster_combatant:
            _state = hub.get_battle(campaign_id) or {}
            for _c in (_state.get("combatants") or []):
                if _c.get("char_id") == caster_char.id:
                    _bh_caster_combatant = _c
                    break
        if not _bh_caster_combatant:
            _bh_caster_combatant = {
                "char_id": caster_char.id,
                "id": "",
                "name": caster_char.name,
            }
        # v2.97.18 — pass cast_id through so the Blessed Healer self-heal
        # also gets a log entry, and a single Undo POST reverses BOTH the
        # primary target's HP gain (v2.97.17 plumbing) AND the caster's
        # Blessed Healer self-heal. Pre-v2.97.18 this was the last
        # remaining HP-undo gap from the v2.97.16 audit notes.
        _bh_result = await _apply_heal_to_combatant(
            db, campaign_id, _bh_caster_combatant, _life_self_uplift,
            cast_id=cast_id,
        )
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": caster_char.id,
                "character_name": caster_char.name,
                "user_color": caster_char.color,
                "feature_name": (
                    f"💗 Blessed Healer → +{_bh_result['applied']} "
                    f"HP to {caster_char.name}"
                ),
                "feature_desc": (
                    f"Life Domain Lv 6+ — healing others heals "
                    f"you for 2 + spell level ({_life_self_uplift}) HP."
                ),
                "source": "blessed-healer",
            },
        })

    # Track claim
    claimed.add(user.id)
    claimed_count = len(claimed)

    new_hp = result["hp"]
    await hub.broadcast(campaign_id, {
        "type": "heal_applied",
        "data": {
            "cast_id": cast_id,
            "char_id": char.id,
            "char_name": char.name,
            "healer_name": user.display_name,
            "dice": claim["dice"],
            "rolled": rolled,
            "breakdown": breakdown,
            "new_hp": new_hp,
            "claimed_count": claimed_count,
            "max_targets": max_targets,
        },
    })
    if result["status_changed"]:
        await hub.broadcast(campaign_id, {
            "type": "character_death_save",
            "data": {
                "character_id": char.id,
                "status": result["death_saves"]["status"],
                "successes": int(result["death_saves"]["successes"]),
                "failures": int(result["death_saves"]["failures"]),
                "hp": new_hp,
                "source": "heal",
            },
        })
    return {"ok": True, "rolled": rolled, "breakdown": breakdown, "new_hp": new_hp,
            "claimed_count": claimed_count, "max_targets": max_targets}


# ----------- Feature-use registry (Phase 1, full-feature-automation) -----------

def _sheet_pb(sheet: "dict | None", level: int) -> int:
    """v2.99.387 — Proficiency bonus from the sheet, falling back to a
    level-derived value (2 + (level-1)//4) when the sheet doesn't carry
    a ``proficiency_bonus`` field."""
    pb = int((sheet or {}).get("proficiency_bonus") or 0)
    if pb <= 0:
        pb = 2 + (max(1, level) - 1) // 4
    return pb


# v2.99.387 — Phase 1 of docs/plans/full-feature-automation.md: a
# data-driven registry of per-rest feature-use counters. Each entry
# declares the bare ``sheet.<field>`` counter, the subclass/level gate
# that owns it, a ``max_fn(sheet)`` returning the max uses, and the
# ``reset`` cadence (``"short"`` refills on a short OR long rest;
# ``"long"`` refills on a long rest only). ``_refill_feature_uses``
# (called from /rest) replaces the hand-written per-feature long-rest
# hooks; ``_feature_use_max`` / ``_consume_feature_use`` let endpoints
# seed + decrement the counter uniformly (decrement → 409 out_of_uses).
_FEATURE_USES: "list[dict]" = [
    # Wild Magic Sorcerer — Tides of Chaos (1/long rest).
    {"field": "tides_of_chaos_uses", "gate": _pc_has_wild_magic,
     "min_level": 1, "max_fn": lambda s: 1, "reset": "long"},
    # Clockwork Soul Sorcerer — Restore Balance (PB/long rest).
    {"field": "restore_balance_uses", "gate": _pc_has_clockwork_soul,
     "min_level": 1,
     "max_fn": lambda s: _sheet_pb(s, _sorcerer_level_from_sheet(s)),
     "reset": "long"},
    # Divine Soul Sorcerer — Favored by the Gods (1/short OR long rest).
    {"field": "favored_by_gods_uses", "gate": _pc_has_divine_soul,
     "min_level": 1, "max_fn": lambda s: 1, "reset": "short"},
    # Shadow Magic Sorcerer — Strength of the Grave (1/long rest).
    {"field": "strength_of_grave_uses", "gate": _pc_has_shadow_magic,
     "min_level": 1, "max_fn": lambda s: 1, "reset": "long"},
    # Samurai Fighter — Fighting Spirit (3/long rest). v2.99.387 — first
    # announce-only → tracked retrofit via the registry.
    {"field": "fighting_spirit_uses", "gate": _pc_has_samurai,
     "min_level": 3, "max_fn": lambda s: 3, "reset": "long"},
    # Hexblade Warlock — Hexblade's Curse (1/short OR long rest).
    # v2.99.388 retrofit.
    {"field": "hexblades_curse_uses", "gate": _pc_has_hexblade_warlock,
     "min_level": 1, "max_fn": lambda s: 1, "reset": "short"},
    # Rune Knight Fighter — Giant's Might (PB/long rest). v2.99.389
    # retrofit — exercises a computed (proficiency-bonus) max_fn.
    {"field": "giants_might_uses", "gate": _pc_has_rune_knight,
     "min_level": 3,
     "max_fn": lambda s: _sheet_pb(s, _fighter_level_from_sheet(s)),
     "reset": "long"},
    # Arcane Archer Fighter — Arcane Shot (2/short OR long rest).
    # v2.99.390 retrofit.
    {"field": "arcane_shot_uses", "gate": _pc_has_arcane_archer,
     "min_level": 3, "max_fn": lambda s: 2, "reset": "short"},
    # Fathomless Warlock — Tentacle of the Deeps (PB/long rest).
    # v2.99.391 retrofit.
    {"field": "tentacle_uses", "gate": _pc_has_fathomless_warlock,
     "min_level": 1,
     "max_fn": lambda s: _sheet_pb(s, _warlock_level_from_sheet(s)),
     "reset": "long"},
]


def _feature_use_spec(field: str) -> "dict | None":
    """Return the ``_FEATURE_USES`` entry for ``field`` (or None)."""
    for spec in _FEATURE_USES:
        if spec["field"] == field:
            return spec
    return None


def _feature_use_max(sheet: "dict | None", field: str) -> "int | None":
    """v2.99.387 — Max uses for a registered feature-use counter when the
    PC's subclass/level gate passes, else None (feature not available to
    this PC). Endpoints use this to seed an absent counter to full."""
    if not sheet:
        return None
    spec = _feature_use_spec(field)
    if spec is None or not spec["gate"](sheet, spec["min_level"]):
        return None
    return int(spec["max_fn"](sheet))


def _consume_feature_use(sheet: dict, field: str) -> "tuple[int, int] | None":
    """v2.99.387 — Spend one use of a registered feature-use counter.

    Seeds an absent counter to its max (so a freshly-statted PC can use
    the feature before resting). Returns ``(remaining, max)`` on success,
    or ``None`` when the counter is already depleted (caller returns 409
    ``out_of_uses``). Mutates ``sheet[field]`` in place; the caller is
    responsible for the ``flag_modified`` + commit.
    """
    cap = _feature_use_max(sheet, field)
    if cap is None:
        cap = 1
    raw = sheet.get(field)
    cur = int(raw) if raw is not None else cap
    if cur <= 0:
        return None
    remaining = cur - 1
    sheet[field] = remaining
    return remaining, cap


def _consume_channel_divinity(sheet: dict) -> "tuple[int, int] | str":
    """v2.99.392 — Spend one use from the shared ``channel-divinity``
    resource pool (Cleric / Paladin Channel Divinity).

    Returns ``(remaining, max)`` on success, or the sentinel string
    ``"no_resource"`` (no CD pool on the sheet → caller 404s) /
    ``"out_of_uses"`` (pool empty → caller 409s). Mutates
    ``sheet["resources"]`` in place; the caller commits + broadcasts
    the ``resource_update``. The pool itself refills via the generic
    ``/rest`` resource loop, so no registry refill entry is needed.
    """
    resources = list(sheet.get("resources") or [])
    for i, r in enumerate(resources):
        if not isinstance(r, dict):
            continue
        if (r.get("key") or "").strip().lower() == "channel-divinity":
            cur = int(r.get("current") or 0)
            cap = int(r.get("max") or 0)
            if cur < 1:
                return "out_of_uses"
            resources[i] = {**r, "current": cur - 1}
            sheet["resources"] = resources
            return cur - 1, cap
    return "no_resource"


def _refill_feature_uses(sheet: dict, rest_type: str) -> None:
    """v2.99.387 — Refill every registered feature-use counter whose gate
    passes and whose reset cadence matches ``rest_type``. reset="short"
    refills on a short OR long rest; reset="long" on a long rest only.
    Called from /rest in place of the bespoke per-feature hooks."""
    for spec in _FEATURE_USES:
        reset = spec.get("reset", "long")
        matches = (reset == "short" and rest_type in ("short", "long")) or (
            reset == "long" and rest_type == "long")
        if not matches:
            continue
        if not spec["gate"](sheet, spec["min_level"]):
            continue
        sheet[spec["field"]] = int(spec["max_fn"](sheet))


# ----------- API: short / long rest -----------

@router.post("/api/campaign/{campaign_id}/character/{char_id}/rest")
async def rest_character(
    campaign_id: int,
    char_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Apply a short or long rest to a character.

    Body: ``{"type": "short" | "long"}``.

    Short rest: spend one hit die, roll d{HD}+CON, recover that much HP
    (capped at max), decrement hit_dice.current. Returns 409 if no hit
    dice are left.

    Long rest: HP→max, Temp HP cleared, hit_dice.current += max(1, ⌊max/2⌋)
    capped at max, every spell_slots[*].used reset to 0. Broadcasts a
    spell_slot_update WS message per slot level so any open mini-sheet or
    full sheet rerenders its pips.
    """
    body = await request.json()
    rest_type = str(body.get("type", "")).strip().lower()
    if rest_type not in ("short", "long"):
        raise HTTPException(400, "type must be 'short' or 'long'")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id
    ).first()
    if not char:
        raise HTTPException(404, "Character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if char.template == "dnd5e":
        normalize_dnd5e_sheet(sheet)
    hp = dict(sheet.get("hp") or {})
    hp_max = int(hp.get("max") or 0)
    hp_cur = int(hp.get("current") or 0)
    hd = dict(sheet.get("hit_dice") or {})
    hd_max = int(hd.get("max") if hd.get("max") is not None else (sheet.get("level") or 1))
    hd_cur = int(hd.get("current") if hd.get("current") is not None else hd_max)

    # Refill matching trackable resources. Long rest refills 'short' + 'long';
    # short rest only refills 'short'. Resources with reset='none' (manual
    # chat-only feature with a counter) are never auto-refilled.
    resources_before = list(sheet.get("resources") or [])
    refilled_resources: list[dict] = []
    new_resources: list[dict] = []
    for r in resources_before:
        if not isinstance(r, dict):
            new_resources.append(r)
            continue
        reset_kind = str(r.get("reset") or "").strip().lower()
        should_refill = (
            reset_kind == "short" and rest_type in ("short", "long")
        ) or (
            reset_kind == "long" and rest_type == "long"
        )
        if should_refill and int(r.get("max") or 0) > 0:
            # v2.158.86 — Magic-items Phase 4b: dice-expression
            # recharge. If the resource row carries a
            # ``charge_recovery`` field (a dice expression like
            # "1d6+1" — Wand of Magic Missiles' RAW recharge),
            # roll it and add to current (capped at max) instead
            # of the standard full refill. Items with simpler
            # 1-use-per-rest cadence (Pearl of Power) leave the
            # field absent and get the standard refill.
            cur_v = int(r.get("current") or 0)
            max_v = int(r.get("max") or 0)
            recovery_expr = str(r.get("charge_recovery") or "").strip()
            if recovery_expr:
                try:
                    roll_result = dice_mod.roll(recovery_expr)
                    add_n = int(roll_result.total)
                except (dice_mod.DiceParseError, Exception):
                    add_n = max_v - cur_v  # fall back to full refill
                new_cur = min(max_v, cur_v + max(0, add_n))
            else:
                new_cur = max_v
            updated = {**r, "current": new_cur}
            new_resources.append(updated)
            refilled_resources.append(updated)
        else:
            new_resources.append(r)
    sheet["resources"] = new_resources

    # v2.99.202 — Reset Relentless Rage DC on short OR long rest.
    # RAW PHB p.49: "When you finish a short or long rest, the DC
    # resets to 10." Clears the per-rest escalation.
    if "relentless_rage_dc" in sheet:
        sheet["relentless_rage_dc"] = 10

    # v2.99.387 — Phase 1 feature-use registry refill (replaces the
    # bespoke Tides of Chaos / Restore Balance / Favored by the Gods /
    # Strength of the Grave hooks). Handles both short- and long-rest
    # cadences via each entry's `reset`, so it runs in the shared
    # (short OR long) section. See docs/plans/full-feature-automation.md.
    _refill_feature_uses(sheet, rest_type)

    if rest_type == "long":
        # v2.220.0 — long rest restores up to the *effective* max, which
        # includes a CON-setting item's boost (Amulet of Health) via the
        # same _effective_max_hp_for_sheet delta the combat heal-clamp
        # reads. Keeps "full HP" consistent between resting and healing.
        _lr_max = hp_max
        try:
            _emh_lr = _effective_max_hp_for_sheet(sheet)
            if _emh_lr:
                _lr_max += int(_emh_lr.get("delta") or 0)
        except Exception:  # noqa: BLE001
            pass
        long_rest_new_cur = _lr_max if _lr_max > 0 else hp_cur
        hp["temp"] = 0
        hd["max"] = hd_max
        hd["current"] = min(hd_max, hd_cur + max(1, hd_max // 2)) if hd_max > 0 else hd_cur
        # Reset slots across every class's nested slot map.
        slots = dict(sheet.get("spell_slots") or {})
        new_slots: dict = {}
        broadcasts: list[tuple[str, int, int]] = []  # (class_slug, level, total)
        for cslug, by_lvl in slots.items():
            if isinstance(by_lvl, dict):
                cleaned: dict = {}
                for lvl_key, slot_obj in by_lvl.items():
                    if isinstance(slot_obj, dict):
                        # v2.49.123 — strip ephemeral Font-of-Magic
                        # slots before resetting used. RAW PHB p.101:
                        # ephemeral slots created by the SP→slot
                        # conversion vanish at long rest. The total
                        # is decremented by the ephemeral count;
                        # font_of_magic_extra is cleared.
                        try:
                            cur_total = int(slot_obj.get("total") or 0)
                        except (TypeError, ValueError):
                            cur_total = 0
                        try:
                            extra = int(slot_obj.get("font_of_magic_extra") or 0)
                        except (TypeError, ValueError):
                            extra = 0
                        post_total = max(0, cur_total - extra)
                        cleaned[lvl_key] = {
                            **slot_obj,
                            "used": 0,
                            "total": post_total,
                            "font_of_magic_extra": 0,
                        }
                        if post_total > 0:
                            try:
                                broadcasts.append((cslug, int(lvl_key), post_total))
                            except (TypeError, ValueError):
                                pass
                    else:
                        cleaned[lvl_key] = slot_obj
                new_slots[cslug] = cleaned
            else:
                new_slots[cslug] = by_lvl
        sheet["spell_slots"] = new_slots
        # v2.159.3 — Phase 8c: clear per-day item state flags on a
        # long rest (Javelin of Lightning ``_used_today: True`` → False).
        # RAW: "until the next dawn" maps to the long-rest dawn boundary.
        inventory_long = list(sheet.get("inventory") or [])
        if inventory_long:
            inv_dirty = False
            for _i, _inv in enumerate(inventory_long):
                if isinstance(_inv, dict) and _inv.get("_used_today"):
                    inventory_long[_i] = {**_inv, "_used_today": False}
                    inv_dirty = True
            if inv_dirty:
                sheet["inventory"] = inventory_long
        sheet["hp"] = hp
        sheet["hit_dice"] = hd
        # v2.99.219 — Portent (Divination Wizard Lv 2+) long-rest
        # refill. RAW PHB p.116: "When you finish a long rest, roll
        # two d20s and record the numbers rolled." 3 dice at Lv 14+
        # (Greater Portent). Pre-rolls the values + persists on
        # sheet.portent_dice; the consumer endpoint /use_portent
        # reads + decrements the list.
        _portent_count = _portent_dice_count(sheet)
        if _portent_count > 0:
            import random as _random_portent
            sheet["portent_dice"] = [
                _random_portent.randint(1, 20)
                for _ in range(_portent_count)
            ]
        # v2.99.387 — Tides of Chaos / Restore Balance / Strength of the
        # Grave long-rest refills now run via `_refill_feature_uses` in
        # the shared section above (Phase 1 feature-use registry).
        # v2.159.17 — exhaustion-levels Phase 1: finishing a long rest
        # reduces exhaustion by 1 (RAW PHB Appendix A). v1 simplification:
        # always reduce, no food/water gate (narrative). Min 0.
        _ex_pre = int(sheet.get("exhaustion_level") or 0)
        _ex_post = max(0, _ex_pre - 1)
        if _ex_pre != _ex_post:
            sheet["exhaustion_level"] = _ex_post
        char.sheet = sheet
        # Long rest restores HP to max and clears any dying/stable state.
        # Route through the death-save state machine so the broadcast +
        # tracker UI stay in sync.
        hp_result = _apply_hp_change(char, long_rest_new_cur)
        db.commit()
        if hp_result["status_changed"]:
            await hub.broadcast(campaign_id, {
                "type": "character_death_save",
                "data": {
                    "character_id": char.id,
                    "status": hp_result["death_saves"]["status"],
                    "successes": int(hp_result["death_saves"]["successes"]),
                    "failures": int(hp_result["death_saves"]["failures"]),
                    "hp": hp_result["hp"],
                    "source": "long_rest",
                },
            })

        # Broadcast slot-pip updates so any open sheet / mini-sheet re-renders
        for cslug, lvl, total in broadcasts:
            try:
                await hub.broadcast(campaign_id, {
                    "type": "spell_slot_update",
                    "data": {
                        "character_id": char.id,
                        "class_slug": cslug,
                        "level": lvl,
                        "total": total,
                        "used": 0,
                    },
                })
            except Exception:
                pass

        # v2.159.17 — exhaustion Phase 1: broadcast exhaustion_update
        # so any open sheet / init tracker re-renders the level badge.
        # v2.159.19 — Phase 3 mirror: also write the new level to the
        # PC's combatant mirror in the hub state so the leaf
        # effective_speed_walk helper can read it.
        if _ex_pre != _ex_post:
            try:
                state = hub.get_battle(campaign_id)
                if state:
                    changed = False
                    for c in state.get("combatants") or []:
                        if c.get("char_id") == char.id:
                            c["exhaustion_level"] = _ex_post
                            changed = True
                    if changed:
                        hub.set_battle(campaign_id, state)
            except Exception:
                pass
            try:
                await hub.broadcast(campaign_id, {
                    "type": "exhaustion_update",
                    "data": {
                        "character_id": char.id,
                        "level": _ex_post,
                        "source": "long_rest",
                    },
                })
            except Exception:
                pass

        # Broadcast resource refills for any open Class Resources panel
        for r in refilled_resources:
            try:
                await hub.broadcast(campaign_id, {
                    "type": "resource_update",
                    "data": {
                        "character_id": char.id,
                        "key": r.get("key"),
                        "current": int(r.get("current") or 0),
                        "max": int(r.get("max") or 0),
                    },
                })
            except Exception:
                pass

        # v2.99.439 — Phase 7.1: drop this character's summoned companions
        # on a long rest (Spiritual Weapon, familiars, etc. don't survive a
        # rest — and the leak guard keeps the board clean).
        _dismissed_summons = await _teardown_summons_for_owner(
            db, campaign_id, char.id,
        )

        return {"ok": True, "type": "long", "hp": hp_result["hp"],
                "hit_dice": hd, "resources": refilled_resources,
                "dismissed_summons": _dismissed_summons}

    # Short rest
    if hd_cur <= 0:
        return JSONResponse(
            status_code=409, content={"error": "no_hit_dice", "hit_dice": hd}
        )

    import re as _re
    die_str = (sheet.get("class_hit_die") or "").strip() or "d8"
    m = _re.search(r"d(\d+)", die_str, _re.IGNORECASE)
    die_size = int(m.group(1)) if m else 8

    abilities = sheet.get("abilities") or {}
    con_score = int(abilities.get("CON") or 10)
    con_mod = (con_score - 10) // 2

    # v2.15.3: Song of Rest — any Bard ≥ Lv 2 in the campaign grants
    # this rest an extra 1dN bonus (d6/d8/d10/d12 by Bard level). The
    # bonus die is folded into the same roll expression so the existing
    # ``dice_mod.roll`` call handles both terms and the breakdown reads
    # naturally ("1d8[5]+1d6[3]+2 => 10"). A Bard resting alone also
    # gets the bonus on their own HD spend (RAW: "you or any friendly
    # creatures who can hear your performance").
    sor_die, sor_bard, sor_bard_lv = _song_of_rest_for_campaign(db, campaign_id)
    sor_part = f"+1d{sor_die}" if sor_die > 0 else ""

    sign = "+" if con_mod >= 0 else ""
    con_part = f"{sign}{con_mod}" if con_mod != 0 else ""
    expr = f"1d{die_size}{sor_part}{con_part}"
    try:
        result = dice_mod.roll(expr)
        recovered = max(1, result.total)
        breakdown = result.breakdown
    except dice_mod.DiceParseError:
        recovered = 1
        breakdown = ""

    # v2.227.0 — Periapt of Wound Closure (RAW DMG p.184): "whenever you
    # roll a Hit Die to regain hit points, double the number of hit points
    # it restores." An equipped+attuned periapt doubles the rolled recovery
    # (reported pre-clamp in `recovered`/`recovered_pre_double`). Reuses the
    # `_equipped_item_effects` substrate's `double_hit_die_healing` union.
    hit_die_healing_doubled = False
    recovered_pre_double = recovered
    try:
        _rest_effects = _equipped_item_effects(sheet)
    except Exception:  # noqa: BLE001
        _rest_effects = {}
    if _rest_effects.get("double_hit_die_healing"):
        recovered = recovered * 2
        hit_die_healing_doubled = True
        _phd_src = _rest_effects.get("double_hit_die_healing_sources") or []
        _phd_name = _phd_src[0] if _phd_src else "Periapt of Wound Closure"
        breakdown = (
            f"{breakdown} ×2 ({_phd_name})" if breakdown
            else f"{recovered_pre_double} ×2 ({_phd_name})"
        )

    # v2.221.0 — clamp at the effective ceiling (stored max + a CON-setting
    # item's boost) so a short rest can refill an Amulet-of-Health wearer
    # up to their boosted pool, consistent with the v2.220.0 combat heal +
    # long-rest clamps.
    _sr_max = _sheet_heal_ceiling(sheet)
    new_hp = min(_sr_max, hp_cur + recovered) if _sr_max > 0 else (hp_cur + recovered)
    hd["current"] = hd_cur - 1
    hd["max"] = hd_max
    # v2.99.25 — Warlock Pact Magic short-rest slot refresh. RAW
    # (PHB p.107): Warlock spell slots refresh on a short rest,
    # unlike every other caster. Walks `sheet.spell_slots[cslug]`
    # and resets `used = 0` on any slot row carrying
    # `reset: "short"`. The slot-level marker (rather than a
    # blanket warlock-class gate) generalizes to future homebrew
    # casters with short-rest slots and to multiclass Warlocks
    # whose pact slots live alongside other classes' long-rest
    # slots. Other classes' slots (no `reset` field or
    # `reset != "short"`) are left untouched on short rest.
    short_rest_slot_broadcasts: list[tuple[str, int, int]] = []
    short_slots = dict(sheet.get("spell_slots") or {})
    new_short_slots: dict = {}
    for cslug, by_lvl in short_slots.items():
        if isinstance(by_lvl, dict):
            cleaned: dict = {}
            for lvl_key, slot_obj in by_lvl.items():
                if (isinstance(slot_obj, dict)
                        and (slot_obj.get("reset") or "").strip().lower() == "short"):
                    try:
                        cur_total = int(slot_obj.get("total") or 0)
                    except (TypeError, ValueError):
                        cur_total = 0
                    cleaned[lvl_key] = {**slot_obj, "used": 0}
                    if cur_total > 0:
                        try:
                            short_rest_slot_broadcasts.append(
                                (cslug, int(lvl_key), cur_total)
                            )
                        except (TypeError, ValueError):
                            pass
                else:
                    cleaned[lvl_key] = slot_obj
            new_short_slots[cslug] = cleaned
        else:
            new_short_slots[cslug] = by_lvl
    sheet["spell_slots"] = new_short_slots

    # v2.99.39 — Sorcerous Restoration (Sorcerer Lv 20 capstone). RAW
    # (PHB p.101): "Beginning at 20th level, you regain 4 expended
    # sorcery points whenever you finish a short rest." Sorcery
    # points use `reset: "long"` so the resource-refill loop above
    # doesn't touch them on a short rest — Lv 20 is the only path to
    # get SP back from a short rest. Gated on class==sorcerer AND
    # level>=20. Multiclass Sorcerers: the gate reads the sheet's
    # base `class`/`level` (the primary class). Future Sorcerer/X
    # multiclass would need a class-roster scan; filed.
    sr_restored_sp = 0
    sr_sp_new = None
    sr_sp_max = None
    if (
        (sheet.get("class") or "").strip().lower() == "sorcerer"
        and int(sheet.get("level") or 0) >= 20
    ):
        sr_resources = list(sheet.get("resources") or [])
        for i, r in enumerate(sr_resources):
            if not isinstance(r, dict):
                continue
            if (r.get("key") or "").strip().lower() != "sorcery-points":
                continue
            sp_cur = int(r.get("current") or 0)
            sp_max = int(r.get("max") or 0)
            if sp_max <= 0:
                break
            sr_restored_sp = min(4, sp_max - sp_cur)
            if sr_restored_sp <= 0:
                # Already at max — no broadcast, RAW restore amount is 0.
                sr_sp_new = sp_cur
                sr_sp_max = sp_max
                break
            new_sp = sp_cur + sr_restored_sp
            updated = {**r, "current": new_sp}
            sr_resources[i] = updated
            sr_sp_new = new_sp
            sr_sp_max = sp_max
            break
        sheet["resources"] = sr_resources

    sheet["hp"] = hp
    sheet["hit_dice"] = hd
    char.sheet = sheet
    from sqlalchemy.orm.attributes import flag_modified as _flag_mod_sr
    _flag_mod_sr(char, "sheet")
    # Short rest healing goes through the state machine so a dying
    # character who somehow ends up able to take a short rest (e.g. via
    # the GM rolling them stable then back up) cleanly wakes them.
    hp_result = _apply_hp_change(char, new_hp)
    db.commit()
    if hp_result["status_changed"]:
        await hub.broadcast(campaign_id, {
            "type": "character_death_save",
            "data": {
                "character_id": char.id,
                "status": hp_result["death_saves"]["status"],
                "successes": int(hp_result["death_saves"]["successes"]),
                "failures": int(hp_result["death_saves"]["failures"]),
                "hp": hp_result["hp"],
                "source": "short_rest",
            },
        })

    # Broadcast resource refills for any short-rest resources (Action Surge,
    # Channel Divinity, Ki, Superiority Dice, …) so live panels re-pip.
    for r in refilled_resources:
        try:
            await hub.broadcast(campaign_id, {
                "type": "resource_update",
                "data": {
                    "character_id": char.id,
                    "key": r.get("key"),
                    "current": int(r.get("current") or 0),
                    "max": int(r.get("max") or 0),
                },
            })
        except Exception:
            pass

    # v2.99.39 — Sorcerous Restoration broadcasts. Mirrors the
    # `resource_update` shape every other SP touch uses + emits a
    # `feature_used(source=sorcerous-restoration)` so the chat log
    # surfaces "Zara regains 4 sorcery points (Sorcerous Restoration)".
    if sr_restored_sp > 0 and sr_sp_new is not None and sr_sp_max is not None:
        try:
            await hub.broadcast(campaign_id, {
                "type": "resource_update",
                "data": {
                    "character_id": char.id,
                    "key": "sorcery-points",
                    "current": int(sr_sp_new),
                    "max": int(sr_sp_max),
                },
            })
        except Exception:
            pass
        try:
            await hub.broadcast(campaign_id, {
                "type": "feature_used",
                "data": {
                    "character_id": char.id,
                    "character_name": char.name,
                    "user_color": char.color,
                    "feature_name": (
                        f"✨ Sorcerous Restoration "
                        f"(+{sr_restored_sp} SP)"
                    ),
                    "feature_desc": (
                        f"{char.name} finishes a short rest and "
                        f"regains {sr_restored_sp} sorcery point"
                        f"{'s' if sr_restored_sp != 1 else ''}."
                    ),
                    "source": "sorcerous-restoration",
                    "remaining": int(sr_sp_new),
                    "max": int(sr_sp_max),
                },
            })
        except Exception:
            pass

    # v2.99.25 — broadcast Pact Magic slot refills so any open
    # sheet / mini-sheet repaints the slot pips. Mirrors the
    # long-rest broadcast loop at the top of this handler.
    for cslug, lvl, total in short_rest_slot_broadcasts:
        try:
            await hub.broadcast(campaign_id, {
                "type": "spell_slot_update",
                "data": {
                    "character_id": char.id,
                    "class_slug": cslug,
                    "level": lvl,
                    "total": total,
                    "used": 0,
                },
            })
        except Exception:
            pass

    return {
        "ok": True,
        "type": "short",
        "hp": hp_result["hp"],
        "hit_dice": hd,
        "expression": expr,
        "recovered": recovered,
        "breakdown": breakdown,
        # v2.227.0 — Periapt of Wound Closure: True when an equipped+attuned
        # periapt doubled the rolled Hit-Die recovery. `recovered_pre_double`
        # is the pre-doubling roll (null when not doubled) so a client/test
        # can verify recovered == 2 × pre regardless of the HP-cap clamp.
        "hit_die_healing_doubled": hit_die_healing_doubled,
        "recovered_pre_double": (
            recovered_pre_double if hit_die_healing_doubled else None
        ),
        "resources": refilled_resources,
        # v2.99.39 — Sorcerous Restoration: how many SP the Lv 20
        # capstone refunded this short rest. 0 for every non-Lv-20
        # Sorcerer + every non-Sorcerer.
        "sorcerous_restoration_sp": int(sr_restored_sp),
        # v2.15.3: ``song_of_rest`` is non-null when any Bard ≥ Lv 2 is
        # in the campaign. ``die`` is the d{N} that was rolled, ``bard``
        # is the highest-level Bard's name (display attribution),
        # ``bard_level`` is their level. Null when no eligible Bard
        # exists. The bonus die's individual roll is included in the
        # ``breakdown`` string ("1d8[5]+1d6[3]+2 => 10") so the client
        # can extract the exact value or just show the breakdown verbatim.
        "song_of_rest": (
            {"die": sor_die, "bard": sor_bard, "bard_level": sor_bard_lv}
            if sor_die > 0 else None
        ),
    }


# ----------- API: exhaustion levels (v2.159.17 Phase 1) ----------------

@router.post("/api/campaign/{campaign_id}/set_exhaustion")
async def set_exhaustion(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.159.17 — exhaustion-levels Phase 1 (see
    docs/plans/exhaustion-levels.md). Single mutation endpoint for the
    `sheet.exhaustion_level` integer (PCs) or
    `combatant.exhaustion_level` (NPCs). Clamps 0-6. At level 6,
    routes through the existing death-saves machinery for PCs
    (status='dead') or 0-HP removal for NPCs.

    Body:
      - `character_id` (int, optional) — target a PC.
      - `combatant_id` (str, optional) — target an NPC by hub state id.
      - `level` (int) — direct set, takes priority over delta.
      - `delta` (int) — relative change (positive or negative).
    Exactly one of level/delta must be supplied; exactly one of
    character_id/combatant_id must be supplied.

    Broadcasts `exhaustion_update` with `{character_id|combatant_id,
    level, source}`. At level 6, also fires the existing
    `character_death_save` (PC) or `battle_update` (NPC HP=0) cards.
    """
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    body = await request.json()

    char_id = body.get("character_id")
    combatant_id = body.get("combatant_id")
    if (char_id is None) == (combatant_id is None):
        raise HTTPException(
            400,
            "exactly one of character_id or combatant_id required",
        )

    has_level = "level" in body
    has_delta = "delta" in body
    if has_level == has_delta:
        raise HTTPException(
            400, "exactly one of level or delta required",
        )

    if char_id is not None:
        char = db.query(Character).filter(
            Character.id == int(char_id),
            Character.campaign_id == campaign_id,
        ).first()
        if not char:
            raise HTTPException(404, "Character not found")
        if not (_user_is_gm(user, campaign, db)
                or char.owner_user_id == user.id):
            raise HTTPException(403, "Not your character")
        sheet = dict(char.sheet or {})
        cur = int(sheet.get("exhaustion_level") or 0)
        if has_level:
            new_level = int(body.get("level") or 0)
        else:
            new_level = cur + int(body.get("delta") or 0)
        new_level = max(0, min(6, new_level))
        sheet["exhaustion_level"] = new_level
        from sqlalchemy.orm.attributes import flag_modified
        char.sheet = sheet
        flag_modified(char, "sheet")
        # v2.159.20 — exhaustion Phase 3b: when transitioning from
        # < 4 to >= 4, clamp current HP down to floor(max/2) if it's
        # above the new ceiling. The PC's HP ceiling is suddenly halved
        # by the level change itself, not by a heal; so we drop the
        # excess in-place. Going BACK below 4 (long rest / Greater
        # Restoration) does NOT restore HP — the player still has to
        # heal up to the new ceiling.
        if new_level >= 4 and cur < 4:
            hp_field = dict(sheet.get("hp") or {})
            hp_max_field = int(hp_field.get("max") or 0)
            hp_cur_field = int(hp_field.get("current") or 0)
            if hp_max_field > 0:
                new_ceiling = hp_max_field // 2
                if hp_cur_field > new_ceiling:
                    hp_field["current"] = new_ceiling
                    sheet["hp"] = hp_field
                    char.sheet = sheet
                    flag_modified(char, "sheet")
        # Level 6 → instant death via the death-save state machine.
        died = False
        if new_level >= 6:
            _set_death_save_state(char, status="dead")
            died = True
        db.commit()

        # v2.159.19 — Phase 3 mirror: also write exhaustion_level onto
        # the PC's combatant mirror in the hub state so the leaf
        # effective_speed_walk helper can read it without DB access.
        # No-op when the PC isn't in an active battle.
        try:
            state = hub.get_battle(campaign_id)
            if state:
                changed = False
                for c in state.get("combatants") or []:
                    if c.get("char_id") == char.id:
                        if int(c.get("exhaustion_level") or 0) != new_level:
                            c["exhaustion_level"] = new_level
                            changed = True
                if changed:
                    hub.set_battle(campaign_id, state)
        except Exception:
            pass

        try:
            await hub.broadcast(campaign_id, {
                "type": "exhaustion_update",
                "data": {
                    "character_id": char.id,
                    "level": new_level,
                    "previous": cur,
                    "source": "set_exhaustion",
                },
            })
        except Exception:
            pass
        if died:
            ds = dict(char.sheet.get("death_saves") or {})
            try:
                await hub.broadcast(campaign_id, {
                    "type": "character_death_save",
                    "data": {
                        "character_id": char.id,
                        "status": ds.get("status", "dead"),
                        "successes": int(ds.get("successes") or 0),
                        "failures": int(ds.get("failures") or 0),
                        "hp": dict(char.sheet.get("hp") or {}),
                        "source": "exhaustion_lv6",
                    },
                })
            except Exception:
                pass
        return {
            "ok": True,
            "character_id": char.id,
            "level": new_level,
            "previous": cur,
            "died": died,
        }

    # NPC path — mutate the combatant in the hub state.
    state = hub.get_battle(campaign_id)
    if not state:
        raise HTTPException(404, "No active battle")
    target = None
    for c in state.get("combatants") or []:
        if c.get("id") == combatant_id:
            target = c
            break
    if target is None:
        raise HTTPException(404, "combatant not found in battle")
    cur = int(target.get("exhaustion_level") or 0)
    if has_level:
        new_level = int(body.get("level") or 0)
    else:
        new_level = cur + int(body.get("delta") or 0)
    new_level = max(0, min(6, new_level))
    target["exhaustion_level"] = new_level
    # v2.159.20 — exhaustion Phase 3b: NPC mirror of the PC HP clamp.
    # Transitioning to >= 4 caps current HP at floor(hp_max/2) if it's
    # above the new ceiling.
    if new_level >= 4 and cur < 4:
        npc_hp_max = int(target.get("hp_max") or 0)
        npc_hp_cur = int(target.get("hp_current") or 0)
        if npc_hp_max > 0:
            new_npc_ceiling = npc_hp_max // 2
            if npc_hp_cur > new_npc_ceiling:
                target["hp_current"] = new_npc_ceiling
    npc_killed = False
    if new_level >= 6:
        target["hp_current"] = 0
        npc_killed = True
    hub.set_battle(campaign_id, state)

    try:
        await hub.broadcast(campaign_id, {
            "type": "exhaustion_update",
            "data": {
                "combatant_id": combatant_id,
                "level": new_level,
                "previous": cur,
                "source": "set_exhaustion",
            },
        })
    except Exception:
        pass
    if npc_killed:
        try:
            await hub.broadcast(campaign_id, {
                "type": "battle_update",
                "data": state,
                "force_gm_sync": True,
            })
        except Exception:
            pass
    return {
        "ok": True,
        "combatant_id": combatant_id,
        "level": new_level,
        "previous": cur,
        "died": npc_killed,
    }


# ----------- API: magic-item attunement toggle (v2.158.79 Phase 2) -----

@router.post("/api/campaign/{campaign_id}/character/{char_id}/attune")
async def attune_item(
    campaign_id: int,
    char_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.158.79 — toggle the ``attuned`` flag on an inventory item.

    Body: ``{"inventory_index": int, "attuned": bool}``.

    Enforces the RAW DMG p.138 3-item attunement cap: when setting
    ``attuned=True``, if the PC already has 3 OTHER items with
    ``attuned: True``, returns 409 ``{"error": "attunement_cap"}``.
    Setting ``attuned=False`` always succeeds (you can always break
    attunement).

    The Phase 1a-c catalog walker (``_equipped_item_effects``) already
    gates passive payloads on the ``attuned`` flag — this endpoint is
    the player/GM-facing surface that flips it. Broadcasts a
    ``character_update`` so any open sheet rerenders.
    """
    body = await request.json()
    if "inventory_index" not in body or "attuned" not in body:
        raise HTTPException(
            400, "inventory_index and attuned are required",
        )
    try:
        inv_idx = int(body["inventory_index"])
    except (TypeError, ValueError):
        raise HTTPException(400, "inventory_index must be an int")
    attuned = bool(body["attuned"])

    campaign = (
        db.query(Campaign).filter(Campaign.id == campaign_id).first()
    )
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Character not found")
    if not (
        _user_is_gm(user, campaign, db) or char.owner_user_id == user.id
    ):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    inventory = list(sheet.get("inventory") or [])
    if inv_idx < 0 or inv_idx >= len(inventory):
        raise HTTPException(400, "inventory_index out of range")

    # RAW DMG p.138 — max 3 attuned items. Count CURRENT attuned items
    # excluding the target index so toggling an already-attuned item to
    # attuned=True is a no-op rather than a spurious 409.
    if attuned:
        attuned_count = sum(
            1 for i, it in enumerate(inventory)
            if i != inv_idx and isinstance(it, dict) and it.get("attuned")
        )
        if attuned_count >= 3:
            return JSONResponse(
                status_code=409,
                content={
                    "error": "attunement_cap",
                    "current_attuned": attuned_count,
                    "max_attuned": 3,
                },
            )

    item = dict(inventory[inv_idx]) if isinstance(inventory[inv_idx], dict) else {}
    item["attuned"] = attuned
    inventory[inv_idx] = item
    sheet["inventory"] = inventory
    char.sheet = sheet
    db.commit()

    await hub.broadcast(campaign_id, {
        "type": "character_update",
        "data": {"id": char.id, "name": char.name},
    })

    return {
        "ok": True,
        "inventory_index": inv_idx,
        "attuned": attuned,
        "item_name": item.get("name") or "",
    }


# ----------- API: magic-item active action use (v2.158.82 Phase 3) -----

@router.post(
    "/api/campaign/{campaign_id}/character/{char_id}/use_item_action",
)
async def use_item_action(
    campaign_id: int,
    char_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.158.82 — M2 primitive: invoke a magic item's active action.

    Body: ``{inventory_index: int, action_key: str, slot_level?: int,
    class_slug?: str, override?: bool}``.

    Dispatches by the inventory item's ``_slug`` against
    ``_MAGIC_ITEM_ACTIONS``. Phase 3 ships only Pearl of Power's
    ``restore-slot``: validate the item is equipped + attuned, find
    the matching resource row (`pearl-of-power`), check `current > 0`
    (409 ``out_of_uses`` otherwise), decrement it, find an expended
    spell slot of the requested level (≤ catalog's
    ``max_slot_level``) on the PC's ``spell_slots[class_slug]``,
    decrement its ``used``, broadcast `spell_slot_update` +
    `resource_update` + `feature_used`.

    Phase 4 will add charge-tracked wands (multi-charge spend per
    use) via the same endpoint with a different action_key.
    """
    body = await request.json()
    if "inventory_index" not in body or "action_key" not in body:
        raise HTTPException(
            400, "inventory_index and action_key are required",
        )
    try:
        inv_idx = int(body["inventory_index"])
    except (TypeError, ValueError):
        raise HTTPException(400, "inventory_index must be an int")
    action_key = str(body.get("action_key") or "").strip()
    slot_level_raw = body.get("slot_level")
    class_slug = str(body.get("class_slug") or "").strip().lower()

    campaign = (
        db.query(Campaign).filter(Campaign.id == campaign_id).first()
    )
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id,
    ).first()
    if not char:
        raise HTTPException(404, "Character not found")
    if not (
        _user_is_gm(user, campaign, db) or char.owner_user_id == user.id
    ):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    inventory = list(sheet.get("inventory") or [])
    if inv_idx < 0 or inv_idx >= len(inventory):
        raise HTTPException(400, "inventory_index out of range")
    item = inventory[inv_idx]
    if not isinstance(item, dict):
        raise HTTPException(400, "inventory_index does not name an item")

    slug = str(item.get("_slug") or "").strip().lower()
    if not slug:
        raise HTTPException(409, "item has no _slug; no action available")
    catalog = _MAGIC_ITEM_ACTIONS.get(slug)
    if not catalog:
        raise HTTPException(
            404, f"no action {action_key!r} for item {slug!r}",
        )
    # v2.158.88 — Phase 4d: multi-action items declare an `actions`
    # sub-map; legacy single-action entries declare a top-level `key`.
    # The dispatch validates the action_key against whichever shape
    # the catalog uses.
    actions_map = catalog.get("actions") if isinstance(catalog.get("actions"), dict) else None
    if actions_map is not None:
        if action_key not in actions_map:
            raise HTTPException(
                404, f"no action {action_key!r} for item {slug!r}",
            )
    elif catalog.get("key") != action_key:
        raise HTTPException(
            404, f"no action {action_key!r} for item {slug!r}",
        )
    if catalog.get("requires_attunement") and not item.get("attuned"):
        raise HTTPException(
            409, f"{item.get('name') or slug} requires attunement",
        )
    # v2.184.0 — consumables (potions) aren't "equipped" in a slot; the
    # catalog flags them and the dispatch skips the equip gate.
    if not catalog.get("consumable") and not item.get("equipped"):
        raise HTTPException(
            409, f"{item.get('name') or slug} must be equipped",
        )

    # Dispatch by slug. Phase 3 had only Pearl of Power; Phase 4a adds
    # Wand of Magic Missiles. Future items get their own branch here.
    if slug == "pearl-of-power":
        return await _use_item_action_pearl(
            db, campaign_id, char, item, sheet, catalog, slot_level_raw,
            class_slug, inventory, inv_idx,
        )
    if slug in ("wand-of-magic-missiles", "wand-of-fireballs",
                "wand-of-lightning-bolts", "wand-of-web",
                "wand-of-polymorph", "wand-of-binding"):
        return await _use_item_action_charge_wand(
            db, campaign_id, char, item, sheet, catalog, slug,
            body.get("charges"),
        )
    if slug == "staff-of-healing":
        action_def = catalog["actions"][action_key]
        return await _use_item_action_staff_of_healing(
            db, campaign_id, char, item, sheet, catalog,
            action_key, action_def, body.get("charges"),
        )
    if slug == "flame-tongue":
        action_def = catalog["actions"][action_key]
        return await _use_item_action_flame_tongue(
            db, campaign_id, char, item, sheet,
            action_key, action_def, inv_idx,
        )
    if slug == "javelin-of-lightning":
        action_def = catalog["actions"][action_key]
        return await _use_item_action_javelin_of_lightning(
            db, campaign_id, char, item, sheet,
            action_key, action_def, inv_idx,
            target_combatant_ids=body.get("target_combatant_ids") or [],
            campaign=campaign,
            prompt_user=user,
        )
    if slug in ("necklace-of-fireballs", "staff-of-fire", "staff-of-frost",
                "staff-of-swarming-insects", "staff-of-thunder-and-lightning",
                "staff-of-power"):
        action_def = catalog["actions"][action_key]
        return await _use_item_action_necklace_of_fireballs(
            db, campaign_id, char, item, sheet, catalog,
            action_key, action_def,
            target_combatant_ids=body.get("target_combatant_ids") or [],
            charges=body.get("charges"),
            campaign=campaign,
            prompt_user=user,
            slug=slug,
        )
    if slug == "ring-of-the-ram":
        action_def = catalog["actions"][action_key]
        return await _use_item_action_attack(
            db, campaign_id, char, item, sheet, catalog,
            action_key, action_def,
            target_combatant_ids=body.get("target_combatant_ids") or [],
            charges=body.get("charges"),
            campaign=campaign,
            prompt_user=user,
            slug=slug,
        )
    if slug in (
        "gem-of-seeing", "wand-of-enemy-detection",
        # v2.324.0 — Wand of Magic Detection lands here via the same
        # `_use_item_action_buff` handler (its `detect` action_kind: "buff"
        # installs a 100-round magic-detection self-buff for 1 charge).
        "wand-of-magic-detection",
        # v2.325.0 — Wand of Secrets — same buff-handler shape with a
        # 1-round single-whisper buff.
        "wand-of-secrets",
    ):
        action_def = catalog["actions"][action_key]
        return await _use_item_action_buff(
            db, campaign_id, char, item, sheet, catalog,
            action_key, action_def,
            charges=body.get("charges"),
            slug=slug,
        )
    if slug == "wand-of-wonder":
        action_def = catalog["actions"][action_key]
        return await _use_item_action_wand_of_wonder(
            db, campaign_id, char, item, sheet, catalog,
            action_key, action_def,
            charges=body.get("charges"),
            force_roll=body.get("force_roll"),
            slug=slug,
        )
    if slug == "horn-of-blasting":
        action_def = catalog["actions"][action_key]
        return await _use_item_action_horn_of_blasting(
            db, campaign_id, char, item, sheet, catalog,
            action_key, action_def,
            target_combatant_ids=body.get("target_combatant_ids") or [],
            campaign=campaign,
            prompt_user=user,
            slug=slug,
        )
    if slug in ("wand-of-fear", "wand-of-paralysis", "staff-of-charming",
                "eyes-of-charming",
                # v2.326.0 — Gem of Brightness Mode 2 ("beam") shares the
                # single-target save-condition handler shape with Wand of
                # Paralysis — the only knobs are the slug, the condition_key
                # ("blinded" vs "paralyzed"), and the save ability (CON).
                "gem-of-brightness",
                # v2.340.0 — Mace of Terror — a Wand of Fear clone (WIS →
                # frightened, 3 charges) on the same save-condition handler.
                "mace-of-terror"):
        action_def = catalog["actions"][action_key]
        return await _use_item_action_wand_of_fear(
            db, campaign_id, char, item, sheet, catalog,
            action_key, action_def,
            target_combatant_ids=body.get("target_combatant_ids") or [],
            charges=body.get("charges"),
            campaign=campaign,
            prompt_user=user,
            slug=slug,
        )
    if slug == "potion-of-fire-breath":
        action_def = catalog["actions"][action_key]
        return await _use_item_action_potion_of_fire_breath(
            db, campaign_id, char, item, sheet, catalog,
            action_key, action_def, inv_idx,
            target_combatant_ids=body.get("target_combatant_ids") or [],
            campaign=campaign,
            prompt_user=user,
        )
    if slug in ("potion-of-mind-reading", "potion-of-animal-friendship"):
        action_def = catalog["actions"][action_key]
        return await _use_item_action_potion_of_mind_reading(
            db, campaign_id, char, item, sheet, catalog,
            action_key, action_def, inv_idx,
            target_combatant_ids=body.get("target_combatant_ids") or [],
            campaign=campaign,
            prompt_user=user,
        )
    if slug in (
        "potion-of-heroism", "potion-of-speed",
        "potion-of-resistance", "potion-of-invulnerability",
        "potion-of-growth", "potion-of-climbing",
        "potion-of-water-breathing", "potion-of-diminution",
        "potion-of-invisibility", "potion-of-flying",
        "potion-of-clairvoyance", "potion-of-gaseous-form",
        "potion-of-giant-strength",
    ):
        return await _use_item_action_self_buff_potion(
            db, campaign_id, char, item, sheet, catalog, inv_idx,
            resistance_type=body.get("resistance_type"),
        )
    if slug in (
        "manual-of-gainful-exercise", "manual-of-bodily-health",
        "manual-of-quickness-of-action", "tome-of-clear-thought",
        "tome-of-understanding", "tome-of-leadership-and-influence",
    ):
        return await _use_item_action_permanent_boost(
            db, campaign_id, char, item, sheet, catalog, inv_idx,
        )
    raise HTTPException(409, "unknown item action handler")


async def _use_item_action_pearl(
    db, campaign_id, char, item, sheet, catalog, slot_level_raw,
    class_slug, inventory, inv_idx,
):
    """v2.158.82 → extracted v2.158.84: Pearl of Power handler."""
    # Pearl of Power — restore one expended spell slot of level
    # 1..max_slot_level.
    try:
        slot_level = int(slot_level_raw or 0)
    except (TypeError, ValueError):
        raise HTTPException(400, "slot_level must be an int")
    max_lvl = int(catalog.get("max_slot_level") or 3)
    if slot_level < 1 or slot_level > max_lvl:
        raise HTTPException(
            400,
            f"slot_level must be 1..{max_lvl} for {item.get('name')}",
        )
    slug = "pearl-of-power"

    # Find the resource row that gates the per-day use. Seeded onto
    # the PC sheet alongside the inventory item.
    resources = list(sheet.get("resources") or [])
    res_key = str(catalog.get("resource_key") or "")
    res_idx = -1
    for i, r in enumerate(resources):
        if isinstance(r, dict) and (r.get("key") or "").lower() == res_key:
            res_idx = i
            break
    if res_idx < 0:
        raise HTTPException(
            409,
            f"No {res_key!r} resource row on sheet — item not bootstrapped",
        )
    res_row = dict(resources[res_idx])
    cur = int(res_row.get("current") or 0)
    res_max = int(res_row.get("max") or 0)
    if cur <= 0:
        return JSONResponse(
            status_code=409,
            content={"error": "out_of_uses", "label": item.get("name") or slug},
        )

    # Find the spellcasting class slug. Take the request's class_slug
    # if provided; otherwise pick the first class on the sheet that has
    # an expended slot at the requested level. (Most demo PCs have
    # exactly one spellcasting class so the picker is unambiguous.)
    all_slots = dict(sheet.get("spell_slots") or {})
    if not class_slug:
        for cs, slots in all_slots.items():
            slot = (slots or {}).get(str(slot_level)) or {}
            if int(slot.get("used") or 0) > 0:
                class_slug = cs
                break
    if not class_slug:
        return JSONResponse(
            status_code=409,
            content={
                "error": "no_expended_slot",
                "slot_level": slot_level,
            },
        )

    class_slots = dict(all_slots.get(class_slug) or {})
    slot = dict(class_slots.get(str(slot_level)) or {})
    used = int(slot.get("used") or 0)
    total = int(slot.get("total") or 0)
    if used <= 0:
        return JSONResponse(
            status_code=409,
            content={
                "error": "no_expended_slot",
                "slot_level": slot_level,
                "class_slug": class_slug,
            },
        )

    # Apply: decrement resource + slot.
    res_row["current"] = cur - 1
    resources[res_idx] = res_row
    sheet["resources"] = resources
    slot["used"] = used - 1
    class_slots[str(slot_level)] = slot
    all_slots[class_slug] = class_slots
    sheet["spell_slots"] = all_slots

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # Broadcasts: slot pip + resource pip + feature_used chat card.
    try:
        await hub.broadcast(campaign_id, {
            "type": "spell_slot_update",
            "data": {
                "character_id": char.id,
                "class_slug": class_slug,
                "level": slot_level,
                "total": total,
                "used": slot["used"],
            },
        })
    except Exception:
        pass
    try:
        await hub.broadcast(campaign_id, {
            "type": "resource_update",
            "data": {
                "character_id": char.id,
                "key": res_key,
                "current": res_row["current"],
                "max": res_max,
            },
        })
    except Exception:
        pass
    try:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "caster_char_name": char.name,
                "source": f"item-{slug}",
                "label": catalog.get("name") or "Use item",
                "summary": (
                    f"{char.name} used {item.get('name')} to restore a "
                    f"L{slot_level} {class_slug} slot."
                ),
            },
        })
    except Exception:
        pass

    return {
        "ok": True,
        "item_name": item.get("name") or slug,
        "slot_restored": {
            "class_slug": class_slug,
            "level": slot_level,
            "total": total,
            "used": slot["used"],
        },
        "resource": {
            "key": res_key,
            "current": res_row["current"],
            "max": res_max,
        },
    }


async def _use_item_action_charge_wand(
    db, campaign_id, char, item, sheet, catalog, slug, charges_raw,
):
    """v2.158.84 → generalized v2.158.87: charge-tracked wand handler
    shared by Wand of Magic Missiles + Wand of Fireballs (+ future
    multi-charge wands). Expend N charges; cast slot level is
    ``base_slot_level + (N - 1)`` (MM base=1, Fireball base=3).
    Decrements the wand resource by N + broadcasts a feature_used
    summary. The actual spell damage roll routes through the existing
    client-side /cast_spell flow; wiring the cast directly through
    this endpoint with a ``source_item`` flag is a future polish.
    """
    try:
        charges = int(charges_raw or 0)
    except (TypeError, ValueError):
        raise HTTPException(400, "charges must be an int")
    min_c = int(catalog.get("min_charges") or 1)
    max_c = int(catalog.get("max_charges") or 7)
    if charges < min_c or charges > max_c:
        raise HTTPException(
            400,
            f"charges must be {min_c}..{max_c} for {item.get('name')}",
        )

    # Find the resource row.
    resources = list(sheet.get("resources") or [])
    res_key = str(catalog.get("resource_key") or "")
    res_idx = -1
    for i, r in enumerate(resources):
        if isinstance(r, dict) and (r.get("key") or "").lower() == res_key:
            res_idx = i
            break
    if res_idx < 0:
        raise HTTPException(
            409,
            f"No {res_key!r} resource row on sheet — item not bootstrapped",
        )
    res_row = dict(resources[res_idx])
    cur = int(res_row.get("current") or 0)
    res_max = int(res_row.get("max") or 0)
    if cur < charges:
        return JSONResponse(
            status_code=409,
            content={
                "error": "insufficient_charges",
                "current": cur,
                "requested": charges,
                "label": item.get("name") or slug,
            },
        )

    res_row["current"] = cur - charges
    resources[res_idx] = res_row
    sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    spell_slug = catalog.get("spell_slug") or "magic-missile"
    # v2.205.0: derive the spell display name from the slug so the
    # broadcast summary names the right spell (was hardcoded "Magic
    # Missile" pre-v2.205.0, which mis-labelled Fireball + the new
    # Lightning Bolt wand).
    spell_name = " ".join(p.capitalize() for p in str(spell_slug).split("-"))
    # v2.158.87: cast_slot_level = base + (charges - 1). MM base=1
    # so 1 charge → Lv 1; Fireball base=3 so 1 charge → Lv 3.
    base_slot = int(catalog.get("base_slot_level") or 1)
    cast_slot_level = base_slot + (charges - 1)

    try:
        await hub.broadcast(campaign_id, {
            "type": "resource_update",
            "data": {
                "character_id": char.id,
                "key": res_key,
                "current": res_row["current"],
                "max": res_max,
            },
        })
    except Exception:
        pass
    try:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "caster_char_name": char.name,
                "source": f"item-{slug}",
                "label": catalog.get("name") or "Use item",
                "summary": (
                    f"{char.name} expended {charges} charge(s) from the "
                    f"{item.get('name')} to cast {spell_name} at Lv "
                    f"{cast_slot_level}."
                ),
            },
        })
    except Exception:
        pass

    return {
        "ok": True,
        "item_name": item.get("name") or slug,
        "spell_slug": spell_slug,
        "charges_spent": charges,
        "cast_slot_level": cast_slot_level,
        "resource": {
            "key": res_key,
            "current": res_row["current"],
            "max": res_max,
        },
    }


async def _use_item_action_staff_of_healing(
    db, campaign_id, char, item, sheet, catalog,
    action_key, action_def, charges_raw,
):
    """v2.158.88 — Phase 4d Staff of Healing handler. Multi-action
    item with 3 distinct action_keys (cast-cure-wounds 1-4 charges,
    cast-lesser-restoration 2, cast-mass-cure-wounds 5). The
    action_def carries the per-action min/max charges + base slot
    level. RAW DMG p.202.
    """
    slug = "staff-of-healing"
    try:
        charges = int(charges_raw or 0)
    except (TypeError, ValueError):
        raise HTTPException(400, "charges must be an int")
    min_c = int(action_def.get("min_charges") or 1)
    max_c = int(action_def.get("max_charges") or 1)
    if charges < min_c or charges > max_c:
        raise HTTPException(
            400,
            f"charges must be {min_c}..{max_c} for "
            f"{action_def.get('name') or action_key}",
        )

    # Resource row lookup (mirror of the other handlers).
    resources = list(sheet.get("resources") or [])
    res_key = str(catalog.get("resource_key") or "")
    res_idx = -1
    for i, r in enumerate(resources):
        if isinstance(r, dict) and (r.get("key") or "").lower() == res_key:
            res_idx = i
            break
    if res_idx < 0:
        raise HTTPException(
            409,
            f"No {res_key!r} resource row on sheet — item not bootstrapped",
        )
    res_row = dict(resources[res_idx])
    cur = int(res_row.get("current") or 0)
    res_max = int(res_row.get("max") or 0)
    if cur < charges:
        return JSONResponse(
            status_code=409,
            content={
                "error": "insufficient_charges",
                "current": cur,
                "requested": charges,
                "label": item.get("name") or slug,
            },
        )

    res_row["current"] = cur - charges
    resources[res_idx] = res_row
    sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    spell_slug = action_def.get("spell_slug") or ""
    base_slot = int(action_def.get("base_slot_level") or 1)
    # Cast slot level scales only for cure-wounds (variable charges).
    # For fixed-charge actions (lesser-rest / mass-cure), cast level
    # equals base_slot.
    if max_c > min_c:
        cast_slot_level = base_slot + (charges - min_c)
    else:
        cast_slot_level = base_slot

    try:
        await hub.broadcast(campaign_id, {
            "type": "resource_update",
            "data": {
                "character_id": char.id,
                "key": res_key,
                "current": res_row["current"],
                "max": res_max,
            },
        })
    except Exception:
        pass
    try:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "caster_char_name": char.name,
                "source": f"item-{slug}",
                "label": action_def.get("name") or "Use Staff",
                "summary": (
                    f"{char.name} expended {charges} charge(s) from the "
                    f"{item.get('name')} to cast {spell_slug} at Lv "
                    f"{cast_slot_level}."
                ),
            },
        })
    except Exception:
        pass

    return {
        "ok": True,
        "item_name": item.get("name") or slug,
        "action_key": action_key,
        "spell_slug": spell_slug,
        "charges_spent": charges,
        "cast_slot_level": cast_slot_level,
        "resource": {
            "key": res_key,
            "current": res_row["current"],
            "max": res_max,
        },
    }


async def _use_item_action_flame_tongue(
    db, campaign_id, char, item, sheet,
    action_key, action_def, inv_idx,
):
    """v2.158.92 — Phase 5b Flame Tongue ignite/extinguish handler.
    Flips the inventory item's ``_lit`` field per action_def.to_state.
    Returns 409 if the requested state matches the current state
    (already lit / already extinguished). RAW DMG p.170.
    """
    slug = "flame-tongue"
    desired = bool(action_def.get("to_state"))
    currently_lit = bool(item.get("_lit"))
    if desired == currently_lit:
        verb = "lit" if currently_lit else "extinguished"
        return JSONResponse(
            status_code=409,
            content={
                "error": "no_state_change",
                "current": currently_lit,
                "label": item.get("name") or slug,
                "detail": f"{item.get('name')} is already {verb}.",
            },
        )

    inventory = list(sheet.get("inventory") or [])
    if inv_idx < 0 or inv_idx >= len(inventory):
        raise HTTPException(400, "inventory_index out of range")
    new_item = dict(inventory[inv_idx])
    new_item["_lit"] = desired
    inventory[inv_idx] = new_item
    sheet["inventory"] = inventory

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    summary_verb = "ignites" if desired else "extinguishes"
    try:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "caster_char_name": char.name,
                "source": f"item-{slug}",
                "label": action_def.get("name") or "Toggle Flame Tongue",
                "summary": (
                    f"{char.name} {summary_verb} the {item.get('name')}."
                ),
            },
        })
    except Exception:
        pass

    return {
        "ok": True,
        "item_name": item.get("name") or slug,
        "action_key": action_key,
        "lit": desired,
    }


async def _use_item_action_self_buff_potion(
    db, campaign_id, char, item, sheet, catalog, inv_idx,
    resistance_type=None,
):
    """v2.184.0 (Potion of Heroism) / v2.185.0 (Potion of Speed) —
    generic "self-buff" consumable handler. Drinking the potion buffs
    the DRINKER per the catalog's ``self_buff`` config: an optional
    flat (non-stacking) temp-HP grant + a buff from ``_SPELL_BUFF_MAP``
    installed on the drinker's own combatant, then the potion is
    consumed. The buff install is best-effort — it only lands when the
    drinker is in an active battle; the temp HP (if any) and the potion
    consumption apply either way.

    RAW: Potion of Heroism (DMG p.187) → 10 temp HP + Bless, 1 hour,
    no concentration. Potion of Speed (DMG p.187) → Haste, 1 minute,
    no concentration (no temp HP).
    """
    from sqlalchemy.orm.attributes import flag_modified

    spec = catalog.get("self_buff") or {}
    temp_amount = int(spec.get("temp_hp") or 0)

    # 1. Temp HP (non-stacking — the higher of existing / grant wins).
    #    Skipped entirely when the potion grants none (e.g. Speed).
    hp = dict(sheet.get("hp") or {})
    new_temp = int(hp.get("temp") or 0)
    if temp_amount > 0:
        new_temp = max(new_temp, temp_amount)
        hp["temp"] = new_temp
        sheet["hp"] = hp

    # 2. Consume the potion (decrement qty; drop the row at 0).
    inventory = list(sheet.get("inventory") or [])
    consumed = False
    remaining_qty = None
    if 0 <= inv_idx < len(inventory):
        new_item = dict(inventory[inv_idx])
        qty = int(new_item.get("qty") or 1)
        remaining_qty = max(0, qty - 1)
        consumed = True
        if remaining_qty <= 0:
            inventory.pop(inv_idx)
        else:
            new_item["qty"] = remaining_qty
            inventory[inv_idx] = new_item
        sheet["inventory"] = inventory

    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # 3. Bless buff on the drinker (best-effort — needs an active battle).
    buff_key = str(spec.get("buff_key") or "bless")
    # v2.187.0 / v2.188.0 — Potion of Resistance: RAW the drinker (GM) picks
    # the damage type. The type can come from the drink-time request
    # (`resistance_type` override — the type-picker) or fall back to the
    # item's seeded `resistance_type`. Either way we swap in the matching
    # typed template so one catalog entry covers all ten RAW damage types.
    # The template owns the name/icon for resistance potions.
    resist_type = None
    if buff_key.startswith("resistance"):
        rt = str(
            resistance_type or item.get("resistance_type") or ""
        ).strip().lower()
        if rt and f"resistance-{rt}" in _SPELL_BUFF_MAP:
            buff_key = f"resistance-{rt}"
            resist_type = rt
    buff_installed = False
    template = _SPELL_BUFF_MAP.get(buff_key) or {}
    if template:
        buff = dict(template)
        buff["effects"] = dict(template.get("effects") or {})
        buff["key"] = buff_key
        if resist_type:
            buff["name"] = template.get("name")
            buff["icon"] = template.get("icon")
        else:
            buff["name"] = spec.get("buff_name") or buff.get("name")
            if spec.get("icon"):
                buff["icon"] = spec["icon"]
        # v2.217.0 — Potion of Giant Strength tier. RAW DMG p.187 ships six
        # tiers (Hill STR 21 → Storm STR 29). The specific tier's STR set
        # value rides the inventory item via `_ability_set` (mirrors the Belt
        # of Giant Strength per-item override) and overrides the template's
        # Hill default. RAW "only if higher" is enforced downstream in
        # `effective_ability_score`. The buff name takes the item name so the
        # sheet override badge attributes the boost to the actual tier.
        item_aset = item.get("_ability_set")
        if buff_key == "giant-strength" and isinstance(item_aset, dict) and item_aset:
            eff = dict(buff.get("effects") or {})
            eff["ability_set"] = dict(item_aset)
            buff["effects"] = eff
            buff["name"] = item.get("name") or buff.get("name")
        # RAW: a potion's buff carries no concentration and runs its own
        # duration (e.g. Heroism's Bless = 1 hour, Speed's Haste = 1 min).
        buff["concentration"] = False
        _dur = int(spec.get("duration_rounds") or buff.get("duration_rounds") or 0)
        buff["duration_rounds"] = _dur
        buff["duration_max"] = _dur
        buff["source_char_id"] = char.id
        buff_installed = await _install_buff(campaign_id, char.id, buff)
        if buff_installed:
            _mirror_buffs_to_sheet(
                db, char.id, _get_buffs(campaign_id, char.id),
            )

    # 4. Broadcasts the client reads: HP meter (only when temp HP
    #    changed) + feature-used log line.
    item_name = item.get("name") or "Potion"
    if temp_amount > 0:
        try:
            await hub.broadcast(campaign_id, {
                "type": "character_hp_update",
                "data": {
                    "character_id": char.id,
                    "hp": hp,
                    "delta": 0,
                    "source": str(item.get("_slug") or "self-buff-potion"),
                },
            })
        except Exception:
            pass
    if resist_type:
        effect_text = f"resistance to {resist_type} damage for 1 hour"
    else:
        effect_text = spec.get("summary_effect") or f"the {buff_key} effect"
    try:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "caster_char_name": char.name,
                "source": f"item-{item.get('_slug') or 'self-buff-potion'}",
                "label": catalog.get("name") or f"Drink {item_name}",
                "summary": f"{char.name} drinks a {item_name}: {effect_text}.",
            },
        })
    except Exception:
        pass

    return {
        "ok": True,
        "item_name": item_name,
        "action_key": catalog.get("key") or "drink",
        "temp_hp": new_temp,
        "temp_hp_granted": temp_amount,
        "buff_installed": buff_installed,
        "buff_key": buff_key,
        "consumed": consumed,
        "remaining_qty": remaining_qty,
    }


async def _use_item_action_permanent_boost(
    db, campaign_id, char, item, sheet, catalog, inv_idx,
):
    """v2.222.0 — Manuals & Tomes: permanently raise one ability score by 2
    and consume the book. RAW DMG pp.180/208 — reading the book over 48
    hours within 6 days increases the score AND its maximum by 2, then the
    book loses its magic. Because the maximum rises too, the +2 always
    lands — there is no 20-cap clamp. This is a flat base-score edit
    (sheet.abilities[X] += 2), distinct from the timed self-buff potions
    and the equipped-item runtime overrides; the boosted base composes
    with those automatically via the existing effective_ability_score
    max(base, set) chain.
    """
    from sqlalchemy.orm.attributes import flag_modified

    spec = catalog.get("permanent_boost") or {}
    ability = str(spec.get("ability") or "").strip().upper()
    amount = int(spec.get("amount") or 0)
    if not ability or amount == 0:
        raise HTTPException(409, "item has no permanent_boost config")

    abilities = dict(sheet.get("abilities") or {})
    old_score = int(abilities.get(ability) or 10)
    new_score = old_score + amount
    abilities[ability] = new_score
    sheet["abilities"] = abilities

    # v2.312.0 — a CON increase retroactively raises max HP by the
    # CON-modifier delta per level (RAW PHB p.173). Bump BOTH max and
    # current by mod_delta × level so the new ceiling is immediately usable.
    # (Ported from the v2.309.0 /use_item ability_increase branch as Phase 1
    # of the permanent-ability-increase reconciliation; see
    # docs/plans/permanent-ability-increase-reconciliation.md.)
    hp_gain = 0
    if ability == "CON":
        mod_delta = (new_score // 2) - (old_score // 2)
        level = int(sheet.get("level") or 1)
        hp_gain = mod_delta * max(1, level)
        if hp_gain:
            hp = dict(sheet.get("hp") or {})
            hp["max"] = int(hp.get("max") or 0) + hp_gain
            hp["current"] = int(hp.get("current") or 0) + hp_gain
            sheet["hp"] = hp

    # Consume the book (decrement qty; drop the row at 0).
    inventory = list(sheet.get("inventory") or [])
    consumed = False
    remaining_qty = None
    if 0 <= inv_idx < len(inventory):
        new_item = dict(inventory[inv_idx])
        qty = int(new_item.get("qty") or 1)
        remaining_qty = max(0, qty - 1)
        consumed = True
        if remaining_qty <= 0:
            inventory.pop(inv_idx)
        else:
            new_item["qty"] = remaining_qty
            inventory[inv_idx] = new_item
        sheet["inventory"] = inventory

    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    item_name = item.get("name") or "Book"
    feature_name = spec.get("feature_name") or catalog.get("name") or f"Read {item_name}"
    effect_text = spec.get("summary_effect") or f"{ability} permanently +{amount}"
    if hp_gain:
        effect_text = f"{effect_text}; max HP +{hp_gain}"
    try:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "caster_char_name": char.name,
                "source": f"item-{item.get('_slug') or 'permanent-boost'}",
                "label": feature_name,
                "summary": (
                    f"{char.name} reads a {item_name}: {effect_text} "
                    f"({ability} {old_score} → {new_score})."
                ),
            },
        })
    except Exception:
        pass
    # Inventory panel re-render (the book is consumed).
    try:
        await hub.broadcast(campaign_id, {
            "type": "inventory_update",
            "data": {
                "character_id": char.id,
                "inventory_index": inv_idx if remaining_qty else -1,
                "item_name": item_name,
                "qty": remaining_qty or 0,
                "was_removed": not remaining_qty,
            },
        })
    except Exception:
        pass

    return {
        "ok": True,
        "item_name": item_name,
        "action_key": catalog.get("key") or "read",
        "ability": ability,
        "amount": amount,
        "old_score": old_score,
        "new_score": new_score,
        "hp_gain": hp_gain,
        "consumed": consumed,
        "remaining_qty": remaining_qty,
    }


async def _use_item_action_potion_of_fire_breath(
    db, campaign_id, char, item, sheet, catalog,
    action_key, action_def, inv_idx,
    target_combatant_ids: list,
    campaign=None,
    prompt_user=None,
):
    """v2.193.0 — Potion of Fire Breath (RAW DMG p.187, uncommon): the
    first OFFENSIVE consumable. Drinking exhales fire at the area — each
    target makes a DC 13 DEX save, 4d6 fire, half on a success — and the
    potion is consumed. Reuses the Necklace of Fireballs per-target save
    loop (``_resolve_feature_save`` → roll → ``_apply_damage_to_combatant``)
    but consumes the potion instead of decrementing a charge resource.
    The RAW 3-breaths-over-an-hour nuance is GM-narrated for now.
    """
    from sqlalchemy.orm.attributes import flag_modified

    slug = str(item.get("_slug") or "potion-of-fire-breath")
    if not isinstance(target_combatant_ids, list):
        raise HTTPException(400, "target_combatant_ids must be a list")
    if len(target_combatant_ids) > 24:
        raise HTTPException(400, "Too many targets for Potion of Fire Breath")

    save_dc = int(action_def.get("save_dc") or 13)
    save_ability = str(action_def.get("save_ability") or "DEX").upper()
    dice = str(action_def.get("dice") or "4d6")
    damage_type = str(action_def.get("damage_type") or "fire")
    save_for_half = bool(action_def.get("save_for_half"))

    results = []
    for tid in target_combatant_ids:
        if not isinstance(tid, str) or not tid:
            continue
        target_c = _lookup_combatant(campaign_id, tid)
        if not target_c:
            results.append({"combatant_id": tid, "reason": "not_found"})
            continue
        try:
            sr = await _resolve_feature_save(
                db, campaign_id,
                caster_char_id=int(char.id),
                caster_char_name=str(char.name or ""),
                target_combatant=target_c,
                save_ability=save_ability,
                dc=save_dc,
                note_label=f"Potion of Fire Breath (DC {save_dc} {save_ability})",
                condition_buff=None,
                repeated_save=False,
                source=f"item-{slug}-save",
                campaign=campaign,
                prompt_user=prompt_user,
                feature_name="🔥 Potion of Fire Breath",
            )
        except Exception:
            logging.exception(
                "Fire Breath save resolve failed for tid=%s", tid,
            )
            results.append({"combatant_id": tid, "reason": "save_error"})
            continue

        damage_dealt = 0
        if sr.get("passed") is not None:
            try:
                r = dice_mod.roll(dice)
                base = int(r.total)
            except dice_mod.DiceParseError:
                base = 0
            if base > 0:
                if sr.get("passed"):
                    if save_for_half:
                        damage_dealt = base // 2
                else:
                    damage_dealt = base
            if damage_dealt > 0:
                try:
                    await _apply_damage_to_combatant(
                        db, campaign_id, target_c,
                        damage_amount=damage_dealt,
                        damage_type=damage_type,
                        is_attack=False, is_magical=True,
                        attacker_char_id=char.id,
                    )
                except Exception:
                    logging.exception(
                        "Fire Breath damage apply failed for tid=%s", tid,
                    )
        results.append({
            "combatant_id": tid,
            "name": target_c.get("name") or "Target",
            "passed": sr.get("passed"),
            "damage_dealt": damage_dealt,
        })

    # Consume the potion (decrement qty; drop the row at 0).
    inventory = list(sheet.get("inventory") or [])
    consumed = False
    remaining_qty = None
    if 0 <= inv_idx < len(inventory):
        new_item = dict(inventory[inv_idx])
        qty = int(new_item.get("qty") or 1)
        remaining_qty = max(0, qty - 1)
        consumed = True
        if remaining_qty <= 0:
            inventory.pop(inv_idx)
        else:
            new_item["qty"] = remaining_qty
            inventory[inv_idx] = new_item
        sheet["inventory"] = inventory
        char.sheet = sheet
        flag_modified(char, "sheet")
        db.commit()

    item_name = item.get("name") or "Potion of Fire Breath"
    try:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "caster_char_name": char.name,
                "source": f"item-{slug}",
                "label": "🔥 Potion of Fire Breath",
                "summary": (
                    f"{char.name} drinks a {item_name} and exhales fire "
                    f"({dice} fire, DC {save_dc} {save_ability} save for half) "
                    f"— {len(results)} save(s) resolved."
                ),
            },
        })
    except Exception:
        pass

    return {
        "ok": True,
        "item_name": item_name,
        "action_key": action_key,
        "dice": dice,
        "save_dc": save_dc,
        "save_ability": save_ability,
        "results": results,
        "consumed": consumed,
        "remaining_qty": remaining_qty,
    }


async def _use_item_action_potion_of_mind_reading(
    db, campaign_id, char, item, sheet, catalog,
    action_key, action_def, inv_idx,
    target_combatant_ids: list,
    campaign=None,
    prompt_user=None,
):
    """v2.197.0 — Potion of Mind Reading (RAW DMG p.187, rare): drink →
    the detect thoughts effect (each probed creature makes a DC 13 WIS
    save; on a failure you read its surface thoughts). v1 models the
    probe as a WIS save that consumes the potion — no damage, the
    thought-reading itself is GM-narrated. Reuses the Fire Breath
    per-target save loop without the damage roll.

    v2.202.0 — generalised to back any save-imposing, no-damage potion:
    the feature label / verb come from the catalog `action_def` with
    Mind-Reading fallbacks, so Potion of Animal Friendship routes through
    the same loop (WIS DC 13, GM-narrated charm).
    """
    from sqlalchemy.orm.attributes import flag_modified

    slug = str(item.get("_slug") or "potion-of-mind-reading")
    default_name = item.get("name") or "Potion of Mind Reading"
    feature_name = str(action_def.get("feature_name") or "🧠 Potion of Mind Reading")
    summary_verb = str(action_def.get("summary_verb") or "probes minds")
    if not isinstance(target_combatant_ids, list):
        raise HTTPException(400, "target_combatant_ids must be a list")
    if len(target_combatant_ids) > 24:
        raise HTTPException(400, f"Too many targets for {default_name}")

    save_dc = int(action_def.get("save_dc") or 13)
    save_ability = str(action_def.get("save_ability") or "WIS").upper()

    results = []
    for tid in target_combatant_ids:
        if not isinstance(tid, str) or not tid:
            continue
        target_c = _lookup_combatant(campaign_id, tid)
        if not target_c:
            results.append({"combatant_id": tid, "reason": "not_found"})
            continue
        try:
            sr = await _resolve_feature_save(
                db, campaign_id,
                caster_char_id=int(char.id),
                caster_char_name=str(char.name or ""),
                target_combatant=target_c,
                save_ability=save_ability,
                dc=save_dc,
                note_label=f"{default_name} (DC {save_dc} {save_ability})",
                condition_buff=None,
                repeated_save=False,
                source=f"item-{slug}-save",
                campaign=campaign,
                prompt_user=prompt_user,
                feature_name=feature_name,
            )
        except Exception:
            logging.exception(
                "Mind Reading save resolve failed for tid=%s", tid,
            )
            results.append({"combatant_id": tid, "reason": "save_error"})
            continue
        results.append({
            "combatant_id": tid,
            "name": target_c.get("name") or "Target",
            "passed": sr.get("passed"),
        })

    # Consume the potion (decrement qty; drop the row at 0).
    inventory = list(sheet.get("inventory") or [])
    consumed = False
    remaining_qty = None
    if 0 <= inv_idx < len(inventory):
        new_item = dict(inventory[inv_idx])
        qty = int(new_item.get("qty") or 1)
        remaining_qty = max(0, qty - 1)
        consumed = True
        if remaining_qty <= 0:
            inventory.pop(inv_idx)
        else:
            new_item["qty"] = remaining_qty
            inventory[inv_idx] = new_item
        sheet["inventory"] = inventory
        char.sheet = sheet
        flag_modified(char, "sheet")
        db.commit()

    item_name = default_name
    try:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "caster_char_name": char.name,
                "source": f"item-{slug}",
                "label": feature_name,
                "summary": (
                    f"{char.name} drinks a {item_name} and {summary_verb} "
                    f"(DC {save_dc} {save_ability} save) "
                    f"— {len(results)} save(s) resolved."
                ),
            },
        })
    except Exception:
        pass

    return {
        "ok": True,
        "item_name": item_name,
        "action_key": action_key,
        "save_dc": save_dc,
        "save_ability": save_ability,
        "results": results,
        "consumed": consumed,
        "remaining_qty": remaining_qty,
    }


async def _use_item_action_javelin_of_lightning(
    db, campaign_id, char, item, sheet,
    action_key, action_def, inv_idx,
    target_combatant_ids: list,
    campaign=None,
    prompt_user=None,
):
    """v2.159.3 — Phase 8c Javelin of Lightning handler. RAW DMG p.178:
    on throw + command word, a 5-ft-wide line of lightning extends to
    the target (120 ft max). Each creature in the line (excluding the
    caster + target) makes a DC 13 DEX save → 4d6 lightning (half on
    pass). The javelin then lands at the target's feet — the player
    fires their normal Javelin attack as a follow-up. v1 models only
    the lightning save chain; the GM picks `target_combatant_ids`
    (the creatures in the line per their tactical read of the map).

    Item state: ``_used_today`` flag — flips True on use, blocks
    re-use until next long rest (RAW: "until the next dawn"). The
    rest endpoint clears the flag in v2.159.3 alongside its existing
    resource recharge.
    """
    slug = "javelin-of-lightning"
    state_field = str(action_def.get("state_field") or "_used_today")
    block_value = action_def.get("state_block_value", True)
    if item.get(state_field) == block_value:
        return JSONResponse(
            status_code=409,
            content={
                "error": "spent_until_dawn",
                "current_state": True,
                "label": item.get("name") or slug,
                "detail": (
                    f"{item.get('name') or 'Javelin of Lightning'} has "
                    f"already discharged today. Recharges on a long rest."
                ),
            },
        )

    if not isinstance(target_combatant_ids, list):
        raise HTTPException(400, "target_combatant_ids must be a list")
    # Cap target count for hub safety — the line can plausibly cross
    # ~10 creatures at most.
    if len(target_combatant_ids) > 24:
        raise HTTPException(400, "Too many targets for Javelin of Lightning")

    save_dc = int(action_def.get("save_dc") or 13)
    save_ability = str(action_def.get("save_ability") or "DEX").upper()
    dice = str(action_def.get("dice") or "4d6")
    damage_type = str(action_def.get("damage_type") or "lightning")
    save_for_half = bool(action_def.get("save_for_half"))

    # Resolve each target's save + apply damage.
    results = []
    for tid in target_combatant_ids:
        if not isinstance(tid, str) or not tid:
            continue
        target_c = _lookup_combatant(campaign_id, tid)
        if not target_c:
            results.append({"combatant_id": tid, "reason": "not_found"})
            continue
        try:
            sr = await _resolve_feature_save(
                db, campaign_id,
                caster_char_id=int(char.id),
                caster_char_name=str(char.name or ""),
                target_combatant=target_c,
                save_ability=save_ability,
                dc=save_dc,
                note_label=f"Javelin of Lightning (DC {save_dc} {save_ability})",
                condition_buff=None,
                repeated_save=False,
                source=f"item-{slug}-save",
                campaign=campaign,
                prompt_user=prompt_user,
                feature_name="⚡ Javelin of Lightning",
            )
        except Exception:
            logging.exception(
                "Javelin of Lightning save resolve failed for tid=%s", tid,
            )
            results.append({"combatant_id": tid, "reason": "save_error"})
            continue

        damage_dealt = 0
        if sr.get("passed") is not None:
            try:
                r = dice_mod.roll(dice)
                base = int(r.total)
            except dice_mod.DiceParseError:
                base = 0
            if base > 0:
                if sr.get("passed"):
                    if save_for_half:
                        damage_dealt = base // 2
                else:
                    damage_dealt = base
            if damage_dealt > 0:
                try:
                    await _apply_damage_to_combatant(
                        db, campaign_id, target_c,
                        damage_amount=damage_dealt,
                        damage_type=damage_type,
                        is_attack=False, is_magical=True,
                        attacker_char_id=char.id,
                    )
                except Exception:
                    logging.exception(
                        "Javelin lightning damage apply failed for tid=%s",
                        tid,
                    )
        results.append({
            "combatant_id": tid,
            "name": target_c.get("name") or "Target",
            "passed": sr.get("passed"),
            "damage_dealt": damage_dealt,
        })

    # Flip the item's state field to mark spent-until-dawn.
    inventory = list(sheet.get("inventory") or [])
    if 0 <= inv_idx < len(inventory):
        new_item = dict(inventory[inv_idx])
        new_item[state_field] = block_value
        inventory[inv_idx] = new_item
        sheet["inventory"] = inventory
        from sqlalchemy.orm.attributes import flag_modified
        char.sheet = sheet
        flag_modified(char, "sheet")
        db.commit()

    # Broadcast a summary.
    target_names = ", ".join(
        r.get("name", "?") for r in results if "name" in r
    ) or "no targets"
    try:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "caster_char_name": char.name,
                "source": f"item-{slug}",
                "label": "⚡ Javelin of Lightning",
                "summary": (
                    f"{char.name} hurls the {item.get('name')} — lightning "
                    f"arcs through {target_names}. "
                    f"({len(results)} save(s) resolved.)"
                ),
            },
        })
    except Exception:
        pass

    return {
        "ok": True,
        "item_name": item.get("name") or slug,
        "action_key": action_key,
        "spent_until_dawn": True,
        "save_dc": save_dc,
        "save_ability": save_ability,
        "results": results,
    }


# v2.273.0 — charged-items Phase 4: the Wand of Wonder d100 chaos table
# (RAW DMG p.213). Each row is an inclusive ``[lo, hi]`` band on a d100
# roll; ``key`` is a stable machine slug, ``effect`` is the short label,
# and ``desc`` is the GM-narration text. Per-row sub-effects (spell
# casts, damage bursts, transformations) are GM-adjudicated in v1 — the
# handler reports the rolled row and the GM resolves it.
_WAND_OF_WONDER_TABLE = [
    {"lo": 1, "hi": 5, "key": "slow",
     "effect": "Slow the target",
     "desc": "You cast slow on the target (or yourself if no creature is in range)."},
    {"lo": 6, "hi": 10, "key": "faerie-fire",
     "effect": "Faerie fire on the target",
     "desc": "You cast faerie fire on the target."},
    {"lo": 11, "hi": 15, "key": "stunned-self",
     "effect": "You are stunned until your next turn",
     "desc": "You are stunned until the start of your next turn, believing something awesome just happened."},
    {"lo": 16, "hi": 20, "key": "gust-of-wind",
     "effect": "Gust of wind",
     "desc": "You cast gust of wind."},
    {"lo": 21, "hi": 25, "key": "detect-thoughts",
     "effect": "Detect thoughts on the target",
     "desc": "You cast detect thoughts on the target. If you didn't target a creature, you take 1d6 psychic damage."},
    {"lo": 26, "hi": 30, "key": "stinking-cloud",
     "effect": "Stinking cloud",
     "desc": "You cast stinking cloud."},
    {"lo": 31, "hi": 33, "key": "heavy-rain",
     "effect": "Heavy rain, 60-ft radius",
     "desc": "Heavy rain falls in a 60-ft radius centered on a point within 100 ft, until the start of your next turn."},
    {"lo": 34, "hi": 36, "key": "summon-animal",
     "effect": "An animal appears (rhino / elephant / rat)",
     "desc": "An animal appears within 5 ft of the target: 01-25 a rhinoceros, 26-50 an elephant, 51-100 a rat (roll d100)."},
    {"lo": 37, "hi": 46, "key": "lightning-bolt",
     "effect": "Lightning bolt",
     "desc": "You cast lightning bolt."},
    {"lo": 47, "hi": 49, "key": "butterflies",
     "effect": "600 butterflies, 30-ft heavily obscured",
     "desc": "A cloud of 600 large butterflies fills a 30-ft square, heavily obscuring it, for 10 minutes."},
    {"lo": 50, "hi": 53, "key": "enlarge-target",
     "effect": "Enlarge the target",
     "desc": "The target enlarges, as the enlarge effect of enlarge/reduce, for 1 minute."},
    {"lo": 54, "hi": 58, "key": "darkness",
     "effect": "Darkness",
     "desc": "You cast darkness."},
    {"lo": 59, "hi": 62, "key": "grass-grows",
     "effect": "Grass grows, 60-ft radius",
     "desc": "Grass grows in a 60-ft radius centered on a point within 100 ft, or withers existing grass there."},
    {"lo": 63, "hi": 65, "key": "object-ethereal",
     "effect": "An object becomes ethereal",
     "desc": "A nonmagical object (up to 1,000 lb, Large or smaller) within 120 ft becomes ethereal for 1 minute."},
    {"lo": 66, "hi": 69, "key": "shrink-self",
     "effect": "You shrink",
     "desc": "You shrink, as the reduce effect of enlarge/reduce, for 1 minute."},
    {"lo": 70, "hi": 79, "key": "fireball",
     "effect": "Fireball",
     "desc": "You cast fireball."},
    {"lo": 80, "hi": 84, "key": "invisibility-self",
     "effect": "Invisibility on yourself",
     "desc": "You cast invisibility on yourself."},
    {"lo": 85, "hi": 87, "key": "leaves-grow",
     "effect": "Leaves grow from the target",
     "desc": "Leaves grow from the target for 24 hours; they wither and fall off after that."},
    {"lo": 88, "hi": 90, "key": "gem-stream",
     "effect": "Stream of gems (bludgeoning line)",
     "desc": "1d4 × 10 gems (1 gp each) shoot in a 30-ft line, 5 ft wide; total 1 bludgeoning damage per gem, split among creatures in the line."},
    {"lo": 91, "hi": 95, "key": "blinding-light",
     "effect": "Blinding light, 30-ft cone (DC 15 CON)",
     "desc": "Colorful light bursts in a 30-ft cone; each creature there makes a DC 15 CON save or is blinded for 1 minute."},
    {"lo": 96, "hi": 97, "key": "skin-blue",
     "effect": "Target's skin turns blue",
     "desc": "The target's skin turns bright blue for 1d6 days (the object's owner instead, if you rolled on an object)."},
    {"lo": 98, "hi": 100, "key": "petrify",
     "effect": "Petrify the target (DC 15 CON)",
     "desc": "The target must make a DC 15 CON save or be restrained, then petrified, as it turns to stone (repeated save at the end of each of its turns; 3 failures = petrified, 3 successes = ends)."},
]


def _wand_of_wonder_row(roll: int) -> dict:
    """Return the d100 table row whose inclusive band contains ``roll``."""
    for row in _WAND_OF_WONDER_TABLE:
        if row["lo"] <= roll <= row["hi"]:
            return row
    return _WAND_OF_WONDER_TABLE[-1]


async def _use_item_action_wand_of_wonder(
    db, campaign_id, char, item, sheet, catalog,
    action_key, action_def,
    charges=None,
    force_roll=None,
    slug="wand-of-wonder",
):
    """v2.273.0 — charged-items Phase 4: the first
    ``action_kind: "random_table"`` charge action. Spends 1 charge and
    rolls d100 on the Wand of Wonder chaos table; the rolled row names
    the effect for the GM to narrate/resolve.

    RAW Wand of Wonder (DMG p.213, rare, attunement by a spellcaster):
    7 charges (regains 1d6+1 at dawn). ``force_roll`` (1-100) overrides
    the random roll — used for deterministic tests and for a GM who
    wants to pick the outcome.
    """
    res_key = str(catalog.get("resource_key") or slug)
    min_c = int(action_def.get("min_charges") or 1)
    max_c = int(action_def.get("max_charges") or 1)
    try:
        n_charges = int(charges) if charges is not None else min_c
    except (TypeError, ValueError):
        raise HTTPException(400, "charges must be an int")
    if n_charges < min_c or n_charges > max_c:
        raise HTTPException(
            400,
            f"charges must be {min_c}..{max_c} for "
            f"{action_def.get('name') or action_key}",
        )

    # Resource lookup + insufficient-charges gate.
    resources = list(sheet.get("resources") or [])
    res_idx = -1
    for i, r in enumerate(resources):
        if isinstance(r, dict) and (r.get("key") or "").lower() == res_key:
            res_idx = i
            break
    if res_idx < 0:
        raise HTTPException(
            409,
            f"No {res_key!r} resource row on sheet — item not bootstrapped",
        )
    res_row = dict(resources[res_idx])
    cur = int(res_row.get("current") or 0)
    res_max = int(res_row.get("max") or 0)
    if cur < n_charges:
        return JSONResponse(
            status_code=409,
            content={
                "error": "insufficient_charges",
                "current": cur,
                "requested": n_charges,
                "label": item.get("name") or slug,
            },
        )

    feature_name = str(action_def.get("feature_name") or "🎲 Wand of Wonder")

    # Roll d100 (or honor the force_roll override, clamped 1..100).
    if force_roll is not None:
        try:
            roll = max(1, min(100, int(force_roll)))
        except (TypeError, ValueError):
            raise HTTPException(400, "force_roll must be an int")
    else:
        import random as _rand
        roll = _rand.randint(1, 100)
    row = _wand_of_wonder_row(roll)

    # Decrement the charge.
    res_row["current"] = cur - n_charges
    resources[res_idx] = res_row
    sheet["resources"] = resources
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    try:
        await hub.broadcast(campaign_id, {
            "type": "resource_update",
            "data": {
                "character_id": char.id,
                "key": res_key,
                "current": res_row["current"],
                "max": res_max,
            },
        })
    except Exception:
        pass
    try:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "caster_char_name": char.name,
                "source": f"item-{slug}",
                "label": feature_name,
                "summary": (
                    f"{char.name} unleashes the {item.get('name')} — "
                    f"d100 = {roll}: {row['effect']}. {row['desc']} "
                    f"({res_row['current']}/{res_max} charges left.)"
                ),
            },
        })
    except Exception:
        pass

    return {
        "ok": True,
        "item_name": item.get("name") or slug,
        "action_key": action_key,
        "action_kind": "random_table",
        "charges_spent": n_charges,
        "roll": roll,
        "row_key": row["key"],
        "effect": row["effect"],
        "description": row["desc"],
        "resource": {
            "key": res_key,
            "current": res_row["current"],
            "max": res_max,
        },
    }


async def _use_item_action_buff(
    db, campaign_id, char, item, sheet, catalog,
    action_key, action_def,
    charges=None,
    slug="gem-of-seeing",
):
    """v2.270.0 — charged-items Phase 3: the first ``action_kind: "buff"``
    charge action. Spends charges to install a timed self-buff on the
    wielder's own combatant instead of resolving a spell cast (wand shape
    #1), an AoE save (staff shape #2), or an attack roll (Ring of the Ram).

    RAW Gem of Seeing (DMG p.171): spend 1 of 3 charges to gain truesight
    60 ft for 10 minutes. The buff template comes from ``_SPELL_BUFF_MAP``
    keyed by the action's ``buff_key``; the duration comes from the
    action_def. The install is best-effort — it only lands when the
    wielder is in an active battle (same as the self-buff potions); the
    charge is decremented either way.
    """
    res_key = str(catalog.get("resource_key") or slug)
    min_c = int(action_def.get("min_charges") or 1)
    max_c = int(action_def.get("max_charges") or 1)
    try:
        n_charges = int(charges) if charges is not None else min_c
    except (TypeError, ValueError):
        raise HTTPException(400, "charges must be an int")
    if n_charges < min_c or n_charges > max_c:
        raise HTTPException(
            400,
            f"charges must be {min_c}..{max_c} for "
            f"{action_def.get('name') or action_key}",
        )

    # Resource lookup + insufficient-charges gate.
    resources = list(sheet.get("resources") or [])
    res_idx = -1
    for i, r in enumerate(resources):
        if isinstance(r, dict) and (r.get("key") or "").lower() == res_key:
            res_idx = i
            break
    if res_idx < 0:
        raise HTTPException(
            409,
            f"No {res_key!r} resource row on sheet — item not bootstrapped",
        )
    res_row = dict(resources[res_idx])
    cur = int(res_row.get("current") or 0)
    res_max = int(res_row.get("max") or 0)
    if cur < n_charges:
        return JSONResponse(
            status_code=409,
            content={
                "error": "insufficient_charges",
                "current": cur,
                "requested": n_charges,
                "label": item.get("name") or slug,
            },
        )

    buff_key = str(action_def.get("buff_key") or "")
    feature_name = str(action_def.get("feature_name") or "💎 Gem of Seeing")

    # Decrement the charges first (the buff install is best-effort).
    res_row["current"] = cur - n_charges
    resources[res_idx] = res_row
    sheet["resources"] = resources
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # Install the timed self-buff on the wielder's own combatant.
    buff_installed = False
    template = _SPELL_BUFF_MAP.get(buff_key) or {}
    if template:
        buff = dict(template)
        buff["effects"] = dict(template.get("effects") or {})
        buff["key"] = buff_key
        buff["concentration"] = False
        _dur = int(
            action_def.get("duration_rounds")
            or buff.get("duration_rounds") or 0
        )
        buff["duration_rounds"] = _dur
        buff["duration_max"] = _dur
        buff["source_char_id"] = char.id
        buff_installed = await _install_buff(campaign_id, char.id, buff)
        if buff_installed:
            _mirror_buffs_to_sheet(
                db, char.id, _get_buffs(campaign_id, char.id),
            )

    try:
        await hub.broadcast(campaign_id, {
            "type": "resource_update",
            "data": {
                "character_id": char.id,
                "key": res_key,
                "current": res_row["current"],
                "max": res_max,
            },
        })
    except Exception:
        pass
    effect_text = action_def.get("summary_effect") or f"the {buff_key} effect"
    verb = str(action_def.get("summary_verb") or "gazes through")
    try:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "caster_char_name": char.name,
                "source": f"item-{slug}",
                "label": feature_name,
                "summary": (
                    f"{char.name} {verb} the {item.get('name')} — "
                    f"gains {effect_text}. "
                    f"({n_charges} charge{'s' if n_charges > 1 else ''}; "
                    f"{res_row['current']}/{res_max} left.)"
                ),
            },
        })
    except Exception:
        pass

    return {
        "ok": True,
        "item_name": item.get("name") or slug,
        "action_key": action_key,
        "action_kind": "buff",
        "charges_spent": n_charges,
        "buff_key": buff_key,
        "buff_installed": buff_installed,
        "duration_rounds": int(action_def.get("duration_rounds") or 0),
        "resource": {
            "key": res_key,
            "current": res_row["current"],
            "max": res_max,
        },
    }


async def _use_item_action_attack(
    db, campaign_id, char, item, sheet, catalog,
    action_key, action_def,
    target_combatant_ids: list,
    charges=None,
    campaign=None,
    prompt_user=None,
    slug="ring-of-the-ram",
):
    """v2.269.0 — charged-items Phase 3: the FIRST non-spell charge
    action (``action_kind: "attack"``). Spends charges to make a ranged
    attack roll (1d20 + ``to_hit`` vs the target's AC) that deals
    ``dice_per_charge`` damage *per charge spent* on a hit, instead of
    resolving a catalogued spell cast.

    RAW Ring of the Ram (DMG p.193, rare, attunement): +7 to hit, 2d10
    force per charge (1-3 charges), 60-ft range, shove on hit (the shove
    is GM-narrated in v1). Reuses the /attack endpoint's
    nat-20-crit / nat-1-miss / AC-compare resolution. Single-target —
    only the first valid id in ``target_combatant_ids`` is used.
    """
    res_key = str(catalog.get("resource_key") or slug)
    min_c = int(action_def.get("min_charges") or 1)
    max_c = int(action_def.get("max_charges") or 1)
    try:
        n_charges = int(charges) if charges is not None else min_c
    except (TypeError, ValueError):
        raise HTTPException(400, "charges must be an int")
    if n_charges < min_c or n_charges > max_c:
        raise HTTPException(
            400,
            f"charges must be {min_c}..{max_c} for "
            f"{action_def.get('name') or action_key}",
        )

    # Resource lookup + insufficient-charges gate (mirrors the necklace
    # handler so the contract is identical across charge shapes).
    resources = list(sheet.get("resources") or [])
    res_idx = -1
    for i, r in enumerate(resources):
        if isinstance(r, dict) and (r.get("key") or "").lower() == res_key:
            res_idx = i
            break
    if res_idx < 0:
        raise HTTPException(
            409,
            f"No {res_key!r} resource row on sheet — item not bootstrapped",
        )
    res_row = dict(resources[res_idx])
    cur = int(res_row.get("current") or 0)
    res_max = int(res_row.get("max") or 0)
    if cur < n_charges:
        return JSONResponse(
            status_code=409,
            content={
                "error": "insufficient_charges",
                "current": cur,
                "requested": n_charges,
                "label": item.get("name") or slug,
            },
        )

    if not isinstance(target_combatant_ids, list):
        raise HTTPException(400, "target_combatant_ids must be a list")
    target_id = next(
        (t for t in target_combatant_ids if isinstance(t, str) and t), None,
    )
    if not target_id:
        raise HTTPException(400, "target_combatant_ids must be non-empty")
    target_c = _lookup_combatant(campaign_id, target_id)
    if not target_c:
        raise HTTPException(404, f"target {target_id!r} not found")

    to_hit = int(action_def.get("to_hit") or 0)
    per_charge = str(action_def.get("dice_per_charge") or "2d10")
    damage_type = str(action_def.get("damage_type") or "force")
    feature_name = str(action_def.get("feature_name") or "💍 Ring of the Ram")

    # Build the damage expression: dice_per_charge scales by charges spent
    # (RAW 2d10 force *per charge* → 2/4/6d10).
    _dm = _re.match(r"\s*(\d+)d(\d+)\s*$", per_charge)
    if _dm:
        dmg_expr = f"{int(_dm.group(1)) * n_charges}d{int(_dm.group(2))}"
    else:
        dmg_expr = per_charge

    # To-hit roll vs the target's AC (same resolution as /attack).
    target_ac = _read_target_ac(db, campaign_id, target_c)
    try:
        _ar = dice_mod.roll(f"1d20{to_hit:+d}")
        attack_total, _abd = int(_ar.total), _ar.breakdown
    except dice_mod.DiceParseError:
        attack_total, _abd = 0, ""
    _nat_m = _re.search(r"\[(\d+)\]", _abd)
    nat = int(_nat_m.group(1)) if _nat_m else (attack_total - to_hit)
    if nat == 20:
        hit, crit = True, True
    elif nat == 1:
        hit, crit = False, False
    else:
        hit, crit = (attack_total >= target_ac), False

    damage_dealt = 0
    if hit:
        roll_expr = _double_dice_for_crit(dmg_expr) if crit else dmg_expr
        try:
            damage_dealt = max(0, int(dice_mod.roll(roll_expr).total))
        except dice_mod.DiceParseError:
            damage_dealt = 0
        if damage_dealt > 0:
            try:
                await _apply_damage_to_combatant(
                    db, campaign_id, target_c,
                    damage_amount=damage_dealt,
                    damage_type=damage_type,
                    is_crit=crit, is_attack=True, is_magical=True,
                    attacker_char_id=char.id,
                )
            except Exception:
                logging.exception(
                    "Ring of the Ram damage apply failed for tid=%s",
                    target_id,
                )

    # Decrement the charges.
    res_row["current"] = cur - n_charges
    resources[res_idx] = res_row
    sheet["resources"] = resources
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    try:
        await hub.broadcast(campaign_id, {
            "type": "resource_update",
            "data": {
                "character_id": char.id,
                "key": res_key,
                "current": res_row["current"],
                "max": res_max,
            },
        })
    except Exception:
        pass
    try:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "caster_char_name": char.name,
                "source": f"item-{slug}",
                "label": feature_name,
                "summary": (
                    f"{char.name} fires the {item.get('name')} at "
                    f"{target_c.get('name') or 'the target'} — "
                    f"{'HIT' if hit else 'MISS'}"
                    f"{' (CRIT!)' if crit else ''} "
                    f"(d20 {attack_total} vs AC {target_ac}). "
                    + (
                        f"{damage_dealt} {damage_type} damage. "
                        if hit else ""
                    )
                    + f"({n_charges} charge{'s' if n_charges > 1 else ''}; "
                    f"{res_row['current']}/{res_max} left.)"
                ),
            },
        })
    except Exception:
        pass

    return {
        "ok": True,
        "item_name": item.get("name") or slug,
        "action_key": action_key,
        "action_kind": "attack",
        "charges_spent": n_charges,
        "to_hit": to_hit,
        "attack_total": attack_total,
        "target_ac": target_ac,
        "hit": hit,
        "crit": crit,
        "dice": dmg_expr,
        "damage_type": damage_type,
        "damage": damage_dealt,
        "target_combatant_id": target_id,
        "resource": {
            "key": res_key,
            "current": res_row["current"],
            "max": res_max,
        },
    }


async def _use_item_action_horn_of_blasting(
    db, campaign_id, char, item, sheet, catalog,
    action_key, action_def,
    target_combatant_ids: list,
    campaign=None,
    prompt_user=None,
    slug="horn-of-blasting",
):
    """v2.271.0 — charged-items Phase 3 (closes the phase): Horn of
    Blasting handler. RAW DMG p.174 (uncommon, NO attunement): blow the
    horn to emit a thunderous blast in a 30-ft cone; each creature makes a
    DC 15 CON save → 5d6 thunder + deafened 1 minute on a fail, half
    damage + no deafen on a pass.

    Mirrors ``_use_item_action_necklace_of_fireballs``'s save-for-half
    AoE-damage loop but with two differences: (1) the horn has NO charges
    — there is no resource row, no charge gate, no ``resource_update``
    broadcast (the RAW 20% self-destruct per blow is GM-narrated in v1);
    (2) a ``deafened`` condition rides the same ``_resolve_feature_save``
    call via ``condition_buff``, so it installs only on a FAILED save (the
    RAW-correct behaviour — a passing creature takes half damage and is
    NOT deafened).
    """
    if not isinstance(target_combatant_ids, list):
        raise HTTPException(400, "target_combatant_ids must be a list")
    if len(target_combatant_ids) > 24:
        raise HTTPException(400, "Too many targets for Horn of Blasting")

    raw_dc = action_def.get("save_dc")
    if isinstance(raw_dc, str) and raw_dc.strip().lower() == "spell":
        save_dc = _compute_spell_save_dc_from_sheet(sheet)
    else:
        save_dc = int(raw_dc or 15)
    save_ability = str(action_def.get("save_ability") or "CON").upper()
    dice = str(action_def.get("dice") or "5d6")
    damage_type = str(action_def.get("damage_type") or "thunder")
    save_for_half = bool(action_def.get("save_for_half", True))
    feature_name = str(action_def.get("feature_name") or "📯 Horn of Blasting")
    item_name = item.get("name") or slug

    cond_key = str(action_def.get("condition_key") or "deafened")
    cond_label = str(action_def.get("condition_label") or "Deafened")
    cond_icon = str(action_def.get("condition_icon") or "🔇")
    cond_dur = int(action_def.get("condition_duration_rounds") or 10)
    cond_effects = action_def.get("condition_effects") or [
        "can't hear, automatically fails any ability check requiring hearing",
    ]
    condition_buff = {
        "key": cond_key,
        "name": f"{cond_label} ({item_name} — {char.name})",
        "icon": cond_icon,
        "duration_rounds": cond_dur,
        "duration_max": cond_dur,
        "concentration": False,
        "source_item": slug,
        "effects": list(cond_effects),
    }

    results = []
    for tid in target_combatant_ids:
        if not isinstance(tid, str) or not tid:
            continue
        target_c = _lookup_combatant(campaign_id, tid)
        if not target_c:
            results.append({"combatant_id": tid, "reason": "not_found"})
            continue
        try:
            sr = await _resolve_feature_save(
                db, campaign_id,
                caster_char_id=int(char.id),
                caster_char_name=str(char.name or ""),
                target_combatant=target_c,
                save_ability=save_ability,
                dc=save_dc,
                note_label=f"{item_name} (DC {save_dc} {save_ability})",
                condition_buff=condition_buff,
                repeated_save=False,
                source=f"item-{slug}-save",
                campaign=campaign,
                prompt_user=prompt_user,
                feature_name=feature_name,
            )
        except Exception:
            logging.exception(
                "Horn of Blasting save resolve failed for tid=%s", tid,
            )
            results.append({"combatant_id": tid, "reason": "save_error"})
            continue

        damage_dealt = 0
        if sr.get("passed") is not None:
            try:
                r = dice_mod.roll(dice)
                base = int(r.total)
            except dice_mod.DiceParseError:
                base = 0
            if base > 0:
                if sr.get("passed"):
                    if save_for_half:
                        damage_dealt = base // 2
                else:
                    damage_dealt = base
            if damage_dealt > 0:
                try:
                    await _apply_damage_to_combatant(
                        db, campaign_id, target_c,
                        damage_amount=damage_dealt,
                        damage_type=damage_type,
                        is_attack=False, is_magical=True,
                        attacker_char_id=char.id,
                    )
                except Exception:
                    logging.exception(
                        "Horn of Blasting damage apply failed for tid=%s", tid,
                    )
        results.append({
            "combatant_id": tid,
            "name": target_c.get("name") or "Target",
            "passed": sr.get("passed"),
            "damage_dealt": damage_dealt,
            # RAW: deafened installs only on a failed save.
            "deafened": (sr.get("passed") is False),
        })

    try:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "caster_char_name": char.name,
                "source": f"item-{slug}",
                "label": feature_name,
                "summary": (
                    f"{char.name} sounds the {item_name} — DC {save_dc} "
                    f"{save_ability} 30-ft cone, {dice} {damage_type} + "
                    f"deafened on a fail ({len(results)} save(s) resolved)."
                ),
            },
        })
    except Exception:
        pass

    return {
        "ok": True,
        "item_name": item_name,
        "action_key": action_key,
        "action_kind": "attack_aoe",
        "dice": dice,
        "save_dc": save_dc,
        "save_ability": save_ability,
        "damage_type": damage_type,
        "condition_key": cond_key,
        "results": results,
    }


async def _use_item_action_necklace_of_fireballs(
    db, campaign_id, char, item, sheet, catalog,
    action_key, action_def,
    target_combatant_ids: list,
    charges=None,
    campaign=None,
    prompt_user=None,
    slug="necklace-of-fireballs",
):
    """v2.159.9 — Phase 8i Necklace of Fireballs handler. RAW DMG
    p.183: each bead is a 3rd-level Fireball (8d6 fire, DC 15 DEX
    save half, 20-ft sphere). v2.159.10 — Phase 8j: hurl multiple
    beads at once to upcast — 8d6 + (N-1)d6 per extra bead, max 6
    beads (full necklace = 13d6). Reads body.charges; defaults to 1.

    v2.210.0 — generalized into a shared save-for-half AoE-damage
    handler: the save DC/ability, dice (or ``dice_fn``), damage type,
    charge cost, and feature label all come from the ``action_def`` so
    a new fire/lightning AoE item is a pure catalog entry. The Staff of
    Fire's Fireball action routes through here. When ``charges`` is
    omitted it defaults to the action's ``min_charges`` (the staff's
    Fireball is a fixed 3-charge spend with no upcast, so the UI sends
    no charge picker).
    """
    res_key = str(catalog.get("resource_key") or slug)

    # v2.159.10 — Phase 8j: validate bead count from body.charges.
    min_c = int(action_def.get("min_charges") or 1)
    max_c = int(action_def.get("max_charges") or 1)
    try:
        n_charges = int(charges) if charges is not None else min_c
    except (TypeError, ValueError):
        raise HTTPException(400, "charges must be an int")
    if n_charges < min_c or n_charges > max_c:
        raise HTTPException(
            400,
            f"charges must be {min_c}..{max_c} for "
            f"{action_def.get('name') or action_key}",
        )

    # Resource lookup + decrement.
    resources = list(sheet.get("resources") or [])
    res_idx = -1
    for i, r in enumerate(resources):
        if isinstance(r, dict) and (r.get("key") or "").lower() == res_key:
            res_idx = i
            break
    if res_idx < 0:
        raise HTTPException(
            409,
            f"No {res_key!r} resource row on sheet — item not bootstrapped",
        )
    res_row = dict(resources[res_idx])
    cur = int(res_row.get("current") or 0)
    res_max = int(res_row.get("max") or 0)
    if cur < n_charges:
        return JSONResponse(
            status_code=409,
            content={
                "error": "insufficient_charges",
                "current": cur,
                "requested": n_charges,
                "label": item.get("name") or slug,
            },
        )

    if not isinstance(target_combatant_ids, list):
        raise HTTPException(400, "target_combatant_ids must be a list")
    if len(target_combatant_ids) > 24:
        raise HTTPException(400, "Too many targets for Necklace of Fireballs")

    # v2.210.0 — honour the "spell" save-DC sentinel (same as the
    # save-condition wand handler): the Staff of Fire casts "using your
    # spell save DC" per RAW DMG p.202, so resolve it from the sheet.
    raw_dc = action_def.get("save_dc")
    if isinstance(raw_dc, str) and raw_dc.strip().lower() == "spell":
        save_dc = _compute_spell_save_dc_from_sheet(sheet)
    else:
        save_dc = int(raw_dc or 15)
    save_ability = str(action_def.get("save_ability") or "DEX").upper()
    # v2.159.10 — Phase 8j: dice scales with bead count via dice_fn.
    dice_fn = action_def.get("dice_fn")
    if callable(dice_fn):
        dice = str(dice_fn(n_charges))
    else:
        dice = str(action_def.get("dice") or "8d6")
    damage_type = str(action_def.get("damage_type") or "fire")
    save_for_half = bool(action_def.get("save_for_half"))
    # v2.210.0 — feature label is content-driven so the shared handler
    # serves both the Necklace and the Staff of Fire.
    feature_name = str(action_def.get("feature_name") or "💥 Necklace of Fireballs")

    # Per-target save resolution.
    results = []
    for tid in target_combatant_ids:
        if not isinstance(tid, str) or not tid:
            continue
        target_c = _lookup_combatant(campaign_id, tid)
        if not target_c:
            results.append({"combatant_id": tid, "reason": "not_found"})
            continue
        try:
            sr = await _resolve_feature_save(
                db, campaign_id,
                caster_char_id=int(char.id),
                caster_char_name=str(char.name or ""),
                target_combatant=target_c,
                save_ability=save_ability,
                dc=save_dc,
                note_label=f"{item.get('name') or slug} (DC {save_dc} {save_ability})",
                condition_buff=None,
                repeated_save=False,
                source=f"item-{slug}-save",
                campaign=campaign,
                prompt_user=prompt_user,
                feature_name=feature_name,
            )
        except Exception:
            logging.exception(
                "Necklace save resolve failed for tid=%s", tid,
            )
            results.append({"combatant_id": tid, "reason": "save_error"})
            continue

        damage_dealt = 0
        if sr.get("passed") is not None:
            try:
                r = dice_mod.roll(dice)
                base = int(r.total)
            except dice_mod.DiceParseError:
                base = 0
            if base > 0:
                if sr.get("passed"):
                    if save_for_half:
                        damage_dealt = base // 2
                else:
                    damage_dealt = base
            if damage_dealt > 0:
                try:
                    await _apply_damage_to_combatant(
                        db, campaign_id, target_c,
                        damage_amount=damage_dealt,
                        damage_type=damage_type,
                        is_attack=False, is_magical=True,
                        attacker_char_id=char.id,
                    )
                except Exception:
                    logging.exception(
                        "Necklace damage apply failed for tid=%s", tid,
                    )
        results.append({
            "combatant_id": tid,
            "name": target_c.get("name") or "Target",
            "passed": sr.get("passed"),
            "damage_dealt": damage_dealt,
        })

    # Decrement the bead charges (v2.159.10: by n_charges, not by 1).
    res_row["current"] = cur - n_charges
    resources[res_idx] = res_row
    sheet["resources"] = resources
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    try:
        await hub.broadcast(campaign_id, {
            "type": "resource_update",
            "data": {
                "character_id": char.id,
                "key": res_key,
                "current": res_row["current"],
                "max": res_max,
            },
        })
    except Exception:
        pass
    try:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "caster_char_name": char.name,
                "source": f"item-{slug}",
                "label": feature_name,
                "summary": (
                    f"{char.name} unleashes {item.get('name')} — "
                    f"{dice} {damage_type} ({n_charges} charge"
                    f"{'s' if n_charges > 1 else ''}). "
                    f"({len(results)} save(s) resolved; "
                    f"{res_row['current']}/{res_max} charges left.)"
                ),
            },
        })
    except Exception:
        pass

    return {
        "ok": True,
        "item_name": item.get("name") or slug,
        "action_key": action_key,
        "charges_spent": n_charges,
        "dice": dice,
        "save_dc": save_dc,
        "save_ability": save_ability,
        "results": results,
        "resource": {
            "key": res_key,
            "current": res_row["current"],
            "max": res_max,
        },
    }


async def _use_item_action_wand_of_fear(
    db, campaign_id, char, item, sheet, catalog,
    action_key, action_def,
    target_combatant_ids: list,
    charges=None,
    campaign=None,
    prompt_user=None,
    slug="wand-of-fear",
):
    """v2.159.11 — Phase 8k Wand of Fear handler, generalized v2.206.0
    into a shared save-condition wand handler (Wand of Fear + Wand of
    Paralysis). Spend N charges → each named target makes a save (DC +
    ability from the action_def) or takes a condition install for the
    action_def's duration (repeated save at end of each turn). No
    damage — the rider is the condition. Reuses the
    ``_resolve_feature_save`` + ``condition_buff`` pattern (same as
    Conquering Presence / Fear-spell path). The condition key / name /
    icon / effects + the feature label all come from the action_def so
    a new save-condition wand is a pure catalog entry; the defaults
    reproduce the original Wand of Fear (WIS → frightened) verbatim.
    """
    res_key = str(catalog.get("resource_key") or slug)

    # Charge validation (v1: always 1, but kept symmetric with the
    # necklace so a future "spend N charges to upcast" upgrade is a
    # 1-line catalog tweak).
    try:
        n_charges = int(charges or 1)
    except (TypeError, ValueError):
        raise HTTPException(400, "charges must be an int")
    min_c = int(action_def.get("min_charges") or 1)
    max_c = int(action_def.get("max_charges") or 1)
    if n_charges < min_c or n_charges > max_c:
        raise HTTPException(
            400,
            f"charges must be {min_c}..{max_c} for "
            f"{action_def.get('name') or action_key}",
        )

    resources = list(sheet.get("resources") or [])
    res_idx = -1
    for i, r in enumerate(resources):
        if isinstance(r, dict) and (r.get("key") or "").lower() == res_key:
            res_idx = i
            break
    if res_idx < 0:
        raise HTTPException(
            409,
            f"No {res_key!r} resource row on sheet — item not bootstrapped",
        )
    res_row = dict(resources[res_idx])
    cur = int(res_row.get("current") or 0)
    res_max = int(res_row.get("max") or 0)
    if cur < n_charges:
        return JSONResponse(
            status_code=409,
            content={
                "error": "insufficient_charges",
                "current": cur,
                "requested": n_charges,
                "label": item.get("name") or slug,
            },
        )

    if not isinstance(target_combatant_ids, list):
        raise HTTPException(400, "target_combatant_ids must be a list")
    if len(target_combatant_ids) > 24:
        raise HTTPException(400, "Too many targets for this wand")

    raw_dc = action_def.get("save_dc")
    if isinstance(raw_dc, str) and raw_dc.strip().lower() == "spell":
        save_dc = _compute_spell_save_dc_from_sheet(sheet)
    else:
        save_dc = int(raw_dc or 15)
    save_ability = str(action_def.get("save_ability") or "WIS").upper()
    dur_rounds = int(action_def.get("duration_rounds") or 10)

    cond_key = str(action_def.get("condition_key") or "frightened")
    cond_label = str(action_def.get("condition_label") or "Frightened")
    cond_icon = str(action_def.get("condition_icon") or "😱")
    cond_effects = action_def.get("condition_effects") or [
        "disadvantage on ability checks / attacks while source in sight",
        "can't willingly move closer to source",
    ]
    feature_name = str(action_def.get("feature_name") or "😱 Wand of Fear")
    item_name = item.get("name") or slug

    condition_buff = {
        "key": cond_key,
        "name": f"{cond_label} ({item_name} — {char.name})",
        "icon": cond_icon,
        "duration_rounds": dur_rounds,
        "duration_max": dur_rounds,
        "concentration": False,
        "source_item": slug,
        "effects": list(cond_effects),
    }

    results = []
    for tid in target_combatant_ids:
        if not isinstance(tid, str) or not tid:
            continue
        target_c = _lookup_combatant(campaign_id, tid)
        if not target_c:
            results.append({"combatant_id": tid, "reason": "not_found"})
            continue
        try:
            sr = await _resolve_feature_save(
                db, campaign_id,
                caster_char_id=int(char.id),
                caster_char_name=str(char.name or ""),
                target_combatant=target_c,
                save_ability=save_ability,
                dc=save_dc,
                note_label=f"{item_name} (DC {save_dc} {save_ability})",
                condition_buff=condition_buff,
                repeated_save=True,
                source=f"item-{slug}-save",
                campaign=campaign,
                prompt_user=prompt_user,
                feature_name=feature_name,
            )
        except Exception:
            logging.exception(
                "%s save resolve failed for tid=%s", item_name, tid,
            )
            results.append({"combatant_id": tid, "reason": "save_error"})
            continue
        results.append({
            "combatant_id": tid,
            "name": target_c.get("name") or "Target",
            "passed": sr.get("passed"),
        })

    res_row["current"] = cur - n_charges
    resources[res_idx] = res_row
    sheet["resources"] = resources
    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    try:
        await hub.broadcast(campaign_id, {
            "type": "resource_update",
            "data": {
                "character_id": char.id,
                "key": res_key,
                "current": res_row["current"],
                "max": res_max,
            },
        })
    except Exception:
        pass
    shape = str(action_def.get("target_shape") or "cone")
    try:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "caster_char_name": char.name,
                "source": f"item-{slug}",
                "label": feature_name,
                "summary": (
                    f"{char.name} unleashes the {item_name} — "
                    f"DC {save_dc} {save_ability} {shape} against "
                    f"{len(results)} target(s). "
                    f"({res_row['current']}/{res_max} charges left.)"
                ),
            },
        })
    except Exception:
        pass

    return {
        "ok": True,
        "item_name": item.get("name") or slug,
        "action_key": action_key,
        "charges_spent": n_charges,
        "save_dc": save_dc,
        "save_ability": save_ability,
        "results": results,
        "resource": {
            "key": res_key,
            "current": res_row["current"],
            "max": res_max,
        },
    }


# ----------- API: class / subclass resource use -----------

@router.post("/api/campaign/{campaign_id}/character/{char_id}/resource")
async def use_resource(
    campaign_id: int,
    char_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Spend or restore a trackable class/subclass resource.

    Body:
        {"key": "<resource key>", "delta": -1}     # spend (negative)
        {"key": "<resource key>", "delta": +1}     # restore by N
        {"key": "<resource key>", "set": N}        # set current absolute
        {"key": "<resource key>", "reset": true}   # refill to max

    Returns 409 ``{"error": "no_uses", ...}`` when a spend would go below 0
    so the caller can show a non-blocking toast instead of mutating state.

    Broadcasts a ``resource_update`` WS message so other connected clients
    (mini-sheet, popped-out roll log) can re-render the pip count.
    """
    body = await request.json()
    key = str(body.get("key") or "").strip()
    if not key:
        raise HTTPException(400, "key is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id
    ).first()
    if not char:
        raise HTTPException(404, "Character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if char.template == "dnd5e":
        normalize_dnd5e_sheet(sheet)
    resources = list(sheet.get("resources") or [])
    idx = next(
        (i for i, r in enumerate(resources)
         if isinstance(r, dict) and (r.get("key") or "") == key),
        None,
    )
    if idx is None:
        raise HTTPException(404, "Resource not found on this sheet")

    res = dict(resources[idx])
    mx = int(res.get("max") or 0)
    cur = int(res.get("current") or 0)

    if body.get("reset"):
        # Refill to max
        new_cur = mx
        announce = False
    elif body.get("set") is not None:
        try:
            new_cur = int(body.get("set"))
        except (TypeError, ValueError):
            raise HTTPException(400, "'set' must be an integer")
        announce = False
    else:
        try:
            delta = int(body.get("delta", -1))
        except (TypeError, ValueError):
            raise HTTPException(400, "'delta' must be an integer")
        # Chat-only features (max == 0) never have insufficient uses;
        # we just announce on negative delta and keep current at 0.
        if mx <= 0:
            new_cur = 0
            announce = delta < 0
        else:
            new_cur = cur + delta
            if new_cur < 0:
                return JSONResponse(
                    status_code=409,
                    content={
                        "error": "no_uses",
                        "key": key,
                        "name": res.get("name", ""),
                        "current": cur,
                        "max": mx,
                    },
                )
            announce = delta < 0

    # Clamp [0, max] when max > 0
    if mx > 0:
        new_cur = max(0, min(mx, new_cur))
    else:
        new_cur = max(0, new_cur)

    res["current"] = new_cur
    resources[idx] = res
    sheet["resources"] = resources
    char.sheet = sheet
    db.commit()

    await hub.broadcast(campaign_id, {
        "type": "resource_update",
        "data": {
            "character_id": char.id,
            "key": key,
            "current": new_cur,
            "max": mx,
        },
    })

    # If the caller explicitly asks for a chat announcement (or this was a
    # chat-only feature being "used"), drop a note into the roll log so the
    # rest of the table sees that the feature fired.
    note_label = ""
    if announce and (body.get("announce") is not False):
        membership = (
            db.query(CampaignMembership)
            .filter(CampaignMembership.campaign_id == campaign_id,
                    CampaignMembership.user_id == user.id)
            .first()
        )
        player_color = (
            membership.color if membership and membership.color
            else (campaign.gm_color if user.id == campaign.gm_user_id else None)
        )
        caster_color = char.color or player_color
        note_label = res.get("name", "feature")
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": char.id,
                "character_name": char.name,
                "user_color": caster_color,
                "feature_name": note_label,
                "feature_desc": res.get("desc", ""),
                "source": res.get("source", ""),
                "remaining": new_cur,
                "max": mx,
            },
        })

    return {
        "ok": True,
        "key": key,
        "current": new_cur,
        "max": mx,
        "announced": bool(note_label),
    }


# ----------- API: Wild Shape / Polymorph transform -----------

# Wild Shape CR cap by druid level (RAW). Moon Druid escalates faster.
_WS_CR_DEFAULT = [
    (2, 0.25), (4, 0.5), (8, 1.0),   # lv2: 1/4, lv4: 1/2, lv8: 1
]
_WS_CR_MOON = [
    (2, 1.0), (4, 2.0), (6, 3.0), (8, 4.0), (10, 5.0), (12, 6.0),
]

def _ws_cr_cap(druid_level: int, is_moon: bool) -> float:
    """Max CR a druid of the given level can Wild Shape into (RAW)."""
    table = _WS_CR_MOON if is_moon else _WS_CR_DEFAULT
    cap = 0.0
    for lvl, cr in table:
        if druid_level >= lvl:
            cap = cr
    return cap


def _wild_shape_economy_slot(sheet: dict, source: str) -> str:
    """Action-economy slot consumed by /transform.

    Default Druid: Wild Shape = 1 action. Circle of the Moon: bonus
    action (Lv 2 RAW feature). Polymorph the spell: 1 action regardless
    of caster class — the polymorph "🦌" button on the resources panel
    is the only path that calls /transform directly without going
    through /cast_spell, so /transform must mark the chip for it too.
    """
    if source == "polymorph":
        return "action"
    for c in sheet.get("classes") or []:
        if not isinstance(c, dict):
            continue
        if (c.get("class") or "").strip().lower() != "druid":
            continue
        if "moon" in (c.get("subclass") or "").strip().lower():
            return "bonus"
    return "action"


def _cr_to_float(cr_raw) -> float:
    """Parse '1/4' / '0' / '2' / '1/2' / '' into a float. Returns 0.0 on
    anything unparseable."""
    if cr_raw is None:
        return 0.0
    s = str(cr_raw).strip()
    if not s:
        return 0.0
    if "/" in s:
        try:
            a, b = s.split("/", 1)
            return float(a) / float(b) if float(b) else 0.0
        except (TypeError, ValueError):
            return 0.0
    try:
        return float(s)
    except (TypeError, ValueError):
        return 0.0


def _fetch_open5e_creature(slug: str) -> dict:
    """Pull a creature stat block from the Open5e v2 API.

    First tries a direct slug lookup (/v2/creatures/{slug}/) which works for
    v2 keys.  If that returns 404 (e.g. a v1-style slug like ``wolf`` passed
    from a Quick Pick preset), converts the slug to a display name and retries
    via a name search so transforms always succeed regardless of slug format.
    """
    import json as _json
    import urllib.request as _urlreq
    import urllib.error as _urlerr
    import urllib.parse as _urlparse

    def _get(url: str) -> dict:
        req = _urlreq.Request(url, headers={"User-Agent": "SimpleVTT/1.0"})
        with _urlreq.urlopen(req, timeout=10) as r:
            return _json.loads(r.read())

    try:
        return _get(f"{_OPEN5E_BASE}/v2/creatures/{slug}/")
    except _urlerr.HTTPError as exc:
        if exc.code != 404:
            raise HTTPException(502, f"Open5e unavailable: {exc}")
    except Exception as exc:
        raise HTTPException(502, f"Open5e unavailable: {exc}")

    # Direct lookup 404'd — derive a human name from the slug and search.
    # "brown-bear" → "brown bear", "giant-constrictor-snake" → "giant constrictor snake"
    name_guess = slug.replace("-", " ")
    try:
        search_url = (
            f"{_OPEN5E_BASE}/v2/creatures/"
            f"?name__icontains={_urlparse.quote(name_guess)}&limit=10&type__key=beast"
        )
        data = _get(search_url)
        results = data.get("results", [])
        name_lower = name_guess.lower()
        match = next(
            (r for r in results if (r.get("name") or "").lower() == name_lower),
            results[0] if results else None,
        )
        if match:
            key = match.get("key") or match.get("slug") or ""
            if key:
                return _get(f"{_OPEN5E_BASE}/v2/creatures/{key}/")
    except Exception:
        pass

    raise HTTPException(404, f"Creature '{slug}' not found in Open5e")


_BEAST_SIZE_TO_INT = {
    "tiny": 1,
    "small": 1,
    "medium": 1,
    "large": 2,
    "huge": 3,
    "gargantuan": 4,
}


def _apply_token_disguise(
    db: Session,
    char_id: int,
    *,
    source: str,
    form_name: str,
    form_size: str,
) -> int:
    """v2.99.168 — Token-disguise primitive. For each Token row
    bound to this character_id, snapshot the original (label, size)
    into the `disguise.original` sub-dict and replace with the
    form's values. Returns the count of tokens updated.

    Idempotent on already-disguised tokens — if `disguise` is
    non-empty, the original isn't re-snapshotted (preserves the
    pre-shape values across consecutive transforms).

    Closes the docs/plans/class-content-status.md filed item
    "token-disguise primitive (v2.15.9)". Generalizes to Polymorph
    / Disguise Self / Alter Self / True Polymorph by passing the
    appropriate `source` enum value.

    `form_size` accepts the Open5e size string ("Small" / "Medium"
    / "Large" / etc.); mapped via `_BEAST_SIZE_TO_INT` to the
    integer Token.size field (1 for Tiny-Medium, 2 for Large, 3
    for Huge, 4 for Gargantuan).
    """
    new_size = _BEAST_SIZE_TO_INT.get(
        (form_size or "").strip().lower(), 1,
    )
    count = 0
    for tok in db.query(Token).filter(Token.character_id == char_id).all():
        if tok.disguise:
            # Already disguised — skip the snapshot but update the
            # current label/size to the new form (chained
            # transforms reuse the original snapshot).
            tok.label = f"{tok.disguise.get('original', {}).get('label', tok.label)} → {form_name}"
            tok.size = new_size
            tok.disguise = {
                "source": source,
                "form_name": form_name,
                "original": tok.disguise.get("original") or {
                    "label": tok.label, "size": new_size,
                },
                "applied_at": datetime.utcnow().isoformat(),
            }
        else:
            original_label = tok.label or ""
            original_size = int(tok.size or 1)
            tok.label = f"{original_label} → {form_name}"
            tok.size = new_size
            tok.disguise = {
                "source": source,
                "form_name": form_name,
                "original": {
                    "label": original_label,
                    "size": original_size,
                },
                "applied_at": datetime.utcnow().isoformat(),
            }
        from sqlalchemy.orm.attributes import flag_modified
        flag_modified(tok, "disguise")
        count += 1
    return count


def _revert_token_disguise(db: Session, char_id: int) -> int:
    """v2.99.168 — Restore original label + size for each Token
    bound to char_id where `disguise` is set. Clears the disguise
    field. Returns the count of tokens reverted.

    No-op for tokens already in their native form (disguise=None
    or empty dict).
    """
    count = 0
    for tok in db.query(Token).filter(Token.character_id == char_id).all():
        if not tok.disguise:
            continue
        original = tok.disguise.get("original") or {}
        if "label" in original:
            tok.label = original["label"]
        if "size" in original:
            try:
                tok.size = int(original["size"])
            except (TypeError, ValueError):
                pass
        tok.disguise = None
        from sqlalchemy.orm.attributes import flag_modified
        flag_modified(tok, "disguise")
        count += 1
    return count


@router.post("/api/campaign/{campaign_id}/character/{char_id}/transform")
async def transform_character(
    campaign_id: int,
    char_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Apply a Wild Shape / Polymorph transformation to a character.

    Body:
        {
          "slug":      "wolf",                       # required
          "source":    "wild-shape" | "polymorph",   # required
          "free_pick": false                         # bypass CR cap if True
        }

    On success: snapshots the character's current HP/AC/speed/abilities/
    attacks/skills/saves into ``sheet["prior_form"]``, replaces those
    fields with the beast's stats (Wild Shape: keeps INT/WIS/CHA;
    Polymorph: replaces all six), sets ``sheet["active_form"]``, and
    decrements the ``wild-shape`` resource if ``source == "wild-shape"``.

    Returns 409 if the character is already transformed, or if the beast's
    CR exceeds the cap for this source/level (and ``free_pick`` is false).

    TODO (filed in docs/plans/class-content-status.md under Druid Wild
    Shape — "token-disguise primitive"): swap the character's Token
    row(s) to reflect the new form (label "{name} → {beast}", image_url
    to beast portrait, size from monster["size"]). The design generalises
    to a reusable ``Token.disguise`` JSON field + ``_apply_token_disguise``
    / ``_revert_token_disguise`` helpers, so the same primitive serves
    Wild Shape AND Polymorph AND Disguise Self AND Alter Self AND True
    Polymorph (each passes its own ``source`` enum value). Storage is
    per-token (not per-sheet) so a Polymorph that targets an enemy NPC
    stores the disguise on the enemy's token without needing the enemy
    to have a Character row. See the plan doc for the full helper
    signatures, edge-case checklist (multiple tokens, summons sharing
    char_id, concentration coupling, death-revert), and the 6-step
    implementation order.
    """
    body = await request.json()
    slug = str(body.get("slug") or "").strip()
    source = str(body.get("source") or "wild-shape").strip().lower()
    free_pick = bool(body.get("free_pick"))
    override = bool(body.get("override"))
    # v2.99.172 — caster_char_id (optional). When set on a Polymorph
    # cast where the caster differs from the target, /transform
    # installs a `polymorph-active` marker buff on the target's
    # combatant entry. The marker carries `source_char_id: caster`
    # + `concentration: True` so the v2.38.0 paired-cleanup cascade
    # (`_drop_paired_concentration_buffs`) auto-reverts the target
    # when the caster's concentration drops.
    # v2.99.179 — also accept `caster_combatant_id` for NPC casters.
    # When set, the marker's `source_combatant_id` field is filled
    # (and `source_char_id` is omitted) so the NPC mirror cascade
    # (`_drop_paired_concentration_buffs_npc`) fires for NPC
    # concentration drops. Closes the v2.99.172 filed item.
    try:
        caster_char_id = int(body.get("caster_char_id") or 0)
    except (TypeError, ValueError):
        caster_char_id = 0
    caster_combatant_id = (
        body.get("caster_combatant_id") or ""
    ).strip()
    if not slug:
        raise HTTPException(400, "slug is required")
    if source not in ("wild-shape", "polymorph"):
        raise HTTPException(400, "source must be 'wild-shape' or 'polymorph'")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id
    ).first()
    if not char:
        raise HTTPException(404, "Character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if char.template == "dnd5e":
        normalize_dnd5e_sheet(sheet)

    if sheet.get("active_form"):
        existing = sheet["active_form"]
        raise HTTPException(409, f"Already transformed into {existing.get('name', 'a form')}. Revert first.")

    # v2.14.6: Phase 4 over-budget gate. Compute the slot from the
    # sheet BEFORE the (expensive) Open5e fetch so a 409 returns
    # without burning a network round-trip. Mirrors the pattern in
    # /cast_spell + /use_feature. strict mode (v2.8.0) suppresses
    # player overrides; GM clicks always bypass.
    slot = _wild_shape_economy_slot(sheet, source)
    was_used = _is_slot_used(campaign_id, char.id, slot)
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    can_override = override and not strict
    if was_used and not user_is_gm and not can_override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": slot,
            "char_name": char.name,
            "source": source,
            "label": "Wild Shape" if source == "wild-shape" else "Polymorph",
            "strict": strict,
        })

    # Fetch beast
    monster = _fetch_open5e_creature(slug)
    creature_type = _o5e_str(monster.get("type")).strip().lower()
    creature_name = (monster.get("name") or slug).strip()
    creature_cr = _cr_to_float(_o5e_cr(monster))

    # Source-specific eligibility checks
    if not free_pick:
        if source == "wild-shape":
            if creature_type != "beast":
                raise HTTPException(409, f"Wild Shape only allows beasts (got '{creature_type or 'unknown'}'). Try 'Free pick (homebrew)' to override.")
            # Find druid level on the roster + detect Moon Druid by subclass
            classes = sheet.get("classes") or []
            druid_lv = 0
            is_moon = False
            for c in classes:
                if isinstance(c, dict) and (c.get("class") or "").strip().lower() == "druid":
                    druid_lv = max(druid_lv, int(c.get("level") or 0))
                    sub = (c.get("subclass") or "").strip().lower()
                    if "moon" in sub:
                        is_moon = True
            if druid_lv < 2:
                raise HTTPException(409, "Wild Shape requires Druid level 2+. Use 'Free pick (homebrew)' to override.")
            cap = _ws_cr_cap(druid_lv, is_moon)
            if creature_cr > cap:
                raise HTTPException(
                    409,
                    f"{creature_name} (CR {_o5e_cr(monster)}) exceeds your Wild Shape CR cap of {cap}. "
                    f"Use 'Free pick (homebrew)' to override.",
                )
        else:  # polymorph
            # Polymorph targets the *target*; for a player polymorphing
            # themselves, the cap is character_level / 4 (rounded down).
            char_level = int(sheet.get("level") or 1)
            cap = max(0.0, char_level / 4.0)
            if creature_cr > cap:
                raise HTTPException(
                    409,
                    f"{creature_name} (CR {_o5e_cr(monster)}) exceeds the Polymorph CR cap of {cap} "
                    f"(target level / 4). Use 'Free pick (homebrew)' to override.",
                )
            if creature_type != "beast":
                raise HTTPException(409, f"Polymorph only targets beasts (got '{creature_type or 'unknown'}'). Try 'Free pick (homebrew)' to override.")

    # Build the beast sheet shape (reuses the GM monster importer helper)
    form_sheet = _open5e_to_dnd5e_sheet(monster)

    # Snapshot prior_form
    prior_form = {
        "hp": dict(sheet.get("hp") or {}),
        "ac": sheet.get("ac"),
        "speed": sheet.get("speed"),
        "abilities": dict(sheet.get("abilities") or {}),
        "skills": dict(sheet.get("skills") or {}),
        "saving_throws": dict(sheet.get("saving_throws") or {}),
        "attacks": list(sheet.get("attacks") or []),
        "race": sheet.get("race"),
        "initiative_bonus": sheet.get("initiative_bonus"),
        "proficiency_bonus": sheet.get("proficiency_bonus"),
        # Defenses follow the beast for the duration of the form — RAW
        # for both Wild Shape and Polymorph (beast stats replace the
        # PC's; Wild Shape preserves the PC's INT/WIS/CHA + class
        # features but not defenses). Snapshot the PC's real-form
        # defenses so revert restores them cleanly.
        "damage_resistances":     list(sheet.get("damage_resistances") or []),
        "damage_immunities":      list(sheet.get("damage_immunities") or []),
        "damage_vulnerabilities": list(sheet.get("damage_vulnerabilities") or []),
        "condition_immunities":   list(sheet.get("condition_immunities") or []),
    }

    # Apply beast stats
    new_abilities = dict(sheet.get("abilities") or {})
    if source == "wild-shape":
        # RAW: keep INT/WIS/CHA, swap STR/DEX/CON
        for ab in ("STR", "DEX", "CON"):
            if ab in form_sheet.get("abilities", {}):
                new_abilities[ab] = form_sheet["abilities"][ab]
    else:
        # Polymorph: full replace per RAW
        new_abilities = dict(form_sheet.get("abilities") or new_abilities)

    sheet["abilities"] = new_abilities
    sheet["hp"] = form_sheet.get("hp") or sheet.get("hp")
    sheet["ac"] = form_sheet.get("ac", sheet.get("ac"))
    sheet["speed"] = form_sheet.get("speed", sheet.get("speed"))
    sheet["skills"] = form_sheet.get("skills") or sheet.get("skills")
    sheet["saving_throws"] = form_sheet.get("saving_throws") or sheet.get("saving_throws")
    sheet["attacks"] = form_sheet.get("attacks") or []
    sheet["race"] = f"{creature_name} (transformed)"
    # Replace the PC's defenses with the beast's for the duration of the
    # form. ``_open5e_to_dnd5e_sheet`` already split Open5e's free-text
    # strings into lists for us; just copy them straight in.
    sheet["damage_resistances"]     = list(form_sheet.get("damage_resistances") or [])
    sheet["damage_immunities"]      = list(form_sheet.get("damage_immunities") or [])
    sheet["damage_vulnerabilities"] = list(form_sheet.get("damage_vulnerabilities") or [])
    sheet["condition_immunities"]   = list(form_sheet.get("condition_immunities") or [])
    # Initiative bonus = DEX mod under the new abilities; keep simple
    try:
        dex = int(new_abilities.get("DEX") or 10)
        sheet["initiative_bonus"] = (dex - 10) // 2
    except (TypeError, ValueError):
        pass

    from datetime import datetime as _dt
    sheet["active_form"] = {
        "slug": slug,
        "name": creature_name,
        "source": source,
        "cr": _o5e_cr(monster),
        "creature_type": creature_type,
        "started_at": _dt.now(timezone.utc).isoformat(),
        "form_sheet": form_sheet,   # full snapshot for reference / future re-apply
    }
    sheet["prior_form"] = prior_form

    # Decrement wild-shape resource if applicable
    resource_update = None
    if source == "wild-shape":
        resources = list(sheet.get("resources") or [])
        for i, r in enumerate(resources):
            if isinstance(r, dict) and (r.get("key") or "") == "wild-shape":
                if int(r.get("max") or 0) > 0:
                    new_cur = max(0, int(r.get("current") or 0) - 1)
                    resources[i] = {**r, "current": new_cur}
                    resource_update = {"key": "wild-shape", "current": new_cur, "max": int(r.get("max") or 0)}
                break
        sheet["resources"] = resources

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # v2.99.168 — Token-disguise primitive. Re-label + resize the
    # PC's token(s) to reflect the new form. Reuses the v2.99.168
    # `_apply_token_disguise` helper that snapshots the original
    # label + size into `disguise.original` and rewrites the live
    # fields. The same helper serves Polymorph in /transform with
    # source="polymorph"; future Disguise Self / Alter Self ships
    # pass their own source enum.
    _disguised_count = _apply_token_disguise(
        db, int(char.id),
        source=source,
        form_name=creature_name,
        form_size=str(monster.get("size") or "").strip(),
    )
    if _disguised_count > 0:
        db.commit()
        # Broadcast token_update for each disguised token so map
        # clients refresh without a full page reload.
        for _tok in db.query(Token).filter(
            Token.character_id == int(char.id),
        ).all():
            await hub.broadcast(campaign_id, {
                "type": "token_update",
                "data": {
                    "id": _tok.id,
                    "label": _tok.label,
                    "size": _tok.size,
                    "disguise": _tok.disguise,
                },
            })

    # v2.99.172 — Polymorph concentration coupling. Install a
    # `polymorph-active` marker buff on the target's combatant when
    # source=="polymorph" + (caster_char_id OR caster_combatant_id)
    # is provided + caster differs from target. The marker carries
    # source_char_id (PC caster) OR source_combatant_id (NPC caster)
    # + concentration=True so the v2.38.0 paired-cleanup cascade
    # (PC) or v2.97.80 NPC mirror auto-reverts the target's
    # transform when the caster's concentration anchor drops.
    # v2.99.179 — NPC-cast path: when caster_combatant_id is set
    # (and caster_char_id is 0), the marker uses source_combatant_id
    # for the NPC mirror.
    _is_pc_cast = caster_char_id > 0 and caster_char_id != int(char.id)
    _is_npc_cast = bool(caster_combatant_id) and not _is_pc_cast
    if source == "polymorph" and (_is_pc_cast or _is_npc_cast):
        _poly_marker = {
            "key": "polymorph-active",
            "name": f"Polymorphed ({creature_name})",
            "icon": "🦌",
            "duration_rounds": 600,  # 1 hour at 6s/round (RAW)
            "duration_max": 600,
            "concentration": True,
            "source": "polymorph-spell",
            "effects": {
                "polymorph_active": True,
                "form_name": creature_name,
                "form_slug": slug,
            },
        }
        if _is_pc_cast:
            _poly_marker["source_char_id"] = int(caster_char_id)
        else:
            _poly_marker["source_combatant_id"] = str(caster_combatant_id)
        await _install_buff(campaign_id, int(char.id), _poly_marker)

    await hub.broadcast(campaign_id, {
        "type": "transform_update",
        "data": {
            "character_id": char.id,
            "active_form": sheet["active_form"],
            "hp": sheet["hp"],
            "ac": sheet["ac"],
            "speed": sheet["speed"],
        },
    })
    if resource_update is not None:
        await hub.broadcast(campaign_id, {
            "type": "resource_update",
            "data": {"character_id": char.id, **resource_update},
        })

    # Announce in the roll log so the table sees the transformation
    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    icon = "🐺" if source == "wild-shape" else "🦌"
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": f"{icon} Transformed into {creature_name}",
            "feature_desc": f"CR {_o5e_cr(monster) or '?'} {creature_type or 'creature'}. "
                            f"Form HP {sheet['hp'].get('current')}/{sheet['hp'].get('max')}, AC {sheet['ac']}.",
            "source": "Wild Shape" if source == "wild-shape" else "Polymorph",
            "remaining": 0,
            "max": 0,
            "over_budget": was_used,
            "over_budget_slot": slot if was_used else "",
        },
    })

    # Mark the action-economy slot the transform consumed. ``slot``
    # was resolved at the top of the endpoint (Moon Druid → bonus,
    # everyone else → action; polymorph → always action) before the
    # over-budget gate. ``_mark_battle_economy`` is a no-op when the
    # campaign has no active battle or the character isn't in init.
    await _mark_battle_economy(campaign_id, char.id, slot)

    return {
        "ok": True,
        "active_form": sheet["active_form"],
        "sheet": sheet,
        "economy_slot": slot,
        "over_budget": was_used,
    }


@router.post("/api/campaign/{campaign_id}/character/{char_id}/revert")
async def revert_character(
    campaign_id: int,
    char_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Revert a Wild Shape / Polymorph back to the character's true form.

    Restores ``sheet["prior_form"]`` onto the live sheet and clears
    ``active_form`` / ``prior_form``.

    Tolerant of "stuck" characters: if ``active_form`` is set but
    ``prior_form`` was lost (e.g. cleared by a pre-v0.35.4 sheet save
    that didn't preserve server-managed fields), the endpoint still
    clears ``active_form`` so the player can edit their sheet back to
    normal. The response carries ``stats_restored: false`` so the UI
    can warn that stats need manual fix-up. Returns 409 only when the
    character is genuinely not transformed (no active_form either).

    RAW Wild Shape: damage that drops the form to 0 HP "overflows" to
    the character's real HP. If the caller passes
    ``{"overflow_damage": N}``, that amount is subtracted from the
    restored real-form HP (clamped to 0).
    """
    body = await request.json() if (await request.body()) else {}
    try:
        overflow = max(0, int(body.get("overflow_damage") or 0))
    except (TypeError, ValueError):
        overflow = 0

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id
    ).first()
    if not char:
        raise HTTPException(404, "Character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    if char.template == "dnd5e":
        normalize_dnd5e_sheet(sheet)

    prior = sheet.get("prior_form")
    active = sheet.get("active_form") or {}

    # Neither set → genuinely not transformed.
    if not isinstance(prior, dict) and not active:
        raise HTTPException(409, "Character is not currently transformed")

    # Rescue path: active_form is set but prior_form was wiped (typically
    # by a save that didn't carry it forward). Clear active_form so the
    # player can edit out of the beast form; warn via stats_restored=False.
    stats_restored = isinstance(prior, dict)

    if stats_restored:
        # Restore prior_form fields onto the live sheet
        for key in ("hp", "ac", "speed", "abilities", "skills", "saving_throws",
                    "attacks", "race", "initiative_bonus", "proficiency_bonus",
                    "damage_resistances", "damage_immunities",
                    "damage_vulnerabilities", "condition_immunities"):
            if key in prior and prior[key] is not None:
                sheet[key] = prior[key]

        # Apply RAW Wild Shape HP overflow: any damage that dropped the
        # form below 0 carries over to the character's real HP.
        if overflow > 0 and isinstance(sheet.get("hp"), dict):
            hp = dict(sheet["hp"])
            hp["current"] = max(0, int(hp.get("current") or 0) - overflow)
            sheet["hp"] = hp

    sheet["active_form"] = None
    sheet["prior_form"] = None

    from sqlalchemy.orm.attributes import flag_modified
    char.sheet = sheet
    flag_modified(char, "sheet")
    db.commit()

    # v2.99.168 — Revert the Token-disguise primitive. Restores
    # the original label + size to each of this character's tokens
    # (no-op for tokens already in native form). Broadcasts a
    # token_update for each reverted token.
    _reverted_count = _revert_token_disguise(db, int(char.id))
    if _reverted_count > 0:
        db.commit()
        for _tok in db.query(Token).filter(
            Token.character_id == int(char.id),
        ).all():
            await hub.broadcast(campaign_id, {
                "type": "token_update",
                "data": {
                    "id": _tok.id,
                    "label": _tok.label,
                    "size": _tok.size,
                    "disguise": _tok.disguise,
                },
            })

    await hub.broadcast(campaign_id, {
        "type": "transform_update",
        "data": {
            "character_id": char.id,
            "active_form": None,
            "hp": sheet.get("hp"),
            "ac": sheet.get("ac"),
            "speed": sheet.get("speed"),
        },
    })

    # Announce the revert in the roll log
    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id,
                CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color
    prev_name = active.get("name") or "form"
    note = f"Reverted from {prev_name}"
    if overflow > 0:
        note += f" — {overflow} overflow damage to real HP"
    if not stats_restored:
        note += " — prior stats not restored, please edit manually"
    await hub.broadcast(campaign_id, {
        "type": "feature_used",
        "data": {
            "character_id": char.id,
            "character_name": char.name,
            "user_color": caster_color,
            "feature_name": "✨ Reverted to true form",
            "feature_desc": note,
            "source": active.get("source", "transform"),
            "remaining": 0, "max": 0,
        },
    })

    return {"ok": True, "sheet": sheet, "stats_restored": stats_restored}


# ----------- API: weapon / structured attacks -----------

@router.post("/api/campaign/{campaign_id}/attack")
async def use_attack(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Resolve a structured attack from a character's sheet.

    For attack-roll based attacks: rolls 1d20 + attack_bonus AND damage at the
    same time, persists both rolls (so they appear in the roll log if anyone
    pops it out), and broadcasts a single ``weapon_attack`` WS message that
    other clients render as an attack card.

    For save-based attacks (save_dc > 0 and save_ability set): skips the d20
    attack roll and broadcasts a card with a "Prompt save" button instead.
    Damage is still pre-rolled so the GM can decide who takes it.
    """
    body = await request.json()
    char_id = int(body.get("character_id") or 0)
    attack_index = int(body.get("attack_index", -1))
    if char_id <= 0 or attack_index < 0:
        raise HTTPException(400, "character_id and attack_index are required")

    # v2.99.75 — OA chain hint. The v2.99.68 client chain POSTs
    # /attack after the user picks a take-the-oa:{idx} key on the
    # OA popup. We surface this in the weapon_attack broadcast so
    # the chat card chrome can read "OA — Greataxe" instead of a
    # bare attack roll that loses the OA context. Pure UX hint —
    # no server-side gating changes.
    is_oa = bool(body.get("is_opportunity_attack"))
    # v2.99.220 — Phase F.3 cont'd: attacker can't see target hint.
    # RAW disadvantage source: attacking a creature you can't see
    # (PHB p.194 — Unseen Attackers and Targets). Feral Senses
    # (Ranger Lv 18+) suppresses this disadvantage. The client
    # opts in via this body field when the target is invisible
    # / heavily obscured / behind cover that blocks LOS.
    attacker_cant_see_target = bool(
        body.get("attacker_cant_see_target")
    )
    # v2.131.0 — Assassinate (Assassin Rogue Lv 3+, PHB p.97). "Any hit
    # you score against a creature that is surprised is a critical hit."
    # No surprise state model yet — the client (or GM) opts in via this
    # one-shot body flag when the target is surprised at the start of
    # combat. Gated to the Assassin subclass at the crit-detection block
    # below so non-Assassin callers can't force auto-crits.
    target_surprised = bool(body.get("target_surprised"))

    # v2.20.0 Phase B: optional target_combatant_id for buff-driven
    # uplifts that need to know the target (Hunter's Mark / Hex match,
    # Colossus Slayer below-max-HP check).
    target_combatant_id = (body.get("target_combatant_id") or "").strip() or None
    # v2.49.85 — multi-target attack list. Each entry gets its own
    # fresh attack roll + damage roll (RAW weapon attacks per-target),
    # and per-target outcomes are returned in ``auto_attack_targets``.
    # The first entry rides through the existing single-target path
    # (so the legacy ``target_combatant_id``, ``hit``, ``damage_applied``
    # fields carry the primary target's outcome for backward compat).
    # Empty / single-entry list = unchanged behavior.
    target_combatant_ids_in = body.get("target_combatant_ids") or []
    if not isinstance(target_combatant_ids_in, list):
        target_combatant_ids_in = []
    target_combatant_ids_in = [
        str(x).strip() for x in target_combatant_ids_in if str(x).strip()
    ]
    if target_combatant_ids_in and not target_combatant_id:
        target_combatant_id = target_combatant_ids_in[0]
    elif target_combatant_id and not target_combatant_ids_in:
        target_combatant_ids_in = [target_combatant_id]

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id
    ).first()
    if not char:
        raise HTTPException(404, "Character not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")

    sheet = dict(char.sheet or {})
    attacks = list(sheet.get("attacks") or [])
    # v2.158.26 — Phase 2 read site for buff-derived natural weapons.
    # Append the entries from `_pc_active_natural_weapons` (today:
    # form-of-the-beast-active; future: shape-change buffs) so an
    # attack_index past the sheet's regular attacks resolves to a
    # natural-weapon entry. Same attack-resolution pipeline (d20 +
    # damage roll + apply to target) as a sheet weapon — the
    # buff-derived entry already carries name / attack_bonus /
    # damage / damage_type / range / desc in the sheet-attacks shape.
    natural_weapons = _pc_active_natural_weapons(
        sheet, campaign_id, char.id,
    )
    if natural_weapons:
        attacks.extend(natural_weapons)
    if attack_index >= len(attacks):
        raise HTTPException(404, "Attack not found")
    attack = dict(attacks[attack_index] or {})

    name = (attack.get("name") or "Attack").strip()

    # v2.6.1: Phase 4 over-budget gate. Every weapon attack consumes the
    # action slot (bonus-action attacks are filed under feature/Class
    # abilities, not /attack). See cast_spell for the matching pattern.
    # v2.8.0: strict-mode honours the same override-suppression rule.
    was_used = _is_slot_used(campaign_id, char.id, "action")
    user_is_gm = _user_is_gm(user, campaign, db)
    strict = bool(campaign.strict_action_economy)
    override = bool(body.get("override")) and not strict
    if was_used and not user_is_gm and not override:
        return JSONResponse(status_code=409, content={
            "error": "over_budget",
            "slot": "action",
            "char_name": char.name,
            "source": "attack",
            "label": name,
            "strict": strict,
        })
    attack_bonus_raw = str(attack.get("attack_bonus") or "").strip()
    damage_expr_raw = (attack.get("damage") or "").strip()
    damage_type = (attack.get("damage_type") or "").strip()
    range_str = (attack.get("range") or "").strip()
    # v2.99.144 — Eldritch Spear invocation extends Eldritch Blast
    # range from 120 ft to 300 ft (PHB p.110). When the helper
    # returns a non-zero value, override the sheet-authored range
    # so the v2.49.76 _check_cast_range gate accepts long-range
    # shots. The original `range_str` is preserved on the response
    # via `range_ft_base` for chat-card display continuity.
    _eldritch_spear_ft = _pc_eldritch_spear_range_ft(sheet, attack)
    if _eldritch_spear_ft > 0:
        range_str = f"{_eldritch_spear_ft} ft"
    save_dc = int(attack.get("save_dc") or 0)
    save_ability = (attack.get("save_ability") or "").strip().upper()
    desc = (attack.get("desc") or "").strip()
    # v2.99.81 — Monk Martial Arts die substitution. RAW (PHB p.78):
    # unarmed strikes + monk weapons use a level-scaling die in
    # place of the weapon's normal damage. Only upgrades (never
    # downgrades) so a sheet-authored larger die wins. The attack
    # name is the gate (must contain "unarmed strike" or "martial
    # arts" — see _attack_is_martial_arts_candidate). Non-Monk
    # sheets short-circuit on _monk_martial_arts_die returning "".
    damage_expr_raw = _apply_monk_martial_arts_die(
        sheet, str(attack.get("name") or ""), damage_expr_raw,
    )
    # v2.99.83 — Fighting Style: Dueling. +2 to damage when wielding
    # a single 1H melee weapon. The helper short-circuits on style
    # mismatch / non-melee attacks. Appended as "+2" to the damage
    # expression so the breakdown reads "1d8+4+2" (the source is
    # the sheet's authored Fighting Style — visible in the chat
    # card's attack name + the next ship can replace with a labeled
    # uplift via _compute_attack_auto_uplifts if needed).
    _dueling = _pc_dueling_bonus(sheet, attack)
    if _dueling and damage_expr_raw:
        damage_expr_raw = f"{damage_expr_raw}+{_dueling}"
    # v2.261.0 — Bracers of Archery (RAW DMG p.156): +2 to damage rolls on
    # ranged attacks made with a longbow or shortbow. The bonus rides an
    # equipped + attuned item via _equipped_item_effects; gated on the attack
    # being a ranged weapon AND the weapon name reading "bow" (but not
    # "crossbow", which RAW excludes). Appended to the damage expression so
    # the breakdown surfaces the +2 alongside the ability mod.
    _bracers_bonus = int(
        _equipped_item_effects(sheet).get("ranged_bow_damage_bonus") or 0
    )
    if _bracers_bonus and damage_expr_raw and _attack_is_ranged_weapon(attack):
        _atk_name_l = str(attack.get("name") or "").lower()
        if "bow" in _atk_name_l and "crossbow" not in _atk_name_l:
            damage_expr_raw = f"{damage_expr_raw}+{_bracers_bonus}"
    # v2.99.87 — Fighting Style: Two-Weapon Fighting. Off-hand
    # attacks (attack.off_hand=True) by RAW don't add the ability
    # mod to damage. With the TWF style, the mod is restored —
    # appended to the damage expression here. _two_weapon_fighting_ability_mod
    # derives the mod from attack_bonus − proficiency_bonus (with
    # a DEX/STR sheet-side fallback). Negative mods still apply
    # (RAW: "unless that modifier is negative" for off-hand without
    # TWF; with TWF the mod always applies, even if negative).
    if _pc_two_weapon_fighting_eligible(sheet, attack) and damage_expr_raw:
        _twf_mod = _two_weapon_fighting_ability_mod(sheet, attack)
        if _twf_mod != 0:
            damage_expr_raw = (
                f"{damage_expr_raw}+{_twf_mod}" if _twf_mod > 0
                else f"{damage_expr_raw}{_twf_mod}"
            )
    # v2.99.89 — Eldritch Invocation: Agonizing Blast (Warlock
    # Lv 2+, PHB p.110). When the Warlock has the invocation on
    # their feats list AND the attack is Eldritch Blast, add the
    # CHA modifier to each beam's damage. Pre-v2.99.89 Magnus's
    # demo sheet baked the +3 into the Eldritch Blast damage
    # ("1d10+3"); v2.99.89 strips it to "1d10" and adds it back
    # here so the source of the +3 is visible in the audit trail
    # (the same "+3 [Agonizing]" treatment as Rage / Hex / etc.).
    _agonizing = _pc_agonizing_blast_bonus(sheet, attack)
    if _agonizing and damage_expr_raw:
        damage_expr_raw = (
            f"{damage_expr_raw}+{_agonizing}" if _agonizing > 0
            else f"{damage_expr_raw}{_agonizing}"
        )
    # v2.99.93 — Hex Warrior damage swap. Mirror of the attack-roll
    # delta above: append the CHA - original ability mod delta to
    # the damage expression so the bound weapon's damage uses CHA
    # instead of STR/DEX. Same helper, no recompute needed for
    # consistency — both calls return identical deltas for the
    # same (sheet, attack) tuple.
    _hex_warrior_delta_dmg = _pc_hex_warrior_bonus(sheet, attack)
    if _hex_warrior_delta_dmg and damage_expr_raw:
        damage_expr_raw = (
            f"{damage_expr_raw}+{_hex_warrior_delta_dmg}"
            if _hex_warrior_delta_dmg > 0
            else f"{damage_expr_raw}{_hex_warrior_delta_dmg}"
        )
    # v2.213.0 — STR-override Phase 1b (docs/plans/str-override.md):
    # an equipped ability-score override (Belt of Giant Strength,
    # DMG p.155) raises the weapon's effective STR, so the modifier
    # delta mod(effective)−mod(base) appends to damage. _pc_attack_
    # ability_override_delta resolves the weapon's backing ability and
    # returns 0 for DEX-keyed attacks, so a STR belt never inflates a
    # bow. Mirrors the Hex Warrior swap above; applied to the attack
    # roll in the to-hit block below.
    _str_override_delta = _pc_attack_ability_override_delta(sheet, attack)
    if _str_override_delta > 0 and damage_expr_raw:
        damage_expr_raw = f"{damage_expr_raw}+{_str_override_delta}"

    is_save = save_dc > 0 and save_ability

    # v2.49.76 — Phase 2D range-enforcement gate. The attack's
    # ``range`` field (e.g. "5 ft" / "30/120 ft") is parsed against
    # the caster's + target's token positions. Same override semantics
    # as /cast_spell: GM auto-bypass, player override + not strict,
    # otherwise enforced. Skipped when no target_combatant_id is
    # supplied (the caller didn't pick a target — the existing
    # untargeted attack flow stays unchanged for "I rolled an attack
    # for the GM to assign").
    if target_combatant_id:
        _override_range = bool(body.get("override_range"))
        _range_err = _check_cast_range(
            db, campaign, char,
            range_str, name,
            target_combatant_id, None, None,
            override_range=_override_range,
            user_is_gm=user_is_gm,
            strict=strict,
        )
        if _range_err:
            return JSONResponse(status_code=409, content=_range_err)

    # v2.20.0 Phase B: detect Rage-driven advantage on STR-based
    # attacks. RAW heuristic: physical damage type + barbarian's Rage
    # buff active = advantage on the d20 attack roll. Stacks with the
    # character's existing roll_state (advantage + advantage = still
    # advantage; advantage + disadvantage = even per RAW, which
    # ``_apply_roll_state`` already handles when both directions
    # are stamped).
    rage_advantage = _attacker_has_str_attack_advantage(campaign_id, char.id, damage_type)
    # v2.49.115 Phase B: target's Patient Defense buff (v2.49.112)
    # → disadvantage on the d20 attack roll. RAW Dodge interaction
    # with Rage: advantage + disadvantage cancel to a straight roll
    # (PHB p.173 "If circumstances cause a roll to have both advantage
    # and disadvantage, you are considered to have neither of them").
    # Handled in the dice-expression patch below.
    target_dodging = _target_has_dodging(campaign_id, target_combatant_id)
    # v2.49.238 Phase B: target's Reckless Attack buff grants the
    # attacker advantage on the d20. Combines with rage_advantage as
    # an OR (both fire? still one advantage source). Combines with
    # target_dodging as a cancel (advantage + disadvantage = none).
    target_grants_advantage = _target_grants_advantage_to_attackers(
        campaign_id, target_combatant_id,
    )
    # v2.97.48 — Protection from Evil and Good attacker-disadvantage.
    # If the target carries PFE&G AND the attacker's creature type
    # is in the buff's protected list (aberration / celestial /
    # elemental / fey / fiend / undead), the d20 attack roll gets
    # disadvantage. Folds into the same cancel logic as
    # target_dodging. Lookups: the attacker's combatant (for the
    # runtime creature_type override set in tests + by GM via
    # PUT /battle), then char.sheet, then NPC template.
    _attacker_cb = None
    _atk_state = hub.get_battle(campaign_id)
    if _atk_state:
        for _c in (_atk_state.get("combatants") or []):
            if _c.get("char_id") == char.id:
                _attacker_cb = _c
                break
    _attacker_type = _attacker_creature_type(db, char.id, _attacker_cb)
    target_pfeag_blocks_type = _target_pfeag_blocks_attacker_type(
        campaign_id, target_combatant_id, _attacker_type,
    )
    # v2.252.0 — Phase 4a: target wears Cloak of Displacement (or any
    # equipped + attuned item with `incoming_attacks_have_disadvantage`)
    # → attacks against it roll at disadvantage. Source name (or None);
    # folds into both branches' disadvantage source set below.
    target_cloak_dis = _target_wearer_imposes_attack_disadvantage(
        db, campaign_id, target_combatant_id,
    )

    # v2.97.53 — Sanctuary ends-on-offense trigger. Closes the second
    # of the v2.97.45-filed Sanctuary mechanical halves. RAW: "The
    # spell ends if the warded creature attacks or casts a spell that
    # affects an enemy creature." We drop the attacker's own Sanctuary
    # buff before the v2.97.52 target-Sanctuary gate fires, since RAW
    # the action of attacking ends the spell — whether or not the
    # attack itself lands. The drop also clears the catalog marker so
    # subsequent attacks in the same turn don't fire the broadcast a
    # second time.
    try:
        await _drop_attacker_sanctuary_on_offense(
            campaign_id, char.id, char.name,
        )
    except Exception:
        pass

    # v2.97.52 — Sanctuary attacker-Wis-save gate. Closes the first of
    # the v2.97.45-filed Sanctuary mechanical hooks. If the target
    # carries Sanctuary, the attacker must make a Wis save vs the
    # caster's spell DC (stamped on the buff at install time). On
    # fail, the attack is lost: the action chip still flips RAW
    # ("the creature loses the attack"), the roll is logged for
    # transparency, a feature_used(source=sanctuary) broadcast names
    # the block, and the endpoint returns early with
    # ``sanctuary_blocked=True``. AoE bypasses (not modeled — single-
    # target /use_attack only). Skipped on self-targeted attacks
    # (rare; attacking yourself shouldn't fire the gate since RAW it's
    # specifically "any creature who targets the warded creature").
    _sanc_dc = _target_sanctuary_dc(campaign_id, target_combatant_id)
    if (
        _sanc_dc > 0
        and target_combatant_id
        and (_attacker_cb is None or _attacker_cb.get("id") != target_combatant_id)
    ):
        _wis_mod, _ = _resolve_stat_modifier(sheet, "dnd5e", "wis_save")
        _wis_expr = f"1d20{_wis_mod:+d}"
        try:
            _wis_r = dice_mod.roll(_wis_expr)
            _wis_rolled = int(_wis_r.total)
            _wis_breakdown = _wis_r.breakdown
        except dice_mod.DiceParseError:
            _wis_rolled = 0
            _wis_breakdown = ""
        _wis_passed = _wis_rolled >= _sanc_dc
        await hub.broadcast(campaign_id, {
            "type": "roll",
            "data": {
                "expression": _wis_expr,
                "total": _wis_rolled,
                "breakdown": _wis_breakdown,
                "note": (
                    f"🕊️ Sanctuary · {char.name} Wis save "
                    f"vs DC {_sanc_dc}"
                ),
                "user_name": char.name,
                "char_name": char.name,
                "visibility": Visibility.PUBLIC.value,
                "dc": _sanc_dc,
            },
        })
        if not _wis_passed:
            # RAW: attack still costs the action. Flip the chip before
            # the early return so the economy state matches a normal
            # attack (UI shows action chip used, prevents the player
            # from spamming retries against the warded target).
            await _mark_battle_economy(campaign_id, char.id, "action")
            await hub.broadcast(campaign_id, {
                "type": "feature_used",
                "data": {
                    "source": "sanctuary",
                    "char_name": char.name,
                    "target_combatant_id": target_combatant_id,
                    "save_dc": _sanc_dc,
                    "save_rolled": _wis_rolled,
                    "label": f"Sanctuary blocked {char.name}'s attack",
                },
            })
            return {
                "ok": True,
                "hit": False,
                "sanctuary_blocked": True,
                "save_dc": _sanc_dc,
                "save_rolled": _wis_rolled,
                "save_passed": False,
                "save_breakdown": _wis_breakdown,
            }

    # v2.97.34 — buff-driven attack-roll modifiers. Sacred Weapon
    # (v2.97.29) adds +CHA mod, Bless (v2.97.31) adds +1d4, Bane
    # (v2.97.33) adds -1d4. Each helper returns 0 / False when the
    # corresponding buff isn't active on the attacker. We compute
    # them once up-front so both the bonused and no-bonus branches
    # below append the same string suffix.
    _sw_attack_bonus = _attacker_sacred_weapon_attack_bonus(
        campaign_id, char.id, sheet,
    )
    _has_bless_attack = _attacker_has_bless(campaign_id, char.id)
    _has_bane_attack = _attacker_has_bane(campaign_id, char.id)
    _buff_attack_suffix = ""
    if _sw_attack_bonus > 0:
        _buff_attack_suffix += f"+{_sw_attack_bonus}"
    if _has_bless_attack:
        _buff_attack_suffix += "+1d4"
    if _has_bane_attack:
        _buff_attack_suffix += "-1d4"

    # Build the to-hit expression. Accept "+5", "5", "1d4+3" etc.
    attack_total = None
    attack_breakdown = ""
    attack_roll_state_applied = ""
    # v2.99.21 — Halfling Lucky attack-roll intercept tracker.
    # Set by _maybe_halfling_lucky_attack_reroll when the kept d20
    # was 1 and the attacker is a Halfling. The broadcast fires
    # after the standard attack-result broadcast lands.
    _hl_old_d20: "int | None" = None
    _hl_new_d20: "int | None" = None
    if not is_save and attack_bonus_raw:
        bonus_expr = attack_bonus_raw if attack_bonus_raw.startswith(("+", "-"))\
            or any(c.isalpha() for c in attack_bonus_raw)\
            else "+" + attack_bonus_raw
        atk_expr = "1d20" + (bonus_expr if bonus_expr.startswith(("+", "-")) else "+" + bonus_expr)
        # v2.99.83 — Fighting Style: Archery. +2 to the attack roll
        # when the attacker has Archery style AND the attack is a
        # ranged weapon attack (range contains "/" or has a single
        # range > 15 ft). Pre-v2.99.83 the demo's Rowan had the +2
        # baked into the sheet's attack_bonus; v2.99.83 strips the
        # pre-bake (Longbow now "+7") and adds it here so the
        # source of the +2 surfaces in the chat-card breakdown
        # parallel to Rage / Bless / other auto-uplifts.
        _archery = _pc_archery_bonus(sheet, attack)
        if _archery:
            atk_expr += f"+{_archery}"
        # v2.99.93 — Eldritch Invocation: Hex Warrior. When the
        # attacker has the invocation + the attack is bound, swap
        # the original ability mod (STR/DEX) for CHA. Same delta
        # appended to both the attack roll AND the damage expression
        # (see the damage block below).
        _hex_warrior_delta = _pc_hex_warrior_bonus(sheet, attack)
        if _hex_warrior_delta:
            atk_expr += (
                f"+{_hex_warrior_delta}" if _hex_warrior_delta > 0
                else f"{_hex_warrior_delta}"
            )
        # v2.213.0 — STR-override Phase 1b: append the same effective-STR
        # modifier delta computed for damage above to the to-hit roll, so
        # an equipped Belt of Giant Strength boosts attack rolls as well.
        if _str_override_delta > 0:
            atk_expr += f"+{_str_override_delta}"
        # v2.97.34 — append buff-driven attack modifiers (Sacred
        # Weapon / Bless / Bane). The suffix is "" when none apply,
        # so this is a no-op for ordinary attacks.
        atk_expr += _buff_attack_suffix
        # v2.2.0: apply character roll_state to the attack d20.
        # v2.20.0: layer Rage advantage on top by stamping "a" if it
        # isn't already there. ``_apply_roll_state`` already handles
        # the kh1 / kl1 suffix; we add ours if neither direction was
        # set by the character's roll_state.
        atk_expr, attack_roll_state_applied = _apply_roll_state(
            atk_expr, (char.sheet or {}).get("roll_state"),
        )
        # v2.49.115 Phase B: layer adv/dis from buff sources. RAW PHB
        # p.173 — if advantage AND disadvantage both apply, the roll
        # is straight (canceled). v2.49.238: third source —
        # Reckless Attack on the target — folds in alongside Rage as
        # an advantage source. The combined OR keeps the cancel
        # logic clean: any-advantage + any-disadvantage = straight.
        # v2.132.0 — Assassinate advantage half (Assassin Rogue Lv 3+,
        # PHB p.97). Subclass-gated so a non-Assassin caller's swing at a
        # target whose has_acted is False isn't accidentally granted
        # advantage. Pairs with the v2.131.0 auto-crit half.
        assassinate_target_hasnt_acted = (
            _pc_has_assassin_subclass(sheet, 3)
            and _target_hasnt_acted_yet(campaign_id, target_combatant_id)
        )
        # v2.152.0 — Phase 2a advantage/disadvantage automation.
        # Standard 5e condition buffs on the attacker / target push
        # entries onto the same adv/dis source set as Rage / Dodge /
        # Reckless. RAW order matters only for the label; the cancel
        # logic is set-OR.
        _attacker_invisible_adv = _attacker_has_invisible_advantage(sheet)
        _target_adv_condition = _target_has_condition_advantage(
            campaign_id, target_combatant_id,
        )
        # v2.158.53 — Vow of Enmity Phase 2 read (Vengeance Paladin Lv 3+
        # CD, PHB p.88): advantage on attacks vs the marked combatant.
        _voe_advantage = _attacker_has_vow_of_enmity_vs_target(
            campaign_id, char.id, target_combatant_id,
        )
        has_adv = (
            rage_advantage or target_grants_advantage
            or assassinate_target_hasnt_acted
            or _attacker_invisible_adv
            or bool(_target_adv_condition)
            or _voe_advantage
        )
        adv_label = (
            "rage" if rage_advantage else
            "reckless" if target_grants_advantage else
            "assassinate_hasnt_acted" if assassinate_target_hasnt_acted else
            "invisible" if _attacker_invisible_adv else
            f"target_{_target_adv_condition}" if _target_adv_condition else
            "vow_of_enmity" if _voe_advantage else ""
        )
        # v2.99.207 — Elusive (Rogue Lv 18+). RAW PHB p.96: "No
        # attack roll has advantage against you while you aren't
        # incapacitated." Suppresses ALL incoming advantage when
        # the target is a Lv 18+ Rogue. v1 simplification skips
        # the "incapacitated" gate (filed).
        _target_elusive = _target_has_elusive(
            campaign_id, target_combatant_id,
        )
        if has_adv and _target_elusive:
            has_adv = False
            adv_label = ""
            attack_roll_state_applied = (
                attack_roll_state_applied or "elusive_suppressed"
            )
        # v2.97.48 — fold target_pfeag_blocks_type into the
        # disadvantage source set alongside target_dodging.
        # v2.99.220 — Feral Senses (Ranger Lv 18+) suppresses the
        # "attacker can't see target" disadvantage. When the body
        # field is set AND the attacker doesn't have Feral Senses,
        # add it as a disadvantage source.
        _attacker_cant_see = (
            attacker_cant_see_target
            and not _pc_has_feral_senses(char.sheet or {})
        )
        # v2.137.0 — Ancestral Protectors Phase 1b: the marked creature
        # has disadvantage on attack rolls vs anyone OTHER than the
        # protector (the raging Ancestral Guardian Lv 3+ that struck
        # them). Reads the attacker's combatant buffs for the mark
        # installed at the v2.136.0 post-hit hook.
        _ap_marked_vs_other = _attacker_marked_by_ancestral_protectors_vs_other(
            campaign_id, char.id, target_combatant_id,
        )
        # v2.140.0 — Unwavering Mark Phase 1b: marked creature within 5
        # ft of the Cavalier has disadvantage on attacks against non-
        # Cavalier targets. Reads the v2.139.0 install + the 5-ft
        # proximity gate via `_distance_ft_between_chars`.
        _um_marked_vs_other = _attacker_marked_by_unwavering_mark_within_5ft_vs_other(
            db, campaign_id, char.id, target_combatant_id,
        )
        # v2.152.0 — Phase 2a: attacker's own standard 5e disabling
        # conditions (Blinded / Poisoned / Restrained / Frightened /
        # Prone) impose disadvantage on its attack roll. Reads the PC
        # `_buffs_active` mirror so we don't need a second hub lookup.
        _attacker_dis_condition = _attacker_has_condition_disadvantage(sheet)
        has_dis = (
            target_dodging or target_pfeag_blocks_type
            or _attacker_cant_see or _ap_marked_vs_other
            or _um_marked_vs_other
            or bool(_attacker_dis_condition)
            or bool(target_cloak_dis)
        )
        dis_label = (
            "dodging" if target_dodging else
            "pfeag" if target_pfeag_blocks_type else
            "cant_see" if _attacker_cant_see else
            "ancestral_protectors_vs_other" if _ap_marked_vs_other else
            "unwavering_mark_vs_other" if _um_marked_vs_other else
            f"attacker_{_attacker_dis_condition}"
            if _attacker_dis_condition else
            "cloak_of_displacement" if target_cloak_dis else ""
        )
        if has_adv and has_dis:
            attack_roll_state_applied = f"canceled_{adv_label}_vs_{dis_label}"
        elif has_adv and "kh1" not in atk_expr and "kl1" not in atk_expr:
            atk_expr = atk_expr.replace("1d20", "2d20kh1", 1)
            attack_roll_state_applied = f"advantage_{adv_label}"
        elif has_dis and "kh1" not in atk_expr and "kl1" not in atk_expr:
            atk_expr = atk_expr.replace("1d20", "2d20kl1", 1)
            attack_roll_state_applied = f"disadvantage_{dis_label}"
        try:
            r = dice_mod.roll(atk_expr)
            # v2.99.21 — Halfling Lucky attack-roll intercept. Reroll
            # the full expression once when the kept d20 == 1. Track
            # the old/new values so the broadcast can surface the
            # trigger after the response broadcast lands.
            r, _hl_old_d20, _hl_new_d20 = _maybe_halfling_lucky_attack_reroll(
                char, atk_expr, r,
            )
            attack_total = r.total
            attack_breakdown = r.breakdown
        except dice_mod.DiceParseError:
            attack_total = None
            attack_breakdown = ""
            _hl_old_d20 = None
            _hl_new_d20 = None
    elif not is_save:
        # No bonus given — flat d20
        atk_expr, attack_roll_state_applied = _apply_roll_state(
            "1d20", (char.sheet or {}).get("roll_state"),
        )
        # v2.97.34 — append buff-driven attack modifiers on the
        # bonusless branch too (Sacred Weapon / Bless / Bane), so
        # an attack with no character to-hit bonus still gets the
        # buff dice/mod folded in.
        atk_expr += _buff_attack_suffix
        # Same Phase B adv/dis layering as the bonused branch above.
        # v2.132.0 — Assassinate advantage half (Assassin Rogue Lv 3+,
        # PHB p.97). Subclass-gated so a non-Assassin caller's swing at a
        # target whose has_acted is False isn't accidentally granted
        # advantage. Pairs with the v2.131.0 auto-crit half.
        assassinate_target_hasnt_acted = (
            _pc_has_assassin_subclass(sheet, 3)
            and _target_hasnt_acted_yet(campaign_id, target_combatant_id)
        )
        # v2.152.0 — Phase 2a advantage/disadvantage automation
        # (bonusless branch mirror). Same source-set fold as the
        # bonused branch above; see comment there for the contract.
        _attacker_invisible_adv = _attacker_has_invisible_advantage(sheet)
        _target_adv_condition = _target_has_condition_advantage(
            campaign_id, target_combatant_id,
        )
        # v2.158.53 — Vow of Enmity Phase 2 read (bonusless branch mirror).
        _voe_advantage = _attacker_has_vow_of_enmity_vs_target(
            campaign_id, char.id, target_combatant_id,
        )
        has_adv = (
            rage_advantage or target_grants_advantage
            or assassinate_target_hasnt_acted
            or _attacker_invisible_adv
            or bool(_target_adv_condition)
            or _voe_advantage
        )
        adv_label = (
            "rage" if rage_advantage else
            "reckless" if target_grants_advantage else
            "assassinate_hasnt_acted" if assassinate_target_hasnt_acted else
            "invisible" if _attacker_invisible_adv else
            f"target_{_target_adv_condition}" if _target_adv_condition else
            "vow_of_enmity" if _voe_advantage else ""
        )
        # v2.99.207 — Elusive (Rogue Lv 18+). RAW PHB p.96: "No
        # attack roll has advantage against you while you aren't
        # incapacitated." Suppresses ALL incoming advantage when
        # the target is a Lv 18+ Rogue. v1 simplification skips
        # the "incapacitated" gate (filed).
        _target_elusive = _target_has_elusive(
            campaign_id, target_combatant_id,
        )
        if has_adv and _target_elusive:
            has_adv = False
            adv_label = ""
            attack_roll_state_applied = (
                attack_roll_state_applied or "elusive_suppressed"
            )
        # v2.97.48 — fold target_pfeag_blocks_type into the
        # disadvantage source set alongside target_dodging.
        # v2.99.220 — Feral Senses (Ranger Lv 18+) suppresses the
        # "attacker can't see target" disadvantage. When the body
        # field is set AND the attacker doesn't have Feral Senses,
        # add it as a disadvantage source.
        _attacker_cant_see = (
            attacker_cant_see_target
            and not _pc_has_feral_senses(char.sheet or {})
        )
        # v2.137.0 — Ancestral Protectors Phase 1b: the marked creature
        # has disadvantage on attack rolls vs anyone OTHER than the
        # protector (the raging Ancestral Guardian Lv 3+ that struck
        # them). Reads the attacker's combatant buffs for the mark
        # installed at the v2.136.0 post-hit hook.
        _ap_marked_vs_other = _attacker_marked_by_ancestral_protectors_vs_other(
            campaign_id, char.id, target_combatant_id,
        )
        # v2.140.0 — Unwavering Mark Phase 1b: marked creature within 5
        # ft of the Cavalier has disadvantage on attacks against non-
        # Cavalier targets. Reads the v2.139.0 install + the 5-ft
        # proximity gate via `_distance_ft_between_chars`.
        _um_marked_vs_other = _attacker_marked_by_unwavering_mark_within_5ft_vs_other(
            db, campaign_id, char.id, target_combatant_id,
        )
        # v2.152.0 — Phase 2a attacker-condition disadvantage (bonusless
        # branch mirror). See bonused branch above for the helper.
        _attacker_dis_condition = _attacker_has_condition_disadvantage(sheet)
        has_dis = (
            target_dodging or target_pfeag_blocks_type
            or _attacker_cant_see or _ap_marked_vs_other
            or _um_marked_vs_other
            or bool(_attacker_dis_condition)
            or bool(target_cloak_dis)
        )
        dis_label = (
            "dodging" if target_dodging else
            "pfeag" if target_pfeag_blocks_type else
            "cant_see" if _attacker_cant_see else
            "ancestral_protectors_vs_other" if _ap_marked_vs_other else
            "unwavering_mark_vs_other" if _um_marked_vs_other else
            f"attacker_{_attacker_dis_condition}"
            if _attacker_dis_condition else
            "cloak_of_displacement" if target_cloak_dis else ""
        )
        if has_adv and has_dis:
            attack_roll_state_applied = f"canceled_{adv_label}_vs_{dis_label}"
        elif has_adv and "kh1" not in atk_expr and "kl1" not in atk_expr:
            atk_expr = atk_expr.replace("1d20", "2d20kh1", 1)
            attack_roll_state_applied = f"advantage_{adv_label}"
        elif has_dis and "kh1" not in atk_expr and "kl1" not in atk_expr:
            atk_expr = atk_expr.replace("1d20", "2d20kl1", 1)
            attack_roll_state_applied = f"disadvantage_{dis_label}"
        try:
            r = dice_mod.roll(atk_expr)
            # v2.99.21 — Halfling Lucky attack-roll intercept on the
            # bonusless branch. Same shape as the bonused branch above.
            r, _hl_old_d20, _hl_new_d20 = _maybe_halfling_lucky_attack_reroll(
                char, atk_expr, r,
            )
            attack_total = r.total
            attack_breakdown = r.breakdown
        except dice_mod.DiceParseError:
            attack_total = None
            attack_breakdown = ""

    # v2.24.0 Phase T.2: detect crit from the kept d20 value. Matches
    # both "1d20[20]" (single die) and "2d20[X,20]kh1=20" (advantage
    # whose kept high was 20). Disadvantage where the LOW kept value is
    # 20 (both dice rolled 20) is also a crit — same =20 subtotal
    # pattern. Skipped for save-DC attacks (no d20 attack roll).
    # v2.49.231: Champion Fighter Lv 3+ Improved Critical lowers the
    # threshold to 19 via _attacker_crit_threshold(sheet); other classes
    # keep the natural-20 default.
    is_crit = False
    if not is_save and attack_breakdown:
        import re as _re_crit
        _crit_m = _re_crit.search(
            r"\d*d20[^d=+ ]*=(\d+)", attack_breakdown, _re_crit.IGNORECASE,
        )
        if _crit_m:
            _crit_threshold = _attacker_crit_threshold(sheet)
            # v2.99.399 — Phase 2.3: an on-hit rider buff (Hexblade's
            # Curse) can lower the crit range vs its target.
            _crit_threshold = min(
                _crit_threshold,
                _attacker_crit_range_from_buffs(
                    campaign_id, char.id, target_combatant_id),
            )
            if int(_crit_m.group(1)) >= _crit_threshold:
                is_crit = True
    # v2.131.0 — Assassinate auto-crit. Subclass-gated so a non-Assassin
    # `target_surprised: true` body is silently ignored. The d20 threshold
    # check above already ran; this elevates a non-crit hit to a crit,
    # which doubles the damage dice below. RAW says "any HIT" — the existing
    # post-roll hit/miss gate handles application-on-miss, so this stays
    # damage-roll-time only.
    if not is_save and target_surprised and _pc_has_assassin_subclass(sheet, 3):
        is_crit = True

    # Pre-roll damage if a dice expression is provided. v2.24.0 Phase
    # T.2: on a crit, double the dice (not the flat modifier) — RAW
    # "all the damage dice of a critical hit are doubled" (PHB 196).
    damage_total = None
    damage_breakdown = ""
    damage_expr_effective = damage_expr_raw
    if damage_expr_raw and is_crit:
        damage_expr_effective = _double_dice_for_crit(damage_expr_raw)
    if damage_expr_effective:
        # v2.99.85 — Fighting Style: Great Weapon Fighting. When the
        # attacker has the GWF style + the attack is 2H melee, reroll
        # 1s and 2s on the damage dice once each (keep new result per
        # RAW). Falls back to the standard dice_mod.roll when the
        # helper can't parse the expression.
        used_gwf = False
        if _pc_great_weapon_fighting_eligible(sheet, attack):
            gwf_total, gwf_breakdown = _apply_great_weapon_fighting_reroll(
                damage_expr_effective,
            )
            if gwf_total is not None:
                damage_total = gwf_total
                damage_breakdown = gwf_breakdown
                used_gwf = True
        if not used_gwf:
            try:
                r = dice_mod.roll(damage_expr_effective)
                damage_total = r.total
                damage_breakdown = r.breakdown
            except dice_mod.DiceParseError:
                damage_total = None
                damage_breakdown = ""

    # v2.20.0 Phase B: auto-uplifts from attacker's buffs + class
    # features. Reads the hub state for active buffs (Rage / Hunter's
    # Mark / Hex) + the sheet for class_features (Colossus Slayer).
    # Each uplift is a separately-rolled die expression; the list
    # rides on the broadcast as ``auto_uplifts`` for the chat card to
    # render. Damage type per uplift varies (Hex is necrotic, Rage
    # inherits weapon type, Colossus Slayer = weapon type) — resistance
    # at damage-application time will apply per type.
    auto_uplifts = _compute_attack_auto_uplifts(
        campaign_id=campaign_id,
        attacker_char_id=char.id,
        attacker_sheet=sheet,
        target_combatant_id=target_combatant_id,
        attack_damage_type=damage_type,
        is_crit=is_crit,
        weapon_damage_expr=damage_expr_raw,
        attack=attack,
        db=db,
    )
    # v2.60.0 — defer the mark-as-used calls for on-hit-only uplifts
    # (Colossus Slayer + Divine Strike) until after hit determination
    # at L ~18731. Pre-v2.60.0 the Colossus Slayer mark fired on every
    # /attack call including misses, burning the once-per-turn use on
    # a swing that never connected. Moved to the post-hit block below.

    # Aggregate auto-uplift damage into the base damage_total so the
    # existing "Total damage" line in chat cards remains accurate
    # without needing client changes. The structured list is still
    # exposed via ``auto_uplifts`` for clients that want per-type
    # rendering.
    auto_uplift_total = 0
    for u in auto_uplifts:
        try:
            auto_uplift_total += int(u.get("total") or 0)
        except (TypeError, ValueError):
            pass
    if auto_uplift_total > 0:
        if damage_total is not None:
            damage_total = damage_total + auto_uplift_total
        else:
            damage_total = auto_uplift_total
        # Append a one-line summary to the breakdown so chat-card
        # readers see "1d12+4=10 + Rage +2 + Hunter's Mark 1d6=4" inline.
        # v2.99.190 — when the uplift dict carries `vs_combatant_id`
        # (Hunter's Mark / Hex riders post-v2.99.187/.189), suffix
        # the label with "(vs NAME)" so a marked Twinned chain can
        # show which mark fired on this swing.
        suffix_parts = []
        for u in auto_uplifts:
            lbl = u.get("label") or u.get("source") or "Bonus"
            bd = u.get("breakdown") or ""
            vs_cid = u.get("vs_combatant_id") or ""
            vs_name = _lookup_combatant_name(campaign_id, vs_cid) if vs_cid else ""
            lbl_with_vs = f"{lbl} (vs {vs_name})" if vs_name else lbl
            suffix_parts.append(f"{lbl_with_vs} {bd}")
        if suffix_parts:
            damage_breakdown = (damage_breakdown + "  +  " + "  +  ".join(suffix_parts)).strip()

    # v2.16.0: per-attack uplifts. ``bonus_damage`` (e.g. "3d6" for Sneak
    # Attack) rolls separately and rides on the broadcast as its own
    # line. ``bonus_damage_label`` ("Sneak Attack" / "Divine Smite") is
    # the chat-card attribution. ``spend_spell_slot`` ({class_slug,
    # level}) atomically decrements a spell slot — used by Divine
    # Smite to consume a Paladin slot. Slot loss happens before the
    # roll so the player can't "back out" if they miss; matches the
    # design call from B.9's plan (RAW would prompt for smite ONLY on
    # hit, but the (B) roll-time intercept that would enable that is
    # filed for later).
    bonus_damage_expr = str(body.get("bonus_damage") or "").strip()
    bonus_damage_label = str(body.get("bonus_damage_label") or "").strip()[:80]
    spend_slot = body.get("spend_spell_slot") or None
    bonus_damage_total = None
    bonus_damage_breakdown = ""
    slot_spent_class = ""
    slot_spent_level = 0

    if isinstance(spend_slot, dict):
        cslug = str(spend_slot.get("class_slug") or "").strip().lower()
        try:
            slot_level = int(spend_slot.get("level") or 0)
        except (TypeError, ValueError):
            slot_level = 0
        if not cslug or slot_level < 1:
            raise HTTPException(400, "spend_spell_slot requires class_slug + level >= 1")
        all_slots = dict(sheet.get("spell_slots") or {})
        per_class = dict(all_slots.get(cslug) or {})
        slot_key = str(slot_level)
        slot = dict(per_class.get(slot_key) or {})
        total = int(slot.get("total") or 0)
        used = int(slot.get("used") or 0)
        if total <= 0 or used >= total:
            return JSONResponse(status_code=409, content={
                "error": "no_slot",
                "class_slug": cslug,
                "level": slot_level,
                "label": bonus_damage_label or "Slot-fueled uplift",
            })
        slot["total"] = total
        slot["used"] = used + 1
        per_class[slot_key] = slot
        all_slots[cslug] = per_class
        sheet["spell_slots"] = all_slots
        slot_spent_class = cslug
        slot_spent_level = slot_level
        _slot_spent_used_before = used  # v2.99.464 — for undo refund

    if bonus_damage_expr:
        # v2.24.0 Phase T.2: crit also doubles player-picked uplift
        # dice (Sneak Attack / Divine Smite). Same _double_dice_for_crit
        # helper that's applied to the base damage above.
        bonus_expr_effective = (
            _double_dice_for_crit(bonus_damage_expr) if is_crit else bonus_damage_expr
        )
        try:
            r = dice_mod.roll(bonus_expr_effective)
            bonus_damage_total = r.total
            bonus_damage_breakdown = r.breakdown
        except dice_mod.DiceParseError:
            bonus_damage_total = None
            bonus_damage_breakdown = ""

    # Persist the slot decrement (if any). The single commit at the
    # broadcast site below would be too late — by then the response
    # could be returning and the sheet state hasn't flushed.
    if slot_spent_class:
        from sqlalchemy.orm.attributes import flag_modified
        char.sheet = sheet
        flag_modified(char, "sheet")
        db.commit()

    # v2.24.0 Phase T.2: hit determination + auto-apply damage.
    # ``hit`` is computed whenever a target is set so the chat card
    # can render a Hit/Miss badge regardless of the campaign toggle.
    # Auto-apply HP changes only fires when:
    #   - campaign.auto_apply_damage is True
    #   - target_combatant_id resolves to a combatant in hub state
    #   - the attack rolled damage_total > 0
    #   - hit is True (attack_total >= target_ac)
    # Crit always hits regardless of AC. Saves (is_save=True) skip the
    # hit determination here — they're handled by T.3's save-spell
    # path (server rolls / prompts the target's save).
    attack_id = uuid.uuid4().hex[:12]
    # v2.99.464 — log the slot-fueled uplift's spell-slot spend (Divine
    # Smite, etc.) under the attack_id so the chat-card ↶ Undo refunds the
    # slot, not just the damage. The HP-undo already keys off attack_id;
    # this adds the spell_slot_spend entry to the same log.
    if slot_spent_class:
        _log_damage_entry(attack_id, {
            "kind": "spell_slot_spend",
            "campaign_id": campaign_id,
            "character_id": char.id,
            "class_slug": slot_spent_class,
            "slot_level": int(slot_spent_level),
            "used_before": int(_slot_spent_used_before),
            "spell_name": bonus_damage_label or "Divine Smite",
        })
    hit = None
    target_ac = None
    # v2.99.408 — Phase 3.3: results of any weapon_hit_save riders fired
    # on a confirmed hit (Battle Master maneuvers armed for the next hit).
    feature_save_results: list[dict] = []
    damage_applied = 0
    target_hp_before = None
    target_hp_after = None
    target_resistance_applied = False
    # v2.99.132 — surface the v2.99.127 vulnerability flag in the
    # /attack response so chat cards + UI can render the badge.
    target_vulnerability_applied = False
    target_dying = False
    target_dead = False
    target_combatant = _lookup_combatant(campaign_id, target_combatant_id) if target_combatant_id else None
    if target_combatant and not is_save and attack_total is not None:
        target_ac = _read_target_ac(db, campaign_id, target_combatant)
        hit = is_crit or (attack_total >= target_ac)
        # v2.60.0 — on-hit-only uplift bookkeeping. Strip Colossus
        # Slayer + Divine Strike from auto_uplifts on a miss (those
        # are "on hit" features per RAW; rolling their bonus dice on
        # a missed swing would inflate the chat card and confuse the
        # player). Mark "used this turn" only on a hit, so a missed
        # swing doesn't burn the once-per-turn charge.
        if not hit:
            # On-hit-only riders don't fire on a miss: strip the hardcoded
            # once-per-turn features + the v2.99.395 buff riders that carry
            # a `once_per_turn_flag` (so a missed swing neither inflates the
            # card nor burns the charge).
            auto_uplifts = [
                u for u in auto_uplifts
                if u.get("source") not in ("colossus-slayer", "divine-strike")
                and not u.get("once_per_turn_flag")
            ]
        else:
            # v2.99.400 — Phase 2.4: damage-type conversion (Planar
            # Warrior). RAW "all damage dealt by the attack becomes
            # force." Re-type the whole attack's damage on a confirmed
            # hit so the base weapon damage + every uplift apply (and
            # render) as the converted type. Computed BEFORE the
            # once-per-turn flags are marked below, since the helper
            # gates on the same `<flag>_used` economy flag the mark loop
            # sets — call it after marking and it would see itself spent.
            _conv_type = _attacker_convert_type_from_buffs(
                campaign_id, char.id, target_combatant_id,
            )
            if _conv_type:
                damage_type = _conv_type
            # v2.99.408 — Phase 3.3: fire any `weapon_hit_save` rider
            # (Battle Master maneuver armed for the next hit) against the
            # target. Runs BEFORE the once-per-turn mark loop below, which
            # marks the shared flag (the rider also carries
            # weapon_hit_bonus_dice, so its uplift stamps it).
            feature_save_results = await _fire_weapon_hit_saves(
                db, campaign_id,
                attacker_char_id=char.id, attacker_char_name=char.name,
                target_combatant=target_combatant,
                campaign=campaign, prompt_user=user,
            )
            if any(u.get("source") == "colossus-slayer" for u in auto_uplifts):
                await _mark_colossus_slayer_used(campaign_id, char.id)
            if any(u.get("source") == "divine-strike" for u in auto_uplifts):
                await _mark_divine_strike_used(campaign_id, char.id)
            # v2.99.395 — Phase 2.1: mark the once-per-turn flag for each
            # buff rider that fired on this hit so it can't fire again
            # until the GM advances the turn.
            for _u in auto_uplifts:
                _flag = _u.get("once_per_turn_flag")
                if _flag:
                    await _mark_attack_flag(campaign_id, char.id, _flag)
        if (
            hit
            and bool(campaign.auto_apply_damage)
            and (damage_total or 0) + (bonus_damage_total or 0) > 0
        ):
            total_damage = int((damage_total or 0) + (bonus_damage_total or 0))
            # v2.63.0 — F6 magical-source flag. Lets the resistance
            # gate skip "nonmagical-X" entries when the attack is
            # magical (Ki-Empowered Strikes Lv 6+, Magic Weapon spell
            # buff, Pact of the Blade, etc.). Currently the only
            # attacker-side detector is Ki-Empowered Strikes — see
            # `_attack_is_magical` for the full list + filed
            # follow-ups (Magic Weapon, Pact of the Blade, etc.).
            attack_is_magical = _attack_is_magical(sheet, name)
            apply_result = await _apply_damage_to_combatant(
                db, campaign_id, target_combatant,
                total_damage, damage_type,
                is_crit=is_crit, is_attack=True, attack_id=attack_id,
                is_magical=attack_is_magical,
                attacker_char_id=char.id,
            )
            damage_applied = apply_result["applied"]
            target_hp_before = apply_result["hp_before"]
            target_hp_after = apply_result["hp_after"]
            target_resistance_applied = apply_result["resistance_applied"]
            # v2.99.132 — capture the vulnerability flag too.
            target_vulnerability_applied = apply_result.get(
                "vulnerability_applied", False,
            )
            target_dying = apply_result["is_dying"]
            target_dead = apply_result["is_dead"]

        # v2.99.92 — Lance of Lethargy invocation. On a successful
        # Eldritch Blast hit, reduce the target's speed by 10 ft
        # until end of caster's next turn (RAW PHB p.111). v1
        # installs a 1-round buff on the target; the mechanical
        # speed reduction at the Mov chip / movement-enforcement
        # layer is filed for a follow-up (the buff carries
        # effects.speed_reduction_ft so future readers can pick it
        # up). Skipped on dead targets.
        # v2.136.0 — Ancestral Protectors install hook (Path of the
        # Ancestral Guardian Barbarian Lv 3+, XGE p.9). When a raging
        # Ancestral Guardian hits a target, install a 1-round mark
        # buff on the target so subsequent attacks the marked creature
        # makes pick up the disadvantage gate (Phase 1b) + the
        # protector's allies the resistance gate (Phase 2).
        if hit and not target_dead:
            try:
                ap_result = await _apply_ancestral_protectors_on_hit(
                    campaign_id, char.id, char.name,
                    sheet, target_combatant,
                )
                if ap_result is not None:
                    await hub.broadcast(campaign_id, {
                        "type": "feature_used",
                        "data": {
                            "character_id": char.id,
                            "character_name": char.name,
                            "feature_name": "👻 Ancestral Protectors",
                            "feature_desc": (
                                f"{ap_result['target_name']} is marked by "
                                f"{char.name}'s warrior spirits until the "
                                f"start of {char.name}'s next turn."
                            ),
                            "source": "ancestral-protectors",
                            "target_combatant_id": ap_result["target_combatant_id"],
                            "target_name": ap_result["target_name"],
                            "protected_char_id": ap_result["protected_char_id"],
                        },
                    })
            except Exception:
                logging.exception(
                    "Ancestral Protectors install failed for char_id=%s",
                    char.id,
                )

        # v2.158.28 — Form of the Beast Phase 2 bite self-heal rider
        # (Path of the Beast Barbarian Lv 3+ TCE). Once per turn when
        # the attacker damages a creature with the BITE form (not
        # claws / tail), they regain HP equal to their proficiency
        # bonus — provided their current HP is less than half max.
        # Gates + helper live in `_apply_form_of_the_beast_bite_on_hit`.
        # RAW: "when you damage a creature" — killing the target still
        # qualifies, so this hook fires on hits regardless of
        # target_dead (unlike Ancestral Protectors / Unwavering Mark
        # which need a live target).
        if hit and damage_applied > 0:
            try:
                fb_bite_result = await _apply_form_of_the_beast_bite_on_hit(
                    db, campaign_id, char.id, char.name,
                    sheet, attack, damage_applied,
                )
                if fb_bite_result is not None:
                    await hub.broadcast(campaign_id, {
                        "type": "feature_used",
                        "data": {
                            "character_id": char.id,
                            "character_name": char.name,
                            "feature_name": (
                                f"🦷 Form of the Beast — Bite self-heal "
                                f"+{fb_bite_result['healed']} HP"
                            ),
                            "feature_desc": (
                                f"{char.name}'s bite drains vitality: "
                                f"regained {fb_bite_result['healed']} HP "
                                f"(proficiency bonus +{fb_bite_result['prof_bonus']}) "
                                f"after damaging a creature while below "
                                f"half HP. (Path of the Beast Barbarian "
                                f"Lv 3+ TCE; once per turn.)"
                            ),
                            "source": "form-of-the-beast-bite-heal",
                            "healed": fb_bite_result["healed"],
                            "prof_bonus": fb_bite_result["prof_bonus"],
                            "hp_before": fb_bite_result["hp_before"],
                            "hp_after": fb_bite_result["hp_after"],
                        },
                    })
            except Exception:
                logging.exception(
                    "Form of the Beast bite self-heal failed for char_id=%s",
                    char.id,
                )

        # v2.139.0 — Unwavering Mark install hook (Cavalier Fighter Lv
        # 3+, XGE p.13). On a melee weapon hit, install a 1-round mark
        # buff on the target. Phase 1b will read it at adv layering;
        # Phase 2 ships the bonus-action punish attack.
        if hit and not target_dead:
            try:
                um_result = await _apply_unwavering_mark_on_hit(
                    campaign_id, char.id, char.name,
                    sheet, attack, target_combatant,
                )
                if um_result is not None:
                    await hub.broadcast(campaign_id, {
                        "type": "feature_used",
                        "data": {
                            "character_id": char.id,
                            "character_name": char.name,
                            "feature_name": "🛡️ Unwavering Mark",
                            "feature_desc": (
                                f"{um_result['target_name']} is marked by "
                                f"{char.name} until the end of "
                                f"{char.name}'s next turn."
                            ),
                            "source": "unwavering-mark",
                            "target_combatant_id": um_result["target_combatant_id"],
                            "target_name": um_result["target_name"],
                            "cavalier_char_id": um_result["cavalier_char_id"],
                        },
                    })
            except Exception:
                logging.exception(
                    "Unwavering Mark install failed for char_id=%s",
                    char.id,
                )

        if hit and not target_dead:
            try:
                lol_result = await _apply_lance_of_lethargy(
                    campaign_id, char.id, char.name,
                    sheet, attack, target_combatant,
                )
                if lol_result is not None:
                    await hub.broadcast(campaign_id, {
                        "type": "feature_used",
                        "data": {
                            "character_id": char.id,
                            "character_name": char.name,
                            "feature_name": "🐌 Lance of Lethargy",
                            "feature_desc": (
                                f"{char.name} slows "
                                f"{lol_result['target_name']} by 10 ft "
                                f"until end of next turn."
                            ),
                            "source": "lance-of-lethargy",
                            "target_combatant_id": lol_result["target_combatant_id"],
                            "target_name": lol_result["target_name"],
                            "speed_reduction_ft": lol_result["speed_reduction_ft"],
                        },
                    })
            except Exception:
                logging.exception(
                    "Lance of Lethargy install failed for char_id=%s",
                    char.id,
                )

        # v2.158.101 — Phase 7a: magic-item nat-20 post-hit hooks.
        # Reads ``attack._slug``, looks for ``on_nat_20`` in
        # ``_MAGIC_ITEM_ATTACK_RIDERS``, and (when the d20 raw is 20,
        # the wielder is attuned, and the target's creature_type
        # isn't on the exempt list) applies the effect — today Vorpal
        # Sword's decapitation. The helper re-parses the d20 from
        # the breakdown so this fires only on a literal 20, not on
        # the Improved Critical 19 threshold. Skipped on dead
        # targets (already-resolved kill).
        if hit and not target_dead:
            try:
                vorpal_result = await _apply_magic_item_nat_20_effect(
                    db, campaign_id, char, sheet, attack,
                    target_combatant, attack_breakdown,
                    campaign=campaign,
                    prompt_user=user,
                )
                if vorpal_result is not None:
                    # v2.158.103 — Phase 7c: per-effect desc + target
                    # death determination. Vorpal's "decap" sets
                    # target_dead True; Sharpness's "damage" leaves it
                    # to the underlying damage helper's HP read.
                    _eff = vorpal_result.get("effect", "decap")
                    if _eff == "decap":
                        _desc = (
                            f"{char.name} rolls a natural 20 and "
                            f"cleaves {vorpal_result['target_name']}'s "
                            f"head clean off. (Vorpal Sword, RAW DMG p.209.)"
                        )
                        target_dead = True
                    elif _eff == "slay_save":
                        # v2.335.0 — Nine Lives Stealer: the slay only
                        # reaches the broadcast when the target FAILED its
                        # CON save (the helper returns None otherwise), so
                        # by the time we're here the target is slain.
                        _desc = (
                            f"{char.name} rolls a natural 20 — the sword "
                            f"tears the life force from "
                            f"{vorpal_result['target_name']}, who fails the "
                            f"DC 15 Constitution save and is slain instantly. "
                            f"(Nine Lives Stealer, RAW DMG p.183.)"
                        )
                        target_dead = True
                    elif _eff == "damage":
                        _desc = (
                            f"{char.name} rolls a natural 20 — the blade "
                            f"flares with arcane light, dealing "
                            f"{vorpal_result['hp_dealt']} extra "
                            f"{vorpal_result['damage_type']} damage. "
                            f"(Sword of Sharpness, RAW DMG p.206.)"
                        )
                    else:
                        _desc = (
                            f"{char.name} rolls a natural 20 against "
                            f"{vorpal_result['target_name']}."
                        )
                    await hub.broadcast(campaign_id, {
                        "type": "feature_used",
                        "data": {
                            "character_id": char.id,
                            "character_name": char.name,
                            "feature_name": vorpal_result["label"],
                            "feature_desc": _desc,
                            "source": f"item-{vorpal_result['slug']}-nat20",
                            "target_combatant_id": vorpal_result["target_combatant_id"],
                            "target_name": vorpal_result["target_name"],
                            "hp_dealt": vorpal_result["hp_dealt"],
                            # v2.320.1 — surface the rider's resolved
                            # damage_type as a top-level broadcast field. Prior
                            # to this, damage_type only appeared inside the
                            # `feature_desc` prose ("...extra slashing
                            # damage."), so tests had to substring-match the
                            # desc instead of reading a field. Now it's
                            # straight off the dispatcher's return value
                            # (`vorpal_result["damage_type"]`), which already
                            # captures the catalog override OR the attack-row
                            # fallback used by Vicious Weapon (v2.320.0).
                            "damage_type": vorpal_result["damage_type"],
                        },
                    })
            except Exception:
                logging.exception(
                    "Vorpal nat-20 decap failed for char_id=%s",
                    char.id,
                )

        # v2.158.102 — Phase 7b: magic-item on-hit save-or-effect
        # hooks. Demon Slayer (RAW DMG p.166): on every hit vs. a
        # fiend, the target makes a DC 15 WIS save or is frightened
        # of the wielder until the end of the wielder's next turn.
        # The helper gates on attunement + the rider's condition
        # (fiend) + reads the catalog's on_hit_save row, then
        # delegates to _resolve_feature_save which auto-rolls NPC
        # saves + installs the frightened buff on failure.
        if hit and not target_dead:
            try:
                save_result = await _apply_magic_item_on_hit_save_effect(
                    db, campaign_id, char, sheet, attack,
                    target_combatant,
                    campaign=campaign,
                    prompt_user=user,
                )
                if save_result is not None:
                    await hub.broadcast(campaign_id, {
                        "type": "feature_used",
                        "data": {
                            "character_id": char.id,
                            "character_name": char.name,
                            "feature_name": save_result["label"],
                            "feature_desc": (
                                f"{save_result['target_name']} rolls a "
                                f"DC {save_result['dc']} "
                                f"{save_result['ability']} save vs. "
                                f"{save_result['label']}."
                            ),
                            "source": f"item-{save_result['slug']}-save",
                            "target_combatant_id": save_result["target_combatant_id"],
                            "target_name": save_result["target_name"],
                            "dc": save_result["dc"],
                            "ability": save_result["ability"],
                        },
                    })
            except Exception:
                logging.exception(
                    "on_hit_save resolve failed for char_id=%s",
                    char.id,
                )

        # v2.99.90 — Repelling Blast invocation. On a successful
        # Eldritch Blast hit, push the target up to 10 ft away in
        # a straight line. RAW says "you can push" (optional); v1
        # makes it automatic (the optional-decision UI is filed
        # for follow-up). Skipped on dead targets (they're no
        # longer threats to push).
        if hit and not target_dead:
            try:
                push_result = await _apply_repelling_blast_push(
                    db, campaign_id, campaign,
                    char.id, sheet, attack, target_combatant,
                )
                if push_result is not None:
                    await hub.broadcast(campaign_id, {
                        "type": "feature_used",
                        "data": {
                            "character_id": char.id,
                            "character_name": char.name,
                            "feature_name": "💨 Repelling Blast",
                            "feature_desc": (
                                f"{char.name} pushes "
                                f"{push_result['target_name']} "
                                f"~{int(push_result['distance_ft'])} ft "
                                f"in a straight line."
                            ),
                            "source": "repelling-blast",
                            "from_x": push_result["from_x"],
                            "from_y": push_result["from_y"],
                            "to_x": push_result["to_x"],
                            "to_y": push_result["to_y"],
                            "distance_ft": push_result["distance_ft"],
                            "target_name": push_result["target_name"],
                        },
                    })
            except Exception:
                # Fire-and-forget — a failed push shouldn't unwind
                # the attack roll itself.
                logging.exception(
                    "Repelling Blast push failed for char_id=%s", char.id,
                )

    # v2.49.85 — multi-target loop. The PRIMARY target (target #0) was
    # just resolved above; collect its outcome here, then iterate the
    # remaining targets with FRESH attack + damage rolls per RAW (each
    # weapon attack is a separate to-hit + damage roll, not a single
    # roll spread across multiple enemies). Auto-uplifts (Hex /
    # Hunter's Mark / Colossus Slayer) intentionally apply only to the
    # primary target — those are target-bound mechanics; spreading a
    # Hexed-target's +1d6 across unrelated enemies would be RAW-wrong.
    # Filed: per-target uplift detection for multi-target attacks.
    auto_attack_targets: list[dict] = []
    if not is_save and target_combatant_ids_in:
        # Primary target entry.
        if target_combatant:
            auto_attack_targets.append({
                "combatant_id": target_combatant_id or "",
                "target_name": _lookup_combatant_name(campaign_id, target_combatant_id) if target_combatant_id else "",
                "attack_total": attack_total,
                "attack_breakdown": attack_breakdown,
                "is_crit": is_crit,
                "hit": hit,
                "target_ac": target_ac,
                "damage_total": damage_total,
                "damage_breakdown": damage_breakdown,
                "damage_applied": damage_applied,
                "damage_type": damage_type,
                "target_hp_before": target_hp_before,
                "target_hp_after": target_hp_after,
                "target_resistance_applied": target_resistance_applied,
                # v2.99.132 — vulnerability flag for the chat-card badge.
                "target_vulnerability_applied": target_vulnerability_applied,
                "target_dying": target_dying,
                "target_dead": target_dead,
            })
        # Additional targets — fresh rolls + damage application each.
        for extra_tid in target_combatant_ids_in[1:]:
            extra_combatant = _lookup_combatant(campaign_id, extra_tid)
            if not extra_combatant:
                continue
            # Fresh attack roll using the same to-hit expression as the
            # primary attack (same bonus, same roll_state, same Rage
            # advantage — those are properties of the attacker + weapon,
            # not the target).
            extra_atk_total: int | None = None
            extra_atk_breakdown = ""
            if attack_bonus_raw:
                _bonus = attack_bonus_raw if attack_bonus_raw.startswith(("+", "-"))\
                    or any(c.isalpha() for c in attack_bonus_raw)\
                    else "+" + attack_bonus_raw
                _atk_expr = "1d20" + (_bonus if _bonus.startswith(("+", "-")) else "+" + _bonus)
                _atk_expr, _ = _apply_roll_state(
                    _atk_expr, (char.sheet or {}).get("roll_state"),
                )
                if rage_advantage and "kh1" not in _atk_expr and "kl1" not in _atk_expr:
                    _atk_expr = _atk_expr.replace("1d20", "2d20kh1", 1)
                try:
                    _r = dice_mod.roll(_atk_expr)
                    extra_atk_total = _r.total
                    extra_atk_breakdown = _r.breakdown
                except dice_mod.DiceParseError:
                    extra_atk_total = None
            else:
                _atk_expr, _ = _apply_roll_state(
                    "1d20", (char.sheet or {}).get("roll_state"),
                )
                if rage_advantage and "kh1" not in _atk_expr and "kl1" not in _atk_expr:
                    _atk_expr = _atk_expr.replace("1d20", "2d20kh1", 1)
                try:
                    _r = dice_mod.roll(_atk_expr)
                    extra_atk_total = _r.total
                    extra_atk_breakdown = _r.breakdown
                except dice_mod.DiceParseError:
                    extra_atk_total = None
            # Crit detection from this attack's d20.
            extra_is_crit = False
            if extra_atk_breakdown:
                import re as _re_crit_extra
                _m = _re_crit_extra.search(
                    r"\d*d20[^d=+ ]*=(\d+)", extra_atk_breakdown, _re_crit_extra.IGNORECASE,
                )
                if _m and int(_m.group(1)) == 20:
                    extra_is_crit = True
            # Fresh damage roll (with crit-doubling if applicable).
            extra_dmg_total: int | None = None
            extra_dmg_breakdown = ""
            if damage_expr_raw:
                _dmg_expr = (
                    _double_dice_for_crit(damage_expr_raw) if extra_is_crit
                    else damage_expr_raw
                )
                try:
                    _dr = dice_mod.roll(_dmg_expr)
                    extra_dmg_total = _dr.total
                    extra_dmg_breakdown = _dr.breakdown
                except dice_mod.DiceParseError:
                    extra_dmg_total = None
            # Hit determination + auto-apply damage.
            extra_ac = _read_target_ac(db, campaign_id, extra_combatant)
            extra_hit = bool(extra_is_crit or (extra_atk_total is not None and extra_atk_total >= extra_ac))
            extra_applied = 0
            extra_hp_before = None
            extra_hp_after = None
            extra_resistance = False
            extra_dying = False
            extra_dead = False
            if (
                extra_hit
                and bool(campaign.auto_apply_damage)
                and (extra_dmg_total or 0) > 0
            ):
                _ar = await _apply_damage_to_combatant(
                    db, campaign_id, extra_combatant,
                    int(extra_dmg_total or 0), damage_type,
                    is_crit=extra_is_crit, is_attack=True,
                    attack_id=attack_id,
                    is_magical=_attack_is_magical(sheet, name),
                    attacker_char_id=char.id,
                )
                extra_applied = _ar["applied"]
                extra_hp_before = _ar["hp_before"]
                extra_hp_after = _ar["hp_after"]
                extra_resistance = _ar["resistance_applied"]
                extra_dying = _ar["is_dying"]
                extra_dead = _ar["is_dead"]
            auto_attack_targets.append({
                "combatant_id": extra_combatant.get("id") or extra_tid,
                "target_name": extra_combatant.get("name") or "",
                "attack_total": extra_atk_total,
                "attack_breakdown": extra_atk_breakdown,
                "is_crit": extra_is_crit,
                "hit": extra_hit,
                "target_ac": extra_ac,
                "damage_total": extra_dmg_total,
                "damage_breakdown": extra_dmg_breakdown,
                "damage_applied": extra_applied,
                "damage_type": damage_type,
                "target_hp_before": extra_hp_before,
                "target_hp_after": extra_hp_after,
                "target_resistance_applied": extra_resistance,
                "target_dying": extra_dying,
                "target_dead": extra_dead,
            })

    # Resolve caster display info
    membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id, CampaignMembership.user_id == user.id)
        .first()
    )
    player_color = (
        membership.color if membership and membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    caster_color = char.color or player_color

    payload = {
        "id": attack_id,
        "caster_user_id": user.id,
        "caster_user_name": user.display_name,
        "caster_user_color": caster_color,
        "caster_portrait_url": char.portrait_url,
        "caster_char_id": char.id,
        "caster_char_name": char.name,
        "attack_index": attack_index,
        "attack_name": name,
        "attack_bonus": attack_bonus_raw,
        "attack_total": attack_total,
        "attack_breakdown": attack_breakdown,
        "damage_expr": damage_expr_raw,
        "damage_type": damage_type,
        "damage_total": damage_total,
        "damage_breakdown": damage_breakdown,
        # v2.99.408 — Phase 3.3: weapon_hit_save rider results (Battle
        # Master maneuvers that fired their save on this hit).
        "feature_saves": feature_save_results,
        # v2.16.0: per-attack uplifts. ``bonus_damage_*`` is null when no
        # uplift was applied; populated when the caller passed a
        # ``bonus_damage`` expression. Chat card renders this on its own
        # line below the base damage line so the audience can attribute
        # the extra dice to Sneak Attack / Divine Smite / etc.
        "bonus_damage_label": bonus_damage_label or "",
        "bonus_damage_expr": bonus_damage_expr or "",
        "bonus_damage_total": bonus_damage_total,
        "bonus_damage_breakdown": bonus_damage_breakdown,
        "slot_spent_class": slot_spent_class,
        "slot_spent_level": slot_spent_level,
        # v2.20.0 Phase B: auto-applied uplifts from attacker's buffs +
        # class features (Rage / Hunter's Mark / Hex / Colossus Slayer).
        # Structured per-uplift list with damage_type so future chat-card
        # work can render labeled lines + resistance can apply per type.
        # Aggregate total is already folded into damage_total above.
        "auto_uplifts": auto_uplifts,
        "auto_uplift_total": auto_uplift_total,
        # v2.62.1 — F1 Sneak Attack ally-adjacency advisory. True when
        # the attacker is a Rogue Lv 1+ AND at least one other
        # combatant is within 5 ft of the target. Advisory only —
        # the server doesn't gate Sneak Attack uplift on this field;
        # the client UI can render an "eligible" hint. Returns False
        # for non-Rogue attackers (silent default) or when token
        # positions aren't available.
        "sneak_attack_ally_adjacent": (
            _sneak_attack_ally_adjacent(
                db, campaign_id, char.id, target_combatant_id,
            )
            if _rogue_level_from_sheet(sheet) >= 1 and target_combatant_id
            else False
        ),
        "target_combatant_id": target_combatant_id or "",
        # v2.23.0 Phase T.8: resolve the target's display name from the
        # hub battle state so the chat card can render "→ NAME" without
        # the client needing a second lookup. Empty string when no
        # target was set or the target isn't in init.
        "target_name": _lookup_combatant_name(campaign_id, target_combatant_id) if target_combatant_id else "",
        # v2.24.0 Phase T.2: hit determination + auto-damage results.
        # ``hit`` is None when no target was set or it's a save spell;
        # True/False otherwise. ``target_ac`` revealed only when hit is
        # determined (so blind-AC tables can hide it on miss via a
        # future setting). ``damage_applied`` is 0 when auto-apply is
        # off OR the attack missed; >0 when HP changed. ``is_crit``
        # surfaces the crit flag for the chat card's crit badge.
        "hit": hit,
        "is_crit": is_crit,
        "target_ac": target_ac,
        "damage_applied": damage_applied,
        "target_hp_before": target_hp_before,
        "target_hp_after": target_hp_after,
        "target_resistance_applied": target_resistance_applied,
        # v2.99.132 — vulnerability flag for the chat-card badge.
        "target_vulnerability_applied": target_vulnerability_applied,
        "target_dying": target_dying,
        "target_dead": target_dead,
        # Echo whether the campaign auto-applies damage so the chat
        # card can render the Hit/Miss badge differently when the
        # GM is still in "manual apply" mode (badge becomes a hint,
        # not a confirmation of HP change).
        "auto_applied": bool(campaign.auto_apply_damage),
        "range": range_str,
        "save_dc": save_dc if is_save else 0,
        "save_ability": save_ability if is_save else "",
        "desc": desc,
        "is_save": is_save,
        "roll_state_applied": attack_roll_state_applied or None,
        "over_budget": was_used,
        "over_budget_slot": "action" if was_used else "",
        # v2.49.85 — per-target outcomes for multi-target attacks.
        # Empty list for single-target attacks (the legacy fields above
        # carry the only target's outcome). For 2+ targets, the first
        # entry mirrors the legacy fields and additional entries
        # describe each subsequent target's fresh attack + damage roll.
        "auto_attack_targets": auto_attack_targets,
        # v2.99.75 — OA hint propagated from the body. Client renders
        # the weapon-attack card chrome with "⚔ OA — {weapon}" when set.
        "is_oa": is_oa,
    }
    await hub.broadcast(campaign_id, {"type": "weapon_attack", "data": payload})
    # v2.99.21 — Halfling Lucky attack-roll companion broadcast. Fires
    # when the primary attack's d20 was 1 and the reroll consumed it.
    if _hl_old_d20 == 1 and _hl_new_d20 is not None:
        await _broadcast_halfling_lucky_attack(
            campaign_id, char, _hl_old_d20, _hl_new_d20,
        )
    # v2.5.5: full-sheet → init chip sync. Weapon attacks always burn the
    # action slot; bonus-action attacks (e.g. off-hand light weapon) come
    # through a separate row whose action.economy override is followed
    # in Phase 3, not here.
    # v2.49.117 Phase B v2 — Flurry of Blows chip refund. If the
    # attacker has ``flurry-of-blows-active`` active AND this attack
    # is an unarmed strike (name prefix "unarmed"), the action chip
    # is NOT marked — Flurry's two follow-up strikes are RAW-free in
    # action-economy terms (the bonus action already paid via the
    # Ki spend at v2.49.114). Decrement ``effects.unarmed_strikes_available``;
    # when it reaches 0, drop the buff. Non-unarmed attacks
    # (Quarterstaff, weapons) while Flurry is active still mark the
    # action chip — RAW says Flurry grants UNARMED strikes only.
    _attack_name_lc = (name or "").strip().lower()
    _is_unarmed_strike = _attack_name_lc.startswith("unarmed")
    _flurry_buff = None
    _strikes_available = 0
    if _is_unarmed_strike:
        for b in _get_buffs(campaign_id, char.id):
            if (b or {}).get("key") == "flurry-of-blows-active":
                effects = (b or {}).get("effects") or {}
                if effects.get("is_flurry") is True:
                    _flurry_buff = dict(b)
                    _strikes_available = int(effects.get("unarmed_strikes_available") or 0)
                break
    if _flurry_buff and _strikes_available > 0:
        _remaining = _strikes_available - 1
        if _remaining <= 0:
            await _remove_buff(campaign_id, char.id, "flurry-of-blows-active")
        else:
            _new_buff = dict(_flurry_buff)
            _new_effects = dict(_flurry_buff.get("effects") or {})
            _new_effects["unarmed_strikes_available"] = _remaining
            _new_buff["effects"] = _new_effects
            await _install_buff(campaign_id, char.id, _new_buff)
        _mirror_buffs_to_sheet(db, char.id, _get_buffs(campaign_id, char.id))
    else:
        await _mark_battle_economy(campaign_id, char.id, "action")
    # v2.66.5 — Sentinel feat advisory. Walk for any Sentinel watcher
    # within 5 ft of the attacker who isn't the target. Emits one
    # `feature_used(source="sentinel-attack-trigger")` per qualifier
    # and returns the list for the response echo below.
    try:
        _sentinel_triggers_for_response = (
            await _broadcast_sentinel_attack_triggers(
                db, campaign_id, char.id, target_combatant_id, name,
            )
        )
    except Exception:
        _sentinel_triggers_for_response = []
    # v2.69.0 Phase 3a — Shield spell prompt. After a PC target is
    # hit, emit a reaction_prompt(attack_targeted) so the target's
    # owning user + GM see a "Cast Shield (+5 AC)" option in the
    # popup + roll log. The catalog gate (Shield in spells, slot
    # available, reaction available) lives in
    # `_eligible_reactions[attack_targeted]`.
    #
    # v2.73.0 Phase 6 — extend to NPC targets too. Bandit Captain
    # (Parry), Knight (Parry), Gladiator (Parry), Erinyes (Parry),
    # Marilith (Parry), Noble (Parry), and any monster stat-block
    # with a `category: "reaction"` action entry can now surface in
    # the popup when hit by a PC swing. The eligibility branch in
    # `_eligible_reactions[attack_targeted]` reads `combatant.
    # source_token_id` → Token → TokenTemplate → projected sheet
    # actions.
    try:
        if hit and target_combatant_id:
            target_cb = _lookup_combatant(campaign_id, target_combatant_id)
            if target_cb is not None:
                _target_econ = (target_cb.get("economy") or {})
                if not bool(_target_econ.get("reaction")):
                    await _emit_reaction_prompt(
                        db, campaign, target_cb,
                        trigger_event="attack_targeted",
                        summary=(
                            f"{char.name} hit {target_cb.get('name') or 'you'} "
                            f"with {name} (d20 total {attack_total} vs AC "
                            f"{target_ac or '?'})."
                        ),
                        context={
                            "attack_id": attack_id,
                            "attack_total": attack_total,
                            "target_ac": target_ac,
                            "attacker_char_id": char.id,
                            "attacker_name": char.name,
                            "attack_name": name,
                            # v2.80.0 — plumb the applied damage so
                            # the cast-uncanny-dodge dispatch can
                            # heal back ceil(applied/2) HP.
                            "damage_applied": damage_applied,
                        },
                    )
    except Exception:
        pass
    # v2.119.0 Phase 7 — Riposte. When this PC attack MISSES a target
    # who is a Battle Master with a free reaction + a Superiority Die,
    # emit `attack_missed` so they can counter-attack. The attacker
    # (this PC) is the riposte target — resolve its combatant id from
    # the live battle so the dispatch can swing back at it.
    try:
        if hit is False and target_combatant_id:
            target_cb = _lookup_combatant(campaign_id, target_combatant_id)
            if target_cb is not None and target_cb.get("char_id"):
                _t_econ = (target_cb.get("economy") or {})
                if not bool(_t_econ.get("reaction")):
                    _atkr_cid = ""
                    _state = hub.get_battle(campaign_id) or {}
                    for _c in (_state.get("combatants") or []):
                        if _c.get("char_id") == char.id:
                            _atkr_cid = _c.get("id") or ""
                            break
                    await _emit_reaction_prompt(
                        db, campaign, target_cb,
                        trigger_event="attack_missed",
                        summary=(
                            f"{char.name} MISSED {target_cb.get('name') or 'you'} "
                            f"with {name} (d20 total {attack_total} vs AC "
                            f"{target_ac or '?'})."
                        ),
                        context={
                            "attack_id": attack_id,
                            "attack_total": attack_total,
                            "target_ac": target_ac,
                            "attacker_char_id": char.id,
                            "attacker_name": char.name,
                            "attacker_combatant_id": _atkr_cid,
                            "attack_name": name,
                        },
                    )
    except Exception:
        pass
    # Return the attack + damage totals so the sheet's .atk-strike handler can
    # fire the shared roll-toast immediately. The broadcast still drives the
    # tabletop's roll-card path; this echo gives the rolling player a popup
    # without needing a WebSocket connection on the sheet page.
    return {
        "ok": True,
        "id": attack_id,
        "attack_total": attack_total,
        "attack_breakdown": attack_breakdown,
        "damage_total": damage_total,
        "damage_breakdown": damage_breakdown,
        # v2.99.400 — echo the resolved damage type so the rolling
        # player's local toast can render it without WS lag, and so a
        # Phase-2.4 damage-type conversion (Planar Warrior re-types to
        # force on a hit) is observable on the HTTP response.
        "damage_type": damage_type,
        "bonus_damage_label": bonus_damage_label or "",
        "bonus_damage_total": bonus_damage_total,
        "bonus_damage_breakdown": bonus_damage_breakdown,
        "slot_spent_class": slot_spent_class,
        "slot_spent_level": slot_spent_level,
        "auto_uplifts": auto_uplifts,
        "auto_uplift_total": auto_uplift_total,
        # v2.99.408 — Phase 3.3: weapon_hit_save rider results.
        "feature_saves": feature_save_results,
        # v2.62.1 — F1 Sneak Attack ally-adjacency advisory (mirror of
        # the broadcast-side return above). Gated on Rogue Lv 1+; the
        # client UI can render an "eligible" hint based on this flag.
        "sneak_attack_ally_adjacent": (
            _sneak_attack_ally_adjacent(
                db, campaign_id, char.id, target_combatant_id,
            )
            if _rogue_level_from_sheet(sheet) >= 1 and target_combatant_id
            else False
        ),
        "target_combatant_id": target_combatant_id or "",
        # v2.23.0 Phase T.8: echo resolved target name so the rolling
        # player's local toast can include the target without WS lag.
        "target_name": _lookup_combatant_name(campaign_id, target_combatant_id) if target_combatant_id else "",
        # v2.24.0 Phase T.2: hit + auto-damage results echoed for the
        # rolling player's local toast.
        "hit": hit,
        "is_crit": is_crit,
        "target_ac": target_ac,
        "damage_applied": damage_applied,
        "target_hp_after": target_hp_after,
        # v2.63.0 — echo `target_resistance_applied` on this return
        # path too (the broadcast-side return at L ~19303 already
        # included it). Chat-card render reads this to label the
        # damage as "resisted" or "full".
        "target_resistance_applied": target_resistance_applied,
        # v2.99.132 — vulnerability flag for the chat-card badge.
        "target_vulnerability_applied": target_vulnerability_applied,
        "auto_applied": bool(campaign.auto_apply_damage),
        "attack_name": name,
        "damage_type": damage_type,
        "is_save": is_save,
        "save_ability": save_ability if is_save else "",
        "save_dc": save_dc if is_save else 0,
        "roll_state_applied": attack_roll_state_applied or None,
        "over_budget": was_used,
        # v2.49.85 — echo the per-target outcomes so the rolling player's
        # local toast can render the multi-target summary without WS lag.
        "auto_attack_targets": auto_attack_targets,
        # v2.66.5 — Sentinel feat advisory. RAW effect 3: a Sentinel
        # within 5 ft of the attacker can use their reaction to make a
        # melee attack against the attacker (when the attack target
        # isn't themselves + doesn't have Sentinel). Broadcast +
        # response list populated by ``_broadcast_sentinel_attack_triggers``
        # called above.
        "sentinel_triggers": _sentinel_triggers_for_response,
    }


async def _broadcast_sentinel_attack_triggers_npc(
    db: Session, campaign_id: int,
    attacker_combatant_id: str,
    target_combatant_id: str | None,
    attack_name: str,
) -> list[dict]:
    """v2.66.6 — NPC variant of the v2.66.5 PC helper. Same logic;
    identifies the attacker by combatant id (NPCs have no char_id)
    and uses the combatant's `name` as the attacker name in the
    broadcast desc.
    """
    triggers = _check_sentinel_attack_triggers(
        db, campaign_id, attacker_combatant_id, None, target_combatant_id,
    )
    if not triggers:
        return []
    attacker_combatant = _lookup_combatant(campaign_id, attacker_combatant_id)
    attacker_name = ""
    if attacker_combatant:
        attacker_name = str(attacker_combatant.get("name") or "")
    target_name = (
        _lookup_combatant_name(campaign_id, target_combatant_id)
        if target_combatant_id else ""
    )
    for trig in triggers:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": trig.get("watcher_char_id"),
                "character_name": trig.get("watcher_name"),
                "user_color": trig.get("watcher_color"),
                "feature_name": "⚔ Sentinel reaction available",
                "feature_desc": (
                    f"{attacker_name or 'Attacker'} attacked "
                    f"{target_name or 'another target'} within 5 ft of you. "
                    f"Sentinel lets you use your reaction to make a melee "
                    f"attack against them."
                ),
                "source": "sentinel-attack-trigger",
                "watcher_combatant_id": trig.get("watcher_combatant_id"),
                "watcher_token_id": trig.get("watcher_token_id"),
                "attacker_combatant_id": attacker_combatant_id,
                "attacker_name": attacker_name,
                "attack_name": attack_name,
                "target_combatant_id": target_combatant_id,
                "target_name": target_name,
            },
        })
        # v2.68.1 — NPC variant: emit reaction_prompt too.
        try:
            state = hub.get_battle(campaign_id) or {}
            watcher_cb = None
            for c in (state.get("combatants") or []):
                if c.get("id") == trig.get("watcher_combatant_id"):
                    watcher_cb = c
                    break
            if watcher_cb is not None:
                campaign_row = db.query(Campaign).filter(
                    Campaign.id == campaign_id,
                ).first()
                if campaign_row:
                    await _emit_reaction_prompt(
                        db, campaign_row, watcher_cb,
                        trigger_event="ally_attacked_near",
                        summary=(
                            f"{attacker_name or 'Attacker'} attacked "
                            f"{target_name or 'someone'} within 5 ft of "
                            f"{trig.get('watcher_name') or 'you'}."
                        ),
                        context={
                            "attacker_combatant_id": attacker_combatant_id,
                            "attacker_name": attacker_name,
                            "attack_name": attack_name,
                            "target_combatant_id": target_combatant_id,
                            "target_name": target_name,
                        },
                    )
        except Exception:
            pass
    return [
        {
            "watcher_combatant_id": t.get("watcher_combatant_id"),
            "watcher_name": t.get("watcher_name"),
            "watcher_char_id": t.get("watcher_char_id"),
            "watcher_token_id": t.get("watcher_token_id"),
            "dist_ft": t.get("dist_ft"),
        }
        for t in triggers
    ]


async def _broadcast_sentinel_attack_triggers(
    db: Session, campaign_id: int, attacker_char_id: int,
    target_combatant_id: str | None, attack_name: str,
) -> list[dict]:
    """v2.66.5 — broadcast Sentinel advisories + return the trigger
    list for the response. Fires one `feature_used(source=
    "sentinel-attack-trigger")` per qualifying watcher. The returned
    list (without WS broadcast metadata) gets surfaced on the /attack
    response so the rolling player's local toast can render the
    advisory without WS lag.
    """
    triggers = _check_sentinel_attack_triggers(
        db, campaign_id, None, attacker_char_id, target_combatant_id,
    )
    if not triggers:
        return []
    attacker_name = ""
    try:
        attacker_char = db.query(Character).filter(
            Character.id == int(attacker_char_id),
        ).first()
        if attacker_char:
            attacker_name = attacker_char.name or ""
    except Exception:
        pass
    target_name = (
        _lookup_combatant_name(campaign_id, target_combatant_id)
        if target_combatant_id else ""
    )
    for trig in triggers:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "character_id": trig.get("watcher_char_id"),
                "character_name": trig.get("watcher_name"),
                "user_color": trig.get("watcher_color"),
                "feature_name": "⚔ Sentinel reaction available",
                "feature_desc": (
                    f"{attacker_name or 'Attacker'} attacked "
                    f"{target_name or 'another target'} within 5 ft of you. "
                    f"Sentinel lets you use your reaction to make a melee "
                    f"attack against them."
                ),
                "source": "sentinel-attack-trigger",
                "watcher_combatant_id": trig.get("watcher_combatant_id"),
                "watcher_token_id": trig.get("watcher_token_id"),
                "attacker_char_id": attacker_char_id,
                "attacker_name": attacker_name,
                "attack_name": attack_name,
                "target_combatant_id": target_combatant_id,
                "target_name": target_name,
            },
        })
        # v2.68.1 — also emit a reaction_prompt so the watcher's
        # owning user + the GM get a popup with a "Take the Sentinel
        # melee attack" button. Legacy feature_used above still fires
        # for the chat-card path; this adds the prompt path.
        try:
            state = hub.get_battle(campaign_id) or {}
            watcher_cb = None
            for c in (state.get("combatants") or []):
                if c.get("id") == trig.get("watcher_combatant_id"):
                    watcher_cb = c
                    break
            if watcher_cb is not None:
                campaign_row = db.query(Campaign).filter(
                    Campaign.id == campaign_id,
                ).first()
                if campaign_row:
                    await _emit_reaction_prompt(
                        db, campaign_row, watcher_cb,
                        trigger_event="ally_attacked_near",
                        summary=(
                            f"{attacker_name or 'Attacker'} attacked "
                            f"{target_name or 'someone'} within 5 ft of "
                            f"{trig.get('watcher_name') or 'you'}."
                        ),
                        context={
                            "attacker_char_id": attacker_char_id,
                            "attacker_name": attacker_name,
                            "attack_name": attack_name,
                            "target_combatant_id": target_combatant_id,
                            "target_name": target_name,
                        },
                    )
        except Exception:
            pass
    return [
        {
            "watcher_combatant_id": t.get("watcher_combatant_id"),
            "watcher_name": t.get("watcher_name"),
            "watcher_char_id": t.get("watcher_char_id"),
            "watcher_token_id": t.get("watcher_token_id"),
            "dist_ft": t.get("dist_ft"),
        }
        for t in triggers
    ]


# ----------- API: NPC attack (v2.49.164) -----------

@router.post("/api/campaign/{campaign_id}/npc_attack")
async def use_npc_attack(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Resolve a structured attack from an NPC (monster) combatant.

    Parallel to ``use_attack`` but for NPC attackers — used by the GM
    init-tracker ``.monster-strike-btn``. Rolls the attack d20 +
    damage, determines hit vs. ``target_combatant_id`` AC, and
    auto-applies damage on hit (when ``campaign.auto_apply_damage`` is
    on) via the shared ``_apply_damage_to_combatant`` helper.
    Broadcasts the existing ``weapon_attack`` message so all clients
    render the same chat-card chrome as PC attacks (caster fields are
    populated from the NPC combatant + GM user).

    Body:
        ``combatant_id``      — attacker NPC combatant
        ``action_id``         — informational; for log + UI attribution
        ``action_name``       — display name ("Scimitar")
        ``attack_bonus``      — "+3" / "5" / "" — empty rolls flat d20
        ``damage``            — dice expression ("1d6+1"); empty skips
                                damage block
        ``damage_type``       — "slashing"
        ``range``             — "5 ft" / "80/320 ft"; informational
        ``target_combatant_id`` — required for hit determination +
                                  auto-apply. When absent the endpoint
                                  still rolls the attack + damage and
                                  broadcasts, leaving the GM to apply
                                  damage manually.

    Auth: GM-only — NPCs aren't owned by players in this codebase, so
    the action authority is the GM.

    No action-economy gate yet (NPCs don't track economy in the demo
    sheet). Range enforcement skipped for the same reason — would
    require a `Character` row to compute caster position; NPC range
    enforcement is filed for a follow-up.
    """
    body = await request.json()
    combatant_id = str(body.get("combatant_id") or "").strip()
    if not combatant_id:
        raise HTTPException(400, "combatant_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    if not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only — NPC attacks are GM-authorised")

    attacker = _lookup_combatant(campaign_id, combatant_id)
    if not attacker:
        raise HTTPException(404, "Attacker combatant not found")
    attacker_name = str(attacker.get("name") or "NPC")

    action_id = str(body.get("action_id") or "").strip()
    action_name = str(body.get("action_name") or "Attack").strip()
    attack_bonus_raw = str(body.get("attack_bonus") or "").strip()
    damage_expr_raw = str(body.get("damage") or "").strip()
    damage_type = str(body.get("damage_type") or "").strip()
    range_str = str(body.get("range") or "").strip()
    # v2.99.75 — OA chain hint (mirrors /attack).
    is_oa = bool(body.get("is_opportunity_attack"))

    target_combatant_id = (
        str(body.get("target_combatant_id") or "").strip() or None
    )
    target_combatant = (
        _lookup_combatant(campaign_id, target_combatant_id)
        if target_combatant_id else None
    )
    if target_combatant_id and not target_combatant:
        raise HTTPException(404, "Target combatant not found")

    # v2.49.166: range enforcement. Mirrors PC /attack's _check_cast_range
    # gate but NPC-specific — looks up the attacker's token via
    # combatant.source_token_id (PCs use character_id; NPCs don't have
    # one). No GM bypass for NPC range — when the GM acts as a bandit
    # they're playing the bandit, not bending its rules. ``override_range``
    # body flag is the explicit escape hatch when the GM does want to
    # bypass (click-again-to-override pattern on the client).
    override_range = bool(body.get("override_range"))
    if target_combatant_id and not override_range:
        _range_err = _check_npc_attack_range(
            db, campaign, attacker, range_str, action_name,
            target_combatant_id,
        )
        if _range_err:
            return JSONResponse(status_code=409, content=_range_err)

    # Dodging disadvantage on the target — same buff lookup PCs honor.
    target_dodging = _target_has_dodging(campaign_id, target_combatant_id)
    # v2.49.238 Phase B: target's Reckless Attack buff grants the
    # attacker advantage on the d20. Combines with rage_advantage as
    # an OR (both fire? still one advantage source). Combines with
    # target_dodging as a cancel (advantage + disadvantage = none).
    target_grants_advantage = _target_grants_advantage_to_attackers(
        campaign_id, target_combatant_id,
    )
    # v2.154.0 — Phase 2c: NPC attacker condition adv/dis. Mirrors the
    # Phase 2a PC `/attack` source-set with three new hub-read helpers
    # gating on the NPC's combatant.buffs (which doesn't have a sheet
    # mirror). Plus the symmetric `_target_has_condition_advantage`
    # that was missing from the NPC path despite already existing on
    # the PC side.
    _npc_attacker_dis_condition = _npc_attacker_has_condition_disadvantage(
        campaign_id, combatant_id,
    )
    _npc_attacker_invisible_adv = _npc_attacker_has_invisible_advantage(
        campaign_id, combatant_id,
    )
    _npc_target_adv_condition = _target_has_condition_advantage(
        campaign_id, target_combatant_id,
    )
    # v2.252.0 — Phase 4a: target wears Cloak of Displacement → the NPC
    # attacker rolls at disadvantage. Symmetric with the PC /attack path.
    target_cloak_dis = _target_wearer_imposes_attack_disadvantage(
        db, campaign_id, target_combatant_id,
    )

    # Build the d20 attack expression. Accept "+5", "5", or "" (flat).
    attack_total = None
    attack_breakdown = ""
    attack_roll_state_applied = ""
    if attack_bonus_raw:
        bonus_expr = (
            attack_bonus_raw
            if attack_bonus_raw.startswith(("+", "-"))
            else "+" + attack_bonus_raw
        )
        atk_expr = "1d20" + bonus_expr
    else:
        atk_expr = "1d20"
    # v2.154.0 — Phase 2c: full advantage/disadvantage composition for
    # NPC attacks. Source set is now symmetric with PC /attack:
    #   adv = target_grants_advantage (reckless) OR npc invisible OR
    #         target condition adv (blinded / paralyzed / etc.)
    #   dis = target_dodging OR npc attacker condition dis
    # Cancel per RAW PHB p.173. Replaces the v2.49.238 reckless-only
    # branch (which is still expressed below as part of the adv label
    # ordering).
    has_adv = (
        target_grants_advantage
        or _npc_attacker_invisible_adv
        or bool(_npc_target_adv_condition)
    )
    adv_label = (
        "reckless" if target_grants_advantage else
        "invisible" if _npc_attacker_invisible_adv else
        f"target_{_npc_target_adv_condition}" if _npc_target_adv_condition else ""
    )
    has_dis = (
        target_dodging
        or bool(_npc_attacker_dis_condition)
        or bool(target_cloak_dis)
    )
    dis_label = (
        "dodging" if target_dodging else
        f"attacker_{_npc_attacker_dis_condition}"
        if _npc_attacker_dis_condition else
        "cloak_of_displacement" if target_cloak_dis else ""
    )
    if has_adv and has_dis:
        attack_roll_state_applied = f"canceled_{adv_label}_vs_{dis_label}"
    elif has_adv:
        atk_expr = atk_expr.replace("1d20", "2d20kh1", 1)
        attack_roll_state_applied = f"advantage_{adv_label}"
    elif has_dis:
        atk_expr = atk_expr.replace("1d20", "2d20kl1", 1)
        attack_roll_state_applied = f"disadvantage_{dis_label}"
    try:
        r = dice_mod.roll(atk_expr)
        attack_total = r.total
        attack_breakdown = r.breakdown
    except dice_mod.DiceParseError:
        attack_total = None
        attack_breakdown = ""

    # Crit detection from the kept d20 value (same regex pattern as
    # use_attack at the v2.24.0 Phase T.2 block).
    is_crit = False
    if attack_breakdown:
        import re as _re_crit
        _crit_m = _re_crit.search(
            r"\d*d20[^d=+ ]*=(\d+)", attack_breakdown, _re_crit.IGNORECASE,
        )
        if _crit_m and int(_crit_m.group(1)) == 20:
            is_crit = True

    # Roll damage. Crit doubles the dice (not the flat modifier) per
    # RAW PHB p. 196. ``_double_dice_for_crit`` is the shared helper.
    damage_total = None
    damage_breakdown = ""
    damage_expr_effective = damage_expr_raw
    if damage_expr_raw and is_crit:
        damage_expr_effective = _double_dice_for_crit(damage_expr_raw)
    if damage_expr_effective:
        try:
            r = dice_mod.roll(damage_expr_effective)
            damage_total = r.total
            damage_breakdown = r.breakdown
        except dice_mod.DiceParseError:
            damage_total = None
            damage_breakdown = ""

    # Hit determination + auto-apply (same gating as use_attack).
    attack_id = uuid.uuid4().hex[:12]
    hit = None
    target_ac = None
    damage_applied = 0
    target_hp_before = None
    target_hp_after = None
    target_resistance_applied = False
    # v2.99.132 — vulnerability flag (mirror of v2.99.127 / the other
    # /attack code path above).
    target_vulnerability_applied = False
    target_dying = False
    target_dead = False
    if target_combatant and attack_total is not None:
        target_ac = _read_target_ac(db, campaign_id, target_combatant)
        hit = is_crit or (attack_total >= target_ac)
        if (
            hit
            and bool(campaign.auto_apply_damage)
            and (damage_total or 0) > 0
        ):
            apply_result = await _apply_damage_to_combatant(
                db, campaign_id, target_combatant,
                int(damage_total or 0), damage_type,
                is_crit=is_crit, is_attack=True, attack_id=attack_id,
            )
            damage_applied = apply_result["applied"]
            target_hp_before = apply_result["hp_before"]
            target_hp_after = apply_result["hp_after"]
            target_resistance_applied = apply_result["resistance_applied"]
            target_vulnerability_applied = apply_result.get(
                "vulnerability_applied", False,
            )
            target_dying = apply_result["is_dying"]
            target_dead = apply_result["is_dead"]

    # NPC casters reuse the GM's user-row identity for the chat-card
    # avatar/color (no per-NPC player). ``caster_char_name`` carries
    # the monster name so the card header reads "Bandit · ⚔ Attack".
    payload = {
        "id": attack_id,
        "caster_user_id": user.id,
        "caster_user_name": user.display_name,
        "caster_user_color": campaign.gm_color,
        "caster_portrait_url": None,
        "caster_char_id": None,
        "caster_char_name": attacker_name,
        "caster_combatant_id": combatant_id,
        "attack_index": -1,
        "attack_name": action_name,
        "attack_bonus": attack_bonus_raw,
        "attack_total": attack_total,
        "attack_breakdown": attack_breakdown,
        "damage_expr": damage_expr_raw,
        "damage_type": damage_type,
        "damage_total": damage_total,
        "damage_breakdown": damage_breakdown,
        "bonus_damage_label": "",
        "bonus_damage_expr": "",
        "bonus_damage_total": None,
        "bonus_damage_breakdown": "",
        "slot_spent_class": "",
        "slot_spent_level": 0,
        "auto_uplifts": [],
        "auto_uplift_total": 0,
        "target_combatant_id": target_combatant_id or "",
        "target_name": (
            _lookup_combatant_name(campaign_id, target_combatant_id)
            if target_combatant_id else ""
        ),
        "hit": hit,
        "is_crit": is_crit,
        "target_ac": target_ac,
        "damage_applied": damage_applied,
        "target_hp_before": target_hp_before,
        "target_hp_after": target_hp_after,
        "target_resistance_applied": target_resistance_applied,
        # v2.99.132 — vulnerability flag for the chat-card badge.
        "target_vulnerability_applied": target_vulnerability_applied,
        "target_dying": target_dying,
        "target_dead": target_dead,
        "auto_applied": bool(campaign.auto_apply_damage),
        "range": range_str,
        "save_dc": 0,
        "save_ability": "",
        "desc": "",
        "is_save": False,
        "roll_state_applied": attack_roll_state_applied or None,
        "over_budget": False,
        "over_budget_slot": "",
        "auto_attack_targets": [],
        "is_npc_attack": True,
        "npc_action_id": action_id,
        # v2.99.75 — OA hint propagated from the body.
        "is_oa": is_oa,
    }
    await hub.broadcast(campaign_id, {"type": "weapon_attack", "data": payload})
    # v2.66.6 — Sentinel feat advisory for NPC attacks. Mirrors the
    # v2.66.5 hook on /attack. Fires when a Sentinel watcher (PC) is
    # within 5 ft of the NPC attacker and isn't the target.
    try:
        _sentinel_triggers_for_response = (
            await _broadcast_sentinel_attack_triggers_npc(
                db, campaign_id, combatant_id, target_combatant_id, action_name,
            )
        )
    except Exception:
        _sentinel_triggers_for_response = []
    # v2.119.0 Phase 7 — Riposte. When this NPC attack MISSES a PC who
    # is a Battle Master with a free reaction + a Superiority Die, emit
    # `attack_missed` so the PC can counter-attack the NPC. The NPC
    # attacker (combatant_id) is the riposte target.
    try:
        if hit is False and target_combatant and target_combatant.get("char_id"):
            _t_econ = (target_combatant.get("economy") or {})
            if not bool(_t_econ.get("reaction")):
                await _emit_reaction_prompt(
                    db, campaign, target_combatant,
                    trigger_event="attack_missed",
                    summary=(
                        f"{attacker_name} MISSED "
                        f"{target_combatant.get('name') or 'you'} with "
                        f"{action_name} (d20 total {attack_total} vs AC "
                        f"{target_ac or '?'})."
                    ),
                    context={
                        "attack_id": attack_id,
                        "attack_total": attack_total,
                        "target_ac": target_ac,
                        "attacker_combatant_id": combatant_id,
                        "attacker_name": attacker_name,
                        "attack_name": action_name,
                    },
                )
    except Exception:
        pass
    return {
        "ok": True,
        "id": attack_id,
        "attack_name": action_name,
        "attack_total": attack_total,
        "attack_breakdown": attack_breakdown,
        "damage_total": damage_total,
        "damage_breakdown": damage_breakdown,
        "damage_type": damage_type,
        "target_combatant_id": target_combatant_id or "",
        "target_name": (
            _lookup_combatant_name(campaign_id, target_combatant_id)
            if target_combatant_id else ""
        ),
        "hit": hit,
        "is_crit": is_crit,
        "target_ac": target_ac,
        "damage_applied": damage_applied,
        "target_hp_after": target_hp_after,
        "auto_applied": bool(campaign.auto_apply_damage),
        "is_npc_attack": True,
        # v2.154.0 — Phase 2c: echo the adv/dis label so the client +
        # tests can read which condition (or combination) drove the
        # roll. Matches the PC /attack response convention.
        "roll_state_applied": attack_roll_state_applied or None,
        "sentinel_triggers": _sentinel_triggers_for_response,
    }


@router.post("/api/campaign/{campaign_id}/npc_cast_spell")
async def use_npc_cast_spell(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.49.215: NPC-caster spell endpoint that emits a ``spell_cast``
    WS event so the chat card renders with PC-style spell-card chrome
    (header with spell name + level + range, target row, save chip,
    damage pill) instead of multiple plain dice cards. Mirrors the
    relevant subset of ``/cast_spell`` behavior — rolls attack + damage
    server-side; on attack hit + ``campaign.auto_apply_damage`` applies
    damage via ``_apply_damage_to_combatant``; for save spells emits
    the DC + ability for the GM to resolve manually (server-side save
    auto-resolution is filed for a follow-up; matches the PC AoE save
    flow's manual-prompt fallback).

    Body:
        ``combatant_id``       — caster NPC combatant
        ``spell_name``         — display name ("Sacred Flame")
        ``spell_level``        — 0 for cantrips
        ``spell_range``        — "60 feet" / "Touch"
        ``damage``             — dice expression ("1d8"); empty skips
        ``damage_type``        — "radiant"
        ``save_ability``       — "DEX" (empty for attack-roll spells)
        ``save_dc``            — int (0 for attack-roll spells)
        ``attack_roll``        — True for attack-roll spells
        ``attack_bonus``       — "+4" / "" for attack-roll spells
        ``target_combatant_id``— required for hit determination +
                                 auto-apply; absent for self-cast or
                                 mass-target spells

    Auth: GM-only — NPCs aren't owned by players. Mirrors /npc_attack's
    GM-only stance.

    Persistence: the rolled dice are NOT persisted as DiceRoll records
    (the spell_cast WS event + the client-side localStorage replay
    via _persistRollEntry carry the chat-card history). PC /cast_spell
    has the same convention.
    """
    body = await request.json()
    combatant_id = str(body.get("combatant_id") or "").strip()
    if not combatant_id:
        raise HTTPException(400, "combatant_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    if not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only — NPC casts are GM-authorised")

    caster = _lookup_combatant(campaign_id, combatant_id)
    if not caster:
        raise HTTPException(404, "Caster combatant not found")
    caster_name = str(caster.get("name") or "NPC")

    spell_name = str(body.get("spell_name") or "Spell").strip()[:100]
    spell_level = int(body.get("spell_level") or 0)
    spell_range = str(body.get("spell_range") or "").strip()[:50]
    # v2.97.75 — optional spell_slug body param for save-or-suck
    # condition install on PC targets. When set + the spell has a
    # ``_SPELL_CONDITION_MAP`` entry + the target is a PC, the v2.97.75
    # ``_save_request_context`` stash makes /respond's existing
    # condition install path fire on a failed save. Mirrors the
    # caster_char_id=0 NPC-caster convention.
    spell_slug = str(body.get("spell_slug") or "").strip().lower()
    damage_expr_raw = str(body.get("damage") or "").strip()
    damage_type = str(body.get("damage_type") or "").strip()
    save_ability = str(body.get("save_ability") or "").strip().upper()
    save_dc = int(body.get("save_dc") or 0)
    attack_roll_flag = bool(body.get("attack_roll"))
    attack_bonus_raw = str(body.get("attack_bonus") or "").strip()

    target_combatant_id = str(body.get("target_combatant_id") or "").strip() or None
    target_combatant = (
        _lookup_combatant(campaign_id, target_combatant_id)
        if target_combatant_id else None
    )
    if target_combatant_id and not target_combatant:
        raise HTTPException(404, "Target combatant not found")

    # v2.49.217: AoE multi-target list from the client's _openAoePicker.
    # When non-empty, the server loops the save+damage resolution per
    # target (matches PC /cast_spell's Phase T.5 AoE loop at line ~8504).
    # The single-target path above still fires for the FIRST id when
    # both are passed — keeps the chat card's legacy single-target
    # fields populated for non-AoE viewers; subsequent ids go through
    # the loop and land in auto_save_targets.
    aoe_target_ids_raw = body.get("aoe_target_combatant_ids") or []
    aoe_target_ids = [
        str(x).strip() for x in aoe_target_ids_raw if isinstance(x, (str, int))
    ]
    aoe_target_ids = [x for x in aoe_target_ids if x]
    area_shape = str(body.get("area_shape") or "").strip()
    area_size_ft = int(body.get("area_size_ft") or 0)
    # If this is an AoE cast with no explicit single target, use the
    # first AoE id as the "primary" target so the single-target path
    # has something to act on (matches PC /cast_spell convention).
    if aoe_target_ids and not target_combatant_id:
        target_combatant_id = aoe_target_ids[0]
        target_combatant = _lookup_combatant(campaign_id, target_combatant_id)

    cast_id = uuid.uuid4().hex[:12]

    # Attack roll (for attack-roll spells like Inflict Wounds). Skipped
    # for save spells (Sacred Flame) which resolve via the target's save.
    auto_attack_total = None
    auto_attack_breakdown = ""
    auto_attack_hit = None
    auto_attack_target_ac = None
    is_crit = False
    if attack_roll_flag:
        bonus_expr = (
            attack_bonus_raw
            if attack_bonus_raw and attack_bonus_raw.startswith(("+", "-"))
            else ("+" + attack_bonus_raw if attack_bonus_raw else "")
        )
        atk_expr = "1d20" + bonus_expr
        try:
            r = dice_mod.roll(atk_expr)
            auto_attack_total = r.total
            auto_attack_breakdown = r.breakdown
            import re as _re_crit
            _crit_m = _re_crit.search(
                r"\d*d20[^d=+ ]*=(\d+)", auto_attack_breakdown,
                _re_crit.IGNORECASE,
            )
            if _crit_m and int(_crit_m.group(1)) == 20:
                is_crit = True
        except dice_mod.DiceParseError:
            pass
        if target_combatant and auto_attack_total is not None:
            auto_attack_target_ac = _read_target_ac(
                db, campaign_id, target_combatant,
            )
            auto_attack_hit = bool(
                is_crit or auto_attack_total >= auto_attack_target_ac
            )

    # Damage roll. Crit doubles dice per RAW.
    auto_attack_damage_rolled = 0
    auto_attack_damage_breakdown = ""
    damage_expr_effective = damage_expr_raw
    if damage_expr_raw and is_crit:
        damage_expr_effective = _double_dice_for_crit(damage_expr_raw)
    if damage_expr_effective:
        try:
            r = dice_mod.roll(damage_expr_effective)
            auto_attack_damage_rolled = r.total
            auto_attack_damage_breakdown = r.breakdown
        except dice_mod.DiceParseError:
            pass

    # Auto-apply damage on attack-roll hit (matches /npc_attack pattern).
    # Save-spell damage stays GM-manual for v1 — the GM clicks Apply or
    # manually edits HP after the targets' saves are resolved.
    auto_attack_damage_applied = 0
    target_hp_after = None
    if (
        auto_attack_hit
        and bool(campaign.auto_apply_damage)
        and target_combatant
        and auto_attack_damage_rolled > 0
    ):
        apply_result = await _apply_damage_to_combatant(
            db, campaign_id, target_combatant,
            int(auto_attack_damage_rolled), damage_type,
            is_crit=is_crit, is_attack=True, attack_id=cast_id,
            is_spell=True,
        )
        auto_attack_damage_applied = int(apply_result.get("applied") or 0)
        target_hp_after = apply_result.get("hp_after")

    is_save = bool(save_ability and save_dc)
    target_name_resolved = (
        _lookup_combatant_name(campaign_id, target_combatant_id)
        if target_combatant_id else ""
    )
    # v2.49.217: collected per-target outcomes for the AoE multi-target
    # loop. Always seeded so the client has a uniform array to iterate
    # even for single-target casts.
    auto_save_targets_payload: list[dict] = []

    # v2.49.216: save-spell auto-resolution for NPC casters. Adapted
    # from the PC /cast_spell flow at line ~8277. For NPC targets the
    # server rolls the save from the target's ability mods + applies
    # save-for-half damage on the result. For PC targets a RollRequest
    # is created and broadcast as a roll_request card so the player
    # rolls in their own UI — damage application waits for the
    # response handler (matches the PC /cast_spell behavior).
    auto_save_target_kind = ""
    auto_save_target_name = ""
    auto_save_rolled = None
    auto_save_passed = None
    auto_save_breakdown = ""
    auto_save_damage_rolled = 0
    auto_save_damage_applied = 0
    auto_save_damage_breakdown = ""
    auto_save_prompted = False
    auto_save_prompt_id = 0
    # v2.98.5 — NPC-target condition-install plumbing. The v2.98.5
    # NPC caster → NPC target save-or-suck branch (below) sets these
    # on a successful install so the spell_cast payload + the chat
    # card render the condition chip on the cast card.
    auto_save_buff_key = ""
    auto_save_buff_name = ""
    auto_save_buff_icon = ""
    auto_save_buff_duration = 0
    if (
        is_save
        and target_combatant
        and save_ability in {"STR", "DEX", "CON", "INT", "WIS", "CHA"}
    ):
        auto_save_target_name = target_combatant.get("name", "") or target_name_resolved or ""
        stat_key = f"{save_ability.lower()}_save"
        note_label = f"{spell_name} — {save_ability} save"
        tgt_char_id = target_combatant.get("char_id")
        tgt_char = None
        if tgt_char_id:
            tgt_char = db.query(Character).filter(
                Character.id == int(tgt_char_id),
                Character.campaign_id == campaign_id,
            ).first()

        if tgt_char and tgt_char.owner_user_id:
            # PC target — create a RollRequest the player rolls in their UI.
            # No save_request_context stash for v1 (the existing context
            # dict shape assumes a PC caster — extending it for NPC casters
            # is filed as a follow-up; for now PC saves on NPC casts go
            # through the standard roll_request → /roll_request/{id}/respond
            # path without the auto-damage application). Matches PC AoE
            # save flow's behavior on PC targets.
            auto_save_target_kind = "pc"
            req = RollRequest(
                campaign_id=campaign_id,
                created_by_user_id=user.id,
                label=note_label,
                base_expression="1d20",
                stat_key=stat_key,
                dc=save_dc,
                visibility=Visibility.PUBLIC,
            )
            db.add(req)
            db.commit()
            db.refresh(req)
            await hub.broadcast(campaign_id, {
                "type": "roll_request",
                "data": {
                    "id": req.id,
                    "label": req.label,
                    "stat_key": req.stat_key,
                    "base_expression": req.base_expression,
                    "dc": req.dc,
                    "visibility": req.visibility.value,
                    "created_by_name": user.display_name,
                    "created_by_user_id": user.id,
                    # v2.99.70 — presence-aware routing.
                    "target_user_ids": _resolve_pc_prompt_target_user_ids(
                        db, campaign, tgt_char.owner_user_id,
                    ),
                    "target_user_names": [tgt_char.name],
                },
            })
            auto_save_prompted = True
            auto_save_prompt_id = req.id
            # v2.97.75 — stash the save context so /respond can install
            # the condition buff on a failed save (Banishment →
            # Banished, Confusion → Confused, etc.). caster_char_id = 0
            # signals NPC caster — /respond's install handles 0
            # gracefully (the caster-side concentration anchor at
            # line ~11042 skips when caster_id is falsy). The spell_slug
            # body param drives the catalog lookup; absent slug → no
            # condition install (matches the pre-v2.97.75 behavior).
            if spell_slug:
                _purge_save_request_context()
                _save_request_context[req.id] = {
                    "ts": _time.time(),
                    "campaign_id": campaign_id,
                    "spell_slug": spell_slug,
                    "spell_name": spell_name,
                    "target_character_id": int(tgt_char.id),
                    "target_name": tgt_char.name,
                    "dc": int(save_dc),
                    "save_ability": save_ability,
                    "caster_char_id": 0,
                    "caster_char_name": caster_name,
                    "cast_id": cast_id,
                    # v2.97.80 — thread the NPC caster's combatant id so
                    # /respond's install path can install a
                    # concentration anchor on the NPC + stamp
                    # ``source_combatant_id`` on the target buff.
                    # caster_char_id=0 is the NPC-caster sentinel.
                    "caster_combatant_id": combatant_id,
                }
        elif target_combatant.get("token_template_id"):
            # NPC target — roll the save server-side from the monster's
            # ability mods. Reuses _resolve_stat_modifier on the resolved
            # monster sheet (same helper /cast_spell uses for NPC saves
            # at line ~8399).
            auto_save_target_kind = "npc"
            tmpl = db.query(TokenTemplate).filter(
                TokenTemplate.id == int(target_combatant["token_template_id"]),
            ).first()
            if tmpl:
                npc_sheet = _monster_template_to_sheet(tmpl, campaign_id)
                npc_mod, _ = _resolve_stat_modifier(npc_sheet, "dnd5e", stat_key)
                expr = f"1d20{npc_mod:+d}"
                # v2.155.0 — Phase 2d: NPC condition disadvantage on save d20.
                if _npc_save_condition_disadvantage(target_combatant, stat_key):
                    expr = expr.replace("1d20", "2d20kl1", 1)
                try:
                    r = dice_mod.roll(expr)
                    auto_save_rolled = int(r.total)
                    auto_save_breakdown = r.breakdown
                except dice_mod.DiceParseError:
                    auto_save_rolled = 0
                    auto_save_breakdown = ""
                auto_save_passed = auto_save_rolled >= save_dc
                # v2.156.0 — Phase 2e: auto-fail STR/DEX saves from
                # Paralyzed / Stunned / Unconscious / Petrified.
                if _saver_auto_fails_strdex_save(
                    target_combatant.get("buffs"), stat_key,
                ):
                    auto_save_passed = False
                # Broadcast as a regular roll so the chat-card's
                # _appendSaveResultToSpellCard correlates the result
                # back to this cast via the note prefix. v2.49.219:
                # the `→ ` prefix is what the client's correlation
                # check expects (`r.note.startsWith("→ {saveLabel}")`)
                # — matches the prefix added by /roll_request/{id}/respond
                # at line ~7451 for PC saves; we apply the same prefix
                # for the NPC-target server-rolled saves so both paths
                # land in the same pill row.
                await hub.broadcast(campaign_id, {
                    "type": "roll",
                    "data": {
                        "expression": expr,
                        "total": auto_save_rolled,
                        "breakdown": auto_save_breakdown,
                        "note": f"→ {note_label}"
                        + (" ✓ Pass" if auto_save_passed else " ✗ Fail"),
                        "user_name": auto_save_target_name,
                        "char_name": auto_save_target_name,
                        "visibility": Visibility.PUBLIC.value,
                        "dc": save_dc,
                    },
                })

        # v2.98.5 — NPC caster → NPC target save-or-suck install path.
        # Mirror of the PC-caster → NPC-target block in /cast_spell at
        # line ~12895. When the spell has a ``_SPELL_CONDITION_MAP``
        # entry + the target failed the save, install the matching
        # condition buff on the target NPC via ``_install_buff_on_combatant_id``;
        # if the catalog entry carries ``concentration: True``, also
        # install a caster-side ``concentration-<spell>`` anchor on
        # the NPC caster combatant (matches the v2.97.80 NPC anchor
        # plumbing that /respond's PC-target path uses). The v2.97.60
        # repeated-save stamps + the v2.97.65 ``save_on_damage`` marker
        # are stamped on the target buff so the v2.97.69 end-of-turn
        # auto-fire + v2.97.66 damage-trigger save both work for this
        # path too.
        if (
            spell_slug
            and not damage_expr_raw
            and auto_save_target_kind == "npc"
            and auto_save_passed is False
            and target_combatant
        ):
            cond = _SPELL_CONDITION_MAP.get(spell_slug)
            if cond:
                # Capture the NPC caster's creature type for PFE&G
                # plumbing — same pattern as v2.98.2 /respond install.
                _caster_cb_for_npc = caster
                _caster_type_for_npc = _attacker_creature_type(
                    db, None, _caster_cb_for_npc,
                )
                target_buff = {
                    "key": cond["key"],
                    "name": cond["name"],
                    "icon": cond.get("icon", "💫"),
                    # NPC caster — no source_char_id; use combatant id.
                    "source_combatant_id": combatant_id,
                    "source_char_name": caster_name,
                    "source_spell": spell_name,
                    "duration_rounds": int(cond.get("duration_rounds", 10)),
                    "duration_max": int(cond.get("duration_rounds", 10)),
                    # v2.97.67 — target-side condition buff carries
                    # concentration: False; the caster's anchor below
                    # handles the concentration semantics.
                    "concentration": False,
                    # v2.99.1 — marker for paired-cleanup helper
                    # (_drop_paired_concentration_buffs_npc).
                    "_dependent_on_caster_concentration": bool(cond.get("concentration")),
                    "effects": list(cond.get("effects", [])),
                    "repeated_save_ability": save_ability,
                    "repeated_save_dc": int(save_dc),
                    "source_caster_creature_type": _caster_type_for_npc or "",
                    "save_on_damage": bool(cond.get("save_on_damage")),
                }
                installed = await _install_buff_on_combatant_id(
                    campaign_id, target_combatant.get("id"), target_buff,
                )
                if installed:
                    auto_save_buff_key = cond["key"]
                    auto_save_buff_name = cond["name"]
                    auto_save_buff_icon = cond.get("icon", "💫")
                    auto_save_buff_duration = int(cond.get("duration_rounds", 10))
                    # NPC caster concentration anchor (mirror of the
                    # /respond PC-target NPC-caster path at v2.97.80).
                    if bool(cond.get("concentration")):
                        npc_caster_buff = {
                            "key": f"concentration-{spell_slug}",
                            "name": f"Concentrating: {spell_name}",
                            "icon": "🌀",
                            "source_combatant_id": combatant_id,
                            "source_char_name": caster_name,
                            "source_spell": spell_name,
                            "duration_rounds": int(cond.get("duration_rounds", 10)),
                            "duration_max": int(cond.get("duration_rounds", 10)),
                            "concentration": True,
                            "effects": [f"Concentrating on {spell_name}"],
                        }
                        await _install_buff_on_combatant_id(
                            campaign_id, combatant_id, npc_caster_buff,
                        )

        # Save-for-half damage application on NPC targets when auto_apply
        # is on. Sacred Flame is "no effect on save" not "half" — that's
        # a per-spell distinction the action schema can express in the
        # future; for v1 the universal save-for-half default applies.
        if (
            auto_save_target_kind == "npc"
            and auto_save_passed is not None
            and damage_expr_raw
            and bool(campaign.auto_apply_damage)
        ):
            try:
                r = dice_mod.roll(damage_expr_raw)
                auto_save_damage_rolled = int(r.total)
                auto_save_damage_breakdown = r.breakdown
            except dice_mod.DiceParseError:
                auto_save_damage_rolled = 0
            if auto_save_damage_rolled > 0:
                # v2.51.5: Evasion (Dex saves) for npc_cast_spell single-target.
                proposed, _ev_used = await _apply_evasion_to_dex_save_damage(
                    db, campaign_id,
                    (target_combatant or {}).get("id") if target_combatant else None,
                    auto_save_damage_rolled, bool(auto_save_passed),
                    save_ability,
                )
                if proposed > 0:
                    apply_result = await _apply_damage_to_combatant(
                        db, campaign_id, target_combatant, proposed,
                        damage_type=damage_type, attack_id=cast_id,
                        is_spell=True,
                    )
                    auto_save_damage_applied = int(apply_result.get("applied") or 0)

    # v2.49.217: AoE multi-target loop. Adapted from PC /cast_spell's
    # Phase T.5 at line ~8504. Seeds auto_save_targets with the single-
    # target outcome (so the client has a uniform array even for
    # non-AoE casts) + loops the remaining ids from the picker. NPC
    # targets get a fresh save + save-for-half damage application;
    # PC targets are skipped for v1 (each would need its own roll_request
    # — filed as a follow-up). The single broadcast carries the array;
    # the chat card renders one save-pill per target.
    if is_save:
        # Seed with the single-target outcome (auto_save_* fields set above).
        if target_combatant_id:
            auto_save_targets_payload.append({
                "combatant_id": target_combatant_id,
                "target_name": auto_save_target_name or target_name_resolved,
                "rolled": auto_save_rolled,
                "breakdown": auto_save_breakdown,
                "passed": auto_save_passed,
                "damage_applied": auto_save_damage_applied,
                "damage_type": damage_type,
                "pc_skipped": (auto_save_target_kind == "pc"),
                "pending_request_id": auto_save_prompt_id if auto_save_prompted else 0,
            })
        # Loop remaining AoE ids — skip the first (already resolved above).
        for extra_id in aoe_target_ids[1:]:
            extra = _lookup_combatant(campaign_id, extra_id)
            if not extra:
                continue
            extra_name = extra.get("name", "") or ""
            # PC target — skipped for v1 (same as /cast_spell AoE PC handling).
            if extra.get("char_id"):
                auto_save_targets_payload.append({
                    "combatant_id": extra_id,
                    "target_name": extra_name,
                    "rolled": None,
                    "breakdown": "",
                    "passed": None,
                    "damage_applied": 0,
                    "damage_type": damage_type,
                    "pc_skipped": True,
                    "pending_request_id": 0,
                })
                continue
            # NPC target — server-roll save + save-for-half damage.
            if not extra.get("token_template_id"):
                continue
            _tmpl = db.query(TokenTemplate).filter(
                TokenTemplate.id == int(extra["token_template_id"]),
            ).first()
            if not _tmpl:
                continue
            _npc_sheet = _monster_template_to_sheet(_tmpl, campaign_id)
            _npc_mod, _ = _resolve_stat_modifier(
                _npc_sheet, "dnd5e", f"{save_ability.lower()}_save",
            )
            _expr = f"1d20{_npc_mod:+d}"
            try:
                _r = dice_mod.roll(_expr)
                _rolled = int(_r.total)
                _bd = _r.breakdown
            except dice_mod.DiceParseError:
                _rolled = 0
                _bd = ""
            _passed = _rolled >= save_dc
            _dmg_applied = 0
            if damage_expr_raw and bool(campaign.auto_apply_damage):
                try:
                    _dr = dice_mod.roll(damage_expr_raw)
                    _dmg_rolled = max(0, int(_dr.total))
                except dice_mod.DiceParseError:
                    _dmg_rolled = 0
                if _dmg_rolled > 0:
                    # v2.51.5: Evasion (Dex saves) for npc_cast_spell AoE extras.
                    proposed, _ev_used = await _apply_evasion_to_dex_save_damage(
                        db, campaign_id, extra.get("id"),
                        _dmg_rolled, bool(_passed), save_ability,
                    )
                    if proposed > 0:
                        _dr_result = await _apply_damage_to_combatant(
                            db, campaign_id, extra, proposed,
                            damage_type=damage_type, attack_id=cast_id,
                            is_spell=True,
                        )
                        _dmg_applied = int(_dr_result.get("applied") or 0)
            auto_save_targets_payload.append({
                "combatant_id": extra_id,
                "target_name": extra_name,
                "rolled": _rolled,
                "breakdown": _bd,
                "passed": _passed,
                "damage_applied": _dmg_applied,
                "damage_type": damage_type,
                "pc_skipped": False,
                "pending_request_id": 0,
            })

    # Mirror /cast_spell's spell_cast payload shape so the existing
    # client-side ``appendSpellCast`` renderer (tabletop.js:4307) handles
    # the chat-card chrome without NPC-specific branches.
    payload = {
        "id": cast_id,
        "cast_id": cast_id,
        "caster_user_id": user.id,
        "caster_user_name": user.display_name,
        "caster_user_color": campaign.gm_color or "",
        "caster_portrait_url": "",
        "caster_char_id": None,
        "caster_char_name": caster_name,
        "caster_combatant_id": combatant_id,
        "spell_name": spell_name,
        "spell_level": spell_level,
        "slot_level": spell_level,
        "spell_range": spell_range,
        "spell_damage_type": damage_type,
        "spell_school": "",
        "spell_casting_time": "1 action",
        "spell_concentration": False,
        "spell_ritual": False,
        "target_combatant_id": target_combatant_id or "",
        "target_name": target_name_resolved,
        # Attack-roll auto-resolution (Inflict Wounds path).
        "auto_attack_hit": auto_attack_hit,
        "auto_attack_total": auto_attack_total or 0,
        "auto_attack_breakdown": auto_attack_breakdown,
        "auto_attack_target_ac": auto_attack_target_ac or 0,
        "auto_attack_target_name": target_name_resolved,
        "auto_attack_damage_rolled": auto_attack_damage_rolled,
        "auto_attack_damage_applied": auto_attack_damage_applied,
        "auto_attack_damage_type": damage_type,
        "auto_attack_damage_breakdown": auto_attack_damage_breakdown,
        # Save-spell metadata + v2.49.216 auto-resolution. Server rolls
        # NPC target saves + applies save-for-half damage; PC target gets
        # a roll_request that the player rolls in their own UI.
        "save_dc": save_dc if is_save else 0,
        "save_ability": save_ability if is_save else "",
        "is_save": is_save,
        "auto_save_target_kind": auto_save_target_kind or None,
        "auto_save_target_name": auto_save_target_name,
        "auto_save_rolled": auto_save_rolled,
        "auto_save_passed": auto_save_passed,
        "auto_save_breakdown": auto_save_breakdown,
        "auto_save_dc": save_dc if is_save else 0,
        "auto_save_damage_rolled": auto_save_damage_rolled,
        "auto_save_damage_applied": auto_save_damage_applied,
        "auto_save_damage_type": damage_type if is_save else "",
        "auto_save_damage_breakdown": auto_save_damage_breakdown,
        "auto_save_prompted": auto_save_prompted,
        "auto_save_prompt_id": auto_save_prompt_id,
        # v2.98.5 — NPC-target condition install (Hold Person at
        # bandit, Fear at NPC, etc.). Empty when no condition
        # installed.
        "auto_save_buff_key": auto_save_buff_key,
        "auto_save_buff_name": auto_save_buff_name,
        "auto_save_buff_icon": auto_save_buff_icon,
        "auto_save_buff_duration": auto_save_buff_duration,
        # v2.49.219: save-result correlation label. The PC-target path
        # creates a RollRequest with this label; the player's response
        # produces a roll with note prefixed `→ {label}` which
        # _appendSaveResultToSpellCard at tabletop.js:3686 matches against
        # the cast card's _saveLabel to render the result as a pill row
        # in-card (instead of as a separate roll-log entry). The NPC-
        # target server-rolled save also broadcasts with the same `→ `
        # prefix (see the roll broadcast above) so both paths pill.
        # Set when is_save is true AND a target was actually resolved.
        "auto_save_label": (
            f"{spell_name} — {save_ability} save"
            if (is_save and auto_save_target_kind) else None
        ),
        # v2.49.217: per-target outcomes from the AoE multi-target loop.
        # Empty for single-target casts; one entry per target otherwise.
        "auto_save_targets": auto_save_targets_payload,
        "area_shape": area_shape or None,
        "area_size_ft": area_size_ft,
        # Misc — empty / None for NPC spells (no heal / auto-hit darts /
        # per-action buttons yet). Area fields already set above with the
        # real values passed in the body (v2.49.217).
        "actions": [],
        "auto_heal_applied": 0,
        "auto_hit_targets": [],
        "auto_applied": bool(campaign.auto_apply_damage),
        "is_npc_cast": True,
        "is_crit": is_crit,
        "target_hp_after": target_hp_after,
    }
    # v2.99.186 — NPC Subtle Spell consume + immune flag. Mirror of
    # the PC /cast_spell path at line ~14791. When the NPC caster
    # carries a `metamagic-subtle-pending` buff, drop it one-shot,
    # broadcast the 🤫 marker, and flag the upcoming Counterspell
    # walker as subtle so it short-circuits prompt emission.
    _npc_was_subtle = _npc_has_subtle_pending(campaign_id, combatant_id)
    if _npc_was_subtle:
        await _consume_npc_subtle_pending(campaign_id, combatant_id)
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "combatant_id": combatant_id,
                "character_name": caster_name,
                "feature_name": "🤫 Subtle Spell consumed",
                "feature_desc": (
                    "Cast without verbal or somatic components — "
                    "Counterspell cannot react."
                ),
                "source": "metamagic-subtle-spell-consumed",
                "counterspell_immune": True,
            },
        })
    payload["was_subtle"] = bool(_npc_was_subtle)
    await hub.broadcast(campaign_id, {"type": "spell_cast", "data": payload})
    # v2.70.0 Phase 3b — Counterspell prompt for nearby PC watchers.
    # Mirror of the /cast_spell hook. NPC caster identity is the
    # combatant_id (no char_id).
    try:
        await _emit_counterspell_prompts(
            db, campaign,
            caster_char_id=None,
            caster_combatant_id=combatant_id,
            spell_name=spell_name,
            spell_level=int(spell_level),
            spell_slug="",
            was_subtle=bool(_npc_was_subtle),
        )
    except Exception:
        pass
    return {
        "ok": True,
        "cast_id": cast_id,
        "auto_attack_hit": auto_attack_hit,
        "auto_attack_total": auto_attack_total,
        "auto_attack_damage_rolled": auto_attack_damage_rolled,
        "auto_attack_damage_applied": auto_attack_damage_applied,
        "is_save": is_save,
        "auto_save_target_kind": auto_save_target_kind or None,
        "auto_save_rolled": auto_save_rolled,
        "auto_save_passed": auto_save_passed,
        "auto_save_damage_rolled": auto_save_damage_rolled,
        "auto_save_damage_applied": auto_save_damage_applied,
        "auto_save_prompted": auto_save_prompted,
        # v2.97.75 — surface the prompt id so callers can wait on the
        # PC's save resolution. Pre-v2.97.75 the field was only on the
        # broadcast payload above (line ~27744-27745); the endpoint
        # response wrapper omitted it.
        "auto_save_prompt_id": auto_save_prompt_id,
        # v2.98.5 — surface the NPC-target install fields so callers
        # can detect when a condition landed without parsing the
        # broadcast payload.
        "auto_save_buff_key": auto_save_buff_key,
        "auto_save_buff_name": auto_save_buff_name,
        "auto_save_buff_icon": auto_save_buff_icon,
        "auto_save_buff_duration": auto_save_buff_duration,
        "target_combatant_id": target_combatant_id or "",
        "target_name": target_name_resolved,
        "auto_applied": bool(campaign.auto_apply_damage),
    }


# ----------- API: Undo applied attack damage (v2.24.0 Phase T.2) -----------

@router.post("/api/campaign/{campaign_id}/undo_attack_damage")
async def undo_attack_damage(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Revert the HP change applied by a previous /attack auto-damage.

    Body: ``{attack_id}``.

    Looks up ``attack_id`` in the in-memory ``_attack_damage_log`` (8-hour
    TTL). Applies a healing of equal magnitude back to the target — PCs
    go through ``_apply_hp_change`` (handles dying → alive transitions
    cleanly), NPCs get the hub combatant's ``hp_current`` bumped up.
    Broadcasts ``character_hp_update`` (PC) or ``battle_update`` (NPC)
    so every client refreshes.

    Returns 404 when the attack_id is unknown / expired / never had
    auto-damage applied. Auth: any campaign viewer can call (the
    in-memory log already filters to the rolling player's recent
    attacks; cross-player undo is desirable for the GM correcting a
    misclick by a player). A future commit can tighten to caster /
    GM only if play-testing reveals abuse.
    """
    body = await request.json()
    attack_id = str(body.get("attack_id") or "").strip()
    if not attack_id:
        raise HTTPException(400, "attack_id is required")
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    _purge_attack_damage_log()
    entries = _attack_damage_log.get(attack_id) or []
    # v2.65.0 — log shape is now list[dict] (Phase A refactor). Walk
    # entries in REVERSE order so the most recent apply is undone
    # first. Each entry is independent: damage / heal / buff_install.
    # Entries are filtered to this campaign so cross-campaign cast_id
    # collisions don't leak.
    entries = [
        e for e in entries
        if isinstance(e, dict) and e.get("campaign_id") == campaign_id
    ]
    if not entries:
        raise HTTPException(404, "Damage log entry not found or expired")

    # No-op path: every entry is a miss / nothing applied. Drop the
    # log and return early so the client can render "nothing to undo."
    # v2.92.0 — also keep going if there's a ``spell_slot_spend`` entry
    # to refund (leveled-spell cast that hit no one still consumed a
    # slot; undo should refund it).
    if not any(
        int(e.get("applied") or 0) > 0
        or e.get("kind") == "buff_install"
        or e.get("kind") == "buff_drop_from_save"
        or e.get("kind") == "spell_slot_spend"
        or e.get("kind") == "resource_spend"
        or e.get("kind") == "slot_restore"
        or e.get("kind") == "resource_gain"
        or e.get("kind") == "slot_gain"
        or e.get("kind") == "inventory_consume"
        for e in entries
    ):
        _attack_damage_log.pop(attack_id, None)
        return {"ok": True, "no_op": True}

    # Track aggregate stats for the response payload — caller's chat-
    # card needs to know the total reverted + whether the last entry
    # was a heal (legacy `was_heal` field for the chat card icon).
    last_heal_entry: dict | None = None
    total_reverted = 0
    last_hp_after: int | None = None
    per_target_undone: list[dict] = []

    for entry in reversed(entries):
        kind = entry.get("kind") or ("heal" if entry.get("is_heal") else "damage")
        # v2.65.0 — Phase B: buff_install entries restore the target's
        # buff list to the snapshot taken pre-install.
        if kind == "buff_install":
            await _restore_target_buffs(
                db, campaign_id,
                entry.get("target_char_id"),
                entry.get("target_combatant_id"),
                entry.get("buffs_before") or [],
            )
            per_target_undone.append({
                "kind": "buff_install",
                "target_char_id": entry.get("target_char_id"),
                "buff_key": entry.get("buff_installed_key"),
            })
            continue

        # v2.97.77 — buff_drop_from_save entries restore the target's
        # buff list to the pre-drop snapshot. Same restore mechanism
        # as buff_install (the snapshot was taken BEFORE the drop, so
        # it includes the dropped buff); semantically distinct so the
        # per_target_undone payload labels it correctly for the UI.
        if kind == "buff_drop_from_save":
            await _restore_target_buffs(
                db, campaign_id,
                entry.get("target_char_id"),
                entry.get("target_combatant_id"),
                entry.get("buffs_before") or [],
            )
            per_target_undone.append({
                "kind": "buff_drop_from_save_reverted",
                "target_char_id": entry.get("target_char_id"),
                "target_combatant_id": entry.get("target_combatant_id"),
                "buff_key": entry.get("buff_dropped_key"),
                "buff_name": entry.get("buff_dropped_name"),
            })
            continue

        # v2.97.44 — Heroism temp-HP grant. Stamped by the
        # /cast_spell v2.97.31 walker when installing a buff whose
        # template carries ``effects.heroism_temp_hp_per_turn``.
        # Restores the target's hp_temp to the pre-grant value the
        # log captured. Broadcasts character_hp_update so any open
        # mini-sheet repaints.
        if kind == "heroism_temp_hp_grant":
            _hg_char_id = entry.get("target_char_id")
            _hg_pre = int(entry.get("pre_temp") or 0)
            if _hg_char_id:
                _hg_char = db.query(Character).filter(
                    Character.id == int(_hg_char_id),
                ).first()
                if _hg_char and _hg_char.sheet:
                    _hg_sheet = dict(_hg_char.sheet)
                    _hg_hp = dict(_hg_sheet.get("hp") or {})
                    _hg_hp["temp"] = _hg_pre
                    _hg_sheet["hp"] = _hg_hp
                    _hg_char.sheet = _hg_sheet
                    from sqlalchemy.orm.attributes import flag_modified as _fm_undo
                    _fm_undo(_hg_char, "sheet")
                    db.commit()
                    await hub.broadcast(campaign_id, {
                        "type": "character_hp_update",
                        "data": {
                            "character_id": _hg_char.id,
                            "hp": _hg_hp,
                            "delta": 0,
                            "source": "undo_heroism_temp_hp",
                        },
                    })
            per_target_undone.append({
                "kind": "heroism_temp_hp_reverted",
                "target_char_id": _hg_char_id,
                "restored_temp": _hg_pre,
            })
            continue

        # v2.97.0 — Phase D: resource-pool refund. Stamped by
        # /use_lay_on_hands + /use_second_wind (and future /use_*
        # endpoints that follow the same shape). Bumps the matching
        # ``sheet["resources"][i]["current"]`` back up by ``amount``,
        # clamped to ``max``. Broadcasts ``resource_update`` so any
        # open resources panel re-pips. Distinct from spell_slot_spend
        # because feature uses live in a different sheet location and
        # use a different broadcast type than spell slots.
        if kind == "resource_spend":
            char_id = entry.get("character_id")
            resource_key = (entry.get("resource_key") or "").strip().lower()
            amount = int(entry.get("amount") or 0)
            if char_id and resource_key and amount > 0:
                refund_char = db.query(Character).filter(
                    Character.id == char_id
                ).first()
                if refund_char:
                    refund_sheet = refund_char.sheet or {}
                    refund_resources = list(refund_sheet.get("resources") or [])
                    idx_e = next(
                        (i for i, r in enumerate(refund_resources)
                         if (r.get("key") or "").lower() == resource_key),
                        -1,
                    )
                    if idx_e >= 0:
                        res_e = dict(refund_resources[idx_e])
                        cur_e = int(res_e.get("current") or 0)
                        mx_e = int(res_e.get("max") or 0)
                        new_cur = (
                            min(cur_e + amount, mx_e) if mx_e > 0
                            else cur_e + amount
                        )
                        res_e["current"] = new_cur
                        refund_resources[idx_e] = res_e
                        refund_sheet["resources"] = refund_resources
                        refund_char.sheet = refund_sheet
                        db.commit()
                        await hub.broadcast(
                            campaign_id,
                            {
                                "type": "resource_update",
                                "data": {
                                    "character_id": char_id,
                                    "key": resource_key,
                                    "current": new_cur,
                                    "max": mx_e,
                                },
                            },
                        )
                        per_target_undone.append({
                            "kind": "resource_refunded",
                            "character_id": char_id,
                            "resource_key": resource_key,
                            "amount": amount,
                            "source_label": entry.get("source_label") or "",
                        })
            continue

        # v2.97.5 — Phase D.2: inverse of spell_slot_spend. Stamped by
        # endpoints that RESTORE slots (Arcane Recovery, future Wish-
        # like recoveries). On undo, bumps ``used`` back UP by ``count``
        # (clamped to ``total``) and broadcasts spell_slot_update so the
        # sheet re-pips. Paired with a resource_spend entry for the
        # counter that drove the restore (e.g. arcane-recovery), so a
        # single undo POST replays both legs.
        if kind == "slot_restore":
            char_id = entry.get("character_id")
            cslug = (entry.get("class_slug") or "").strip().lower()
            slot_level_entry = int(entry.get("slot_level") or 0)
            count = int(entry.get("count") or 0)
            if char_id and cslug and slot_level_entry >= 1 and count > 0:
                refund_char = db.query(Character).filter(
                    Character.id == char_id
                ).first()
                if refund_char:
                    refund_sheet = refund_char.sheet or {}
                    all_slots = dict(refund_sheet.get("spell_slots") or {})
                    per_class = dict(all_slots.get(cslug) or {})
                    slot_key_e = str(slot_level_entry)
                    slot_e = dict(per_class.get(slot_key_e) or {"total": 0, "used": 0})
                    used_e = int(slot_e.get("used") or 0)
                    total_e = int(slot_e.get("total") or 0)
                    new_used = min(used_e + count, total_e) if total_e > 0 else used_e + count
                    slot_e["used"] = new_used
                    per_class[slot_key_e] = slot_e
                    all_slots[cslug] = per_class
                    refund_sheet["spell_slots"] = all_slots
                    refund_char.sheet = refund_sheet
                    db.commit()
                    await hub.broadcast(
                        campaign_id,
                        {
                            "type": "spell_slot_update",
                            "data": {
                                "character_id": char_id,
                                "class_slug": cslug,
                                "level": slot_level_entry,
                                "total": total_e,
                                "used": new_used,
                            },
                        },
                    )
                    per_target_undone.append({
                        "kind": "slot_restore_undone",
                        "character_id": char_id,
                        "class_slug": cslug,
                        "slot_level": slot_level_entry,
                        "count": count,
                    })
            continue

        # v2.97.6 — Phase D.3: inverse of resource_spend. Stamped by
        # endpoints that GAIN a resource (Font of Magic to_points adds
        # sorcery-points from a sacrificed slot). On undo, subtracts
        # ``amount`` from the resource's ``current`` (clamped to 0 —
        # can't go negative).
        if kind == "resource_gain":
            char_id = entry.get("character_id")
            resource_key = (entry.get("resource_key") or "").strip().lower()
            amount = int(entry.get("amount") or 0)
            if char_id and resource_key and amount > 0:
                refund_char = db.query(Character).filter(
                    Character.id == char_id
                ).first()
                if refund_char:
                    refund_sheet = refund_char.sheet or {}
                    refund_resources = list(refund_sheet.get("resources") or [])
                    idx_e = next(
                        (i for i, r in enumerate(refund_resources)
                         if (r.get("key") or "").lower() == resource_key),
                        -1,
                    )
                    if idx_e >= 0:
                        res_e = dict(refund_resources[idx_e])
                        cur_e = int(res_e.get("current") or 0)
                        mx_e = int(res_e.get("max") or 0)
                        new_cur = max(0, cur_e - amount)
                        res_e["current"] = new_cur
                        refund_resources[idx_e] = res_e
                        refund_sheet["resources"] = refund_resources
                        refund_char.sheet = refund_sheet
                        db.commit()
                        await hub.broadcast(
                            campaign_id,
                            {
                                "type": "resource_update",
                                "data": {
                                    "character_id": char_id,
                                    "key": resource_key,
                                    "current": new_cur,
                                    "max": mx_e,
                                },
                            },
                        )
                        per_target_undone.append({
                            "kind": "resource_gain_reverted",
                            "character_id": char_id,
                            "resource_key": resource_key,
                            "amount": amount,
                        })
            continue

        # v2.97.6 — Phase D.3: inverse of "the slot exists / is fresh".
        # Stamped by Font of Magic to_slot for the slot side of the
        # conversion. Two flavors:
        #   - ephemeral=True: cast bumped the slot's ``total`` by 1 to
        #     create an over-the-cap slot. On undo decrement total by 1
        #     (clamped to >=0). If the player already cast the ephemeral
        #     slot before undo, ``used`` may exceed the new ``total`` —
        #     accept that and let the next long rest normalize.
        #   - ephemeral=False: cast decremented ``used`` to restore a
        #     used slot. On undo bump used back up by 1 (clamped to total).
        if kind == "slot_gain":
            char_id = entry.get("character_id")
            cslug = (entry.get("class_slug") or "").strip().lower()
            slot_level_entry = int(entry.get("slot_level") or 0)
            ephemeral = bool(entry.get("ephemeral"))
            if char_id and cslug and slot_level_entry >= 1:
                refund_char = db.query(Character).filter(
                    Character.id == char_id
                ).first()
                if refund_char:
                    refund_sheet = refund_char.sheet or {}
                    all_slots = dict(refund_sheet.get("spell_slots") or {})
                    per_class = dict(all_slots.get(cslug) or {})
                    slot_key_e = str(slot_level_entry)
                    slot_e = dict(per_class.get(slot_key_e) or {"total": 0, "used": 0})
                    total_e = int(slot_e.get("total") or 0)
                    used_e = int(slot_e.get("used") or 0)
                    if ephemeral:
                        new_total = max(0, total_e - 1)
                        slot_e["total"] = new_total
                        existing_extra = int(slot_e.get("font_of_magic_extra") or 0)
                        slot_e["font_of_magic_extra"] = max(0, existing_extra - 1)
                        new_used = used_e
                    else:
                        new_total = total_e
                        new_used = min(used_e + 1, total_e) if total_e > 0 else used_e + 1
                        slot_e["used"] = new_used
                    per_class[slot_key_e] = slot_e
                    all_slots[cslug] = per_class
                    refund_sheet["spell_slots"] = all_slots
                    refund_char.sheet = refund_sheet
                    db.commit()
                    await hub.broadcast(
                        campaign_id,
                        {
                            "type": "spell_slot_update",
                            "data": {
                                "character_id": char_id,
                                "class_slug": cslug,
                                "level": slot_level_entry,
                                "total": new_total,
                                "used": new_used,
                            },
                        },
                    )
                    per_target_undone.append({
                        "kind": "slot_gain_reverted",
                        "character_id": char_id,
                        "class_slug": cslug,
                        "slot_level": slot_level_entry,
                        "ephemeral": ephemeral,
                    })
            continue

        # v2.97.8 — Phase D.4: inventory consume refund. Stamped by
        # /use_item when a consumable is used (potion, scroll, etc.).
        # Stores the pre-cast item dict + index + a ``was_removed`` flag
        # for the case where qty hit 0 and the row was popped. On undo:
        # 1. Try to find an item in the current inventory whose ``_slug``
        #    (preferred — survives renames) or ``name`` matches the
        #    stored item. If found, bump its ``qty`` by 1.
        # 2. If not found (row was popped on cast OR player has since
        #    discarded the leftover stack), re-insert the stored
        #    ``item_dict`` at the pre-cast ``inv_idx`` (or append if the
        #    inventory has since shortened past that position).
        # Broadcasts ``inventory_update`` so any open sheet re-renders.
        # HP / death-save effects from a heal item are NOT reversed —
        # mirroring Lay on Hands' v2.97.0 precedent that the resource
        # leg is refunded but downstream effects are filed separately.
        if kind == "inventory_consume":
            char_id = entry.get("character_id")
            inv_idx_e = int(entry.get("inv_idx") or 0)
            item_dict = entry.get("item_dict") or {}
            was_removed = bool(entry.get("was_removed"))
            if char_id and item_dict:
                refund_char = db.query(Character).filter(
                    Character.id == char_id
                ).first()
                if refund_char:
                    refund_sheet = refund_char.sheet or {}
                    refund_inventory = list(refund_sheet.get("inventory") or [])
                    item_slug = (item_dict.get("_slug") or "").strip().lower()
                    item_name = (item_dict.get("name") or "").strip().lower()
                    found_idx = -1
                    for i, it in enumerate(refund_inventory):
                        if not isinstance(it, dict):
                            continue
                        if item_slug:
                            if (it.get("_slug") or "").strip().lower() == item_slug:
                                found_idx = i
                                break
                        else:
                            if (it.get("name") or "").strip().lower() == item_name:
                                found_idx = i
                                break
                    if found_idx >= 0:
                        cur_it = dict(refund_inventory[found_idx])
                        cur_it["qty"] = int(cur_it.get("qty") or 0) + 1
                        refund_inventory[found_idx] = cur_it
                        refunded_idx = found_idx
                        refunded_qty = int(cur_it["qty"])
                    else:
                        # Re-insert at the original position; clamp.
                        restored = dict(item_dict)
                        restored["qty"] = max(1, int(item_dict.get("qty") or 1))
                        insert_at = min(inv_idx_e, len(refund_inventory))
                        refund_inventory.insert(insert_at, restored)
                        refunded_idx = insert_at
                        refunded_qty = int(restored["qty"])
                    refund_sheet["inventory"] = refund_inventory
                    from sqlalchemy.orm.attributes import flag_modified
                    refund_char.sheet = refund_sheet
                    flag_modified(refund_char, "sheet")
                    db.commit()
                    await hub.broadcast(
                        campaign_id,
                        {
                            "type": "inventory_update",
                            "data": {
                                "character_id": char_id,
                                "inventory_index": refunded_idx,
                                "item_name": item_dict.get("name") or "",
                                "qty": refunded_qty,
                                "was_reinserted": found_idx < 0,
                            },
                        },
                    )
                    per_target_undone.append({
                        "kind": "inventory_refunded",
                        "character_id": char_id,
                        "item_name": item_dict.get("name") or "",
                        "was_reinserted": found_idx < 0,
                    })
            continue

        # v2.92.0 — Phase C: spell-slot refund. Stamped at /cast_spell's
        # slot-decrement site (level >= 1 only — cantrips never log an
        # entry). Decrements ``sheet["spell_slots"][cslug][lvl]["used"]``
        # by 1, clamped to 0, then broadcasts spell_slot_update so the
        # sheet's slot row + the over-budget gate both refresh.
        if kind == "spell_slot_spend":
            char_id = entry.get("character_id")
            cslug = (entry.get("class_slug") or "").strip().lower()
            slot_level_entry = int(entry.get("slot_level") or 0)
            if char_id and cslug and slot_level_entry >= 1:
                refund_char = db.query(Character).filter(
                    Character.id == char_id
                ).first()
                if refund_char:
                    refund_sheet = refund_char.sheet or {}
                    all_slots = dict(refund_sheet.get("spell_slots") or {})
                    per_class = dict(all_slots.get(cslug) or {})
                    slot_key_e = str(slot_level_entry)
                    slot_e = dict(per_class.get(slot_key_e) or {"total": 0, "used": 0})
                    used_e = int(slot_e.get("used") or 0)
                    total_e = int(slot_e.get("total") or 0)
                    if used_e > 0:
                        slot_e["used"] = used_e - 1
                        per_class[slot_key_e] = slot_e
                        all_slots[cslug] = per_class
                        refund_sheet["spell_slots"] = all_slots
                        refund_char.sheet = refund_sheet
                        db.commit()
                        await hub.broadcast(
                            campaign_id,
                            {
                                "type": "spell_slot_update",
                                "data": {
                                    "character_id": char_id,
                                    "class_slug": cslug,
                                    "level": slot_level_entry,
                                    "total": total_e,
                                    "used": slot_e["used"],
                                },
                            },
                        )
                        per_target_undone.append({
                            "kind": "spell_slot_refunded",
                            "character_id": char_id,
                            "class_slug": cslug,
                            "slot_level": slot_level_entry,
                            "spell_name": entry.get("spell_name") or "",
                        })
            continue

        applied = int(entry.get("applied") or 0)
        if applied <= 0:
            continue
        is_heal_entry = bool(entry.get("is_heal")) or kind == "heal"
        if is_heal_entry:
            last_heal_entry = entry
        delta_sign = -1 if is_heal_entry else +1
        target_char_id = entry.get("target_char_id")
        target_combatant_id = entry.get("target_combatant_id")

        if target_char_id:
            char = db.query(Character).filter(Character.id == target_char_id).first()
            if not char:
                continue
            sheet = char.sheet or {}
            hp_cur = int((sheet.get("hp") or {}).get("current") or 0)
            hp_max = int((sheet.get("hp") or {}).get("max") or 0)
            if delta_sign > 0:
                new_hp = min(hp_max, hp_cur + applied) if hp_max > 0 else (hp_cur + applied)
            else:
                new_hp = max(0, hp_cur - applied)
            result = _apply_hp_change(char, new_hp)
            db.commit()
            await hub.broadcast(campaign_id, {
                "type": "character_hp_update",
                "data": {
                    "character_id": char.id,
                    "hp": result["hp"],
                    "delta": delta_sign * applied,
                    "source": "undo_heal" if is_heal_entry else "undo_attack",
                },
            })
            total_reverted += applied
            last_hp_after = result["hp"]["current"]
            per_target_undone.append({
                "kind": kind, "target_char_id": target_char_id,
                "applied": applied, "hp_after": last_hp_after,
            })
            continue

        if target_combatant_id:
            state = hub.get_battle(campaign_id)
            if not state:
                continue
            target = None
            for c in state.get("combatants") or []:
                if c.get("id") == target_combatant_id:
                    target = c
                    break
            if target is None:
                continue
            hp_cur = int(target.get("hp_current") or 0)
            hp_max = int(target.get("hp_max") or 0)
            if delta_sign > 0:
                new_hp = min(hp_max, hp_cur + applied) if hp_max > 0 else (hp_cur + applied)
            else:
                new_hp = max(0, hp_cur - applied)
            target["hp_current"] = new_hp
            hub.set_battle(campaign_id, state)
            await hub.broadcast(campaign_id, {
                "type": "battle_update",
                "data": state,
                "force_gm_sync": True,
            })
            total_reverted += applied
            last_hp_after = new_hp
            per_target_undone.append({
                "kind": kind, "target_combatant_id": target_combatant_id,
                "applied": applied, "hp_after": last_hp_after,
            })

    _attack_damage_log.pop(attack_id, None)
    return {
        "ok": True,
        "reverted": total_reverted,
        # Legacy fields for backward-compat with the chat card's undo
        # button. ``hp_after`` matches the FINAL undone entry; pre-
        # v2.65.0 there was only one entry per cast_id so ``hp_after``
        # was unambiguous. For multi-target undo, the per_target list
        # carries the full picture.
        "hp_after": last_hp_after if last_hp_after is not None else 0,
        "was_heal": bool(last_heal_entry),
        "per_target": per_target_undone,
    }


# ----------- API: Open5e item proxy (weapons / armor / magic items) -----------

@router.get("/api/open5e/items")
def open5e_items_proxy(type: str = "weapons", search: str = "", limit: int = 60):
    """Search Open5e for weapons / armor / magic items.

    Items aren't part of the local Open5e cache, so this always proxies the
    public API. Type is one of "weapons", "armor", "magicitems".
    """
    cat = (type or "weapons").strip().lower()
    if cat not in ("weapons", "armor", "magicitems"):
        raise HTTPException(400, "type must be one of weapons, armor, magicitems")
    cap = max(1, min(int(limit or 60), 200))

    import json as _json
    import urllib.parse as _urlparse
    import urllib.request as _urlreq

    qs = _urlparse.urlencode({"search": search or "", "limit": cap})
    url = f"https://api.open5e.com/v1/{cat}/?{qs}"
    try:
        req = _urlreq.Request(url, headers={"User-Agent": "SimpleVTT/1.0"})
        with _urlreq.urlopen(req, timeout=10) as r:
            data = _json.loads(r.read())
    except Exception as e:
        raise HTTPException(502, f"Open5e fetch failed: {e}")

    import re as _re
    raw = data.get("results") or []
    items = []
    for it in raw:
        # Open5e v1 armor stores AC in the `armor_class` field as a string
        # like "16" or "11 + Dex modifier (max 2)" or "+2" for shields.
        # Pull the leading integer (ignoring sign) out for `ac` and pass the
        # original string through for the detail panel.
        ac_string = it.get("armor_class") or it.get("ac_string") or it.get("ac_display") or ""
        ac_int = 0
        if ac_string:
            m = _re.search(r"\d+", str(ac_string))
            if m:
                ac_int = int(m.group(0))
        elif it.get("ac_base") or it.get("ac"):
            try:
                ac_int = int(it.get("ac_base") or it.get("ac") or 0)
            except (TypeError, ValueError):
                ac_int = 0

        items.append({
            "slug": it.get("slug") or it.get("key") or "",
            "name": it.get("name") or "",
            "category": it.get("category") or it.get("type") or it.get("rarity") or "",
            "damage_dice": it.get("damage_dice") or "",
            "damage_type": it.get("damage_type") or "",
            "properties": ", ".join(it.get("properties") or []) if isinstance(it.get("properties"), list) else (it.get("properties") or ""),
            "range": it.get("range") or "",
            "ac": ac_int,
            "ac_string": ac_string,
            "armor_type": it.get("category") or "",
            "stealth_disadvantage": bool(it.get("stealth_disadvantage")),
            "strength_requirement": it.get("strength") or "",
            "weight": it.get("weight") or "",
            "cost": it.get("cost") or "",
            "rarity": it.get("rarity") or "",
            "desc": it.get("desc") or it.get("description") or "",
        })
    return {"results": items}


# ----------- API: concentration tracking -----------

@router.post("/api/campaign/{campaign_id}/concentration")
async def set_concentration(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Set (or replace) the concentration effect for a character.
    Allowed by the character's owner or any GM.
    Body: {character_id, spell_name, rounds, notes}
    """
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    body = await request.json()
    char_id = int(body.get("character_id", 0))
    spell_name = str(body.get("spell_name", "")).strip()[:120]
    if not spell_name:
        raise HTTPException(400, "spell_name is required")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id
    ).first()
    if not char:
        raise HTTPException(404, "Character not found")

    is_gm = _user_is_gm(user, campaign, db)
    if not is_gm and char.owner_user_id != user.id:
        raise HTTPException(403, "Not your character")

    rounds_raw = body.get("rounds")
    rounds = int(rounds_raw) if rounds_raw is not None and str(rounds_raw).strip() else None
    notes = str(body.get("notes", "") or "").strip()[:200] or None

    eff = db.query(ConcentrationEffect).filter(
        ConcentrationEffect.campaign_id == campaign_id,
        ConcentrationEffect.character_id == char_id,
    ).first()
    if eff:
        eff.spell_name = spell_name
        eff.rounds_remaining = rounds
        eff.notes = notes
    else:
        eff = ConcentrationEffect(
            campaign_id=campaign_id,
            character_id=char_id,
            spell_name=spell_name,
            rounds_remaining=rounds,
            notes=notes,
        )
        db.add(eff)
    db.commit()

    await hub.broadcast(campaign_id, {
        "type": "concentration_update",
        "data": {
            "character_id": char_id,
            "spell_name": spell_name,
            "rounds_remaining": rounds,
            "notes": notes or "",
            "ended": False,
        },
    })
    return {"ok": True}


@router.delete("/api/campaign/{campaign_id}/concentration/{char_id}")
async def end_concentration(
    campaign_id: int,
    char_id: int,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """End the concentration effect for a character."""
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")

    char = db.query(Character).filter(
        Character.id == char_id, Character.campaign_id == campaign_id
    ).first()
    if not char:
        raise HTTPException(404, "Character not found")

    is_gm = _user_is_gm(user, campaign, db)
    if not is_gm and char.owner_user_id != user.id:
        raise HTTPException(403, "Not your character")

    eff = db.query(ConcentrationEffect).filter(
        ConcentrationEffect.campaign_id == campaign_id,
        ConcentrationEffect.character_id == char_id,
    ).first()
    if eff:
        db.delete(eff)
        db.commit()

    await hub.broadcast(campaign_id, {
        "type": "concentration_update",
        "data": {"character_id": char_id, "ended": True},
    })

    # v2.49.41 — also drop the caster's concentration buff(s) AND
    # any paired target-side condition buffs. Pre-fix: DELETE
    # /concentration just deleted the ConcentrationEffect row + fired
    # concentration_update with ended:True, but LEFT the concentration
    # buff (Hex / Hunter's Mark / etc.) on the caster's combatant.buffs
    # list AND left paired conditions (Paralyzed via Hold Person,
    # Frightened via Fear, …) on every target's buff list. The GM had
    # to manually × out each chip. ``_remove_buff`` already handles
    # both the broadcast of the post-removal buff list AND the
    # paired-cleanup branch (via ``_drop_paired_concentration_buffs``),
    # so we just iterate the caster's concentration-tagged buffs and
    # call it once per key. Surfaced by the encounter-sim
    # test_concentration_lifecycle (v2.49.25) which had to document
    # that the chip stays put after DELETE as a known limitation.
    state = hub.get_battle(campaign_id)
    if state:
        for c in state.get("combatants") or []:
            if c.get("char_id") == char_id:
                conc_keys = [
                    (b or {}).get("key") for b in c.get("buffs") or []
                    if (b or {}).get("concentration")
                ]
                for key in conc_keys:
                    if key:
                        await _remove_buff(campaign_id, char_id, key)
                break

    return {"ok": True}


@router.post("/api/campaign/{campaign_id}/concentration/{char_id}/tick")
async def tick_concentration(
    campaign_id: int,
    char_id: int,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Decrement rounds_remaining by 1 at the end of the character's turn.
    If rounds_remaining reaches 0, concentration ends automatically.
    Called by the GM's battle tracker when advancing turns.
    """
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only")

    eff = db.query(ConcentrationEffect).filter(
        ConcentrationEffect.campaign_id == campaign_id,
        ConcentrationEffect.character_id == char_id,
    ).first()
    if not eff:
        return {"ok": True, "active": False}

    # Only decrement if rounds are being tracked
    if eff.rounds_remaining is not None:
        eff.rounds_remaining = max(0, eff.rounds_remaining - 1)
        if eff.rounds_remaining == 0:
            db.delete(eff)
            db.commit()
            await hub.broadcast(campaign_id, {
                "type": "concentration_update",
                "data": {"character_id": char_id, "ended": True, "reason": "expired"},
            })
            return {"ok": True, "active": False, "ended": True}
        db.commit()

    await hub.broadcast(campaign_id, {
        "type": "concentration_update",
        "data": {
            "character_id": char_id,
            "spell_name": eff.spell_name,
            "rounds_remaining": eff.rounds_remaining,
            "notes": eff.notes or "",
            "ended": False,
        },
    })
    return {"ok": True, "active": True, "rounds_remaining": eff.rounds_remaining}


# ----------- API: battle / initiative tracker -----------

@router.get("/api/campaign/{campaign_id}/battle")
async def get_battle(
    campaign_id: int,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.101.0 — return the persisted battle state for a campaign.

    Reads the authoritative `battles` row directly from the DB (the
    canonical store the hub write-through-persists to), so a client can
    fetch the current initiative-tracker state over HTTP without opening
    a WebSocket. Returns ``{"battle": <state-dict>}`` when a battle
    exists, or ``{"battle": null}`` when none is persisted. Any campaign
    viewer may read it (players see the init tracker too) — the PUT
    remains GM-only.
    """
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    row = db.get(Battle, campaign_id)
    state = row.state if (row is not None and isinstance(row.state, dict)) else None
    return {"battle": state}


@router.post("/api/campaign/{campaign_id}/battle/line-targets")
async def battle_line_targets(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.159.4 — Phase 8d: server-side line-AoE geometry. Takes a
    caster combatant + a target combatant + an optional width_ft
    (default 5, RAW Lightning Bolt / Javelin of Lightning) and an
    optional max_length_ft (default 120). Walks the segment from the
    caster's token center to the target's token center and returns
    the combatants whose tokens lie within ``width_ft/2`` of the
    segment, excluding the caster + target. Useful for the Javelin
    of Lightning client to pre-fill ``target_combatant_ids`` for
    /use_item_action instead of asking the GM to enumerate by hand.

    Body: ``{caster_combatant_id, target_combatant_id, width_ft=5,
    max_length_ft=120}``. Returns ``{caster_id, target_id, results:
    [{combatant_id, name, distance_ft}]}``.

    Requires the campaign's active map to have grid_size_px > 0
    (no-grid maps return 400). Combatants without a ``source_token_id``
    are silently skipped — they have no on-map position to test.
    """
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    body = await request.json()
    caster_id = str(body.get("caster_combatant_id") or "").strip()
    target_id = str(body.get("target_combatant_id") or "").strip()
    if not caster_id or not target_id:
        raise HTTPException(400, "caster_combatant_id + target_combatant_id required")
    try:
        width_ft = float(body.get("width_ft") or 5)
    except (TypeError, ValueError):
        raise HTTPException(400, "width_ft must be a number")
    try:
        max_length_ft = float(body.get("max_length_ft") or 120)
    except (TypeError, ValueError):
        raise HTTPException(400, "max_length_ft must be a number")
    if width_ft <= 0 or max_length_ft <= 0:
        raise HTTPException(400, "width_ft + max_length_ft must be positive")

    state = hub.get_battle(campaign_id)
    if not state:
        raise HTTPException(404, "No active battle")
    combatants = state.get("combatants") or []
    by_id = {str(c.get("id")): c for c in combatants if isinstance(c, dict)}
    caster = by_id.get(caster_id)
    target = by_id.get(target_id)
    if not caster or not target:
        raise HTTPException(404, "Caster or target combatant not in battle")

    if not campaign.active_map_id:
        raise HTTPException(400, "Campaign has no active map")
    map_row = db.query(Map).filter(Map.id == campaign.active_map_id).first()
    if not map_row or not map_row.grid_size_px:
        raise HTTPException(400, "Active map has no grid_size_px")
    grid_px = int(map_row.grid_size_px)
    grid_type = (
        map_row.grid_type.value if map_row.grid_type else "square"
    ).lower()

    def _xy_for(combatant: dict) -> "tuple[float, float] | None":
        tok_id = combatant.get("source_token_id")
        if not tok_id:
            return None
        tok = db.query(Token).filter(
            Token.id == int(tok_id), Token.map_id == map_row.id,
        ).first()
        if not tok:
            return None
        # Center the token in its tile by adding half a grid cell —
        # consistent with the v2.61.0 distance primitive's read of
        # token.x / token.y as the top-left corner of the cell.
        size = int(tok.size or 1)
        cx = float(tok.x or 0) + (size * grid_px) / 2.0
        cy = float(tok.y or 0) + (size * grid_px) / 2.0
        return (cx, cy)

    caster_xy = _xy_for(caster)
    target_xy = _xy_for(target)
    if caster_xy is None or target_xy is None:
        raise HTTPException(400, "Caster or target has no on-map token position")
    ax, ay = caster_xy
    bx, by = target_xy

    half_width = width_ft / 2.0
    results: list[dict] = []
    for c in combatants:
        if not isinstance(c, dict):
            continue
        cid = str(c.get("id") or "")
        if not cid or cid == caster_id or cid == target_id:
            continue
        xy = _xy_for(c)
        if xy is None:
            continue
        px, py = xy
        dist_seg = _segment_to_point_min_ft(grid_px, ax, ay, bx, by, px, py)
        if dist_seg > half_width:
            continue
        # Also enforce the max line length — combatants beyond the
        # caster → target segment shouldn't be hit just because they
        # happen to be co-linear past the target.
        dist_from_caster = _distance_ft_between_points(
            grid_px, grid_type, ax, ay, px, py,
        )
        if dist_from_caster > max_length_ft:
            continue
        results.append({
            "combatant_id": cid,
            "name": c.get("name") or "",
            "distance_ft": dist_seg,
            "distance_from_caster_ft": dist_from_caster,
        })

    return {
        "caster_id": caster_id,
        "target_id": target_id,
        "width_ft": width_ft,
        "max_length_ft": max_length_ft,
        "results": results,
    }


@router.post("/api/campaign/{campaign_id}/battle/sphere-targets")
async def battle_sphere_targets(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.159.5 — Phase 8e: server-side sphere-AoE geometry. Takes
    a center (either a combatant id OR raw map x/y) + radius_ft and
    returns the combatants whose tokens fall within that radius.
    RAW 5e spheres (Fireball / Shatter / Sleep / Burning Hands when
    interpreted as a sphere variant): "a sphere with a 20-foot
    radius centered on a point you choose within range."

    Body: ``{center_combatant_id?, center_x?, center_y?, radius_ft}``.
    Either ``center_combatant_id`` OR ``(center_x, center_y)`` must
    be supplied. When both are supplied, the combatant wins.

    Returns ``{center_id?, center_x, center_y, radius_ft, results:
    [{combatant_id, name, distance_ft}]}``. The center combatant
    (if supplied via id) is excluded from results — RAW Fireball
    includes the caster's space (this is a target-picker helper,
    so the caller will typically NOT want to include themselves in
    the auto-pick).
    """
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    body = await request.json()
    center_id = str(body.get("center_combatant_id") or "").strip()
    try:
        radius_ft = float(body.get("radius_ft") or 0)
    except (TypeError, ValueError):
        raise HTTPException(400, "radius_ft must be a number")
    if radius_ft <= 0:
        raise HTTPException(400, "radius_ft must be positive")

    state = hub.get_battle(campaign_id)
    if not state:
        raise HTTPException(404, "No active battle")
    if not campaign.active_map_id:
        raise HTTPException(400, "Campaign has no active map")
    map_row = db.query(Map).filter(Map.id == campaign.active_map_id).first()
    if not map_row or not map_row.grid_size_px:
        raise HTTPException(400, "Active map has no grid_size_px")
    grid_px = int(map_row.grid_size_px)
    grid_type = (
        map_row.grid_type.value if map_row.grid_type else "square"
    ).lower()

    def _xy_for_combatant(c: dict) -> "tuple[float, float] | None":
        tok_id = c.get("source_token_id")
        if not tok_id:
            return None
        tok = db.query(Token).filter(
            Token.id == int(tok_id), Token.map_id == map_row.id,
        ).first()
        if not tok:
            return None
        size = int(tok.size or 1)
        cx = float(tok.x or 0) + (size * grid_px) / 2.0
        cy = float(tok.y or 0) + (size * grid_px) / 2.0
        return (cx, cy)

    combatants = state.get("combatants") or []
    by_id = {str(c.get("id")): c for c in combatants if isinstance(c, dict)}

    if center_id:
        center_c = by_id.get(center_id)
        if not center_c:
            raise HTTPException(404, "center combatant not in battle")
        center_xy = _xy_for_combatant(center_c)
        if center_xy is None:
            raise HTTPException(400, "center combatant has no token position")
    else:
        try:
            cx = float(body.get("center_x"))
            cy = float(body.get("center_y"))
        except (TypeError, ValueError):
            raise HTTPException(400, "Either center_combatant_id or center_x+center_y required")
        center_xy = (cx, cy)

    ax, ay = center_xy
    results: list[dict] = []
    for c in combatants:
        if not isinstance(c, dict):
            continue
        cid = str(c.get("id") or "")
        if not cid or (center_id and cid == center_id):
            continue
        xy = _xy_for_combatant(c)
        if xy is None:
            continue
        px, py = xy
        dist = _distance_ft_between_points(grid_px, grid_type, ax, ay, px, py)
        if dist > radius_ft:
            continue
        results.append({
            "combatant_id": cid,
            "name": c.get("name") or "",
            "distance_ft": dist,
        })

    return {
        "center_id": center_id or None,
        "center_x": ax,
        "center_y": ay,
        "radius_ft": radius_ft,
        "results": results,
    }


@router.post("/api/campaign/{campaign_id}/battle/cone-targets")
async def battle_cone_targets(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.159.5 — Phase 8e: server-side cone-AoE geometry. RAW PHB
    p.204: "A cone extends in a direction you choose from its point
    of origin. A cone's width at a given point along its length is
    equal to that point's distance from the point of origin." Width
    == distance from apex means the cone's half-angle is
    arctan(0.5) ≈ 26.57° (apex angle ≈ 53.13°).

    Body: ``{apex_combatant_id, direction_combatant_id, length_ft,
    apex_half_angle_deg=26.57}``. The apex is at the apex combatant's
    token center; the cone points from there through the direction
    combatant's token center, extending ``length_ft`` from the apex.

    Returns ``{apex_id, direction_id, length_ft, apex_half_angle_deg,
    results: [{combatant_id, name, distance_ft}]}``. Apex + direction
    combatants are excluded from results (RAW spell text on
    Burning Hands etc. covers them via the cone shape; this endpoint
    is a target-picker helper, not a damage applier).
    """
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    body = await request.json()
    apex_id = str(body.get("apex_combatant_id") or "").strip()
    direction_id = str(body.get("direction_combatant_id") or "").strip()
    if not apex_id or not direction_id:
        raise HTTPException(400, "apex_combatant_id + direction_combatant_id required")
    try:
        length_ft = float(body.get("length_ft") or 0)
    except (TypeError, ValueError):
        raise HTTPException(400, "length_ft must be a number")
    if length_ft <= 0:
        raise HTTPException(400, "length_ft must be positive")
    try:
        apex_half_angle_deg = float(body.get("apex_half_angle_deg") or 26.57)
    except (TypeError, ValueError):
        apex_half_angle_deg = 26.57

    state = hub.get_battle(campaign_id)
    if not state:
        raise HTTPException(404, "No active battle")
    if not campaign.active_map_id:
        raise HTTPException(400, "Campaign has no active map")
    map_row = db.query(Map).filter(Map.id == campaign.active_map_id).first()
    if not map_row or not map_row.grid_size_px:
        raise HTTPException(400, "Active map has no grid_size_px")
    grid_px = int(map_row.grid_size_px)
    grid_type = (
        map_row.grid_type.value if map_row.grid_type else "square"
    ).lower()

    def _xy_for_combatant(c: dict) -> "tuple[float, float] | None":
        tok_id = c.get("source_token_id")
        if not tok_id:
            return None
        tok = db.query(Token).filter(
            Token.id == int(tok_id), Token.map_id == map_row.id,
        ).first()
        if not tok:
            return None
        size = int(tok.size or 1)
        cx = float(tok.x or 0) + (size * grid_px) / 2.0
        cy = float(tok.y or 0) + (size * grid_px) / 2.0
        return (cx, cy)

    combatants = state.get("combatants") or []
    by_id = {str(c.get("id")): c for c in combatants if isinstance(c, dict)}
    apex_c = by_id.get(apex_id)
    direction_c = by_id.get(direction_id)
    if not apex_c or not direction_c:
        raise HTTPException(404, "apex or direction combatant not in battle")
    apex_xy = _xy_for_combatant(apex_c)
    direction_xy = _xy_for_combatant(direction_c)
    if apex_xy is None or direction_xy is None:
        raise HTTPException(400, "apex or direction combatant has no token position")

    import math as _math_cone
    ax, ay = apex_xy
    dx, dy = direction_xy
    vec_dir_x = dx - ax
    vec_dir_y = dy - ay
    vec_dir_len = (vec_dir_x ** 2 + vec_dir_y ** 2) ** 0.5
    if vec_dir_len == 0:
        raise HTTPException(400, "apex + direction combatants share a position; cone direction undefined")
    half_angle_rad = _math_cone.radians(max(0.0, min(89.9, apex_half_angle_deg)))
    cos_half = _math_cone.cos(half_angle_rad)

    results: list[dict] = []
    for c in combatants:
        if not isinstance(c, dict):
            continue
        cid = str(c.get("id") or "")
        if not cid or cid == apex_id or cid == direction_id:
            continue
        xy = _xy_for_combatant(c)
        if xy is None:
            continue
        px, py = xy
        # Distance from apex (ft).
        dist_ft = _distance_ft_between_points(grid_px, grid_type, ax, ay, px, py)
        if dist_ft > length_ft:
            continue
        # Angle test: vec from apex to combatant vs. cone direction.
        vec_pt_x = px - ax
        vec_pt_y = py - ay
        vec_pt_len = (vec_pt_x ** 2 + vec_pt_y ** 2) ** 0.5
        if vec_pt_len == 0:
            # Combatant sits exactly on the apex — include.
            results.append({
                "combatant_id": cid,
                "name": c.get("name") or "",
                "distance_ft": 0.0,
            })
            continue
        cos_pt = (
            (vec_pt_x * vec_dir_x + vec_pt_y * vec_dir_y)
            / (vec_pt_len * vec_dir_len)
        )
        if cos_pt < cos_half:
            # Outside the cone's angular span.
            continue
        results.append({
            "combatant_id": cid,
            "name": c.get("name") or "",
            "distance_ft": dist_ft,
        })

    return {
        "apex_id": apex_id,
        "direction_id": direction_id,
        "length_ft": length_ft,
        "apex_half_angle_deg": apex_half_angle_deg,
        "results": results,
    }


@router.put("/api/campaign/{campaign_id}/battle")
async def update_battle(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    if not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only")
    state = await request.json()
    # v2.97.58 — Heroism per-turn temp HP recurrence. Detect a turn
    # advance (prev_turn_index != new_turn_index) and re-grant temp HP
    # to the new active combatant if they carry the v2.97.58 install-
    # time-stamped ``effects.heroism_temp_hp_amount`` marker. RAW
    # (PHB p.250): "gains temporary hit points equal to your
    # spellcasting ability modifier at the start of each of its turns."
    # Compute before set_battle so prev_state still has the old
    # turn_index. Apply after set_battle so the buff list seen by the
    # hook matches the new state (in case the client trimmed expired
    # buffs alongside the turn shift). Temp HP RAW does NOT stack with
    # itself — the higher value wins, so the grant is conditional on
    # ``amount > existing_temp``.
    _prev_battle = hub.get_battle(campaign_id) or {}
    _prev_turn = _prev_battle.get("turn_index") if _prev_battle else None
    _new_turn = state.get("turn_index")

    # v2.169.0 — carry forward the lair-action flags. `/battle` PUT
    # replaces the whole state dict with the client body, which (pre-3c
    # UI) doesn't round-trip `in_lair` / `lair_slug`. Without this guard a
    # routine init-tracker save would silently clear the lair state set by
    # `/set_in_lair`. Preserve them whenever the client omits the key.
    if isinstance(state, dict) and isinstance(_prev_battle, dict):
        if "in_lair" not in state and "in_lair" in _prev_battle:
            state["in_lair"] = _prev_battle.get("in_lair")
        if "lair_slug" not in state and "lair_slug" in _prev_battle:
            state["lair_slug"] = _prev_battle.get("lair_slug")
        # v2.172.0 — carry forward the no-repeat memory (RAW MM p.11: a
        # lair action can't be used two rounds in a row) for the same
        # reason as the flags above.
        if "last_lair_action_id" not in state and "last_lair_action_id" in _prev_battle:
            state["last_lair_action_id"] = _prev_battle.get("last_lair_action_id")
        # v2.173.0 — carry forward the once-per-round counter for the same
        # reason (RAW MM p.11: one lair action per round).
        if "lair_acted_round" not in state and "lair_acted_round" in _prev_battle:
            state["lair_acted_round"] = _prev_battle.get("lair_acted_round")
        # v2.175.0 — carry forward the init-20 broadcast dedup marker. The
        # client never round-trips this key, so without the carry-forward
        # every PUT while in the init-20 zone would re-broadcast.
        if ("lair_init20_broadcast_round" not in state
                and "lair_init20_broadcast_round" in _prev_battle):
            state["lair_init20_broadcast_round"] = _prev_battle.get(
                "lair_init20_broadcast_round")
        # v2.181.0 — carry forward the regional-effect fade tracker (RAW MM
        # p.11: effects fade over 1d10 days after the creature dies). The
        # client never round-trips this key, so without the carry-forward a
        # routine init-tracker PUT would clear the countdown.
        if "regional_fade" not in state and "regional_fade" in _prev_battle:
            state["regional_fade"] = _prev_battle.get("regional_fade")

    # v2.99.185 — NPC concentration-drop auto-cascade. Closes a
    # v2.99.179 filed item. Walk the prev/new combatants for any
    # NPC (no char_id) whose concentration buff was present pre-PUT
    # but is absent post-PUT. For each, fire
    # `_drop_paired_concentration_buffs_npc` to clean up paired
    # target-side buffs (Polymorph reverts, condition buffs sourced
    # from this NPC, etc.). Mirror of the v2.99.172 PC cascade
    # which fires on PC's manual /end_buff. NPCs don't have a
    # /end_buff; the /battle PUT is the canonical "edit NPC's
    # buff list" entry point.
    _npc_concentration_dropped: list[str] = []
    _prev_combatants_by_id = {
        c.get("id"): c for c in (_prev_battle.get("combatants") or [])
        if c.get("id")
    }
    for _new_c in (state.get("combatants") or []):
        _cid = _new_c.get("id")
        if not _cid or _new_c.get("char_id"):
            continue  # PC or anonymous; skip
        _prev_c = _prev_combatants_by_id.get(_cid)
        if not _prev_c:
            continue
        _prev_had_conc = any(
            isinstance(b, dict) and bool(b.get("concentration"))
            for b in (_prev_c.get("buffs") or [])
        )
        _new_has_conc = any(
            isinstance(b, dict) and bool(b.get("concentration"))
            for b in (_new_c.get("buffs") or [])
        )
        if _prev_had_conc and not _new_has_conc:
            _npc_concentration_dropped.append(_cid)
    # v2.99.191 — PC mirror of the v2.99.185 NPC cascade detection.
    # When a PC's concentration buff is removed via /battle PUT
    # (e.g. GM strikes it from the init tracker's mini-sheet), fire
    # `_drop_paired_concentration_buffs` for that caster's char_id
    # so paired conditions (Hold Person Paralyzed, Hex on the
    # caster's buff list, Polymorph markers on PC targets, etc.)
    # cascade-drop. PC `/end_buff` already routes through
    # `_remove_buff` which fires the cascade — this closes the
    # `/battle PUT` parallel.
    _pc_concentration_dropped: list[int] = []
    for _new_c in (state.get("combatants") or []):
        _cid_pc = _new_c.get("id")
        _char_id_pc = _new_c.get("char_id")
        if not _cid_pc or not _char_id_pc:
            continue  # NPC or anonymous; PC mirror only
        _prev_c_pc = _prev_combatants_by_id.get(_cid_pc)
        if not _prev_c_pc:
            continue
        _prev_had_conc_pc = any(
            isinstance(b, dict) and bool(b.get("concentration"))
            for b in (_prev_c_pc.get("buffs") or [])
        )
        _new_has_conc_pc = any(
            isinstance(b, dict) and bool(b.get("concentration"))
            for b in (_new_c.get("buffs") or [])
        )
        if _prev_had_conc_pc and not _new_has_conc_pc:
            _pc_concentration_dropped.append(int(_char_id_pc))
    # v2.99.44 — Bard Lv 20 Superior Inspiration. RAW (PHB p.54): "At
    # 20th level, when you roll initiative and have no uses of
    # Bardic Inspiration left, you regain one use." Fires when the
    # battle transitions inactive → active (the canonical "initiative
    # was just rolled" moment). Walks combatants for PC Bards Lv 20+
    # whose bardic-inspiration resource is at 0; refunds 1 use +
    # broadcasts `resource_update` + `feature_used`. Computed
    # BEFORE set_battle so the prev-state read is honest.
    _battle_just_started = (
        bool(state.get("active"))
        and not bool(_prev_battle.get("active"))
    )
    # v2.175.0 — RAW MM p.11: lair actions fire on initiative count 20.
    # Server-authoritative detection of "init 20 reached" so the prompt is
    # broadcast (not just client-derived as in v2.174.0). Mirrors the
    # client logic: the active combatant's initiative <= 20 (combatants
    # above 20 already acted; the lair acts before the first <= 20), or
    # every combatant is above 20 (count 20 falls after the last turn).
    # Deduped per round via `lair_init20_broadcast_round` so it fires once
    # when the turn order crosses into count 20, not on every PUT. Computed
    # before set_battle so the dedup marker persists in the saved state.
    _lair_init20_payload = None
    if isinstance(state, dict) and bool(state.get("in_lair")):
        _combs = state.get("combatants") or []
        _n = len(_combs)
        if _n:
            try:
                _ti = int(state.get("turn_index") or 0)
            except (TypeError, ValueError):
                _ti = 0
            try:
                _cur_round = int(state.get("round") or 0)
            except (TypeError, ValueError):
                _cur_round = 0

            def _init_of(_c):
                try:
                    return float((_c or {}).get("initiative") or 0)
                except (TypeError, ValueError):
                    return 0.0

            _active_init = _init_of(_combs[_ti % _n])
            _all_above_20 = all(_init_of(c) > 20 for c in _combs)
            _reached = (_active_init <= 20) or _all_above_20

            try:
                _acted_round = state.get("lair_acted_round")
                _already_acted = (_acted_round is not None
                                  and int(_acted_round) == _cur_round)
            except (TypeError, ValueError):
                _already_acted = False
            try:
                _last_bcast = state.get("lair_init20_broadcast_round")
                _already_bcast = (_last_bcast is not None
                                  and int(_last_bcast) == _cur_round)
            except (TypeError, ValueError):
                _already_bcast = False

            if _reached and not _already_acted and not _already_bcast:
                _owner_name = ""
                for _c in _combs:
                    if isinstance(_c, dict) and _c.get("lair_actions"):
                        _owner_name = _c.get("name") or ""
                        break
                state["lair_init20_broadcast_round"] = _cur_round
                _lair_init20_payload = {
                    "lair_slug": state.get("lair_slug") or "",
                    "owner_name": _owner_name,
                    "round": _cur_round,
                }

    hub.set_battle(campaign_id, state)
    await hub.broadcast(campaign_id, {"type": "battle_update", "data": state})
    if _lair_init20_payload is not None:
        await hub.broadcast(campaign_id, {
            "type": "lair_init_20_reached",
            "data": _lair_init20_payload,
        })

    # v2.99.185 — Fire the NPC concentration-drop cascade for each
    # NPC that lost concentration via this PUT. Calling AFTER
    # set_battle so the cascade reads the post-PUT state. Each
    # call removes paired buffs sourced from this NPC (e.g.
    # Polymorph reverts via the v2.99.179 hook in the same
    # helper).
    for _dropped_npc_cid in _npc_concentration_dropped:
        try:
            await _drop_paired_concentration_buffs_npc(
                campaign_id, _dropped_npc_cid,
            )
        except Exception:
            # Don't let one cascade failure block the others or
            # the surrounding PUT response.
            pass
    # v2.99.191 — Fire the PC concentration-drop cascade for each
    # PC that lost concentration via this PUT. Mirrors the v2.99.185
    # NPC dispatch above. Removes paired conditions sourced from
    # the PC caster (Hold Person Paralyzed on targets, etc.) and
    # broadcasts a battle_update covering the removals.
    for _dropped_pc_char_id in _pc_concentration_dropped:
        try:
            await _drop_paired_concentration_buffs(
                campaign_id, _dropped_pc_char_id,
            )
        except Exception:
            pass

    if _battle_just_started:
        for _c in (state.get("combatants") or []):
            _bard_cid = _c.get("char_id")
            if not _bard_cid:
                continue
            _bard = db.query(Character).filter(
                Character.id == int(_bard_cid),
                Character.campaign_id == campaign_id,
            ).first()
            if not _bard or not _bard.sheet:
                continue
            _bard_sheet = dict(_bard.sheet)
            if (_bard_sheet.get("class") or "").strip().lower() != "bard":
                continue
            try:
                _bard_level = int(_bard_sheet.get("level") or 0)
            except (TypeError, ValueError):
                _bard_level = 0
            if _bard_level < 20:
                continue
            _bard_resources = list(_bard_sheet.get("resources") or [])
            _bi_row = None
            _bi_idx = -1
            for _i, _r in enumerate(_bard_resources):
                if not isinstance(_r, dict):
                    continue
                if (_r.get("key") or "").strip().lower() == "bardic-inspiration":
                    _bi_row = dict(_r); _bi_idx = _i; break
            if _bi_row is None:
                continue
            _bi_cur = int(_bi_row.get("current") or 0)
            _bi_max = int(_bi_row.get("max") or 0)
            if _bi_cur > 0 or _bi_max <= 0:
                continue
            _bi_row["current"] = 1
            _bard_resources[_bi_idx] = _bi_row
            _bard_sheet["resources"] = _bard_resources
            _bard.sheet = _bard_sheet
            from sqlalchemy.orm.attributes import flag_modified as _fm_si
            _fm_si(_bard, "sheet")
            db.commit()
            await hub.broadcast(campaign_id, {
                "type": "resource_update",
                "data": {
                    "character_id": _bard.id,
                    "key": "bardic-inspiration",
                    "current": 1, "max": _bi_max,
                },
            })
            await hub.broadcast(campaign_id, {
                "type": "feature_used",
                "data": {
                    "character_id": _bard.id,
                    "character_name": _bard.name,
                    "user_color": _bard.color,
                    "feature_name": (
                        "🎵 Superior Inspiration (+1 Bardic Inspiration)"
                    ),
                    "feature_desc": (
                        f"{_bard.name} rolls initiative with no Bardic "
                        f"Inspiration uses left — Superior Inspiration "
                        f"restores one use."
                    ),
                    "source": "superior-inspiration",
                    "granted": 1,
                    "remaining": 1, "max": _bi_max,
                },
            })
        # v2.99.210 — Phase F.2 final: Perfect Self (Monk Lv 20).
        # RAW PHB p.79: "At 20th level, when you roll for
        # initiative and have no ki points remaining, you regain
        # 4 ki points." Direct mirror of the Superior Inspiration
        # hook above. Same init-transition trigger; refunds 4 ki
        # for Monk Lv 20+ PCs whose ki is at 0.
        for _c_ps in (state.get("combatants") or []):
            _monk_cid = _c_ps.get("char_id")
            if not _monk_cid:
                continue
            _monk = db.query(Character).filter(
                Character.id == int(_monk_cid),
                Character.campaign_id == campaign_id,
            ).first()
            if not _monk or not _monk.sheet:
                continue
            _monk_sheet = dict(_monk.sheet)
            if (_monk_sheet.get("class") or "").strip().lower() != "monk":
                continue
            try:
                _monk_level_ps = int(_monk_sheet.get("level") or 0)
            except (TypeError, ValueError):
                _monk_level_ps = 0
            if _monk_level_ps < 20:
                continue
            _monk_resources = list(_monk_sheet.get("resources") or [])
            _ki_row_ps = None
            _ki_idx_ps = -1
            for _i, _r in enumerate(_monk_resources):
                if not isinstance(_r, dict):
                    continue
                if (_r.get("key") or "").strip().lower() == "ki-points":
                    _ki_row_ps = dict(_r); _ki_idx_ps = _i; break
            if _ki_row_ps is None:
                continue
            _ki_cur_ps = int(_ki_row_ps.get("current") or 0)
            _ki_max_ps = int(_ki_row_ps.get("max") or 0)
            if _ki_cur_ps > 0 or _ki_max_ps <= 0:
                continue
            _new_ki = min(4, _ki_max_ps)
            _ki_row_ps["current"] = _new_ki
            _monk_resources[_ki_idx_ps] = _ki_row_ps
            _monk_sheet["resources"] = _monk_resources
            _monk.sheet = _monk_sheet
            from sqlalchemy.orm.attributes import flag_modified as _fm_ps
            _fm_ps(_monk, "sheet")
            db.commit()
            await hub.broadcast(campaign_id, {
                "type": "resource_update",
                "data": {
                    "character_id": _monk.id,
                    "key": "ki-points",
                    "current": _new_ki, "max": _ki_max_ps,
                },
            })
            await hub.broadcast(campaign_id, {
                "type": "feature_used",
                "data": {
                    "character_id": _monk.id,
                    "character_name": _monk.name,
                    "user_color": _monk.color,
                    "feature_name": (
                        "☯️ Perfect Self (+4 Ki Points)"
                    ),
                    "feature_desc": (
                        f"{_monk.name} rolls initiative with no ki "
                        f"left — Perfect Self restores 4 ki "
                        f"(Monk Lv 20+ class feature)."
                    ),
                    "source": "perfect-self",
                    "granted": _new_ki,
                    "remaining": _new_ki, "max": _ki_max_ps,
                },
            })
    if (
        bool(state.get("active"))
        and _prev_turn is not None
        and _new_turn is not None
        and _prev_turn != _new_turn
    ):
        _new_combs = state.get("combatants") or []
        try:
            _active = _new_combs[int(_new_turn)] if (
                0 <= int(_new_turn) < len(_new_combs)
            ) else None
        except (TypeError, ValueError):
            _active = None
        # v2.132.0 — flip the newly-active combatant's `has_acted` to True
        # so Assassinate's "hasn't taken a turn yet" gate stops granting
        # advantage to subsequent attacks on this target. RAW PHB p.97:
        # "any creature that hasn't taken a turn in the combat yet" — once
        # they've had a turn, the gate closes. Applies to both PCs and
        # NPCs (no `char_id` gate), since either can be an Assassinate
        # target.
        if _active is not None:
            _active["has_acted"] = True
        # v2.159.34 — legendary-actions Phase 1b: refresh the active
        # combatant's legendary-action pool to full on their turn start.
        # RAW DMG p.11: legendary action points refresh at the START
        # of the legendary creature's own turn (the points are then
        # spent over the round at the END of each other creature's
        # turn). No-op for non-legendary combatants (the pool field
        # is absent on those, so ``_refresh_legendary_action_pool``
        # returns False and skips the broadcast).
        if _active is not None and _refresh_legendary_action_pool(_active):
            await hub.broadcast(campaign_id, {
                "type": "legendary_action_pool_update",
                "data": {
                    "combatant_id": _active.get("id"),
                    "max": int(
                        (_active.get("legendary_actions") or {}).get("max") or 3
                    ),
                    "current": int(
                        (_active.get("legendary_actions") or {}).get("current") or 0
                    ),
                    "reason": "turn_start_refresh",
                },
            })
        # v2.150.0 — Death Saves Phase 3a: when the newly-active
        # combatant is a PC in `dying` state, broadcast a
        # `death_save_prompt` event so the owning player's client can
        # surface the "Roll Death Save" modal automatically. RAW: the
        # death save is taken at the start of the dying character's
        # turn. The client handler can post to the existing
        # /character/{cid}/death-save endpoint once the player clicks
        # through; this commit ships the server-side prompt hook only,
        # the client UI is a follow-up.
        if _active and _active.get("char_id"):
            try:
                _ds_char = db.query(Character).filter(
                    Character.id == int(_active["char_id"]),
                ).first()
            except (TypeError, ValueError):
                _ds_char = None
            if _ds_char:
                _ds_sheet = _ds_char.sheet or {}
                _ds = _ds_sheet.get("death_saves") or {}
                if (_ds.get("status") or "alive") == "dying":
                    await hub.broadcast(campaign_id, {
                        "type": "death_save_prompt",
                        "data": {
                            "character_id": _ds_char.id,
                            "character_name": _ds_char.name,
                            "combatant_id": _active.get("id"),
                            "successes": int(_ds.get("successes") or 0),
                            "failures": int(_ds.get("failures") or 0),
                            "source": "turn_start",
                        },
                    })
        if _active and _active.get("char_id"):
            _active_buffs = _active.get("buffs") or []
            for _b in _active_buffs:
                if not isinstance(_b, dict):
                    continue
                if _b.get("key") != "heroism":
                    continue
                _hero_eff = _b.get("effects") or {}
                try:
                    _hero_amount = int(_hero_eff.get("heroism_temp_hp_amount") or 0)
                except (TypeError, ValueError):
                    _hero_amount = 0
                if _hero_amount <= 0:
                    continue
                _hero_char = db.query(Character).filter(
                    Character.id == int(_active["char_id"]),
                ).first()
                if not _hero_char or not _hero_char.sheet:
                    continue
                _hero_sheet = dict(_hero_char.sheet)
                _hero_hp = dict(_hero_sheet.get("hp") or {})
                _pre_temp = int(_hero_hp.get("temp") or 0)
                if _hero_amount > _pre_temp:
                    _hero_hp["temp"] = _hero_amount
                    _hero_sheet["hp"] = _hero_hp
                    _hero_char.sheet = _hero_sheet
                    from sqlalchemy.orm.attributes import flag_modified as _fm
                    _fm(_hero_char, "sheet")
                    db.commit()
                    await hub.broadcast(campaign_id, {
                        "type": "character_hp_update",
                        "data": {
                            "character_id": _hero_char.id,
                            "hp": _hero_hp,
                            "delta": 0,
                            "source": "heroism-temp-hp-turn-start",
                        },
                    })
                    await hub.broadcast(campaign_id, {
                        "type": "feature_used",
                        "data": {
                            "source": "heroism-turn-start-temp-hp",
                            "char_name": _hero_char.name,
                            "granted": _hero_amount,
                            "label": (
                                f"Heroism: +{_hero_amount} temp HP "
                                f"at start of {_hero_char.name}'s turn"
                            ),
                        },
                    })
                break  # one Heroism buff per character RAW

        # v2.99.425 — Phase 5.1: aura tick. Apply any aura emitted by the
        # new active combatant (owner-turn-start model) to the creatures
        # in its radius. Runs for ANY active combatant (PC or NPC), so
        # it's outside the PC-gated Heroism block above.
        await _tick_auras(
            db, campaign_id, state, _active,
            campaign=campaign, prompt_user=user,
        )

        # v2.97.62 — auto-fire repeated end-of-turn saves for the
        # PREVIOUS active combatant. RAW (Hold Person / Fear / etc.):
        # "at the end of each of its turns, the target can make
        # another <ability> saving throw." Fires for the combatant
        # whose turn just ended, walks their buffs for any carrying
        # the v2.97.60 install-time stamps (``repeated_save_ability``
        # + ``repeated_save_dc``), rolls each save with the same
        # v2.97.50 PFE&G advantage + v2.97.35 Bless/Bane suffix
        # composition as the v2.97.60 manual endpoint. On a passed
        # save the buff is dropped via ``_remove_buff``. The v2.97.61
        # manual panel still works post-auto-fire for edge cases (a
        # GM rewinding initiative, a player wanting to roll mid-turn
        # for a non-RAW reason).
        try:
            _prev_active_idx = int(_prev_turn)
        except (TypeError, ValueError):
            _prev_active_idx = -1
        _prev_active = None
        if 0 <= _prev_active_idx < len(_new_combs):
            _prev_active = _new_combs[_prev_active_idx]
        # v2.97.70 — delegate to the shared
        # ``_resolve_repeated_save_for_buff`` helper. Saver assembly
        # stays here (PC vs NPC sheet lookup); the save resolution +
        # broadcast + drop loop is shared with /use_repeated_save and
        # the v2.97.65/66 damage-trigger hook.
        if _prev_active:
            _saver_for_eot = None
            if _prev_active.get("char_id"):
                _prev_char_id = int(_prev_active["char_id"])
                _prev_char = db.query(Character).filter(
                    Character.id == _prev_char_id,
                ).first()
                if _prev_char and _prev_char.sheet:
                    _saver_for_eot = {
                        "kind": "pc",
                        "char_id": _prev_char_id,
                        "char_name": _prev_char.name,
                        "sheet": dict(_prev_char.sheet),
                    }
            else:
                _tmpl_id_for_eot = _prev_active.get("token_template_id")
                if _tmpl_id_for_eot:
                    _tmpl_for_eot = db.query(TokenTemplate).filter(
                        TokenTemplate.id == int(_tmpl_id_for_eot),
                    ).first()
                    if _tmpl_for_eot:
                        try:
                            _npc_sheet_eot = _monster_template_to_sheet(
                                _tmpl_for_eot, campaign_id,
                            )
                            _saver_for_eot = {
                                "kind": "npc",
                                "char_name": (
                                    _prev_active.get("name")
                                    or _tmpl_for_eot.name
                                    or "Creature"
                                ),
                                "sheet": _npc_sheet_eot,
                                "combatant": _prev_active,
                            }
                        except Exception:
                            _saver_for_eot = None
            if _saver_for_eot is not None:
                # Snapshot the buff list because the helper mutates
                # state during the loop.
                _rs_buffs = list(_prev_active.get("buffs") or [])
                for _rs_buff in _rs_buffs:
                    if not isinstance(_rs_buff, dict):
                        continue
                    await _resolve_repeated_save_for_buff(
                        campaign_id, db, _saver_for_eot, _rs_buff,
                        note_prefix="🔁 End-of-turn save",
                        feature_used_source="repeated-save-passed-auto",
                    )

    # v2.19.2 Phase C.3: mirror each PC's buff list to their sheet so
    # the full-sheet Active Effects panel reflects auto-expire ticks
    # done client-side by the GM's nextTurn handler. PUT /battle is
    # the post-tick sync point — the GM JS decrements duration_rounds
    # locally, drops expired buffs, then pushes the whole state here.
    # The mirror helper is idempotent (no-op when sheet already matches
    # the new list), so the cost is one query + at most one write per
    # PC combatant per turn-end. NPC buffs (combatants without char_id)
    # are not mirrored — they have no sheet.
    for c in (state.get("combatants") or []):
        char_id = c.get("char_id")
        if not char_id:
            continue
        _mirror_buffs_to_sheet(db, char_id, c.get("buffs") or [])

    return {"ok": True}


# ----------- API: character portrait -----------

_PORTRAIT_DIR = Path(__file__).resolve().parent.parent / "static" / "uploads" / "portraits"
_PORTRAIT_DIR.mkdir(parents=True, exist_ok=True)
_MAX_PORTRAIT_BYTES = 5 * 1024 * 1024
_ALLOWED_PORTRAIT_EXT = {".png", ".jpg", ".jpeg", ".webp", ".gif"}


@router.post("/campaign/{campaign_id}/character/{char_id}/portrait")
async def upload_portrait(
    campaign_id: int,
    char_id: int,
    portrait: UploadFile = File(...),
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    char = db.query(Character).filter(Character.id == char_id).first()
    if not campaign or not char or char.campaign_id != campaign_id:
        raise HTTPException(404, "Not found")
    if not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Cannot edit this character")
    ext = Path(portrait.filename or "").suffix.lower() or ".png"
    if ext not in _ALLOWED_PORTRAIT_EXT:
        raise HTTPException(400, "Unsupported image format (use png/jpg/webp/gif)")
    data = await portrait.read()
    if len(data) > _MAX_PORTRAIT_BYTES:
        raise HTTPException(400, "Image exceeds 5 MB limit")
    if char.portrait_url and char.portrait_url.startswith("/static/uploads/portraits/"):
        old_path = Path(__file__).resolve().parent.parent / "static" / char.portrait_url.removeprefix("/static/")
        try:
            old_path.unlink(missing_ok=True)
        except Exception:
            pass
    fname = f"{uuid.uuid4().hex}{ext}"
    (_PORTRAIT_DIR / fname).write_bytes(data)
    char.portrait_url = f"/static/uploads/portraits/{fname}"
    db.commit()
    return {"ok": True, "portrait_url": char.portrait_url}


# ----------- API: token templates -----------

_TMPL_IMG_DIR = Path(__file__).resolve().parent.parent / "static" / "uploads" / "token_templates"
_TMPL_IMG_DIR.mkdir(parents=True, exist_ok=True)


def _tmpl_dict(tmpl: "TokenTemplate") -> dict:
    return {
        "id": tmpl.id,
        "name": tmpl.name,
        "image_url": tmpl.image_url,
        "tags": tmpl.tags or [],
        "template": tmpl.template,
        "sheet": tmpl.sheet or {},
    }


@router.get("/api/campaign/{campaign_id}/templates")
def list_templates(
    campaign_id: int,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    tmpls = db.query(TokenTemplate).filter(TokenTemplate.campaign_id == campaign_id).order_by(TokenTemplate.name).all()
    return [_tmpl_dict(t) for t in tmpls]


@router.post("/api/campaign/{campaign_id}/templates")
async def create_template(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only")
    body = await request.json()
    tmpl = TokenTemplate(
        campaign_id=campaign_id,
        name=str(body.get("name", "Unnamed"))[:200],
        tags=body.get("tags", []),
        template=body.get("template", "generic"),
        sheet=body.get("sheet", {}),
    )
    db.add(tmpl)
    db.commit()
    db.refresh(tmpl)
    return _tmpl_dict(tmpl)


@router.get("/api/campaign/{campaign_id}/templates/export")
def export_templates(
    campaign_id: int,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only")
    tmpls = db.query(TokenTemplate).filter(TokenTemplate.campaign_id == campaign_id).order_by(TokenTemplate.name).all()
    return {"version": 1, "campaign": campaign.name, "templates": [_tmpl_dict(t) for t in tmpls]}


@router.post("/api/campaign/{campaign_id}/templates/import")
async def import_templates(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only")
    body = await request.json()
    raw_list = body if isinstance(body, list) else body.get("templates", [])
    if not isinstance(raw_list, list):
        raise HTTPException(400, "Expected a list of templates")
    created = []
    for td in raw_list[:100]:
        if not isinstance(td, dict):
            continue
        tpl_type = td.get("template", "generic")
        if tpl_type not in ("generic", "dnd5e"):
            tpl_type = "generic"
        tags = td.get("tags", [])
        img = td.get("image_url")
        sheet = td.get("sheet", {})
        t = TokenTemplate(
            campaign_id=campaign_id,
            name=str(td.get("name", "Imported"))[:200],
            image_url=str(img)[:500] if isinstance(img, str) and img else None,
            tags=tags if isinstance(tags, list) else [],
            template=tpl_type,
            sheet=sheet if isinstance(sheet, dict) else {},
        )
        db.add(t)
        db.flush()
        created.append(_tmpl_dict(t))
    db.commit()
    return {"ok": True, "count": len(created), "templates": created}


@router.post("/api/campaign/{campaign_id}/templates/import-monster")
async def import_open5e_monster(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only")
    body = await request.json()
    slug = str(body.get("slug", "")).strip()
    if not slug:
        raise HTTPException(400, "slug required")
    import json as _json
    import urllib.request as _urlreq
    try:
        req = _urlreq.Request(
            f"{_OPEN5E_BASE}/v2/creatures/{slug}/",
            headers={"User-Agent": "SimpleVTT/1.0"},
        )
        with _urlreq.urlopen(req, timeout=10) as r:
            monster = _json.loads(r.read())
    except Exception as exc:
        raise HTTPException(502, f"Open5e unavailable: {exc}")
    sheet = _open5e_to_dnd5e_sheet(monster)
    tags = [t for t in [_o5e_str(monster.get("type")), _o5e_str(monster.get("size")), f"CR {_o5e_cr(monster)}"] if t]
    tmpl = TokenTemplate(
        campaign_id=campaign_id,
        name=monster.get("name", slug)[:200],
        tags=tags,
        template="dnd5e",
        sheet=sheet,
    )
    db.add(tmpl)
    db.commit()
    db.refresh(tmpl)
    return _tmpl_dict(tmpl)


@router.get("/api/user/gm-campaigns")
def user_gm_campaigns(
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    primary = db.query(Campaign).filter(Campaign.gm_user_id == user.id).all()
    co_ids = [
        m.campaign_id
        for m in db.query(CampaignMembership).filter(
            CampaignMembership.user_id == user.id,
            CampaignMembership.is_gm == True,  # noqa: E712
        ).all()
    ]
    co_gm = db.query(Campaign).filter(Campaign.id.in_(co_ids)).all() if co_ids else []
    seen = {c.id for c in primary}
    return [{"id": c.id, "name": c.name} for c in primary + [c for c in co_gm if c.id not in seen]]


def _custom_monster_lite(row: dict) -> dict:
    """Return a file-based homebrew monster record in the same lite shape the
    beast picker receives from Open5e v2 (after normalisation). v2.0.0: the
    input is now a local_content dict (not a CustomMonster row)."""
    return {
        "slug": row.get("slug"),
        "name": row.get("name"),
        "cr": row.get("challenge_rating") or "0",
        "type": row.get("type") or "",
        "size": row.get("size") or "",
        "hp": row.get("hit_points"),
        "ac": row.get("armor_class"),
        "source": "Custom",
        "is_custom": True,
    }


def _cr_to_float(raw: str) -> float:
    """Convert a CR text ("1/4", "5", "0") to a float for ``cr_max``
    filtering. Unknown forms yield 0."""
    s = (raw or "").strip()
    if "/" in s:
        try:
            a, b = s.split("/", 1)
            return float(a) / float(b)
        except (ValueError, ZeroDivisionError):
            return 0.0
    try:
        return float(s)
    except ValueError:
        return 0.0


@router.get("/api/open5e/monsters")
def open5e_monsters_proxy(
    search: str = "",
    limit: int = 20,
    type_filter: str = "",
    cr_max: str = "",
    campaign_id: int | None = None,
    db: Session = Depends(get_db),
):
    """Proxy for the Open5e v2 creatures endpoint.

    Query params:
        search      — text match on creature name (passed through).
        limit       — page size, capped at 50.
        type_filter — when non-empty, narrows to one creature type
                      (e.g. ``beast``). Forwarded to v2 as
                      ``type__key={type_filter}``.
        cr_max      — when non-empty, narrows to creatures of CR <= the
                      given value. Accepts ``"1/4"`` etc.; converted to
                      a decimal and passed as ``cr__lte=``.

    The v2 endpoint uses different field names than v1 (``cr`` rather
    than ``challenge_rating``, ``type`` / ``size`` as ``{key,name}``
    dicts). Output is normalized so the client can rely on the legacy
    flat-string shape regardless of upstream version.

    On a 4xx from v2 (e.g. a filter param the API doesn't accept), we
    retry once without the filter so the picker stays usable.
    """
    import json as _json
    import urllib.parse as _urlparse
    import urllib.request as _urlreq
    import urllib.error as _urlerr

    # ── Campaign-scoped homebrew monsters prepend the list ───────────────
    # Apply the same filters the client wanted upstream (type, cr_max,
    # search) so a homebrew "Awakened Boulder" only shows up when the
    # picker is in beast / Free pick mode.
    custom_rows: list[dict] = []
    custom_slugs: set[str] = set()
    if campaign_id:
        records, _ = local_content.search(
            type="monsters", campaign_id=campaign_id, q=search, limit=min(abs(limit), 50),
        )
        rows = [r for r in records if r.get("_source") == "local-homebrew"]
        if type_filter:
            tf = type_filter.strip().lower()
            rows = [r for r in rows if (r.get("type") or "").lower() == tf]
        if cr_max:
            cap = _cr_to_float(cr_max)
            rows = [r for r in rows if _cr_to_float(r.get("challenge_rating") or "0") <= cap]
        for r in rows:
            custom_rows.append(_custom_monster_lite(r))
            slug_v = r.get("slug")
            if slug_v:
                custom_slugs.add(slug_v)

    def _build_url(use_filters: bool) -> str:
        # Open5e v2 is django-filter based and silently ignores DRF's
        # ``?search=`` — name matching uses ``?name__icontains=foo``
        # instead. The v1 endpoints (still used by the spell / class
        # proxies elsewhere in this file) DO honour ``?search=``, so
        # keep that pattern there but send the v2 idiom here.
        params: dict[str, str] = {
            "limit": str(min(abs(limit), 50)),
        }
        if search:
            params["name__icontains"] = search
        if use_filters and type_filter:
            params["type__key"] = type_filter.strip().lower()
        if use_filters and cr_max:
            try:
                raw = cr_max.strip()
                cr_val = (float(raw.split("/")[0]) / float(raw.split("/")[1])) if "/" in raw else float(raw)
                params["cr__lte"] = str(cr_val)
            except (TypeError, ValueError):
                pass
        return f"{_OPEN5E_BASE}/v2/creatures/?{_urlparse.urlencode(params)}"

    def _fetch(url: str) -> dict:
        req = _urlreq.Request(url, headers={"User-Agent": "SimpleVTT/1.0"})
        with _urlreq.urlopen(req, timeout=8) as r:
            return _json.loads(r.read())

    data: dict
    try:
        data = _fetch(_build_url(use_filters=True))
    except _urlerr.HTTPError as exc:
        if 400 <= exc.code < 500:
            # Filter param the API doesn't accept (or schema drift) —
            # retry once with the plain search so the picker still works.
            try:
                data = _fetch(_build_url(use_filters=False))
            except Exception as exc2:
                # If we have homebrew, prefer returning just that over a 502.
                if custom_rows:
                    return {"count": len(custom_rows), "results": custom_rows}
                raise HTTPException(502, f"Open5e unavailable: {exc2}")
        else:
            if custom_rows:
                return {"count": len(custom_rows), "results": custom_rows}
            raise HTTPException(502, f"Open5e unavailable: {exc}")
    except Exception as exc:
        if custom_rows:
            return {"count": len(custom_rows), "results": custom_rows}
        raise HTTPException(502, f"Open5e unavailable: {exc}")

    results = []
    for m in data.get("results", []):
        slug = m.get("key", m.get("slug", ""))
        # Homebrew with the same slug shadows the Open5e entry.
        if slug in custom_slugs:
            continue
        ac = m.get("armor_class", 10)
        if isinstance(ac, list) and ac:
            ac = ac[0].get("value", 10) if isinstance(ac[0], dict) else ac[0]
        results.append({
            "slug": slug,
            "name": m.get("name", ""),
            # v2 uses ``cr`` (string); v1 used ``challenge_rating``. _o5e_cr
            # handles both.
            "cr": _o5e_cr(m),
            # ``type`` / ``size`` arrive as either plain strings (v1) or
            # ``{"key", "name"}`` dicts (v2) — coerce to a string so the
            # client's ``.toLowerCase()`` filter doesn't blow up.
            "type": _o5e_str(m.get("type")),
            "size": _o5e_str(m.get("size")),
            "hp": m.get("hit_points", 0),
            "ac": ac,
            "source": m.get("document__title", m.get("document", {}).get("title", "") if isinstance(m.get("document"), dict) else ""),
        })
    return {
        "count": len(custom_rows) + data.get("count", 0),
        "results": custom_rows + results,
    }


def _creature_lite(m: dict) -> dict:
    """Slim an Open5e creature record down to the same shape returned by
    the monsters list proxy. Used by ``/api/open5e/creature/{slug}`` so
    the picker's Favorites section can render rows that look identical
    to the search results."""
    ac = m.get("armor_class", 10)
    if isinstance(ac, list) and ac:
        ac = ac[0].get("value", 10) if isinstance(ac[0], dict) else ac[0]
    return {
        "slug": m.get("key", m.get("slug", "")),
        "name": m.get("name", ""),
        "cr": _o5e_cr(m),
        "type": _o5e_str(m.get("type")),
        "size": _o5e_str(m.get("size")),
        "hp": m.get("hit_points", 0),
        "ac": ac,
        "source": m.get("document__title", m.get("document", {}).get("title", "") if isinstance(m.get("document"), dict) else ""),
    }


def _creature_full(m: dict) -> dict:
    """Extended creature shape that adds abilities, actions, and speed
    to the lite shape. Used by the beast picker detail panel."""
    base = _creature_lite(m)
    abilities = {}
    for short, full_key in [
        ("STR", "strength"), ("DEX", "dexterity"), ("CON", "constitution"),
        ("INT", "intelligence"), ("WIS", "wisdom"), ("CHA", "charisma"),
    ]:
        val = _o5e_ability(m, short.lower(), full_key)
        abilities[short] = val if val is not None else 10
    actions = []
    for a in (m.get("actions") or []):
        if isinstance(a, dict):
            name = (a.get("name") or "").strip()
            desc = (a.get("desc") or "").strip()
            if name or desc:
                # v2.99.469 — derive structured combat fields from the
                # prose desc so imported Open5e monsters' Strike buttons
                # resolve via /npc_attack + /npc_cast_spell (same as the
                # backfilled local SRD set). Existing structured fields on
                # the source action win over the parsed ones.
                from ..content.monster_action_parse import (
                    parse_monster_action_combat as _parse_monster_action_combat,
                )
                parsed = _parse_monster_action_combat(desc)
                for k, v in parsed.items():
                    if a.get(k) not in (None, "", 0, False):
                        parsed[k] = a.get(k)
                actions.append({"name": name, "desc": desc, **parsed})
    speed_raw = m.get("speed", {})
    speed = {}
    if isinstance(speed_raw, dict):
        for k, v in speed_raw.items():
            if v:
                speed[k] = v
    return {**base, "abilities": abilities, "actions": actions, "speed": speed}


@router.get("/api/open5e/creature/{slug}")
def open5e_creature_detail(
    slug: str,
    campaign_id: int | None = None,
    full: bool = False,
    db: Session = Depends(get_db),
):
    """Creature lookup by slug.

    When ``full=true``, the response also includes ability scores, actions,
    and speed — used by the beast picker detail panel.

    When ``campaign_id`` is supplied, a homebrew monster with this slug
    in that campaign takes precedence over the Open5e fetch.
    Returns 404 when neither source has the slug.
    """
    slug = (slug or "").strip()
    if not slug:
        raise HTTPException(400, "slug required")
    # 1. Campaign homebrew first (v2.0.0: file-based).
    if campaign_id:
        hit = local_content.resolve(slug.lower(), type="monsters", campaign_id=campaign_id)
        if hit and hit[1] == "local-homebrew":
            return _custom_monster_lite(hit[0])
    # 2. Live Open5e v2.
    import json as _json
    import urllib.request as _urlreq
    import urllib.error as _urlerr
    try:
        req = _urlreq.Request(
            f"{_OPEN5E_BASE}/v2/creatures/{slug}/",
            headers={"User-Agent": "SimpleVTT/1.0"},
        )
        with _urlreq.urlopen(req, timeout=8) as r:
            monster = _json.loads(r.read())
    except _urlerr.HTTPError as exc:
        if exc.code == 404:
            raise HTTPException(404, f"Creature '{slug}' not found")
        raise HTTPException(502, f"Open5e unavailable: {exc}")
    except Exception as exc:
        raise HTTPException(502, f"Open5e unavailable: {exc}")
    return _creature_full(monster) if full else _creature_lite(monster)


@router.get("/api/open5e/update-check")
def open5e_update_check(request: Request, db: Session = Depends(get_db)):
    """Compare local Open5e data counts against the live public API.

    Only meaningful when LOCAL_OPEN5E=true. Restricted to authenticated users
    so random visitors can't trigger outbound HTTP calls.
    """
    user = get_current_user(request, db)
    if not user:
        raise HTTPException(401, "Login required")
    from ..open5e_local import check_staleness
    return check_staleness()


def _fmt_hit_die(c: dict) -> str:
    hd = c.get("hit_die") or c.get("hit_dice") or ""
    if not hd:
        return ""
    s = str(hd).strip()
    if not s or s == "0":
        return ""
    if s.startswith("1d"):
        return s[1:]   # "1d6" → "d6"
    if s.startswith("d"):
        return s
    try:
        int(s)
        return f"d{s}"
    except ValueError:
        return s


def _class_detail_response(c: dict) -> dict:
    from ..open5e_local import format_class_text
    return {
        "text": format_class_text(c),
        "hit_die": _fmt_hit_die(c),
        "armor": c.get("prof_armor", "") or "",
        "weapons": c.get("prof_weapons", "") or "",
        "tools": c.get("prof_tools", "") or "",
        "saving_throws": c.get("prof_saving_throws", "") or "",
        "skills": c.get("prof_skills", "") or "",
        "spellcasting": (c.get("spellcasting_ability", "") or "").upper(),
        "equipment": c.get("equipment", "") or "",
        "features": c.get("features_json", "") or c.get("features", "") or "",
    }


@router.get("/api/open5e/class-detail")
def open5e_class_detail(
    slug: str = "",
    campaign_id: int | None = None,
    db: Session = Depends(get_db),
):
    from ..open5e_local import is_ready, get_class
    from .. import local_features
    if not slug:
        raise HTTPException(400, "slug required")
    # 1. Local-first provider chain. DB-backed homebrew (custom_classes)
    # wins over the shipped FS overrides; both shadow Open5e fallbacks.
    scopes = [f"campaign:{campaign_id}", "global"] if campaign_id else ["global"]
    record, source = local_features.resolve_class(slug, scopes=scopes, db=db)
    if record:
        return {**_class_detail_response(record), "source": source}
    # 2. Local Open5e mirror (LOCAL_OPEN5E=true).
    if is_ready():
        c = get_class(slug)
        if c:
            local_features.record_miss("class", slug, source="open5e_mirror")
            return {**_class_detail_response(c), "source": "open5e_mirror"}
    # 3. Live Open5e fallback.
    import json as _json, urllib.request as _urlreq
    try:
        req = _urlreq.Request(f"https://api.open5e.com/v1/classes/{slug}/",
                              headers={"User-Agent": "SimpleVTT/1.0"})
        with _urlreq.urlopen(req, timeout=8) as r:
            c = _json.loads(r.read())
    except Exception as exc:
        local_features.record_miss("class", slug, source="open5e_unreachable")
        raise HTTPException(502, f"Open5e unavailable: {exc}")
    local_features.record_miss("class", slug, source="open5e_live")
    return {**_class_detail_response(c), "source": "open5e_live"}


def _subclass_response(s: dict) -> dict:
    from ..open5e_local import format_subclass_text, parse_subclass_features
    parsed = parse_subclass_features(s)
    return {
        "text": format_subclass_text(s),
        "name": parsed["name"],
        "flavor": parsed["flavor"],
        "features": parsed["features"],
    }


@router.get("/api/open5e/subclass-detail")
def open5e_subclass_detail(
    slug: str = "",
    class_slug: str = "",
    campaign_id: int | None = None,
    db: Session = Depends(get_db),
):
    from ..open5e_local import is_ready, get_subclass, format_subclass_text
    from .. import local_features
    if not slug:
        raise HTTPException(400, "slug required")
    # Build the scope priority list.  Campaign-scoped homebrew (DB
    # provider) wins over the shipped global SRD content (FS provider).
    # Caller may omit ``campaign_id`` — then only global content is
    # considered, preserving the v0.40.1 contract.
    scopes = [f"campaign:{campaign_id}", "global"] if campaign_id else ["global"]
    # 1. Local-first provider chain.  Files already match the response
    # shape; synthesise the legacy "text" summary if absent.
    record, source = local_features.resolve_subclass(class_slug, slug, scopes=scopes, db=db)
    if record:
        features = record.get("features") or []
        return {
            "text": record.get("text") or format_subclass_text({
                "name": record.get("name", ""),
                "subclass_flavor": record.get("flavor", ""),
                "feature_items": features,
            }),
            "name": record.get("name", ""),
            "flavor": record.get("flavor", ""),
            "features": features,
            "source": source,
        }
    # 2. Local Open5e mirror.
    if is_ready():
        s = get_subclass(slug)
        if s:
            local_features.record_miss("subclass", slug, class_slug=class_slug, source="open5e_mirror")
            return {**_subclass_response(s), "source": "open5e_mirror"}
    import json as _json, urllib.request as _urlreq

    def _req(url: str) -> dict:
        r = _urlreq.Request(url, headers={"User-Agent": "SimpleVTT/1.0"})
        with _urlreq.urlopen(r, timeout=8) as resp:
            return _json.loads(resp.read())

    # 3. Live Open5e — primary: v1/subclasses/{slug}/
    try:
        s = _req(f"https://api.open5e.com/v1/subclasses/{slug}/")
        local_features.record_miss("subclass", slug, class_slug=class_slug, source="open5e_live")
        return {**_subclass_response(s), "source": "open5e_live"}
    except Exception:
        pass

    # 4. Live Open5e — fallback: archetype inside the parent class detail
    if class_slug:
        try:
            data = _req(f"https://api.open5e.com/v1/classes/{class_slug}/")
            archetypes = data.get("archetypes") or data.get("subclasses") or []
            for a in archetypes:
                if a.get("slug") == slug or a.get("name", "").lower() == slug.replace("-", " "):
                    local_features.record_miss("subclass", slug, class_slug=class_slug, source="open5e_live")
                    return {**_subclass_response(a), "source": "open5e_live"}
        except Exception:
            pass

    local_features.record_miss("subclass", slug, class_slug=class_slug, source="open5e_unreachable")
    return {"text": "", "name": "", "flavor": "", "features": [], "source": "open5e_unreachable"}


@router.get("/api/open5e/race-detail")
def open5e_race_detail(
    slug: str = "",
    campaign_id: int | None = None,
    db: Session = Depends(get_db),
):
    from ..open5e_local import is_ready, get_race, format_race_text, parse_race_traits
    from .. import local_features
    if not slug:
        raise HTTPException(400, "slug required")

    # 1. Local-first provider chain (DB + reserved FS slot).
    scopes = [f"campaign:{campaign_id}", "global"] if campaign_id else ["global"]
    record, source = local_features.resolve_race(slug, scopes=scopes, db=db)
    if record:
        # Synthesise the legacy Open5e fields the renderers expect.
        synth: dict = {
            "name": record.get("name", ""),
            "ability_bonuses": record.get("ability_bonuses") or [],
            "size": record.get("size") or "",
            "speed": record.get("speed") or {"walk": 30},
            "age": record.get("age") or "",
            "alignment": record.get("alignment") or "",
            "languages": record.get("languages") or "",
        }
        flavor = format_race_text({**synth})  # not used — overwritten below
        # Build the structured response using the existing helpers; pass
        # the same fields ``parse_race_traits`` expects, plus a synthetic
        # ``traits`` markdown blob derived from the structured trait list
        # so the parser round-trips.
        traits_list = record.get("traits_list") or []
        traits_blob = "\n\n".join(
            f"### {t.get('name','').strip()}\n{(t.get('desc') or '').strip()}"
            for t in traits_list if isinstance(t, dict) and t.get("name")
        )
        parsed = parse_race_traits({**synth, "traits": traits_blob})
        # If parse_race_traits fell back to a single "Racial Traits" card
        # because no markdown headings were found (which won't happen with
        # our synthesised blob), prefer the structured list directly.
        return {
            "text":   format_race_text({**synth, "traits": traits_blob}),
            "name":   parsed["name"] or record.get("name", ""),
            "flavor": parsed["flavor"],
            "traits": traits_list or parsed["traits"],
            "source": source,
        }

    # 2. Local Open5e mirror.
    if is_ready():
        r_data = get_race(slug)
        if r_data:
            local_features.record_miss("race", slug, source="open5e_mirror")
            parsed = parse_race_traits(r_data)
            return {
                "text":   format_race_text(r_data),
                "name":   parsed["name"],
                "flavor": parsed["flavor"],
                "traits": parsed["traits"],
                "source": "open5e_mirror",
            }

    # 3. Live Open5e fallback.
    import json as _json, urllib.request as _urlreq
    try:
        req = _urlreq.Request(f"https://api.open5e.com/v1/races/{slug}/",
                              headers={"User-Agent": "SimpleVTT/1.0"})
        with _urlreq.urlopen(req, timeout=8) as r:
            r_data = _json.loads(r.read())
    except Exception as exc:
        local_features.record_miss("race", slug, source="open5e_unreachable")
        raise HTTPException(502, f"Open5e unavailable: {exc}")
    local_features.record_miss("race", slug, source="open5e_live")
    parsed = parse_race_traits(r_data)
    return {
        "text":   format_race_text(r_data),
        "name":   parsed["name"],
        "flavor": parsed["flavor"],
        "traits": parsed["traits"],
        "source": "open5e_live",
    }


@router.get("/api/open5e/subclasses")
def open5e_subclasses_proxy(
    search: str = "",
    class_slug: str = "",
    limit: int = 20,
    campaign_id: int | None = None,
    db: Session = Depends(get_db),
):
    from ..open5e_local import is_ready, search_subclasses, _source
    cap = min(abs(limit), 100)

    # ── Campaign-scoped homebrew (DB-backed) takes the top of the list ───────
    # and shadows any Open5e / mirror entry with the same slug.  Carries
    # ``is_custom: true`` so the picker can render an authoring affordance.
    custom_results: list[dict] = []
    custom_slugs: set[str] = set()
    if campaign_id:
        # v2.0.0: file-based subclasses. The file's `slug` is the combined
        # `<class>__<sub>` form; we split for the response shape that the
        # picker UI already consumes (it shows `slug` = the bare sub_slug
        # and filters by class_slug separately).
        records, _ = local_content.search(
            type="subclass_features", campaign_id=campaign_id, q=search, limit=cap,
        )
        for rec in records:
            if rec.get("_source") != "local-homebrew":
                continue
            combined = rec.get("slug") or ""
            cls_part, _, sub_part = combined.partition("__")
            if not sub_part:
                sub_part = combined
                cls_part = rec.get("class_slug") or ""
            if class_slug and cls_part != class_slug:
                continue
            if not sub_part:
                continue
            custom_results.append({
                "name": rec.get("name") or sub_part,
                "slug": sub_part,
                "flavor": (rec.get("subclass_flavor") or rec.get("flavor") or "")[:300],
                "source": "Custom",
                "is_custom": True,
            })
            custom_slugs.add(sub_part)

    def _dedupe(results: list[dict]) -> list[dict]:
        return [r for r in results if r.get("slug") not in custom_slugs]

    if is_ready():
        items, total = search_subclasses(q=search, class_slug=class_slug, limit=cap)
        open5e_rows = [
            {"name": s.get("name", ""), "slug": s.get("slug", ""),
             "flavor": s.get("subclass_flavor", ""), "source": _source(s)}
            for s in items
        ]
        open5e_rows = _dedupe(open5e_rows)
        return {
            "count": len(custom_results) + total - (len(items) - len(open5e_rows)),
            "results": custom_results + open5e_rows,
        }
    import json as _json, urllib.parse as _urlparse, urllib.request as _urlreq

    def _req(url: str) -> dict:
        r = _urlreq.Request(url, headers={"User-Agent": "SimpleVTT/1.0"})
        with _urlreq.urlopen(r, timeout=8) as resp:
            return _json.loads(resp.read())

    def _q_match(name: str) -> bool:
        return not search or search.lower() in name.lower()

    # ── Primary: v1/subclasses/ ───────────────────────────────────────────────
    try:
        params: dict = {"limit": cap}
        if search:     params["search"] = search
        if class_slug: params["class_slug"] = class_slug
        data = _req(f"https://api.open5e.com/v1/subclasses/?{_urlparse.urlencode(params)}")
        results = []
        for s in data.get("results", []):
            src = s.get("document__title", "") or (
                s.get("document", {}).get("title", "") if isinstance(s.get("document"), dict) else ""
            )
            results.append({"name": s.get("name", ""), "slug": s.get("slug", ""),
                             "flavor": s.get("subclass_flavor", ""), "source": src})
        results = _dedupe(results)
        return {
            "count": len(custom_results) + data.get("count", 0),
            "results": custom_results + results,
        }
    except Exception:
        pass

    # ── Fallback: extract archetypes from the class detail endpoint ───────────
    # The v1/subclasses/ endpoint is unreliable; v1/classes/{slug}/ embeds
    # archetype data (subclasses) directly in the class object.
    if class_slug:
        try:
            data = _req(f"https://api.open5e.com/v1/classes/{class_slug}/")
            archetypes = data.get("archetypes") or data.get("subclasses") or []
            results = []
            for a in archetypes:
                name = a.get("name", "")
                if not _q_match(name):
                    continue
                results.append({
                    "name": name,
                    "slug": a.get("slug", ""),
                    "flavor": a.get("subtypes_name", "") or "",
                    "source": a.get("document__title", ""),
                })
            results = _dedupe(results)
            return {
                "count": len(custom_results) + len(results),
                "results": (custom_results + results)[:cap],
            }
        except Exception:
            pass

    # ── Both Open5e sources failed — still return any homebrew we found. ─────
    return {"count": len(custom_results), "results": custom_results}


@router.get("/api/open5e/classes")
def open5e_classes_proxy(
    search: str = "",
    limit: int = 20,
    campaign_id: int | None = None,
    db: Session = Depends(get_db),
):
    from ..open5e_local import is_ready, search_classes, _source
    from .. import local_features
    cap = min(abs(limit), 30)

    # Campaign-scoped homebrew classes prepend the list and shadow any
    # Open5e/mirror entry with the same slug, mirroring the subclass behavior.
    custom_results: list[dict] = []
    custom_slugs: set[str] = set()
    if campaign_id:
        records, _ = local_content.search(
            q=search or "", type="class_features",
            campaign_id=campaign_id, limit=cap,
        )
        for rec in records:
            if rec.get("_source") != "local-homebrew":
                continue
            slug = rec.get("slug")
            custom_results.append({
                "name": rec.get("name"),
                "slug": slug,
                "hit_die": rec.get("hit_die") or 8,
                "source": "Custom",
                "is_custom": True,
            })
            custom_slugs.add(slug)

    # Shipped FS classes sit between campaign homebrew and Open5e — same
    # arrangement as races. If Open5e is unreachable the picker still
    # lists the SRD baseline; if Open5e is reachable the FS entries
    # dedupe out of its results below (detail endpoint resolves to FS
    # regardless).
    fs_results: list[dict] = []
    fs_slugs: set[str] = set()
    needle = (search or "").strip().lower()
    for entry in local_features.list_local_classes():
        slug = entry.get("slug", "")
        if slug in custom_slugs:
            continue
        name = entry.get("name") or slug
        if needle and needle not in name.lower() and needle not in slug.lower():
            continue
        fs_results.append({
            "name": name,
            "slug": slug,
            "hit_die": entry.get("hit_die") or "",
            "source": "SRD",
        })
        fs_slugs.add(slug)

    def _dedupe(results: list[dict]) -> list[dict]:
        skip = custom_slugs | fs_slugs
        return [r for r in results if r.get("slug") not in skip]

    if is_ready():
        items, total = search_classes(q=search, limit=cap)
        rows = [
            {"name": c.get("name", ""), "slug": c.get("slug", ""),
             "hit_die": c.get("hit_die", ""), "source": _source(c)}
            for c in items
        ]
        rows = _dedupe(rows)
        return {
            "count": len(custom_results) + len(fs_results) + total - (len(items) - len(rows)),
            "results": custom_results + fs_results + rows,
        }
    import json as _json, urllib.parse as _urlparse, urllib.request as _urlreq
    url = f"https://api.open5e.com/v1/classes/?{_urlparse.urlencode({'search': search, 'limit': cap})}"
    try:
        req = _urlreq.Request(url, headers={"User-Agent": "SimpleVTT/1.0"})
        with _urlreq.urlopen(req, timeout=8) as r:
            data = _json.loads(r.read())
    except Exception as exc:
        # Open5e unreachable — fall back to homebrew + shipped FS classes.
        if custom_results or fs_results:
            return {
                "count": len(custom_results) + len(fs_results),
                "results": custom_results + fs_results,
            }
        raise HTTPException(502, f"Open5e unavailable: {exc}")
    results = []
    for c in data.get("results", []):
        src = c.get("document__title", "") or (
            c.get("document", {}).get("title", "") if isinstance(c.get("document"), dict) else ""
        )
        results.append({"name": c.get("name", ""), "slug": c.get("slug", ""),
                         "hit_die": c.get("hit_die", ""), "source": src})
    results = _dedupe(results)
    return {
        "count": len(custom_results) + len(fs_results) + data.get("count", 0),
        "results": custom_results + fs_results + results,
    }


