# Keys that route into a specific entry of ``sheet["classes"]`` when the
# caller passes ``class_slug``.  These are the per-class subclass cache keys.
_CLASS_SCOPED_KEYS = {
    "subclass_features_data",
    "subclass_name",
    "subclass_flavor",
    "subclass_features",
    "subclass_choice",
    # v2.99.39 — class level. PATCH with `class_slug` routes the new
    # level into the matching `classes[]` entry; the post-patch
    # `normalize_dnd5e_sheet` call then mirrors it onto the top-level
    # `sheet["level"]`. Without class scoping, a bare top-level PATCH
    # would be silently undone by the next /rest call (which calls
    # normalize and recomputes top-level level from classes[].level).
    "level",
    # v2.99.227 — subclass. Same /rest-undoes-the-PATCH dynamic as
    # `level`: normalize_dnd5e_sheet mirrors classes[0].subclass over
    # the top-level subclass field. With class scoping, the PATCH
    # writes to both classes[] and top-level, so /rest's normalize
    # leaves it alone.
    "subclass",
}


def _apply_sheet_patch(sheet: dict, body: dict) -> dict:
    """Merge whitelisted keys onto a sheet, routing per-class fields into
    the right entry of ``sheet["classes"]`` when ``class_slug`` is supplied."""
    patch = {k: v for k, v in body.items() if k in _SHEET_PATCH_KEYS}
    if not patch:
        return sheet
    cslug = (body.get("class_slug") or "").strip().lower()
    sheet = {**(sheet or {})}
    if cslug:
        # Ensure classes[] exists, then merge per-class keys into the matching entry
        normalize_dnd5e_sheet(sheet)
        classes = list(sheet.get("classes") or [])
        target_idx = next(
            (i for i, c in enumerate(classes)
             if isinstance(c, dict) and _class_slug(c.get("class") or "") == cslug),
            None,
        )
        if target_idx is not None:
            entry = dict(classes[target_idx])
            for k, v in patch.items():
                if k in _CLASS_SCOPED_KEYS:
                    entry[k] = v
            classes[target_idx] = entry
            sheet["classes"] = classes
            # Re-mirror primary onto top-level
            normalize_dnd5e_sheet(sheet)
    # Always merge into top-level too (legacy callers / non-class-scoped keys).
    sheet.update({k: v for k, v in patch.items() if k not in _CLASS_SCOPED_KEYS or not cslug})
    return sheet


@router.get("/api/campaign/{campaign_id}/character/{char_id}/sheet-json")
async def get_character_sheet_json(
    campaign_id: int,
    char_id: int,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.117.0 — read a character's sheet as JSON. The existing
    character GETs render HTML; this returns the raw (dnd5e-normalized)
    sheet dict so tooling can read it without scraping the page —
    notably restore-safe test fixtures that patch a field (resources /
    spells / level) and need to snapshot the original first, plus any
    future client that wants the sheet directly.

    Gated to the GM or the character's owner (mirrors the sheet-fields
    PATCH). Returns ``{ok, character_id, name, template, sheet}``.
    """
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    char = db.query(Character).filter(Character.id == char_id).first()
    if not campaign or not char or char.campaign_id != campaign_id:
        raise HTTPException(404, "Not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Forbidden")
    sheet = dict(char.sheet or {})
    if char.template == "dnd5e":
        normalize_dnd5e_sheet(sheet)
    # v2.159.27 — carrying-capacity Phase 1: bundle the leaf derivations
    # into a top-level `derived` key parallel to `sheet`. RAW PHB p.176:
    # carry capacity = STR × 15 lb. Defensive try/except — a malformed
    # sheet should never block /sheet-json from returning, since many
    # call sites (tests, the sheet UI, the sheet-fields PATCH) depend on
    # this endpoint.
    derived: dict = {}
    if char.template == "dnd5e":
        # v2.212.0 — ability-score override (Belt of Giant Strength etc.,
        # docs/plans/str-override.md). Expose the EFFECTIVE scores for any
        # ability an equipped item sets above its base, and feed the
        # effective STR into the carry-capacity derivation so the meter
        # reflects the boost. Only overridden abilities appear.
        eff_abilities = _effective_abilities_for_sheet(sheet)
        if eff_abilities:
            derived["effective_abilities"] = eff_abilities
        # v2.216.0 — Amulet of Health second-order max-HP effect. Only
        # present when an equipped item overrides CON above its base.
        eff_max_hp = _effective_max_hp_for_sheet(sheet)
        if eff_max_hp:
            derived["effective_max_hp"] = eff_max_hp
        try:
            from ..content.carry_weight import sheet_carry_summary
            _eff_str = effective_ability_score(sheet, "STR")
            derived["carry"] = sheet_carry_summary(sheet, effective_str=_eff_str)
        except Exception:
            pass
        # v2.229.0 — stored-spell capacity (Ioun Stone of Reserve). Only
        # present when an equipped+attuned item carries a reserve buffer.
        try:
            _item_eff = _equipped_item_effects(sheet)
            _reserve = int(_item_eff.get("spell_reserve_levels") or 0)
            if _reserve > 0:
                derived["spell_reserve"] = {
                    "levels": _reserve,
                    "sources": list(_item_eff.get("spell_reserve_sources") or []),
                }
            if _item_eff.get("no_food_or_drink"):
                derived["no_food_or_drink"] = {
                    "sources": list(_item_eff.get("no_food_or_drink_sources") or []),
                }
            if _item_eff.get("cannot_be_surprised"):
                derived["cannot_be_surprised"] = {
                    "sources": list(_item_eff.get("cannot_be_surprised_sources") or []),
                }
            # v2.232.0 — proficiency-bonus override (Ioun Stone of Mastery).
            # Only present when an equipped+attuned item raises PB.
            _pb_bonus = int(_item_eff.get("proficiency_bonus") or 0)
            if _pb_bonus > 0:
                _pb_base = int(sheet.get("proficiency_bonus") or 2)
                derived["proficiency_bonus"] = {
                    "base": _pb_base,
                    "effective": _pb_base + _pb_bonus,
                    "bonus": _pb_bonus,
                    "sources": list(_item_eff.get("proficiency_bonus_sources") or []),
                }
            # v2.233.0 — disease immunity (Periapt of Health). Only present
            # when an equipped item sets the flag.
            if _item_eff.get("disease_immune"):
                derived["disease_immune"] = {
                    "sources": list(_item_eff.get("disease_immune_sources") or []),
                }
            # v2.234.0 — scry proof (Amulet of Proof against Detection).
            # Only present when an equipped+attuned item sets the flag.
            if _item_eff.get("scry_proof"):
                derived["scry_proof"] = {
                    "sources": list(_item_eff.get("scry_proof_sources") or []),
                }
            # v2.235.0 — equipped-item damage resistance (Ring of
            # Resistance). Only present when an equipped+attuned item
            # resists at least one damage type.
            _item_resist_types = list(_item_eff.get("resistance_to") or [])
            if _item_resist_types:
                derived["resistances"] = {
                    "types": _item_resist_types,
                    "sources": list(_item_eff.get("resistance_sources") or []),
                }
            # v2.306.0 — equipped-item damage vulnerability (Armor of
            # Vulnerability). Only present when an equipped+attuned item makes
            # the wearer vulnerable to at least one damage type.
            _item_vuln_types = list(_item_eff.get("vulnerability_to") or [])
            if _item_vuln_types:
                derived["vulnerabilities"] = {
                    "types": _item_vuln_types,
                    "sources": list(_item_eff.get("vulnerability_sources") or []),
                }
            # v2.288.0 — equipped-item damage/condition immunity (Periapt of
            # Proof against Poison). Only present when an equipped(+attuned)
            # item makes at least one damage type / condition immune.
            _item_immune_types = list(_item_eff.get("immunity_to") or [])
            if _item_immune_types:
                derived["immunities"] = {
                    "types": _item_immune_types,
                    "sources": list(_item_eff.get("immunity_sources") or []),
                }
            _item_cond_immune = list(_item_eff.get("condition_immunity_to") or [])
            if _item_cond_immune:
                derived["condition_immunities"] = {
                    "types": _item_cond_immune,
                    "sources": list(_item_eff.get("condition_immunity_sources") or []),
                }
            # v2.236.0 — spell-save advantage (Mantle of Spell Resistance).
            # Only present when an equipped+attuned item sets the flag.
            if _item_eff.get("spell_save_advantage"):
                derived["spell_save_advantage"] = {
                    "sources": list(_item_eff.get("spell_save_advantage_sources") or []),
                }
            # v2.237.0 — spider climb (Slippers of Spider Climbing). Only
            # present when an equipped item sets the flag.
            if _item_eff.get("spider_climb"):
                derived["spider_climb"] = {
                    "sources": list(_item_eff.get("spider_climb_sources") or []),
                }
            # v2.238.0 — flying speed (Winged Boots). Only present when an
            # equipped+attuned item sets the flag.
            if _item_eff.get("flying_speed"):
                derived["flying_speed"] = {
                    "sources": list(_item_eff.get("flying_speed_sources") or []),
                }
            # v2.284.0 — levitate at will (Boots of Levitation). Only present
            # when an equipped+attuned item sets the flag.
            if _item_eff.get("levitate_at_will"):
                derived["levitate_at_will"] = {
                    "sources": list(_item_eff.get("levitate_at_will_sources") or []),
                }
            # v2.239.0 — speed doubling (Boots of Speed). Only present when
            # an equipped+attuned item sets the flag.
            if _item_eff.get("speed_doubling"):
                derived["speed_doubling"] = {
                    "sources": list(_item_eff.get("speed_doubling_sources") or []),
                }
            # v2.240.0 — free action (Ring of Free Action). Only present when
            # an equipped+attuned item sets the flag.
            if _item_eff.get("free_action"):
                derived["free_action"] = {
                    "sources": list(_item_eff.get("free_action_sources") or []),
                }
            # v2.241.0 — water walking (Ring of Water Walking). Only present
            # when an equipped item sets the flag.
            if _item_eff.get("water_walk"):
                derived["water_walk"] = {
                    "sources": list(_item_eff.get("water_walk_sources") or []),
                }
            # v2.256.0 — water breathing (Cap of Water Breathing). Only present
            # when an equipped item sets the flag.
            if _item_eff.get("water_breath"):
                derived["water_breath"] = {
                    "sources": list(_item_eff.get("water_breath_sources") or []),
                }
            # v2.257.0 — x-ray vision (Ring of X-ray Vision). Only present when
            # an equipped + attuned item sets the flag.
            if _item_eff.get("xray_vision"):
                derived["xray_vision"] = {
                    "sources": list(_item_eff.get("xray_vision_sources") or []),
                }
            # v2.258.0 — environment adaptation (Necklace of Adaptation). Only
            # present when an equipped + attuned item sets the flag.
            if _item_eff.get("env_adaptation"):
                derived["env_adaptation"] = {
                    "sources": list(_item_eff.get("env_adaptation_sources") or []),
                }
            # v2.259.0 — climb/swim ease (Gloves of Swimming and Climbing).
            # Only present when an equipped + attuned item sets the flag.
            if _item_eff.get("climb_swim_ease"):
                derived["climb_swim_ease"] = {
                    "sources": list(_item_eff.get("climb_swim_ease_sources") or []),
                }
            # v2.260.0 — jump at will (Ring of Jumping). Only present when an
            # equipped + attuned item sets the flag.
            if _item_eff.get("jump_at_will"):
                derived["jump_at_will"] = {
                    "sources": list(_item_eff.get("jump_at_will_sources") or []),
                }
            # v2.261.0 — ranged bow damage bonus (Bracers of Archery). Only
            # present when an equipped + attuned item carries the bonus.
            if _item_eff.get("ranged_bow_damage_bonus"):
                derived["ranged_bow_damage_bonus"] = {
                    "bonus": int(_item_eff.get("ranged_bow_damage_bonus") or 0),
                    "sources": list(
                        _item_eff.get("ranged_bow_damage_bonus_sources") or []
                    ),
                }
            # v2.265.0 — spell attack bonus (Wand of the War Mage). Only
            # present when an equipped + attuned item carries the bonus.
            if _item_eff.get("spell_attack_bonus"):
                derived["spell_attack_bonus"] = {
                    "bonus": int(_item_eff.get("spell_attack_bonus") or 0),
                    "sources": list(
                        _item_eff.get("spell_attack_bonus_sources") or []
                    ),
                }
            # v2.242.0 — swim speed (Ring of Swimming). Only present when an
            # equipped item sets the flag.
            if _item_eff.get("swim_speed"):
                derived["swim_speed"] = {
                    "sources": list(_item_eff.get("swim_speed_sources") or []),
                }
            # v2.244.0 — feather falling (Ring of Feather Falling). Only
            # present when an equipped + attuned item sets the flag.
            if _item_eff.get("feather_fall"):
                derived["feather_fall"] = {
                    "sources": list(_item_eff.get("feather_fall_sources") or []),
                }
            # v2.245.0 — mind shielding (Ring of Mind Shielding). Only present
            # when an equipped + attuned item sets the flag.
            if _item_eff.get("mind_shield"):
                derived["mind_shield"] = {
                    "sources": list(_item_eff.get("mind_shield_sources") or []),
                }
            # v2.307.0 — telepathy (Helm of Telepathy). Only present when an
            # equipped + attuned item sets the flag.
            if _item_eff.get("telepathy"):
                derived["telepathy"] = {
                    "sources": list(_item_eff.get("telepathy_sources") or []),
                }
            # v2.315.0 — bonus-action-attack (Scimitar of Speed). Only present
            # when an equipped + attuned item sets the flag.
            if _item_eff.get("bonus_action_attack"):
                derived["bonus_action_attack"] = {
                    "sources": list(_item_eff.get("bonus_action_attack_sources") or []),
                }
            # v2.321.0 — disguise-self-at-will (Hat of Disguise). Only present
            # when an equipped + attuned item sets the flag.
            if _item_eff.get("disguise_self_at_will"):
                derived["disguise_self_at_will"] = {
                    "sources": list(_item_eff.get("disguise_self_at_will_sources") or []),
                }
            # v2.246.0 — cold-environment tolerance (Ring of Warmth). Only
            # present when an equipped + attuned item sets the flag. (The ring's
            # cold resistance surfaces in derived.resistances above.)
            if _item_eff.get("cold_tolerance"):
                derived["cold_tolerance"] = {
                    "sources": list(_item_eff.get("cold_tolerance_sources") or []),
                }
            # v2.249.0 — magic-missile immunity (Brooch of Shielding). Present
            # only when an equipped + attuned item sets the flag. (The brooch's
            # force resistance surfaces in derived.resistances above.)
            if _item_eff.get("magic_missile_immune"):
                derived["magic_missile_immune"] = {
                    "sources": list(
                        _item_eff.get("magic_missile_immune_sources") or []
                    ),
                }
            # v2.252.0 — incoming-attack disadvantage (Cloak of Displacement).
            # Display-only mirror; the attack pipeline reads the flag directly
            # via _target_wearer_imposes_attack_disadvantage. Present only when
            # an equipped + attuned item sets the flag.
            if _item_eff.get("incoming_attacks_have_disadvantage"):
                derived["incoming_attacks_have_disadvantage"] = {
                    "sources": list(
                        _item_eff.get(
                            "incoming_attacks_have_disadvantage_sources"
                        ) or []
                    ),
                }
            # v2.253.0 — item-granted check advantage (Cloak of Elvenkind,
            # Phase 4b). Display-only mirror of the `/roll` read: lists the
            # skill keys an equipped + attuned item grants advantage on, with
            # the granting item per skill. Present only when non-empty.
            if _item_eff.get("check_advantage_on"):
                derived["check_advantage_on"] = {
                    "skills": list(_item_eff.get("check_advantage_on") or []),
                    "sources": dict(
                        _item_eff.get("check_advantage_sources") or {}
                    ),
                }
        except Exception:
            pass
    return {
        "ok": True,
        "character_id": char.id,
        "name": char.name,
        "template": char.template,
        "sheet": sheet,
        "derived": derived,
    }


@router.patch("/api/campaign/{campaign_id}/character/{char_id}/sheet-fields")
async def patch_sheet_fields(
    campaign_id: int,
    char_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Merge a small set of pre-approved keys into a character's sheet JSON.

    v2.1.0: when ``hp`` is included in the patch, route through
    ``_apply_hp_change`` so the death save state machine sees the
    transition (e.g. HP dropping to 0 → dying). The optional body field
    ``hp_change_reason`` accepts ``"damage"`` to enable the auto-failure
    tick / massive-damage rule; defaults to a plain set (no damage
    semantics)."""
    body = await request.json()
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    char = db.query(Character).filter(Character.id == char_id).first()
    if not campaign or not char or char.campaign_id != campaign_id:
        raise HTTPException(404, "Not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Forbidden")

    # Extract HP separately so we can route it through the state machine.
    incoming_hp = body.get("hp") if isinstance(body.get("hp"), dict) else None
    body_for_patch = {k: v for k, v in body.items() if k != "hp"}
    char.sheet = _apply_sheet_patch(char.sheet, body_for_patch)

    hp_result = None
    pre_patch_current_hp = None
    if incoming_hp is not None and "current" in incoming_hp:
        # Preserve max/temp by writing them first, then routing current
        # through the state machine.
        sheet = dict(char.sheet or {})
        existing_hp = dict(sheet.get("hp") or {})
        # v2.49.42 — snapshot the pre-patch current HP so we can emit
        # a character_hp_update broadcast with the right delta below.
        pre_patch_current_hp = int(existing_hp.get("current") or 0)
        if "max" in incoming_hp:
            existing_hp["max"] = int(incoming_hp.get("max") or 0)
        if "temp" in incoming_hp:
            existing_hp["temp"] = max(0, int(incoming_hp.get("temp") or 0))
        sheet["hp"] = existing_hp
        char.sheet = sheet

        reason = str(body.get("hp_change_reason") or "set").lower()
        is_damage = reason == "damage"
        is_crit = bool(body.get("is_crit"))
        damage_amount = int(body.get("damage_amount") or 0)

        # v2.20.0 Phase B: resistance. When the caller passes a
        # damage_type AND the target has Rage (or any other buff with
        # ``resistance_to`` containing that type), halve the damage
        # before HP application. The halved value flows into
        # ``_apply_hp_change`` so the death-save state machine + the
        # massive-damage threshold both see the post-resistance number,
        # which matches RAW (resistance applies before HP is dealt).
        # incoming_hp's "current" is the player's pre-resistance new HP;
        # we recompute to keep them in sync.
        damage_type = str(body.get("damage_type") or "").strip().lower()
        resistance_applied = False
        new_hp_current = int(incoming_hp.get("current") or 0)
        if is_damage and damage_amount > 0:
            halved_damage, resistance_applied = _resistance_halve(
                damage_amount, damage_type, char.sheet or {},
            )
            if resistance_applied:
                # Recompute the new HP from the existing current HP -
                # halved damage. We can't just halve the difference
                # because the client may have applied other effects.
                existing_hp_inner = (char.sheet or {}).get("hp") or {}
                old_current = int(existing_hp_inner.get("current") or 0)
                new_hp_current = max(0, old_current - halved_damage)
                damage_amount = halved_damage

        hp_result = _apply_hp_change(
            char,
            new_hp_current,
            is_damage=is_damage,
            is_crit=is_crit,
            damage_amount=damage_amount,
        )

    db.commit()

    # v2.19.1 Phase C.2: if this was damage AND the character is
    # concentrating on a buff, roll a CON save (DC = max(10, damage//2))
    # and drop the buff on fail. Auto-rolled server-side; broadcasts
    # ``concentration_save`` so every client sees the result.
    # v2.19.2 Phase C.3: pass db so the sheet mirror updates on fail.
    if hp_result and is_damage and damage_amount > 0:
        await _maybe_concentration_save(campaign_id, char, damage_amount, db=db)

    if hp_result and hp_result["status_changed"]:
        await hub.broadcast(campaign_id, {
            "type": "character_death_save",
            "data": {
                "character_id": char.id,
                "status": hp_result["death_saves"]["status"],
                "successes": int(hp_result["death_saves"]["successes"]),
                "failures": int(hp_result["death_saves"]["failures"]),
                "hp": hp_result["hp"],
                "source": "sheet_patch",
            },
        })

    # v2.49.42 — also broadcast ``character_hp_update`` whenever HP
    # actually changed, NOT just on status-boundary crossings. Pre-fix:
    # PATCH /sheet-fields fired ``character_death_save`` only when
    # ``hp_result["status_changed"]`` (e.g. crossing into dying / stable
    # / dead), so a vanilla 35→25 HP drop within "alive" went silent —
    # non-GM observers' ``window.battle.combatants[…].hp_current`` stayed
    # at 35 until something else triggered a refresh. The character_hp_
    # update broadcast pattern (no IS_GM guard at tabletop.js:3102, fed
    # by /attack and /cast_spell paths) is the right place to plug this
    # gap — same shape, same client handler. Surfaced by the encounter-
    # sim test_alice_observes_hp_update which had to use /attack instead
    # of PATCH /sheet-fields to get an observable HP change for Alice.
    if hp_result and pre_patch_current_hp is not None:
        new_current = int(hp_result["hp"].get("current") or 0)
        if new_current != pre_patch_current_hp:
            await hub.broadcast(campaign_id, {
                "type": "character_hp_update",
                "data": {
                    "character_id": char.id,
                    "hp": hp_result["hp"],
                    "delta": new_current - pre_patch_current_hp,
                    "source": "sheet_patch",
                },
            })

    return {
        "ok": True,
        "hp": hp_result["hp"] if hp_result else None,
        "death_saves": hp_result["death_saves"] if hp_result else None,
        # v2.20.0 Phase B: signal whether resistance halved the damage
        # before applying. Useful for the player UI to surface a "🛡
        # resisted" toast.
        "resistance_applied": bool(hp_result and resistance_applied) if hp_result else False,
        "damage_amount_after_resistance": damage_amount if hp_result and is_damage else None,
    }


# ----------- API: death saving throws (v2.1.0) -----------

@router.post("/api/campaign/{campaign_id}/character/{char_id}/death-save")
async def roll_death_save(
    campaign_id: int,
    char_id: int,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Roll a death saving throw for a dying character.

    Per RAW: 10+ = success, <10 = failure, nat 20 wakes the character
    with 1 HP, nat 1 counts as two failures, 3 successes → stable,
    3 failures → dead. The roll lands in the campaign roll log so the
    table sees it.
    """
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    char = db.query(Character).filter(Character.id == char_id).first()
    if not campaign or not char or char.campaign_id != campaign_id:
        raise HTTPException(404, "Not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Forbidden")

    ds = dict((char.sheet or {}).get("death_saves") or {})
    status = ds.get("status") or "alive"
    if status != "dying":
        raise HTTPException(409, f"Character is {status}, not dying — cannot roll a death save")

    successes = int(ds.get("successes") or 0)
    failures = int(ds.get("failures") or 0)

    # v2.49.12: route the death-save d20 through the shared seedable
    # dice RNG so encounter-sim tests can make the result deterministic.
    raw = dice_mod.get_rng().randint(1, 20)

    outcome = ""
    regained = False
    if raw == 20:
        outcome = "regain_consciousness"
        regained = True
    elif raw == 1:
        failures += 2
        outcome = "crit_fail"
    elif raw >= 10:
        successes += 1
        outcome = "success"
    else:
        failures += 1
        outcome = "fail"

    if regained:
        # Wake up: HP set to 1, status alive, counters cleared
        hp_result = _apply_hp_change(char, 1)
        new_ds = dict(char.sheet.get("death_saves") or {})
        new_hp = hp_result["hp"]
    else:
        # Threshold checks
        if failures >= 3:
            new_status = "dead"
            successes = 0
            failures = 0
        elif successes >= 3:
            new_status = "stable"
            successes = 0
            failures = 0
        else:
            new_status = "dying"
        _set_death_save_state(char, status=new_status, successes=successes, failures=failures)
        new_ds = dict(char.sheet.get("death_saves") or {})
        new_hp = dict(char.sheet.get("hp") or {})
        # v2.49.49 — when a death save flips status to "dead", drop
        # the caster's concentration. RAW "incapacitated → lose
        # concentration" applies here even though no damage was
        # dealt by the roll itself. The v2.49.48 fix covered the
        # damage-event path; this covers the death-save 3-failures
        # path. ``_drop_caster_concentration`` reuses ``_remove_buff``
        # which fires buff_update + cascades target-side cleanup.
        if new_status == "dead":
            await _drop_caster_concentration(
                campaign_id, char.id,
                reason="3 failed death saves",
            )

    # Persist roll record so the campaign log sees it
    note_label = {
        "success": f"💀 Death Save: SUCCESS ({new_ds.get('successes', 0)}/3)",
        "fail": f"💀 Death Save: FAILURE ({new_ds.get('failures', 0)}/3)",
        "crit_fail": "💀 Death Save: CRITICAL FAILURE (2 failures)",
        "regain_consciousness": "💀 Death Save: NATURAL 20 — regain consciousness!",
    }.get(outcome, "💀 Death Save")
    rec = DiceRoll(
        campaign_id=campaign_id,
        user_id=user.id,
        expression="1d20",
        breakdown=f"1d20[{raw}]={raw}  =>  {raw}",
        total=raw,
        visibility=Visibility.PUBLIC,
        note=note_label[:200],
    )
    db.add(rec)
    db.commit()
    db.refresh(rec)

    # Roller / character info for the broadcast (matches /roll endpoint shape)
    _char_name = char.name
    _portrait_url = char.portrait_url
    _membership = (
        db.query(CampaignMembership)
        .filter(CampaignMembership.campaign_id == campaign_id, CampaignMembership.user_id == user.id)
        .first()
    )
    _player_color = (
        _membership.color if _membership and _membership.color
        else (campaign.gm_color if user.id == campaign.gm_user_id else None)
    )
    _user_color = (char.color if char.color else _player_color)

    await hub.broadcast(campaign_id, {
        "type": "roll",
        "data": {
            "id": rec.id,
            "user_id": user.id,
            "user_name": user.display_name,
            "char_name": _char_name,
            "user_color": _user_color,
            "portrait_url": _portrait_url,
            "expression": rec.expression,
            "breakdown": rec.breakdown,
            "total": rec.total,
            "visibility": rec.visibility.value,
            "note": rec.note,
            "created_at": rec.created_at.isoformat() if rec.created_at else None,
            "kind": "death_save",
            "death_save_outcome": outcome,
        },
    })
    await hub.broadcast(campaign_id, {
        "type": "character_death_save",
        "data": {
            "character_id": char.id,
            "status": new_ds.get("status"),
            "successes": int(new_ds.get("successes") or 0),
            "failures": int(new_ds.get("failures") or 0),
            "hp": new_hp,
            "source": "roll",
            "outcome": outcome,
            "raw": raw,
        },
    })

    return {
        "ok": True,
        "raw": raw,
        "outcome": outcome,
        "status": new_ds.get("status"),
        "successes": int(new_ds.get("successes") or 0),
        "failures": int(new_ds.get("failures") or 0),
        "hp": new_hp,
    }


@router.post("/api/campaign/{campaign_id}/character/{char_id}/death-save/override")
async def override_death_save(
    campaign_id: int,
    char_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """GM-only: manually set a character's death save status and counters.
    Used for narrative beats and misclick recovery. Body: ``{status, successes,
    failures}`` — any field omitted is left alone."""
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    char = db.query(Character).filter(Character.id == char_id).first()
    if not campaign or not char or char.campaign_id != campaign_id:
        raise HTTPException(404, "Not found")
    if not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only")

    body = await request.json()
    status_in = body.get("status")
    if status_in is not None and status_in not in _DEATH_SAVE_STATUSES:
        raise HTTPException(400, f"status must be one of {_DEATH_SAVE_STATUSES}")

    # If transitioning to "alive" from a 0-HP state, bump HP to 1 so the
    # state is internally consistent (alive at 0 HP would immediately fall
    # back to dying on the next state machine pass).
    if status_in == "alive":
        sheet = dict(char.sheet or {})
        hp = dict(sheet.get("hp") or {})
        if int(hp.get("current") or 0) <= 0:
            hp["current"] = 1
            sheet["hp"] = hp
            char.sheet = sheet

    new_ds = _set_death_save_state(
        char,
        status=status_in,
        successes=body.get("successes"),
        failures=body.get("failures"),
    )
    db.commit()

    await hub.broadcast(campaign_id, {
        "type": "character_death_save",
        "data": {
            "character_id": char.id,
            "status": new_ds.get("status"),
            "successes": int(new_ds.get("successes") or 0),
            "failures": int(new_ds.get("failures") or 0),
            "hp": dict(char.sheet.get("hp") or {}),
            "source": "gm_override",
        },
    })

    # v2.49.49 — drop the caster's concentration when GM overrides
    # the status to a non-alive state. RAW "incapacitated → lose
    # concentration" applies regardless of how the PC got there.
    # Override paths covered: dying / stable / dead. Override to
    # "alive" doesn't drop (the PC just woke up). The damage-event
    # path is already covered by v2.49.48; the death-save roll path
    # by the elif above; this is the third / final gap.
    if status_in in ("dying", "stable", "dead"):
        await _drop_caster_concentration(
            campaign_id, char.id,
            reason=f"GM override → {status_in}",
        )

    return {"ok": True, "death_saves": new_ds, "hp": char.sheet.get("hp")}


@router.post("/api/campaign/{campaign_id}/character/{char_id}/stabilize")
async def stabilize_character(
    campaign_id: int,
    char_id: int,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """GM-only: set a dying character to ``stable``. Equivalent to a
    successful DC 10 Medicine check by an ally (auto-resolution of the
    Medicine roll is deferred to a Phase 3 follow-up)."""
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    char = db.query(Character).filter(Character.id == char_id).first()
    if not campaign or not char or char.campaign_id != campaign_id:
        raise HTTPException(404, "Not found")
    if not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only")

    new_ds = _set_death_save_state(char, status="stable", successes=0, failures=0)
    db.commit()

    await hub.broadcast(campaign_id, {
        "type": "character_death_save",
        "data": {
            "character_id": char.id,
            "status": "stable",
            "successes": 0,
            "failures": 0,
            "hp": dict(char.sheet.get("hp") or {}),
            "source": "stabilize",
        },
    })
    return {"ok": True, "death_saves": new_ds}


@router.post("/api/campaign/{campaign_id}/character/{healer_char_id}/medicine_stabilize")
async def medicine_stabilize(
    campaign_id: int,
    healer_char_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.151.0 — Death Saves Phase 3b (Medicine-check stabilize).
    RAW PHB p.197: a healer can stabilize a dying creature with a
    successful DC 10 Wisdom (Medicine) check as an action. This
    endpoint resolves the roll server-side and applies the result.

    Body: ``{target_char_id: int}``. Caller must be the healer
    character's owner OR the GM. Both healer and target must be PCs
    in the same campaign. Target must be in `dying` state. Rolls
    1d20 + WIS mod + (PB if proficient in Medicine) vs DC 10. On
    success, sets target's `death_saves.status = stable` (same as the
    GM-only `/stabilize` endpoint). Broadcasts `character_death_save`
    with `source: "medicine_check"` so the chat-card chrome can
    attribute the stabilize source.

    v1 simplification: no range check between healer and target (RAW
    requires adjacency — GM adjudicates). The Medicine check uses the
    standard skill check pipeline; advantage/disadvantage from the
    healer's `roll_state` rides through naturally.
    """
    body = await request.json()
    try:
        target_char_id = int(body.get("target_char_id") or 0)
    except (TypeError, ValueError):
        target_char_id = 0
    if target_char_id <= 0:
        raise HTTPException(400, "target_char_id is required")

    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign:
        raise HTTPException(404, "Campaign not found")
    healer = db.query(Character).filter(
        Character.id == healer_char_id,
        Character.campaign_id == campaign_id,
    ).first()
    if not healer:
        raise HTTPException(404, "Healer not found")
    if not (_user_is_gm(user, campaign, db) or healer.owner_user_id == user.id):
        raise HTTPException(403, "Not your character")
    target = db.query(Character).filter(
        Character.id == target_char_id,
        Character.campaign_id == campaign_id,
    ).first()
    if not target:
        raise HTTPException(404, "Target not found")
    target_sheet = target.sheet or {}
    target_ds = target_sheet.get("death_saves") or {}
    if (target_ds.get("status") or "alive") != "dying":
        return JSONResponse(status_code=409, content={
            "error": "target_not_dying",
            "target_status": target_ds.get("status") or "alive",
        })

    # Compute the healer's Medicine modifier: WIS mod + (PB if proficient).
    healer_sheet = healer.sheet or {}
    abilities = healer_sheet.get("abilities") or {}
    try:
        wis = int(abilities.get("WIS") or 10)
    except (TypeError, ValueError):
        wis = 10
    wis_mod = (wis - 10) // 2
    pb = int(healer_sheet.get("proficiency_bonus") or 2)
    skills = healer_sheet.get("skills") or {}
    med_entry = skills.get("Medicine") or {}
    is_proficient = bool(med_entry.get("proficient"))
    medicine_mod = wis_mod + (pb if is_proficient else 0)

    # Roll 1d20 + modifier through the existing dice helper.
    mod_str = f"+{medicine_mod}" if medicine_mod >= 0 else str(medicine_mod)
    expr = f"1d20{mod_str}"
    try:
        r = dice_mod.roll(expr)
        roll_total = int(r.total)
        roll_breakdown = r.breakdown
    except dice_mod.DiceParseError:
        roll_total = 0
        roll_breakdown = ""
    dc = 10
    passed = roll_total >= dc

    new_ds = None
    if passed:
        new_ds = _set_death_save_state(
            target, status="stable", successes=0, failures=0,
        )
        db.commit()
        await hub.broadcast(campaign_id, {
            "type": "character_death_save",
            "data": {
                "character_id": target.id,
                "status": "stable",
                "successes": 0,
                "failures": 0,
                "hp": dict(target_sheet.get("hp") or {}),
                "source": "medicine_check",
                "healer_char_id": healer.id,
                "healer_char_name": healer.name,
                "roll_total": roll_total,
                "roll_breakdown": roll_breakdown,
                "dc": dc,
            },
        })
    else:
        await hub.broadcast(campaign_id, {
            "type": "feature_used",
            "data": {
                "source": "medicine_stabilize_failed",
                "character_id": healer.id,
                "character_name": healer.name,
                "feature_name": (
                    f"🩹 Medicine check failed (DC {dc}, rolled "
                    f"{roll_total})"
                ),
                "feature_desc": (
                    f"{healer.name}'s DC {dc} Medicine check to "
                    f"stabilize {target.name} failed (rolled "
                    f"{roll_total}). {target.name} remains dying."
                ),
                "target_char_id": target.id,
                "target_char_name": target.name,
                "roll_total": roll_total,
                "roll_breakdown": roll_breakdown,
                "dc": dc,
            },
        })

    return {
        "ok": True,
        "passed": passed,
        "roll_total": roll_total,
        "roll_breakdown": roll_breakdown,
        "medicine_modifier": medicine_mod,
        "dc": dc,
        "target_char_id": target.id,
        "target_death_saves": new_ds if new_ds is not None else target_ds,
    }


# ----------- API: roll-state toggle (v2.2.0) -----------

@router.post("/api/campaign/{campaign_id}/character/{char_id}/roll-state")
async def set_roll_state(
    campaign_id: int,
    char_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Set or clear a character's roll-state. Body: ``{value: "advantage"
    | "disadvantage" | null}``. While set, single-d20 expressions sent
    through /roll and /attack are auto-upgraded to 2d20kh1 / 2d20kl1
    per the v2.2.0 plan. Manual 2d20kh1 / 2d20kl1 / 1d20a / 1d20d
    submissions remain unchanged and are tagged with "(manual …)" in
    the roll log. Owner or GM only."""
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    char = db.query(Character).filter(Character.id == char_id).first()
    if not campaign or not char or char.campaign_id != campaign_id:
        raise HTTPException(404, "Not found")
    if not (_user_is_gm(user, campaign, db) or char.owner_user_id == user.id):
        raise HTTPException(403, "Forbidden")

    body = await request.json()
    value = body.get("value")
    if value not in ("advantage", "disadvantage", None):
        raise HTTPException(400, "value must be 'advantage', 'disadvantage', or null")

    sheet = dict(char.sheet or {})
    rs = dict(sheet.get("roll_state") or {})
    rs["value"] = value
    sheet["roll_state"] = rs
    char.sheet = sheet
    db.commit()

    await hub.broadcast(campaign_id, {
        "type": "character_roll_state",
        "data": {
            "character_id": char.id,
            "value": value,
        },
    })
    return {"ok": True, "value": value}


# ----------- WebSocket -----------

@router.websocket("/ws/campaign/{campaign_id}")
async def campaign_ws(websocket: WebSocket, campaign_id: int):
    session = websocket.session  # type: ignore[attr-defined]
    user_id = session.get("user_id") if session else None
    if not user_id:
        await websocket.close(code=4401)
        return
    db = SessionLocal()
    # Audio sync: if a track is currently playing for this campaign, the
    # new client gets the audio_play payload sent privately on connect so
    # they sync to the same seek offset everyone else hears. Built here
    # while the DB session is open; sent below after hub.connect accepts
    # the socket. Targeted send (not broadcast) — broadcasting would
    # restart audio for every other client too.
    initial_audio_payload: dict | None = None
    identity: dict | None = None
    try:
        user = db.query(User).filter(User.id == user_id).first()
        campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
        if not user or not campaign or not _user_can_view_campaign(db, user, campaign):
            await websocket.close(code=4403)
            return
        # v2.9.1: build the presence identity here while the DB session
        # is open. Color resolves character.color > membership.color >
        # campaign.gm_color (for the GM); display name is the User's
        # canonical display_name. GM detection uses the same helper as
        # the rest of the auth path.
        membership = (
            db.query(CampaignMembership)
            .filter(CampaignMembership.campaign_id == campaign_id,
                    CampaignMembership.user_id == user.id)
            .first()
        )
        # First character this user owns in this campaign, for color
        # preference. None for the GM (who often owns multiple).
        my_char = (
            db.query(Character)
            .filter(Character.campaign_id == campaign_id,
                    Character.owner_user_id == user.id)
            .first()
        )
        is_gm_user = _user_is_gm(user, campaign, db)
        char_color = my_char.color if my_char and my_char.color else None
        member_color = membership.color if membership and membership.color else None
        gm_color = campaign.gm_color if is_gm_user else None
        identity = {
            "user_id": user.id,
            "display_name": user.display_name,
            "color": char_color or member_color or gm_color,
            "is_gm": is_gm_user,
        }
        if campaign.now_playing_track_id:
            track = (
                db.query(PlaylistTrack)
                .filter(PlaylistTrack.id == campaign.now_playing_track_id)
                .first()
            )
            if track:
                from .audio_routes import _now_playing_payload
                initial_audio_payload = {
                    "type": "audio_play",
                    "data": _now_playing_payload(campaign, track),
                }
    finally:
        db.close()

    await hub.connect(campaign_id, websocket, identity=identity)

    if initial_audio_payload is not None:
        import json as _json
        try:
            await websocket.send_text(_json.dumps(initial_audio_payload, default=str))
        except Exception as exc:
            log.warning("audio sync send failed for campaign %s: %s", campaign_id, exc)

    try:
        while True:
            await websocket.receive_text()
    except WebSocketDisconnect:
        pass
    except Exception as e:
        log.warning("ws error: %s", e)
    finally:
        await hub.disconnect(campaign_id, websocket)


# ----------- Player character roster + standalone sheet -----------

@router.get("/campaign/{campaign_id}/characters", response_class=HTMLResponse)
def player_characters(
    campaign_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Character roster — accessible without an active session."""
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign:
        raise HTTPException(404, "Campaign not found")
    if not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    is_gm = _user_is_gm(user, campaign, db)
    if is_gm:
        characters = (
            db.query(Character)
            .filter(Character.campaign_id == campaign_id)
            .order_by(Character.name)
            .all()
        )
    else:
        characters = (
            db.query(Character)
            .filter(
                Character.campaign_id == campaign_id,
                Character.owner_user_id == user.id,
            )
            .order_by(Character.name)
            .all()
        )
    # Build owner name map for GM view
    owner_names: dict[int, str] = {}
    if is_gm:
        owner_ids = {c.owner_user_id for c in characters if c.owner_user_id}
        if owner_ids:
            for u in db.query(User).filter(User.id.in_(owner_ids)).all():
                owner_names[u.id] = u.display_name
    return templates.TemplateResponse(
        "my_characters.html",
        {
            "request": request,
            "user": user,
            "campaign": campaign,
            "characters": characters,
            "is_gm": is_gm,
            "owner_names": owner_names,
            "system": get_system(campaign.game_system),
        },
    )


@router.get("/campaign/{campaign_id}/character/{char_id}/sheet", response_class=HTMLResponse)
def character_sheet_page(
    campaign_id: int,
    char_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """Standalone full-page character sheet — no active session required."""
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    char = db.query(Character).filter(Character.id == char_id).first()
    if not campaign or not char or char.campaign_id != campaign_id:
        raise HTTPException(404, "Not found")
    if not _user_can_view_campaign(db, user, campaign):
        raise HTTPException(403, "Not a member")
    is_gm = _user_is_gm(user, campaign, db)
    can_edit = is_gm or char.owner_user_id == user.id
    sheet_template = "sheet_dnd5e.html" if char.template == "dnd5e" else "sheet_generic.html"
    page_sheet = char.sheet or get_template(char.template)
    if char.template == "dnd5e":
        normalize_dnd5e_sheet(page_sheet)
    return templates.TemplateResponse(
        "character_page.html",
        {
            "request": request,
            "user": user,
            "campaign": campaign,
            "char": char,
            "sheet": page_sheet,
            "can_edit": can_edit,
            "is_gm": is_gm,
            "sheet_template": sheet_template,
            "system": get_system(campaign.game_system),
            "class_roster": class_levels_summary(page_sheet) if char.template == "dnd5e" else [],
            "effective_abilities": (
                _effective_abilities_for_sheet(page_sheet)
                if char.template == "dnd5e" else {}
            ),
            "movement_traits": (
                _movement_traits_for_sheet(page_sheet)
                if char.template == "dnd5e" else []
            ),
            "animate_gifs": user.animate_gifs,
        },
    )


# ----------- Monster sheet (v2.3.10) -----------
# Reuse sheet_dnd5e.html for monsters by projecting a TokenTemplate (stat
# block + structured actions) into the same context shape the character
# sheet expects. Gives GMs PC-parity click-to-roll for ability checks,
# saves, skills, and structured attacks without rebuilding a parallel UI.
# See docs in monster_page.html + the adapter below.


class _SyntheticMonsterChar:
    """Stand-in for a ``Character`` ORM object so ``sheet_dnd5e.html`` (and
    its wrapper ``monster_page.html``) can render a monster's stat block
    without needing a DB-backed Character row. Only the attributes the
    template actually reads need to exist — see the template scan in
    docs/plans/monster-sheet.md (when written) or grep ``char\\.`` in
    ``app/templates/sheet_dnd5e.html`` to confirm the surface.

    Intentionally NOT a SQLAlchemy model: the monster lives in
    ``TokenTemplate`` (and optionally a homebrew JSON file), not in
    ``characters``. Saving to the character API would 404, so the
    monster sheet renders with ``can_edit=False`` and the form's
    data-readonly flag suppresses save buttons.
    """

    __slots__ = (
        "id", "name", "sheet", "template", "owner_user_id", "campaign_id",
        "color", "portrait_url", "ring_style", "template_id",
    )

    def __init__(
        self,
        *,
        id,
        name: str,
        sheet: dict,
        template: str = "dnd5e",
        owner_user_id: int = 0,
        campaign_id: int = 0,
        color: Optional[str] = None,
        portrait_url: Optional[str] = None,
        ring_style: Optional[str] = None,
        template_id: Optional[int] = None,
    ) -> None:
        # ``id`` may be a numeric TokenTemplate primary key (used by the
        # 2.3.10 standalone monster sheet route) or a string like
        # ``"monster-22"`` (used by the 2.3.17 mini-sheet pool, where DOM
        # ids need to NOT collide with real Character primary keys). The
        # partial stamps it into ``id=`` / ``data-char-id=`` attributes
        # directly; downstream JS parses or branches as needed.
        self.id = id
        self.name = name
        self.sheet = sheet
        self.template = template
        self.owner_user_id = owner_user_id
        self.campaign_id = campaign_id
        self.color = color or "#888"
        self.portrait_url = portrait_url
        self.ring_style = ring_style or "solid"
        # ``template_id``: the underlying TokenTemplate primary key as an
        # int, even when ``id`` is the string form. The mini-sheet partial
        # uses this to build the ``/monster-template/{tid}/sheet`` URL
        # for the "Open full sheet" link without needing to parse the
        # ``"monster-N"`` prefix off ``id``.
        self.template_id = template_id


def _monster_dict_to_sheet(m: dict, *, base: Optional[dict] = None) -> dict:
    """Project a Monster Pydantic dict (loaded by ``local_content.resolve``
    from ``app/data/local/dnd5e/monsters/*.json`` or a homebrew JSON file)
    into the sheet dict shape ``sheet_dnd5e.html`` consumes.

    ``base`` is the TokenTemplate's existing sheet — any keys it carries
    that we don't compute here (notes, custom overrides, etc.) pass
    through unchanged. Anything we compute (HP, AC, abilities, speed,
    race header, damage lists, actions) overrides the base.
    """
    import re as _re
    out = dict(base or {})
    hp = int(m.get("hit_points") or 10)
    out["hp"] = {"current": hp, "max": hp, "temp": 0}
    out["ac"] = int(m.get("armor_class") or 10)
    speed_raw = m.get("speed") or {}
    if isinstance(speed_raw, dict):
        walk = speed_raw.get("walk") or 30
        out["speed"] = int(walk) if str(walk).isdigit() else 30
    else:
        digits = _re.search(r"\d+", str(speed_raw))
        out["speed"] = int(digits.group()) if digits else 30
    out["abilities"] = {
        "STR": int(m.get("strength") or 10),
        "DEX": int(m.get("dexterity") or 10),
        "CON": int(m.get("constitution") or 10),
        "INT": int(m.get("intelligence") or 10),
        "WIS": int(m.get("wisdom") or 10),
        "CHA": int(m.get("charisma") or 10),
    }
    size = (m.get("size") or "").strip()
    type_ = (m.get("type") or "").strip()
    header_bits = " ".join(b for b in (size, type_) if b)
    if header_bits:
        out["race"] = header_bits
    if m.get("alignment"):
        out["background"] = m.get("alignment")
    for key in ("damage_resistances", "damage_immunities",
                "damage_vulnerabilities", "condition_immunities"):
        raw = m.get(key)
        if isinstance(raw, str) and raw.strip():
            out[key] = [p.strip() for p in _re.split(r"[,;]", raw) if p.strip()]
        elif isinstance(raw, list):
            out[key] = [str(p) for p in raw]
    # Pass the structured actions through so the caller's fold step picks
    # them up. Caller handles attack-button projection.
    if m.get("actions"):
        out["actions"] = m.get("actions")
    # v2.165.0 Phase 2a — derive the per-day legendary-resistance count
    # from the "Legendary Resistance (N/Day)" special ability (RAW MM
    # p.11) so the Phase 2 resistance pool can seed from the stat block
    # without editing every monster JSON. One code path covers all 15
    # SRD legendary monsters + any homebrew carrying the special ability.
    lr_per_day = 0
    for a in (m.get("actions") or []):
        if not isinstance(a, dict):
            continue
        nm = str(a.get("name") or "")
        if "legendary resistance" in nm.lower():
            mm = _re.search(r"\((\d+)\s*/\s*day\)", nm, _re.I)
            if mm:
                lr_per_day = int(mm.group(1))
            break
    if lr_per_day:
        out["legendary_resistance_per_day"] = lr_per_day
    # v2.168.0 Phase 3a — fold curated lair actions (RAW per-monster
    # "Lair Actions" sidebar) onto the projected sheet, keyed by slug.
    # The SRD content build doesn't carry a lair-action block, so these
    # are hand-authored in app/content/lair_actions.py. Only a handful
    # of legendary creatures have a lair, so this is a no-op for almost
    # every monster. The initiative-20 lair-action scheduler (Phase 3b)
    # reads sheet["lair_actions"] directly.
    lair = _lair_actions_for_slug(m.get("slug"))
    if lair:
        out["lair_actions"] = lair
    reg = _regional_effects_for_slug(m.get("slug"))
    if reg:
        out["regional_effects"] = reg
    return out


# v2.49.181: spellcasting-ability lookup by class slug. Used by
# _enrich_pc_spell_from_catalog to compute the per-spell attack_bonus
# and save_dc (= 8 + mod + prof for save spells, = mod + prof for
# attack-roll spells). Subclass entries (Eldritch Knight, Arcane
# Trickster) get their own ability because they use INT regardless
# of the parent Fighter/Rogue class.
_SPELLCASTING_ABILITY_BY_CLASS = {
    "wizard": "INT",
    "cleric": "WIS",
    "druid": "WIS",
    "ranger": "WIS",
    "sorcerer": "CHA",
    "warlock": "CHA",
    "bard": "CHA",
    "paladin": "CHA",
    "artificer": "INT",
    "eldritch-knight": "INT",
    "arcane-trickster": "INT",
}


def _enrich_pc_spell_from_catalog(
    spell: dict,
    campaign_id: int,
    sheet: dict | None = None,
) -> dict:
    """v2.49.180: PC spell entries on the demo sheet carry only
    ``{name, level, _slug, casting_time}`` — no damage / range /
    save_ability / attack_roll. The mini-sheet + full-sheet spell
    rows render compact chips for those fields when present
    (v2.49.177-179), so without enrichment the rows render bare.

    This helper merges the catalog spell's top-level fields (range,
    school, duration, components, desc, concentration, ritual) AND
    its ``actions[0]`` mechanical fields (damage, damage_type,
    attack_roll, save_ability, aoe_targets, area) into the spell
    entry using ``setdefault`` — sheet-side overrides (homebrew,
    partial customization, the v2.46.0 Lightning Bolt inline data)
    take precedence over the catalog.

    v2.49.181: when ``sheet`` is provided, also computes the caster-
    dependent ``attack_bonus`` (mod + prof) and ``save_dc`` (8 + mod
    + prof). Uses the spell's tagged ``class`` slug (or the sheet's
    primary class as fallback) to pick the spellcasting ability
    (Wizard→INT, Cleric→WIS, Sorcerer→CHA, etc.), reads that
    ability's score from ``sheet["abilities"]``, and computes the
    standard 5e modifier ``floor((score - 10) / 2)``. The
    proficiency bonus is read from ``sheet["proficiency_bonus"]``
    (default 2).

    Returns the enriched spell dict (or the original if no _slug or
    no catalog hit).
    """
    slug = (spell.get("_slug") or "").strip().lower()
    if not slug:
        return spell
    hit = local_content.resolve(slug, type="spells", campaign_id=campaign_id)
    if not hit:
        return spell
    srd_rec, _src = hit
    out = dict(spell)
    # Top-level catalog fields the spell row chips read.
    for key in (
        "range", "school", "duration", "components", "desc",
        "concentration", "ritual", "casting_time",
    ):
        if srd_rec.get(key) is not None:
            out.setdefault(key, srd_rec[key])
    # Mechanical fields from actions[0] (damage, type, attack/save).
    spell_actions = srd_rec.get("actions") or []
    if spell_actions and isinstance(spell_actions[0], dict):
        sa = spell_actions[0]
        for key in (
            "damage", "damage_type", "damage_scaling",
            "attack_roll", "save_ability",
            "aoe_targets", "area",
        ):
            if sa.get(key) not in (None, "", 0, []):
                out.setdefault(key, sa[key])
    # v2.49.181: caster-dependent attack_bonus + save_dc. Requires the
    # character sheet so we can read the spellcasting ability score +
    # proficiency bonus.
    if sheet:
        # Pick the casting class. Prefer the spell's tagged class
        # (multi-class characters have spells from multiple classes);
        # fall back to the sheet's primary single-class.
        spell_class = (out.get("class") or "").strip().lower()
        if not spell_class:
            spell_class = (sheet.get("class") or "").strip().lower()
        # Normalize spaces and slug-ify (e.g., "Eldritch Knight" →
        # "eldritch-knight" so subclass entries match the map).
        spell_class_slug = spell_class.replace(" ", "-")
        ability = _SPELLCASTING_ABILITY_BY_CLASS.get(spell_class_slug)
        if ability:
            abilities = sheet.get("abilities") or {}
            try:
                score = int(abilities.get(ability) or abilities.get(ability.lower()) or 10)
            except (TypeError, ValueError):
                score = 10
            mod = (score - 10) // 2
            try:
                prof = int(sheet.get("proficiency_bonus") or 2)
            except (TypeError, ValueError):
                prof = 2
            # Spell attack bonus = mod + prof; save DC = 8 + mod +
            # prof. Both stored with the same setdefault convention so
            # inline overrides (Lightning Bolt etc.) still win.
            atk = mod + prof
            dc = 8 + mod + prof
            if out.get("attack_roll") and not out.get("attack_bonus") and not out.get("atk_bonus"):
                out["attack_bonus"] = ("+" if atk >= 0 else "") + str(atk)
            if out.get("save_ability") and not out.get("save_dc"):
                out["save_dc"] = dc
    return out


def _resolve_spell_slug_action(action: dict, campaign_id: int) -> dict:
    """v2.49.174: merge a monster action with its referenced spell
    catalog entry when the action carries a ``spell_slug``.

    The spell catalog (``app/data/local/dnd5e/spells/*.json``) is the
    source of truth for spell mechanics (damage, type, attack-roll vs
    save, AoE shape, range, scaling). NPC actions can reference a
    spell by slug — e.g., ``{"spell_slug": "inflict-wounds",
    "attack_bonus": "+4", "save_dc": 13, "charges_max": 2}`` — and
    this helper resolves the slug, then merges the spell action's
    fields into the monster action. Monster-specific fields (name,
    id, charges_max, attack_bonus, save_dc, category, custom desc)
    override the catalog defaults.

    Returns the merged action dict (or the original if no spell_slug
    or the slug doesn't resolve).
    """
    if not isinstance(action, dict):
        return action
    slug = action.get("spell_slug")
    if not slug:
        return action
    resolved = local_content.resolve(
        str(slug).strip(), type="spells", campaign_id=campaign_id,
    )
    if not resolved:
        return action
    spell_dict, _src = resolved
    spell_actions = spell_dict.get("actions") or []
    if not spell_actions:
        return action
    spell_action = spell_actions[0]
    spell_range = spell_dict.get("range", "")
    # Build the merged action. Start with spell catalog defaults, then
    # overlay the monster's overrides on top — empty / None monster
    # values fall through to the spell catalog so the catalog wins
    # for fields the NPC didn't override.
    merged = dict(action)
    catalog_defaults = {
        "damage": spell_action.get("damage", ""),
        "damage_type": spell_action.get("damage_type", ""),
        "damage_scaling": spell_action.get("damage_scaling") or [],
        "attack_roll": bool(spell_action.get("attack_roll")),
        "save_ability": (spell_action.get("save_ability") or "").lower(),
        "area": spell_action.get("area") or {},
        "aoe_targets": spell_action.get("aoe_targets") or 1,
        "range": spell_range or "",
        # Append spell's short desc if the monster doesn't provide one.
        "desc": spell_dict.get("desc", ""),
        # v2.49.206: spell-level metadata needed by the unified mini-sheet
        # partial's Spells tab (_tab_spells.html). The PC spell shape that
        # _tab_spells.html consumes reads level / casting_time /
        # concentration / ritual / duration / components from the spell
        # dict; without these the partial can't render the NPC spell row
        # at the right level header (cantrips vs leveled) or emit the
        # ⏱ Concentration / ® Ritual sigils.
        "level": int(spell_dict.get("level") or 0),
        "casting_time": spell_dict.get("casting_time", ""),
        "concentration": bool(spell_dict.get("concentration")),
        "ritual": bool(spell_dict.get("ritual")),
        "duration": spell_dict.get("duration", ""),
        "components": spell_dict.get("components", ""),
    }
    for k, v in catalog_defaults.items():
        cur = merged.get(k)
        # Empty cur (None / "" / 0 / []) → inherit from catalog.
        is_empty = cur is None or cur == "" or cur == 0 or cur == []
        # v2.49.218: dicts stored with all-falsy values also count as
        # absent. The homebrew Action Pydantic model defaults
        # ``area`` to ``{"shape": "", "size_ft": 0, "secondary_ft": 0}``
        # (explicit-present rather than None / missing) — without this
        # guard the catalog's area overlay silently skipped for every
        # spell_slug action stored through the homebrew editor. The
        # symptom: Soren's Burning Hands had `area: {"shape": ""}` in
        # the projected sheet, the `.mini-cast-btn` `data-spell-area-
        # shape` attr was empty, the client's AoE picker branch never
        # fired, and the GM got the single-target picker instead of the
        # cone interface. Same shape stripping that bit v2.49.176
        # (Pydantic stripping spell_slug). Generic enough to apply to
        # any dict-typed overlay value going forward.
        if not is_empty and isinstance(cur, dict):
            is_empty = not any(cur.values())
        if is_empty:
            merged[k] = v
    return merged


def _monster_template_to_sheet(tmpl: TokenTemplate, campaign_id: int) -> dict:
    """Project a monster TokenTemplate's stat block + structured actions
    into the dict shape that ``sheet_dnd5e.html`` consumes.

    Source resolution order:

    1. ``tmpl.sheet["monster_slug"]`` — if the template is a pointer to a
       shipped or homebrew monster (the minimal demo NPC seed shape — see
       ``app/demo_seed.py _npc_sheet``), resolve via ``local_content`` and
       overlay the full stat block. The pointer pattern keeps the
       TokenTemplate rows tiny and the stat-block authoring in one place.

    2. ``tmpl.sheet["actions"]`` (homebrew structured Action shape from the
       v2.3.8 editor) and/or ``tmpl.sheet["attacks"]`` (legacy regex-
       derived character schema from SRD imports via
       ``_open5e_to_dnd5e_sheet``). The former gets folded into the latter
       so the character template, which reads ``sheet.attacks``, sees a
       unified list. De-duped by name so a homebrew override shadows an
       SRD-imported same-name attack.

    For SRD monsters where the Action's ``attack_bonus`` is null (shipped
    files describe the to-hit only in the desc text), the projection regex-
    extracts ``+N to hit`` from the desc so the attack button rolls
    ``1d20+N`` instead of a raw 1d20.
    """
    import re as _re

    sheet = dict(tmpl.sheet or {})
    monster_slug = sheet.get("monster_slug")
    if monster_slug:
        resolved = local_content.resolve(
            str(monster_slug), type="monsters", campaign_id=campaign_id,
        )
        if resolved is not None:
            monster_dict, _src = resolved
            sheet = _monster_dict_to_sheet(monster_dict, base=sheet)

    actions = sheet.get("actions") or []
    if not actions:
        return sheet

    # v2.49.174: NPC actions can reference the shared spell catalog
    # via ``spell_slug``. Resolve and merge here so downstream
    # consumers (action button stamping, /npc_attack request builder)
    # see the fully-expanded action — damage / damage_type /
    # damage_scaling / attack_roll / save_ability / area / aoe_targets /
    # range / desc inherited from the spell catalog entry; monster-
    # specific fields (id, name, charges_max, attack_bonus, save_dc,
    # category) override. This means a monster's "Inflict Wounds"
    # action is THE SAME spell as the cleric's — update the spell
    # JSON once, both casters get the change.
    actions = [_resolve_spell_slug_action(a, campaign_id) for a in actions]
    sheet["actions"] = actions

    existing_attacks = list(sheet.get("attacks") or [])
    by_name = {
        (a.get("name") or "").strip().lower(): i
        for i, a in enumerate(existing_attacks)
        if isinstance(a, dict)
    }

    for a in actions:
        if not isinstance(a, dict):
            continue
        if not (a.get("attack_roll") or a.get("damage") or a.get("save_ability")):
            continue
        # v2.49.208: skip spell-slug actions when folding into sh["attacks"].
        # The v2.49.206 spells projection below puts them into sh["spells"]
        # (the unified mini-sheet partial's Spells tab); folding them ALSO
        # into sh["attacks"] makes the partial's Actions tab render a 🗡 Strike
        # button for the same spell that already has a ✨ Cast button in the
        # Spells tab — Sacred Flame appearing twice on Soren the Cult Acolyte
        # was the user-reported v2.49.206 dup. Spells belong in the Spells
        # tab; non-spell actions (weapon attacks, Multiattack, special
        # abilities) keep folding into attacks unchanged.
        if a.get("spell_slug"):
            continue
        name = (a.get("name") or "Action").strip()
        save_ability_raw = (a.get("save_ability") or "").strip().upper()
        atk_bonus = a.get("attack_bonus") or ""
        # SRD fallback: shipped monsters set attack_roll=true but leave
        # attack_bonus null — the to-hit lives in the desc text. Regex it
        # out so the attack button does ``1d20+N`` instead of raw 1d20.
        if a.get("attack_roll") and not atk_bonus:
            bonus_m = _re.search(r"([+-]\d+)\s*to hit", a.get("desc") or "")
            if bonus_m:
                atk_bonus = bonus_m.group(1)
        atk_entry = {
            # v2.3.40: pass through the structured Action's ``id`` so the
            # client can key per-combatant charge state (combatant.
            # action_charges[action_id]) and ``charges_max`` so the init-
            # tracker view can render the N/M counter + disable buttons
            # when the action is spent.
            "id": a.get("id") or name.lower().replace(" ", "-"),
            "name": name,
            "atk_bonus": atk_bonus,
            "damage": a.get("damage") or "",
            "damage_type": a.get("damage_type") or "",
            "save_dc": (a.get("save_dc") or None) if a.get("save_dc") else None,
            "save_ability": save_ability_raw or None,
            "charges_max": int(a.get("charges_max") or 0),
            "description": a.get("desc") or "",
        }
        key = name.lower()
        if key in by_name:
            existing_attacks[by_name[key]] = atk_entry
        else:
            existing_attacks.append(atk_entry)
            by_name[key] = len(existing_attacks) - 1

    sheet["attacks"] = existing_attacks

    # v2.49.206: also project spell_slug actions into sh["spells"] so the
    # unified mini-sheet partial (_tab_spells.html) renders an NPC Spells
    # tab. The partial gates the tab on `_is_caster and _spell_vis.any`,
    # which both depend on `spells_list = sh.get("spells")`. Pre-fix, NPC
    # actions with spell_slug ended up only in sh["attacks"] — the
    # buildMonsterInitSheet path used to filter those into a separate
    # spells panel client-side; the v2.5b unified partial reads sh["spells"]
    # directly. Each entry mirrors the PC spell shape so the partial's
    # row template (✨ name + range / atk / dmg / save chips, ⏱ / ®
    # sigils, expandable detail) renders identically across PC + NPC.
    # The `class` field is intentionally empty: monsters don't have a
    # class hierarchy; the partial's empty-_iter_classes fallback
    # (also v2.49.206) handles this case by synthesizing a single
    # empty-slug iteration entry so the spell rows match.
    existing_spells = sheet.get("spells") or []
    if not existing_spells:
        spells_proj = []
        for a in actions:
            if not isinstance(a, dict):
                continue
            slug = a.get("spell_slug")
            if not slug:
                continue
            spells_proj.append({
                "name": a.get("name") or str(slug).replace("-", " ").title(),
                "level": int(a.get("level") or 0),
                "class": "",
                "range": a.get("range", ""),
                "damage": a.get("damage", ""),
                "damage_type": a.get("damage_type", ""),
                "save_ability": a.get("save_ability", ""),
                "save_dc": a.get("save_dc") or None,
                "attack_roll": bool(a.get("attack_roll")),
                "attack_bonus": a.get("attack_bonus", ""),
                "concentration": bool(a.get("concentration")),
                "ritual": bool(a.get("ritual")),
                "casting_time": a.get("casting_time", ""),
                "duration": a.get("duration", ""),
                "components": a.get("components", ""),
                "desc": a.get("desc", ""),
                "_slug": str(slug),
                # v2.49.217: area shape + size so the unified mini-sheet's
                # cast handler can route through _openAoePicker for AoE
                # spells (Burning Hands cone, Fireball sphere, etc.).
                "area": a.get("area") or {},
                "aoe_targets": int(a.get("aoe_targets") or 1),
                # v2.49.220 action_charges migration: per-action id + max
                # charges so the unified partial can render the
                # 2/2 ↻ counter + spent-disabled state for limited-use
                # spells (Inflict Wounds N/day, Frightful Howl 1/day, etc).
                # The per-combatant current count lives in
                # battle.combatants[i].action_charges[id] client-side;
                # the hydration patches the counter text + spent class
                # from there. Pre-v2.49.220 these fields weren't in the
                # spells projection — buildMonsterInitSheet read them
                # directly from sh.actions; the unified partial path
                # needs them on the spell row too.
                "id": a.get("id") or str(slug),
                "charges_max": int(a.get("charges_max") or 0),
            })
        if spells_proj:
            sheet["spells"] = spells_proj

    return sheet


@router.get(
    "/campaign/{campaign_id}/monster-template/{template_id}/sheet",
    response_class=HTMLResponse,
)
def monster_template_sheet_page(
    campaign_id: int,
    template_id: int,
    request: Request,
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    """v2.3.10: full sheet view for a monster ``TokenTemplate``, reusing
    ``sheet_dnd5e.html`` so the GM gets PC-parity click-to-roll for
    ability checks, saves, skills, and structured attacks.

    GM-only because monsters are GM-visibility data in this codebase.
    Read-only — ``can_edit=False`` makes the sheet's form render with
    ``data-readonly="1"``, which the sheet JS uses to suppress save
    buttons. The form fields stay populated though, because
    ``wireDnd5eRollButtons`` reads ability/skill/save state via
    ``form.querySelector('[name="..."]').value``.
    """
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign:
        raise HTTPException(404, "Campaign not found")
    if not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only")
    tmpl = (
        db.query(TokenTemplate)
        .filter(TokenTemplate.id == template_id,
                TokenTemplate.campaign_id == campaign_id)
        .first()
    )
    if not tmpl:
        raise HTTPException(404, "Monster template not found")

    sheet = _monster_template_to_sheet(tmpl, campaign_id)
    if (tmpl.template or "dnd5e") == "dnd5e":
        normalize_dnd5e_sheet(sheet)
    # v2.49.3 — overlay live combatant HP onto the template's static
    # max when the GM opens the sheet for a specific instance in
    # init. Without this the sheet keeps reading the template's
    # default HP even after the bandit took 22 fire damage from a
    # Fireball. The query string ``?combatant_id=tok_xyz`` (or
    # ``?combatant_id=tok:14``) selects which instance to show; the
    # init tracker's "📋 Sheet" link sets it automatically.
    combatant_id_q = (request.query_params.get("combatant_id") or "").strip()
    if combatant_id_q:
        battle_state = hub.get_battle(campaign_id)
        if battle_state:
            for c in (battle_state.get("combatants") or []):
                if c.get("id") == combatant_id_q:
                    hp = dict(sheet.get("hp") or {})
                    hp_cur = int(c.get("hp_current") or 0)
                    hp_max_state = int(c.get("hp_max") or hp.get("max") or hp_cur)
                    hp["current"] = hp_cur
                    hp["max"] = hp_max_state
                    sheet["hp"] = hp
                    break
    sheet_template = (
        "sheet_dnd5e.html"
        if (tmpl.template or "dnd5e") == "dnd5e"
        else "sheet_generic.html"
    )
    # v2.3.42: surface the homebrew slug to the template so it can render
    # an "✏️ Edit" link in the breadcrumb that bounces the GM to the
    # campaign-settings homebrew editor (anchored to the right entry).
    # Only set when (a) the TokenTemplate points to a slug via
    # ``sheet.monster_slug`` AND (b) the resolver tags the source as
    # ``local-homebrew`` (not shipped SRD, not Open5e cache) — editing
    # SRD content through the homebrew editor would silently fork it,
    # which is what the existing "📋 Clone" button already does
    # explicitly. ``raw_sheet`` reads the original sheet because
    # ``_monster_template_to_sheet`` overlays the resolved monster onto
    # ``sheet`` and the slug pointer survives the overlay too, but
    # reading from the original keeps the intent obvious.
    edit_homebrew_slug: Optional[str] = None
    raw_sheet = tmpl.sheet or {}
    raw_slug = raw_sheet.get("monster_slug")
    if raw_slug:
        resolved = local_content.resolve(
            str(raw_slug), type="monsters", campaign_id=campaign_id,
        )
        if resolved is not None and resolved[1] == "local-homebrew":
            edit_homebrew_slug = str(raw_slug)
    synthetic = _SyntheticMonsterChar(
        id=template_id,
        name=tmpl.name or "Monster",
        sheet=sheet,
        template=tmpl.template or "dnd5e",
        owner_user_id=0,
        campaign_id=campaign_id,
        portrait_url=tmpl.image_url,
    )
    return templates.TemplateResponse(
        "monster_page.html",
        {
            "request": request,
            "user": user,
            "campaign": campaign,
            "char": synthetic,
            "sheet": sheet,
            "can_edit": False,
            "is_gm": True,
            "sheet_template": sheet_template,
            "system": get_system(campaign.game_system),
            "class_roster": [],
            "animate_gifs": user.animate_gifs,
            # v2.3.13: lets sheet_dnd5e.html hide PC-only sections
            # (spells, inventory, class/subclass/race features, class
            # resources, notes) that have no meaning for a monster.
            "is_monster_sheet": True,
            # v2.3.42: homebrew slug for the "✏️ Edit" breadcrumb link;
            # None for SRD / Open5e monsters or templates without a
            # monster_slug pointer (those use Clone-then-edit flow).
            "edit_homebrew_slug": edit_homebrew_slug,
        },
    )


# ----------- Settings: characters (GM) -----------

_SETTINGS_UPLOAD_ROOT = Path(__file__).resolve().parent.parent / "static" / "uploads"
_MAP_DIR = _SETTINGS_UPLOAD_ROOT / "maps"
_ALLOWED_IMG = {"image/png", "image/jpeg", "image/webp", "image/gif", "video/webm", "video/mp4"}


def _make_map_thumbnail(data: bytes, content_type: str, map_dir: Path, stem: str) -> Optional[str]:
    """Return a static JPEG thumbnail URL for GIFs (frame 0) and videos (ffmpeg).
    Returns None for static images — callers fall back to image_url."""
    if content_type == "image/gif":
        try:
            import io as _io
            from PIL import Image as _PIL
            with _PIL.open(_io.BytesIO(data)) as im:
                im.seek(0)
                frame = im.convert("RGB")
                thumb_name = stem + "_thumb.jpg"
                frame.save(str(map_dir / thumb_name), "JPEG", quality=80)
                return f"/static/uploads/maps/{thumb_name}"
        except Exception:
            return None
    if content_type in ("video/mp4", "video/webm"):
        try:
            import subprocess, tempfile, os as _os
            thumb_name = stem + "_thumb.jpg"
            thumb_path = map_dir / thumb_name
            with tempfile.NamedTemporaryFile(suffix=".tmp", delete=False) as tf:
                tf.write(data)
                tf_path = tf.name
            try:
                subprocess.run(
                    ["ffmpeg", "-y", "-ss", "0.5", "-i", tf_path,
                     "-vframes", "1", "-q:v", "3", str(thumb_path)],
                    capture_output=True, timeout=30, check=True,
                )
                return f"/static/uploads/maps/{thumb_name}"
            finally:
                try:
                    _os.unlink(tf_path)
                except Exception:
                    pass
        except Exception:
            return None
    return None


@router.post("/campaign/{campaign_id}/settings/characters")
def settings_create_character(
    campaign_id: int,
    name: str = Form(...),
    owner_user_id: Optional[int] = Form(None),
    db: Session = Depends(get_db),
    user: User = Depends(require_user),
):
    campaign = db.query(Campaign).filter(Campaign.id == campaign_id).first()
    if not campaign or not _user_is_gm(user, campaign, db):
        raise HTTPException(403, "GM only")
    sys = get_system(campaign.game_system)
    char = Character(
        campaign_id=campaign_id,
        name=name.strip()[:120] or "New character",
        template=sys.sheet_template,
        sheet=get_template(sys.sheet_template),
        owner_user_id=owner_user_id or None,
    )
    db.add(char)
    db.commit()
    return RedirectResponse(f"/campaign/{campaign_id}/settings#characters", status_code=303)


